Object.assign(window.__TXT,{"5000": "脉数多遗，脊酸腰坠，此督任失固，非通不能入脉，非涩无以填精，色苍形瘦，不宜温补。", "5001": "脉数小，不饥，痰多，阴虚伏热。", "5002": "阴液枯槁，阳气独升，心热惊惕，倏热汗泄，议用复脉汤，甘以缓热，充养五液。", "5003": "脉大不敛，神迷呓语，阴阳不相交合，为欲脱之象。救阴无速功，急宜镇固阴阳，冀其苏息。", "5004": "男子脉大为劳。暑月阳不伏藏，初夏阳升血溢，皆内损少固。填精固气，是为药饵，静摄绝欲，经年可复。", "5005": "右痪，舌喑，足痱，头岑，面戴阳，呵欠，微呃，诊脉小濡而缓，此肾纳失司，肝风震突。但病起耳后暴肿，必兼温热客气。清上轻扬，肿势颇减，七日以来，当阴阳经气一小周天，不必以时邪引病为惑。昔河间《宣明方论》中谓：舌强难言，其咎在乎舌下。筋脉不主流动，以肾脉萦及舌本耳。其主地黄饮子，取意浊药清投，机关渐灵，并无碍乎上气痰热，仿此为法。", "5006": "脉象左部稍振，水亏木中风动，左牙痛，盖风从内旋，乃阳之化风，只以春深地气上升之候，多升少降，无非下元不司收纳，虚证何疑？况因目恙，频用韭子烟熏，查本草药性，辛辣升腾助阳，孙真人于遗浊用之，藉其升阳以涵阴，更无漏泄耳。今痱中八日，声音渐振者，乃精气略有宁静，里窍略有灵机，是顺境也。乃不明此理，仍用辛以泄气，加人参亦是清散上焦之药，以肝肾脏虚，在于至阴，若再投辛以伤其阴，必致虚症蜂起焉。望其向安，倘必以上有火热，古称实火宜清，虚火宜补，温养柔和，与温热刚燥迥异，幸勿疑讶。", "5007": "张石顽治春榜赵明远，平时六脉微弱，己酉九月，患类中风，经岁不痊。邀石顽诊之，其左手三部弦大而坚，知为肾脏阴伤，壮火食气之候，且人迎斜内向寸，又为三阳经满溢，入阳维之脉，是不能无颠仆不仁之虞。右手三部浮缓，而气口以上微滑，乃痰沫壅塞于膈之象。以清阳之位，而为痰气占据，未免侵渍心主，是以神识不清，语言错误也。或者以其神识不清，语言错误，口角常有微涎，目睛恒不易转，以为邪滞经络，而用祛风导痰之药，殊不知此本肾气不能上通于心，心脏虚热生风之症，良非燥药所宜，或者以其小便清利倍常，以为肾虚，而用八味壮水之剂，殊不知此症虽虚，而虚阳伏于肝脏，所以阳事易举，饮食易饥，又非益火销阴药所宜。或者以其向患休息久痢，大便后常有淡红渍沫，而用补中益气，殊不知脾气陷于下焦者可用升举之法，此阴血久利之余疾，有何清气在下可升发乎？若用升柴，升动肝肾虚阳，鼓激膈上痰饮，能保其不为喘胀逆满之患乎？是升举药，不宜轻服也。今举河间地黄饮子助其肾，通其心，一举而两得之，但不能薄滋味，远房室，则药虽应病，终无益于治疗也。惟智者善为调摄为第一义。", "5008": "脉左大右濡，肝风震动，阳明脉空，舌强肢软。是属中络，议用缓肝熄风。", "5009": "头痛累月，阳脉大，阴脉涩，此阴衰于下，阳亢于上，盛下虚之候也。阳气居上，体本虚也，而浊气干之则实。阴气居下，体本实也，而气反上逆则虚。头为清阳之位，而受浊阴之邪，阴阳混乱，天地否塞，而成病矣。法用六味地黄汤，加青铅五钱。", "5010": "头痛经年不愈，早则人事明了，自午至亥，神气昏愦不宁，风火之剂，杂治无功，两脉俱沉且滑，此太阴阳明痰厥头痛也。当用礞石滚痰丸，间服导痰汤，以荡涤其痰。次以六君子汤，少加秦艽、全蝎，调理而安。", "5011": "周身掣痛，头不可转，手不能握，足不能运，两脉浮虚。浮虽风象，而内虚者，脉亦浮而无力。以脉参症，当是劳倦伤中，阳明不治之候。阳明者，五脏六腑之海，主束筋骨，而利机关。阳明不治，则气血不荣，十二经络无所禀受，而不用矣。卫中空虚，营行不利，相搏而痛，有由然也。法当大补阳明气血，不与风寒湿所致成痹者同治。", "5012": "患风三月，周身流走作肿，手不能握，足不能履，诊其脉，浮大而数，发热口干。此阴虚生内热，热胜则风生，况风性善行，火热得之，愈增其势，伤于筋脉，则纵缓不收，逆于肉理，则攻肿为楚也。", "5013": "左脉如刃，右脉缓涩。盖阴亏本质，暑热为虐，水谷气蒸，湿流肢末，遂成挛痹。已经泄泻食减，阳明脉中气衰极矣，缓治可以冀功。", "5014": "湿痹，络脉不通，用渗湿苦温药小效，但汗出形寒，泄泻食减，阳气大衰，可知难以湿甚生热例治。通阳宣行，以冀脉络流通。", "5015": "高年液涸风动，酒湿气蒸，足趾曾经腐疡，经年来或麻痹，或牵制，不能转侧，已成筋骨之痿，兼之火升眩晕，头面清窍常似不爽，大便艰涩，四五日始一更衣。阳气不能潜伏，阴液日就枯槁。老来痿躄，原无复元之法，诊得脉数动疾，温燥之补，无益反害，仿丹溪虎潜之制，稍为加减，冀得津液少存，亦安闲永年之算，非攻病也。", "5016": "长夏湿痹，经脉流行气钝，兼以下元脉络已虚，痿弱不能步趋，脊膂常似酸楚，大便或结或溏，都属肝肾、奇经为病。盖必佐宣通脉络为正治法，倘徒呆补，夏季后必滋湿扰，须为预理。", "5017": "俞天音脉左大，舌干白苔，肿痛流走四肢，此行痹。喘急不食二十日外矣。", "5018": "脉微而涩，微为阳气虚，涩为阴血伤。去冬已下肢独冷，步趋无力，高年内乏藏纳之司，入夏身动加喘，肉腠麻痹若虫行。此真阳失蛰，胃阳失护，生生意少，岂攻病药石所宜？喻嘉言先生所谓大封大固，莫令真阳泄尽而暴脱，皆为此也，录严氏《三因方》。", "5019": "俞文调先生《灵枢》云：神伤思虑则内脱，意伤忧愁则肢废，皆痿症也。脉形大虚无力，常饵补阳，而今操持萦思，犹未能免，病必迁延。", "5020": "四十二岁，右脉涩，左脉微，饮食不能健运，嗳呕，间或溏泄，此中宫阳气欲寂，当用辛温以补之。", "5021": "左脉弦大空虚，右脉虚软涩滞，能食不能运，便溏跗肿，此系积劳伤阳。壮岁经年不复，当作虚症，宜补脾肾治。", "5022": "十九岁，翻胃三月，粒米不存，左脉大空虚，右脉细小虚涩，纳食少停，即涌出口，面白神瘁，大便燥结。此阴血枯槁，阳气郁结，已成膈症。勉拟补中纳下法。", "5023": "发热痰喘，胸满身痛，左边睪丸不时逆上，痛不可忍。肝脉弦急，肺脉独大。此肺肝受邪之故也。肝为木脏，其化风，其生火，风火合邪，旺于本位，则为热为痛。乘于肺金，则为痰为喘。法宜滋达肺金，兼疏肝木。", "5024": "阴茎作痛，痛甚而愦。诊两脉，浮虚而涩，浮为气虚，涩乃精伤。阴阳两虚，得之忧思劳郁，而伤中也。经云：阳明为气血之海，主润宗筋。又阳气者，精则养神，柔则养筋，今多悒郁，则气必伤。又任劳倦，则血必耗。气血两伤，宗筋失润，故令作痛。治以当归补血汤，加人参、甘草、秦艽、桂心、红花，继用归脾汤调理。", "5025": "患溺血症，已三月矣。前用升补法不应，右脉虚涩无神，左关独弦，茎中作痛，下多血块，形色憔悴，又多嗳气。据脉论症，乃肝脾积热也。肝热则阴火不宁，而阴血自动，以血为肝脏所藏，而三焦之火，又寄养于肝也，故溺血茎中作痛。脾热则湿气内壅，而生气不伸，以脾为湿土之化，而三焦之气又运行于脾也，故时时嗳气，形色憔悴。法当益肝之阴，则火自平，利脾之湿，则气自和。", "5026": "下血不已，汗出躁烦，心悸恍惚，头不安枕，转侧不能。两脉虚涩，虚为气虚，涩为阴伤。人身阳根于阴，阴附于阳，两相维系者也。今阴血暴亡，虚阳无偶，势必外越矣。虚阳外越，而阴愈无主，其能内固乎？阴阳相离，气血两亏，法宜兼补。然血有形，难以骤致，气无形，可以急固。固其气，则气自充。气充则不必治血，而血自守矣。先用归脾汤，继以大造丸。", "5027": "寒热如疟，便血不已，左胁有块，攻逆不已而作痛。脉弦数兼涩，弦则为风，数则为热，涩则气结。此肝脾之气，悒郁不宣，胸中阳和，抑而成火，故神明不精。肝之应为风，肝气动则风从之，故表见寒热也。人身左半，肝肾主之。肝风自逆，故左胁攻楚有块也。肝为藏血之地，肝伤则血不守。且以风淫热胜，益为亡血之由也。", "5028": "面目悉黄，微见黑滞，烦渴腹满，左脉弦数，右脉空大，此内伤发黄，为厥阴肝木，太阴脾土，二脏交伤之候也。夫肝为风脏，其性喜伸而恶屈，郁则木不得伸而屈矣。郁极则其气盛，而风乃发，风发必挟其势以贼脾。脾为湿土之司，土受克，而气不行，则湿胜矣。风性虽善行，遇湿以留之，反壅滞经络而不解，由是湿停热瘀，而烦渴有加，其发黄也必矣。虽曰风湿所致，实由木亢而不宁，土困而不舒，非外来风湿之比，况黑色见于面，则知并伤其肾，以脾病不行胃中谷气，入肾反将脾中浊气下流，故于黄中见黑滞耳，即其腹满，亦是中气不行，虚热内壅，非结热，当下之比，若误下之，则脏气空虚，风从内生矣。若误汗之，则阳气外解，湿愈不能行矣。为商治法，平肝之亢，扶土之虚，兼解郁热，以清气道，除湿蒸而和中气。", "5029": "产后下损，八脉交虚，形寒内热，骨痛耳鸣，血液日耗，生气不充，冬季不得复元，春深发泄司令，延为劳瘵矣。", "5030": "产后阴伤，寒热疟，几两月病发，白带淋漓，八脉空隙，大著腹有动瘕，下元虚惫已极，议固下真通脉方。", "5031": "产后十二日，诊脉数疾，上涌下垂，此血去阴伤，孤阳上冒，内风燔燎，肝魂不宁。面赤头痛，昼轻夜重，阴弱阳亢，上实下虚。若不按法施治，必增瘛痉厥逆。议咸润益下和阳方。", "5032": "产后脉虚，舌白，背寒凛，身痛，干咳，不饥，是血气两损，不肯复元，有蓐劳之虑。急当培养足三阴脏，莫以肺经咳嗽治，再伐胃气，用贞元饮方。", "5033": "方此血痹之症，产蓐百脉皆动，春寒凛冽，客气乘隙袭入经络，始而热胜，继则寒多。邪渐陷于阴络，致夜分偏剧汗多，神昏谵语，由邪逼神明，岂是小病？正如仲景劫汗亡阳、惊谵同例。议救逆汤减芍药方治。", "5034": "产后络脉伤，腹痛频发，嗔怒，食物不宜则甚。当调和脉络，庶不延成痼疾，宜葱白丸。", "5035": "脉右涩左微，色悴不华，食减不能健运，嗳呕溏泄，此中宫阳气欲寂。法宜辛温通补，失治酿成中满难调。", "5036": "脉沉右小，左虚大，脐上有动气，䐜胀不嗜食，艰于大便。此中气大虚，肝气内变，忌用攻伐消导，宜泄肝和胃。", "5037": "脉沉属水，初因食物之滞，继为下夺太速，脾阳顿伤，气窒湿聚，为肿胀矣。", "5038": "脉左大坚弦，肝风震动，脾胃络脉不和，不知饥，不安寐，口流涎，右肢肿。当兼理中焦之络，议用茯苓饮法。", "5039": "汪介臣鼻冷涕泪，腹胀仍空，形色衰夺，脉微而涩。阳气已惫，浊阴日聚，为胀满不食，危期至速，勉议通阳方法。", "5040": "脉沉迟，肿胀腹满，茎缩溺不利，起于上年冬底，痰饮咳嗽，气逆不得卧，误认肾虚水泛之恙疗治，遂致增剧难调，勉拟进浚川丸以通水道，得小便频利，冀其势缓。久泻伤肾，下午黄昏为甚，非通套药所宜，拟温肾法。", "5041": "朱客肋稍隐隐痛，卧起咳甚，冷汗，背有微寒，两足带冷，身体仰卧稍安。左右不堪转侧，此皆脉络中病。良由客寒闭其流行，两脉逆乱，上犯过也。治在血分，通络补虚。", "5042": "脉数重按无力，左腰胁痛不能转侧，舌苔白，边红，心中热闷，不欲饮，是湿邪滞著，经络阻痹，宜进气分轻清之药，庶几不伤正气。", "5043": "又脉数，左腰胁疼未止，舌苔黄，昨进芳香轻剂略安，仍不宜重药。", "5044": "又脉数无力，左腰胁疼未止，舌色转红，是病邪虽稍缓，却阴气已经不振，进清余热略兼养阴方。", "5045": "又案：脉数无力，左腰胁疼未止，舌苔已退。虽病邪稍缓，但阴气仍然不振，议用清余热略兼养阴方。", "5046": "老人久嗽，古人但以温养脾肾，未必以肺药，见病治病贻害。但身小质薄，络脉单弱，桂附雄猛，液枯必犯肺疡。此温剂通纳为无弊耳。", "5047": "脉细有遗症，是阴虚不主收纳。因冲气上激为咳嗽，肺药无益。今胃纳颇好，急宜填下绝欲，安养尚可图愈。", "5048": "此痿症也！因肝肾两虚，阳明脉络失用，筋缩牵强，足痛不堪动作，当温散下焦，莫进疏解。", "5049": "痛胀甚于暮夜，病根已在阴经。从前温补相安，今则服之不应。因以寒凝痰滞为患，进神保丸即上吐下泻。此非有形之滞矣！斯脏液日耗为虚，腑经阳气窒塞为实。行痹日久，时愈时发，脉来六至，湿热居多。今关节肿痛，游走不定，是湿热中又夹风火矣！总宜养血清热，兼用风剂，庶几有中病情耳。方失", "5050": "久嗽失音，脉小，痰冷，冲气，入暮为重。此肺虚气馁，不易骤愈，酒家有饮邪。", "5051": "枫桥汪（四十）胁膈左右，懊𢙐不舒，呕逆带血。凡人脏腑之外，必有脉络拘拌，络中乃聚血之地。中年操持，皆令耗血，血不和气，气攻入络，病状难以自明。宣通血分以和络，俾不致瘀著，可免噎膈反胃。", "5052": "绍兴眷，（三十一）少腹痛坚，攻及当脐。每午后必气胀滞痛，贯串腰尻，环跳肉腠之间，肌肤亦渐浮肿。再问经事愆期，仅得些微黄水，是阴寒已入血络。病盖起于产蓐，累及奇经八脉，身伛不直，俯不能仰，此肝肾入奇经之见症。", "5053": "枫桥（四十三）此肝病也。肝属木主筋，木脏内寄风火。情志不适，热自内起，烁筋袭脉，肢体为之牵强不舒。惟怡悦静养，可希渐愈，药无除根之理。", "5054": "泰兴（二十八）色脉是阴虚，其喉妨食纳，乃阴乏上承，热气从左上升，内应肝肾阴火。前议复脉法，大便滑泄，知胃气久为药伤，不受滋阴，必当安闲静室以调之，岂偏寒偏热药能愈？", "5055": "海宁（廿六）劳怯是肾精内损，真阴枯槁，龙雷之火，闪烁无制。肾脉循喉，屡受阴火燔灼，必糜腐而痛。冬无藏精，春生亦无生发，胃气已索，草木何能挽回？", "5056": "葑门（三十九）过劳熬夜，阳升痰血。在土旺之令中，夜热非外感。脉尺中动，左数。肝肾内虚，失收肃之令。", "5057": "木渎（三十二眷）经水不来是络脉无血。古云：气旺血自生，大忌通经。", "5058": "黎里（四十四）形色脉象，确是阳虚。酒食聚湿，湿注入肠，肠痔下血。湿为阴浊，先伤脾阳，阳微气衰，麻木起于夜半气血交代之时，中年痱中，大有可虞。", "5059": "山西（三十九）夏季吐血，秋深入冬频发。诊脉右弦空左濡，是形神两伤，络血不得宁静，气血因经营而耗，不比方壮矣。", "5060": "黄家巷（廿七）色夺脉促，寒露霜降嗽甚，风冷形肌凛凛，卫阳疏，气易泄也。", "5061": "兴化（廿四）肛疡成漏年余，真阴五液皆伤，纳食在胃，传入小肠而始变化。因咳痰不出，必呕尽所食乃已。喉痛失音，涎沫吐出，喉中仍似存留。明明少阴脉中阴火内烁，上燔阴液，蒸变涎沫，内损精血，医见咳嗽音低，咸进清金润肺，不明此咳呛之原，是速其笃已。", "5062": "齐门外（三十眷）上年产蓐无乳，已见血虚之象。延半年后经水不来，少腹瘕气有形。病人自述背脊常冷，心腹中热。视面黄色夺，问食少不美。夫督脉为阳脉之海，由腰而起，剂颈而还。下元无力，阳虚背寒。任脉为阴海之冲，虚攻入络为瘕。考《内经图翼》，病机宛然在目。此产损蓐劳，非是小恙。无如医不读书，见寒热经闭而妄治，淹缠日久，速其笃已。", "5063": "南京（廿八）环跳筋骨酸痛，少年精伤，阳维脉少护卫。", "5064": "流贞巷（四十九）漏经继下如卵，形已见，血损气结。按：任脉为病，女子带下瘕聚，少腹形象是也。血伤忌投气燥温热，但血药不取沉滞，血中宣气为是。", "5065": "泰兴（三十七）精未生成，强泄最难充旺，至今未有生育。视形瘦，问食少，精薄易泄。形脉不受刚猛阳药，议藉血肉有情温养气血。", "5066": "太仓（十八眷）每交夏五六月，喉间宿病俄发。既愈后仍然鼻塞火升，上热下冷。经水或前或后，形瘦脉小数，是阴弱不旺，肝阳左升太速，右降不及。夏令阴伏于里，阳泄上浮，乃发病根由。", "5067": "十四岁室女，无温热药之例，视色夺脉弱，下焦未寒先冷，经事淋漓，是冲任虚冷，二气不交，冬宜藏阳，用温摄升阳。", "5068": "山塘（七十五）立冬未冷，温热之气外入，引动宿饮。始而状如伤风，稀痰数日，继则痰浓咽干，是少阴脉中乏津上承，五液尽化痰涎。皆因下虚易受冷热，是以饮邪上泛。老年咳嗽，大要宜调脾肾，最忌发散泄肺理嗽，暂用越婢法。", "5069": "常熟（三十二眷）寡居无欢悦之念，肝胆中气火郁勃，直上直下，莫能制伏，失其疏泄之用，小溲成淋。谓肝脉环绕阴窍，用龙胆泻肝法。", "5070": "常熟（廿七眷）疟母瘕聚有形，治有宣通气血。第所述病状，已是产虚。八脉交损，不敢攻瘕。", "5071": "（四十九）积劳伤阳，腹膨仍软，脉弦无胃气，形肉衰削，理中宫阳气之转旋，望其进食，无能却病矣。", "5072": "复脉法去麻仁。", "5073": "无锡（三十九）任脉为病，男子内结七疝，女子带下瘕聚。问经水仍至，知是气攻入络，渐次有形，况产后又十六年不育，冲任之病显然。", "5074": "南京（三十五）频年发失血症，嗽甚痰出，继以呕嗳，日晡寒热，夜深汗泄。据述医见血，投以郁金、姜黄、韭汁、制大黄，逐瘀下走，希图血止，此是有余治法。夫人禀阴阳，偏则致病。自内损伤，即是不足。脉左动数，尺不附骨，明明肾精肝血内夺，弱阴无能交恋其阳，冲阳上逆，吸气不入，是以咳嗽气并，旋必呕嗳浊涎黏沫。《内经》谓：五脏六腑皆令人咳。奈何今人以咳治肺，见痰降浊清热，损者更损，殆不复脏阴腑阳消长之机，杂药徒伐胃气。经年累月，已非暴病，填实下隙，须藉有情之属。", "5075": "杭州（廿一）据述遗精频致哮喘，病发必甚。此肾虚失纳，真气散越之疾，少年形瘦，难用温药，治当导入任脉阴海以固之。", "5076": "无锡（三十九眷）秋七月经停几两月，继下血块，疑是小产，遂经漏不止。入冬血净，加五心脊椎骨热，天明微汗热缓。凡经漏胎走，下元真阴先损，任脉阴海少液，督脉阳海气升，所谓阴虚生热矣。以肝肾脏阴，精血损伤，医投耆术呆守中上，是不究阴阳气血，不亦左乎。", "5077": "常山（四十三）食入脘闷，嗳气呕吐觉爽，少焉仍然痞闷。视形躯充伟，按脉形小濡。中年阳微不运，即为不足，泄降气分，攻痰是为有余治法，非脉症所宜。", "5078": "医案之作，昉于明人。《四库全书》医家类著录薛己、陈桷两家医案，世鲜传本。惟明·江瓘《名医类案》、国朝魏之琇《续名医类案》，乾隆间长塘鲍氏刊行之，同治间有重刻本。江氏征引古今方论，附以评语，颇多辨证；魏氏采摭尤繁富，而不能免芜杂之累。若喻嘉言《寓意草》，自述其所治验，而不以医案名；叶天士《临证指南》，盛行吴越间，市医浅学，奉若科律，然中多门弟子伪托，不皆出于天士。故纯驳互见，胶柱鼓瑟，贻误后来，识者病焉。淮阴吴鞠通氏，以医名大江南北，所著《温病条辨》，上为吴又可之诤臣，下导王孟英之先路，亦既家有其书矣。金君月笙覃精灵兰之秘，博观医家书，得鞠通氏医案手稿，分类编次，厘为五卷。金君谨斋为排印行之，而督余序其端。余于医学无所得，顾少而善病，颇事涉猎，因受而卒业为。窃叹是书也，可以为医门之阶梯矣。其辨微也，分肌擘理，若屠牛坦，一朝解十二牛而芒刃不顿；其纠缪也，若老吏谳狱，虽情伪万变，执吾法以绳之，而无所于挠。至若疗章氏颠狂之疾，而先激其羞恶之良心，几几于穷理尽性之学。治陈某肿胀之疾，与陈颂帚论药，齐轻重以决其效不效，折座客之气，而卒以服颂帚之心。於戏，可不谓神矣乎。昔杭先生大宗序《名医类案》，括以三言：曰审脉，曰辨药，曰慎思，其论绝伟。余于是书，则但取鞠通氏之自道，曰「认证无差」一言尽之矣。认证无差，非多读古书，善察时变者不能。今世言医者十九下工耳。不读古书，不察时变，苟焉以医为市，其戕贼于芒昧中者，不知其凡几矣。夫守一家之言，讵遂足为高手医。然得是书而深究其处方用意之所在，触类以充其识，隅反以神其悟，由是上通五运六气、三部九候之旨，不愆于汤齐先后缓急之序，毋以学医人费蒙世询病，驯至于祲诊潜消，民无夭札，则金君传布是书之举，不诚为仁人之用心矣乎！", "5079": "初六日风温，脉浮数，邪在上焦。胸痞微痛，秽浊上干清阳。医者误认为痰饮阴邪之干清阳，而用薤白汤。又有误认伤寒少阳经之胁痛，而以小柴胡治之者。逆理已甚，无怪乎谵语烦躁，而胸痞仍不解也。议辛凉治温以退热，芳香逐秽独以止痛。", "5080": "初七日风温误汗，昨用芳香逐秽，虽见小效，究未能解。今日脉沉数，乃上行极而下也，渴甚。议气血两燔之玉女煎法，合银翘散加黄连。夜间如有谵语，仍服牛黄丸。", "5081": "初八日大势已解，余焰尚存，今日脉浮，邪气还表。", "5082": "初九日脉沉数有力，邪气入里，舌老黄微黑，可下之。然非正阳明实证大满、大痞可比，用增液足矣。", "5083": "初十日昨服增液，黑粪已下。舌中黑边黄，口渴，面赤，脉浮，下行极而上也。自觉饥甚，阳明热也。仍用玉女煎加知母，善攻病者，随其所在而逐之。", "5084": "十一日邪少虚多，用复脉法，二甲复脉汤。", "5085": "姚三十二岁三月初二日风温误认伤寒发表，致令神呆谵语，阳有汗，阴无汗，大便稀水不爽，现在脉浮，下行极而上也。先渴今不渴者，邪归血分也。", "5086": "初三日昨用清膻中法，今日神识稍清，但小便短，脉无阴，大便稀水。议甘苦合化阴气法，其牛黄丸仍服。", "5087": "初七日温病已解，邪少虚多，用复脉法。", "5088": "王十岁风温发疹，初起肢厥，脉不甚数，势非浅鲜。", "5089": "陈氏七十岁风温，咳嗽黏痰，脉弦数，曾吐血丝、血沫，此风温而误以治风寒之辛温法治之也。当用辛凉甘润。", "5090": "以上三人，温病日久不解，六脉全无，目闭不言，四肢不动，宛如死去。有一日一夜者，有二日者，有三日者，有手足不温，亦不甚凉者，有凉如冰者，有微温者，诚如吴又可所云体厥脉厥之证。佥用紫雪丹续续灌醒，继以复脉汤收功。", "5091": "赵二十六岁乙酉年四月初四日六脉浮弦而数，弦则为风，浮为在表，数则为热，证现喉痛。卯酉终气，本有温病之明文。虽头痛身痛恶寒甚，不得误用辛温，宜辛凉芳香清上。盖上焦主表，表即上焦也。", "5092": "赵四十二岁丙戌年正月初九日脉浮，风温，咽痛，项强，颈微肿，舌伸不长，宜开提肺气为主。", "5093": "张六十七岁甲申年正月十六日本有肝郁，又受不正之时令浊气，故舌黑苔，口苦，胸痛，头痛，脉不甚数，不渴者年老体虚，不能及时传化邪气也。法宜辛凉芳香。", "5094": "十七日老年肝郁挟温，昨用辛凉芳香，今日舌苔少化，身有微汗，右脉始大，邪气甫出，但六脉沉取极弱，下虚阴不足也，议辛凉药中加护阴法。", "5095": "十八日老年阴亏，邪退十分之七，即与填阴，耳聋脉芤，可知其阴之所存无几，与复脉法。", "5096": "十九日较昨日热退大半，但脉仍大，即于前方内加鳖甲六钱，以搜余邪。", "5097": "二十日脉静便溏，再于前方内加牡蛎八钱收阴，甘草三钱守中。", "5098": "温斑三日，犹然骨痛，胸痛，咽痛，肢厥，未张之秽热尚多，清窍皆见火疮，目不欲开，脉弦数而不洪，口干燥而不渴。邪毒深居血分，虽有药可治，恐高年有限之阴精，不足当此燎原之势，又恐不能担延十数日之久，刻下趁其尚在上焦，频频进药，速速清阳。再以芳香透络逐秽，俾邪不入中下焦，可以望愈。", "5099": "十二日《灵枢》温热论曰：狂言失志者死。况加以肢厥，冷过肘膝，脉厥六部全无，皆大用表药，误伤心阳，致厥阴包络受伤之深如是。现在危急之秋，只有香开内窍，使锢蔽之邪，一齐涌出方妙。且喜舌苔之板者已化，微有渴意，若得大渴，邪气还表，脉出身热，方是转机。即于前方内加犀角三钱，如谵语甚，约二时辰，再服紫雪丹一钱。", "5100": "十三日肢厥脉厥俱有渐回之象，仍服前方二帖。晚间再服紫雪丹一钱，牛黄丸一粒。明早有谵语，仍服紫雪丹一钱，不然不必服。", "5101": "谢五月初三日酒客脉象模糊，苔如积粉，胸中郁闷，病势十分深重，再舌苔刮白，大便昼夜十数下，不惟温热，且兼浊湿，岂伤寒六经药可治。", "5102": "初五日旧苔已退，新苔又出，邪之所藏者尚多。脉象之模糊者，较前稍觉光明。", "5103": "初六日脉洪，舌滑而中心灰黑，余皆刮白，湿中秽浊，须重用芳香。", "5104": "初七日温病已有凉汗，但脉尚数而协热下利不止。议白头翁汤法。", "5105": "初八日热邪虽退，而脉仍未静，尚有余热未清。大泄十余日，大汗一昼夜，津液丧亡已多，不可强责小便。再胃之上脘痛，有责之阳衰者，有责之痰饮者，有责之液伤者。兹当热邪大伤津液之后，脉尚未静，犹然自觉痰黏，断不得作阳衰论。且阳衰胸痹之痛，不必咽津而后痛也。与甘苦合化阴气法，既可以保胃汁，又可以蓄水之上源，得天水循环，水天一气，自然畅流。", "5106": "初十日肺脉独大，仍渴思凉。", "5107": "初五日温毒脉象模糊，舌黄喉痹，胸闷渴甚。议时时轻扬，勿令邪聚方妙。", "5108": "初六日舌苔老黄，舌肉甚绛，脉沉壮热，夜间谵语，烦躁面赤，口干唇燥，喜凉饮。议急下以存津液法，用大承气减枳朴辛药，加增液润法。", "5109": "初八日脉浮邪气还表，下行极而上也。即于前方内加：", "5110": "初九日脉仍数，余焰未息，口仍微渴，少用玉女煎法，两解气血伏热。", "5111": "初十日脉沉微数，自觉心中躁，腹中不爽，舌上老黄苔，二日不大便，议小承气汤微和之。", "5112": "十四日六脉沉数而实，四日不大便，汗不得除，舌苔微黄，老年下虚，不可轻下。然热病之热退，每在里气既通以后。议增液汤，作增水行舟之计。", "5113": "十六日脉已滑，渴稍加，汗甚多，邪有欲出之势，但仍未大便，犹不能外增液法，少入玉女煎可也。既可润肠，又可保护老年有限津液，不比壮年可放心攻劫也。", "5114": "十八日大便已见，舌苔未净，脉尚带数，不甚渴，仍清血分为主，复领邪法。", "5115": "再按：痉厥神昏，故以清宫为主。血分太热脉极数，故以地黄汤犀角为佐。邪气在血分虽多，尚能渴思凉饮，故加石膏合冬地为玉女煎法，以清气血两燔之伏热。大抵治逆之症，不能一辙，其势不得不用复方也，煮成三碗，分三次服。明日渣再煮半碗服。", "5116": "初二日诸证俱减而未尽除，脉之至数亦减。但老年下虚，咳声不满喉咙，可畏之至。议搜邪之中，寓补阴和阳之用。", "5117": "初三日脉证虽减，犹在险途。", "5118": "初四日神识略清，脉洪数有力，周身尽赤若斑，大便大频，用玉女煎加苦以坚阴。今晚明早，如神识不甚清爽，再服紫雪丹三五钱。", "5119": "此证服紫雪丹共一两八钱，牛黄丸五粒。神识清，大便通，舌苔退，脉静身凉，后二甲复脉汤十八帖。", "5120": "普四十四岁五月二十九日温热月余不解，初用横补中焦，致邪无出路。继用暑湿门中刚燥，致津液大亏，湿热之邪，仍未能化。现在干呕脉数，大小便闭，烦躁不安，热仍未除，证非浅鲜，议甘寒、苦寒合化阴气，令小便自通。若强责小便，不畏泉源告竭乎！", "5121": "三十日昨用玉女煎、银翘散合法，再加苦寒，为甘苦合化阴气，又为苦辛润法。今日已见大效，汗也，便也，表里俱通。但脉仍沉数有力，是仍有宿粪，与久羁之结邪相搏。议增水行舟，复入阴搜邪法。", "5122": "史三十八岁温病汗后，法当脉静身凉。今脉虽为汗衰，究有五至，且不能弱。况对医者说病刺刺不休，岂一二日内欲虚脱者，而能若是乎？此证人佥畏其虚，我独畏其实也。现在大便溏泄频频，势若可畏，然不可与收摄肾胃两关。盖伏邪藏深，为日已久，兹方有出路，而可骤行纳缩乎？但柔滑之品，须暂行停止。议热淫于内，治以甘苦，佐以咸寒法，妙在即寓坚阴收纳于其中。", "5123": "梁六十二岁丙辰年六月二十三日脉数急，身热头痛，思凉饮，暑伤手太阴，切忌误认伤寒而用羌防柴葛。", "5124": "二十五日六脉洪大而数，渴思凉饮，纯阳之症，气血两燔，用玉女煎。", "5125": "梁二十二岁壬申年六月初四日温热自汗，脉浮，舌满白，最忌足三阳表药发汗。用辛凉法。", "5126": "初六日温病脉浮自汗，喘喝，舌苔白厚，思凉饮，用辛凉重剂。", "5127": "大渴思凉饮，大汗如注，脉数急，非辛凉重剂，不足以解之。", "5128": "用辛凉重剂，大热已解，脉小数，以养阴清解余邪立法。", "5129": "甘五岁壬申年六月十八日温热七日不退，渴思凉饮，脉仍洪浮而长，急宜辛凉退热，加入芳香化浊，最忌羌防柴葛发表。腹痛者，秽浊也。勿认作寒，用温药。", "5130": "十九日热稍减，脉势亦减过半，气分尚未解透，血分亦有邪耳！今用玉女煎加芳香法。", "5131": "前方用芳香开膻中，是治邪法。恐老年阴气告竭，自汗而脱，再用复脉法护阴，是固正法。二更后服。", "5132": "初五日脉仍有力，舌黄黑，仍有宿粪未净，再服增液一帖。", "5133": "初六日大便后仍用二甲复脉法，以复其丧失之真阴。", "5134": "十三日今日脉浮，鼻息太粗，粗甚则为喘矣。温病大忌喘促，恐化源绝也。再手指与臂，时时掣动，瘛疭之象也。勉与玉女煎法。", "5135": "十五日脉浮为邪气还表，渴甚加石膏。", "5136": "二十日渴止脉静身凉，用复脉法。", "5137": "杨甲子年四月初四日温病自汗，脉浮芤，神气昏霿，时有谵语，可先服牛黄丸二丸，继以人参白虎汤。", "5138": "初六日大用白虎，脉为敛戢，热未全退，咳而腹痛，议甘苦合化阴气法。", "5139": "初七日今日脉少敛，但手心热甚于手背，温热未净，而津液已亏。用存阴退热法，兼润肺燥。", "5140": "初十日脉复大而芤。", "5141": "十一日脉势火敛，但手心热甚，应治里。议热淫于内，治以甘苦，佐以咸寒。", "5142": "十二日脉复浮大而芤，前方去二甲黄芩，加石膏、洋参。", "5143": "十三日脉少敛，热未净，左脉仍空大，用存阴退热法。", "5144": "十四日邪少虚多，且左大为下焦血分，非右大可比。议复脉法，复胃中之阴，渐有驱邪之势。", "5145": "岳七十八岁二月十八日右脉大于左，滑而且数，舌苔老黄，渴欲凉饮。诊尺篇，所谓尺肤热为温病者是也。法宜辛凉解肌，合芳香化浊。切忌辛温发表，甘热温里。", "5146": "十九日其人素有痰饮，又以客气加临，身热，苔黄，脉数，思凉，为温病。昨用辛凉芳香，今日大便后，病势仍未除。仍须辛凉解散。《金匮》所谓先治新病，旧病当后治也，但当回护痰饮耳！", "5147": "二十日病势虽较前稍减，脉体亦小，黄苔亦彻。但寒从左升，热从入分，寒少热多，颇似温疟。议白虎桂枝法，加青蒿等，使陷下之邪，一齐涌出，庶不致缠绵日久，坐耗真元也。", "5148": "二十二日脉静身凉，舌苔悉退，温热已尽。惟余痰饮胁痛，一以宣通悬饮为法。", "5149": "二十三日今日大便后，面微赤，脉微大，舌微苔，胸中热思凉饮，又有余邪上泛之故。议芳香之中，仍稍加辛凉。", "5150": "二十五日脉静身凉，惟头微热，余邪已去八九，一以宣肺透饮为主。须能入胁者宜之。", "5151": "三月初四日食复，脉弦细而滑，胁痛胀，舌苔重浊，不思食。其人本有痰饮，与两和肝胃法。", "5152": "脉虽安静，苔尚未化，未可恣意饮食。胁下刺痛，开胃兼与和络。", "5153": "章丙寅年二月十一日头痛身热，脉芤数，口渴，自汗，喉痛，舌苔重浊而尖赤甚，温病也。势甚重，法宜辛凉，最忌发汗。", "5154": "十三日大便通，咽痛减，脉渐静，不可躁。", "5155": "十四日脉静，痛止大半，小便未畅，余焰尚存，仍不可食谷。", "5156": "十六日脉静身凉，用一甲复脉汤。", "5157": "赵初六日热病脉七至，烦躁无宁晷，谵语神昏，汗出辄复热，脉不为汗衰。《内经》所谓见三死不见一生，虽愈必死也。余向来见此症，每用一面大剂护阴清热，一面搜逐心包之邪，获效亦不少。但黄帝岐伯所云之死症，谁敢谓必生，勉与玉女煎法。", "5158": "初八日热病瘛疭，痉厥神昏，脉洪大而芤，与育阴潜阳，咸以止厥法。但喉舌之肿，未能一时消尽，可与代赈普济散间服，其紫雪丹仍用。", "5159": "初十日左脉洪而有力，右脉甚软，是温邪日久，陷入下焦血分无疑。古谓三时热病，深入下焦血分者，每借芳香以为搜逐之用。仍用紫雪丹五分一次，约三次，热退神清能言即止。", "5160": "十一日汗已得而脉未静，宿粪已解而肿未消、神未清，其代赈普济散仍服一二次，紫雪丹仍服三五分，其汤药与重收阴气。", "5161": "十二日汗出脉静身凉之后，甫过七八日，忽又身热，脉洪数有力，便涩口渴思凉。乃余邪续出，以当日受邪之时，非一次也，并非食后劳复之比。但久病不宜反复，恐气血不支也，与玉女煎法。紫雪丹（三分）一次，身热神昏瘛疭则服，否则止。", "5162": "十四日今日脉浮大，下行极而上也。", "5163": "十五日今日右脉已小，左脉仍壮，邪气又归下焦血分。先用紫雪丹以搜之，继之培阴清热。热淫于内，治以咸寒，佐以苦甘法。", "5164": "十六日今日右脉复浮而大，犹思凉饮，暂与玉女煎法。其芳香搜逐邪浊之法，仍不能止。", "5165": "十七日今日右脉稍沉而小，左脉仍洪大而浮。余邪续出，神识反昏，微瘛疭，肢微厥，非吉兆也。舌上津液已回，大便甚通。自始至终，总无下法，只有护阴，一面搜逐深入之伏邪。", "5166": "十九日温毒日久，诸症渐减，惟脉未静，应照邪少虚多例，其不尽之邪，付之紫雪可也。", "5167": "复脉汤去参桂姜枣，二帖。", "5168": "史氏二十七岁癸丑年七月初一日温热误汗于前，又误用龙胆芦荟等极苦化燥于后，致七月胎动不安，舌苔正黄，烂去半边，目睛突出眼眶之外，如蚕豆大，与玉女煎加犀角。以气血两燔，脉浮洪数极故也。", "5169": "初六日下后脉静身凉，目睛渐收，与甘寒柔润。", "5170": "初十日复脉汤去刚药。", "5171": "十四日复脉加三甲。", "5172": "赵五十五岁癸丑年六月二十六日体瘦无子，过服桂、附，津液枯燥。于二十二日得温热，自服补中益气汤三帖，致邪无出路，服辛凉轻剂二帖，竹叶石膏汤三帖，至七月初二日，烦躁不寐，并不卧床，赤身满地混抓，谵语干热，无汗舌黄，与调胃承气汤，加元参一小剂，得大便少许，随出赤红疹数十枚，少安半日，其症如前，与沃阴之甘凉法。二三日大躁大狂，又与调胃承气汤一小帖。又出疹数十枚，又少安，热总不退，脉总不静。如是者前后共下十三次，出疹十三次。而后脉静身凉，服复脉汤七帖后作专翕大生膏半料，计十二斤，半年后始复原。此证原案已失，举其大略，以备一格。", "5173": "王三十八岁温病狂热，大渴引饮，周十二时，饮凉水担余，癫狂谵语，大汗不止。每日用白虎汤合犀角地黄汤，石膏用半斤，日服二帖。外用紫雪一两有余，间服牛黄清心丸五六丸。如是者七八日，热始渐退，药渐减，后以复脉汤收功。", "5174": "甘二十四岁壬戌六月二十九日暑温邪传心包，谵语神昏，右脉洪大数实而模糊，势甚危险。", "5175": "十五日厥与热似乎稍缓，据云夜间烦躁亦减，是其佳处；但脉沉弦细数，非痉厥所宜，急宜育阴而恋阳，复咸以止厥法。", "5176": "十六日脉之弦刚者，大觉和缓，沉者已起，是为起色；但热病本属伤阴，况医者误以伤寒温燥药五六帖之多，无怪乎舌燥如草也。议启肾液法。", "5177": "十八日厥已回，面赤，舌干黑苔，脉洪数有力，十余日不大便，皆下证也。人虽虚，然亦可以调胃承气小和之。", "5178": "十九日大下宿粪如许，舌苔化而干未滋润，脉仍洪数，微有潮热，除存阴无二法。", "5179": "二十一日小便短而赤甚，微咳，面微赤，尺脉仍见数洪象，议甘润益下，以治虚热，少复苦味，以治不尽之实邪。且甘苦合化阴气而利小便也。按：甘苦合化降气利小便法，举世不知，在温热门中诚为利小便之上等法。盖热伤阴液，小便无由而生，故以甘润益水之源；小肠火腑，非苦不通，为邪热所助，故以苦药泻小肠而退邪热。甘得苦则不呆腻，苦得甘则不刚燥，合而成功也。", "5180": "二十三日复脉复苦法，清下焦血分之阴热。", "5181": "王三十八岁癸亥六月初三日暑温舌苔满布，色微黄，脉洪弦而刚甚，左反大于右，不渴，初起即现此等脉症，恐下焦精血之热，远甚于上焦气分之热也。且旧有血溢，故手心之热又甚于手背。究竟初起，且清上焦，然不可不免知其所以然。", "5182": "初八日向有失血，又届暑病之后，五心发热，法当补阴以配阳；但脉双弦而细，不惟阴不充足，即真阳亦未见其旺也。议二甲复脉汤，仍用旧有之桂、参、姜、枣。", "5183": "十二日外邪虽退，无奈平素劳伤太过，虚不肯复，六脉无神，非参不可。", "5184": "七月初六日病后饮食不调，又兼暑湿著里，腹中绞痛，痛极便溏，脉微数，欲作滞下，议芩芍法，夺其滞下之源。", "5185": "一二帖后腹痛除，仍服复脉汤服十余帖。", "5186": "荣十五岁乙丑六月十一日暑温挟痰饮怒郁，故脉芤身热而胁痛，误用足六经表药，烦躁不宁，六日不解，至危之证。", "5187": "孙四十五岁乙丑六月初六日头痛，左关独高，责之少阳内风掀动，最有损一目之弊。若以为外感风寒，则远甚矣。议清少阳胆络法。再此症除左关独高，余脉皆缓，所谓通体皆寒，一隅偏热，故先清一隅之热。《金匮》谓先治新病，旧病当后治也。", "5188": "广二十四岁七月二十二日六脉洪大之极，左手更甚，目斜视，怒气可畏，两臂两手，卷曲而瘛疭，舌斜而不语三四日，面赤身热，舌苔中黄边白，暑入心包胆络，以清心胆之邪为要，先与紫雪丹。", "5189": "八月初二日暑热已退七八，惟十余日不大便，微有谵语，脉沉。可与轻通阳明，与增液承气法。", "5190": "初三日温病下后宜养阴；暑温下后宜兼和胃。盖暑必挟湿，而舌苔白滑故也。脉缓，与外台茯苓饮意。", "5191": "史男七岁癸亥六月十二日右脉洪大无伦，暑伤手太阴，有逆传心包之势，喘渴太甚，烦躁不宁，时有谵语，身热，议两清营卫之法。", "5192": "十三日诸症俱减，热已退，但右脉仍洪，舌黄而滑，呕未尽除。", "5193": "俞男三岁七月初二日暑湿伤脾，暮夜不安，小儿脉当数，且少腹以下常肿痛，肝肾亦复虚寒；况面色青黄，舌苔白，手心时热，调理乳食要紧，防成疳疾。议腑以通为补，食非温不化例。", "5194": "田十四岁暑温误下，寒凉太多，洞泄之后，关闸不藏，随食随便，完谷丝毫不化，脉弦。与桃花汤改粥法。", "5195": "周十四岁壬戌八月十六日伏暑内发，新凉外加。脉右大左弦，身热如烙，无汗，胶痰，舌苔满黄，不宜再见泄泻。不渴，腹胀，少腹痛，是谓阴阳并病，两太阳互争，难治之症。拟先清上焦湿热，盖气化湿亦化也。", "5196": "二十日津液稍回，宿粪未除，潮热因邪气还表，右脉仍然浮大，未可下，宜保津液，护火克金之嗽。", "5197": "二十二日津液消亡，舌黑干刺，用复脉法。", "5198": "二十三日右脉仍数，余邪陷入肺中，咳甚痰艰，议甘润兼凉肺气。", "5199": "二十四日舌黑苔退，脉仍数，仍咳，腹中微胀。", "5200": "二十五日昨晚得黑粪如许，潮热退，唇舌仍绛。热之所过，其阴必伤，与复脉法复其阴。", "5201": "二十八日伏邪内溃，续出白痧如许，脉较前却稍和，第二次舌苔未化，不大便。", "5202": "服此得黑粪如许，而潮热退，脉静。以后一以养阴收功。", "5203": "陈二十八岁左脉洪大数实，右脉阳微，阴阳逆乱，伏暑似疟，最难即愈。议领邪外出法。", "5204": "二甲复脉汤，加黄芩（三钱）如有谵语，其牛黄丸仍服。", "5205": "二十六日昨用甘苦合化阴气法，服后大见凉汗，兹热已除，脉减，舌苔尽退，但六脉重按全无，舌仍干燥。议热之所过，其阴必伤例，用二甲复脉汤，重加鳖甲、生甘草八帖。", "5206": "某乙丑九月十六日夏伤于湿，冬必咳嗽。况六脉俱弦，木旺克土，脾土受克则泄泻，胃土受克则不食欲呕，前曾腹胀，现在胸痞，舌白滑，此寒湿病也。而脉反数，思凉思酸，物极必反之象，岂浅鲜哉！急宜戒恼怒，小心一切为要。", "5207": "十八日脉数甚，思凉，湿中生热之故。", "5208": "巴二十二岁面目青黄，其为湿热无疑；右脉单弦，其为伏饮无疑；脘痞胸痛，合之脉弦，其为肝郁无疑。上年夏日曾得淋症，误服六味酸甘化阴，致令其湿热稳伏久踞，故证现庞杂无伦，治法以宣通三焦，使邪有出路，安胃能食为要。", "5209": "初六日其人本有饮症，又加内暑外凉，在经之邪，似疟而未成，在腑之邪泄泻不止，恐成痢疾，急以提邪外出为要。按六脉俱弦之泄泻，古谓之木泄，即以小柴胡汤为主方，况加之寒热往来乎？六脉俱弦，古谓脉双弦者寒也，指中焦虚寒而言，岂补水之生熟地所可用哉！现在寒水客气，燥金司天，而又大暑节气，与柴胡二桂枝一法。", "5210": "初八日寒暑兼受，成疟则轻，成痢则重。前用柴胡二桂枝一法，现在面色青，热退，痰多而稀，舌之赤者亦淡，脉之弦劲者微细，不渴，阳虚可知，与桂枝柴胡各半汤，减黄芩加干姜。", "5211": "初十日昨用两救表里，已见小效，今日仍宗前法而退之，脉中阳气已有生动之机故也。不可性急，反致偾事。", "5212": "十二日杂受寒暑，再三分析，方成疟疾，寒多热少，脉沉弦，乃邪气深入，与两分阴阳之中偏于温法。", "5213": "十六日脉弦细，指尖冷，阳微不及四末之故。兼之腹痛便溏，痰饮咳嗽，更可知矣。以和胃阳，温中汤，逐痰饮立法。", "5214": "张十七日伏暑酒毒，遇寒凉而发，九日不愈，脉缓而饮，滞下，身热，谵语，湿热发黄，先清湿热，开心包。", "5215": "十九日黄亦少退，脉之软者亦鼓指；惟舌赤、小便赤浊，余湿余热未尽，尚须清之。", "5216": "二十日黄退，小便赤浊，舌赤脉洪，湿热未净。", "5217": "李十八岁十一月初九日伏暑如疟状，脉弦数，寒热往来，热多于寒，解后有汗，与青蒿鳖甲汤，五帖而愈。", "5218": "某九月二十四日初因肝郁，继因内饮招外风为病，现在寒热如疟状。又有伏暑内发，新凉外加之象，六脉弦细而紧，两关独大而浮，厥阴克阳明，医者全然不究病从何来，亦不究脉象之是阴是阳，一概以地黄等柔药补阴，以阴药助阴病，人命其何堪哉。势已沉重，欲成噎食反胃，勉与两和肝胃，兼提少阳之邪外出法。", "5219": "陶五十八岁乙酉九月十八日伏暑遇新凉而发，舌苔裛白，上灰黑，六脉不浮不沉而数，误与发表，胸痞不食，此危证也。何以云危？盖四气杂感，又加一层肾虚，又加一层肝郁，又加一层误治，又加一层酒客中虚，何以克当！勉与河间之苦辛寒法，一以宣通三焦，而以肺气为主，望其气化而湿热俱化也。", "5220": "二十三日舌之灰化为黄，滑而不燥，唇赤颧赤，脉之弦者，化而为滑数，是湿与热俱重也。", "5221": "二十六日伏暑舌之灰者化黄，兹黄虽退，而白滑未除，当退苦药，加辛药，脉滑甚，重加化痰，小心复感要紧。", "5222": "十月初二日伏暑虽退，舌之白滑未化，是暑中之伏湿尚存也，小心饮食要紧。脉之滑大者已减，是暑中之热去也。无奈太小而不甚流利，是阳气未充，不能化湿，重与辛温，助阳气，化湿气。", "5223": "王氏二十二岁二月二十六日伏暑咳嗽寒热，将近一年不解，难望回生，既咳且呕而泄泻，勉与通宣三焦，俾邪有出路，或者得有生机。何以知其为伏暑而非劳？瘵劳之咳，重在丑寅卯木旺之时，或午前，或终日，湿家之咳，旺在戌亥子。劳之寒热后无汗，伏暑寒热如疟状，丑寅卯阳升，乃有汗而止。劳之阴虚身热，脉必芤大，伏暑之脉，弦细而弱。故知其为伏暑而非劳瘵也。再左边久不著席，此水在肝也。", "5224": "裘四十岁乙酉八月初五日酒客中虚湿重，面色滞暗，业已有日，现在又感伏暑新凉，头胀便溏，舌白滑，脉弦细，中虚寒湿可知，不能戒酒，断乎病不除根。盖客症易除，久病伏湿虚寒难退也。", "5225": "周五岁本系伏暑，误以为风寒挟食，发表消导难进，致邪气深入下焦血分，夜热早凉，与煎厥瘅疟相似。食减脉大，汗多便结，先与救阳明之阴。", "5226": "王氏二十三岁甲子五月十一日温毒颊肿，脉伏而象模糊，此谓阳证阴脉耳，面目前后俱肿，其人本有瘰疬，头痛身痛，谵语肢厥，势甚凶危，议普济消毒饮法。", "5227": "十二日脉促，即于前方内加：", "5228": "十八日脉出，身壮热，邪机向外也。然其势必凶，当静以镇之，勿事荒张，稍有谵语，即服：", "5229": "二十日肿消热退，脉亦静，用复脉汤七帖，全愈。", "5230": "王二十三岁乙丑八月十一日温毒发斑，时在初秋，盛暑未消，何妄用大汗大下之伤寒六经法，悖谬已极。右脉洪大芤甚，渴甚，汗太甚。急急重用化斑汤。", "5231": "史二十二岁温毒三日，喉痛胀，滴水不下，身热脉洪数，先以代赈普济散五钱煎汤，去渣嗽口与喉，噙化少时，俟口内有涎，即控吐之。再嗽再化再吐，如是者三五时，喉即开，可服药矣。计用代赈普济散二两后，又用五钱一次与服，每日十数次，三日而喉痛止，继以玉女煎五帖，热全退，后用复脉汤七帖收功。", "5232": "徐五十一岁己酉五月二十日因湿毒而发天行杨梅疮，脉弦兼有外风。", "5233": "陈三十二岁温热面赤，口渴烦躁，六七日壮热大汗，鼻衄，六脉洪数而促，左先生用五苓散双解表里。余曰：此温病阳明经证也，其脉促，有燎原之势，岂缓药所能挽回非白虎不可。", "5234": "煮四碗，分四次服，尽剂而脉静身凉。", "5235": "《脉经》谓数而时一止曰促，缓而时一止曰结。按：古方书从无治促、结之明文，余一生治病，凡促脉主以石膏，结脉主以杏仁。盖促为阳，属火，故以石膏得肺胃之阳；结脉属阴，乃肺之细管中块痰，堵截隧道而然，故以杏仁利肺气而消块痰之阴，无不如意。然照世人用药，石膏用七八钱，杏仁用三五钱，必无效也。吾尝谓未能学问思辨，而骤然笃行，岂非孟浪之极，既已学问思辨，而不能笃行，岂非见义不为，无勇乎。", "5236": "二十五日面赤，舌黄大渴，脉沉肢厥，十日不大便，转矢气，谵语，下证也。小承气汤。", "5237": "二十七日昨日虽大解而不爽，脉犹沉而有力，身热不退而微厥，渴甚面赤，犹宜微和之，但恐犯数下之戒，议增液承气，合玉女煎法。", "5238": "二十八日大便虽不甚爽，今日脉浮不可下，渴思凉饮，气分热也；口中味甘，脾热甚也。议用气血两燔例之玉女煎，加苦药以清脾瘅。", "5239": "初三日邪少虚多，宜用复脉去桂、枣，以其人本系酒客，再去甘草之重甘，加二甲、丹皮、黄芩。", "5240": "某初九日面赤目赤，舌苔满布，至重之温热病，脉反缓而弦，外热反不盛，口反不渴，肢微厥，所谓阳证阴脉，乃本身阳气，不能十分充满，不肯化解耳。兹与化邪法。", "5241": "十一日温病未有不渴而燥者，今舌苔布满而不渴，虽黄而滑，脉缓甚，热不壮，盖挟湿之故也。议照湿温例，治用苦辛寒法。", "5242": "陈三十三岁初八日六脉弦细而劲，阴寒脉也；咳嗽稀痰，阴湿咳也；舌苔刮白而滑，阴舌苔也；呕吐泄泻，阴湿证也。虽发热汗出而解，乃湿中兼风，病名湿温，天下有如是之阴虚证乎？", "5243": "初十日痰饮兼风，误治成坏证。前用温平逐湿除风，诸恶证俱成，惟寒少热多，热后汗出未除，现在面赤口渴，暮夜谵语，有风化热之象，但六脉尚弦，未尽转阳也。再咳嗽则胸胁小腹俱微痛，又有金克木之象。", "5244": "十四日脉弦数，午后潮热，前有白苔，复变黄苔，呕恶口渴，颇有湿疟之象；但咳嗽便溏，又有湿温之形。伏邪内陷，所致最难清理。", "5245": "某初十日六脉俱弦而细，左手沉取数而有力，面色淡黄，目白睛黄。自春分午后身热，至今不愈。曾经大泻后，身软不渴，现在虽不泄泻，大便久未成条，午前小便清，午后小便赤浊。与湿中生热之苦辛寒法。", "5246": "文三十八岁丁卯七月初二日湿温，舌苔白滑厚浊，脉象模糊，弦细而且沉濡。用通三焦法，先寒热，继微热，后不热，更方三十余帖，大抵不出渗湿之苦辛淡法。四十五日以后方解，解后以两和脾胃收功。", "5247": "张六十八岁甲子十一月二十五日舌黄，口渴，头不痛而恶寒，面赤，目赤，脉洪热甚，形似伤寒，实乃冬温夹痰饮，与伏暑一类。", "5248": "二十九日温病渴甚，热甚，面赤甚，脉洪甚。", "5249": "初二日脉洪滑，于前方内加：", "5250": "某三月二十二日脉不浮而细数，大渴欲饮，大汗，里不足之热病也，用玉女煎法。", "5251": "二十三日温热大渴大汗，脉数，昨用玉女煎法，诸证俱减，平素有消渴病，服昨药后，大便稀溏，加牡蛎。一面护阴，一面收下。", "5252": "某初一日冬温，脉沉细之极，舌赤，面赤，谵语，大便闭，邪机纯然在血分之里，与润下法。", "5253": "服一帖而饮下咽，服七帖而舌肿消。服二十帖，诸病虽渐减，而无大效，左肢拘挛如故，舌虽消肿，而语言不清，脉兼结。余曰：此络中痰堵塞，皆误补致壅之故，非针不可。于是延郏七兄针之，舌上中泉穴一针，出紫黑血半茶碗，随后有物如蚯蚓，令伊子以手探出，即使针孔中拉出胶痰一条，如匀粉，长七八寸，左手支沟穴一针，透左关手背三阳之络，用小针十数针。以后用药日日见效。前方止减石膏之半，服至七十余帖，自行出堂上轿矣。", "5254": "哈六十六岁中风湿，口歪，臂不举，腿肿，脉洪数，口渴，胃不开，与辛凉开水道法。", "5255": "中风，神呆不语，前能语时，自云头晕，左肢麻，口大歪，不食，六脉弦数，此痱中也，与柔肝法。", "5256": "李氏七十二岁伏暑挟痰饮，肝郁，又加中风，头痛，舌厚白苔，言蹇，畏寒，脉洪数而弦，先与辛凉清上。", "5257": "又此症肝风无疑，昨服柔肝清热之剂而烧退，是外邪已解。现在六脉弦细，手足发凉，似有厥意。治法熄风之中，似宜参入开心胞之络为是，倘一二天不醒，便难挽回矣。", "5258": "初四日诸症向安，惟余晨泄，左手脉紧，宜补肾阳。", "5259": "陶氏癸酉二月十五日上脉洪大，尺部更甚，左脉弦细，上盛下虚，卒中不能言，如中风状，乃肝风内动络热窍闭之故，证势甚重。", "5260": "黄三十岁肝风内动，脉弦数，乃真水不配相火，水不生木，故木直强而上行，头晕甚，即颠厥也。久不治为痱中，医云痰者妄也。先与清肃少阳胆络，继以填补真阴可也。", "5261": "高氏四十五岁乙丑十一月十一日肝阳上窜，因怒即发，十余年矣。经云：久病在络，岂经药可效？再肝厥之症，亦有寒热之不同。此症脉沉而弦细，其为寒也无疑。大凡寒厥必死，今不死者，以其为腑厥而非脏厥也，现在胁下有块有声，经色紫黑。拟先用温通络脉法。", "5262": "頟三兄夫人二十二岁除夕日亥时先是产后受寒痹痛，医用桂附等极刚热之品，服之大效；医见其效也，以为此人非此不可，用之一年有余。不知温燥与温养不同，可以治病，不可以养生，以致少阳津液被劫无余，厥阴头痛，单巅顶一点，痛不可忍，畏明，至于窗间有豆大微光，即大叫，必室如黑漆而后少安，一日厥去四五次。脉弦细数，按之无力，危急已极，勉与定风珠潜阳育阴，以熄肝风。", "5263": "杨室女四十九岁甲申十二月初二日初因肝郁胁痛，继而肝厥犯胃，医者不识病名肝著，与络痛治法，无非滋阴补虚，或用凉药，以致十年之久，不能吃饭，饮粥汤止一二口，食炒米粉止一酒杯，稍闻声响即痉厥，终夜抽搐，二三日方渐平，六脉弦紧而长，经闭二年，周身疼痛，痰饮咳嗽，终年无已，骨瘦如柴，奄奄一息。此症内犯阳明，故不食；木克脾土，故饮聚；阳明空虚，故无主，闻声而惊；外犯太阳，故身痛而痉；本脏致病，故厥。经谓治病必求其本，仍从肝络论治。", "5264": "乙酉二月二十八日脉稍和平，虽弦而有胃气，干饭能吃一碗有半，经亦复通，仍间服前二方。夜间偶感燥症，欲起不得起，欲坐不得坐，欲卧不得卧，烦躁无奈不可当，约二时，服霹雳散三两许始安。次日仍与和胃。", "5265": "十八日能食干饭两小碗矣，六脉又和一等，仍间服前二方。", "5266": "伊氏二十岁肝郁胁痛病名肝著，亦妇科之常证，无足怪者。奈医者不识，见其有寒热也，误以为风寒而用风药。夫肝主风，同气相求，以风从风，致令肝风鸱张；肝主筋，致令一身筋胀；肝开窍于目，致令昼夜目不合、不得卧者七八日；肝主疏泄，肝病则有升无降，失其疏泄之职，故不大便，小溲仅通而短赤特甚。医者又不识，误以为肠胃之病，而以大黄通之，麻仁润之，致令不食不饥，不便不寐，六脉洪大无伦，身热，且坐不得卧，时时欲呕，烦躁欲怒，是两犯逆也。《金匮》论一逆尚引日，再逆促命期，不待智者而知其难愈也。议宣通络脉法，肝藏血，络主血故也，必加苦寒泄热，脉沉洪有力，且胆居肝内，肝病胆即相随故也。", "5267": "又昨用苦辛法，脉减便通。今日腹中觉痛，将近经期，一以宣络为主。", "5268": "又昨日一味通络，已得大便通利，腹中痛止，但不成寐；今日用胃不和则卧不安，饮以半夏汤，复杯则寐法，仍兼宣络。此仲景先师所谓冲脉累及阳明，先治冲脉后治阳明也。", "5269": "又昨与半夏汤和胃，业已得寐，但脉沉数，溲赤短，议加苦药，泄肝热而通小肠火府。", "5270": "又昨日和胃宣络，兼用苦通火府，今日得寐，溲色稍淡，口亦知味，是阳明有渐和之机矣。惟胸中微痛，背亦掣痛，按肝脉络胸，背则太阳经也。是由厥阴而累及少阳，肝胆为夫妻也；由少阳而累及太阳，少太为兄弟也。今日仍用前法，加通太阳络法。", "5271": "又绕脐痛者，瘕也，亦冲脉肝经之病。", "5272": "又诸证悉减而未尽，左脉已和，右脉弦大，是土中有木，于两疏气血之中，兼泄木安土法。", "5273": "又右脉弦刚，土中木盛。", "5274": "又脉弦数，头痛时止时甚，向来时发时止，已非一日。此乃少阳络痛，虚风内动也。今日且与清胆络法，勿犯中焦。", "5275": "又八脉丽于肝肾，肝病久，未有不累及八脉者，用通补阴络，兼走八脉法。", "5276": "又镇冲脉，泄胆阳，业已得效，仍宗其法。其血络之郁痛未能卒治，盖事有缓急也。", "5277": "苏氏三十二岁癸亥十月二十八日脉弦数，左尺独大，瘕居右胁，发则攻心，痛跃不止，病名肝著，先宜宣络，后补八脉。", "5278": "甘氏五十岁凡两畔不同者，皆肝病也。此证气至丑寅则上升，暮卒复。左脉沉弦，右脉浮弦，升降失司，痰饮斯聚。", "5279": "谢四十四岁辛巳三月二十四日病起肝郁胁痛，痰中带血，病名肝著。医者不识络病因由，与络病治法，非见血投凉，即见血补阴，无怪乎愈治愈穷也。大凡血症之脉，左脉坚搏，治在下焦血分；右坚搏，治在上焦气分。兹左手脉浮取弦，沉取洪大而数，重按即芤，前曾痰有气味，现在痰挟瘀滞黑色，唇舌皓白，其为肝经络瘀挟痰饮，咳血无疑。势已惫极，勉与宣络止血，兼之两和肝胃，以逐痰定咳。（方此未服）", "5280": "四月初三日血家左手脉坚搏，治在下焦血分。此症先因肝络瘀滞，以致血不归经，日久不治，由阴经损及阳气，自汗溺变痿弱，阳虚也，左脉洪数而芤，阴伤也。如是阴阳两伤之极，而瘀滞仍然未净，通络则虚急，补虚又络滞，两难措手。不得已用新绛一方，缓通其络，其补药则用阴阳两摄法，聊尽人力而已。（从此服起）", "5281": "初四日病起于胁痛，瘀血致壅，久嗽成劳，至骨痿不能起床，仍有瘀滞不化之象，且痰有臭味，即系肝著成痈。前日脉虽芤大而涩，昨日大见瘀血后，今日则纯然芤矣，岂非瘀血之明征乎？若一味贪补，断难再起，兼之宣络，万一得苏，妄诞之诊，高明酌之。", "5282": "初五日痰中臭味太甚，黑痰未净，是活络之方不能除；脉芤自汗甚，是补摄之方又不可缓。痰稀纯白，内有支饮，于补方中去牡蛎、海参。盐味之碍饮者。此症极虚极实，时人但知其虚而不知其实，所以日误一日，以至于此。治实碍虚，治虚碍实，焉望成功。一通一补，俱每日照前服法未改。", "5283": "初七日脉较前敛戢，于新绛方内半夏加钱半，作三钱，余仍旧，服法亦如之。", "5284": "初八日今日左尺脉独大，加封固肾气法，余有原案二方，每日间服如前。", "5285": "十七日左脉空大未敛，精神较前虽好，犹宜收摄下焦，于前方内去龟板、五味子、白芍、海参、苁蓉，余如旧间服法。煮好去渣，再上火煎成二杯，分二次服。", "5286": "二十一日脉少敛，通补二方间服如前，四帖。", "5287": "二十四日痰浊未变，脉象少敛，午后微热不寐，饮食由渐而加，不可太过不及。", "5288": "陀五十九岁病由情志而伤，中年下焦精气不固，上年露痱中之萌，近因情志重伤，又在相火主令，君火司天，君火客气，内与本身君火相火相应，以致肝风鸱张，初起如狂。医者仍然攻风劫痰，大用辛温刚燥，复以苦寒直下，是助贼为虐也。现在左脉实大坚牢，大非吉兆，勉以紫雪定瘛疭肢厥，而泄有余之客热，再以定风珠济不足之真阴，而息内风之震动。如果病有回机，神色稍清，再拟后法。", "5289": "二十日左脉仍然牢固，较昨日诸证俱减，舌苔黄黑，尺肤热，阳明络现。昨谓不止本身虚热，且有客气加临，非虚语也，汤药仍照前方，再以清宫汤，化牛黄紫雪辈，二时一次。", "5290": "二十一日瘛疭肢厥虽止，其狂如故，会厌不利，脉仍牢固数大。按：阳盛并于上则狂，的系阳火有余，非极苦之药，直折其上盛之威，其势未必得减。况小肠火腑，非苦不降，痰亦因之而降，其会厌庶可得利矣。", "5291": "二十四日脉气大减，但阳升阴络，机不灵，拟兼清会厌胆络之热。", "5292": "二十六日稍进糜粥，觉勇力培常，舌红黑，脉亦较昨日实大，犹为阳火有余。", "5293": "初二日诸证与脉俱减，然未以净，苦药犹不能除也，颊肿系客气，拟加辛凉。", "5294": "齐四十二岁己巳二月初二日脉弦数而劲，初因肝郁，久升无降，以致阳并于上则狂。心体之虚，以用胜而更虚，心用之强，因体虚而更强。间日举发，气伏最深，已难调治。况现在卯中乙木盛时，今岁又系风木司天，有木火相煽之象，勉与补心体泻心用两法。", "5295": "初六日操持太过，致伤心气之狂疾，前用补心体，泻心用，摄心神，已见大效，脉势亦减，经谓脉小则病退是也。", "5296": "某二十七日左脉弦劲，经谓单弦饮癖，前五日因观戏后，病恶梦，病狂肢厥，经谓阳并于上则狂，两阴交尽之厥。《灵枢》有淫发梦一卷，大意以五脏偏胜，非因梦而后病也。前人诸般怪症。皆属于痰之诊。虽不尽然，但此症现在咳嗽块痰，左脉单弦，应作痰治。", "5297": "二十八日狂而厥，左脉单弦，咳嗽痰块，昨议应作痰治。今日左脉渐有和平之象，证于外者亦效，但形貌怯弱，色白而嫩，脉亦不壮，此症之痰，究因惊起，凡神气壮者不惊，况惊后恶梦发后大汗，其为阳虚神怯显然。此症将来必大补而后收功，现在不得以攻痰见效，而忘其虚怯，与化痰之中，微加益气。", "5298": "二十九日体虚有痰之证，不能纯治一边，今日脉微滑数，于昨日法中，少加逐痰。", "5299": "初一日昨日稍加逐痰，痰出如许，大势安静，但多怒耳，右脉仍滑，痰未净也。", "5300": "鲍三十二岁十月初二日大狂七年，先因功名不遂而病，本京先医市医儒医，已历不少，既徽州医、杭州医、苏州医、湖北医。所阅之医，不下数百矣，大概补虚者多，攻实者少。间有已时，不旋踵而发。余初诊时，见其蓬首垢面，下体俱赤，衣不遮身，随作随毁，门窗分碎，随钉随拆，镣铐手足，外有铁索数根，锢锁于大石盘上，言语之乱，形体之羸，更不待言。细询其情，每日非见妇人不可，妇人不愿见，彼尽闹不可，叫号声嘶，衰鸣令人不可闻，只得令伊姬妾强侍之，然后少安，次日仍然，无一日之空。诊其脉六脉弦长而劲，余曰：此实症，非虚症也。于是用极苦以泻心胆二经之火，泻心者必泻小肠，病在脏，治其腑也，但无出路，亦必泻小肠也。", "5301": "服二帖而大效，妄语少而举动安静，初三日见其效也。以为久病体虚，恐过刚则折，用病减者减其制例，于原方减苦药，加补阴之甘润。初五日，病家来告云，昨服政方二帖，病势大重，较前之叫哮妄语加数倍之多，无一刻静，此症想不能治，谅其必死，先生可不诊矣。余曰：不然，初用重剂而大效，继用轻剂加补阴而大重，吾知进退矣。复诊其脉，弦长而数，于是重用苦药。", "5302": "章氏四十二岁先是二月间病，神识恍惚，误服肉桂、熟地等补药，因而大狂，余于三月间用极苦以折其上盛之威，间服芳香开心包，治三十日而愈。但脉仍洪数，余嘱其戒酒肉，服专翕大生膏，补阴配阳，彼不惟不服丸药，至午节大开酒肉，于是狂不可当，足臭至邻，不时脱净衣裤，上大街，一二男子不能搏之使回。五月十四日，又延余视，余再用前法随效，二三日仍然如故，盖少阳相火极，挟制君主行令，药随暂开其闭，暂折其威，相火一动，而仍然如故。延至六月十六日，午刻复自撕其裤，人不防而出大门矣。余坐视不忍，复自渐无术以已其病，因谓其胞弟曰：此症非打之极痛，令其自著衣裤也不可。盖羞恶之心，亦统于仁，能仁则不忍，忍则不仁，不仁之至，羞恶全丧，打之极痛，则不能忍，不忍而仁心复，仁心复而羞恶之心亦复矣，此古圣王扑作教刑之义也。伊弟见其乃姊如是景况，羞而成怒，以保父母体面为义，于是以小竹板责其腿，令著裤，彼知痛而后自作衣著衣稍明。次月十七日立秋，余以大剂苦药，一帖而全愈，盖打之功，与天时秋金之气，药之力，相须而成功也，后以专翕生生膏而收全功。", "5303": "二十岁所伤残，脾阳肾阳，亦为苦寒滑润，伐其生发健运之常，此腹痛晨泄不食，脉沉弦细之所由来也。按：三焦俱损，先建中焦，补土可以生金，肾关之虚，亦可仰赖于胃关矣。", "5304": "陈二十三岁左脉搏大，下焦肝肾吐血，上焦咳嗽，中焦不食，谓之三焦俱损，例在不治，勉拟三焦俱损，先建中焦法。", "5305": "陈氏三十二岁甲子四月初五日脉弦细失音，谓之金碎不鸣，暮热不食，食则呕，亦系俱损为难治。", "5306": "施二十岁形寒而六脉弦细，时而身热，先天不足，与诸虚不足之小建中法。", "5307": "姚三十岁乙酉五月初五日六脉弦细而紧，劳伤吐血，诸虚不足，小建中汤主之。", "5308": "李二十四岁乙酉五月初三日每日五更，胃痛欲饮，得食少安，胃痛则背冷如冰，六脉弦细，阳微，是太阳之阳虚，累及阳明之阳虚，阳明之阳虚现症，则太阳之阳更觉其虚。此等阳虚，只宜通补，不宜守补。", "5309": "傅十八岁乙酉五月十三日六脉弦细而紧，吐血遗精，阳气不摄，胃口不开，法当与建中复其阳：奈系酒客，中焦湿热壅聚，不可与甘，改用辛淡微甘以和胃，胃旺得食，而后诸症可复也。", "5310": "二十二日业已见效，胃开得食，脉尚弦紧，多服为宜。", "5311": "沈十五岁乙酉年五月十五日幼孩脉双弦而细紧，瘰疬结核，胃阳不开，色白食少，且呕，形体羸瘦，与通补胃阳。", "5312": "六月十二日前药已服十二帖，呕止胃开，腹微胀，脉有回阳之气。于前方加厚朴、杉皮消胀，胀消后。按服前方化核，于前方内去生姜、广皮，加香附、土贝母、忍冬藤、青橘叶、海藻，以化瘰疬痰核。", "5313": "钱二十七岁乙酉五月二十八日六脉弦紧，胃痛，久痛在络，当与和络。", "5314": "八月十九日六脉弦细而紧，脏气之沉寒可知，食难用饱，稍饱则䐜胀，食何物则嗳何气，间有胃痛时，皆腑阳之衰也。阳虚损症，与通补脏腑之阳法，大抵劳阳者十之八九，劳阴者十之二三，不然经何云劳者温之。世人佥以六味八味治虚损，人命其何堪哉，暂戒猪肉介属。", "5315": "二十四日前方已服五帖，脉之紧无胃气者和，痛楚已止，颇能加餐，神气亦旺，照前方减川椒一钱，丁香一钱，再服七帖，可定丸方。", "5316": "三十日前因脉中之阳气已回，颇有活泼之神，恐刚燥太过，减去川椒、丁香各一钱，今日诊脉，虽不似初诊之脉紧，亦不是念四日之脉和肢凉，阳微不及四末之故。与前方内加桂枝五钱，再服七帖。", "5317": "诸症向安，惟六脉尚弦，与通补脾胃两阳。", "5318": "谭四十七岁乙酉八月二十八日病后六脉弦细而紧，绝少阳和之气，形体羸瘦，幸喜胃旺，可以守补，与形不足者，补之以气法。", "5319": "陈十九岁脉虚数，头目眩冒，暮有微热，饮食减少，面似桃花，身如柳叶。", "5320": "李四十岁面赤舌绛，脉虚弦而数，闻妇声则遗，令其移居大庙深处。", "5321": "三甲复脉汤", "5322": "宗二十五岁粉红色，虚数脉，头时晕，身微热，心悸气短不寐，食少，与补心肾之阴。", "5323": "王脉弦如刃，吐血后左胁微痛，喉中如有物阻。治在肝络，使血不瘀，则吐可止，止后当与补阴。", "5324": "又如刃之脉，已渐平减，但虚数如故。", "5325": "普女二十三岁大凡吐血，左脉坚搏，治在下焦血分，右脉坚搏，治在上焦气分。又有心血、肝血、大肠血、小肠血、胃血、冲脉血，各种不同，岂一概见血，投凉所可治哉，无怪乎室女童男，劳瘵干血甚数，体厚色白，少腹痛，小便短赤，咳吐瘀紫，继见鲜红血，喉中咸，此冲脉袭受寒邪，致经不得行，倒送而吐耳。大忌柔润寒凉，议温镇冲脉，行至阴之瘀浊，使经得行而血症愈矣。苦辛通法。", "5326": "罗三十二岁右脉浮洪，咳痰吐血，唇绛，治在上焦气分。", "5327": "初三日血后咳不止，进食不香，右脉不浮而仍洪，兼与养阳明之阴。", "5328": "初五日诸证俱退，惟进食不旺，右脉大垂尺泽，先与甘寒养胃阴。", "5329": "伊二十四岁癸酉七月二十五日六脉弦数，两关独浮，左更甚，右胁痛，胸中痞塞，肝郁吐血，先理肝络。", "5330": "二十三日左脉仍弦细数锋钢如刃，吐血，左手脉坚搏，治在下焦血分。", "5331": "二十六日脉数减，弦刚甚。", "5332": "章丙寅二月初九日劳伤吐血，脉双弦，《金匮》谓大则为虚，弦则为减，虚弦相搏，其名曰革，男子失精亡血诸不足，小建中汤主之。", "5333": "章丙寅二月二十四日右脉空大，左脉弦，血后咳吐浊痰腥臭，真液不守，阴火上冲克金，非纯补纯清之症，然而惫矣。", "5334": "二十八日脉少敛，痰咳亦减，切戒用心。", "5335": "脉大敛戢，古所谓脉小则病退是也，颇有起色，若得舌苔化去，则更妙矣。", "5336": "胡三十一岁乙酉四月二十八日劳伤吐血，汗多足麻，六脉弦细不数，小建中汤主之。", "5337": "沈二十四岁乙酉五月初十日六脉弦数，劳伤吐血，建中汤主之。", "5338": "十五日六脉弦劲，前用建中，现脉已和，左手仍劲，胸前咳甚则痛，间有一二日紫色之血，按：肝脉络胸，是肝络中尚有瘀滞，且与宣络。", "5339": "二十一日六脉弦数，以清气在头之故，受微风，右寸独浮大而衄血，暂与清清道之风热。", "5340": "吴七十岁周身痒不可当，脉洪，狂吐血，与大黄黄连泻心汤，以后永不发。", "5341": "史五十岁酒客大吐狂血盛盆，六脉洪数，面赤，三阳实火为病，与大黄黄连泻心汤，一帖而止，二帖脉平，后七日又复发，血如故，又二帖。", "5342": "吴二十五岁每日饱食就床，脾阳致困，因失其统血之职，此为伤食吐血，脉弦，与灶中黄土，每日一斤，分二次煎服，将尽半月而愈，戒其夜食，永远不发。", "5343": "寿二十岁乙酉十一月十二日怒伤吐血，两胁俱痛，六脉弦紧，误补难愈。凡怒伤肝郁，必有瘀血，故症现胁痛，一以活肝络为主，俟瘀血去净，而后可以补虚。", "5344": "二十二日复诊脉之弦紧虽减，而未和缓，胁痛虽大减，而未净除，与原方去桃仁，加细生地（五钱）。", "5345": "十二月初五日六脉弦细而紧，《金匮》谓脉双弦者寒也，弦则为减，男子失精亡血，小建中汤主之。怒伤吐血愈后，以小建中复阳生阴。", "5346": "初七日小儿脉当数而反缓，粪后便血，前用黄土汤，业已见效，仍照前法加刚药，即于前方内去白芍、全当归，加：", "5347": "胡三十岁乙酉年九月十七日本系酒客，湿中生热，久而发黄，颜色暗滞，六脉俱弦，其来也渐，此非阳黄，况粪后见红，非又为小肠寒湿乎。", "5348": "二十一日诸症皆效，大势未退，左脉紧甚，加熟附子一钱，降香末三钱，干姜一钱，已服三帖。", "5349": "七月十四日面色青黄滞暗，六脉弦细无阳，胃口不振，暂与和胃，其黄土汤，俟便红发时再服。", "5350": "十一月十五日肝郁挟痰饮，寒湿为病，前与黄土汤，治粪后便血之寒湿，兹便红已止，继与通补胃阳，现在饮食大进，诸症渐安，惟六脉细弦，右手有胃气，左手弦紧，痰多畏寒，胁下仍有伏饮，与通补胃阳，兼逐痰饮。", "5351": "十二月初十日脉弦紧痰多畏寒，冲气上动，与桂枝茯苓甘草汤，合桂枝加桂汤法。", "5352": "十一日冲气已止，六脉紧退，而弦未除，可将初十日方，再服半帖，以后再服二十九日改定方，以不畏寒为度。", "5353": "十四初背畏寒，脉仍弦紧，再服十二月初十日桂枝加桂汤二帖，以峻补冲阳，服药后吐顽痰二口。", "5354": "十七日脉仍弦紧，背犹畏寒，阳未全复，照原方再服二帖，分四日服。", "5355": "十九日前之畏寒，至今虽减，而未痊愈，脉之弦紧，亦未冲和，冲气微有上动之象，可取初十日桂枝加桂汤法，再服二帖，分四日，立春以后故也。", "5356": "丙戌正月初五日六脉俱弦，左脉更紧，粪后便红，小肠寒湿，黄土汤为主方，议黄土汤去柔药，加淡渗通阳，虽自觉胸中热，背心如热水浇，所云热非热也，况又恶寒乎。", "5357": "阳虚脉弦，素有寒湿痰饮，与蠲饮丸方，通阳渗湿而补脾阳。", "5358": "初十日粪后便红虽止，寒湿未尽，脉之紧者亦减，当退刚药，背恶寒未罢，行湿之中，兼与调和营卫。", "5359": "陈三十二岁甲寅年二月初四日太阴所至，发为䐜胀者，脾主散津液，脾病不能散津，土曰敦阜，斯䐜胀矣。厥阴所至，发为䐜胀者，肝主疏泄，肝病不能疏泄，木穿土位，亦䐜胀矣。此症起于肝经郁勃，从头面肿起，腹因胀大，的系蛊胀，而非水肿，何以知之。满腹青筋暴起如虫纹，并非本身筋骨之筋，故知之。治法行太阳之阳，泄厥阴之阴为要，医用八味丸误治，反摄少阴之阴，又加牡蛎涩阴恋阳，使阳不得行，而阴凝日甚，六脉沉弦而细，耳无所闻，目无所见，口中血块累累续出，经所谓血脉凝泣者是也。势太危极，不敢骤然用药，思至阳而极灵者，莫如龙，非龙不足以行水，而开介属之翕，惟鲤鱼三十六鳞能化龙，孙真人曾用之矣。但孙真人《千金》原方去鳞甲用醋煮，兹改用活鲤鱼大者一尾，得六斤不去鳞甲，不破肚，加葱一斤，姜一斤，水煮熟透，加醋一斤，任服之。", "5360": "洪氏六十八岁孀居三十余年，体厚忧郁太多，肝经郁勃久矣，又因暴怒重忧，致成厥阴太阴两经䐜胀并发，水不得行，肿从跗起，先与腰以下肿，当利小便例之五苓散法，但阴气太重，六脉沉细如丝，断非轻剂所能了。", "5361": "前方服三五帖不效，亦无坏处，小便总不见长，肉桂加至二三两，桂枝加至四五两，他药称是，每剂近一斤之多，作五六碗，服五七帖后，六脉丝毫不起，肿不消，便亦不长。所以然之故，肉桂不佳，阴气太重，忧郁多年，暴怒伤肝，必有陈菀。仍用原方加鸡矢醴熬净烟六钱，又加附子八钱，服之小便稍通，一连七帖，肿渐消，饮食渐进，形色渐喜。于是渐减前方分量，服至十四帖，肿胀全消。后以补脾阳，疏肝郁收功。", "5362": "郭氏六十二岁先是郭氏丧夫于二百里外其祖墓之侧，郭携子奔丧，饥不欲食，寒不欲衣，悲痛太过，葬后庐墓百日，席地而卧，哭泣不休，食少衣薄，回家后致成单腹胀，六脉弦，无胃气，气喘不能食，唇舌刮白，面色淡黄，身体羸瘦。余思无情之草木，不能治有情之病，必得开其愚蒙，使情志畅遂，方可冀见效于万一。因问曰：汝之痛心疾首，十倍于常人者何故？伊答曰：夫死不可复生，所遗二子，恐难立耳。余曰：汝何不明之甚也。大凡妇人夫死，曰未亡人，言将待死也。汝如思夫愈切，即死墓侧，得遂同穴之情，则亦已矣。虽有病何必医，医者求其更苏也。其所以不死者，仍系相夫之事业也。汝子之父已死，汝子已失其荫，汝再死，汝子岂不更无所赖乎。汝之死，汝之病，不惟无益于夫，而反重害其子，害其子，不惟无益于子，而且大失夫心。汝此刻欲尽妇人之道，必体亡夫之心，尽教子之职，汝必不可死也。不可死，且不可病，不可病，必得开怀畅遂，而后可愈。单腹胀，死症也。脉无胃气，死脉也。以死症而见死脉，必得心火旺，折泄肝郁之阴气，而后血脉通，血脉通，脏气遂，死证亦有可生之道。诗云：见𬀪曰消者是也。伊闻余言大笑，余曰：笑则生矣。伊云：自此以后，吾不惟不哭，并不敢忧思，一味以喜乐从事，但求其得生，以育吾儿而已。余曰：汝自欲生则生矣。于是为之立开郁方，十数剂而收全功。", "5363": "陈二十六岁乙酉年五月十五日脉弦细而紧，不知饥，内胀外肿，小便不利，与腰以下肿当利小便法，阳欲灭绝，重加热以通阳，况今年燥金，太乙天符，经谓必先岁气，毋伐天和。", "5364": "二十六日服前方八帖，肿胀稍退。惟阳脉微弱，加以椒炭三钱；大便不通，加两头尖三钱，去陈菀。", "5365": "初七日服肝络药，胀满、胁痛、不寐少减，惟觉胸痛。按：肝脉络胸，亦是肝郁之故。再小便赤浊，气湿也。", "5366": "十四日脉缓，太阳已开，而小便清通，阳明已阖，而得寐能食。但䐜胀不除，病起肝郁，与行湿之中，必兼开郁。", "5367": "徐三十岁腹胀且痛，脉弦细，大便泄，小便短，身不热，此属寒湿，伤足太阴。", "5368": "丁氏五十八岁滞下白积，欲便先痛，便后痛减，责之积重，脉迟而弦，甚痛，盖冷积也，非温下不可。", "5369": "二十日先泄后滞下，古云难治，非一时可了，且喜脉弱，尚有生机。", "5370": "二十三日脉沉有力，滞下，胀痛太甚，便后少减，片时其痛仍然，议纲开一面，用温下法。", "5371": "张二十七岁甲子三月十三日脐右有积气，以故右脉沉细弦沉伏，阳微之极，浊阴太甚克之也。溯其初原从左胁注痛而起，其为肝著之咳无疑。此症不必治咳，但宣通肝之阴络，久病在络故也。使浊阴得有出路，病可自已，所谓治病必求其本者也。如不识纲领而妄冀速愈，必致剥削阳气殆尽而亡。", "5372": "十九日服通络药，已见小效，脉气大为回转，但右胁著席则咳甚，胁下支饮故也，议于前方内去桃仁、川楝、小茴，加：", "5373": "六月初九日业已见效，未能除根，照常服前药，早晚各五分，症瘕痛发时服二钱，舌苔厚白，面色淡黄而暗，左脉沉细阳微，再与汤药行湿通阳。", "5374": "甘二十九岁乙酉年五月初一日十年瘕气，六脉弦细而紧。淡吴萸（三钱）乌药（三钱）川椒炭（五钱）归须（二钱）良姜（二钱）小茴香（五钱，炒黑）", "5375": "王氏四十岁乙酉五月二十一日六脉弦紧，心下伏梁，非易化之症。一生忧泣，肝之郁也，又当燥金太乙天符之年，金来克木，痛愈甚矣。与温络法，其吐血亦络中寒也。", "5376": "余氏三十岁乙酉五月二十四日瘕结脐左，经来必痛，六脉沉细，阳微。", "5377": "车五十五岁须发已白大半，脐左坚大如盘，隐隐微痛，不大便十数日。先延外科治之，外科谓肠痈，以大承气下之，三四次终不通。延余诊视，按之坚冷如石，面色青黄，脉短涩而迟，先尚能食，屡下之后，糜粥不进，不大便已四十九日。余曰：此症也，金气之所结也，以肝木抑郁，又感秋金燥气，邪中入里，久而结成，愈久愈坚，非下不可。然寒下非其治也，以天台乌药散二钱，加巴豆一分，姜汤和服。设三服以待之，如不通，第二次加巴豆霜分半，再不通，第三次加巴豆霜二分，服至三次后，始下黑亮球四十九枚，坚莫能破，继以苦温甘辛之法调理，渐次能食。又十五日不大便，余如前法，下至第二次而通，下黑亮球十五枚，虽亦坚结，然破之能碎，但燥极耳，外以香油熬川椒熨其坚处，内服芳香透络，月余化净。于此证方知燥金之气伤人如此，而温下之法，断不容紊也。", "5378": "龚五十八岁先是大小便俱闭，自用大黄八钱，大便虽通而小便点滴全无，续用五苓，仍不通，诊其六脉弦紧，病因肝郁而成，开阴络法。", "5379": "珍四十五岁血淋太多，先与导赤不应，继以脉弦，细询由怒郁而起，转方与活肝络。", "5380": "王四十五岁，小便狂血，脉弦数，病因肝郁。", "5381": "保五岁夏日痘后受暑，小便不通，脉洪数，玉茎肿亮，蜷曲如勾，与凉利膀胱。", "5382": "叶四十五岁乙酉年七月初一日金实无声，六脉俱弦，痰饮兼之湿痹，小便白浊，先与行湿。", "5383": "伏饮湿痹便浊，前与淡渗通阳，已服三十帖，因停药二十余日，现在饮又上泛，胸满短气，腰酸淋浊未除，且与行心下之饮，脉弦细，阳不复。", "5384": "陶四十五岁乙酉年四月十五日久泄脉弦，自春令而来，古谓之木泄，侮其所胜也。", "5385": "五月初六日前曾木泄，与小柴胡汤十三帖而愈。向有粪后便红，乃小肠寒湿之症，现在脉虽弦而不劲，且兼缓象，大便复溏，不必用柴胡汤矣，转用黄土汤法。", "5386": "八月初六日胃不开，大便溏，小便不畅，脉弦。", "5387": "陆二十七岁乙酉年五月十九日六脉弦细，面色淡黄，泄则脾虚，少食则胃虚，中焦不能建立，安望行经，议先与强土。", "5388": "二十八日右脉宽泛，缓也。胃口稍开，泄则加添，小便不通，加实脾利水。", "5389": "六月十八日前方服十四帖，泄止，胃稍醒，脘中闷，舌苔滑，周身痹痛，六脉弦细而沉，先与和中，治痹在后。", "5390": "汪男三岁初报痘点，形即繁重，表虚脉滑，心热恣甚，谨防八九朝塌痒，且与辛凉解肌透毒。", "5391": "十五日十天浆足色苍，形势圆绽，四肢陆续上浆，皮肤扪之平和，不冷亦不过热，脉洪数有力，合观皆情理之正，其不食畏缩，皆痛象也。痘多浆亦多，炼气血而成浆，痛亦情理之正，断非陷症，议补气以胜痛，活络以定痛法，似不歧于路矣。", "5392": "王左尺独大，肾液不充，肾阳不安其位，尺脉以大为虚，经所谓阴衰于下者是也。右手三部俱弦，食入则痛，经所谓阳结于上者是也。有阴衰而累及阳结者，有阳结而累及阴衰者。此证形体长大，五官俱露，木火通明之象。凡木火太旺者，其阴必素虚，古所谓瘦人多火，又所谓瘦人之病，虑虚其阴。凡噎症治法，必究阴衰阳结，何者为先，何者为后，何者为轻，何者为重？此症既系阴虚为本，阳结为标，何得妄投大黄十剂之多？虽一时暂通阳结，其如阴虚而愈虚，何业医者岂不知数下亡阴乎？且云歧子九法，大半皆攻，喻嘉言痛论其非，医者岂未之见耶？愚谓因怒停食，名之食膈，或可一时暂用，亦不得恃行数用，今议五汁饮果实之甘寒，牛乳血肉之变化，降胃阴以和阳结治其标，大用专翕膏峻补肝肾之阴，以救阴衰治其本，再能痛戒恼怒，善保太和，犹可望愈。", "5393": "李五十四岁大凡噎症由于半百之年，阴衰阳结，古来纷纷议论，各疏所长，俱未定宗。大抵偏于阳结而阴衰者，宜通阳气，如旋覆代赭汤，进退黄连汤之类。偏于阴衰而阳结者，重在阴衰，断不可见一毫香燥，如丹溪之论是也。又有食膈宜下，痰膈宜导，血膈宜通，络气膈宜宣。肝呕吐太过而伤胃液者，宜牛转草复其液。老僧寡妇，强制太过，精气结而成骨，横处幽门，宜鹅血以化之。厨役受秽浊之气伤肺，酒肉胜食而伤胃，宜化清气，不可胜数。按：此症脉沉数有力而渴，面色苍而兼红，甫过五旬，须发皆白，其为平日用心太过，重伤其阴，而又伏火无疑。用玉女煎法。", "5394": "二十日阳脉已起，恐过涸其液，议进阴药，退阳药。", "5395": "二十五日前日脉数，因退阳进阴，今日脉缓而痰多，仍须进阳，俾中焦得运，以复其健顺之体。", "5396": "傅五十五岁先因酒楼中饮酒，食烧小猪响皮，甫下咽，即有家人报知朋友凶信，随即下楼寻车，车伕不知去向，因步行四五里，寻至其友救难未遇。又步行四里，又未遇。渴急饮冰冻乌梅汤三碗，然后买车返家，心下隐隐微痛，一月后痛有加，延医调治，一年不效。次年五月饮水一口，胃中痛如刀割，干饭不下咽，已月余矣。闰五月初八，计一粒不下已十日，骨瘦如柴，面赤如赭，脉沉洪有力，胃中痛处，高起如桃大，按之更痛。余曰：此食膈也，当下之。因用大承气汤，加牵牛，作三碗，一碗痛至少腹，三碗痛至肛门，大痛不可忍，又不得下。于是又作半剂，服一碗，外加蜜导法，始下如鸭蛋，黑而有毛，坚不可破。次日先吃烂面半碗，又次日饮粥汤，三日食粥，五日吃干饭矣。下后所用者，五汁饮也。", "5397": "杨四十六岁先因微有痰饮咳嗽，误补于前，误下于后，津液受伤，又因肝郁性急，致成噎食，不食而大便燥，六脉弦数，治在阴衰。", "5398": "二十三日前方业已见效，但脉迟紧，与通养胃阳。", "5399": "恒氏二十七岁初因大惊，肝气厥逆，呕吐频仍。复因误补，大呕不止，呕急避人以剪刀自刎。渐即米粒不下，体瘦如柴，奄奄一息。仍不时干呕，四肢如冰，脉弦如丝而劲，与乌梅丸法。", "5400": "王三十岁癸亥六月十五日六脉俱濡，右寸独大，湿淫于中，肺气贲郁，因而作哕，与伤寒阳明足太阴之寒哕有间，以宣肺气之痹为主。", "5401": "十九日脉之濡者已解，寸之大者已平。惟胃中有饮，隔拒上焦之气，不得下通，故于其旺时而哕甚，今从阳明主治。", "5402": "二十二日哕虽止而六脉俱数，右手更大，泄泻色黑，舌黄，气分湿热可知。", "5403": "朱乙丑二月初二日右脉洪数有力，金实无声，麻杏石甘汤证也。奈已为前医发汗，麻黄未便再用，议清音汤加石、杏。", "5404": "初四日右脉洪数，已减其半，音亦渐开，仍用麻杏石甘加半夏一帖。", "5405": "沈二十岁正月二十九日六脉弦细若丝，阳微极矣。咳嗽便溏，纳食不旺，由上焦损及中焦，所以致损之由，初因遗精，继因秋伤于湿，冬必咳嗽。外邪未清，骤然用补，使邪无出路，致咳嗽不已。古谓病有三虚一实者，先治其实，后治其虚。现在喉哑治实，先与提肺气，治虚与诸虚不足之小建中汤。", "5406": "二月初六日六脉弦细之极，阴阳俱损，急需用补，以外感未净，喉音未清，暂与理肺二帖，后再诊。", "5407": "服五帖音大出，但脉滑耳，与清音汤。", "5408": "服五帖音清，脉滑痰饮不尽，与外台茯苓饮法，减辛药。", "5409": "兰女十四岁脉数，水气由面肿至足心。经谓病始于上而盛于下者，先治其上，后治其下。议腰以上肿当发汗例，越婢加术汤法。", "5410": "二十六日前因中焦停饮咳嗽，转用温药，今虽饮咳见效，小便究未畅行，脉之沉部洪较有力，症本湿中生热，又有酒毒，仍凉利小便之苦辛淡法。", "5411": "二十八日风水已愈其半，复感风寒，身热头痛虽减，身半以上覆肿，口渴，浮脉数，仍与越婢加术法。", "5412": "二十九日风水汗后，脉洪数，渴而停水，肿水全消，尤宜凉开膀胱。", "5413": "初五日小便犹不甚长，胃中得热物微噎，右脉滑数。", "5414": "初七日小便仍未通畅，右脉数大未退，仍宜凉肺以开膀胱。", "5415": "初九日肿未全消，又发痰饮，咳嗽，表通则小便长，右脉洪数，议照溢饮例，与大青龙汤。", "5416": "十五日肿减咳增，脉洪数，衄未止。", "5417": "十七日咳虽减，脉仍滑数，肿未全消。", "5418": "福二十四岁初因爱饮冰冻黄酒，与冰糖冰果，内湿不行，又受外风，从头面肿起，不能卧，昼夜坐被上，头大如斗，六脉洪大，先以越婢汤发汗。肿渐消，继以调理脾胃药，服至一百四十三帖而愈，嘱戒猪肉、黄酒、水果。伊虽不饮，而冰冻水果不能戒也，一年后粪后便血如注，与金匮黄土汤，每剂黄土用一斤，附子用八钱，服至三十余剂而血始止。后与温补脾阳至九十帖而始壮。", "5419": "煮四碗，四次服。共服十三帖而后脉转。", "5420": "胡十八岁四月十九日跗肿，右脉洪数，痰多咳嗽，口渴，茎中痛，与凉利小便法。", "5421": "五月初六日脉之洪数者减，去石膏二钱，加：", "5422": "二十四日脉洪数，小便反黄，加黄柏、滑石，茎痛止，去甘草。", "5423": "七月初四日小便已长，肿未全消，脉弦滑，咳嗽多痰。", "5424": "张二十岁七月十九日身热头痛，腰痛，肢痛，无汗，六脉弦细，两目不明，食少，寒湿痹也。", "5425": "初八日痹症已愈，颇能健步，便溏泄泻皆止，目已复明，胃口较前加餐。因服一帖，脉稍数，寒湿有化热之象，当与平药，逐其化热之余邪而已。", "5426": "云苓皮（五钱）防己（二钱）滑石（六钱）桑枝（五钱）泽泻（三钱）晚蚕砂（三钱）苡仁（五钱）杏仁（二钱）六月十八日又感受暑湿，泄泻，脉弦，腹胀，与五苓法。", "5427": "赵氏四十七岁六月二十日太阳寒痹，脉弦，背心板著而痛。", "5428": "七月初二日脉已回阳，痛未止，每日服半帖，六日三帖。加：", "5429": "初九日脉仍小，阳未回，背仍痛，再服三帖，分六帖。", "5430": "赵三十六岁五月初六日痹症夹伏湿胀痛，且有肥气，湿已化热，故六脉洪滑，本寒标热，先治其标，本当缓治。", "5431": "初十日尺脉洪数更甚，加：", "5432": "十二日尺脉仍洪，腹痛欲便，便后肛门热痛，原方再服二帖。", "5433": "六月初三日右脉大而数，加黄芩二钱，去川朴。", "5434": "初五日诸症向安，脉亦调适，胃口亦开，以调理脾胃立法。", "5435": "钱三十四岁五月二十九日寒痹，脉弦短涩而紧，由腿上连少腹，痛不可忍，甚至欲厥，兼有痰饮胃痛。", "5436": "六月初一日左脉稍长，仍然紧甚，再服二帖。", "5437": "杨氏二十六岁乙酉正月初七日前曾崩带后得痿痹，病者自疑虚损。询病情寒时轻热时重，正所谓经热则痹，络热则痰者也。再行经有紫有黑，经来时不惟腰腿大痛，少腹亦痛，经亦不调，或多或寡，日数亦然。此不但湿热，且有瘀血。治湿热用汤药，治瘀血用丸药，（左脉浮取弦，沉取宽泛。右脉浮取弦，沉取洪。）汤药用诸痹汤取太阴法，丸药用化症回生丹。", "5438": "王四十六岁寒湿为痹，背痛不能转侧，昼夜不寐，二十余日。两腿拘挛，手不能握，口眼歪斜，烦躁不宁，畏风自汗，脉弦，舌苔白滑，面色昏暗且黄，睛黄，大便闭。先以桂枝、杏仁、苡仁、羌活、广皮、半夏、茯苓、防己、川椒、滑石令得寐；继以前方去川椒、羌活，加白通草、蚕砂、萆薢，得大便。一连七八日均如黑蛋子，服至二十余剂，身半以上稍轻，背足痛甚，于前方去半夏，加附子、片姜黄、地龙、海桐皮。又服十数帖，痛渐止；又去附子、地龙，又服十数帖，足渐伸。后用二妙丸，加云苓、苡仁、萆薢、白术等药收功。", "5439": "何二十六岁手足拘挛，误服桂、附、人参、熟地等补阳，以致面赤，脉洪数，小便闭，身重不能转侧，手不能上至鬓，足蜷曲，丝毫不能移动。细询病情，因大饮酒食肉而然。所谓湿热不攘，大筋软短，小筋弛长，软短为拘，弛长为痿者也。与极苦通小肠，淡渗利膀胱法。", "5440": "周四十二岁两腿紫绛而肿，上起细疮如痱，已三年矣。两腿足酸痛不能立，六脉弦细而紧，窦氏《扁鹊新书》，谓之苏木腿，盖寒湿著痹也。", "5441": "成五十四岁腰间酸软，两腿无力，不能跪拜，间有腰痛，六脉洪大而滑。前医无非补阴，故日重一日。此湿热痿也，与诸痿独取阳明法。", "5442": "赵四十五岁乙酉正月十五日肝郁挟痰饮，肾水上凌心，心悸短气，腹胀胸痹，六脉反沉洪，水极而似火也，与蠲痰饮伐邪，兼降肝逆法。", "5443": "二十日痰饮夹痹，肾水上凌，心惊悸短气，腰脊痹痛，皆太阳所过之地，小便短而腹胀，肚脐突出，是内而脏腑，外而经络，无不痹者。且开太阳之痹，脉洪大，与大青龙合木防己汤法。", "5444": "二十三日外而经络之痹，内而脏腑之痹，行痰开痹，俱不甚应，现在脉洪数，少腹胀，小便短浊而臭。先与开支河，使湿热有出路，再商后法。", "5445": "二十九日痹症夹痰饮，六脉洪大，湿已化热，屡利小便不应，非重用石膏宣肺热不可。诸痹独取太阴也。", "5446": "二月初四日痹症十年，误补三年，以致层层固结，开之非易，石膏用至二斤有余，脉象方小其半，现在少腹胀甚，而小便不畅，腰痛胸痛，邪无出路，必得小便畅行，方有转机。", "5447": "以后脉大而小便不利，用此小便利，去滑石。", "5448": "初五日大用石膏，六脉已小，经谓脉小则病退。盖脉为病之帅，脉退不患病不退，经又谓脉病人不病者死。人病脉不病者生，现在病归下焦血分，其人本有肝郁，暂退下焦血分。", "5449": "初六日脉复洪大，加：", "5450": "丸方：痹症夹痰饮疝瘕，六脉洪大，用诸痹独取太阴法，脉洪大者小，《难经》所谓人病脉不病者生。但脉虽平而瘕胀痹痛未除，议以乌药散退瘕痹之所难退者，以久病在络故也。再以丸药缓通脉络法，脉若复大，仍服前方数帖，见小即止。", "5451": "三月二十四日痹症夹痰饮，脉本洪数，前用辛凉脉减，兼用通络散、瘕丸散亦效，现在六脉中部仍洪，但不数耳。议暂用辛凉宣肺。", "5452": "二十六日诊右脉更大，小便反短，用苦辛淡法，于前方内加：", "5453": "五月初三日大凡腹胀之疾，不责之太阴，即责之厥阴。此症自正月以来，开太阳之药，未有不泄太阴者，他症虽减其半，则尚未除。其故有三：一者病起肝郁；二者肝主疏泄，误补致壅；三者自正月以来，以右脉洪大之故，痹症甚重。治在肺经，经有诸痹独取太阴之明训。兹右脉平而左脉大，不得著于前议，暂与泄厥阴之络，久病在络故也。", "5454": "二十三日左胁痛胀，卧不著席胸亦闷胀，气短，肝脉络胸之故。", "5455": "六月初一日痰饮肝郁，脉弦细，气上冲胸。", "5456": "十五日脉缓，服前方。", "5457": "十六日脉缓甚，服前方。", "5458": "二十七日脉浮，筋骨酸痛，气短，五心烦热，新感暑湿之气，加以辛凉，与三焦。", "5459": "初九日近日阴雨连绵，背痛腹胀不减，二便不爽，非嗳则哕，脉小于前，与宣痹开郁，兼去陈莝。", "5460": "二十一日寒湿发痹，脉缓甚，中有痰饮。", "5461": "二十八日脉弦紧，痰饮痹症症瘕，因燥气而发，脏腑经络俱痹，故肢冷而畏寒也，峻与通阳。", "5462": "十二月初十日痹痛，饮咳，脉弦细。", "5463": "十二日冲气上动畏寒，脉沉细，与桂枝加桂汤法，直伐冲气。", "5464": "十三日大寒节冲气未止，脉反弦紧。于原方内加：", "5465": "服二帖，脉中阳气生动，冲气平，畏寒止，仍然早服化症回生丹一丸，晚服奇经丸三钱。", "5466": "陶三十岁乙酉六月初二日风淫末疾，两手发软，不能持物，脚亦有时而软，脉弦数，治以辛凉。", "5467": "十三日脉稍平，病起本渴，大服姜桂，渴反止者。饮居心下，格拒心火之渴也，仍以蠲饮为主。微恶寒，兼和营卫。", "5468": "谢氏二十五岁癸亥二月二十二日痰饮哮喘，咳嗽声重，有汗，六脉弦细，有七月之孕，与小青龙去麻辛主之。", "5469": "二十四日寒饮误服苦寒坚阴，大用辛温三帖，今日甫能转热，右脉始大，左脉仍弦细，咳嗽反重者，是温药启其封固也。再用温药兼滑痰，痰出自然松快。", "5470": "二十五日右脉已退，病势少减，但寒热汗多胸痹，恐成漏汗，则阳愈虚，饮更难愈。议桂枝加附子，去甘草，以肋胀故也。合栝蒌薤白汤意，通中上之清阳，护表阳为急。", "5471": "僧四十二岁脉双弦而紧，寒也；不欲饮水，寒饮也；喉中痒，病从外感来也；痰清不黏，寒饮也；咳而呕，胃阳衰而寒饮乘之，谓之胃咳也。背恶寒时欲厚衣向火，卫外之阳虚，而寒乘太阳经也。面色淡黄微青，唇色淡白，亦寒也。法当温中阳而护表阳，未便以吐血之后，而用柔润寒凉，小青龙去麻杏，加枳实、广皮、杏仁、生姜汤主之。服此方十数帖而愈。", "5472": "徐二十六岁二月初十日酒客脉弦细而沉，喘满短气，胁连腰痛，有汗，舌白滑而厚，恶风寒，倚息不得卧，此系内水招外风为病，小青龙去麻辛证也。", "5473": "痰饮喘咳，前用小青龙汤，业已见效，但非常服之品，脉迟缓，议外治脾法。", "5474": "皮氏四十八岁甲子十月二十八日痰饮喘咳，左脉浮弦沉紧，自汗，势甚凶危，议小青龙加杏仁、厚朴，去麻、辛。", "5475": "初四日脉现单弦，喘止咳喊，眩冒未宁，再太阴属土，既重且缓，万不能一时速愈。且痰饮五年，岂三五日可了。", "5476": "邵三十八岁十一月十一日脉弦细而沉，咳嗽，倚息不得卧，胸满口渴，小青龙去麻辛法。", "5477": "十三日服小青龙已效，但喉哑知渴，脉见微数，为痰饮欲去，转用辛凉，开提肺气法。", "5478": "颜四十二岁丙寅正月二十四日嗽不欲饮，倚息不得卧，胁痛，自汗，不寐，脉弦缓，议小青龙去麻辛，加杏仁、苡仁，再重加半夏。", "5479": "昆四十二岁正月二十六日饮家眩冒，用白术泽泻汤法，脉洪滑而沉。", "5480": "二月初十日脉沉微数。", "5481": "陶氏三十六岁二月二十五日痰饮脉洪数，咳嗽，倚息不得卧，有汗，胸痹。", "5482": "佟氏七十五岁脉沉细而不调，喘满短气，心悸气上阻胸，咳嗽倚息不得卧，乃中焦痰饮，下焦浊饮为患。年老全赖阳气生活，兹阴气阴邪上僭如此，何以克当。勉与通阳降浊法。", "5483": "陈四十三岁正月二十五日病由疟邪伤胃，土虚邪实，六脉俱结，且有块痰，寒滞经脉隧道，病有三虚一实者，先治其实，后治其虚。", "5484": "二十八日脊痛，痹也。右腿偏软，痿也。咳嗽而喘，支饮射肺也。日久不愈，皆误补用熟地等壅塞隧道之故，脉洪。", "5485": "二月初九日痹夹痰饮，与开痹蠲饮法，现在痹解而饮未除，脉之洪者减，病减者减其治。", "5486": "六月初五日暑湿行令，脉弦细，胃不开，渴而小便短，用渴者与猪苓汤法。", "5487": "初六日痰饮之质，冒暑欲呕，六脉俱弦，虽渴甚，难用寒凉，与局方消暑丸法。", "5488": "十四日脉沉细，胃不开，减：猪苓（三钱）泽泻（三钱）飞滑石（三钱）加藿香梗（三钱）广皮（三钱）益智仁（三钱）", "5489": "十七日头胀胸闷，脉缓气歉，暑必夹湿也。", "5490": "二十五日六脉阳微，暑湿之余，小便白浊，与分利法。", "5491": "九月二十一日痰饮喘咳，脉双弦，与小青龙法。", "5492": "二十四日痰饮胁动而喘渴，是谓悬饮。悬饮者，水在肝也，脉弦数。水在肝内者，外风未净也。", "5493": "二十七日痰饮胁痛而喘咳，是谓悬饮，水在肝也，脉弦数。", "5494": "初六日口水减，牙痛，脉如故，再服四帖。", "5495": "吴五十七岁六脉洪数，右寸独大，酒客痰多，肺热之至。", "5496": "二十日脉洪数，右大于左，喉哑痰多，戒油腻。", "5497": "八月初四日右寸脉独大，金实无声，已效而未全愈，照前方再服三剂。前后共服三十余帖，计石膏三百数十两。", "5498": "严三十九岁五月初二日六脉弦细短涩，吐血三年不愈，兼有痰饮咳嗽，五更出汗。经谓阳络伤则血上溢。要知络之所以伤者，有寒有热，并非人之有络，只许阳火伤之，不许寒水伤之也。今人见血投凉，见血补阴，为医士一大痼疾。医士之疾不愈，安望病家之病愈哉。此症阳欲亡矣，已难数治，勉照脉症立方。", "5499": "初六日据云饮食已增，午后五心烦热如故，脉和缓，诸病必究眠食，得谷者昌，方无可转。至午后之热，方即甘温除大热法也。因脉稍和缓，去干姜炭。", "5500": "十三日前后共服过十帖，汗敛食增，血亦不吐，头中发空，得甜食则咳减，中气虚也。加甘草三钱以补中气，再服四帖，以其脉仍紧也。前后共服十四帖，诸症向安。惟脉之弦紧如故，咳甚则欲呕，于原方去五味，减甘草，再服四帖。", "5501": "二十五日脉弦细如故，咳嗽日减，夜甚阳微，阴盛可知，午后身热已减，惟食后反觉嘈杂，胸中有水状，少时即平，于原方加：", "5502": "三十日汗停嗽减，五心烦热亦减，脉弦数，夜间咳甚，服热药反不渴，饮尚重也。病痰饮者，冬夏难治。", "5503": "六月初四日前方已服四帖，脉弦紧不数，仍不知渴，于前方加：", "5504": "初八日脉弦紧如故，呛咳如故，舌苔白滑，加桂枝二钱，再加干姜二钱。", "5505": "十二日脉之短涩退而弦细如故，痰饮仍重，再加桂枝二钱，干姜二钱，茯苓三钱，以化饮。", "5506": "十七日夜咳已止，是其佳处，咳来日减，亦是最好。左脉沉细，右脉弦紧，饮未尽除，至遍身骨痛，久病之故。古人云劳者温之，甘温调营卫而复胃气，气旺进食，久久自愈，病减者减其治。", "5507": "陈五十一岁五月初十日人尚未老，阳痿多年，眩冒昏迷，胸中如伤油腻状，饮水多则胃不快，此伏饮眩冒状也。先与白术泽泻汤逐其饮，再以缓治湿热之阳痿。岂有六脉俱弦细，而恣用熟地久服六味之理哉。", "5508": "十一日诸窍不和，六脉纯阴，皆痰阴为腻补药所闭，昨用半夏汤，已得寐而未熟，再服前方三帖，续用小青龙去表药，加广皮、枳实，以和其饮。盖现在面色光亮，水主明也。六脉有阴无阳，饮为阴邪故也。左脉弦甚，经谓单弦，饮澼也。有一症必有一症之色脉，何医者盲无所知，不知伊一生所学何事，宁不愧死。", "5509": "十八日胃之所以不和者，土恶湿而阳困也。昨日纯刚大燥，以复胃阳，今诊脉象较前生动，胃阳已有生动之机，但小便白浊，湿气尚未畅行，胃终不得和也。与开太阳阖阳明法。", "5510": "高五十二岁乙酉五月十六日脉弦痰饮喘咳，与小青龙去麻辛，加广皮、枳实。", "5511": "董五十四岁五月二十七日脉沉细弦弱，咳嗽夜甚，久而不愈，饮也。最忌补阴，补阴必死。以饮为阴邪，脉为阴脉也，经曰无实。", "5512": "十九日寒热已止，脉微弱，去蔻仁、青蒿，加桂枝、干姜，以治其咳。", "5513": "二十二日咳减寒热止，胃开，嗽未尽除，脉尚细小，效不更方，服至不咳为度。", "5514": "周二十二岁正月初七日六脉弦紧，右脉沉取洪大，先从腰以上肿例。舌白滑喘而咳无汗，从溢饮例之大青龙汤，去甘药，为其重而滞也。", "5515": "十一日溢饮，脉紧，无汗，喘咳，浮肿，昨用大青龙汗出，肿消，喘咳减，与开太阳阖阳明法。", "5516": "陈七十六岁正月初十日悬饮脉弦，左胁不快，为水在肝法，当用十枣汤。近八旬之老人，难任药力，与两和肝胃可也。", "5517": "二十三日脉结加：杏泥（六钱）", "5518": "觉罗六十二岁壬戌正月十三酒客痰饮哮喘，脉弦紧数，急与小青龙去麻辛，加枳实橘皮汤不应。右胁痛甚，此悬饮也，故与治支饮之小青龙不应，应与十枣汤。以十枣大峻，降用控涎丹。", "5519": "汪室女伏暑夹痰饮，与三仁汤重加半夏、广皮，屡效而热不退。痰不除，右脉微结，中有块痰，堵塞隧道。因延郏芷谷兄针中泉穴，紫血出后，继咳老痰二口。以后用药无不见效，半月后伏暑痰饮皆愈矣。", "5520": "钱三十二岁甲子八月初十日咳嗽胃中停水，与小青龙去麻辛，重加枳实、广皮五帖，已愈八九。因回母家为父祝寿，大开酒肉。其父亦时医也，性喜用人参，爱其女，遂用六君子汤，服关东参数十帖。将近一年，胃中积水胀而且痛。又延其父治之，所用之药，大抵不出守补中焦之外。治愈胀而愈痛，以致胸高不可以俯，夜坐不可以卧，已数日不食。其翁见势已急，力辞其父，延余治之。余视其目欲努出，面色青黄，胸大胀痛不可忍，六脉弦急七八至之多，余曰：势急矣，断非缓药所能救。因服巴霜三分，下黑水将近一桶，势稍平，以和脾胃药调之。三四日后渐平，胃大开，于是吃羊肉饺三十二枚，胃中大痛一昼夜。又用巴霜一分五厘，下后痛止。严禁鱼肉，一月而安。", "5521": "赵四十六岁正月三十日太阳痹则腰脊痛，或左或右，风胜则引也。或喘或不喘者，中焦流饮，上泛则喘，不泛则不喘也。切戒猪肉生冷，与一切补药，周年可愈。六脉洪大已极，石膏用少，万不见效，命且难保。", "5522": "二十九日右脉洪大已减，右膏只用一两。", "5523": "二十二至三十日、四月初一至初五日自淮安复至绍兴，又诊得洪大之脉，较前已减七八，然较之平脉，仍大而有力。现在小便赤浊，阴痿，牙缝臭味复出。痹痛虽止，阳明太阳二经湿热未净，太阴化气未复。", "5524": "十九日脉渐退，减石膏至二两，加：", "5525": "十一日前因风寒夹饮之故，用小青龙法。现在风寒解而饮未除，脉复洪大，仍与大青龙与木防己汤合法，兼治饮与痹也。", "5526": "初七日右脉洪数，六腑不和，食后恶心，二便不爽，暑湿所干之故，议通宣三焦。", "5527": "十七日停饮兼痹，脉洪，向用石膏，无不见效。数日前因食后倒饱，脉不大，石膏已近三十斤之多，转用温醒脾阳方法，丝毫不应，水之蓄聚如故，跗肿不消，胃反不开，右脉复洪大有力，小便短。思天下无肺者无溺，肺寒者溺短，热者溺亦短，仍用石膏凉肺胃。", "5528": "九月初四日脉之洪大不减，加：", "5529": "服石膏至五十斤之多，而脉犹浮洪，千古未有如是之顽病。皆误下伤正于前，误补留邪于后之累。今日去补阳明药，盖阳明之脉大也。", "5530": "十三日脉洪滑，痰饮未除，晨起微喘，足跗肿未消尽，余有原案。", "5531": "十五日气已不急，去葶苈；右脉仍浮洪，加石膏一倍，成一斤。", "5532": "十六日气急者得葶苈而止，右脉之洪大者，得石膏一斤大减，病减者减其制，但仍滑数，加行痰饮。", "5533": "十八日脉渐小，减：", "5534": "二十日脉洪数，加石膏八两，成十二两。", "5535": "二十二日脉减，减石膏六两，加：", "5536": "脉之洪大者，得石膏一斤大减，病减者减其制，脉复洪大有力，再酌加其制。", "5537": "妙应丸方，《金匮》谓凡病至其年月日时复发者，当下之。此症痰饮兼痹，自正月服药至十月，石膏将近百斤之多，虽无不见效，究未拔除病根。左胁间漉漉有声，不时呕咳，此水在肝也。《金匮》谓水在肝，十枣汤主之；又谓偏弦饮澥；又谓咳家之脉弦为有水，十枣汤主之；又谓咳家一百日，至一岁不死者，十枣汤主之。合而观之，此症当用十枣无疑。但十枣太峻，南人胆怯，未敢骤用，降用妙应丸续续下之，庶无差忒也。", "5538": "十二日脉仍洪大有力。", "5539": "右脉洪数，本有饮聚，小便不长。", "5540": "十一月十七日痰饮喘咳，右脉洪，左关独浮，与建金制木法。", "5541": "二十七日洪大之脉已退，惟两关独浮，右大于左而兼实，木陷入土。与两和肝胃，兼开膀胱，小便短而水易停故也。", "5542": "十二月初一日数日不服石膏，右脉复洪数，左关之独浮者，亦未十分清净。与金木同治法。", "5543": "以后凡右脉大者，服此小即停止。", "5544": "十一日于前方去桂枝、广皮，脉不肯小故也，服至十五日止。", "5545": "丙戌正月十四日《金匮》谓心下坚大如盘，水饮所作，枳术丸主之。兹虽不坚大而水停不去，病情相合，再脉洪大，洪大甚则喘发，最宜服石膏、杏仁。但石膏不可入丸方，议用橘半枳术丸，脉小时用开水下，脉大时暂用石膏汤送下，喘发加杏仁，脉复小，不用石膏。", "5546": "陈四十六岁病由疟邪伤胃，土虚则水泛，以致喘而肢软，正虚邪实，六脉俱结，且有块痰，塞滞经脉隧道。病有三虚一实者，先治其实，后治其虚。", "5547": "初六日脊病，痹也。右腿偏软，痿也。咳嗽而喘，支饮射肺也。日久不愈，皆误用熟地等补塞隧道之故。脉洪。", "5548": "二月初二日痹夹痰饮，与开痹蠲饮法，现在痹解而饮未除，脉之洪大者减，病减者减其制。", "5549": "二月初五日暑湿行令，脉弦细，胃不开，渴而小便短，用渴者与猪苓汤法。", "5550": "初六日痰饮之质，冒暑欲呕，六脉俱弦，虽渴甚，难用寒凉，与局方消暑丸法。", "5551": "十四日脉沉细，胃不开，减，猪苓（三钱）泽泻（三钱）滑石（六钱）加藿梗（三钱）广皮（三钱）益智仁（三钱）", "5552": "十七日头胀胸闷，脉缓气歉，暑必夹湿也。", "5553": "二十五日六脉阳微，暑湿之余，小便白浊，与分利法。", "5554": "九月二十一日痰饮喘咳脉弦，与小青龙法。", "5555": "二十四日痰饮胁痛而喘咳，是谓悬饮。悬饮者，水在肝也，脉弦数。身热者，外风未净也。", "5556": "二十七日痰饮胁痛而喘咳，是谓悬饮。悬饮者，水在肝也，脉弦数。", "5557": "十一月初六日痰饮，脉沉弦，有微喘之意，与小青龙去麻辛。", "5558": "十二月初七日内饮招外风为病，喘咳，脉弦缓，虽头痛恶寒，能大食，只有风而无寒，用小青龙去麻黄，减细辛，兼用桂枝汤啜稀粥令微汗法。", "5559": "初十日脉不浮，外感已解，但弦细，而畏冷，中阳虚也。去细辛。", "5560": "十三日脉双弦，咳而呕，胃咳也。", "5561": "正月十六日脉沉弦而缓，饮居右胁，呕痰由肋痛外至脊背恶寒，由厥阴内犯阳明，外犯太阳也。与逐胁下之饮法。", "5562": "王氏五十六岁癸亥三月初八日初起喉痹，为快利药所伤，致成肺痈。胸中痛，口中燥，喉痹仍未痊，不食不寐。痰气腥臭。已有成脓之象。脉短而数，寒热，且移热于大肠而泄泻，难愈之证。勉与急急开提肺气，议千金苇茎汤，与甘桔合法。", "5563": "朱咏齐五十余岁以己卯年二月初受风，与桂枝汤一帖，风解，胆怯不敢去厚衣，因而汗多。初四五日又受风温，口渴思凉，脉洪数。先与辛凉轻剂不解，脉又大，汗更多，口更渴，身更热。因与辛寒重剂石膏等一帖，身凉渴止脉静，仍胆怯不去厚衣。初十日当大差坐夜起五更，衣更厚，途间不敢去皮衣，以致重亡津液而成肺痈，与苇茎汤二三两一帖。服至五七日不应，脓成臭极，加苦苈葶子五钱，脓始退，未能十分净尽。后十日又发，脓又成，吐如绿豆汁浓臭，每吐一碗余。又于前方加葶苈三钱，服二帖方平复，以补胃逐痰饮收功。再其人色白体肥，夙有痰饮，未病之年前秋冬两季，以在上书房行走，早起恐寒，误服俗传药酒方，本不嗜酒，每早强饮数小杯，次年患此恙之由也。", "5564": "刘三十二岁脉弦而长，木气太旺，与君火结而成喉痹。", "5565": "酒客脉弦数，与苦药清酒中之湿，即于前方内加：", "5566": "灵乙丑六月二十六日舌苔边白中浊，喉肿而痛，头晕，身热，脉数，疠气所干。切戒谷食，急开关窍，用时时轻扬法。", "5567": "二十九日喉痛虽止，舌浊未除，脉仍微数，则其中之湿可知。按：《灵枢经》五脏温病，以舌苔专属之肺，故药方一以宣通肺气为主，盖气化则湿化，而火亦无依矣。", "5568": "王氏三十八岁乙酉五月初二日六脉沉弦而细，纯阴之象，喉痛足痹宜温。", "5569": "满氏三十五岁面色青黄，呼吸定息，脉再至而弦紧，食减，经不行，腹中有块二三枚，长三四寸，肝厥无五日不发，喉痛十数年不休。向来所服之方，非寒凉，即妇科地芍药等，以致历年沉困不休，病势日重，十二年不孕矣。与苦辛热法，急回真阳，或者可救。", "5570": "前方服七帖，六脉将进至四至，服通补奇经丸一料，半年后受孕。", "5571": "吴二十五岁癸亥七月十六日但寒不热，似乎牝疟，然渴甚脉数，皮肤扪之亦热，乃伏暑内发，新凉外加，热未透出之故。仍用苦辛寒法。加以升提。", "5572": "但寒不热之疟，昨用升提，已出阳分，渴甚，脉洪数甚，热反多。昨云热邪深伏，未曾透出，不得作真牝疟者，非虚语也。用苦辛寒重剂。", "5573": "佟氏四十岁少阴三疟，二年不愈，寒多热少。脉弦细，阳微，损及八脉，通补奇经丸四两，服完全愈。", "5574": "萧三十三岁少阴三疟，久而不愈，六脉弦紧，形寒嗜卧，发时口不知味，不渴，肾气上泛，面目黧黑，与扶阳汤法。", "5575": "郑五十五岁四月十九日脉双弦，伏暑成疟，间二日一至，舌苔白滑，热多寒少，十月之久不止，邪入已深极，难速出，且与通宣三焦，使邪有出路，勿得骤补。", "5576": "初四日脉紧汗多，加：", "5577": "初六日脉已活动，色已毕，寒大减，热亦少减，共计已减其半。汗至足底，时已早至八刻，议去青蒿，加黄芩一钱。舌苔虽减而仍白，余药如故，再服四帖。", "5578": "十四日三疟与宣三焦，右脉稍大，热多汗多，舌苔之白滑虽薄，而未尽化，湿中生热，不能骤补，与两清湿热。", "5579": "二十九日病又减，去黄连，加益智仁三钱，以其脉大而尚紧也，仍系六日服三帖。", "5580": "十二日三疟与宣化三焦，十退其九，白苔尚未尽退。今日诊脉，弦中兼缓，气来至缓，是阳气未充。议于前方退苦寒，进辛温。", "5581": "二十二日左脉弦紧，右大而缓，舌白未化，疟虽止而余湿未消，此方仍服。去：", "5582": "七月初二日四疟已止，胃已开，脉已回阳，与平补中焦。", "5583": "丸方疟后六脉俱弦微数，与脾肾双补法。", "5584": "高十六岁乙酉六月十六日间三疟，脉弦，暑邪深入矣。", "5585": "十八日诊脉数热，重加：", "5586": "朱三十八岁但寒不热，舌苔白滑而厚三四日，灰黑而滑五六日，黑滑可畏，脉沉弦而紧。太阴湿疟，与牝疟相参，但牝疟表寒重，此则偏于在里之寒湿重也。初起三日，用桂枝、草果、苍术、黄芩、茯苓、苡仁、广皮、猪苓、泽泻。三四日加附子，五六日又加草果、苍术分量。再加生姜，舌苔始微化黄，恶寒渐减。服至十二三日，舌苔恶寒始退。愈后峻补脾肾两阳，然后收功。", "5587": "初五日左脉沉紧，即于前方加：", "5588": "初六日脉洪大而数，经络痛虽解而未尽除，痹也；小便白而浊，湿也。", "5589": "初九日昨服开肺与大肠痹法，湿滞已下，小便亦清，但大便与瘼中微有血迹，证从寒湿化热而来，未便即用柔药以清血分。今日且与宣行腑阳，右脉仍见数大，可加苦药。如明日血分未清，再清血分未迟。", "5590": "十七日中风漏汗，兼之肾水上凌心，心悸腹痛，昨用桂枝加附子汤，诸症悉退。今左脉沉缓。右脉滑，表虽清而浊阴未退。议苓桂伐肾邪，归茴温冲脉，吴萸、半夏、生姜两和肝胃，白芍以收阴气，合桂枝而调营卫，加黄芩以清风化之热。合诸药为苦辛通法，此外感之余，兼有下焦里证之治法也。", "5591": "十九日脉缓浊阴久居，兼有滞物续下，用药仍不外苦辛通法，稍加推荡之品，因其势而导之。大意通补阳明之阳，正所以驱浊阴之阴。若其人阳明本旺，胃阴自能下降，六腑通调，浊阴何以能聚，再胃旺自能坐镇中州，浊阴何以能越胃而上攻心下，反复推求，病情自见。", "5592": "二十二日凡痛胀滞下，必用苦辛通法，兼护阳明，固不待言。前法业已见效，细询病已十余年，以半产后得之，误用壅补成之。按久病在络再痛胀偏左下至少腹板著，其中必有瘀滞，非纯用汤药所能成功。盖汤者荡也，条肠胃和通百脉，固其所长。至于细雕密镂，缓行横络，是其所短，非兼用化症回生丹缓通不可。且阳剂过重，有症散为蛊之虞，不得不思患预防也。", "5593": "吴氏二十三岁二月二十一头项强痛而恶寒，脉缓有汗，太阳中风，主以桂枝汤。", "5594": "二十五日服前方已，脉静身凉，不肯避风，因而复中，脉紧无汗，用麻黄汤法。", "5595": "唐五十九岁三月十六日头痛恶寒，脉紧，言蹇，肢冷，舌色淡，太阳中风，虽系季春，天气早间阴晦，雨气甚寒，以桂枝二麻黄一法。", "5596": "二十日中风表解后，言蹇减食则汗头行痛，舌白滑，脉微紧，宜桂枝加附子汤，除风实表护阳。", "5597": "二十一日表解后复中，恶寒胸结，舌苔厚而白，脉迟紧里急。", "5598": "二十六日太阳中风，误下胸痞，四五日太阳症未罢。昨用太阳证仍在例之桂枝法，今日恶寒已罢，头目已清，惟胸痞特甚，不渴舌白而壮热，泄泻稀水频仍。仲景法云病发于阳而误下成胸痞者，泻心汤主之。今用其法，再经谓脉不动数者为不传经也。昨日已动数太甚，断无不传之理，可畏在此。", "5599": "二十七日太阳中风误下，前日先与解外，昨日太阳证罢，即泻胸痞。今日胸痞解，惟自利不渴，舌灰白，脉沉数。经谓自利不渴者，属太阴也。太阴宜温，但理中之甘草，人参，恐不合拍，议用其法而不用其方。", "5600": "二十八日太阳中风，先与解外，外解已即与泻误下之胸痞，痞解而现自利不渴之太阴证。今日口不渴而利止，是由阴出阳也，脉亦顿小其半。古云脉小则病退。但仍沉数，身犹热而气粗不寐，陷下之余邪不净。仲景《伤寒论》谓真阴已虚，阳邪尚盛之不寐，用阿胶鸡子黄汤。按：此汤重用芩连。议用甘草泻心法。", "5601": "二十九日脉沉数，阴经热阳经不热，是陷下之余邪在里也。气不伸而哕，哕者伤寒门中之大忌也，皆误下之故。议少用丁香柿蒂汤法，加芩、连以彻里热，疏逆气。", "5602": "初一日误下成胸痞自利，两用泻心，胸痞自利俱止。但陷下之邪，与受伤之胃气，搏而成哕。昨用丁香柿蒂汤去人参加芩连，方虽易，仍不外仲圣苦辛通降之法。病者畏而不服，今日哕不止而左脉加进，勉与仲圣哕门中之橘皮竹茹汤，其力量降前方数等矣。所以如此用者，病多一日，则气虚一日，仲圣于小柴胡汤中即用人参，况误下中虚者乎。", "5603": "十九日误下之陷证，哕而喘，昨连与橘皮竹茹汤，一面补中，一面宣邪。兹已邪溃诸恶候如失，脉亦渐平，但其人中气受伤不浅，议与小建中汤加橘皮、半夏，小小建立中气，调和营卫，兼宣胃阳，令能进食安眠。", "5604": "初六日病后两服建中，胃阳已复，脾阳不醒，何以知之？安眠进食，是胃阳起。舌起白滑苔，小便短，大便不解，脉乍数，是脾阳未醒，而上蒸于肺也。议与宣利三焦法，以醒脾阳。", "5605": "初八日大小便已利，脉仍洪数，舌白滑苔未除，仍宜苦辛淡法，转运脾阳，宣行湿热。", "5606": "十一日脉仍沉数，舌苔反白滑，仍宜建中行湿以除伏邪。湿最伤气，非湿去气不得健，与急劫湿法。", "5607": "吴五十六岁十一月十二日内热外寒，兼发痰饮，喉哑，咳嗽，痰多，头痛，恶寒，脉浮，与麻杏石甘汤。", "5608": "十四日肺脉独浮，去：", "5609": "十七日脉浮，喉哑，咳嗽，痰多。", "5610": "二十三日脉浮，喉哑，咳嗽，痰多，内饮招外风为病，与大青龙法。", "5611": "二十七日喉复哑，脉洪数，小便已长，前方去木通，加：", "5612": "赵十三岁十一月二十九日头痛，脉浮，弦不甚紧，无汗，与杏苏法。", "5613": "十三日阴未化，阳自不复，且心下坚大如盘，脉如故，前方再服。", "5614": "姚四十八岁乙酉四月二十一日燥金感后，所伤者阳气，何得以大剂熟地补阴。久久补之，阳气困顿，无怪乎不能食而呕矣。六脉弦紧，岂不知脉双弦者寒乎。", "5615": "二十一日复感燥气，呕而欲泻，于前方内去甘药加分量自愈。六脉弦细如丝，阳微之极。", "5616": "二十七日诸症皆效，脉稍有神，于原方内去吴萸、丁香之刚燥，加苡仁之平淡，阳明从中治也。", "5617": "李四十六岁乙酉四月十六日胃痛胁痛，或呕酸水，多年不愈，现在六脉弦紧，皆起初感燥金之气，金来克木，木受病，未有不克土者。土受病之由来，则自金克木始也，此等由外感而延及内伤者，自唐以后无闻焉。议变胃而受胃变法，即用火以克金也。又久病在络法：", "5618": "五月初二日现在胃痛胁痛吐酸之证不发，其六脉弦紧不变，是胸中绝少太和之气，议转方用温平，刚燥不可以久任也。", "5619": "十一日诊脉已回阳，去干姜，减桂枝之半。", "5620": "二十四日复诊脉仍紧，原方加：", "5621": "余五十二岁五月初二日胃痛胁痛，脉双弦，午后更甚者，阳邪自旺于阴分也。", "5622": "十七日复诊病稍减，脉仍紧，去：", "5623": "二十四日脉之紧者稍和，腹痛已止，惟头晕不寐，且与和胃令寐，再商后法。", "5624": "谭四十七岁五月初二日感受金凉，胸痹头痛，脉弦细而紧。", "5625": "十八日燥气虽化，六脉俱弦，舌苔白滑，用阳明从中治法，与苦辛淡法，最忌酸甘。", "5626": "二十一日脉仍弦紧，热药难退，咳嗽减，效不更方。右胁微痛。加：", "5627": "二十三日右胁微痛，脉弦紧如故，加：", "5628": "二十六日胁痛咳嗽皆止，痰尚多，脉弦未和，于前方内去香附苏子霜降香旋覆花加：", "5629": "桂枝（四钱）干姜（二钱半）以充其阳气，行痰饮，和弦脉。", "5630": "主治中燥吐泻腹痛，甚则四肢厥逆转筋，骽痛肢麻，起卧不安，烦躁不宁，再甚则六脉全无。阴毒发斑疝症等症，并一切凝寒痼冷积聚，寒轻者不可多服，寒重者不可少服，以愈为度。非实在纯受燥湿寒三气阴邪者不可服。", "5631": "二十五日燥气腹痛虽止，当脐仍坚，按之微痛，舌苔微黄而滑，周身筋骨痛，脉缓，阳明之上中见太阳，当与阳明从中治例。", "5632": "二十六日脉小于前，身痛已止，六脉未和，舌黄滑苔。", "5633": "初十日六脉俱弦，胃口不开，腹胀肢倦，宜通六腑，即劳者温之之法也。", "5634": "张女十五岁燥金之气，直中入里，六脉全无，僵卧如死，四肢逆冷，已过肘膝，骽痛转筋，与通脉四逆汤加川椒、吴萸、丁香一大剂。厥回脉出，一昼夜，次日以食粥太早，复中如前，脉复厥，体又死去矣。仍用前方，重加温药一剂，厥回其半。又二帖而无活，后以补阳收功。", "5635": "顾五十岁直中燥气，呕少泻多，四肢厥逆，无脉，目开，无语，睛不转，与通脉四逆汤。加：", "5636": "一帖而效，三帖脉渐复，重与补阳而愈。", "5637": "杨室女五十岁胁痛，心烦懊𢙐，拘急肢冷，脉弦细而紧。欲坐不得坐，欲立不得立，欲卧不得卧，随坐即欲立，刚立又欲坐，坐又不安。一刻较一刻脉渐小，立刻要脱。与霹雳散不住灌之，计二时，服散约计四两而稍定，后与两和脾胃而全安。", "5638": "郑二十六岁先是三月初九日，得太阳中风，与桂枝汤已愈。十二日晚已卧，下身有微汗，因厨房不戒于火，只穿小汗褂一件，未著袜，出外救火，火熄复卧，觉身微热恶寒，腹中胀痛，脉弦数，与桂枝柴胡各半汤，汗出稍轻，究不能解。以后外虽化热，面赤汗多如温病状，以当脐之痛未休，舌白不燥，断不敢用辛凉，而辛温之药，或进或退，十日不解。至二十四日反重用温热，佐以黄连三钱，次日表证里证，一齐俱解如失。后与调理脾胃两阳而安。", "5639": "多十六岁燥淫表里俱病，面赤身热，舌黄燥渴，六脉洪数而紧，大便闭，小便短，通体全似火证，只有当脐痛拒按。此为阳中之阴，乃为真阴，与苦热芳香，一剂而热退，减轻分量，三帖而病全失矣。", "5640": "温癸亥二月二十九日六十日之幼孩，痉已二十余日，现在脉不数，额上凉汗，并无外感可知，乃杂药乱投，致伤脾胃。故乳食有不化之形，恐成柔痉，俗所谓慢脾风。议护中焦，乃实土制风法，又肝苦急，急食甘以缓之义也。", "5641": "三月初一日赤子不赤而刮白兼青，脉迟凉汗，舌苔白滑而厚，食物不化，洞泄者必中寒。按：痉必因于湿，古所谓柔痉是也。议从中治。经谓有者求之，无者求之。此症全无风火之象，纯然虚寒，乳中之湿不化，土愈虚则肝中内风愈动，若不崇土而惟肝是求，恐日见穷蹴矣。", "5642": "初七日脉仍不数，大便犹溏，但舌苔微黄，神气渐复，不似前虚寒太甚之象，宜退刚药，少进柔药。医经谓上守神，粗守形，兵法谓见可而进，知难而退，此之谓也。", "5643": "张十三岁乙酉六月初三日脉沉细而弱，舌苔白，滑幼童体，厚纯然湿邪致，痉一年有余。", "5644": "十六日脉至沉至细至缓，舌白滑甚，湿气太重，故效而不愈。于前方中加劫湿而通补脾阳之草果，调和营卫之桂枝、白芍、甘草。", "5645": "二十一日痉症脉沉细，舌白滑，与湿淡法，发来渐稀，未得除根，于前方内去刚燥，加化痰。", "5646": "二十五日服前方四帖已效，舌苔仍然白滑，六脉阳微，照前方再服四帖。", "5647": "七月初九日前方又服九帖，痉症只发一次甚轻，已不呕吐，痰尚多，脉甚小，照前方再服。", "5648": "陈十五岁乙丑六月二十五日病久阴伤已极，骨瘦如柴，又加卒然中暑，中热气，舌绛芒刺，唇干液涸，无怪乎痉厥神昏，十指蠕动，危险之至。以脉尚浮弦而芤，勉与一面大队填阴，兼咸以止厥法。先与紫雪丹二钱，凉水和服，共服六钱。", "5649": "七月初一日邪少虚多，用复脉已当，但舌上黑苔未化，宿粪未见，兼加润法。", "5650": "初五日服前药五帖，见宿粪碗许，黑苔已化，但神识尚未十分清楚，用三加复脉加犀角，即于三甲复脉汤内，加：", "5651": "陈三岁九月十六日燥气化火，壮热，舌黄，脉数，瘛疭而厥，法宜清凉解肌，切忌发表。", "5652": "岳八个月六月二十八日未及岁之儿，瘟毒头肿，瘛疭而厥，壮热气促，脉及数大。恐真阴不胜阳邪，先以普济消毒饮宣毒外出，必去升麻、柴胡之直升少阳阳明者，加犀角、羚羊、泻心胆之热。", "5653": "吴三岁六月初九日辰刻以跌扑惊后瘛疭，至戌正始醒，醒后身大热，口渴，脉数，舌无苔，用复脉汤六帖。热退脉静，又服二帖而安。", "5654": "十三日热退脉平，以调理脾胃为主。", "5655": "继男十二月十四日脉大浮取弦数，脾虚食滞，疳疾将成，大便频仍，面肿腹大，与温宣中焦法。", "5656": "二十日脾虚火衰，则食物有不化之形，肝肾与冲脉伏寒，怒甚则疝痛。", "5657": "张男八个月泄泻四五日，暑邪深入下焦，头热如火，手冷如冰，谓之暑厥。羸瘦难堪，脉迟紧，未必得愈，姑立方以救之。先与紫雪丹五分，三次服。", "5658": "孟十五岁八月初八日伏暑泄泻，加以停食，欲泻腹痛，泻后痛减，防成滞下，与五苓散加消食，脉细弦而缓。", "5659": "刘十七岁乙酉五月二十四日三月间春温，呛咳见吐，现在六脉弦细，五更丑寅卯时，单声咳嗽甚，谓之木扣金，鸣风本生于木也。议辛甘化风，甘凉柔木。", "5660": "二十八日咳嗽减，食加，脉犹洪数，左大于右。效不更方，再服四五帖。", "5661": "六月初二日木扣金鸣，与柔肝清肺已效，左脉洪数已减，与前方去气分辛药，加甘润。", "5662": "吴二十岁甲子四月二十四日六脉弦劲，有阴无阳，但嗽无痰，且清上焦气分。", "5663": "陈四十岁丙戌正月十三日咳嗽起于前年九月，夏伤于湿，伏暑遇新凉而发之咳，症本不大，后因误补封固，邪已难出。又用桑皮末用地骨引邪入肾。按肾为封藏之脏，误入者永难再出矣。身热得补药汗解，而足心之热总不解，是其确证也。现在咳而呕，六脉弦细而数，阴阳两虚也。勉照胃咳方法，先能得谷，建立中焦，假如胃旺，或有生机。常吐血一二口，中有瘀滞，亦系久病络伤，季胁作痛，肝经部分应加宣络降气。", "5664": "陈十六岁少年而体质本弱，六脉弦细而软，五更咳嗽，时而吐血，应照阳虚夹饮吐血论治。又劳者温之治法，与小建中汤，加茯苓、半夏。", "5665": "赵氏五十五岁乙丑三月十八日六脉弦而迟，沉部有，浮部无，巅顶痛甚，下连太阳，阳虚内风眩动之故。", "5666": "陈三十五岁乙丑十月二十二日少阳风动，又袭外风为病，头偏左痛，左脉浮弦而数，大于右脉一倍，最有损一目之弊。议急清胆络之热，用辛甘化风方法。", "5667": "二十七日复诊症小效，脉尚仍旧，照前清少阳胆络方，再服二三帖，俟大效后再议。", "5668": "五月初二日此时无扁豆花为引，改用鲜荷叶边煎汤为引亦可。少阳络热，误用峻补阳气，以致头目左半麻木发痒，耳后痈肿，发为马刀。现在六脉沉洪而数，头目中风火相扇，前用羚羊角散法，虽见小效，而不能大愈。议加一煎方，暂清脑户之风热，其散方仍用勿停。", "5669": "十二日偏头痛系少阳胆络病，医者误认为虚，而用鹿茸等峻补其阳，以致将少阳之热，移于阳明部分，项肿牙痛，半边头脸肿痛，目白睛血赤，且闭不得开，如温毒状，舌苔红黄，六脉沉数有力。议与代赈普济散，急急两清少阳阳明之热毒。", "5670": "十六日舌黄更甚，脉犹数，肿未全消，目白睛赤缕，自下而上，其名曰倒垂帘，治在阳明，不比自上而下者，治在太阳也。", "5671": "二十三日经谓脉有独大独小，独浮独沉，斯病之所在也。兹左关独大独浮，胆阳太旺，清胆络之药，已服过数十帖之多，而胆脉尚如是之旺。络药清轻上浮，服至何日是了？议胆无出路，借小肠以为出路，小肠火腑，非苦不通，暂与极苦下夺法。然此等药可暂而不可久，恐化燥也。", "5672": "二十六日前方服二帖，左关独大独浮之脉已平。续服羚羊角散一天，代赈普济散一天，目之赤缕大退，其耳后之马刀，坚硬未消。仍服代赈普济散，日四五次。", "5673": "七月初一日脉沉数，马刀之坚结未消，少阳阳明经脉受毒之处，犹然牵拉板滞。议外面改用水仙膏敷患处，每日早服羚羊角散一帖，已午后服代赈普济散四包。", "5674": "初九日服前药喉咙较前清亮，舌苔之黄浊，去其大半，脉渐小仍数，里症日轻，是大佳处。外症以水仙膏拔出黄疮少许，毒气仍未化透，仍须急急再敷，务斯拔尽方妙。至于见功迟缓，乃前此误用峻补之累，速速解此重围，非旦晚可了。只好宁耐性情，宽限令其自化，太紧恐致过刚则折之虞。前羚角散，每日午前服一帖，午后服代赈散四包，分四次，再以二三包煎汤漱口，以护牙齿。", "5675": "十七日数日大便不爽，左脉关部复浮，疮口痛甚，再用极苦以泻小肠，加芳香活络定痛。", "5676": "十八日马刀虽溃，少阳阳明之热毒未除，两手关脉独浮，气大旺，于清少阳阳明络热之中，兼疏肝郁，软坚化核。", "5677": "二十八日肝郁误补，结成马刀，目几坏。现在马刀已平其半，目亦渐愈，脉之数者已平。惟左关独浮，其性甚急，肝郁总未能降，胃不甚开，胸中饭后觉痞，舌白滑微黄，皆木旺克土之故。败毒清热之凉剂，暂时停止，且与两和肝胃。", "5678": "二十六日脉少大而数，加：", "5679": "二十九日脉仍数，肝胆俱病，不能纯治一边。", "5680": "九月十二日前方服十一帖，胃口大开，舌苔化尽，肝气亦渐和。惟马刀核未消尽，鼻犹塞，唇犹强，变衄为鼽。脉弦数，大便黑，又于原方内去护土之刚药，加入脑户之络药。盖由风热蟠聚于脑户，故鼻塞而衄或鼽，误补而邪不得出也。", "5681": "二十八日右脉洪大而数，渴欲饮水，牙床肿甚，阳明热也。于前方内加石膏一两，共二两，银花五钱，共八钱，桑叶二钱，共五钱。如服三五帖后，肿不消，加石膏至四两。", "5682": "富氏二十五岁巅顶一点痛，畏灯光日光如虎，脉弦细微数，此厥阴头痛也，与定风珠三剂而愈。", "5683": "何氏四十岁阳虚头痛，背恶寒，脉弦紧甚，与黄耆建中，加附子三帖而痛减，脉稍和。又每日服半帖，四日而愈。", "5684": "伊氏三十岁甲子十月二十七日脉弦急，胁胀攻心痛，痛极欲呕，甫十五日而经水暴至甚多，几不能起，不欲食，少腹坠胀而痛。此怒郁伤肝，暴注血海，肝厥犯胃也，议胞宫阳明同治法。盖《金匮》谓胞宫累及阳明，治在胞宫；阳明累及胞宫，治在阳明。兹因肝病下注胞宫，横穿土位，两伤者两救之。仍以厥阴为主，虽变《金匮》之法，而实法《金匮》之法者也。", "5685": "伊氏二十一岁十一月二十九日脉双弦而细，肝厥犯胃，以开朗心地要紧，无使久而成患也。", "5686": "车脉沉弦而紧，呕而不渴，肢逆且麻，浊阴上攻厥阴，克阳明所致，急宜温之。", "5687": "许四十七岁癸亥二月二十日脉弦而紧，弦则木旺，紧则为寒，木旺则土衰，中寒则阳不运，土衰而阳不运。故吞酸嗳气，不寐不食，不饥不便，九窍不和，皆属胃病。浊阴蟠踞中焦，格拒心火，不得下达，则心热如火，议苦辛通法。", "5688": "二十四日六脉阳微，浊阴蟠踞，不食，不饥，不便，用和阳明兼驱浊阴法。今腹大痛，已归下焦，十余日不大便，肝病不能疏泄，用驱浊阴通阴络法。又苦辛通法，兼以浊攻浊法。", "5689": "某脉沉紧为里寒，木旺土衰，浊阴上攻，腹拘急时痛，胁胀，腰痛，宜苦辛通法，兼醒脾阳。", "5690": "某脉弦细而紧，浊阴上攻，胸痛，用辛香流气法。", "5691": "李十三岁五月十四日六脉俱弦，不浮，不沉，不数，舌苔白滑，不食，不饥，不便，不寐，九窍不和，皆属胃病。卧时自觉气上阻咽，致令卧不著席，此肝气之逆也。额角上有虫斑，神气若昏，目闭不欲开，视不远，医云有虫，亦复有理。与两和肝胃，如再不应，再议治虫。", "5692": "二十日六腑不通，九窍不和。医者不知六腑为阳，以通为补，每见其二便闭也，则以大黄、蒌仁寒药下之。以后非下不通，屡下屡伤遂致神气若昏，目闭不开，脉弦缓而九窍愈不通矣。已成坏症，勉与通阳。", "5693": "庆宝女十六岁不食十余日诸医不效，面赤脉洪，与五汁饮，降胃清阴法，兼服牛乳，三日而大食矣。", "5694": "邱十八岁温热愈后，午后微热不除，脉弦数，面赤，五汁饮三日，热退进食，七日全愈。", "5695": "咯血胁痛，项下有核，脉数恶热，咽痛便溏。此肝火乘脾之证，反能食者，脾求助于食，而又不能胜之则痞耳。治在制肝益脾", "5696": "柳师加味较原方切实。若脉非弦大，惟羚羊去之。", "5697": "肝藏失调，侵脾则腹痛，侮肺则干咳，病从内生，非外感客邪之比。是宜内和藏气，不当外夺卫气者也。但脉弱而数，形瘦色槁，上热下寒，根本已漓，恐难全愈。", "5698": "形盛脉充，两尺独虚，下体麻痹，火浮气急。此根本不固，枝叶虽盛，未足恃也。", "5699": "诒按：如此脉证，似可参用肾气法以温摄之。", "5700": "类中偏左，于法为逆，犹幸病势尚轻，可以缓图取效。原方补少通多，最为合理。惟是阳脉则缓，阴脉则急，所以指节能屈不能伸，此亦病之关键处，刁；可忽也。经云：肝苦急，宜食甘以缓之。于前方中增进阴药之甘润者一二，更为完备。", "5701": "指节屈不能伸，病在厥阴肝经，是阴脉则急之义。若治痿取阳明，即阳脉则缓者矣。", "5702": "脉虚而涩，左半手足麻痹，食不知味。此气血不能运行周体，乃类中之渐也。", "5703": "方书每以左瘫属血虚，右痪属气虚。据述频年已来，齿疼舌赤，常有精浊。纳谷如昔，卒然右偏，肢痿舌强，口喁语蹇，脉浮数动。此乃肝肾两虚，水不涵木，肝风暴动，神必昏迷。河间所谓肝肾气厥，舌瘩不语，足痱无力之证。伹肾属坎水，真阳内藏，宜温以摄纳；而肝藏相火内寄，又宜凉以清之。温肾之方，参入凉肝，是为复方之用。", "5704": "诒按：即古法而化裁之。参详脉证，斟酌尽善。", "5705": "邓评：此症必有痰火窜闭络脉，再加钩钩、姜汁，竹沥，于痰火一层，稍为著力。", "5706": "脉濡，按之则弦，右肩及手指麻木，两腿酸痒，难以名状。此脾饮肝风，相合为病，乃类中之渐，不可不慎。", "5707": "邓评：脉濡属湿，弦则为风，风与湿合，放麻木酸痒，所谓饮者正由湿化也。羚羊宜与桂枝并用始妥，即木瓜，薏仁亦可参入。", "5708": "脉虚而数，两膝先软后肿，不能屈伸。此湿热乘阴气之虚而下注，久则成鹤膝风矣。", "5709": "邓评：想必舌绛脉盛，是以不顾厥汗而直任羚羊。似可参入生脉，兼治其虚。柳师亦在应加之例。", "5710": "惊悸易泄，腰疼足软，有似虚象，而实因痰火。盖脉不弱数，形不枯瘁，未可遽与补也。", "5711": "邓评：柳评加羚单、黄连，与否，总须以舌苔脉象为凭。", "5712": "肝风与痰饮相搏，内壅脏腑，外闭窍隧，以致不寐不饥，肢体麻痹。迄今经年，脉弱色悴，不攻则病不除，攻之则正益虚，最为棘手。", "5713": "久嗽脉不数，口不干，未必即成损证。此为肺饮，郁伏不达故也。", "5714": "体虚邪滞，肺络不清，脉泫而细，幸不数耳。", "5715": "肺病以中气健旺，能食便坚为佳。兹喘咳已久，而大便易溏，能食难运，殊非所宜。诊得脉象与前无异，但能节饮食，慎寒暖，犹可无虞。", "5716": "久嗽便溏，脉虚而数。脾肺俱病，培补中气为要。恐后泄不食，则瘦削日增也。", "5717": "脉细数促，是肝肾精血内耗，咳嗽必吐呕清涎浊沫。此冲脉气逆，自下及上，气不收纳，喘而汗出，根本先拨，药难奏功。医若见血为热，见嗽治肺，是速其凶矣。", "5718": "脉虚数，颧红声低，咳甚吐食，晡时热升，多烦躁。此肝肾阴亏，阳浮于上，精液变化痰沫。病已三年，是为内损，非消痰治嗽可愈。固摄下焦，必须绝欲。以饮食如故，经年可望其愈。", "5719": "脉微小，形寒，久嗽失音。是气馁阳损，议固胃阳，取甘温之属。", "5720": "用复脉甘润法。呛止音出，得益水濡润之力也。无如胃弱便溏，此药不宜再用。仿金匮麦门冬汤义，取养土之阴，以生肺金。", "5721": "孙评：叶氏用复脉每去麻仁者因此。", "5722": "久咳，便溏腹满。脾肺同病，已属难治。况脉数口干潮热，肝肾之阴，亦不足耶。", "5723": "脉寸关大而尺小，口干，上气不下，足冷不温。此阳气不潜。当用阴中阳药治之。", "5724": "邓评：阳既失潜，参以介类潜阳可也。须脉大而豁然者，桂、味始合。", "5725": "脉数减，咳亦缓。但浮气不得全归根本。宜补益下焦，以为吸受之地。", "5726": "《喘足冷至膝，唇口干，鼻塞，脉虚小。下气上逆，病在根本。勿以结痰在项，而漫用清克也。", "5727": "邓评：口干鼻塞，不免兼有外感。今用肾气丸，直任无疑者，以脉之虚小故也，急则先治耳。", "5728": "邓评：病象毕露于脉，谁谓脉不足凭乎。", "5729": "吐血得劳与怒即发，脉小数微呛。病在肝心，得之思虑劳心，宜早图之，勿使延及肺家则吉。", "5730": "失血咳逆，心下痞满，暮则发厥，血色黯，大便黑，肝脉独大。此有瘀血，积留不去。勿治其气，宜和其血。", "5731": "邓评：想必有舌绛脉数，心胸烦热之证，故方中可用犀角。", "5732": "脉寸静尺动，屡经失血，觉气从下焦上冲则呛，劳动则气促不舒。此病不在肺而在肾。治嗽无益，宜滋肾阴。", "5733": "心脉独大，口干易汗，善怒血逆。此心阴不足，心阳独亢。宜犀角地黄汤。", "5734": "邓评：此肝阳未尝不亢。盖肝阳过升，脉乃上溢，溢则并火于心脉矣。茅根宜易丹皮。", "5735": "劳伤失血，心下痛闷，不当作阴虚证治。但脉数咳嗽潮热，恐其渐入阴损一途耳。", "5736": "闭不足而阳有余，肝善逆而肺多郁。脉数气喘咳逆，见血胁痛。治宜滋降，更宜静养；不尔，恐其血逆不已也。", "5737": "再诊：热渐减，头中时痛，脉数不退，喉中痰滞不清。", "5738": "三诊：体虽不热，脉仍细数，宜养阴气。", "5739": "面黧形瘦，脉虚而数，咳嗽气促，腰膝无力，大便时溏。此先后天俱虚，虑其延成虚损。清润治肺之品，能戕中气，勿更投也", "5740": "络脉空隙，气必游行作痛，最虑春末夏初，地中阳气上升，血随气溢，趁此绸缪，当填精益髓。盖阴虚咳嗽，是他脏累及于肺，若治以清凉，不独病不去而胃伤食减，立成虚损，难为力矣。", "5741": "汗出偏沮，脉来不柔，时自歇止。知肝阳有余，而胃阴不足，于是稠痰浊火，扰动于中，壅滞于外。目前虽尚安和，然古人治未病，不治己病。知者见微知著，须加意调摄为当。", "5742": "四诊：大便通，脉和。惟宜滋养。", "5743": "下既不通，势必上逆而为呕，所谓幽门之气，上冲吸门是也，治法自当疗下。但脉小目陷，中气大伤，宜先安中止呕。呕定再商。", "5744": "痛呕之余，脉当和缓，而反搏大，头运欲呕，胸满不食，神倦欲卧，虑其土啧木张，渐致痉厥。法当安胃清肝，亦古人先事预防之意。", "5745": "邓评：既恐土啧，而立方不以补中，只云安胃清肝者，为脉反搏大故也。片语只字，具见斟酌。", "5746": "气郁痰凝，阻隔胃脘，食入则噎，脉涩，难治。", "5747": "诒按：旋覆代赭为噎膈正方。食入则噎，肺气先郁，故加郁、贝、枇杷叶；惟脉涩者正虚，可加人参。", "5748": "邓评：病较前案稍深，故用药亦较进步。脉涩不独为正虚，抑且为血痹。", "5749": "脉疾徐不常，食格不下。中气大衰，升降失度。", "5750": "邓评：脉疾徐不常，却系中气大衰，制剂精幻可法。", "5751": "中气迭伤，不能健运，朝食暮吐，完谷不腐。诊得脉虚色黑，腰脚少力，知不独胃病，肾亦病矣，此岂细故哉。", "5752": "肝阴素亏，温邪扰之，发为痉病，神昏骱齿，瘛疯不定。法当滋养肝阴，以荣筋脉，清涤痰热，以安神明者也。若能应手，尚可无虑。", "5753": "热伤津液，脉细口干，难治。", "5754": "诒按：此存阴泄热之正法，所云难治，想因脉细之故。", "5755": "邓评：口干仅为津液受伤，脉细则其元气亦弱，故云难治。", "5756": "舌干脉数，汗为热隔，虽发之亦不得，惟宜甘寒养液。虽不发汗，汗当自出，然必足温，而后热退乃吉。", "5757": "风温郁于肺胃，咳而胸满，痰多胁下痛，脉数口干。", "5758": "脉右大，舌黄不渴，呕吐黏痰，神躁语言不清，身热不解。此劳倦内伤，更感湿温之邪，须防变端。", "5759": "邓评：脉右大舌黄，知肺胃受热；不渴，知复多痰湿。用药甚轻，而识见甚高。惟姜炒川连，何不加用，此为莫解。", "5760": "脐中时有湿液腥臭，按脉素大。此少阴有湿热也。六味能除肾间湿热，宜加减用之。", "5761": "邓评：得元有精滑之症乎。然脉必缓小者为宜，即见数象，亦必无力。", "5762": "面黑目黄，脉数而微，足寒至膝，皮肤爪甲不仁。其病深入少阴，而其邪则仍白酒湿得之及女劳也。", "5763": "邓评；此必是体实脉实者，故可峻用开导。盖有识自能有胆。", "5764": "诒按：寒袭于肾，而气上逆，故用温养。胀及腰背者，督阳不用也。鹿茸温通督脉，麝香开泄浊阴，故以主为君。", "5765": "脉弦小腹痛，食后胃脘痛，上至咽嗌。肝火乘胃。宜泄厥阴、和阳明。", "5766": "心腹痛，脉弦，色青，是肝病也。", "5767": "脉虚数，色白不泽。左胁有块杯大，大便小便自利。病在肝家，营血不和，此为虚中有实，补必兼通。", "5768": "大腹右有形为聚，脉大，食入即作胀，治在六腑。", "5769": "邓评：既云脉大，何不加川连、枳实？", "5770": "脉迟胃冷，腹胀，气攻胸胁，恶心少食泄泻。宜振脾胃之阳。", "5771": "脉微迟，左胁宿痞，腹渐胀大，便溏溺少。此是浊阴上攻，当与通阳。", "5772": "脉弦中满，病在肝脾。", "5773": "邓评：脉弦者，人参不如白木为妥善。", "5774": "脉证合参，乃气结在上，津不运行，蒸变浊痰，由无形渐变有形。徐之才谓轻可去实，非胶固阴药所宜。", "5775": "头痛偏左，耳重听，目不明，脉寸大尺小。风火在上，姑为清解。", "5776": "少阳之脉，循耳外，走耳中。是经有风火，则耳脓而鸣。治宜清散。", "5777": "邓评：小便浑浊，绝不犯分利治法，惟凭之于脉耳", "5778": "形伟体丰，脉得小缓。凡阳气发泄之人，外似有余，内实不足，水谷之气，不得阳运，酿湿下注，而为浊病，已三四年矣。气坠宜升阳为法，非比少壮阴火自灼之病。", "5779": "恼怒伤中，湿热乘之，脾气不运，水谷并趋大肠，而为泄；腹中微疼，脉窒不和，治在中焦。", "5780": "又按：案中脉窒句，不甚明了。", "5781": "脉窒即是涩滞之意。但何不竟云脉涩为直捷了当！", "5782": "气郁不行，津枯不泽，饮食少，大便难，形瘦脉涩。未可概与通下。宜以养液顺气之剂治之。", "5783": "邓评：仲景虽有脉涩可下之例，究属涩不宜下者罕见也。此方宗通凿汤而交通之，却胜于原方，以其流利不滞也。", "5784": "下血后，大便燥闭不爽，继而自利，白滑胶黏，日数十行，形衰脉沉。必因久伏水谷之湿。府病宜通，以温下法。", "5785": "鼻痒心辣，大便下血，形瘦，脉小而数，已经数年。", "5786": "脉虚细数，阴不足也。鼠漏未愈，热在大肠。", "5787": "诒按：此肛门漏也，名为鼠漏，未知所本。脉证已属损象，故以滋补肝肾为主。", "5788": "胎前病子肿，产后四日即大泄，泄已一笑而厥，不省人事，及厥回神清，而左胁前后痛满，至今三月余矣。形瘦，脉虚，食少，少腹满，足肿，小便不利。此脾病传心，心不受邪，即传之于肝，肝受病而更传之于睥也。此为五脏相贼，与六腑食气水血成胀者不同。所以攻补递进，而绝无一效也。宜泄肝和脾法治之。", "5789": "心营与肾水交亏，肝气挟肝阳上逆，胸中气塞，口内常干，手震舌掉，心烦不寐，即有寐时，神魂游荡，自觉身非己有，甚至便溏纳少，脾胃亦衰，脉形细小无神，而有歇止之象。逐证施治，似乎应接不暇。因思精神魂魄，必令各安其所，庶得生机勃勃；否则悠悠忽忽，恐难卜其旋元吉。拟许学士真珠母丸法。", "5790": "邓评：心烦不寐，心火亢矣，何又脉小便溏？大都火被湿痰所遏也。于清心安神内，务参辛燥开痰，俾湿化痰豁，乃能木达风清也；若滋寒太过，恐多弊而少利耳。", "5791": "孙评：所述病情，均因痰火上蒙致病，即便溏脉歇，亦为痰滞于中，脾营胃卫不调和之症，若损证而至见此，则正气垂绝，决无生理。", "5792": "再诊：脉之歇止向和，便之溏泄不作，气塞稍平，手震亦定。但寤多寐少，内藏之魂魄未安；胸痞脘闷，上壅之浊痰未降。容将通阳镇逆法，参入前方，冀相与有成耳。", "5793": "邓评：脉之歇止，是亦疫之咎欤。", "5794": "三诊：夜半得寐，心肾已交，肺魄肝魂，自能各安其脏。无如心易烦动，神反疲乏，气犹短促，胸还痞闷，脉仍细小，两足不安。脉虚证虚，是谓重虚，而兼有湿痰从之为患。夫痰即有形之火，火即无形之痰也。法当固本为主，消痰佐之。", "5795": "四诊：风火痰三者之有余，留滞肝经，以致卧血归肝，魂不能与之俱归，筋惕肉（目闰）而醒，前次气短等证，莫不因此。而又起于有年病后，气血两亏，何堪磨耐。所治之方，不出许学士法加减。现在脉息细小带弦，虽无止歇之形，尚有不静之意，究属难免风波，未可以能食为足恃也。", "5796": "五诊。前夜熟睡，昨又变为少寐，寐之时，适在子时以后，肝胆两经尚有余邪可知。更兼痰火阻气，时逆时平，其气逆时，必面赤心悸，甚则肉（目闰）筋惕，烦热不安，脉亦随之变异，所谓心火一动，相火随之是也。调治之外，必须静养，俾心火凝然不动，方可渐入坦途。", "5797": "六诊：所患小恙，无一不除，盖以清之、化之、补之、养之，无微不至，而得此小效耳。所嫌者，寐非其时，寤非其时，心阳太旺，神气外驰，是卫气独行于阳，阳𫏋脉满，满则不入于阴，阴分之虚明矣。将滋阴之品，参入前方，未识能弋获否？", "5798": "诒按：此证不寐，乃肝胆有痰火所致。案中引内经阳𫏋脉满之文，本属强为牵合；至以经言阴虚，指为阴血之虚，尤非经文本旨。", "5799": "七诊：人可以参天地之干者，莫贵于眠食如常。今食能知味，眠则未安，昨夜忽寐忽醒，醒则不爽，寐则不安，以昭卫气不得入于阴，独留行于阳之意。柳按：案语牵合支离，总由误认经文阴字，故说来总不入理。是阳𫏋脉满，营血不能充足，肌肉不能润泽，苟非阳生阴长，阴足恋阳，何以渐入佳境。然营中之血，既不生之于心，乌能藏之于肝，统之．于脾，而欲藉草木之无情，俾血肉之有情者，以生以长，谈何容易。况当此痰火易烦，得食暂安，以及虚风内动，筋惕肉（目闰），支体牵摇，大便难通之候，更难为力矣。急宜加意调理。", "5800": "邓评：不爽不安，无非痰火为患。所引阳𫏋脉满经文一节，自是勉强。", "5801": "八诊：彻夜好眠，神魂己定，是佳兆也。但脉形细小而兼滑数，数为有火，滑为有痰，细属阴虚，小属气弱，虚弱之中，兼有痰火，有时面红，有时咳嗽，有时气痞而短，有时烦热不安；更兼大便燥而小便短，筋惕肉（目闰），支体动摇，神情困倦，语言无力等证，均未平复。还宜谨慎小心。", "5802": "孙评：论脉确合病机，得其要领。评语真得神髓。", "5803": "阳络重伤，咳无虚日，而于五更为甚，口干盗汗，溺赤便溏，脉数而身热，欲成损证也；咽中已痈，虑其加喘生变，权以清热存阴。", "5804": "三诊：溏泄已止，咳嗽未除，咽痛盗汗，脉数。肺经尚有热邪。", "5805": "四诊：便泄稀，身热轻，咽喉干痛，亦渐向愈。而咳嗽腹鸣，神疲纳少，脉小带数。想是风热递减，气阴两亏，而脾中之湿，又从而和之为患。补三阴、通三阳之外，更以崇土化湿佐之。", "5806": "八诊：脾虚则便溏，肺虚则咳嗽，肾虚则虚火上炎，咽喉干痛，脉弱无力，元气伤矣。急宜补气育阴。", "5807": "先生之病，素禀湿热，又挟阴虚之病也。湿者何？地之气也。热者何？天之气也。天地郁蒸，湿热生焉。湿热禀于先天者，与元气混为一家，较之内伤外感之湿热，属在后天者，岂可用日语哉。设使薄滋味，远房帏，不过生疡出血而已。乃从事膏粱，更多嗜欲，斯湿热外增，阴精内耗，脏腑营卫，但有春夏之发，而无秋冬之藏，无怪乎风火相煽，而耳为之苦鸣也。当斯时也，静以养之，犹可相安无事，何又喜功生事，火上添油，致陡然头晕面赤，其一派炎炎之势，盖无非肝经之火，督脉之阳，上冒而为患。近闻用引火归原之法，以为甘温能除大热，嗟乎！未闻道也。夫甘温除大热者，良以下极阴寒，真阳上越，引其火，归其原，则坎离交媾，太极自安；若阴虚湿热蒸动于上者，投以清滋，尚难对待，况敢以火济火，明犯一误再误之戒乎！逮后，清已有法，滋亦频投，饮食能增，身体能胖，而坐立独不能久者，明是外盛中空，下虚上实，用药殊难。尝见东垣之清燥汤，丹溪之虎潜丸，润燥兼施，刚柔并进，张氏每赞此两方，谓必互用，始克有济，何故而不宗此耶。然犹有进于此者，治病必资药力，而所以载行药力者，胃气也。胃中湿热薰蒸，致吐血痰嗽，鼻塞噫气，二便失调，所谓九窍不和，都属胃病也。然则欲安内脏，先清外腑，又为第一要著矣。至秋末冬初病甚者，十月坤卦纯阴，天已静矣；而湿热反动，肾欲藏矣，而湿热仍露，能勿令病之加剧乎，附方谨复。", "5808": "身热，手心热，少力神倦，游利脉濡。此睥阳下陷，阴火上乘。甘温能除大热，正为此等证设也。", "5809": "劳倦而招风湿，右脉濡小，左脉浮弦，舌苔薄白，溺赤便溏，肢体疫楚，神倦嗜卧，少纳口干。", "5810": "五腑六腑，皆有营卫，营卫不调，则寒热分争。此病分争之后，肌肉暗消，因思脾主肌肉，肌肉暗消，正所以昭脾之营卫虚也。无怪乎脘痞纳少，力乏嗜卧，脉形软弱，有种种脾虚见象。于法当健脾为主，而八八已过之年，阳气必衰，又宜兼壮元阳，使火土合德，尤为要务。", "5811": "心脉宜大者反小，肾脉宜沉者反浮；浮则为伤，小则为虚。想是读书攻苦，心肾不交，失其封藏之职。夫心肾即婴儿姹女，欲其交者，须得黄婆为之媒合。黄属中央，脾土所主，舍补中宫之外，皆属徒然。", "5812": "邓评：肾脉浮者宜补真阴；须得黄婆为之媒合者，不果于交心肾之中，参以疏补中官，为黄婆媒合之义也。", "5813": "昼为阳，阳旺应不恶寒；夜为阴，阴旺应不发热。兹乃日间恶寒，夜间发热，何以阴阳相反若是耶？此无他，阳虚则恶寒于日，阴虚则发热予夜。阴阳之正气既虚，所有疟后余邪，无处不可为患，足为之浮，腹为之满，溺为之短。一饮一食，脾为之不运；生饮生痰，肺为之咳嗽。脉从内变，而为细弦。夫形瘦色黄舌白，阳分比阴分更亏，极易致喘。", "5814": "类中之余，足不任身，手难举物，尺脉无力。阴阳并弱。拟用河间地黄饮子法。", "5815": "邓评：尺脉无力，阴阳并弱，为地黄饮子的对题旨。但类中之症，于本虚之中，更必有风痰湿热错杂其间。观其膏方加萆薢，三诊加蝎尾，亦从可知矣。", "5816": "怒则气上，痰即随之，陡然语言蹇涩，口角流涎，月余不愈，所谓中痰中气也。然痰气为标，阳虚为本，所以脉息迟弦，小水甚多，肢麻无力，法宜扶阳为主，运中化痰佐之。", "5817": "左肢痿而不用，口歪流涎，舌苔起腻，便溏溺少，脉形弦迟，以中虚湿胜之体，易于生痰动风，内风既动，未有不招外风者也。", "5818": "邓评；因便溏脉迟，故立方以温化湿痰作主，兼疏外风。", "5819": "膝骨日大，上下渐形细小，是鹤膝风证。乃风寒湿三气合而为病，痹之最重者也。三气既痹，又挟肺金之痰以痹肘，所谓肺有邪，其气留于两肘。肘之痹，偏于左，属血属阴。阴m久亏，无怪乎腰脊突出，接踵而来。至于咳嗽鼻流清涕，小水色黄，肌肉暗削，行步无力，脉形细小，左关独见弦数，是日久正虚，风寒湿三气渐见化热之象。拟用痹门羚羊角散加减。", "5820": "神识不清，自言自语，起坐无常，寤寐失度，脉形小滑，舌苔白腻。此痰热内郁心包，无路可出，而作心风也。久久归入癫痫，毋忽。", "5821": "阳明之脉环于唇。唇起红筋，即发牵动而厥，厥醒吐沫，咳血鼻衄，二便失调，脉弦滑数。显系胃有积热，动血生痰，又被肝火所冲激，乃痫证之根，毋忽。", "5822": "心悸，初从惊恐得之，后来习以为常，经年不愈，手振舌糙，脉芤带滑，不耐烦劳。此系心血本虚，痰涎袭入也。", "5823": "神蒙善忘，包络之病为多。然左寸脉息上浮，关部独带弦数，右寸与关小而带弦，白苔满布，大便久溏，肢体无力，倦怠嗜卧。脾经之湿痰，被肝火所冲激，累及心包也。", "5824": "曾经失血，现在内热吐痰，夜来大魇，脉象滑数。阴虚挟痰所致。", "5825": "邓评：脉象既已滑数，当必痰火内盛。所用参、地、五味，恐有碍于痰火。", "5826": "鼻血遗精，肺肾俱病；寒热盗汗，营卫并伤。必须大补为是。无如脉息细弦，舌苔满布，二便失调，饮食不舒，脾家又有湿痰为患，先宜化湿健脾，再商补剂。", "5827": "动则气喘，言则亦然，是下虚也，宜其俯仰不适矣。至于脘中拒按，隐隐作疼，筑筑而跳，脉息中部太弦，必有湿热痰浊交阻于胃，失下行为顺之常，未便独以虚治。", "5828": "邓评：病既下虚上实，用药须两不相碍。此方固称平妥，拟再加蒌、连、桑皮可也。盖脉息中部太弦，必挟木火为患耳。", "5829": "年逾古稀，肾气下虚，生痰犯肺，咳喘脉微，当与峻补。", "5830": "金水六君煎麦、地、橘，夏、苓、草。合生脉散加核桃肉", "5831": "原注：补命门之火以生土，清其生痰之原，则肺之咳喘自宁。煎方金水六君煎以治脾肾，生脉以养肺，桃肉以补命门。其奠安下焦之剂，另用丸药常服，斟酌可谓尽善矣。", "5832": "交冬咳嗽，素惯者也。今春未罢，延及夏间。当春已见跗肿，入夏更增腹满，口燥舌剥，火升气逆，右脉濡数，左脉浮弦。风邪湿热由上而及下，由下而及中，即经所云：久咳不已，三焦受之，三焦咳状，咳而腹满是也。际此天之热气下行，小便更短，足部尚冷，其中宫本有痞象，亦从而和之为患，用药大为棘手。姑拟质重开下法，佐以和胃泄肝之品。", "5833": "寒热后咳嗽痰浓，头疼口渴，舌红脉数，大便溏泄。冬温之邪郁于肺分，而从燥化，当泄之清之。", "5834": "寒必伤营，亦必化热，咳嗽不止，呕吐紫血，咽中干痛，苔白边青，脉紧而数，近更咳甚则呕，气息短促。肺胃两经皆失其清降也。郁咳成劳，最为可怕。", "5835": "孙评：舌青脉紧，病情甚恶。用药平淡，大不可法。", "5836": "伤风不醒，咳嗽呕恶，所见之痰，或薄或浓，或带血色。左关脉独见浮弦且数，小有寒热，此损征之根也。千金法治之。", "5837": "再诊：进前方咳嗽大减，所出之痰，仍见青黄之色，身热虽轻，咽中苦痛，脉形弦细数。风邪未尽，中下两虚，制小前方之外，参入猪肤法，一治身热，一治咽痛。", "5838": "再诊：进劳风法，咳嗽大减，红痰亦无。但痰色尚带青黄，左关脉息弦硬不和，肝胆留邪容易犯肺胃俞也。毋忽。", "5839": "右脉弦滑而数，滑为痰；弦为风，风郁为热，热郁为痰，阻之于肺，清肃不行，咳嗽自作。", "5840": "晨起咳嗽，劳倦伤脾，积湿生痰所致。久而不已，气喘畏风，金水因此而虚，补中寓化，一定章程。现在身热口干苔白，脉息细弦而紧；紧则为寒，寒风新感。必须先治新邪，权以疏化法。", "5841": "去冬咳嗽，今春寒热，至秋令而咳嗽或轻或重。惟喉痒则一。所谓火逆上气，咽喉不利，此等证是也。最易成劳，未可以脉未促，气未喘为足恃。", "5842": "肺经咳嗽，咳则喘息有音，甚则吐血；血已止，咳未除，右寸脉息浮弦，弦者痰饮也。良以饮食入胃，游溢精气，上输于脾，脾气散精，上归于肺；而肺气虚者，不能通调水道，下输膀胱，聚液为痰，积湿为饮，一俟诵读烦劳，咳而且嗽，自然作矣。补肺健脾，以绝生痰之源，以清贮痰之器。", "5843": "咳者，和谐声也，其音开口而出，仿佛亥字之音，故有声无痰为咳。嗽则如水之灌漱，然有物在喉，漾漾欲出，故从口从敕，后人遂以有痰为嗽。然则咳嗽之病，胡从生也？日：病有万变，要不出内伤外感两端，请先明外感。外感者，风寒暑湿燥火六者尽之。论其常，则各主一时为病；论其变，则四时皆可以受六淫之邪。今则即风寒论。感风者，鼻塞身重，恶风清涕，此证也；左脉浮弦，此脉也。感寒者，恶寒体痛，发热脉紧，此寒之证与脉也。而风之中，又有辨。春则为温风，肝木用事；受风者，必伤肝，而又有中血中气之别；风伤卫，则参苏饮；风伤营，则芎苏饮。夏则为热风，伤心包，而亦有凉热之别；凉风香薷饮，热风鸡苏散。秋为凉风，伤肺，败毒散、金沸草散。冬为寒风，伤膀胱，桂枝厚朴杏仁汤、麻黄汤。傥冬时天热而感寒风，则当用葳蕤汤、阳旦汤，此冬温之邪也。惟秋分以后少暑湿，春夏无燥气。他如先伤风而后伤热，为热包寒，葳蕤汤；肺素热而感寒风，为寒包热，金沸草散。一嗽而痰出稠黏者，脾湿胜，二陈之类。连嗽无痰者，肺燥甚，清燥救肺汤。此皆外感咳也。言风一端，而六气可类推矣。若夫内伤，大法惟痰饮、津伤两种。痰饮多阳虚，津伤多阴虚。其阳虚痰饮尚浅者，六安、二陈之类；有火者，温胆汤；夹阴虚者，金水六君煎；阳虚甚，兼夹痰火不可攻者，玉竹饮子成降法；喘者，降气汤、贞元饮，此阳虚痰饮一端也。他如阴虚者，阴火易于上升，胃气不清者，麦门冬汤；曾见血者，四阴煎；痰多而浓，无胃气者，六君子汤；痰少而嗌干，胃气未绝者，六味丸、都气丸、八仙长寿丸。此粗举内伤之一端也。此外又有劳风一门，咳吐浊涕青黄之痰，由劳碌伤风，恋而不化，最为难治。浅者，秦艽鳖甲，表虚汗多者，黄耆鳖甲；深则柴前连梅煎，千金法也。此皆劳风之治也。至于芎枳二味，以治寒郁化火之咳；合二母以泻肺之母；泻白散，以清泄肺脏；四物桔梗汤，以引清血分，皆在所常用也。似此某证某方，条分缕析，须平日有格致功夫。试观先生临证之方，似乎夹杂，合之病人之证，则无一味可以增减。先生尝曰：吾门之病，如时文，割截隔章隔节之题，他人无处下手，左支右拙。余能以心思灵空，贯串合凑一方，令病安稳。此无他，外感多与内伤同，病内伤，每因外感而发，更遇杂药乱投之医，治丝而棼，愈难就绪。治此者，不能不兼采众方，就中另出一方，其立方之意，在案中宣露明白。噫！执此意以寻先生之门径，思过半矣。", "5844": "再诊。接阅手书，知咳血、梦遗、畏火三者，更甚于前。因思天符之火行于夏时，可谓火之淫矣。即使肺金无病者，亦必暗受其伤，而况痰火久踞，肺金久伤，再受此外来之火，而欲其清肃下降也，难矣。肺不下降，则不能生肾水，肾水不生，则相火上炎，此咳逆梦遗之所由来也。至于畏火一条，《内经》载在阳明脉解篇中，是肝火乘胃之故。法宜泻肝清火，不但咳血、梦遗、畏火等证之急者，可以速平，而且所患二便不通，亦可从此而愈。悬而拟之，未识效否。", "5845": "三诊：阳明中土，万物所归，现在盯经湿热之邪，大半归于阳明，以著顺乘之意，而逆克于肺者，犹未尽平。所以睡醒之余，每吐青黄绿痰，或带血点，其色非紫即红，右胁隐隐作痛，脉形滑数，独见肺胃两部。宜从此立方。", "5846": "邓评：病由相火内亢，更多痰湿夹杂，用生地以助痰，则火反受遏，窜于络脉故胁痛。", "5847": "咳嗽而见臭痰络血，或夜不得眠，或卧难著枕，大便干结，白苔满布，时轻时重，已病半年有余。所谓热在上焦者，因咳为肺痿是也。左寸脉数而小，正合脉数虚者为肺痿之训。而右关一部不惟数疾，而且独大独弦独滑，阳明胃经必有湿生痰，痰生热，薰蒸于肺，母病及子，不独肺金自病，此所进之药，所以始效而总不效也。夫肺病属虚，胃病属实。一身而兼此虚实两途之病，苟非按部就班，循循调治，必无向愈之期。", "5848": "邓评：凡咳嗽，脉之弦滑见于右关者，必多痰湿浊邪壅聚于胃，热被湿遏，湿为热蒸。阅案中议论，亦极清正。惟方内胶、麦、地骨，似太遏邪；欲清胃热，不如易芦根、知母为善。", "5849": "孙评：右关大弦数之胃脉，热遏于中，不得肃化。阿胶、生地滋阴补血，热得补而愈壅，宜去。当从柳氏用苇茎汤加肃清之味。", "5850": "再诊：诸恙向安，右脉亦缓。药能应手，何其速也。再守之，观其动静。", "5851": "三诊：右关之大脉已除，弦滑未化，数之一字，与寸相同，湿热痰三者，尚有薰蒸之意，肺必难于自振。", "5852": "六诊：肺虚则易招风，偶然咳嗽加剧，而今愈矣。脉数右寸空大，阴气必虚。自当养阴为主；然阳明胃经，湿热薰蒸之气，不能不兼理之。", "5853": "七诊：右脉小中带数，肺阴不足，肺热有余；其所以致此者，仍由胃中之湿热薰蒸也。", "5854": "昨日所溢之血，盈盆成块而来，无怪乎其厥矣。幸得厥而即醒，夜半得寐，其气稍平。今日仍然上吐，脉来芤数，火升颧红，咳逆时作，大便不爽而黑。阳明胃腑必有伏热。防其再冒再厥。", "5855": "久嗽失血，鲜而且多，脉数左弦，苔黄心嘈，金受火刑，木寡于畏，以致阳络被伤也，防冒。", "5856": "阳络频伤，胸前窒塞，咳逆不爽，舌红苔黄，脉形弦数。此系瘀血内阻，郁而为热，肺胃受伤，极易成损，慎之。", "5857": "邓评：脉弦数而苔黄，当有风热郁恋。所用方药，亦非背谬。", "5858": "痧子之后，咳嗽四月，颈旁鬁串，咳甚则呕，纳少形瘦，肤热脉细。想是余邪内恋，阴分大虚，欲成损证也。", "5859": "孙评：咳而肤热脉细，余邪内恋，热未清也，芎、归不宜。况痧后久咳，明明是余热留恋，入肺伤阴所致。", "5860": "温邪发痧之后，咳嗽失血，血止而咳嗽不减，所吐之痰，或黄或白，或稠或稀，舌质深红，其苔满白，喉痒嗌干，脉弦带数，渐作痧劳之象。", "5861": "邓评：据此苔脉，邪郁尚重，还当著意疏邪。", "5862": "子后咳嗽，天明而缓，脉形弦数，声音不扬，肝胆之火未清，金受其刑，水必暗亏也。", "5863": "邓评：子后咳嗽，的系肝胆之火，亦诊脉之关键处。", "5864": "咳嗽失血，音烁咽干，近来小有寒热，头痛喉疼；脉浮促而数。肺阴久伤，又兼燥气加临。补肺之中，当参以辛散。", "5865": "阳络频伤之后，咳嗽痰浓，内热嗌干，脉芤数，左关独弦。此肝火刑金，金气不清之候，容易成损。慎之。", "5866": "失血后，咳嗽梦遗，脉数左关弦急。必有肝火在里，既犯肺金，又泄肾气也。久延势必成劳。", "5867": "失血久咳，阴分必虚，虚则不耐热蒸，食西瓜而稍退，脉数左弦，唇干苔白色滞，溺黄，加以咽痛，久而不愈，想是水不涵木，阴火上冲，胃气不清也。势欲成劳，早为静养，以冀气不加喘，脉不加促，庶几可图。", "5868": "邓评：苔白色滞，而断其为阴虚者，良以脉数左弦故也。盖一病须有一病之著眼处。", "5869": "再诊。浊痰虽少，咳逆仍然，阴分之火上冲于肺。肺属金，金受火刑，水之生源绝矣。能不虑其脉促气喘乎。知命者自能静以养之。", "5870": "原注：前两方，六昧加减法也。脉数左弦，咽痛，水不涵木，阴火上冲。惟苔白二字，为胃气不清之证。此病头绪甚繁，方中一一还他的对之药。", "5871": "脉形细数，细属阴亏，数为有火；火上刑金，水即绝其生源，未可以咳嗽小恙目之。幸而气息未喘，脉象未促，如能静养，犹可以作完人。", "5872": "邓评；未见潮热失血，亦尚幸事。苟至气喘脉促，更且临危矣。", "5873": "邓评：此病必脉小、色白，小便清利，故可进以温热重剂，即启峻汤方法也。饴糟或饴糖之误。", "5874": "食则右胁下痛，痰自上升，升则得吐而安，右脉弦滑，左关坚急，寸部独小。此心气下郁于肝经，脾弱生痰为膈。放开怀抱，第一要义。", "5875": "食则噎痛，吐去浊痰而止，胸前常闷，脉象弦滑，舌苔满白，肌肉瘦削之人，阴血本亏，今阳气又结，阴液与痰浊交阻上焦，是以胃脘狭窄也。久则防膈。", "5876": "脉形细涩，得食则噎，胸前隐隐作痛。瘀血内阻，胃络不通，此膈证之根。", "5877": "诒按：此瘀血膈也，脉证均合，用药亦专注在此。", "5878": "瘀血挟痰，阻于胸膈，食则作痛，痛则呕吐，右脉涩数，惟左关独大且弦。是痰瘀之外，更有肝经之气火，从而和之为患，乃膈证重候。慎之。", "5879": "食已即吐，脉弦苔白，便溏溺清。湿痰内胜，被肝经淫气所冲。", "5880": "脾阳不足，湿浊有余，少纳多胀，舌白脉迟，茅术理中汤合四七汤。", "5881": "胸痛彻背，是名胸痹。痹者，胸阳不旷，痰浊有余也。此病不惟痰浊，且有瘀血交阻膈间，所以得食梗痛，口燥不欲饮，便坚且黑，脉形细涩；昨日紫血从上吐出，究非顺境，必得下行为妥。", "5882": "邓评；得食梗痛，便坚脉涩，却已能归入膈门。惟如此等方法，自有胆识。", "5883": "心痛彻背，是名胸痹，久而不化，适值燥气加临，更增咳嗽咽干，痰中带红，脉形细小，治之不易。", "5884": "心痛有九，痰食气居其三。三者交阻于胃，对痛时止，或重或轻，中脘拒按，饮食失常，痞闷难开，大便不通，病之常也。即有厥证，总不离乎痛极之时。兹乃反是，其厥也，不发于痛极之时，而每于小便之余，陡然而作，作则手足牵动，头项强直，口目歪邪，似有厥而不返之形；及其返也，时有短长，如是者三矣，此名痫厥。良以精夺于前，痛伤于后，龙雷之火，挟痰涎乘势上升，一身而兼痛厥两病。右脉不畅，左脉太弦，盖弦则木乘土位而痛，又挟阴火上冲而厥。必当平木为主，兼理中下次之。盖恐厥之愈发愈勤，痛之不肯全平耳。", "5885": "邓评：中脘拒按，痞闷便秘，究属不通之实象。惟肝气久郁，则阳内亢而化火生风，风阳升动则厥且痫矣。今转发于溺余者，以肝脉络阴器，溺则肝阴虚而风阳乘机陡动耳。始而郁极故痛厥，继则动甚故痫厥，横乘于中则痛，直升于上则厥。法当用酸苦辛药以制肝之旺气、疏肝之郁气，清火化痰，并具于内，故此方合病焉。惟连、柏、姜、萸，尚可参用也。", "5886": "再诊；据述厥已全平，痛犹未止，便黑溺黄，右脉反弦，想诸邪都合于胃也，胃为腑，以通为补。悬拟方。", "5887": "诒按：诸邪都合于胃，从右脉之弦看出，是病机紧要处。", "5888": "邓评：便黑者抉瘀故也，或为肝火所煅烁，理亦有之，然其粪必坚燥也。进酸敛而右脉反弦，是肝之旺气已减，故胃脉得较畅也，当属佳象。此方更觉松灵活泼。", "5889": "三诊；痛厥已平，尚有背部隐疼之候，腰部亦疼，气逆咳呛，脉形细数。想肝肾阴虚，气滞火升，肺俞络脉因之俱受其伤也。", "5890": "邓评：见证是肝家之气火留窜于络脉，宜加山栀、钩钩、丝瓜络，以清经络之郁火，更宜姜汁以反佐之。", "5891": "四诊：腰脊尚疼，咳嗽不止，苔白底红，脉形弦细。是阴虚而挟湿热也。", "5892": "脾气素虚，湿郁难化，而木之郁于内者，更不能伸，所以酸水酸味，虽有减时，而灰白之苔，终无化日，无怪乎脉小左弦，脘胁胀痛也。此臌胀之根，毋忽。", "5893": "邓评：脉既左弦，附子终怕碍肝，参用柴、芍自合，金铃子散亦所需要。", "5894": "病分气血，不病于气，即病于血，然气血亦有同病者。即如此病，胃脘当心而痛，起于受饥，得食则缓，岂非气分病乎。如独气分为病，理其气即可向安，而此痛虽得食而缓，午后则剧，黄昏则甚，属在阳中之阴，阴中之阴之候，其为血病无疑。况但头汗出，便下紫色，脉形弦细而数，更属血病见证。但此血又非气虚不能摄血之血，乃痛后所瘀者，瘀则宜消，虚则宜补，消补兼施，庶几各得其所。", "5895": "原注：分明两病，一是脾虚，气分不能畅达而痛，得食则缓，宜补可知。然人每疑痛无补法者，以痛必有痰气凝滞也。先生用理中以补脾，即加青皮、陈皮以通气；至便紫脉弦数，肝家之血必有瘀于胃脘者，此时不去其有形之瘀滞，痛必不除，病根不拔也。此种病，世医不能治，往往以为痼疾，不知不去瘀，则补无力，徒去瘀则脾胃更伤。先生则双管齐下，立案清沏，度尽金针，非名家恶能如是。", "5896": "胃脘当心而痛，少腹气升，呕吐酸苦痰涎，脉形弦数。显系寒热错杂之邪，郁于中焦，肝属木，木乘土位，所有积饮，从此冲逆而上，病已年余，当以和法。", "5897": "邓评：据其呕吐酸苦，脉形弦数，则肝胆郁火必盛，虽属寒热错杂，附子究恐有碍郁火，若竟服乌梅丸则有碍。", "5898": "胃脘当心而痛，脉形弦数，舌绛苔黄，口干苦，小便赤。一派火热之象，气从少腹上冲于心，岂非上升之气自肝而出，中挟相火乎。", "5899": "脘痛下及于脐，旁及于胁，口干心悸，便栗溺黄，脉弦而数，此郁气化火也化肝煎合雪羹原注；此景岳化肝煎也。必肝有实火者可用，口干、脉数，溺黄是其的证也。", "5900": "邓评：为木郁而佐以逍遥散者，其脉必兼弦象可知。雪羹参入方内，似属不妥。", "5901": "当脐胀痛，按之则轻，得食则减，脉形细小而数，舌上之苔左黄右剥，其质深红，中虚伏热使然。", "5902": "少腹久痛未痊，手足挛急而疼，舌苔灰浊，面色不华，脉象弦急。此寒湿与痰，内壅于肝经，而外攻于经络也。现在四肢厥冷，宜以当归四逆汤加减。", "5903": "少腹作痛，甚则呕吐，脉右弦左紧俱兼数，舌苔浊腻，口中干苦，头胀溺赤。此湿热之邪内犯肝经，挟痰浊上升所致。泄之化之，得无厥逆之虞为幸。", "5904": "再诊：呕吐已减，白苔稍化，头胀身热亦缓。惟腹之作痛、便之下痢、脉之紧数，以及口中之干苦、小水之短赤，尚不肯平。肝经寒热错杂之邪，又挟食滞痰浊为患也。仍宜小心。", "5905": "肝脉布于两胁，抵于少腹，同时作痛，肝病无疑。肝旺必乘脾土，土中之痰浊湿热，从而和之为患，势所必然。", "5906": "气结于左，自下而盘之于上，胀而且疼，发则有形，解则无迹，甚则脉形弦数，口舌干燥，更属气有余便是火之见证，急须化肝", "5907": "再诊：病势不增不减，诊得左脉细涩，右部小弱。气血久虚，致使营卫失流行之象，非大建其中不可。", "5908": "邓评：此寒入厥阴之候，其脉当见迟细弦象。", "5909": "狐疝，原属肝经之湿，随气下陷，脾阳必衰。而今夏多食冷物，阳气又被所遏，苔白不干，指冷脉小，右睾丸胀大，当以温散。", "5910": "寒气客于肠外，与血沫相搏，脐下结瘕，胀大下坠，不时作痛，痛则气升自汗，脉形弦涩。此为臌胀之根。毋忽。", "5911": "脉来细而附骨者，积也。已经半载，不过气行作响而已。而其偏于胁下者，牢不可破，是寒食挟痰，阻结于气分也。此等见证，每为胀病之根。", "5912": "食入而痛，是有积也。积非一端，就脉弦数、二便黄热、干咳不爽、面黄苔白言之，必有湿热痰食互相阻滞，经年累月，无路可出，无力以消。", "5913": "邓评：据此症脉，是火被寒郁，为郁火腹痛之候。然食入而痛，或有蛔动于中也，以并无食积见端耳。拟加椒、萸、梅、连之属。", "5914": "寒热后，脘左隐癖作疼，脉形弦细，舌苔浊厚。湿热痰食，交相为患。", "5915": "邓评：起于寒热之后，内有留邪可知。惟癖疼偏左，脉细兼弦，此湿热痰食之中，更必挟肝气为患也。宜参金铃子散兼平其肝。", "5916": "脘腹膨胀，二便失调，经络酸痛，四肢无力，脉形弦细，舌苔白腻而厚。此湿邪内郁。当用苦辛宣泄。", "5917": "脉细而弦，是脾弱而兼木郁；苔白而腻，知湿胜且有热蒸，俾湿热化解，脾健木达，则诸恙向安矣。", "5918": "脾主湿，湿因脾虚而郁，郁蒸为热，所以隐癖僭逆中宫；大腹胀满，纳少便溏，面黄溺赤，咳嗽，身热时作，脉息弦细，极易成臌。", "5919": "原注：以上越鞠丸证。大约越鞫治无形湿热之痞，从泻心化出；鸡金治有形食积之癖，从陷胸化出。且如脘痛门中，郁痰作痛，脉数多渴者，用清中蠲痛汤。山栀、姜汁炒，干姜、川芎、童便炒，黄连、姜汁炒，苍术、童便浸切麻油炒，香附、醋炒，神曲、姜汁炒，托红、姜、枣。治中脘火郁作痛，发即寒热。中以寒热为主，即越鞠加姜、连、橘、枣。可知此方治气火湿食血五者之郁，信极妙矣。说者以栀主火，术主湿，香附主气，芎主血，曲主食，分为五郁，似可不必，正如五音必合奏而始和也。", "5920": "大腹胀满，已经四十余日，近来气更急促，足跗浮肿，溺黄口干，脉形弦数。湿热之邪，因气而阻，因食而剧，理之不易。", "5921": "邓评：大腹胀满是病也，溺黄口干是证也，脉形弦数是脉也。凭证脉以推求，则是病之系乎何邪，自无遁情矣。", "5922": "大腹主脾，腹大而至脐突，属脾无疑。然胀无虚日，痛又问作，舌苔薄白，脉息沉弦，见于经期落后之体，显系血虚不能敛气，气郁于中，寒加于外，而脾经之湿，因而不消。", "5923": "邓评：脉息沉弦，尚非血虚不能敛气之比。", "5924": "附桂理中汤加肉果当归牡蛎木瓜茯苓生脉散", "5925": "邓评；虚寒腹胀，固当责之脾肾。至偏于肾虚或偏于脾虚，须观其胀处之甚于小腹，抑或脘腹矣。参入生脉者，想其舌光苔微也。", "5926": "大腹胀满，便溏，舌苔冷白，干喜热饮，肤热脉数。脾阳大虚，无力运化湿浊，而成臌也。理之棘手。", "5927": "邓评：脉弦、妨食、气短，似乎寒饮之内，更挟木气之郁。", "5928": "温补元阳，浮肿胀满有增无减，阳之衰也极矣。脐平脉迟之候，非温不可，非补亦不可；然温补亦不见长，盖下泄者肾更伤耳。", "5929": "邓评：此等方法，非洞彻病情者则不可浪用。必须脉形洪数者，始能放胆用之，恐其湿热未去而中阳已惫也。", "5930": "中阳不足，寒湿有余，脘痞纳少，舌白便溏，脉细小。法当温化，即平为妙。", "5931": "素有隐癖，肝脾之不调可知。去年血痢于下，痞结于中，久未向愈，大腹胀满，溺赤舌黄，脉形弦细而数。湿热内聚，脾虚无力以消，极易成臌。毋忽。", "5932": "脉弦数大，苔厚中黄，头痛及旁。阳明湿热，挟胆经风阳上逆也。", "5933": "邓评；证惟风阳上升，药惟滋熄和阳。而舌绛脉数，亦从可知矣。", "5934": "肝居人左，左胁不时攻痛，甚则厥逆，左关沉小带弦，是肝气郁而不升也；右脉弦滑，舌苔薄白，喜饮热汤，又有湿痰内阻。当兼治之。", "5935": "脉沉弦滑，腿骱刺痛，腰部疫疼，背脊作响，诸节亦然，舌苔白浊。风湿痰三者著于肝肾之络也。", "5936": "邓评：断其为风湿痰实邪者，全于苔脉得之。惟风善上行，今所以陷著肝肾之络者，内被湿痰阻遏故也，岂得拘一例论之。", "5937": "肾者主蛰，封藏之本，精之处也。精之所以能安其处者，全在肾气充足，封藏乃不失其职；虚者反是，增出胫酸、体倦、口苦、耳鸣、便坚等证，亦势所必然。然左尺之脉浮而不静，固由肾气下虚；而关部独弦独大独数，舌苔黄燥，厥阴肝脏又有湿热助其相火；火动乎中，必摇其精，所谓肝主疏泄也。虚则补之，未始不美；而实则泻之，亦此证最要之义。", "5938": "邓评；湿热助其相火，为此症之要旨，于关尺脉与舌苔上见出。故肾脏虽虚，尤必须参实则泻之之法矣。", "5939": "再诊：大便畅行，口中干苦亦愈，左关之脉大者亦小。惟弦数仍然，尺亦未静。可以前方增损。", "5940": "邓评：炎上作苦，火能下降，故口苦亦愈。惟脉尚弦数未静，是以苦寒泻火，还当著意。", "5941": "邓评：三诊似乎湿热已去，当以守中。谁知邪势初衰之际，须防余邪未尽，所谓炉烟虽熄，灰中有火，故至此脉象复见弦数，仍不能舍苦寒泻火之剂也。当邪势初衰，速尔进补者，每有此弊。", "5942": "四诊：大便已和，脉形弦数，数为有火，弦主乎肝。肝经既有伏火，不但顺乘阳明，而且容易摇精。精虽四日未动，究须小心。", "5943": "再诊：接来劄，知所言梦遗者，有梦而遗者也，比之无梦者，大有分别。无梦为虚，有梦为实。就左脉弦数而论，弦主肝，数主热，热伏肝家，动而不静，势必摇精。盖肾之封藏不固，由肝之疏泄太过耳。", "5944": "三诊。迭进封髓秘元，而仍不主蛰。细诊脉息，左关独见沉弦且数。肝经之疏泄显然。", "5945": "曾经失血，现在遗精，精血暗伤，当脐之动气攻筑，漫无愈期，肢体从此脱力，语言从此轻微，饮食从此减少，无怪乎脉息芤而无神也。病情如此，虚已甚矣。而舌苔腻浊，中宫又有湿邪，治须兼理。", "5946": "白浊久而不痊，以致肾失封藏，梦遗更甚，少寐少纳，面痿脉小。", "5947": "阴虚之体，心火下郁于小肠，传入膀胱之府，尿中带血，时作时止，左脉沉数，小水不利。", "5948": "再诊：所下之淋，薄且少矣，而当便之时，尚属不利，既便之后，反觉隐痛，肢膝不温，脉小弦，唇红嗌干。热未全消，虚已渐著。", "5949": "曾患淋证，小便本难，近来变为癃闭，少腹硬满，小便肿胀，苔白不渴，脉小而沉。下焦湿热，被外寒所遏，膀胱气化不行，最为急证，恐其喘汗。", "5950": "邓评：苔脉属寒，故宜温通为佐。", "5951": "飧泄不由乎胃滞，即系乎阳弱，此乃兼而有之，脉迟，嗳腐脘痛。", "5952": "邓评：未可以脉迟，便谓系乎阳弱，或者阳气窒滞有之。且脘痛之证，不免木气内阻，中挟相火，附子一味，极宜慎用。", "5953": "肠游便血，时重时轻，或痛或否，脉形细小，饮食少。此虚也，恐增浮喘", "5954": "便血之前，先见盗汗，盗汗之来，由于寒热，寒热虽已，而盗汗便血之证不除，脉小而数。气阴两虚之病也。", "5955": "邓评：凡血内溢者，病源甚多。大都见证面黄兼白，浮肿眩悸、肢酸力乏。惟血色淡红而非深赤，脉象虚濡而不弦实，阳分受伤偏重者，附子始能合用，否则有助火灼阴之弊。", "5956": "湿热伤营，腹臌便血，久而不愈，左脉细涩，右芤、寸大尺小；加以浮肿，气分亦虚，不但不能摄血，而且不能清化湿热。防喘。", "5957": "病将一载，肝气横逆而不平，中气久虚而不振。惟肝逆，故胸脘阻塞而攻冲；惟中虚，故营卫不和而寒热。凡大便溏、饮食少、右脉细、左脉弦，是其证也；四君子合逍遥、加左金，是其治也。", "5958": "邓评：论证明晰，用药不紊。惟寒热而便溏，脉细弦者，总宜兼温理脾胃营卫，如桂枝、煨姜、大枣之类；肝逆攻冲，金铃子亦在需用。方内川连或可删去。", "5959": "邓评：推论病源，不外乎是，制方亦极精切不泛。脉虽未见，而关尺想必弦大且数。", "5960": "骨格瘦小，先天元气不足。夏秋寒热，至今不已，脉细数弱，气血两亏。头不痛而但身痛，或口沃清水，此胃阳虚惫也。当商温补，仿东垣法。", "5961": "邓评t脉既细数，似宜兼养营阴。不及转方为妥善。", "5962": "左脉空大，肾水亏也；倦怠无力，脾气弱也；食少则阴虚，阴虚生内热，证属内伤。", "5963": "诒按：补中益气补脾气，六味补肾阴，立法颇切实。惟左脉空大，方中升柴两味，尚宜斟酌耳。", "5964": "邓评，左脉空大，不但肾水亏，更知肝阳旺，若再投以升柴，深恐阳升至极，而卒致晕厥矣。", "5965": "两手关脉，皆见一粒厥厥动摇之象。此土虚木胜，内风动跃之候也。左半肢体，麻木不仁，头眩面麻，病属偏枯，虑延仆中首乌当归白芍茯苓陈皮秦艽菊花天麻石决明钩钩刺蒺藜桑枝邓评：论病有卓识，立方亦精到。再诊{动摇之脉大减，内风有暗熄之机，左手屈伸稍安，左足麻木未和。拟补肾生肝，为治本之计。", "5966": "再诊：肺为水源，百脉朝宗于肺，犹众水朝宗于诲也。肺热叶焦，则津液不能灌输于经脉，而为痿蹙。、卧床不能行动，形肉消削，咳嗽痰臭，舌红无苔，脉细而数。是皆津液消耗，燥火内灼之象。考经论治痿独取阳明者，以阳明主润宗筋，胃为气血之源耳。今拟生胃津以供于肺，仿西昌喻氏意", "5967": "邓评：据此苔脉，火灼阴损已极。然风寒究竟闭郁，倘痰黏厚而腥臭重者，如萎蕤汤法，亦可出入仿用乎。愚不揣鄙陋，粗备法则，以侯有识者采择。", "5968": "盖士君子有济世之心者，必托经世之术以运之，遇不遇无论也。何也？得时而驾，则宇内之休戚利害，隐然共之，视其患若切于身之疾痛疴痒，不措之安全不止。此士君子之心，得位以行之者也。不幸不获遇，泽不及物，而心不得施，有志君子，往往怀其道而隐于医。故是昔人谓济人利物，无位者不能，惟医以救死扶生为功，故业之者，可以推不忍之心及于物，而于道有益。有味乎其言之也。然医岂易言哉？吾闻其宗旨，自《内经》、本草以来，书之藏于有司者，一百七十九家。非博通巨儒，超悟上哲，专攻其业，何能探讨？洞明其阴阳、寒热、静躁、虚实，消息盈缩之奥，而措之行事。夫人之待命于医，生死攸系，乃以未谙浅薄者尝试之，其不贼人之命者几希。医以济人，至于贼人，可不畏耶!此医之所以难言也。余顷多病，谒告山居，尝叹济物之衷未措于用。顾思延医以求济其身。然而医之良者，苦不一遇也。乃壬申仲秋，吴君柳溪，谈新安海阳有孙君东宿者，医可谓称良矣。余亟请而相印证之，耳其论沨沨乎《素》、《难》之旨，而表里夫张、刘、孙、李、丹溪、伯仁诸家。其视余疾也，未投药，先谈余之经络、色脉、机能，与受病之自，即勿药而余病爽然若失。及详察其端方之度，沉著之思，渊渊之阃奥，则杳焉莫竟其涯。非所谓深于道而隐于医者耶!余因诘之曰：神农尝百草，先天而命之药，黄帝、岐伯，后天而著之经。此天以神授，圣以神符，不可及矣。嗣后若和、扁、华佗、淳于意、仲景、思邈、河间、东垣、朱、滑，莫不簸弄化机，制人命于掌上，术亦神也。何今日之事是业者，不能踵其芳躅耶!抑世代之不同也？孙君勃然曰：古今人非不相及，用心殊尔!宋儒有言，古之仁者为人，今之仕者为己。不佞亦谓古之医者为人，今之医者为己，道不同而受病一也。夫士君子之视天下，与吾身血脉相流通，天下病，若痌瘝之切身，天下安，则惬然而无恨。虽以道为药石者，其济宏，以医为道术者，其济狭，其心一也。故古之医也，以救死扶生之心，其业专而用方也慎。专则精而造诣入室，慎则审而投药奏功。此和、扁诸名家，所以悉臻秘妙，称神奇。今之医，则异是也。将以市利，非以济人。黄、岐以来诸书，非不剽窃以资口说，乃其心则实胡越一膜视天下，率以利之盈绌，为心之重轻。人之济与否，若与吾术不相关，此何以比古人而接其芳躅哉？不佞奎何能造古贤哲之阃奥，第无愧于此心尔!余闻而喟然叹曰：孙君充是心而行是术，其将大有裨于时矣!虽隐而亦显也。因次其语而归之，爰以订夫业是术者，是为序。", "5969": "万历龙飞二年小春月，予始游苕之东双林。于时，族兄吉泉之友吴小峰与其弟小川俱病目，专科者愈治愈重。其目始红肿，次加太阳痛，继则白星翳叠出。予不以目科名，而识者称予大方，因谋于吉泉曰：医以通变为良，昔秦越人过邯郸，闻贵妇人，则为带下医；过洛阳，闻周人爱老人，则为耳目痹医。闻东宿君国手也，必能随俗为变，愿一言去吾兄弟目疾。吉泉邀予，余曰：嘉靖间论医者，必首西吴，如周仲仁氏，凌汉章氏，王宾湖氏者，皆擅一时名，其家世必有传也，何需于予。吉泉曰：渠家慕弟久矣，且其尊人受博士易，为西吴名家，弟好易，幸一往，借此为谈易地，勿逊。诊其脉，小峰之脉，濡而缓大，两目血缕直贯瞳人，薄暮则疼。小川之脉，皆洪大鼓指，黑珠有浮翳瘼，隐涩难开，大小便皆不利。故于小峰用补，先以清肝散与之。夏枯草五钱，香附四钱，甘草一钱五分，细茶五分，以彻其痛。药两进而痛止。继用人参、白茯苓、熟地黄、枸杞子、桂心、牛膝、破故纸、白蒺藜、牡凡皮。服八日而愈。于小川用泻，内用泻肝汤，及当归龙荟丸。外用象牙、冰片为末点之，七日痊愈。其尊君我峰翁喜诣余曰：二目均病，年同齿，染同时，诸医同治而同不愈，先生一补一泻，而二病均愈，何哉？余曰：此阴阳虚实之辨也。经云：实者正治，虚者从治。令侄之症，惟厥阴肝火炽盛，肝常有余，有余者泻之，正治也。郎君下虚，又为怒所激，怒则火起于肝，肝为藏血之地，故血丝贯瞳人，而薄暮作痛，方用夏枯草、香附为君，疏其肝气。经云：肝苦急，急食甘以缓之，故用甘草为臣。茶能清头目，用以为使，先为去此痛。经又云：水流湿，火就燥，故复用甘温补其下元之虚，俾火得归元，此从治也。若用苦寒降火之剂，不惟血凝而痛加，抑且激其火而使愈炽矣。我峰闻之，语人曰；孙君本阴阳而治寒热，是用《易》为医也。故补者补效，攻者攻效。语曰：不知《易》者，不可以为太医。孙君神于《易》而于医乎何有，愿于吾苕悬一壶也。余哂之，谓：昔韩伯休且不欲人间知其名，余又何壶之可悬哉。", "5970": "万历甲戌，其年自仲秋徂冬，瘄子盛行。三月内，予所治男妇婴孩共七十二人，苕之望族沈最著，大中丞观颐公当考功时，幼君瘄，喘嗽不宁，声哑，发热，泄泻，斑紫不敛。予以小无比散愈之。夫人妊，腹痛昏厥者五日，名医如高、陈二公者，沈姻娅。无巨细悉任之，亦不能措手。予至诊之，两手脉皆洪大，法当下，众佥以妊难之。予曰：经云有故无殒，亦无殒也。妊已九月，将解，即胎动奚伤？若当下不下，不独其痛难忍，而变且不测。考功是予言而请药，予即用小承气汤加苏梗、砂、仁，下之而安。考功偶冒风，头痛倦怠，发寒热如疟，脉弦浮而数。予曰：此小柴胡汤症也，一剂而瘥。考功请告家居者二十年，笃好方书，予初之苕，苕人未知予，考功闻予，亟欲识之，谓予治病甚奇，又与予论伤寒、痘疹、胎产皆中窾，深然之。语人曰：良相良医等尔，如孙君所诣，即千金不足为其重，特撰医说书于册，以不朽孙君云。", "5971": "张孝廉后渠，丁年，患大头疫。头大如斗。不见项，唇垂及乳，色如紫肝，昏愦不知人事。见者骇而走，其年疫甚疠，人畏传染，致废吊庆。张与考功公子，同受《春秋》于会稽陶春源所，陶邀余诊之。其脉皆浮弦而数，初以柴胡一两，黄芩、玄参各三钱，薄荷、连翘、葛根各二钱，甘草一钱，服三剂，寒热退，弦脉减，但洪大。予知其传于阳明也，改以贯众一两，葛根、天花粉各三钱，甘草一钱，黑豆四十九粒，一剂，肿消其半；再剂，全消。浆粒不入口者二十一日，再与小柴胡汤两剂服之，始纳干糕如指者二条，次日进粥，而渐平矣。丁酉秋闱报捷。", "5972": "吴江孙质庵老先生行人，时患痛风，两手自肩髃及曲池，以至手梢，两足自膝及跟尻，肿痛更甚，痛处热，饮食少，请告南还，而伏蓐者三年。里有吴君九宜者，沈考功西席也。见予起后渠疾，因语行人逆予。诊其脉，皆弦细而数，面青肌瘦，大小腿肉皆削。予与言：此病得之禀气弱，下虚多内，以伤其阴也。在燕地又多寒。经云：气主煦之，血主濡之。今阴血虚，则筋失养，故营不营于中；气为寒束，百骸拘挛，故卫不卫于外。营卫不行，故肢节肿而痛，痛而热，病名周痹是也。治当养血舒筋，疏湿润躁，使经络通畅，则肿消热退，而痛止矣。痛止，即以大补阴血之剂实其下元，则腿肉复生。稍愈之后，愿加珍重，年余始可出户。行人闻而喜曰：果如公言，是起白骨而肉之也。吾即未药，病似半去，惟公命剂。予先以五加皮、苍术、黄柏、苍耳子、当归、红花、苡仁、羌活、防风、秦艽、紫荆皮。服之二十剂，而筋渐舒，肿渐消，痛减大半。更以生地、龟板、牛膝、苍术、黄柏、晚蚕砂、苍耳子、苡仁、海桐皮、当归、秦艽，三十剂而肿痛全减。行人公益喜。予曰：病加于小愈，公下元虚惫，非岁月不能充实。古谓难足而易败者，阴也。须痛戒洒色，自培根本，斯饮药有效，而沉疴可除。据公六脉轻清流利，官必腰金，愿葆真以俟之，万毋自轻，来春气和，可北上也。乃用仙茅为君，枸杞子、牛膝、鹿角胶、虎骨、人参为臣，熟地黄、黄柏、晚蚕砂、茯苓、苍耳子为佐，桂心、秦艽、泽泻为使，蜜丸服，百日腿肉长完，精神复旧。又喜语予曰：贫官何以称报，撰次公济人泽物盛德于沈考功册后，以彰盛美云。后十年，行人官至江西副宪。", "5973": "张文学子心，二尹可泉公长君也。自知医，弱冠病，吴下名医皆诊之，佥曰瘵，治久不效。子心亦自分必死，督家人具秘器，已沐浴，衣襚衣而卧正寝，断粒、绝药者二日。可泉闻予治其高第张星岳之婶奇，因访予曰：病心痹而尸寝浃旬者能起之，谁不啧啧称公高手，吾子病且革，幸怜而诊之。予至，诊其脉，左寸短弱，右关略弦，余皆洪大。其症咳嗽，下午热从两足心起，渐至头面，夜半乃退，面色青，形羸气促，多梦遣，交睫卧床褥奄奄一息耳。时则七月初旬也。诊毕，语可泉公曰：郎君病可治，不宜豫凶器也。可泉公曰：诸医佥谓火起九泉者，十不救一，大肉尽削者死，咳嗽加汗者死，脉不为汗衰者死，又当此铄石流金之候，又恐肺金将绝。豚子亦自谓无生理，先生何言可治也？予曰：汗多者，孤阳几于飞越也。可泉公曰：飞越亦死候也。予曰：几者，将成未成之辞也。症虽危，其色、其声音、其脉，尚有生意。终不可以一凶而废三善。两颧不赤，心火未焚也；声音不哑，肺金未痿也：耳轮不焦，肾水未涸也。相书云：面青者，忧疑不决：左寸短者，心神不足：关略弦者，谋为不遂。夫心者，万世万化之主，《内经》曰：主明则下安，主不明则十二官危。又肝主谋为，胆主决断。谋为不决，故色青。症与色与脉皆非瘵也。盖郎君志愿高而不遂其欲，殆心病，非肾病也。经曰：色脉相得者生。予故谓郎君之病可起也。病者闻言，明目语其父曰：吾今由寐者初寤矣!从来未有此论沁吾心脾也。吾病由星士许决科于癸酉，是年余落第，而同窗者中，故怏怏至此。先生得吾心于色脉，神矣!此言可当药石，谨拜命。予为定方，煎方名调肝益神汤。以人参、酸枣仁、龙骨为君，丹参、石斛、贝母、麦冬、五味子为臣，山栀、香附为佐，服二十帖而病起。丸方则大龟板、熟地黄、枸杞子、人参、麦冬、五味、茯苓，蜜丸，服三月而精神健，肌肉完。次年生女。可泉公，苕中名士，奇予治，而延誉闻于大宗伯董浔阳公，宗伯交欢予者，由可泉公始也。", "5974": "大宗伯董浔老，年六十七，有脾胃疾，翁以过啖瓜果而胸膈胀痛，时当处暑也。延予治。诊其脉，寸关弦紧，观其色，神藏气固。翁门下蒋虹桥、沈乐闲者，多艺人也，翁素亲信二公，诘余曰：症脉何如？予曰：症脉虽胸腹胀痛，然易瘳也。二公曰：翁生平不能素食，食辍泻。今不茹荤者半月，燕居好弈，好看书，好作诗文，即盛暑亦手一编不言倦，日永亦不瞌，今不亲笔砚者月余，不栉沐者七日，它一切无所事事，倦极矣。诸名家如沈竹亭、沈春宇、金樗丘者，剂备尝之无益也。而公何言易？予曰：诸公不过用二陈平胃，加山楂、麦芽等消导剂耳，与症何涉。盖翁伤于瓜果，而为寒湿淫胜。经云：寒淫所胜，治以辛温。然瓜果非麝香、肉桂不能消，此诸公所以不能愈翁疾也。予以高良姜、香附各一两为君，肉桂五钱为臣，麝香一钱为佐，每服二钱，酒调下之。药入腹，胸次便宽，再而知饿，三服而巾栉，交接宾客如未病者。翁语沈、蒋曰：孙君所见所养，度越诸人若是。往闻治张氏子，气绝两日而能活之，今于活吾病益信，诚临淄虢国之遗，特书一轴以彰其高，因以纪一时之良遇云。", "5975": "大宗伯郎君董龙山公夫人，为宪副茅鹿门公女，年三十五而病便血，日二三下，腹不疼，诸医诊治者三年不效。予诊之，左脉沉涩，右脉漏出关外，诊不应病。予窃谓，血既久下，且当益其气而升提之，以探其症。乃用补中益气汤，加阿胶、地榆、侧柏叶，服八剂，血不下者半月。彼自喜病愈矣。偶因劳而血复下，因索前药。予语龙山公曰：夫人之病，必有瘀血积于经隧，前药因右脉漏关难凭，故以升提兼补兼涩者，以探虚实耳。今得病情，法当下而除其根也。龙山公曰：三年间便血，虽一日二三下，而月汛之期不爽，每行且五日，如此尚有瘀血停蓄耶？予曰：此予因其日下月至而知其必有瘀血停蓄也。经云：不塞不流，不行不止。今之瘀，实由塞之行也，不可再涩。古人治痢，必先下之，亦此意也。公曰：明日试卜之。予曰：卜以决疑，不疑何卜？公随以语夫人，夫人曰：孙先生非误人者，识见往往出寻常，宜惟命。盖夫人读书能文，聪明谋断，不啻丈夫，故言下便能了悟。即用桃仁承气汤，加丹参、五灵脂、荷叶蒂，水煎，夜服之，五更下黑瘀血半桶，其日血竟不来，复令人索下药。予曰：姑以理脾药养之，病根已动，俟五日而再下未晚也。至期复用下剂，又下黑血如前者半，继用补中益气汤、参苓白术散，调理痊愈。", "5976": "大宗伯董浔老门下有马厨者，七月初旬病。病二十余日愈剧，而势甚獗。时宗伯对余弈正酣，而蒋虹桥、沈乐闲报曰：马厨危在旦夕。宗伯闻之，推枰叹息曰；吾命吾命!予叩其故，语曰；能厨者，不下二十人，独此厨适吾意，将恃之以怡晚节，今病不可起，奈何？予诘何病，翁顾蒋与沈曰：第详道其状。蒋、沈述其症，大发寒热，寒至不惮入灶，热至不惮下井，痢兼红白，日夜八十余行，腹痛、恶心、汗多，神气倦甚。究其脉，曰；脉不吉，下痢脉洪大者死，细微者生，今洪大逆也。予曰；痢固忌洪大，寒热亦非细微所宜，其中必有故。二公曰：幸一往决之。浔翁不可，谓何可以细人而劳长者。予曰；医寄人生死，何论巨细，矧事翁之人，犹不可坐视不救也。浔翁欣然握余手偕行，至宅后桥，余入门，同居数十家，皆执香拱立以伺。诊其脉，察其症，果如蒋、沈所言。其面色微红，汗淋淋下。予究病所由起，渠谓过客众，厨间燥热，食瓜果菱藕过多，晚又过饮御内，而寝于楼檐之下，次日即寒热腹痛，因而下痢。虽得其病情，尚未融通一治法，因沉思之，不觉行至桥，而浔老犹立而俟予，见予无婉容，知病重，遂置不问，如前握余手而回。蒋、沈问余可治否？予曰：侥幸先生宠灵，偶有一得，乃背水阵也。人参、白术、石膏、滑石各五钱，知母、炮姜各三钱，大附子、炙甘草各二钱，作一大剂煎之。蒋、沈将问予，浔翁即命近侍煎于其侧，不欲蒋、沈问也。熟则付饮之，饮讫即睡。老先生曰：服后何状为佳？予曰：倘得一睡，则阴阳始和，和则汗可敛，而寒热呕恶可止也。蒋、沈曰：闻已睡矣。明日巳刻，二公鼓掌来言，夜来痢减半，汗吐全无，脉亦敛矣。再用人参、石膏、白术、白芍药、滑石各三钱，炮姜、肉桂、知母各二钱，炙甘草、附子各一钱，服后疟止，痢又减半，饮食渐进，神气渐转。改用白芍药酒炒五钱，人参、白术、滑石各二钱，甘草、陈皮、炮姜、肉桂各一钱，三剂而痢全止，饮食加，渐就安矣。蒋、沈问曰：公寒热均投，此为何症？而剂何名也？予笑曰：此滑公所谓混沌汤也。浔老又问，予对曰：经云：夏伤于暑，秋必疟痢。白虎汤、益元散皆解暑之剂。瓜果寒凉伤其中气，酒后御色，损其下元，附子理中汤正所以温中补下者。《内经》又云：实者，邪气实也。故以白虎汤、益元散应之。虚者，正气虚也。故以理中汤应之。若以寒热均用为疑，而张仲景附子甘草泻心汤，即用大黄、黄连，又用干姜、附子，此何说哉!盖假对假，真对真也。浔翁跃然喜曰：先生惟是，故能起垂毙之人而生之，余诗册中临淄虢国之谈，非虚语矣。", "5977": "吴江吴太仆长君肖峰令政，太宗伯董浔老次女也。患咳嗽、体倦、多汗、腹痛，呻吟不绝口者半月，吴江之医不效，访远近名最著者，如姑苏盛氏后湖，王氏后山，震泽沈氏竹亭，先后递治之而痛愈加。予适寓苕城，龙山公邀予乘快舡兼程而进。至则诊其脉，左手三五不调，右手沉弦，面色青而息甚微，腹中漉漉有声。予因问上年夏月曾病否？肖峰曰：曾头痛体倦多汗，动止无力，不能亲事，但不咳嗽，不腹痛。今五月初，病如上年，而市医谓伤风所致，用参苏饮表之，始咳嗽。沉为其清嗽，则加腹痛；王与盛谓通则不痛，以沉香滚痰丸下之，则势惫而不可支。予方殚思，谓此乃疰夏病。仲景谓春夏剧，秋冬瘥者是也。而龙山公诘问：疰夏何为咳嗽？予曰：原不咳嗽，由参苏饮而咳嗽也。汗多又重发汗，肺金受伤，故燥而嗽。何为腹痛？予曰：原不腹痛，因治嗽而寒其中气，腹故痛也。后事者，又不究其因寒而痛，乃谓通则不痛，而用寒凉滚痰之剂，重伤其中气。不思五月六阳之气皆散于外，汗而又汗，汗多则亡阳，夏至一阴将萌，腹中尚虚，虚而复下，下多则亡阴，阴阳俱亡，不惫何待。予欲酌一方以起之，恐从事者又将议其后。龙山促之，乃用洒炒白芍五钱，甘草、黄耆各三钱，桂枝二钱，大枣二枚，水煎，临服加饴糖一合。吴下诸公，果群然又辩。龙山公曰：不必辩，病者望此以苏其生，速煎饮之。饮讫而睡，自已至申不醒。先事者，皆摇首，命仆急携药囊将去，且语龙山公曰：夺令妹之速者，孙君也。《本草》云：夏不用桂，伐天和也。诸痛不补，助邪气也。故一饮而不醒，吾侪行矣。龙山公以其言语余，因诘病者之熟睡。予曰：所善者，以其睡也。睡则阴气生，阴生则汗可敛，痛可止也。假令药不对症，安得有此。又诘所投之剂何名。予曰：此仲景小建中汤也，出《金匮要略》。盖建者，立也，中者，阳明所主，今腹痛如缚，带脉急缩也。东垣治例，腹痛以芍药为君，恶寒而痛，加桂。甘草，缓带脉之急缩，用以为臣。经曰，急者缓之。面青脉弦，肝气盛也，肝属木，木盛则脾土受制，而又误下，因伤之极，故痛之猛也。经云：木得桂而枯。佐以黄耆，伐肝补脾，又能敛汗止痛，此建中之所由名也。语未竟，内报病者醒而索粥，予曰：与之，谷气进则有本矣。粥后又睡。至天明，腹全不痛，惟稍咳嗽，加五味子、麦门冬，兼治疰夏而全瘳焉。龙山公述病之始末，剂之药味，报大宗伯，宗伯公致书于予曰：足下以四味之常药，振不起之危疴，名震三吴，声溢两浙。昔宋景濂为朱丹溪立传，吾固不敏，幸先生以所治节条敷之，俾序以传于后，俾工是术者，有所籍乎!予怃然语龙山公曰：何修而得老先生宠幸之深也。第令妹被克伐太过，阴阳俱亡，今病虽愈，而脉弦不退，犹可为虑，幸叮咛戒暴怒、节饮食，谢去人事，恬澹多补，庶可永年。不然亥月阴极阳生，恐不能保无患也，慎之慎之。后至期，与肖峰龃龉，怒而绝药，果以凶闻。苕人多予之直与先见云。", "5978": "大光禄庞公子远，吴江人也。其太夫人病头痛恶寒，胸膈懑且痛，时发寒热。吴医王后山者，有时名，吴人最所笃信。延治五日不瘥。闻予居吴，礼致为治。诊其脉，右滑大，左浮弦而数。问服何剂？光禄公曰：不识，而有药在。予视之，偶失言曰：左矣!时有西席项姓者，闻言而厉声曰：此三吴最名士也。渠发剂而有议者，辄面唾之，幸不在尔。予笑曰：渠是而议者非，则当唾人；渠非而议者是，是自唾且不暇，何暇唾人。四物汤、玄胡索、牡丹皮、香附子，养血调经剂也。太夫人七十余矣，而有经可调哉!投剂之左，由生平守常套，而不知因人因症随俗为变也。项子曰：此何症？予曰：仲景有云，头痛恶寒，外感病也。浮弦而数，胸膈懑痛，少阳脉症俱在，右脉滑，饮食滞而为痰。彼用当归、地黄、芍药，皆滞痰闭气之味，内伤何由得消，外感何由得出？此症只宜用柴胡汤合平胃散，一二帖可瘳也。项犹有言，光禄公曰：勿辩，饮药而泾渭明矣。一饮而寒热除，再饮而胸膈泰。光禄喜曰：奇公名不虚附矣!予私问项子何极誉王？光禄曰：项初受业于王，未睹大方，而独是其师说，多见其识之不广也。", "5979": "光禄公后有事于庄所，值中秋，乘酒步月，失足一跌，扶起便胁痛不能立，昼夜不宁，行血散血活血之剂，一日三进，阅三月服二百余帖，痛不少减，因迎予治。诊之，脉左弦右滑数，予曰：此痰火症也。公曰：否，贱躯虽肥，生平未尝有痰，徒以遭跌，积血于胁间作痛尔。予曰：据脉，实痰火也，痰在经络间，不在肺，故不咳嗽，而亦不上出。脉书云：滑为痰，弦为饮。予据脉而认痰火。如瘀血，脉必沉伏，或芤或涩也，面色亦必带黄。前诸君认瘀血治者，皆徇公言，不以色脉为据。且多服峻厉克伐破坚之剂无效，此非瘀血之积明矣。公欣然请药，即用大栝蒌壳者二枚，重二两，研碎，枳实、甘草、前胡各一钱，贝母二钱，与四帖。公以为少。予曰：愚见犹以为多，此症服之一二剂可瘳，又即报我，为制补益之药可也。公得药一更矣，仍煎服，五更腹中漉漉有声，天明大泻一二次，皆痰无血，痛减大半。再服又下痰数碗许，痛全止，随能挺立。三服腹中不复有声，亦不泻。盖前由痰积泻也，今无痰，故不泻。公曰：望闻问切四者，医之要务，人人皆著之口吻，有先生独见之行事，即予母子之疾，先有事者，皆吴之名流，微先生，吾殆撞壁矣!何能还辕而生哉，吾于是益服先生之高。", "5980": "进贤三尹张思轩公，与潘少保印川公，皆受室于施氏，称联襟云。施故富家，而张公夫人贤慧，治家勤笃，为人精洁周致，以产多而气血惫，又以婚嫁繁，而费用不支积忧，年将五十，因病心痹，发则晕厥，小水短涩，胸膈痛不可忍，烦躁，干哕恶，内蒸热，气苾苾上腾，肌削骨立，月汛不止。苕城时辈，有认为气怯者，有认为膈食者，皆束手无措。尸寝浃旬，浆粒不入口者五日，凶具备而待毙，举家计无所之，惟神是祷。予适在潘府，逆予诊之，脉左弦大，右滑大而数。诊毕，予曰：可生也。病机云：诸逆吐酸，皆属于火；诸风掉眩，皆属于木。法当调肝清热，开郁安神。诸医群然目摄而背谑曰：书云骨蒸肉脱者死，形瘦脉大胸中多气者死，绝谷食者死。孙君独许其生，果药王再世哉。予若不闻，而捡药以进。竹茹、滑石各三钱，白豆蔻仁七分，半夏曲、橘红、姜连、茯苓各一钱，甘草五分，水煎，令一口口咽之。服毕，哕止晕定。次日用温胆汤调辰砂益元散三钱，服之，胸膈顿开，渐进饮食，小水通长，烦躁尽减，骎骎然安若无事。后用逍遥散、六君子汤，加黄连、香附，三越月而肌肉全，精神如旧。苕入骇然曰：能起此病，信药王矣。", "5981": "马二尹迪庵公，年五十五，以扫墓而过食鳗肉卷饼，心腹胀痛，市医不知用吐，而遽用硝黄下之，大便不行，胀痛愈增。继至者，又用木香槟榔丸，继又有下以小承气汤者，有下以大承气汤者。十日多，胀痛益甚，饮食粒不能进，大便并不行，小水亦仅点滴。后医又以大黄芒硝，多服不行，谓非白饼子不可。服五日，而胀痛尤加。又谓非备急丸不可，服三日，胀痛益不可当。又用甘遂、芫花、大戟、牵牛之属。服三日，不惟大便不行，并小便点滴亦无矣，胀不可言。众医大叫称怪。自三月初二日起、至是念二日矣。有名士王南野者，用灸法灸中脘三十余壮，毫不为动，因断其越三日为念五，戌时当弃人间。迪老四子皆逢掖，闻言涕泗。时有张太学怀赤者，迪老甥也，见予起张思轩夫人疾，喻亟请予。予至，观其色苍黑，神藏不露，声音亮，惟腹大如覆箕，不能反侧，诊其脉，两手皆滑大，两尺尤有力。究其受病之源，查其历服之药，予骇然以为未闻且见也。因思一治法，先用六君子汤，加木香、砂仁，参、术俱用二钱。乃旁有钱小松者，自称家世受医，见剂争之。予曰：非若所知也。彼犹喋喋诘予，谓：人言中满者，泻之于内，大小便不利者，当先利大小便，然欤？予曰：非人言，《素问》云云也。又云：诸痛不得用参术，苍黑之人尤忌。先生既知《素问》，奈何不用通而用塞也？予悄然不答，顾迪老诸子言曰：钱君拘儒常见，何能起尊君病，尊君非中满胀症，内伤症也。当始伤时，犹在上膈，法当用吐，《素问》云：在上者，因而越之是也。不用吐而用下药，以伤其脾，脾气伤则失运动之职，是以愈下愈伤，愈伤愈胀。不思脾气伤而神不为用，药不能行，以峻厉味益下之，是遵何说也？予因脾伤，故用六君子汤以醒其脾，木香、砂仁助其运动，再用吐法，吐出前药，予剂非治尊君之病，治诸君药也。予初欲为诸君讳，何钱君激予，而使暴其短哉。且予不虑大便不行，独虑行之不止也。钱又谬言：急则治标，今法用尽不能使一行，何以不止为虑？予曰：君试思，常人能服硝、黄几何？服巴豆、白饼子几何？今硝、黄服过五斤，巴豆、白饼子之属服过五、六两，又加甘遂、牵牛、芫花、大戟至悍至急之剂，幸而大便未行，药性未动，尚可为计。若一行，而诸药性动，譬瓶水底漏，其中能蓄点滴哉？危矣!钱又诘：迪老多服下药，而大便不行何也？予曰此易知之。始为食伤，继为药伤，所伤在上、中二焦，下元未损，故两尺脉尚有神气。《难经》曰：人有两尺，如树之有根也。《内经》曰：肾者，胃之关。盖肾主大便，观其色苍黑，神藏气固，皆由根本未动，赖此犹可为也。服药后，腹中大痛，予知其药力已动，改用人参芦、防风芦、升麻、桔梗各三钱，水煎服之，少顷，用鹅翎探喉中，令吐之。前服药物，一涌而出十数碗。病者以手加额曰：目前光矣。此巳时也。予曰：酉时大便必行，可预买人参数斤，以备不虞。至午进至宝丹一帖，以温中气，未申间，腹中汩汩有声，浊气下滚，倾刻间，腹宽数寸。至晚，大便行一次，小水略通。予即用人参、白术各五钱，炮姜三钱，茯苓二钱，木香、甘草各五分，陈皮一钱，令急煎服。四鼓又大便一次，小水继至，胀痛渐减。次日大便泻十次余，因以前理中汤剂为丸，与煎剂兼补，腹胀全消，饮食渐进，共泻七十二日，服人参二斤余。苕人闻以补收功，群然异之。而钱小松始帖然心服。曰：奇哉，奇哉!人多用攻，孙君独用补，人多用下，孙君独用吐。由见之真，而所投者确也。医可易言哉？今而后，知孙君之高矣。", "5982": "舜田臧公，吴车驾涌澜公岳也，年将六旬，为人多怒多欲，胸膈痞胀，饮食少，时医治以平胃散、枳术丸、香砂丸，不效，复以槟榔、三棱、莪术之类日消之，而大便溏泻，两足跟踝皆浮肿，渐及两手背。医又以其手足浮肿而认为黄胖者，以针砂丸与之，肿益加，面色黄且黑。自二月医至八月，身重不能动止，又有以水肿治者。车驾公雅善予，因延诊之。脉沉而濡弱，予曰：此气虚中满症也，法当温补兼升提，庶清阳升，则大便可实；浊阴降，则膈胸自宽。以人参、白术各三钱，炮姜、回阳、陈皮各一钱，茯苓、黄耆各二钱，泽泻、升麻、肉桂、苍术、防风各七分，三十帖而安。客有疑而诘予曰：此症，诸家非消导则淡渗，而先生独以温补收功，腹中积而为满为肿者，从何道而去也？予曰：胀满非肿满比也，故治不同。肿满由脾虚不能摄水，水渗皮肤，遍身光肿。今胀满者，先因中虚，以致皮胀，外坚中空，腹皮胀紧象鼓，故俗名鼓胀。盖由气虚以成中满，若气不虚，何中满之有？气虚为本，中满为标，是以治先温补，使脾气健运，则清浊始分，清浊分而胀斯愈也。", "5983": "金溪令净涵臧公尊堂太夫人，以季春眉寿，连看戏文二十余本，且多食鱼腥虾蟹，偶发寒热，三日不退。第四日，左耳前后及颊车皆红肿。第五日，右边亦肿。第六日，肿及满头，红大如斗，眼合无缝，昏愦不知人事，谵语若有邪崇，粒米不进者八日。举家惊惶，逆予为治。诊其脉，六部皆洪长而数。予曰：此大头疫也。即以贯众、石膏各六钱，柴胡、葛根各三钱，赤芍药、天花粉各二钱，甘草一钱，黑豆四十九粒，水煎服之。日进二帖，脉始减半，第九日，方进粥饮半盅。前药除石膏，又四帖而安。是役也，人皆为予危之，谓八十之尊年，八日之绝粒，头大如斗，体热如燔炭，昏愦谵语，乃不去而治，何冥行不知止如此!而其婿闵怀海亦言病势如此，吾心亦危疑，见先生安闲而甘寝食，赖以少慰。予曰：此疾为阳明、少阳二经热壅而然。夫阳明多气多血之经也，以高年故不敢用硝黄，惟投以轻清解散之剂，使因微汗而解。症脉相对，虽重可生。假如人言以高年病危而弃不治，岂惟非医之存心，于病家相托之意亦孤矣，可乎哉？", "5984": "丙申夏，见所潘公谒予于海阳邑邸，时霪浃旬，邑市水涨。公至，予惊问曰：公贵倨也者，何堪此？公曰：与君间者阔矣，且先君服阕，秋当北上，不卜补任南下，谒求一诊，他何计？予究何疾。公曰：无，第年甫逾疆，微觉阳萎。次早诊毕，语其随行俞金二字曰：公脉上盛下虚，上盛为痰与火，下虚为精元弱，切宜戒色慎怒，剂宜清上补下。不然，三年内恐中风不免。盖由痰生热，热生风也，谨之识之，乃为立方。别去，公亦未暇制服。公次年八月，往返武林，不无劳怒，又届中秋，连宵酒色。平常色后，辍用鹿角胶三钱，人参一钱，酒送下。以连宵有犯，乃用鹿角胶五钱，人参三钱，空心服之，十七日薄暮，偶与社友谈诗，筵间，左手陡然颤动，把捉不住，随归房，左手重不能举，十八日早，左边半体手足皆不为用矣。亟令人逆予，予适在前丘吴宅，及至，公惊喜交集曰：君何先见若此也，先少保患在左体不遂者，三年而殁，不佞今亦左体，其风水致然欤？第先少保年七十余，不佞四十有七；先少保不能遇先生，不佞赖有先生，或可企无恙也。予始观面色赤，口微㖞向右，唇麻，手足軃拽，已成瘫痪。诊其脉，左弦大，右滑大。先用乌药顺气散一帖，服后昏睡半日，醒觉面更加赤，㖞也稍加，知痰盛使然。即以二陈汤加全蝎、僵蚕、天麻、黄芩、石菖蒲、红花、秦艽、水煎。临服加竹沥一小酒杯，生姜汁五茶匙，一日两进，晚更与活络丹。服至第六日，手指梢头略能运动，足可倚棹而立。予喜曰：机动矣!改用归芍六君子汤，加红花、钩藤、天麻、竹沥、姜汁，服二十帖，行可二十步矣，手指先麻木不知痛痒，至是能执物。继用天麻丸，兼服全鹿丸，调理百日，病去十之九，次年二月，北上补任永清。公以病后，能戒色断酒，自知培养，故药功获奏。此症予历治历效者，良由先为疏通经络，活血调气，然后以补剂收功。惟经络疏通，宿痰磨去，新痰不生，何疾不瘳。此治类中风之法也。", "5985": "见所公弱冠，随尊君大司马印老治河居北。患白浊，精淫淫下。自北地山东、淮扬、镇江及江右三吴诸名家，医药三年不效。癸酉冬，礼予诊之。其脉两寸短弱，两关滑，两尺洪滑，观其人襟期潇洒出尘，而神色闲雅，真翩翩佳公子也。一接见，便就暱而信余请药。予曰：公疾易愈，第待来春之仲，一剂可瘳，而今时不可。公固请曰：先生大方，而善拯人之急。以大方而治小疾，试可立效，何待来年？予曰：非秘其术不售也。《素问》有云：升降浮沉必顺之。又曰：天时不可伐。公脉为湿痰下流症也。经曰：治痰必先理气。而脉书亦谓，洪大而见于尺部者，阳乘于阴也。法当从阴引阳，今冬令为闭藏之候，冬之闭藏，实为来春发生根本，天人一理。若不顾天时而强用升提之法，是逆天时而泄元气，根本既竭，来春何以发生？故《素问》曰，必先岁气，毋伐天和，必养必和，待其来复。公疾本小，而历治三年不效者，良由诸医不知脉、不识病、不按时也。公闻言唯唯。乃尊君所遣之医踵接，治竟无效，至春分而逆予，以白螺蛳壳火煅四两为君，牡蛎二两为臣，半夏、葛根、柴胡、苦参各一两为佐，黄柏一两为使，面糊为丸，名曰端本丸。令早晚服之，不终剂而全愈。公复书曰：贱疾果如先生言，今勿药也，何历治三年不效。窃谓天下无药，服端本丸而愈，又信天下有药矣。", "5986": "少司空凌绎老夫人蒋，适绎老无几，腹胀痛，发热，经过期不行者五日。诸医皆以经期作痛，为调经不效。而绎老召予诊。左寸洪滑，两尺皆滑数，左尺之外，更有神气。予喜而语绎老曰：经闭非病，孕也，产必男。绎老雅信予，因究其说。予曰：滑非经闭之脉，左尺尤有神气，是以知产必男也，绎老谓：果孕矣，奈发热腹痛何？予曰：何伤，气虚血热耳。以安胎饮加减调理即安也。用人参、白术、白芍药为君，川芎、当归为臣，香附、柴胡、苏梗、条芩、甘草为佐，四帖，腹痛减，热除。至期果生子。绎老德余，而多推毂云。", "5987": "金文学元岩之眷，产后两日，腹痛，下痢纯红，肠鸣三越月，时当孟秋，两脉皆软弱，用佛手散加减以治，川芎三钱，当归五钱，艾叶、炮姜各一钱，桂心五分，酒炒白芍药二钱，连进三帖，而疾减半。后因食新菱、新栗，又连为怒气所激，日晡晕厥，以生姜汤灌苏，腹胁大痛，手不可近，用二陈汤加香附、砂仁、桂皮、炮姜与之，痛亦不减，且胸膈胀甚。自以手探喉中，吐出菱栗，痛稍定。少顷复痛，又用手探吐，吐后泻三四次，而元气脱矣。脉皆散乱如解索状，神气惫而恍惚，循衣摸床，病势危急。用人参、白术各五钱，酒炒白芍药二钱，砂仁、炮姜、肉桂、甘草各一钱，急煎进之，痛乃稍定，精神清，仍泻二次，次日复进药，痛减泻止。加白术又四帖，而饮食进，精神勃勃兴起矣。此因初痢时，医者不以产后为重，徒以治痢苦寒之剂伤其中气，又为菱栗生冷所损，中气益坏然也，治可不慎哉。", "5988": "沈三石别驾公夫人严，产三日而腹不畅。南浔女科陈姓者，为下之，大泻五六次，遂发热恶心，又用温胆汤止吐，小柴胡退热，服四日，热吐四日，粒米不进亦四日，又进八珍汤加童便，服后昏愦，耳聋，眼合，口渴，肠鸣，眼胞上下及手足背皆有虚浮。因逆予治。诊其六脉皆数，时五月初二日也。予曰：脉书云数脉所主，其邪为热，其症为虚。法当以十全大补汤加炮姜进之。夜半稍清爽，进粥一盂，始开目言语。次日午时，以承值者倦而药不相接，且言语太多，复昏昧不知人事。初四日，以人参、白术各三钱，炮姜、茯苓、陈皮各一钱，甘草五分，煎服讫，体微汗，遍身痱痤，热退而神爽。下午又药不接，又动怒，昏昧复如前，六脉散乱无伦，状如解索，痱痤没而虚极矣。亟以人参、白术各五钱，炙甘草、炮姜，大附子各一钱，连进二帖。是夜熟寝，唯呼吸之息尚促。初六日，脉又数，下午发热不退，环跳穴边发一毒如碗大，红肿微痛。夫人父严翁，与陈女科交谮之，曰：向之发热恶心，皆此所致，由附子、干姜温补误也，须急用寒凉解毒之剂。予正色而谕以理曰：此乃胃中虚火游行无制，大虚之症，非毒也。若作毒治而用寒凉，速其死尔。《内经》云：壮者气行则愈，怯者著而成病。惟大补庶可万全。三石翁然予言，急煎附子理中汤进之，日夕两帖，参、术皆用七钱，服后痱痤复出，毒散无踪，热亦退，沾沾喜矣。复以参苓白术散调理而全安。皆由产后误用下药，致变百出，噫唏!彼不达变之专科，其可任哉。", "5989": "诰封吴太夫人者，车驾涌澜公母也。年余六十，久患白带，历治不效，变为白崩，逆予治之。诊得右寸滑，左寸短弱，两关濡，两尺皆软弱。予曰：据脉，心肾俱不足，而中焦不湿。《脉经》云：崩中日久为白带，漏下多时骨木枯。今白物下多，气血日败，法当燥脾，兼补心肾。以既济丹补其心肾，以断下丸燥中宫之湿，则万全矣。服果不终剂而愈。", "5990": "吴北海太学令政，每月经行期之前，四肢累累发块，红紫胀痛，不思饮食，胃脘亦常痛，经水多不及期。诊其脉，两手皆驶，以症脉参之，肝脾二经有郁火也。盖肝主怒，脾主思，多思多怒，隐而不发，郁滞于中，故临经累累发红肿于四肢也。以柴胡、川芎、香附、乌药、白芍药、青皮、丹参、玄胡索、郁金、酒炒黄连、山栀子，治之而愈。", "5991": "吴之清客周刍玉者，豪放不拘，人言有晋人风，酒后益恣而好男色，因患白浊。吴医有以补中益气汤升提者，有以六味地黄丸补阴者，有以五苓散、六一散渗利者，有为降火者，有为温补者，不效。又以草头药乱进之，肌瘦如削，膝软如痿，患有年所矣。因绍介吴太学北海而谒余，恳为治之。诊其脉，右寸关皆数。予曰：皆由酒后不检所致也。中宫多湿多痰，积而为热，流于下部，故浊物淫淫而下，久不愈矣。与以加味端本丸服之而瘥。白螺蛳壳四两，牡蛎、苦参、葛根、黄柏各二两，陈皮、半夏、茯苓各一两，甘草五钱，面糊为丸，令早晚白汤下三钱。", "5992": "丁酉夏，予寓雉城顾乡宦宅。其门下竹匠妇，怀妊五月而患心痛。究其所由起，谓由失足坠楼也。始教饮韭菜汁一盏，而痛随止。其夫又从他医赎药二帖归，令煎服。服既，心复痛，吐鲜血盈盆，胸间忡忡上抵，疼不可言，危在顷刻。竹匠告急予仆孙安，安怜之，恳予诊治。六脉皆洪大，汗出如雨，喘息不相续。其妇楼居低小，予令亟移居楼下，随与益元散五钱，令用紫苏汤调服。又嘱之曰：今夜若睡，听其自醒，切勿惊动，汗止即苏也。服后果睡至晓，汗敛而胸膈不痛，喘息亦定。再与固胎饮一帖，煎服而安全矣。先是邻医诊其脉，谓吐血之脉宜沉细，今反洪大，而汗出喘息不休，危在今夜。及病起来，询余曰：妊妇不得汗、不得下、不得利小便，是谓三禁。昨日之剂悉犯之，而反获效，何哉？予曰：医贵审证，盖妇之患，非由病汗，以楼居低小，当酷暑而热逼故也。汗血去而胎失养，故忡忡上抵，喘息不续。移楼下以避暑气，益元散为解暑之圣药，而紫苏又安胎下气之妙品，气下则血归原而病痊矣。此对症之药，法出王海藏《医垒元戎》中四血饮是也。特诸君检阅不遍，即检阅亦不知为胎产之治。余何能，不过融会前人之法，用之不胶焉耳。邻医俯首，唯唯而退。", "5993": "壬申仲秋，予东游槜李，而王松泉、吴小峰偕行。小峰语予：中秋至矣，此间一妓李姓者，行第七，殊可人意，须访之。晚令佐酒，至则见其态度果澹雅风致。坐少顷，连咳两声，少峰究其病，曰：偶耳。小峰谓：毋诳，孙公知人生死，不啻扁鹊，可求一诊。诊之，两寸短涩，两尺洪滑，关弦。予未语，而小峰问脉，予曰：脉甚怪，公可问经行否？曰：行仅一日，亦仅点滴。予曰：此脉在良家主梦遗，若不宜有也。妓曰：良然，即御客时亦或遗，遗则冷汗淫淫，体倦而不能支。小峰为请药，予曰：姑置之。小峰问何故？予曰：金木相胜，心神无主，法当不治。小峰谓人尚无恙，何得便至于此？予曰：弦为春令，当金旺之时，犹然猖獗，设在卯月木旺火相，肺金枯萎，水之上源已竭，且肾脉洪滑，妓以欲胜，阴血既亏，淫火愈炽。书云：阴虚则病，阴绝则死。今已咳嗽，其兆见矣，可治乎？次年二月果死。", "5994": "有老妓金姓者，其嫂三月患头痛，身热，口渴，水泻不止，身重不能反侧，日渐昏沉，耳聋眼合，梦多乱语。嘉秀医者，历试不效，视为必死。予适吴江归，便道过槜李，访南溪、吉泉二兄。吉泉兄以是症见询，且言诸医有以补中益气汤进者，有以附子理中汤进者，二药已煎成未服，幸弟至，乞为诊之。六脉洪大，观其色内红外黑，口唇干燥，舌心黑胎，不知人事。予曰：此疫症也，法当清解，急以小白汤进之，犹可生也。若附子理中汤，杀之耳，安可用!南溪兄问：小白何汤也？予曰：小柴胡、白虎汤，合而一之是也。南溪兄谓：泄泻昏沉如此，恐石膏不可用也。予曰：此挟热下痢，但使清阳上升，则泻止热退，而神气自清也。服讫，夜半神气苏醒，惟小水不利，热渴不退。予思仲景法谓，渴而身热不退，小便不利者，当利其小便。乃以辰砂六一散一两，灯心汤调服之。两帖而瘳。南溪兄曰：死生信乎命也，弟顷刻不至，必服理中汤，此妇不为泉下人哉!", "5995": "有曹姓讳镗者，九月重阳，以胸膈不舒畅，而谒南溪兄为治，诊未竟，予至。南溪兄起语曹曰：舍弟高手，浼诊之。诊讫未有言。而南溪私问曰：曹何如脉？予曰：不治。会易货者沓至，予亦别去，曹果次年二月死。南溪兄问曰：何曹无它病，而弟见脉即断不治，何也？予曰：其脉两寸洪滑搏指，两关微弦，两尺微弱，《难经》所谓溢脉也。九月深秋，木凋零时也，不宜弦大，大则上盛下虚，至二月木旺，木能生火，火木性皆上升不下，下无真阴以相济，是有阳无阴，有升无降，《内经》曰：出入废则神机化灭，升降息则气立孤危。是以断曹子二月当呕吐而死也。", "5996": "嘉善之妓李双，号素琴，体虽肥，而性冲澹，态度闲雅端重，歌调娼家推其擅场，与予邑程芹溪处厚，患痛风，自二月起至仲冬，诸治不效。鸨母悭毒，遂视为痼疾，不为治。而芹溪固恳予诊之，六脉大而无力，手足肢节肿痛，两跨亦痛，不能起止，肌肉消其半，日仅进粥二碗，月汛两月一行，甚少。予曰：此行痹也。芹溪问：病可治否？予笑而应曰：君能娶，予能治之。芹溪曰：嫁娶乃风月中套语，公长者，乃亦此言。予曰：观此子虽堕风尘，实有良家风度，予故怜之。且君断弦未续，而彼有心于君，或天缘也。芹溪曰：诚吾素愿，恐鸨母高其价而难与言。予谓：乘其病而盟之，易与耳。芹溪以予言为然，乞为治之。以人参、白术、苡仁各三钱，当归、枸杞、杜仲、龟板、苍耳子各二钱，晚蚕砂、秦艽、防风各一钱，大附子、甘草、桂枝、黄柏各五分，十帖而痛止肿消。改用归芍六君子，加苡仁、丹参、红花、石斛、紫荆皮，三十帖而痊愈。芹溪娶之，善持家，举族称贤，而亦羡予知人焉。", "5997": "沈别驾翁，有老仆，头痛，遍身骨节痛，面色黑，发热，口渴，胸膈膨胀，饮食七日不入，复感寒，人皆危之。予诊其脉，左弦数，右洪大，以藿香、苍术、防风、葛根、白芷、紫苏、甘草、陈皮、大腹皮、麦芽、枳实，服后胸膈稍宽，热与痛更甚。改以麻黄、葛根、柴胡各二钱，石膏、滑石各三钱，紫苏叶、白芷、苍术各一钱，甘草五分，姜三片，服后大汗出，而热痛皆除，惟口渴。又以白芍药、当归、石膏、知母、柴胡、黄芩、麦冬、葛根、陈皮，煎服痊愈。别驾翁喜诘予曰：老仆病甚重，无不谓其必死，先生三日起之，此何症？而何汤剂饮之使起也？予曰：此三阳合病，先为饮食所伤，予故先用藿香正气汤，加消导之剂治其本，又以六神通解散，加助表之药治其标，病虽重，年虽高，喜其色脉相对，故投以对症之药易愈也。翁曰：在先生然耳!若他人轻者且重，况重者乎!吾未见其能起也。", "5998": "蔡中林文学内人，发热口渴，舌上燥裂，小腹痛，呕吐，药食不能入者七日，诸医之技殚矣，皆视为膈食而不可为。吴我峰翁固邀予诊，右寸脉绝不应指，关沉滑有力，左手弦数。予曰：此阳明少阳合病，邪热壅于上焦然也，非膈食，法当解散，数剂可愈，无恐。以软柴胡、石膏各五钱，半夏曲、枳实、黄芩、黄连、葛根、竹茹、人参各二钱，姜三片，煎服，药纳而不吐，五更下黑粪数块，热痛减半。次日仍与前药，右寸脉至是亦起粥始进。改用小柴胡加橘红、竹茹、葛根，服三帖而全安。", "5999": "吴九宜先生，每早晨腹痛泄泻者半年，粪色青，腹膨脝，人皆认为脾肾泄也。为灸关元三十壮，服补脾肾之药皆不效。自亦知医，谓其尺寸俱无脉，惟两关沉滑，大以为忧，以人言泄久而六脉将绝也。予为诊之曰：君无忧，此中焦食积痰泄也，积胶于中，故尺寸脉隐伏不见。法当下去其积，诸公用补，谬矣!渠谓：敢下耶？予曰：何伤。《素问》云：有故无殒亦无殒也。若不乘时，久则元气愈弱，再下难矣。以丹溪保和丸二钱，加备急丸三粒，五更服之，巳刻下稠积半桶，胀痛随愈。次日六脉齐见。再以东垣木香化滞汤，调理而安。渠称谢言曰：人皆谓六脉将绝为虚极，公独见之真而下之，由公究理深邃，故见之行事，著之谈论，皆自理学中来，他人何敢望其后尘。", "6000": "沈大官，左膝肿痛，不能起止者年半，大便泻，一日三次。诊其脉弦紧，予曰：此脾虚有湿热凝于经络，流于下部也。古谓肿属湿，痛属火。用苍术、黄柏、薏苡仁为君，泽泻、猪苓、五加皮为臣，炙甘草、防风、桂枝为佐，木通为使，四帖痛减肿消，泄泻亦止。改用苍术、苍耳子、五加皮、苡仁、当归、枸杞子、杜仲、丹参、黄柏、乌药叶，酒糊为丸，调理月余，步履如故。", "6001": "沈继庵先生，下痢十二日，腹痛，脱肛，后重，嗳气，不知饥。一友用补中益气加白芍药，腹痛愈加，后重亦甚。予脉之，右关滑大搏指，曰：此积滞固结肠胃间，故后重脱肛也。当为推荡，以其素弱多郁，不敢，只为调气而兼消导。木香、山楂、槟榔、枳实、川芎、白芍药、黄连、黄芩、秦艽。服后稍宽。次日用七伤丸，二帖痊愈。", "6002": "沈晴岳先生，五更耳鸣，腹不舒畅，稍劳则烘然热，自汗。脉右关滑大有力，左脉和缓。原为当风睡卧而得，素来上焦有痰火，午后过劳或受饿，大作眩晕，冷汗津津，再不敢动，稍动则呕吐，此皆痰火所致，盖无痰不作晕也。先与藿香正气散一帖，以去表里之邪；继与温胆汤加天麻，服后眩晕、呕吐皆止。次日诊之，右关脉仍滑，此中焦食积痰饮胶固已久，卒难动摇，姑以二陈汤加枳实、黄连、滑石、天花粉、天麻、竹茹调理，后以当归龙荟丸加牛胆南星、青礞石，凡数帖痊愈。", "6003": "潘景宇内人，后半夜不睡，面黄肌瘦，两太阳及眉棱骨痛，大便溏，稍劳动则体热，四肢无力。其脉左寸洪滑，自春至秋皆然。此由脾虚，肝心二经火盛然也。先用四君子加酒连、柴胡、白扁豆、泽泻、滑石调理，夜与钱仲阳安神丸数粒，灯心汤送下。服八日得睡，两太阳亦不痛，继用六君子加黄耆、秦艽、柴胡、泽泻、当归、白芍药、黄柏，全安。", "6004": "臧六老，上吐血下泻血，胸膈背心皆胀，原从怒触，又犬肉所伤，故发热而渴。医者皆作阴虚火动，而为滋阴降火，胸背愈胀，血来更多。予诊之，两关俱洪滑有力。谓曰：此肝脾二经有余症也，作阴虚治，左矣!《内经》曰：怒伤肝。甚则呕血并下泄。胸背胀痛，瘀血使然。脾为犬肉所伤，故不能统血。今误用地黄、麦冬、黄柏、知母等剂，是以脾益伤，而上焦瘀血愈滞也。惟调气健脾兼之消导，则万全矣。六老曰：人皆谓劳怯，故发热吐红，血上吐，阳络伤也；血下行，阴络伤也。阴阳俱伤，法当不治，公独认非阴虚何也？予曰：脉书云：脉数无力者阴虚也。今脉固非阴虚。书又曰：凡阴虚之热，发于申酉戌间，夜半而退，明日犹是，如潮信然。以下午乃阴分主事，故曰阴虚潮热也。今热不分昼夜，而症亦非阴虚，故曰作阴虚治者左也。六老闻言大喜曰：公诚见垣一方者，幸惠一匕以生之。即与山楂、香附、枳实，调气消导为君；丹参、丹皮、桃仁、滑石、茅根化瘀血为臣；黄连、芦根，解犬肉之热为佐。四帖，胸背宽，血吐止，惟腹中不舒，仍以前药同丹溪保和丸与之，四帖，大便下极臭黑粪半桶，寝食俱安矣。", "6005": "有臧氏之妇，原以有痰火，服降火之药过多，至秋痰积，因令气下行而滞于大肠，脐边有硬块，按之甚痛，痢下红白八日，下惟点滴，日夜二十余行，腹痛潮热，口渴，小水不利，大便里急后重，饮食不进，身重不能转侧。予诊之，喜左脉皆有神气，即从刘守真之法，行血则便脓自愈，调气则后重自除治之。用白芍药、滑石、桃仁为君，当归为臣，木香、槟榔、山楂、酒芩、酒连、枳壳为佐，服下大便稍流利，腹中稍宽舒，次日仍与前药，则滞下大行，痢减大半。第三日，用芍药、当归、滑石、桃仁、炙甘草、酒连、木香，与保和丸同服，下午大便行，上午所服丸药，随粪而下，乃知积滞已尽，诸症悉减，惟脐边痛未全止。以仲景小建中汤加当归、木香，服之而安。", "6006": "丁耀川文学令堂，年四十四，常患胃脘痛，孀居十五年，日茹蔬素。其年七月，触于怒，吐血碗许，不数日平矣。九月又怒，而吐血如前，加腹痛。至次年二月，忽里急后重，肛门大疼，小便短涩，出惟点滴，痛不可言，腰与小腹之热，如滚汤泡者，日惟仰卧不有侧，一侧则左跨并腿作痛。两跨原有痛，小便疼则肛门之痛减，肛门疼则小便之痛亦减。肛门以疼之故不能坐。遇惊恐则下愈坠而疼，经不行者两月，往常经来时腰腹必痛，下紫黑血块甚多，今又白带如注，口渴，通宵不寐，不思饮食，多怒，面与手足发虚浮，喉中梗梗有痰，肌肉半消。诊之脉仅四至，两寸软弱，右关滑，左关弦，两尺涩。据脉上焦气血不足，中焦有痰，下焦气凝血滞，郁而为火，盖下焦之疾，肝肾所摄，腰胯肝之所经，而二便乃肾之所主也。据症面与手足虚浮，则脾气甚弱；饮食不思，则胃气不充；不寐，由过于愁忧思虑而心血不足，总为七情所伤故尔。《内经》云：二阳之病发心脾，女子得之则不月，此病近之。且值火令当权之候，诚可虑也。所幸者，脉尚不数，声音清亮，尤可措手。因先为开郁清热，调达肝气，保过夏令后，再为骤补阴血。必戒绝怒气，使血得循经，而病可痊。不然，则仓扁亦难奏功矣。初投当归龙荟丸，以彻下部之热，继以四物汤，龙胆草、黄柏、知母、柴胡、泽兰叶，煎吞滋肾丸，连服四日，腰与小腹之热始退。后以香薷、石苇、龙胆草、桃仁、滑石、杜牛膝、甘草梢、软柴胡，煎吞滋肾丸，大小便痛全减。", "6007": "丁文学长令姊，常患晕厥，吐痰碗许乃苏，一月三、五发。后又口渴，五更倒饱，肠鸣腹疼，泄泻，小水短涩，咳嗽。余脉之，两寸濡弱，两关滑大，此中焦痰积所致也。先与二陈汤，加苍术、山楂、麦芽以健脾祛湿为臣，以白芍药止痛为君，以滑石、泽泻引湿热从小便出为佐，黄芩为裨佐。十帖，二阴之痛俱止，改以六味地黄丸加黄柏、知母、牛膝，服之而安。", "6008": "有金良美者，年十八，患咳嗽吐红，下午潮热梦遗。市医进四物汤加天门冬、黄柏，知母之类，治半年，反加左胁胀疼，不能侧卧，声音渐哑，饮食辄恶心，肌肉大削，六脉俱数，医告技穷，因就予治。观其面色白，又隐隐有清气夹之，两足痿弱无力，予语之曰：此症气虚血热，而肝脉甚弦，弦则木气太旺，脾土受亏，不能统血，殆始怒气所触，继为寒凉之剂所伤，以致饮食恶心，肌肉瘦削。书云，脾胃一虚，肺气先绝。以肺金不足，则肝木愈不能制。浊痰瘀血凝于肺窍，故咳嗽声哑，滞于肝，故左胁不能贴席而卧，病势危矣。喜在青年，犹可措手。因急用人参二钱，鳖甲五钱为君，白术、白芍、陈皮、茯苓、通草、贝母各一钱为臣，甘草、牡丹皮各七分为佐，桔梗五分为使。二十帖，潮热止，咳嗽减大半。三十帖，声音开亮，左胁亦能贴席而卧。后以大造丸调理全安矣。乃嘱之曰：病愈虽可喜，而弦脉未退，须切忌怒气及劳心劳力之事，庶几可保无虞。苟不守予言，而劳怒相触，血来必不能御，戒之防之。此后精神日旺，肌体半肥，六年无事。一日遇事拂意，大怒，而又结算劳心，则血如泉涌，顷刻盈盆，上唇黑肿，汗出淋漓。急请予诊，脉乱无伦。诊毕，渠语近侍欲大解。予曰：此死征也，阴阳乖离矣。辞而出，未离门而气绝。父母哭谢予曰：始守翁训，苟活六年，一旦不戒，遂如翁所料，死生虽命，亦不自慎致之。其为人也，量窄而紧于财，因记此以戒世之重财轻生者。", "6009": "王祖泉令政，患头疼夜热，洒淅恶寒，汗淋漓如雨，上身热，下身寒，渴不思饮，遍身疼，腹有一块，大如拳，硬如石，肠鸣，小水短少，饮食俱废。脉则右关滑，左弦数。究所由起，谓大怒后即伤于食，市医皆以地黄、门冬、芩、连、黄柏之剂治之，热愈甚，脾气大虚。予治用平胃散，加山楂、麦芽、砂仁、香附、木香、川芎、枳实，连进四帖，中气稍能运动，而夜热如前。再与补中益气汤，寒热俱退矣，而腹痛里急后重。予知其积滞将行也，乃与白六神丸，而腹痛后重皆除，改进以参苓白术散，加香附、乌梅、山楂，服之病良已。", "6010": "温巽桥子妇，吴车驾涌澜公长女也。发热恶心，小腹痛，原为怒后进食，因而成积，左脚酸已十日矣。南浔有陈女科，始作瘟疫疗治，呕哕益加。又作疟治，粒米不能进，变为滞下，里急后重，一日夜三十余行。陈技穷而辞去。且言曰：非不尽心，犯逆症也。下痢身凉者生，身热者死；脉沉细者生，脉洪大者死。今身热脉大，而又噤口，何可为哉？因请予治。脉之，两手皆滑大，尺部尤搏指。予曰：症非逆，误认为疫为疟，治者逆也。虽多日不食，而尺脉搏指，《内经》云：在下者引而竭之。法从下可生也。即与当归龙荟丸一钱五分，服下，去稠积半盆，痛减大半，不食者十四日，至此始进粥一瓯，但胸膈仍饱闷不知饿。又与红六神丸二钱，胸膈舒而小腹软，惟两跨痛，小腹觉冷，用热砖熨之，子户中白物绵绵下，小水短涩。改用五苓散加白芷、小茴香、白鸡冠花、柴胡服之，至夜满腹作疼。亟以五灵脂醋炒为未，酒糊为丸三钱，白汤送下，通宵安寝，次日，精神清健，饮食大进，小水通利矣。而独白物仍下，再用香附炒黑存性，枯矾各一两，面糊为丸，每空心益母草煎汤送下二钱，不终剂而白物无，病痊愈矣。专科赧然称奇而服，录其案验而去。", "6011": "温一渠内人，平素血虚咳嗽，近为饮食所伤，不知饥饿。专科作阴虚治，而胸膈愈胀。予脉之，右关滑大，左手软弱。法当先健脾，消去饮食，然后治嗽。若为补阴降火，不惟咳嗽无功，恐脾胃转伤，腹胀泻泄，变将不测。何也？脾胃喜温而误寒也。即以二陈汤加山楂、麦芽、枳实、白术、川芎、香附与之。一剂而胸膈宽，再剂而饮食进。继用桑白皮、地骨皮、甘草、陈皮、贝母、栝蒌仁、马兜铃、桔梗、紫菀，十帖而咳嗽脱然矣。", "6012": "温天衢氏，冬月病目，医为发散太过，至春间吐血碗余，及夏，下午潮热咳嗽，胸膈胀疼，早晨冷汗淋漓，大便溏，一日两行，饮食少，肌肉消十之七，脉数。据症脉，法在不治。里中诸长老，以其素行端厚，群然恳予措剂。予以众恳不能辞，乃用泻白散加五味子、白芍药、贝母、马兜铃。服下，其夜帖然而卧，不嗽，惟大便溏。前药加白扁豆、山药、茯苓，汗亦渐止，复与泻白散，加石斛、马兜铃、贝母、陈皮、薏苡仁、白芍药、山药、五味子、桔梗，调理三月而痊。", "6013": "温南溪内人，居常大便秘结，面赤，不思饮食，头时眩晕。诊其脉，右关尺滑大有力，此痰火症也。用栝蒌四钱为君，滑石三钱，枳实二钱，半夏一钱半为臣，萝卜子、姜黄各一钱为佐，两帖愈矣。又教以或遇大便秘结，每服当归龙荟丸，加牛胆南星一钱立应。", "6014": "潘敬斋令媳，原因经水不行，医投安胎之剂。越七月，经水忽大行，内有血块筋膜如手大者一二桶，昏冒困惫为剧。逆予治，其脉右关洪滑，左寸洪数，两尺皆洪大。病形夜分咬牙乱语，手心热，口噤，时手足皆冷，心头胀闷不快，面色青。始诸医皆谓难治。予曰：无恐，此浊痰流滞血海，以误服安胎之剂，益加其滞。夫血去多，故神魂无依，痰鸣心窍，故神昏语乱。急为调气开痰，安神养血，可生也。即以温胆汤加石菖蒲、酒芩、天麻、酸枣仁、丹参与服，其夜子丑时，咬牙乱语皆减半。次日仍与前药，每帖加竹茹五钱，临睡，又与黑虎丹数粒，诸症悉去而愈。敬斋问曰：藉高手病痊矣，而每发于夜半何也？予曰：此心包络与胆经有痰热，故每至其时而发，单治此两经，痰既消，而神魂俱安也。敬斋曰：善。", "6015": "臧七房二老妇人，年六十八，患痢，痢后过食熟菱与腐汤，以致大便滑泄不固，饮汤水，径直下不停，胸膈痞闷，语言无力，舌干口燥生疮，咽津液则喉疼。元气大虚而热，皆虚火所致。且长素二十余年，又当痢后，益知非有余之症也。脉又尺寸俱弱，两关滑大。《内经》云：清气在下，必生飧泄；浊气在上，必生䐜胀，此之谓也。法当提清降浊，补助元气。用四君子汤，加葛根、白芍药、黄连清虚热，止燥渴为君，桔梗辅佐葛根升提清气为臣，陈皮、麦芽降其浊气，以消胸膈痞闷为佐，加乌梅为使。上使生津，下使止浊，连服二剂，尺寸之脉稍起，饮食亦得停腹，骎骎，然始有生气。仍以前方加白扁豆、神曲，打糊为丸，调理而安。", "6016": "蔡乐川令眷，患头痛，痛如物破，发根稍动，则痛延满头，晕倒不省人事，逾半时乃苏。遍身亦作疼，胸膈饱闷，饮汤水停膈间不下。先一日吐清水数次，蛔虫三条。原为怒起，今或恶风，或恶热，口或渴，或不渴，大便秘，脉则六部皆滑大有力。予曰：此痰厥头痛症也。先以藿香正气散止其吐，继以牛黄丸、黑虎丹清其人事。头仍疼甚，又以天麻、藁本各三钱，半夏二钱，陈皮、白芷、薄荷、麻黄、生姜、葱白煎服，得少汗而头痛少止。至晚再服之，五更痛止大半，而人事未全清。予谓此中焦痰盛，非下不可。乃用半夏五钱，巴霜一分，面糊为丸，每服三十丸，生姜汤送下。下午大便行三次。皆稠黏痰积也。由此饮食少进，余症瘥可，惟遍身仍略疼。改用二陈汤，加前胡、石膏、藁本、薄荷、枳壳、黄芩、石菖蒲，调理而安。", "6017": "周芦汀乃眷，患胃脘痛，手心热，呕吐不食者四日，昼夜叫痛不辍声，脉则两手皆滑数。予谓当以清热止痛为先，故先与清热止痛末药二钱令服之，不一饭顷，痛遂止而睡。家人皆色喜。予曰：未也，此火暂息耳，其中痰积甚固，不乘时而下之，势必再作。因与总管丸三钱，服下腹中微痛，再服二钱，又睡至天明乃寤，而腹痛亦止。大便下痰积甚多。次日以二陈汤加枳实、姜黄、香附、山栀、黄连与之，服后胃脘之痛全止，惟小腹略觉膨脝。予谓其痰积未尽也。再与总管丸三钱，夜服之，天明又行一次，痰积之下如前，而胃脘之痛亦绝不发矣。", "6018": "施泾阳先生内人，年五十八，左胁有痰饮，每升至咽间，即胀闷不知人事，遍身皆胀，不能卧，小水赤。诊其脉，两寸关洪滑，六部皆数。予谓此痰火症也，痰生热，热生风，故每发人事不知尔。乃与牛黄清心、凉膈丸同黑虎丹服之，夜遂得睡，人事亦安静。再以二陈汤加滑石、竹茹、郁金、薄荷、黄芩、前胡，加灯心、生姜煎服，全安矣。", "6019": "屠侍轩尊眷，产一日而触于怒，大便泄泻，昏愦不省人事，大热，气促，汗多。众医谓产后脉不宜大，今脉大左手散乱，又汗出喘促，法在不治。予曰：固然。书云医而不起者有矣，未有不药而起者也。且不药而视其死，与药而或可图生者，孰优？予试之。亟与人参五钱，白术三钱，炙甘草一钱五分，炮姜二钱，肉果六分，五味子七分，煎服。其夜遂稍睡。予窍喜，补而得睡，其阴阳和矣。次早脉果稍收敛，喘促亦缓，大便前半夜泻三次，五更啜粥半盂，小便通利。大有生意也。再以人参、阿胶固元气、定喘为君，白术、炮姜补脾为臣，泽兰叶退产后之热，五味子敛神止汗，肉果止泻为佐，甘草和中为使，五帖而安。", "6020": "屠学恒先生乃眷，以产后欠补养，而精神疲困，脾胃亦弱，腹中间作痛。作泻，脉两手皆濡软无力，以六君子汤加藿香、砂仁、香附、苍术、泽泻，调理而安。", "6021": "周鉴泉令政，病伤寒。发热，谵语，口渴，咳嗽，胸膈痛，泄泻，呕吐，遍身发斑。诊之，六脉洪滑，予曰：此少阳阳明合病之症，势亦重矣。急以升麻葛根汤，加滑石，五味子进之。服后汗大出，下午即退凉而谵语止。晚进柴苓汤加五味子、滑石，其夜泻止，神思始清。次日左脉已和，右脉亦稍收敛。予喜曰：可无恙也。改用白芍药为君，陈皮、柴胡、酒芩、五味子、牡蛎、滑石、茯苓、泽泻、白术，服四帖而痊可。", "6022": "大国博臧顾渚先生，病两耳焮痒，唇燥舌干，咳嗽吐浓痰，脉左稍浮弦，右洪滑。此胃中痰火流入肺经，郁积久而生热生风也。先以总管丸导其痰，又与黑虎丹祛其风热，继以天花粉、薄荷、郁金、葛根、白药子、甘草、黄连、连翘、蝉蜕煎服而安。", "6023": "王南岗咳嗽气涌，不能伏枕，吐痰不已。下午微热，胸膈膨胀，不知饱饿，口干，舌上白苔厚，小水短少，大便里急后重，间有紫黑血。脉右关洪滑，左手涩。据脉症，胃中有瘀血痰积，而肺气亦虚也。法当先补而后泻，以人参、白术、白芍药、柴胡、黄连、陈皮、半夏、五味子、桔梗，与三帖后，察其肺脉已旺，乃与总管丸下之，去黑血屑极多，诸症悉减，再与红六神丸调理而痊。", "6024": "张桃津乃政，原有小便癃闭之症，又小产后三日，脐下作疼，夜分发热，口渴，大便溏，日三四度。先与补中益气汤，加玄胡索、泽兰叶、牡丹皮服之，连进三帖，大便实矣。惟小便频数，滴滴不断，一日夜二十余次，夜分尤多，精神甚惫。脉虽五至，不甚充指，此血虚有热，而气亦滞也。湿热在气分。故口中渴，血虚，故脐下痛。法当峻补其阴，而淡渗其阳。以熟地黄三钱，黄柏一钱补阴为君，萆薢去湿热为臣，瞿麦穗、泽泻淡渗为佐，乌药调气，甘草为使。服下脐痛全止，小便其夜亦不起，连进三帖，病脱然矣。", "6025": "溧水令君吴涌澜公尊夫人，每五更倒饱，必泻一次，腹常作胀，间亦痛。脉两手寸关洪滑，两尺沉伏。予曰：此肠胃中有食积痰饮也。乃与总管丸三钱，生姜汤送下。大便虽行，不甚顺利，又以神授香连丸和之，外用滑石、甘草、木香、枳壳、山楂、陈白、白芍药、酒连调理而安。", "6026": "李悦斋先生夫人，胸胁大腹作痛，谵语如狂。寅卯辰三时稍轻，午后及夜痛甚，昼夜不睡，饮食不进者十八日。究其故，原有痰火与头疼、牙疼之疾，又困经行三日后，头疼发寒热。医以疟治，因大恶热，三四人交扇之，而两手浸冷水中，口噙水而不咽，鼻有微衄，又常自悲自哭，目以多哭而肿，痛时即壁上亦欲飞去，剧则咬人，小水直下不固，喉梗梗吞药不下。脉则左弦数，右关洪滑。予曰：此热入血室症也，误服治疟刚燥之剂而动痰火，以致标本交作。诸人尤谓：热入血室，当夜间谵语如狂，如见鬼，何至胸胁痛剧咬人也？予曰：仲景云，经水适来适止，得疾，皆作热入血室治之，治同少阳，而以小柴胡汤为主，加凉血活血之药，此古人成法可守也。痛极咬人者，乃胃虚虫行，求食而不得，故喉中梗梗然也。即以小柴胡汤加桃仁、丹皮，而谵语减，次日以安蛔汤与服，而疼随止，饮食进，遂骎骎有生意。", "6027": "吴仲峰先生邀予诊，时为仲秋初二日也。六部皆沉微，而左尤甚，隐隐又如蛛丝之细。症则原以肠风去血，过服寒凉，致伤脾胃。自春至秋，脾泄不愈，日夜十二三行，面色黄白带青，两颐浮肿，四肢亦浮，小水不能独利，利必与大便并行，肠鸣，四肢冷，口不渴，饮食大减，口唇龈肉皆白。其为人也，多忧思。夫四肢者，脾之所主，清冷为阳气不充。两颐乃肾经部位，浮肿益见肾气之不足也。脉沉微与面色黄肿，皆属于湿。书云：诸湿肿满，皆属脾土。合脉症观之，由脾虚不运，积湿而然，虚寒明矣。病至此，势亦甚危，第形症相符，色脉相应，又能受补，庶几可生也。法当大温补升提。以东垣益胃升阳渗湿汤加减调理。人参三钱，白术五钱，黄耆二钱，茯苓、益智仁、苍术、泽泻各一钱，大附子五分，炮姜、炙甘草、升麻、防风各五分，连服八帖，诸症悉减。乃嘱之曰：病虽暂愈，宜戒生冷、忧思，庶服药有效，切勿轻犯，犯之非药石可回也。翁曰：诺，敢不唯命？", "6028": "府佐张五桥先生夫人，患喘嗽，夜分气壅不能仰卧，体素弱，脉右滑大，左细弱，每咳嗽，必连连数十声，痰不易出，甚至作吐。以东垣人参平肺散加减治之，四日而愈。人参、桑白皮、地骨皮、青皮、茯苓、五味子、知母、滑石、麦芽、天麻、粳米、甘草，水煎服，夜与白丸子。", "6029": "方东野患脊骨痛，牵引胸腹皆疼，舌上黄苔甚厚，脉沉滑而数。先以川芎、羌活、炙甘草、苍术、姜黄、防风、藁本、枳壳、桔梗、柴胡服之。服后背脊痛减，腹仍痛。与木香、槟榔、姜黄、香附、青皮、酒连、大栝蒌、柴胡、川芎服之，腹痛稍减，腰疼甚，知其痰积下行，欲去而不能也。即以木香槟榔丸下之，连行三四次，舌上黄苔始退，腹痛全止。脉亦软弱。改以人参、当归、白芍、甘草、茯苓、陈皮、白芥子、香附、柴胡、青皮、白术，调理而安。", "6030": "张一尹近川翁，始以内伤外感，过服发散消导之剂，致胃脘当心而痛，六脉皆弦而弱，此法当补而敛之也。白芍药酒炒五钱，炙甘草三钱，桂枝一钱半，香附一钱，大枣三枚，饴糖一合，煎服一帖而瘳。", "6031": "闵文川先生，肛上生一肿毒，月余脓溃矣，但稍动则出鲜血不止，大便结燥，胸膈饱胀，饮食不思。脉两寸短弱，关弦，尺洪滑。此气虚血热，陷于下部。法宜补而升提也者，不然痔漏将作，可虑也。黄耆二钱，归身、地榆、槐花、枳壳各一钱，升麻、秦艽各七分，荆芥穗五分，甘草三分，服后胸膈宽，惟口苦甚，前方加酒连、连翘各五分而愈。", "6032": "李古愚先生，每食后即大便，腹皮稍胀急，胸膈饱闷。医与参术则痞闷愈甚，小水清而长。予脉之，左寸涩，右寸滑，按之如黄豆大，且鼓指，关尺之脉皆弦小，左尺脉迢迢有神气。据脉乃积痰郁滞于肺莫能出，以致大便之气不固也。法当效丹溪治乃叔用吐，吐去上焦痰积，而大便自实矣。先用苦梗、萝卜子各三钱，白豆仁、橘红、山栀仁各一钱，川芎五分，生姜三片，葱三根，水煎服之，取吐。服后半小时许，恶心，吐出清痰，恶心之势虽有，乃痰积胶固，犹不易出。又以萝卜子一合，擂浆水，加蜂蜜，与半碗饮之，始吐出胶痰二碗余。平日每小水则大便并行，吐后小水始能独利，连行三四次，而胸腹宽舒。初亦以吐为惧，至是豁然称快，大便五日不行，始以予言为不谬也。再以二陈汤加白术、旋覆花、麦芽，调理而全可矣。", "6033": "姚惠斋先生，夜多泄泻，泻必三五次，甚且十数次，小腹时作疼，按亦疼，口不渴，小便长，医半年不愈。予诊之，左寸滑，余五部皆濡弱。此阳气大虚，虚中有寒也。治当温补下元，兼之升举。人参一钱半，黄耆、白术各二钱，白芍药酒炒三钱，大附子五分，肉桂一钱，杜仲、补骨脂各一钱半，升麻、防风各七分，姜枣煎服。其夜大便减半，次早虽泻，俱是白积，如生豆汁状，小腹痛止。再诊之，右脉稍起，连服四帖而瘳。翁喜言曰：抱病半年，药无虚日，今收功于四剂，何速哉!认病真而投剂确也，敢不铭心。", "6034": "大京兆姚画老夫人，年几七十，右手疼不能上头。医者皆以痛风治，不效，益加口渴烦躁，请予诊之。右手脉浮滑，左平。予谓此湿痰生热，热生风也。治宜代痰清热，兼流动经络可瘳也。二陈汤倍加威灵仙、酒芩、白僵蚕、秦艽，四剂而病去如脱。", "6035": "一仆发热头疼，口渴，腹疼，小便赤，大便泻，日夜不睡者六日。予诊之曰：据脉，汗后浮数，热尚不减，乃疫症也。以滑石三钱，青蒿、葛根、白芷、片芩各一钱半，炙甘草、升麻各五分，一帖即得睡，热减大半，头痛全除。惟小水赤，头晕，脚膝无力。此病后血虚之故。以四物汤加青蒿、酒芩、薏苡仁，服之而安。", "6036": "一仆病与前类，而身如火烁，头痛如破，大便不泻，小水赤，口渴，鼻干，不得眠，胸膈膨胀，腹饥不能食，六脉弦而数。用竹叶石膏汤，加知母、枳壳、白芷、葛根，大加青蒿，一帖而热痛减半，胸膈亦宽。惟口渴，小水短涩，睡卧不安，又与化瘟丹三钱，井水化下，渴止，稍得睡，头晕脚软，喘急。与四物汤加青蒿、酒芩、薏苡仁、木瓜，服之全安。", "6037": "马凤阳文学，五月患咳嗽，内热，额上多汗，恶风。脉左弦数，右滑数。予曰：据弦数为阴虚，滑为有痰。不亟调治，恐成虚怯。以白芍药、川归、茯苓、五味子、白术、甘草、陈皮、贝母、天花粉、酒芩、麦冬、知母、桑白皮，十帖，诸症皆瘳。七月复疟，间日一发，寒热相半，寒热亦俱极，渴甚，上身汗多。以石膏五钱，人参、黄耆、白芍药、麦冬、知母二钱，柴胡三钱，桂枝、甘草、陈皮、贝母各一钱，竹叶三十片，一帖而愈。", "6038": "倪二南先生内人，小水不禁，一日二十余起。脉右寸洪而有力，左寸虚，右尺沉微。此心肾不交之症也。以当归、远志、丹参、牡丹皮、桑螵蛸、人参、山茱萸、益智仁、黄柏、知母为丸，服之，五日为安。后凡遇辛苦则发，以此服之立效。", "6039": "柱史严印老长媳，少司空沈镜老女也。患腹痛有小块累累然，腹觉冷甚，两寸关皆滑数，两尺皆沉微，此脾气弱而饮食不消。又当秋令湿淫之候，不利亦泻，宜预防。与白术、苍术、茯苓、甘草、白豆仁、木香、半夏、陈皮、泽泻煎服。其夜果泻一度。次早又泻一度。小腹仍疼不少减，且里急后重。盖其禀赋素虚，当补中兼消兼利。白芍药三钱，桂心一钱，甘草、人参、茯苓、泽泻、陈皮、白术各八分，升麻、葛根各六分。服后脉皆软弱不滑，累块亦消。改以人参、黄耆、白术、白芍药各二钱，炙甘草、陈皮、泽泻、葛根、柴胡、茯苓各一钱，调理而痊。", "6040": "新市陈鹿塘先生，原有肠风脏毒之症，大便燥结，数日不能一行，痛苦殊甚。此胃寒肠热之症，其脉两寸皆数，两关皆弦而无力，两尺洪滑而左尤甚。诊毕，渠告予曰：病数年，百医不效，望生难矣。闻公治多奇中，冀一奇而生之，实再造之恩也。予怜其苦，而俯想久之。因思李东垣有云：大肠喜清而恶热，脾胃喜温而恶寒，以胃属土，而大肠属金也。今治肠胃相兼之疾，必寒非凄凄，热非灼灼始可。乃详酌一方，专以肠风脏毒之药为君主，外以养血之剂裹之，使不伤胃气。盖药先入胃，而后传入大肠，入胃时裹药未化，及入大肠则裹药化，而君药始见，庶几两不相妨，亦假道灭虢之策也。因以大黄酒浸九蒸九晒者二两，槐花三两，木耳二两，郁李仁、皂角子、象牙屑、条芩各一两，血余灰、升麻、荆芥穗各五钱为末，炼蜜为丸，赤豆大，外以四物汤加蒲黄各一两为衣，米汤送下，空必及下午各服二钱。服此果然血止，而大便不燥，饮食日加。鹿塘大喜曰：古称用药如用兵，奇正相生，鲜有不克敌者，其公之谓乎。", "6041": "张道南先生尊堂老妇人，以劳倦致早晨膈上有痰痞而恶心。每食热物，目中即出泪，脉右寸关皆滑，左寸短弱，此心血不足，而肺胃有痰也。以六君子汤加麦芽、白豆仁、旋覆花治之而愈。", "6042": "马迪庵先生内人，原以饮食过伤，又为风寒外袭，以内伤外感治之后，复至五更发热，唇燥，胸中冲跳不已，手足皆冷，脉两寸俱滑数。予谓此奇痰症也。以小陷胸汤加白芍药、萝卜子、前胡、酒芩二帖，次早大便行，下蛔虫八条，胸中即不冲跳，但觉力怯。再诊之，两寸减半，尺脉稍起。以二陈汤加白术、白芍药、酒芩调理，后四帖加当归而痊愈。", "6043": "大宗伯董浔老夫人，常眩晕，手指及肢节作胀。脉右寸软弱，关滑，左脉弦长，直上鱼际，两尺皆弱，此亢而不下之脉。《难经》所谓木行乘金之候也。总由未生育而肝经之血未破尔。《内经》云：诸风掉眩，皆属肝木。兼有痰火，治当养金平木，培土化痰。以白术半夏天麻汤，正与此对。服两帖而眩晕平。再与六君子汤加天麻、白僵蚕以治其晕，加白芍药以泻肝，麦门冬、人参以补肺金，麦芽、枳实、神曲、苍术以健脾，使宿痰去而新痰不生。少用黄柏二分为使，引热下行，令不再发。", "6044": "王谷泉，大便作泻，上身热，耳中壅塞，头眩晕，胸膈不宽，口渴，痰多，咳嗽，六脉俱濡弱，汗大出。此正气大虚，或由克伐太过所致，当以补养为先。人参、白术、白芍药酒炒各四钱，柴胡、石菖蒲、陈皮各一钱，炙甘草五分，泽泻、茯苓各一钱。两服而神清、膈宽、脾健，惟汗不敛，眩晕未除。再与人参、白术、黄耆、酒炒白芍药各二钱，炙甘草五分，大附子五分，桂枝三分，泽泻一钱而愈。", "6045": "方东野，两胁痛，上壅至胸，发热，饮食不进。脉左手沉而弦数，乃积气也。右手滑，痰饮也。关脉濡弱，脾气不充也。据症或触于怒，故痛之暴耳。治当先去积热，消痰气，然后用补。栝蒌仁六钱，枳壳、姜连、半夏各一钱半，白芥子一钱，牡蛎二钱，炙甘草五分，柴胡一钱五分，二帖，诸症尽去，饮食进矣。然恐其复发也。与当归龙荟丸使行之，以刈其根。服下果行两次。", "6046": "一妇人心痛，唇红，痛则大发热，头疼，少顷出汗，脉大小不一。予曰：此虫痛之症，痛吐白沫可征也。槟榔、川椒各二钱，杏仁一钱五分，石菖蒲一钱，乌梅七个，炮姜、草豆仁、陈皮各五分，山栀仁一钱，一进而痛减半，再进而痛全除。", "6047": "倪少南内人，行经如崩，势不可遏，头晕眼花，脉右寸极软弱，左近快，此气虚血热之候，由气虚而血不固也。仲景云：血脱益气。特用人参、黄耆各三钱，白术二钱，粉草五分，荆芥穗、蒲黄、侧柏叶、姜炭各一钱，三帖全瘳。", "6048": "高仰山内人，痔血，里急后重。饮良入腹，大便即行，昼夜行五六度，五更咳嗽，喉中痰响，肌肉脱，口作渴。由服痔科凉血之药过多，致脾虚不能统血也。脉六部皆软弱无力。以四君子汤加荆芥穗、秦艽、陈皮、炮姜，四帖而饮食进，血全止，嗽定而睡宁。后减炮姜，倍加何首乌，又四帖，而数年不发矣。", "6049": "徐文学三泉令郎，每下午发热直至天明，夜热更甚，右胁胀痛，咳嗽吊疼，坐卧俱疼。医以疟治罔效。延及二十余日，热不有退。后医谓为虚热，投以参术为主，痛益增。逆予诊之，左弦大，右滑大搏指。予曰：《内经》云：左右者，阴阳之道路。据脉肝胆之火为痰所凝，必勉强作文，过思不决，木火之性不得通达，郁而为疼。夜甚者，肝邪实也。初治只当能调肝气，一剂可瘳。误以为疟，燥动其火，补以参术，闭塞其气。书云：体若燔炭，汗出而散。今汗不出，舌上之胎已沉香色，热之极矣。设不急治，立见凶危。乃以仲景小陷胸汤为主。大栝蒌一两，黄连三钱，半夏曲二钱，前胡、青皮各一钱，水煎饮之。夜服当归龙荟丸微下之。诸公犹争之曰：病久而食不进，精神狼狈若此，宁可下乎？予曰：经云肝常有余，且脉亦为有余，故有余者泻之。前时误认为虚，投补左矣，岂容再误哉!服后，夜半痛止热退，两帖全安。", "6050": "王祖泉乃眷，朝饭后稍寒，恶风发热，遍身疼痛，汗大出不止，口中热，腹中不知饿，小水短，六脉皆涩。以白芍药五钱，白术二钱，桂皮、黄芩各一钱，甘草八分。二帖而汗止，寒热除，减去白术，加当归而遍身痛止。", "6051": "费一吾先生令政，妊已四月，夜不能睡，小便淋痛，痰嗽内热。脉右关滑，左寸微弱，两手皆数。与橘红、贝母、片芩、黄连、茯苓、泽泻、枳壳、苏梗、前胡，水煎服之。其夜即能安寝。次日再以四君子汤加当归、香附、贝母、陈皮、条芩、紫苏梗、前胡，调理足月而产一子。", "6052": "令弟媳六娘子，遍身痛，发热，汗大出，昏昏如醉，卧不能起。两寸脉短弱，两手皆数而无力，此劳倦之余，故汗大走也。黄耆三钱，白芍四钱，粉草一钱五分，桂皮八分，当归一钱，石斛二钱。一帖热除，痛、汗皆止。惟倦而不能起，仍以前方加人参、陈皮，两帖而痊。", "6053": "姚弁山老先生内人，自上年十月，左足不能履地。至十二月，产后忽好三日，复不能动，时常胸胁作痛，素多痰火，而治者卒以四物汤、天麦门冬为主，间服独参汤，服将弥年，而病如故。予诊之，两寸脉俱洪滑而数，夜分发热，此系湿痰凝滞，补塞太重，故迁延不脱。乃以二陈汤加苍术、黄柏、威灵仙、五加皮、生地黄、白芥子、白芍药、当归，两帖，胸胁痛止，热除，再加薏苡仁，八帖，而足能举步矣。", "6054": "李坦渠老先生令子室，十月发寒热起，一日一发，咳嗽，心痛，腰亦痛。至次年正月十七日，始间日一发，肌肉大瘦，喉疼，汗出如雨，白带如注，饮食减少，百试而汗不止，延予为诊。其脉右手软弱，左手散乱，此汗多而脉不敛，病势至此，危之甚矣。书云火热似疟，此病之谓欤？以黄耆二钱，白芍一钱五分，粉草、阿胶各一钱，鳖甲三钱，桂枝五分，乌梅一个，水煎服。其夜汗止。次早诊之，左脉已敛，神气亦回。前方加何首乌、石斛、牡蛎。其日寒热亦不发，饮食稍加，骎骎然有幽谷回春之象。", "6055": "太学周衡宇先生，吴江澜溪人，大冢宰白川公之令孙也。近来咯血色紫，胃中痰火素盛，壅于胸膈，作痞作疼，痰与瘀血挟而为热。脉左寸洪大，右寸关皆滑，两手尽数，此有余之候。总管丸四钱，再以滑石、桃仁各三钱，山楂二钱，枳壳、栀子、贝母、红花、丹皮各一钱，茅根五钱，水煎服之。次日大便行三次，痰积极多，内带瘀血。改以山栀子、紫菀、丹皮各一钱，滑石三钱，桃仁一钱五分，小蓟三钱，茅根五钱，水煎，加童便一酒杯，三帖全安。", "6056": "大参张公，分守杭嘉湖道，因丧夫人，衙中亡者八口，心中惶惶。因凌绎翁交厚，而礼予为诊。左寸脉短，关弦，右关滑，两尺亦弦。据脉心血不足，中焦有痰，流于下部，凝于经络，以故腰膝酸疼，居常背心作胀，头多眩晕，夜睡多汗。先时诸医悉投风剂，非所宜也。予以陈皮、白芍药、木瓜、牛膝、五加皮、苡仁、黄柏、酒芩、甘草、生地、当归、威灵仙调理，十剂，诸症悉愈。", "6057": "张丽川咳嗽多痰，面青，潮热，肌瘦，性躁而多自用，以数考不利，悒悒成疾。又新婚之后，饮食不节。脉之右关滑大，余部皆无神气，且粪门已发瘘疮，溃流脓血。予曰：此阳病极而下也。法在不治，果不逾月而亡。", "6058": "陈仰山先生内人，小产后二月而血大下。白沫如注，五更泄泻，面虚浮，下午身热口渴，面色青黄，脉右手豁大近芤，左濡弱。据此，大虚之候，血海尚有瘀血不尽，以致新血不得归源，稍动气即下如崩。盖脾乃统血之经，虚则不能约束，且面浮食少，脾虚剧矣。急宜温补，势或可为。人参、白术各二钱，姜炭、粉草各五分，茯苓六分，香附八分，丹参炒过一钱，水煎服。四帖而泻止。再以人参、白术各二钱，茯芩、丹参、黄耆、蒲黄各一钱，姜炭、泽兰叶、粉草各五分，调理痊愈。", "6059": "张溪亭乃眷，喉中梗梗有肉如炙脔，吞之不下，吐之不出，鼻塞头晕，耳常啾啾不安，汗出如雨，心惊胆怯，不敢出门，稍见风即遍身疼，小腹时疼，小水淋涩而疼。脉两寸皆短，两关滑大，右关尤搏指，此梅核气症也。以半夏四钱，厚朴一钱，紫苏叶一钱五分，茯苓一钱三分，姜三片，水煎，食后服。每用此汤调理多效。", "6060": "溪亭子室，妊已七月，梦见亡过祖母，挥拳背打一下，惊醒即觉胎动不安，血已下，大小便皆急，腰与小腹胀疼者五日，此亦事之奇也。迓予为治。两寸脉俱短弱，此上焦元气大虚，当骤补之。人参、阿胶、黄耆、白术各二钱，当归、白芍、条芩、杜仲各一钱，砂仁、香附各五分，苎根嫩皮三钱，葱白六钱。一剂而血止，两剂诸症悉除，而神渐安。四帖后，减去苎根、葱白，调理旬日。足月而产一女。", "6061": "陈茂之，劳倦之后，勉强色欲，精竭而血继至。续感风寒，发热头痛，胸膈饱闷。始从太阳而传之少阳，胸胁痛而耳聋，呕逆口苦，咳嗽，六脉俱弦数，此少阳症也。以小柴胡汤加枳壳、桔梗、竹茹，而呕逆止，热退。因进粥早，夏热口渴，小水不利，大便一日夜六七次，所行皆清水，日晡热甚，舌上黄苔，昏沉振颤。此食夏之候。书云：渴而小便不利者，当先利其小便。以猪苓汤为主。猪苓、泽泻各二钱，滑石三钱，赤茯苓一钱，柴胡八分，升麻、木通各五分。连进两帖，小便利而大便实，但热不退。以六神通解散一帖，其夜热仍不退。次早诊之，左脉不弦数矣。两寸脉虚，以故服药无汗，口渴，漱水而不欲咽，咽热，此邪传阳明经，不急凉血，必作鼻衄，病势至此，可谓极恶矣。投黄芩芍药汤合生脉散以止嗽渴，用葛根汤以解肌热。白芍药三钱，葛根、升麻、黄芩各一钱，人参一钱五分，麦冬、滑石各三钱，甘草、五味子各五分，乌梅一枚。急煎二帖饮之。日中大便下燥粪十数枚。始得微汗，就得睡矣。晚进粥一盂，夜卧向安。", "6062": "沈大参玉阳老先生，中焦有食积痰饮而作痞滞，以故大便了而不了，间或作胀。予脉之，两寸短弱，关滑，两尺沉滑有力。予曰：脾胃经有湿痰，蕴而为热，但清其中宫，使清阳升，浊阴降，而气血自旺，此不补之补也。以二陈汤加枳实、酒连、酒芩、滑石、姜黄、木香、干葛、山楂，两剂而愈。", "6063": "王敬泉头晕且痛，起则倒仆，胸膈胀闷如绳束缚，呕吐而食饮皆不得入，六脉俱涩，此痰饮挟木火之势而作晕也。先以济生竹茹汤而吐不止，且烦躁发眊、发热。再与芦根汤，连进二碗，气眊稍定。再以吴茱萸一两为末，以鸡子心调涂两足心，引火下行，外用二陈汤加姜汁炒黄芩、黄连、旋覆花、枇杷叶、丁香、白豆仁、槟榔、柴胡，水煎服之。服后热退，大便亦行，头晕呕吐皆止。惟胃脘有一块作痛，仍与前药两剂，而块亦消。", "6064": "张二官发热头痛，口渴，大便秘结三日未行，脉洪大，此阳明少阳二经之症。用大柴胡汤行三五次，所下者皆黑粪，夜出臭汗，次日清爽，惟额上仍热。用白虎汤加葛根、天花粉。因食粥太早，复发热咳嗽，口渴殊甚，且恶心。用小柴胡加枳实、山栀子、麦芽。次日渴不可当。改以白虎汤加麦门冬、天花粉，外与辰砂益元散以井水调下五钱，热始退，渴始定。不虞夜睡失盖，复受寒邪，天明又大发热，不知人事，急用小柴胡汤加升麻、葛根、前胡、薄荷进之而汗出热退，神思大瘁，四肢皆冷，语言懒倦，且咳嗽。以生脉散加石斛、百合、大枣、白芍药，服后咳嗽寻止，精神日加，饮食进而向安矣。", "6065": "大司马潘印川第三令子室，尚书蒋公孙女也。年二十五，体素弱，语言端谨。因难产伤力，继以生女拂意，后又女死悲戚，即时晕厥，醒而神思咪昧，手足瘛疭，目作上视。予更后始至，因瘛疭不能诊脉，细询之，自女落地，恶露绝无，比有女医在旁，乃昔所亲信者，时与人参大嚼，及独参汤并粥乱进，参与粥皆壅塞膈上不下，以故神昏瘛疭不已也。予教以手于喉中探而吐之，喜其随手吐出痰饮、粥、药盈盆，瘛疭方定。乃与川芎、山楂、泽兰叶、陈皮、半夏、茯苓、香附进之，稍得睡。予亦出中堂就寝。不虞女医又私与补药二帖。子丑时，陡然狂乱如降神之状，口中乱语云：我是观音大士降坛。所言皆儒雅官话，问答如流，声甚壮厉，殊无产后不足之态。生平不谙汉声，至是出语如生成者，人皆异之，目为神附，禳祷百般。予独诤之，语诸左右曰：此恶露不尽，乃蓄血如见鬼之症，非真有神佛相附也。徐以正言叱之即缄默，继以清魂散加滑石、童便与之。至天明小水乃行，狂乱皆定。迨予出房少顷，讵知女医意欲要功，又不知与何药服之，少刻狂乱如前。再与川芎一钱五分，当归四钱，泽兰叶、益母草各一钱，临服加童便，连饮二帖不效。予逆思之，胸中必有余痰作滞，前剂中无佐、使之品，故药力不行也。即用前剂大加山楂与之，恶露稍行，神思即静，嗣后稍睡少时，手足微动，或自以手掌其面，或自以手捶其胸，昏乱不息。诊其脉近虚，早间面红而光，申酉时面色白，此血行火退，故脉虚而当补矣。与人参、川芎、泽兰叶各一钱，当归、山楂各二钱，茯苓、陈皮各八分，卷荷叶一片，煎熟调琥珀末子五分，服下半时许，嗳气二声。予喜曰：此清阳升而浊阴降矣，自兹安静。夜中恶露行，大便亦利，乃索粥饮。问其昨日汉声何来？答曰：不知也。诸君始信蓄血如见鬼之言为不诬。昔秦越人有言曰：病有六不治，信巫不信医一不治也。古称用药如用兵。以郭子仪之英明，而以鱼朝恩监之，便不成功。予固非郭令公之俦，彼女医之误，则又有过于鱼朝恩矣。噫!宁不慎哉？", "6066": "孝廉臧茗泉老先生，脉左弦数，右寸弱，关大，重则滑，右尺微。原以疟后复伤饮食，大便泻而变痢，一日夜虽只五六行，皆积滞无粪，腹疼后重难安。午未后发热，至天明始退，此夏伤于暑而秋为疟痢也。其热仍疟之余邪，当先解散，然后以补剂投之，则大便自愈矣。与神授香连丸一服。服讫，腹中肠鸣，须臾大便行，且较前更多，方有粪下。改以白芍药四钱，泽泻、黄连各一钱，滑石二钱，粉草、桂皮、木香各四分，山楂七分，两日后，乃与补中益气汤加木香、黄连、白芍药。调理半月，潮热，大便皆愈。", "6067": "包继可先生令眷，孕三月而疟疾发，先寒后热，胸膈大胀疼，口渴，汤水入即吐，谵语，无汗，胎气上冲而成子悬，脉皆弦大，以川芎、柴胡、黄芩、知母、甘草、橘红、紫苏、枳壳、砂仁，水煎服之，吐止痛除。", "6068": "一张氏妇，年才二十一，其夫延余诊之。左寸关短弱，尺滑，右寸亦滑，关濡弱，尺沉微。诊毕问予曰：脉何如？予曰：心神脾志皆大不足，肺经有痰。夫曰：不然，乃有身也。予曰：左寸短弱如此，安得有孕？夫曰：已七十日矣。予俯思久之，问渠曰：曾经孕育否？夫曰：已经二次，今乃三也。予问：二产皆足月否？男耶女也？夫曰：实不敢讳，始产仅九个月，手足面目完全，而水火不分，脔肉一片，生下亦无啼声，抱起已身冷矣。细检之，乃知其无水火也。次亦九个月，产下又无啼声，看时口中无舌。二胎之异，不知何故？闻先生能细心察人之病，特祈审之。予方悟前二胎之不完者，由心脾二经不足所致也。今左寸右关之脉可见矣，乃为筹思一方，专以补心血为主，令其多服，以百帖为率。酸枣仁、远志、茯神各一钱，白术二钱，白芍药、当归、枸杞子各一钱五分，甘草五分，生地黄八分，艾絮二分，龙眼肉五枚，水煎服。足月而产一子。次年又有身，不以前事为意，至九个月，产下形体俱具，外有脂膜一片包其面，耳目口鼻不见，但不能去此脂膜，产下即殁。因思上年之子，为药之力也。因予久不至苕，其家以予方黏于壁间，一觉有身，即照方服之。后生二子一女。里中以此方为补天手云。", "6069": "癸巳仲夏，吴比部凤麓父母，以次君弦台先生眼目红痛，恐学道按临，速于取效，乃听眼科罄寒凉而治，两越月无验。又眼科视之曰，目疾不宜多用寒凉，恐冰其血。以人参五钱，枸杞子一两，悉温补之剂。凡用人参、枸杞子五六斤矣。目肿如桃，绝不能开。又专科语之曰：红肿而痛，明是热症，误服温补，反助其热，宁不益肿。顾其势，即百寒凉亦不易瘳，捷径无如用下，此釜底抽薪法也。弦台惟其速效，一听下之，用大黄、芒硝、枳壳作大剂，下五六次，而饮食日减，恶心、畏风，则不能出房门矣。又专门谓前剂欠当，大泻之后，正合补也，又听补之。一补而目肿如旧。又有眼师云：目疾热症多，寒症少，只当滋补肾水，水升则火自降，火降而目疾斯愈矣。用是以滋阴降火之剂为恃，才数服而精滑不禁，一夜梦遗一二次，神气大脱。投补则目肿痛，用降则精元滑脱，屡试屡如是。诸医无策，悉谢而退。乃修书命使自淮阴之海阳，恳祝令君介绍，征予为治。予始以远为惧，祝再四为渠言，予亦素为渠重义，不得以远为辞，乃解行李向往。至即诊之，左寸脉甚短，右寸大而无力，左关弦弱，右滑，两尺亦滑。予见其坐在幔中，略不敢见风。问其日食几何？答曰三次，计二碗许，荤腥绝不能用。予曰：夜卧安否？答曰：迩来甚苦于睡，才合目即梦魇可畏，或被虎蛇交咬，或有鬼来勾摄，或落桥坠井，或与人争门而负。猛然惊悟，冷汗淋淋，四肢瘫软，不能动惮，少顷乃定。今幸公不远千里而临，足征素雅。予曰：足下始无大恙，只缘大推大搬，以致狼狈若是。彼专科者，不足恃也。经谓五脏精华皆上注于目。今专科局局然守其死法，安知五脏盈虚，阴阳消长，随时出入哉。以愚管见，但平平治之易与耳。据足下之脉，心神脾志互相不足，肝胆之火郁而不散，致生目痹。今为补养心脾，壮其神志，则饮食日加，寝卧安稳，而精元有守，神水盈溢，何目痹之不愈哉!弦台曰：善，惟先生命剂。乃以归脾汤减去黄耆、木香，加丹参而补心脾，以大安丸专助脾胃，而磨谷食，俾新痰不生，则气血可继日而旺矣。后五日而饮食加；十日而梦魇少，寻能出户，不畏风日；半月而肌肉生，目可观奕，津津然而有万全之兆。不虞专门张氏子复至，以白眼药日频点之，一日凡七八次，后此复不能开，脸肉风粟生满。适予有南都之往，卒为所误。后幸有李少塘，打去风粟，眼始能开。李虽手法精熟，然于轩岐阃奥，尚亦未窥藩篱。予后自南都至，见左目虽愈，右目终成内障。予故曰：彼专科者，不足恃也，岂虚语哉!", "6070": "丘太守镇山翁令侄，淮阴人也。丁年患两手筋挛，指掉不能屈伸，臂肉瘦削，体瘠面白，寝食大减。市中诸友调治不验，乃任京口诸名家疗之半年，肉更消，色更瘁。闻予在吴比部衙中，敦予为治。诊其脉，六部俱弦，重按稍快。诊竟，扣其受病之源，太守公曰：自上年冬底，偶发寒热，筋骨疼痛，迨于仲春，寒热虽退，而筋骨之疼不减。服药无虚日，甚之日三四进，肉渐消去，指掉不随，似有加于往昔。医之来者，一曰风，二曰风，三四五六皆曰风，即十数辈，又莫不皆曰风者。竭技尽方，卒无一应，奄奄床第，绝不知为何病。予对公曰：此筋痿症也，乃少年不谨欲而受风湿，邪气乘虚而入。医者不察天时，不分六经，概而汗之。仲景治风湿之法，但使微汗津津，则风湿尽去，若汗大出，则风去而湿存，由是血气俱虚。经云，阳气者，精则养神，柔则养筋。虚则筋无所养，渐成痿弱，乃不足之疾。故陈无择、朱丹溪、刘宗厚皆谓诸痿切不可作风治，误则成痼疾，公闻言愕然曰：服风药几二百剂矣，顾今已痼，奈之何？予对曰：令侄青年，犹可图也。公曰：用何法？予曰：法当大补气血。经云：气主煦之，血主濡之。气血旺则筋柔而软，由是乃可以束骨而利机关也。抑何掉之有哉!病者闻言大喜曰：聆先生详病之源，治法之略，虽未服药，已觉沉疴去体矣!即请剂。予以五加皮、薏苡仁、红花、人参、鹿角胶、龟板、虎骨、当归、丹参、地黄、骨碎补、苍耳子之类。服两月，肌肉渐生，饮食大进，两手指掉亦平复。", "6071": "一书办年过五十，糟酒纵欲无惮，忽患下消之症，一日夜小便二十余度，清白而长，味且甜，少顷凝结如脂，色有油光。治半年不验，腰膝以下皆软弱，载身不起，饮食减半，神色大瘁。脉之六部大而无力。书云：脉至而从，按之不鼓，诸阳皆然，法当温补下焦。以熟地黄六两为君，鹿角霜、山茱萸各四两，桑螵蛸、鹿角胶、人参、白茯苓、枸杞子、远志、菟丝子、怀山药各三两为臣，益智仁一两为佐，大附子、桂心各七钱为使，炼蜜为丸，梧桐子大，每早晚淡盐汤送下七八十丸，不终剂而愈。或曰：凡云消者皆热症也。始公具方，人多议之，今果以温补成功，此何故哉？予曰：病由下元不足，无气升腾于上，故渴而多饮。以饮多，小便亦多也。今大补下元，使阳气充盛，熏蒸于上，口自不干。譬之釜盖，釜虽有水，若底下无火，则水气不得上升，釜盖干而不润。必釜底有火，则釜中水气升腾。熏蒸于上，盖才湿润不干也。予已详著《医旨绪余》中，兹不多赘。", "6072": "佥宪韩约斋老先生令子室，每动怒则夜卧不安，如见鬼魅，小水淋沥，今又大便秘结，腹中疼痛，腰胯胀坠如生产状，坐卧不安，因痛而脉多不应指。此肝经郁火所致，法当通利。以杏仁、桃仁各三钱，桕树根皮、山栀仁、青皮各一钱，槟榔五分，枳壳八分，水煎服之。少顷大便通，痛胀随减。", "6073": "佥宪韩约斋老先生夫人，向来夜分脐腹疼极甚，必用炒盐熨之，两时久乃止。次日必头痛，两太阳如箍，遍身亦疼，此上盛下虚症也。先用柴胡、川芎、粉草、酒连、薄荷、天麻、橘红、茯苓、半夏、蔓荆子、水煎服。数帖头痛全止，惟咳嗽胸前略痛。两寸脉浮滑，两尺弱。再用鹿角霜、鹿角胶、补骨脂、远志、枸杞子、金铃子、香附子，炼蜜为丸，梧桐子大，每空心及下午食前淡盐汤送下七十丸而瘳。", "6074": "武进令君孙康宇公子室，臧位宇丈女也。年十六，初产女，艰苦二日，偶感风邪，继食面饼。时师不察，竟以参术投之，即大热谵语，口渴，汗出如洗，气喘泄泻，泻皆黄水无粪，一日夜不计遍数，小水短少，饮食不进，症甚危恶。时当六月初旬，女科见热不除，乃投黄芩、芍药、黄连寒凉之剂，诸症更甚。又以参术大剂、肉果、干姜等止泻。一日计用人参二两四钱，泻益频，热益剧，喘汗转加，谵语不彻口。医各缚手辞谢曰：书云汗出如油，喘而不休，死症也。又汗出而热不退，泻而热不止，且谵语神昏，产后而脉洪大，法皆犯逆，无生路矣。惟附子理中汤，庶侥幸于万一。适予为顾太守肖溪公延至，即过为一诊，六脉乱而无绪，七八至，独右关坚硬。踌躇久之。因思暑月汗出乃常事，但风邪面食瘀血皆未消熔，补剂太骤。书云：蓄血如见鬼。治当消瘀血、面食，解其暑气，犹可图生，勿遽弃也。有臧玉宇者，位宇堂兄也。医有雅致，深以予言为然，而速予措剂。予曰；剂凭症发，难拘常套，不常之症，须用不常之药。乃用益元散六钱，解暑气清热为君。仲景云：渴而小便不利者，当先利其小便。况水泻，尤当用之为君也。以糖球子三钱为臣；红曲、泽兰叶各一钱五分，消瘀血、安魂为佐；香附一钱五分为裨佐；橘红、半夏曲、茯苓，乃统理脾气为使；京三棱五分，消前参、术，决其壅滞为先锋。水煎饮之。饮下即稍睡，谵语竟止。连进二剂，其晚大便减半。次日仍用前剂饮之，其夜热大减，大便只二次，有黄粪矣。恶露略行黑血数枚。又次日诊之，脉始有绪，神亦收敛，进粥一盏，大有生意。前方减去京三棱、红曲，加白扁豆。其夜大便一次，所下皆黑粪。从此热尽退，大便亦实。改用四君子汤加益元散、青蒿、香附、白扁豆、酒炒白芍药、炮姜，调理而平。", "6075": "吴东星上舍，辰州太守公长君也，冒暑赴南都试，落第归而怏怏，因成疟。自八月中旬延至十月，疟虽止，而腰痛白浊，日夜咳嗽，肌肉大消。药剂乱投。认为风者，以羌活、防风、续断等发散；认为虚者，以六味地黄丸为补；认为火者，以芩、连、栀子、黄柏、知母、天花粉、生地黄泻其火；认为半虚半实者，投以独活寄生汤；认为寒者，以大附子、肉桂、鹿角胶、参、术温补之。痛剧欲死，叫撼四邻。予脉之，左弦细，右滑大，俱六至。口渴眼赤。予知其昔患杨梅疮，余毒尚伏经络，适因疟后气血不足，旧毒感动，故痛而暴也。以当归芍药、甘草、牛膝、钩藤、苡仁、木通、白藓皮，用土茯苓四两煎汤代水煎前药。服下而痛止，咳嗽亦除，脉缓其半，连服数剂大效，精神渐复，乃起而督工视事。冬至日为酒兴鼓舞，纵欲无忌，次日腰如束缚，足面亦疼，左眼赤，小水短，足底有火从两胯直冲其上，痛不可言。予以当归、钩藤、甘草、白芍药、牛膝、苡仁、石斛、红花、生地、黄柏，调理三日，症已守定，略无进退。适大雪，寒冻殊甚，有女医为渠宅所亲信者，因其大便燥结，一日夜服玄明粉一两五钱，大便且不行，而腰痛愈猛，两足挛缩，气息奄奄，一语而三换气，面青惨。渠自觉危急，乃唤内人及弟叔嘱其后事。天明予至诊之，六脉俱伏，痛使然也。扣其由，乃知服玄明粉所致。予曰：症虽热，便虽燥，但公病不在肠胃，而在经络筋骨间，徒泻肠胃无益也。且冬月阳气闭藏，误泻则阳气亏乏，来春无发生根本矣。今四肢拘缩，腰胯痛剧者，由日来天令寒极，经络凝涩也。寒主收敛，法当温散寒邪之标，使痛定，然后复治其本，庶可保全。乃用桂心、杜仲、炙甘草、苍术、破故纸、五加皮、连与二剂，痛定而四肢柔和，饮食始进。予知渠宅素喜速效，予适有荆溪之往，乃宣言曰：足下之疾在经络，顾今天令严寒，幸宁耐以俟春和为足下拔去病根。渠宅不以予言为然，乃用张云溪调理，予亦赞张之可守，盖张氏药用养血清热，虽不去病，亦不害事。迨二月，太守公归，乃改用沈春宇，沈揣渠必以酒色而致阴虚，乃纯用滋阴降火之剂，以为旬日可奏功也。及调治月余，略无影响。予从荆溪归而谒渠，为三月初旬也。渠闻予至，即以沈药呈予，且语予：公许春和拔除病根，此其时也。予知太守公方笃信沈，随以温语慰渠曰；沈公名士也，可使彼展尽底蕴。沈又调理半月，以无功而行。沈去，予再以煨肾散进，大泻五六度，四肢冰冷，举家大恐，以予泻之为非也。予曰：病人此日减矣，夫奚忧？后进理脾药，服数帖，神气始转，腰胯柔和，可下床举数步矣。方始信而问予曰：人皆以补为治，公何得病源之真，于三月之前，先已预定，节节如公语也？予曰：此杨梅疮余毒伏于经络，岂补剂所能去哉!予故先为疏通湿热，然后以补剂收功，则无反复之患。后仍以威灵仙末子二钱，入猪腰子内，煨熟食之。又泻一二度，病根尽拔。改用苡仁、当归、生熟地黄、白芍药、牛膝、黄柏、丹参、龟板、调理全安。", "6076": "少司空凌绎泉翁，年已古稀，原有痰火之疾，因正月上旬，为令孙大婚过劳，偶占风寒，内热咳嗽，痰中有血，血多而痰少，痰坚不易出，鼻流清水，舌生芒刺，色焦黄，语言强硬不清，大小便不利，喘急不能睡，亦不能仰，惟坐高椅，椅前安棹，棹上安枕，日惟额伏枕上而已。市医环治半月不瘳，敦予诊之。两手脉浮而洪，两关滑大有力。知其内有积热痰火，为风邪所閟，且为怒气所加，故血上逆。议者以高年见红，脉大发热为惧。予曰；此有余症，诸公认为阴虚，而为滋阴降火，故不瘳。法当先驱中焦痰火积热，然后以地黄补血等剂收功，斯不失先后著也。翁以予言为然。用栝蒌、石膏各三钱，橘红、半夏曲、桑白皮、前胡、杏仁、酒芩、紫苏子，水煎，临服加入萝卜汁一小酒盏，一剂而血止。次日诊之，脉仍浮而洪大，尚恶寒。予曰：古云伤风必恶风，伤寒必恶寒，此其常也。只因先时失于清散，表中之热未彻，竟用滋阴之剂，又加童便收敛，降下太速，以致风寒郁而不散，故热愈甚也。改以定喘汤，一剂而喘急减半，再剂热退而不恶寒。复为诊之，两手浮体已无，惟两关之脉甚鼓指，此中焦痰积胶固已久，不可不因其时而疏导之。以清中丸同当归龙荟丸共二钱进之。其夜大便所下稠黏秽积甚多。予忆朱丹溪有云：凡哮喘火盛者，以白虎汤加黄连、枳实有功。此法正绎翁对腔剂也。与十剂，外以清中丸同双玉丸夜服，调理而安。", "6077": "令郎采石先生，中焦湿热生痰，痞闷，五更倒饱，且下午两股或膝下筋脉抽掣疼痛，时常嗳气，面色带黄，间常梦遗。予以清气大安化痰丸，及猪肚丸二方调治而安。猪肚丸用白术五两，苦参酒炒二两，牡蛎煅过三两，为末，将雄猪肚子一具，摘去油，甘草汤洗过，将药装入肚中，缝其口，饭中蒸极烂为度，捣极匀为丸，此方极健脾去湿热、固精丸也。清气大安化痰丸用白术四两，橘红、半夏、山楂各三两，黄芩、黄连俱生姜汁炒，各一两五钱，枳实、栝蒌仁各二两，白芥子、萝卜子各炒一两，姜黄碱水煮干一两，青黛五钱，麦芽取曲打糊为丸，绿豆大，每食后及夜，茶送下二钱。", "6078": "闵文学蜃楼，患虚损咳嗽，昼轻夜重。乃政丁氏，长兴富翁女也。躯甚肥，性甚躁，患痛风，手不能沐栉，足不能履地，凡痛处略肿，呻吟喊叫。比有朱远斋氏，为时推重，夫好倚朱治者七越月，纤毫不减。吴九宜翁乃举予治。至其家，蜃楼大兄岳楼，旦暮与偕。诊毕，语岳楼曰：令弟之症，虽易见功，然非百日不能断根。丁氏症，十日便可刈其根，但恐不能尽五剂，奈何!岳楼曰：何谓也？予曰：令弟咳嗽，由肺火未清，误服参术太过而然。但为清肺利肺，咳可立止，止后以补心安神之剂养之，则万全矣。药用麦门冬、桑白皮、白药子、贝母、桔梗、甘草、黄芩、枳壳，十帖咳嗽全止。惟心血不足，神不固精，以酸枣仁、远志、麦冬、莲花心、丹参，调养百日，果能出户肄业。丁症乃湿痰凝滞经络作痛，朱公作血虚而投以地黄、芍药、当归、人参、牛膝之类，宜其痛愈加而病愈久也。今必须燥湿流动之剂，疏决一番，庶经络通畅，虽不服补剂，而五谷精华足以自充。但疏决之剂，不能止痛，恐其不信余而中止也。岳楼曰：先生既已言明，惟命是听。用二陈汤加乌药叶、苍术、僵蚕、海桐皮、南星，服至五帖，果不怿而欲止药。岳楼曰：孙君已先言十帖见功，今过半，何不勉强而使功亏一篑哉？又服一帖而止，百般强之不从。乃扬言曰：请医疗痛而反加痛，吾何药为，后四剂断断乎不敢奉命矣。时巳申刻，予知其富家娇态，亦不强服。随以芫花醋炒过三分，海金沙一分为末，白汤调下。至晚泻一次，下稠痰半盆。足痛减大半，稍能动止。初更后吾辈酒犹未散，忽服云腹中大痛，促予进看。行至后堂，内中人出而止曰：病者卒矣，不劳进看。予曰：此必痛厥，非长逝也，乌可不进一看。至即冷汗淋漓，兀坐溺器，面青息断。执而诊之，手冷如冰，但六脉俱在，惟沉伏耳。知其为痛极使然，用生姜汤灌之而苏。徐语近侍女使曰：适来腹中痛甚耳。后火光溅出，肛门如焚，大响一声，不知泻下何物。众看之，乃血鳅一条，长六寸，阔半寸余，鳞目俱在，盆中尚能游动，众皆悚骇。岳楼问曰：此鳅下可好否？予应之曰：此尤物也，得下岂不好，但丁症实由痰作，予特为行痰，初不知其有虫，如是第药中有芫花，乃杀虫之物，故偶中，亦令弟之福也。次日手足皆能动，仍以二陈汤加苡仁、红花、五加皮，四帖，脱然如故。闵宅以予不矜功而益重予。", "6079": "金寄闲令堂暑月患痢，小腹窘迫，胸膈膨胀，口舌焦渴。右寸关脉洪滑，左脉弦，乃气郁食积痢也。先与木香槟榔丸开而下之，微利一二度，因口渴食西瓜一片，即恶心而吐。昨日大便利后，胸膈宽快，就进饭一碗，致腹饱闷，兀兀欲吐，所吐皆痰涎。乃以温胆汤加减治之。半夏四钱，枳实一钱五分，竹茹二钱，橘红、茯苓各一钱，甘草五分，姜连八分，生姜五片，水煎服之。一饮而胸膈舒畅，便能就枕而睡，恶心顿无，痢亦寻止。", "6080": "徐中宇之妇，汗出如雨，昏昏愦愦，两手无所著落，胸要人足踹之不少放，少放即昏愦益甚，气促不能以息，稍近风则呕恶晕厥。与九龙镇心丹一丸，服下即稍定，少间则又发，始知胸喉中有物作梗而痛，汤水难入，即药仅能吞一口，多则弗能咽下。乃以苏合香丸与之，晕厥寻止，心痛始萌。昨日六脉俱伏，今早六部俱见，惟左寸短涩，知其痛为瘀血也。用玄胡索、桃仁、丹皮、丹参、青皮、当归、香附。其夜仍晕厥一次，由其痛极而然。再与玄胡、丹皮、桃仁、丹参、香附、青皮、乌梅、人参、贝母、桂枝、赤芍药，服此痛减大半。乃自云心虚，有热，头眩。加山栀仁。居常多梦交之症，近更甚，以其心虚故也。人参、石斛、丹参、贝母、当归、白芍药、酸枣仁、酒连、香附，调理全安。", "6081": "金文学达泉先生令政，暑月患痢赤白，一日夜三十余度，后重腿急，口渴，小腹痛。孕已二月，幸而腰不痛，右手脉弦，左脉滑。与白芍药三钱，黄连、黄芩、当归、陈皮、香附各一钱，桂皮、木香各五分，水煎服。外与香连丸，服下后重稍轻。因进饭太早，其夜仍十数度。次早诊之，右弦减半。前药煎成，吞女金丹，一帖痢减大半，六脉已和，但软弱。此气血不足，宜从补养，用八珍汤加陈皮、香附、阿胶、条芩，一帖全安。凡孕妇痢疾，后重稍轻，腹痛稍减，独痢不止，必须补养气血为主，加调气之剂为佐，庶可保胎。斯亦丹溪虚回而痢自止之意也。", "6082": "金元岩文学，下午发热，痢下红多白少，一日夜七十余度，后重下坠，饮食不思。左脉细数，右脉滑，此阴虚之候。询知二日前曾梦遗，续得痢疾，阴虚明矣。但滑脉主食积。法当先补后攻，乃与小建中汤一帖，白芍药三钱，桂枝七分，粉草、酒连、酒芩各八分，当归一钱，槟榔五分，水煎饮之。夜半复诊，脉稍克指，改与枳壳三钱，桃仁一钱，当归四钱，煎熟，吞木香槟榔丸一钱五分。至天明大便泻三次，则见粪矣。次日午进饭，又食火肉，随即大便频，并后重如前，与山楂枳术丸一服不效，再为诊之，六部皆虚软无力，独右关滑，此进肉、饭太早，脾弱不能消磨，宜健脾气兼为升举。人参、黄耆各二钱，白术一钱，升麻三钱，防风、藿香、炮姜、粉草各五分，白芍药一钱半，茯苓八分，连进两帖，痢减而后重宽。因食狗肉过多，复伤脾气，前方加砂仁、山楂，调理痊愈。", "6083": "金文学达泉先生，因食肝白肠内伤，续又冒风，就成疟痢，日夜四十余度，小腹痛甚，每登厕汗出如雨，下迫后重，小水涩痛。头疼口渴，下午发热，天明始退。左脉浮弦而数，右软弱，中部稍滑。此内伤饮食，外感风邪，疟痢并作。法当速治，否则深秋阳气潜藏，邪因陷下，未易瘳也。乃先与柴苓汤一剂，小便即清，不痛。疟发时寒多热少，晚与人参败毒散加减。人参、干葛、防风、桂枝、粉草、茯苓、枳壳各五分，柴胡、白芍药各一钱，水煎饮之。次日头痛痢疾俱减，夜才起三次。改与补中益气汤加酒芩、桂枝、白芍药，其夜疟止，但微热，再改胃风汤，人参、白术、桂皮各二钱，白芍药四钱，当归一钱五分，茯苓、川芎各八分，酒芩、酒连各一钱，炮姜二分，地榆五分，服后寒热殄迹。夜起一次，已是真粪。前方减去桂枝，再三剂而巾栉出户矣。", "6084": "金寄闲先生，七月既望，患头痛口渴，汗大泄不敛，呕恶发寒热，间日一发，而发于阳日，乃为诊之，两寸洪大有力，左浮弦而数，右脉稍软，亦弦长。此少阳与阳明合并为疟。以柴葛解肌汤主之。柴胡、葛根各二钱，白芍药、石膏各三钱，粉草、桂枝各五分，知母一钱，姜三片，水煎饮之。次早左脉稍退，乃与补阴鳖血何首乌丸截之，又与黄耆芍药汤一帖，以防作痢。白芍药、石膏、黄耆各三钱，桂枝五分，知母、粉草各一钱，柴胡七分，姜三片，煎服。后加人参七分，疟竟全止而向安矣。", "6085": "淮阴胡少泉翁，丽水县三尹也。令郎年弱冠患梦遗，百治不应。体倦而气弱，食少而汗多，四肢酸软，头眩，肌热，将成瘵疾。知予在理刑吴比部衙中，敦余为治。其脉两寸短，左寸尤甚，余部滑数。余曰：郎君之脉，心气大弱，盖心者，神之舍；神者，精之主。神旺始能固精。今遗不禁，由神弱不能固摄其精，致多妄泄。时近端阳，诸症丛集，乃兼疰夏病也。法当养心安神，庶几不成瘵。翁曰：然。前此诸公，每为滋阴降火，多不见功，徒见损脾减食。今先生主以养神，愿以先生是听。乃与人参、黄耆、石莲子、酸枣仁、莲花心、石菖蒲、远志、当归补心安神为君，俾精固汗敛。经曰：汗者心之液。汗多则心血愈虚，故佐以甘草、白术、黄柏、麦门冬、五味子兼治疰夏，使饮食加而四肢壮，缓而图之可万全矣。药进甚妥，竟以此方调理，果精固神全，肌热尽退。又令媛及笄，头痛微热，经水愆期，日多咳嗽，食渐减，肌渐消，口渴，睡卧不宁，喉中血腥，四肢不劳而疲，体不动而汗，六脉弦而且数，左关长出寸口。余以逍遥散加石斛、丹参、牡丹皮、酸枣仁、山栀子、麦门冬，调理而瘳。", "6086": "前丘一染匠之妇，腹痛两月矣。或以为寒，为热，为气，为虚，为食积，为虫，递尝试之转加。一医与膏药如斗大者一个，满腹贴之，痛益剧。乃揭去膏药，即贴牢不可起，火熨油调，百计不能脱分寸，如生在肉上相类。无可奈何，知予在吴乡宦宅中，乃买舟就予诊。及抵吴门桥口，匠偕乃母乃姑四人尽力扶挽，绝不能动移一步。岸上环视如堵，莫不语匠曰：病势若此，时刻难抵，固乃强其起而欲污吾桥口耶？匠乃止妇舟中，起而垦予为治。至舟中，见其面色苍黑。及伸手求诊，皮肤燥若老松树皮之状。六脉皆洪数。问其腹中之痛何在？匠即为解衣露腹指其痛所，始知膏药黏牢之故，此甚希觏。叩其不能举步之由，妇曰：非力弱不能行，乃左脚不可动，动即痛应于心，是以一步不能举也。予俯思，若色若脉，皆非死候，胡治而益剧也？此必肠痈，左脚莫能举是其征也。与营卫返魂汤，加金银花为君，与四帖，酒水各一碗煎服。一帖痛稍减，二帖下臭脓半桶，痛全减。腹上膏药不须手揭，自脱而下。由热去而膏脱也。四帖完，其妇同匠诣吴宅拜谢予，并求善后之方。吴宅见之，一族皆惊。", "6087": "王祖泉，大便里急后重，腹痛，日夜下紫黑稠黏三四十度。市中凡有名者，雷同痢治。自秋历冬，三越月不瘳。形色瘦瘁，匙箸厌举，即勉强，仅一盏而止，眼阖懒开，悉以为不治弃去。访余脉之，六部濡弱，观其所下之色甚晦，如芋苗汁之状。予曰：观此色，非痢，乃脏毒下血症。《医说》中人参樗皮散，正此对腔剂也。即制与之，其夜果减半，终剂全愈。方以人参、樗根白皮各二两，为末，每空心米饮调服二钱，忌肉汁，生菜、鱼腥。", "6088": "癸巳秋仲，南都大司马袁洪溪老先生，以兼署工部都察院，操江印日，冲暑往来各衙门，而经络其政事，致发热燥渴。因解燥渴，而过食水浸瓜梨新藕，遂成泄泻，小水短少。医以胃苓汤加滑石、木通、车前子利之而泻止。大便又因之结燥，艰涩不堪。乃用润肠丸，复泻不止。又进以前通利之剂，泻虽止而小水竟不得流通直遂，脐下胀急。立起解之，则点滴不出，卧则流之不竭，以频取夜壶，致通宵不得寐也。治半月余，而精神削，寝食废。闻予寓崔勋部衙，而征予治。初见即告以受病之源，又谓都城诸医俱不识为何症。将认为癃，则立解时点滴不出；认为秘，卧则涓涓而流；谓为脾约，大便又不结燥；谓气虚下陷，心血不足，而补中益气汤与安神丸，服过十昼夜无益。雅闻先生高手，愿一诊以决之。探其脉，两寸短弱，关缓大，两尺洪大。语之曰：此余暑未解，而司马素善饮，湿热流于下部也。今已下午，恐诊之未准，俟明早细察而再定方。公曰：延颈吾子久矣，适所言近似，愿亟求一剂饮之，侥夜间一睡。予不得已，以益元散三钱，煎香薷汤进之，略无进退。次早复诊，六脉如昨。予思之而恍然悟。又语之曰：此症尿窍不对也。司马曰：名出何书？予曰：《内经》云：膀胱者，脬之室也。脬中湿热下坠，故立解而窍不对，小水因不得出，卧则脬不下坠，而尿渗出膀胱。亦以窍不对，小水虽涓涓而流，亦不能通达直遂，故了而不了也。治惟提补上中二焦元气，兼清下焦湿热，斯得矣。又有一法，今气虚下陷已久，一两剂未能取效，安得伏枕而睡？且此不寐，非心血不足之故，因著心防闲小便之了而不了而不敢寐也。暂将旧衣或布衬于席上，不必防而任其流出，又免取夜器而劳动其神，自然熟睡矣。以补中益气汤提补上中二焦之元气，加黄柏、知母、祛下焦之湿热，夫清阳升则浊阴自降，脬无湿热则不下坠，窍可对而病可瘳矣。司马忻然请药，夜如法衬之，果嗒然一睡，相忘其尿之出不出也。次早视衬布，虽湿而不甚。以久不阖目，得此一睡，神气顿回，胸臆爽快如未病者。调理四日而病全安。司马大喜，而欲留久住，缘漕运李公相延之亟，勿克也。差大马舡，鼓吹送予阡关而还。", "6089": "崔百原公者，河南人也。年余四十矣，而为南勋部郎。患右胁痛，右手足筋骨俱痛，艰于举动者三月，诸医作偏风治之不效。驰书邑大夫祝公征余治。予至，视其色苍，其神固，性多躁急。诊其脉，左弦数，右滑数。时当仲秋。予曰：此湿痰风热为痹也。脉之滑为痰，弦为风，数为热。盖湿生痰，痰生热，热壅经络，伤其营卫，变为风也。公曰：君何以治？予曰：痰生经络，虽不害事，然非假岁月不能愈也。随与二陈汤加钩藤、苍耳子、薏苡仁、红花、五加皮、秦艽、威灵仙、黄芩、竹沥、姜汁饮之。数日手足之痛稍减，而胁痛如旧。再加郁金、川芎、白芥子，痛俱稍安。予以赴漕运李公召而行速，劝公请假缓治，因嘱其慎怒、内观以需药力。公曰：内观何为主？予曰：正心。公曰：儒以正心为修身先务，每苦工夫无下手处。予曰：正之为义，一止而已，止于一，则静定而妄念不生，宋儒所谓主静。又曰：看喜怒哀乐，未发以前，作何气象。释氏之止观，老子之了得一万事毕。皆此义也，孟子所谓有事勿正、勿忘、勿助长，是其工夫节度也。公曰：吾知止矣。遂上疏请告。予录前方，畀之北归，如法调养半年，而病根尽除。", "6090": "琼兄内伤饮食，外感风邪，洒淅恶寒发热，烦躁不宁。已经表汗泻吐之后，小水短赤，口渴腹中疼，夜不能睡，耳聋气塞，神魂不安，懊𢙐不已。予脉之，两寸滑大，左关弦，右关滑，两尺皆弦皆七至。据此乃少阳阳明两经合病。仲景云：渴而小便不利者，当利其小便。先与柴苓汤加竹茹进之。耳稍聪，稍得睡，热仍不退，闻食气即呕，以济生竹茹汤加人参、麦冬、黄连与辰砂六一散三钱，服后神稍清，手足心仍热，用竹叶石膏汤而热亦不退，且懊𢙐殊甚，合目即谵语。按仲景谓伤寒汗吐下后懊𢙐不得眠者，热在心胸之间，宜轻涌之。以栀子豆豉汤主之。服后晚间仍不得眠，两耳气塞难当，改以小柴胡汤合白虎汤进之，即得睡。睡中汗出二次，耳顿通利。因进食早，又发热口渴，舌上黄苔，此阳明余热复萌，乃用石膏七钱，甘草一钱，知母三钱，黄连一钱五分，百合、竹茹各一钱，竹叶三十片，急进而热全退，始得获安。", "6091": "程龙邱翁每行动即作热发渴呕恶，腰与环跳常痛，脉左沉细，右寸滑，关尺濡弱，此上焦有痰火，下焦有湿热，治当流湿舒筋，然后施补。先用苡仁三钱，苍术、威灵仙、黄柏、乌药叶、紫荆皮各一钱，红花、桂皮、防己各五分，水煎服。外以鹿茸、虎骨、晚蚕砂、仙茅、黄柏、龟板、苍术、牛膝、杜仲蜜丸服之而安。", "6092": "汪松岗翁原伤于酒夜分有热，咳嗽咯血，不思饮食，左胁气不调，左寸脉芤，关涩，尺弱；右寸短，关滑。此胃中痰火正旺，气血俱虚，宜先清胃。保肺，然后大补。麦冬、知母、寒水石、甘草、紫菀、人参、牡丹皮、白芍药、当归、贝母、桑白皮煎服。一帖，红仍未止，加侧柏叶、茅根四帖而红止。过后四月，又为怒气所伤，血又动，左不能睡，桃仁、滑石、红花、当归、人参、贝母、山栀、甘草、香附、青皮、牡丹皮煎服而安。予嘱渠令子曰；寄语令堂，诸凡得意事可与尊翁知之，如不得意者切不可使之闻也。盖肝为藏血之所，况血去多，肝火刚燥，心主不足。《内经》云：主不明则十二官危。不可不谨防之。且左不得眠肝胀可知，予甚为尊翁虑。后三年，果为怒复，乃命使迎予，予固辞谢曰：何曾叮嘱，今病之来非不佞所堪任也。不逾旬而殁。", "6093": "族妹经不行者八十日，每饮食入腹即疼痛，必尽吐出乃止。居常亦吐酸水，上焦热，下焦寒，大便半月始一行，食饮不进者四十日。六脉皆数，左滑右软弱。妹能事者，以其夫多病，且不谙世故，由是悒悒，病从思虑而得，恐成膈症。今大便燥结、吐酸乃膈之征，急宜拂虑，庶药有功。先与丁灵丸一粒而吐止，继用温胆汤加大腹皮、姜连痛吐全安，改以二陈汤加香附、条芩、山栀仁、丹参、砂仁调理两月，经行，大便始润，而膈症斯不作矣。", "6094": "孙华野，脉沉弦而数，喉痛颊车肿，两太阳作胀疼，遍身皆胀痛，憎寒发热，乃痰火上壅而变风热，将欲作毒也，宜急治之。薄荷、甘草、升麻、白芷、石膏、枳壳、天花粉、桔梗、大力子、连翘、玄参，一帖而愈。", "6095": "显兄，每辛苦及酒多则咯血数口，脉两寸皆短弱，关尺洪数。此胃中有痰火，而下焦有阴火，由壮年酒色所伤故耳。以丹参、滑石各三钱，白芍药二钱，麦冬、贝母、桃仁、紫菀、牡丹皮各一钱，当归七分，甘草五分煎服而安。", "6096": "歙邑吴遂兄，木商也，在吴兴年七十。因冒雨劳力汗出，又以冷水澡浴，因而发热，口渴，心与背互相胀痛，小水长而赤，舌上黄苔，夜不得卧，眼目如金，皮肤尽黄。吴兴之医见之远走，不敢措剂，谓其年高不宜此病。赞劝回家，乃敦访予治。诊得左脉浮数，右濡弱，两手皆有六至。予曰：此湿热发黄症也。病虽重，年虽高，有是症当有是药，毋用仓惶。乃以柴胡三钱，酒芩、葛根、青蒿、香薷、天花粉各一钱，人参七分，粉草五分，连进二帖，晚得微汗即能睡，次早热退其半，舌苔稍淡润不焦燥矣。胸膈余热作烦，身黄如旧，以竹茹、青蒿、葛根各一钱，人参、麦门冬、天花粉、知母各八分，白芍药六分，二帖，热退食进，精神陡长。后于补中益气汤加青蒿、麦门冬、天花粉十帖而眼目肌肤之黄尽释然矣。吴兴诸公悉服其精当，各录方而传。", "6097": "族侄文学明之，以作文过劳，痰火上逆，大吐痰沫，因而呕血，一涌数碗。昏晕汗出，奄奄而卧，略不敢动，稍动即呕吐而血随出，色鲜红。饮食汤水皆不敢入，入即吐而眩晕，血即随之。里有婺君程闻野氏为之诊，骇而走曰：血如涌泉，体热脉大，眩晕而药食难入，似无佳兆。乃速予治，予诊视毕，语其乃兄勉之曰：可生也，何举家张惶若此？勉之以程言告予，予曰：看症要圆活，勿拘泥。据经云：心主血，肝藏血。又曰：怒则气上。又曰：脉虚身热得之伤暑。今左脉弦大，右脉虚大，明之不独作文劳心动火，且亦被怒伤肝，抑又为暑所逼，以致木火上升，眩晕作吐，经曰：诸风掉眩皆属肝木，诸呕吐逆皆属于火。又诸动属火。内为木火上冲，外为暑气所迫，故吐而汗多血随吐出也。医贵识病，有是病则有是药。予特以白丸子三钱，解其暑气，清其痰饮，抑其冲逆，则吐可止，吐止气平则血自能归经。服后果嗒然而睡，醒则吐止食进，眩晕寻已。继用滑石、香薷各三钱，甘草五分，黄连、白扁豆各一钱五分，竹茹一钱，四帖全安。", "6098": "族嫂程氏，年近五十，患咳嗽吐臭脓血，一日夜一碗余。发热昼轻夜重，肌肉大瘦，六脉浮而洪滑且数。人皆谓：呕血身热脉大，法在不治。予曰：此非吐血比也。此系酿酒伤肺，又为怒气所触，瘀血浊痰滞于肺之气窍，无从而出，久之化而为脓，成肺痈也。治宜开肺窍，活血化痰，使脓尽当自愈也，诸人治之，二年不效，予教以白芨、薏苡仁各三钱，牡丹皮、桔梗、茜根、归尾、山栀子、贝母、白芍药各一钱，甘草、葶苈子各五分，三十帖。痊愈。后寿七十三，以它病而终，此疾再不复发。", "6099": "族侄孙伍仲立年，善饮好内，小便血淋疼痛。予以滑石、甘草梢、海金沙、琥珀、山栀子、青蒿、茅草根煎膏为丸，梧桐子大，每空心及食前灯心汤送下三钱，不终剂而愈。后五年，因子迟，服补下元药过多，血淋又发，小便中痛极，立而不能解，必蹲下如妇女小解样，始能解出，皆大血块，每行一二碗余，如是者半月。诸通利清热之剂，靡不遍尝不应，脉俱洪数，予以五灵脂、蒲黄、甘草梢各二钱，小蓟、龙芽草各三钱，水煎空心服，二帖而痛减半，血仍旧。改用瞿麦、山栀子、甘草各二钱，茅根、杜牛膝、连叶车前草各三钱，生地黄、柴胡、黄柏、木通各一钱，四帖痛全减，血全止，惟小便了而不了，六脉亦和缓不似前矣。后以人参、葛根、青蒿、白术、茯苓、甘草、白芍药、升麻、黄柏、知母调理万全。", "6100": "令眷，辰州太守石峰公女也。吐红发热，经水二十日一行或一月行二次，白带且多，胸膈饱胀，脉洪数。以丹参、生地、山栀子、白芍药、小蓟、鹿角胶，水煎。临服前加入童便一酒杯，二十剂而瘳。", "6101": "侄孙少竹，大学生也，眼红肿胀。佘云谷以苦寒治时疾之剂与之，眼愈肿且增两太阳痛。前药中再加石膏，不惟眼肿不消，头痛不止，且令遍身胀闷，寝食俱废。予为脉之，弦大而无力，乃用蔓荆子、桑白皮、柴胡、香附、夏枯草、甘草、芽茶，一帖而痛定，两帖肿消，四帖全瘳。", "6102": "华岳令堂，年五十余，向来小水短少。今则右背盐匙骨边一点痛，夜尤痛，已经半月，医治不效，辗转加剧，即于右边手臂、肢节皆胀痛，筋皆暴起，肌肉上生红点子，脉两手皆滑数，右尺软弱，乃湿热伤筋而成痛痹，以东垣舒筋汤为主，羌活、升麻、桃仁、麻黄、红花、当归、防风、甘草、独活、猪苓、黄柏、防己、知母、黄连，两帖痛减肿消，再亦不发。", "6103": "由溪程两峰丈内人患血痢，里急后重，呕吐不纳谷，两寸脉洪大，以竹茹温胆汤加姜连、滑石、橘红、酒芩，水煎服。二帖大便结实，脓血皆止，惟后重。与枳壳、当归、芍药、生地、桃仁、条芩、甘草、滑石、酒连，四帖全安。", "6104": "由溪程七护兄，脐腹右边疼痛，小水短少，大便四日未行，呕吐不能进食，舌上白苔，面青手冷，势甚危急。脉之左沉伏，右滑大有力。予曰：此痰格中焦，气闭下焦，故大小便秘而不利，气逆呕吐也，不急治即无救矣，与桕树东行根皮二钱，滑石三钱，桃仁、青皮、枳实、槟榔各一钱，水煎服之。夜半吐出胶痰碗余，大便未行，痛亦不减。次日改用玄胡索五钱，水煎，临服调下玄明粉三钱，辰刻服下，午刻痛减大半，未刻大便始行，右脉平而左脉起矣。觉体倦无力，以生脉散加甘草、山栀仁、黄柏、芍药、苡仁、陈皮调理如故。", "6105": "由溪程社贵兄，先醉酒，后御色，次早四肢冷，胃脘痛极，脉仅四至。先医以郁火为治，投以寒凉痛更增极，三日前所食西瓜仍吐出不化。乃翁以为阴症伤寒，欲用附子理中汤，不决，逆予治之。予观其面色青，惨叫痛而声不扬，坐卧烦乱。予曰：此霍乱兼蛔厥症也。先当止痛安蛔，后理霍乱可免死也，迟则误事矣。急用五灵脂醋炒三钱，苍术一钱五分，乌梅三枚，川椒、炮姜、桂心各五分，水煎饮下，痛减大半，下午以大腹皮、藿香、半夏、陈皮、山楂、五灵脂、茯苓，两帖全安。", "6106": "孙熙宇肢节肿痛，痰多呕恶，胸中气不畅达，语言亦不清利，夜梦皆亡人野鬼追陪，精神惨恶，惊恐不安，且汗多不止，饮食减三之二。远近名家，医治逾月不应，敦予为治。诊其脉，左手甚弱，汗多故也。右手滑大，痰饮湿热而然。法当补敛，前医皆作风治而用疏散，泄其元神将成柔痁。予以人参、麦门冬、五味子、白芍药、当归、苡仁、陈皮、石斛、木瓜、甘草、白术、桂枝，服此汗大敛而神思稍清，吐亦止矣。惟饮食不思，夜梦与亡人同游为恶耳。改用人参、黄耆、枸杞子、苡仁、白术各一钱五分，当归、远志、茯苓、木瓜、陈皮各一钱，甘草五分，水二盅入雄猪心血一枚，煎作八分，饮之，四帖乃能睡，始梦生人，不复梦亡人矣。", "6107": "爱泉，上年十月因伤风咳嗽，即时声哑，继闻父伤过忧，右边不能贴席而睡。医以滋阴降火之剂治之，半年肌肉大削，大便溏泻，饮食减少，咳嗽声哑有加，喉且疼痛。迎余为治，诊得六脉俱弦数，此忧伤肺、思伤脾症也，危急甚矣，以白术、茯苓、陈皮、粉草、苡仁、桔梗、柴胡、桑白皮、酒炒白芍药、泽泻、麦芽、山楂，煎服一日，再以荆芥、桔梗、玄参、甘草、茯苓、白芍、酒连、扁豆、山药、山楂、木通，服此而右边可睡矣。改用参苓白术散加白芍药、乌梅、诃子、酒连、山楂，调理而愈。", "6108": "侄妇戴氏，有孕已五月矣。忽血大下，午后发战，六脉俱数，左寸滑大，右关搏指，左关软弱。予以白芍药二钱，生地、陈胶、人参、蒲黄各一钱，柴胡、香附、地榆、荆芥穗各七分，甘草五分煎服。午后发寒热，每夜凡三次，头痛恶心，腹中块硬，所下血块甚多，心下怯力，此虚无疑也。以补中益气汤加阿胶、炮姜、白芍药、乌梅煎服。下午右眼白珠发一白泡，光肿下垂，而面亦肿，此虚火游行无制之症。其夜大发寒热，指爪皆黑，唇白，汗大出，腹中作痛牵引两乳皆痛，仍以补中益气汤加阿胶、白芍药、桂枝、五味子、麦冬，服后热退，汗止，渴除，神气稍定，乃有生意。次日咳嗽而胎堕，即以独参汤继服，其夜肠鸣泻二次，以人参、白术各三钱，炙甘草一钱五分，炮姜一钱，桂心、茯苓各五分，陈皮七分，莲子、大枣煎服，后因咳嗽以四君子加炮姜、五味子、紫菀调理而愈。", "6109": "歙溪南吴人峰先生内人，两胁胀急抵于胃脘作痛，痛一阵则汗出一番，两颧红，唇口亦红，饮食汤水饮之立吐，不受者三日夜矣。予为诊之，两寸脉洪大，两尺沉微。予以井水半碗，白滚汤半碗和之，名曰阴阳汤，用此调玄明粉一钱五分服之，不惟不吐，痛减半矣。少顷大便行二次，因食豆腐及粥太早而痛复萌，唇脸皆红，此必有虫故如是也。与白芍药、桂枝、粉草、乌梅、花椒、五灵脂、杏仁水煎，痛乃定其大半，再与苍术、厚朴、山楂、枳实、茯苓、玄胡索、香附一帖，全止。但心背皮肤外疼，不能著席而睡，以川芎、当归、白术、厚朴、大腹皮、粉草、茯苓、香附、陈皮、半夏调养痊愈。", "6110": "程石洲乃眷因产难子死，忧闷，小腹有块作痛，下午发热不思饮食。次早诊之，脉右大于左者三倍且数。与芎归汤加糖球子、泽兰叶、肉桂。次日下午腰腹胀痛。诘之，晌午食圆眼一斤矣，从此小腹渐胀，大便三日未行，早晨鼻衄，夜间极热口渴，脉大无绪，势甚危急，用川芎、当归、红花、桃仁、青皮、槟榔、莪术、山楂，水煎调玄明粉二钱，服后大便稍行结粪二枚，安而就寝，醒后进粥稍多，又复胀痛，腹大如斗，坚如石，气促不安，势危至此亦已极矣。乃与五灵脂、糖球子各四钱，凌霄花二钱，赤芍药一钱，服后大便通，腹软气定。始可进粥，渐有生气，但脉仍鼓指，此腹中积滞尚多，不可不因其时而驱去也。用糖球子、大黄各三钱，桃仁二钱，桂心、红花各五分，炙甘草七分，水煎，临服调玄明粉一钱五分，其夜下黑粪四次，热始退，上腹虽消，脐下仍大，仍以桃仁承气加山楂、滑石、红花煎饮之。五更大便行，脐腹胀又渐减，后与积块丸调理全消。是役也，女流只知女科专门为仗，故前发热腹痛止之时，彼专门不察虚实，即以常套十全大补汤投之，讵知圆眼肉初入腹之时不觉，少顷渐渐胀开，故腹亦因之而胀也。且其味甘尤能作滞，复加地黄、参、术，宁不塞其塞哉？由是而成大满大坚之症。《内经》谓：中满者，泻之于内。良以此夫。彼亦泥乎丹溪产后须当大补气血之误也。", "6111": "文学程道吾先生令眷夜为梦魇所惊，时常晕厥，精神恍惚，一日三五发。咳嗽面色青，不思谷食。日惟啖牛肉脯数块而已。时师屡治无功。吴渤海视为寒痰作厥，投以附子、肉桂而厥尤加。逆予为治，诊左脉弦，右脉滑，两寸稍短。道吾先令眷二皆卒于瘵，知其为传尸瘵症也，不易治之。乃权以壮神补养之剂，消息调理，俟饮食进，胃气转始可用正治之法，姑用人参、茯苓、柏子仁、石菖蒲、远志、丹参、当归、石斛以补养神气，以陈皮、贝母、甘草、紫菀化痰治嗽，服半月而无进退。乃为制太上浑元丹，药用紫河车一具，辰砂、鳖甲、犀角各一两，鹿角胶、紫石英、石斛各八钱，沉香、乳香、安息香、茯苓、紫菀、牛膝、人参各五钱，麝香五分，炼蜜为丸，赤豆大，每早晚盐汤或酒送下三十六丸。又制霹雳出猎丹，药用牛黄、狗宝、阿魏、安息各一钱，虎头骨五钱，啄木鸟一只，獭爪一枚，败鼓心破皮三钱，麝香五分，天灵盖一个，炼蜜为丸，雄黄三钱为衣，每五更空心葱白汤送下五分，三五日服一次，与太上浑元丹相兼服，才服半月，精神顿异，不似前时恍惚矣，但小腹左边一点疼，前煎药中加白芍一钱，服之一月，精神大好，晕厥再不发矣。次年生一女，其宅瘵疾从此再亦不传。", "6112": "参军程方塘翁，年六十四，向以殈胤服温补下元药太多，冬月下身著单裤立溪边督工，受寒致筋骨疼痛，肩井、缺盆、脚、膝、跟、踝、手肘、掌后及骨节动处皆红肿而痛，卧床褥三年。吴中溪视为虚而用虎潜丸；吴渤海视为寒而用大附子、肉桂、鹿茸。徐东皋认为湿，周皜认为血虚，张甲认为风，李乙认为历节，百治不瘳。腿间大肉尽消，惟各骨节处肿大而疼。予适在程道吾宅，乃逆予。诊之，其脉弦涩有力，知其为湿热痰火被寒气凝滞固涩经络也。第为药剂不对，故病日加。所取者目中精神尚在，胃气仍未全损，但小水解下，以瓦盆盛之少顷则澄结为砂，色红而浊，两膝下及脚指皆生大疮，疮靥如靴钉状，此皆平昔服温补春方所致。病虽久，年虽高，犹为有余之疾，不可因高年疾痼弃不治也。乃特为先驱逐经络中凝滞，然后健脾消痰，俾新痰不生，气血日长，最后以补剂收功，斯得矣。翁生平好补畏攻，故进门者皆务迎合，予独反之。以新取威灵仙一斤，装新竹筒中，入烧酒二斤，塞筒口，刮去筒外青皮，重汤煮三炷官香为度，取出威灵仙晒干为末，用竹沥打糊为丸，梧桐子大，每早晚酒送下一钱，一日服二次。五日后大便泻出稠黏痰积半桶，肿痛消去大半。改以人参、石斛、苍术、黄柏、苡仁、苍耳子、牛膝、乌药叶、龟板、红花、犀角屑、木通煎服二十帖，又用前末药服三日，又下痰积如前之半。仍以前煎药服半月，又将末药服三日，腹中痰渐少，乃为制丸药，以虎骨、晚蚕砂、苍术、黄柏、丹参、杜牛膝茎叶、苡仁、红花、五加皮、苍耳子、龟板打酒，面糊为丸，梧桐子大，每空心白汤送下七八十丸外，以丹溪保和丸食后服半年痊愈，腿肉复完，步履如故。", "6113": "江东之丈，七月初旬自浙归，连日与客手谈过劳，口中生疮，医以香薷饮、清胃汤、泻黄汤、三黄丸、黄连解毒汤、白虎汤、凉膈散。凡治上焦热症之剂，竭寒凉而进之者十一日矣。口疮日甚一日，不但饮食不进，即药亦难下咽，因疮延及于喉也。逆予为诊，其脉六部俱豁大无力。诊罢，有外科陈氏者自称喉舌专门，炫其口疳敷药之妙。予曰：汝试为口中一洗，看是何状？才开口见涎沫迷漫，不能得见肉色，陈以荆芥汤洗而引之，搅出稠涎一二碗余。倾于地上，偶见二鸡争啄之，二鸡立毙，其毒何如？此亦疾之奇者。予嘱陈曰：汝用药只可吹入喉中，切不可敷其舌，必候喉中全好，然后敷舌，待舌好再敷口唇，甚毋得概敷。恐毒无出路，反攻入喉，极为误事。陈曰：诺。予对乃翁曰：令郎之疾，乃虚阳口疮也。翁曰：当用何剂？予曰：附子理中汤，煎热待冷饮之，可救。如他药不能立功。翁曰：疮乃热症，况上身已热，又天时酷暑，大热之剂其敢进乎？予曰：此阴盛格阳之症，初未尝如此，因服寒凉过剂激之使然尔，翁不看其两足膝下皆冷乎？翁用手探足下果冷，乃欣然听用。用人参、白术各三钱，大附子、炮姜、炙甘草各一钱，水煎冷与之。服后即鼾睡达旦，次早便能食粥半盏，足膝下渐暖，药仍如前。早饭后，予与二三友散步山溪，午刻归来，乃见举家大恸于地，见予至，哭语予曰：不可为矣？本是热病误服热药，今舌肿大，塞满口中，不能言语，死在顷刻，奈何？奈何？予骇然应曰：安得有是不祥语也？今晨诊脉与昨不二，适往返不过二时许，何倏尔有此大变乎？待予再诊决之，及诊六脉渐敛较昨大有神气，面色亦和，独舌胀大。予心知为陈寒凉敷药所致也。乃诘陈曰：我别后可用敷药否？陈点首曰：已二次矣。予抚翁及诸人曰：无恸，立看予为翁消之。急取官桂研末五钱，用生姜自然汁调涂舌上，才涂上但见眼泪双流，鼻中涕出，口内涎垂，舌顿消去。语近侍曰：我无事矣。诸环侍者，男妇不下二十，皆面面相觑，以为神奇。予曰：可即取粥与食，使压之庶虚火不再升。适舌胀满者，乃敷药寒凉，闭其毒气，毒无从出，故作胀耳。桂皮乃辛热之物，又以姜汁调涂，取辛散之义也。诸人皆服其论。", "6114": "东之丈令眷妊已六月，为伤风咳嗽，腹中吊疼，痰壅喉音不清，头且眩晕，脉左滑数，右寸弱，关滑，左尺有力，右尺弱。予以人参、白术、陈皮、贝母、茯苓、桔梗、桑白皮、紫苏、粉草、黄芩、前胡，四帖而病痊愈。", "6115": "吴斗一丈歙溪南人也。八月初旬，自新都往湖州途次偶感风邪，发热多痰，且又腹痛下痢，里急后重。原有肠风下血之疾，又以旧年乃翁痢疾发热卒于湖州，心甚恐怖。予脉之，两关滑大有力，尺寸俱不足，乃以白芍药一半生、一半酒炒，五钱止痛为君，当归活血，酒连、酒芩、柴胡、桔梗清热升提阳气为臣，枳壳、槐花兼治肠风为佐，益元散、木香以实大肠，山楂以消瘀血调肝安脾为裨佐，一帖热减半，痢稍轻，次日仍用前药，外与丹溪保和丸调理，五日而出户。侄孙二水体甚肥胖患温疟", "6116": "族侄云岳，患偏坠脐腹腰俞俱胀而痛，左关脉弦大鼓指。用小茴香、甘草、苍术、益智仁、防风各五分，荔枝核、橘核、糖球子、柴胡各一钱，山栀、青皮各七分，服后其痛如旧，脉且转数，恐作囊痈，急为解毒。栝蒌五钱，当归、甘草节、金银花各一钱，连翘、柴胡、青皮各七分，水煎服之，痛定肿消。因食鸡鱼太早，次日脐腹又作胀痛，发热不能睡。昨日囊消后，弦脉尽退，今复弦矣。改以山楂、栝蒌各二钱，金银花、柴胡、连翘各八分，甘草节、黄连、当归各五分，青皮七分，两帖而愈。", "6117": "一妇，时方妙龄，表虚易感风寒致成鼻渊。流清涕不止，便觉头运，两太阳常作疼，且多喷嚏，脉之两寸洪大，用秦艽、酒芩、桑白皮、马兜铃各八分，白芍一钱，滑石、石膏各二钱，枳壳、蔓荆子各五分，甘草三分，四帖涕止病愈。", "6118": "程两峰丈，偶与乃侄稍有介蒂，其晚饮于侄家，归觉腹中胀满，呕哕不宁，次日眼珠面色皆黄，恶寒发热。时当仲秋，正疟痢为疠之候。医作疟治，五心加热，下午潮热烦躁，似呕不呕，且鼻衄，腹痛，大便黑如墨，吐出黑血如烂猪肺者然约碗余。有谓：所吐之物如此，大便之黑又如彼，似有中蛊之象，心疑乃侄毒之也。正欲与乃侄争辩，予仲子泰来适在渠宅，徐语渠诸郎君日，尊翁症尚可起，顾不为救症，而务与人哄，何舍重而图轻耶!渠家素不急予，仍迓所亲信者率相视之。见目珠如金，面若熏橘，腹大如斗，其中有块大如碟，坚如石，两足下皆浮肿，四肢且冷，小水赤，饮食不思，莫不面面相觑，辞而不药。举家闻言，通宵号泣，惟欲攘臂争哄。仲子泰来又语之曰：家君固不敏，其知识量不出诸公下，昨自华阳归，迓而诊之，当必有说。举家忻然敦予求诊，其脉左涩右滑。予曰：据滑脉主痰饮，涩主有瘀血也，今所吐所下皆瘀之征，断非蛊也。使得早从事，曷有此猜忌此号泣哉。两峰曰：吾生平颇谨疾，瘀自何致？予曰：《内经》云：怒则伤肝，甚则呕血，不呕则积，积而瘀于经隧，满而溢也。两峰曰：若谓从怒而致，则此语恰当吾病源矣，敢请剂。予用当归尾三钱，赤芍药、牡丹皮、川芎各一钱五分，玄胡索、五灵脂、桃仁各一钱，滑石、茜根各二钱，水煎饮之，所下黑物甚多，腹中仍痛，块犹未软。前方再加青皮、山楂、酒蒸大黄服之，大便行三次，黑瘀及痰不计其数。从此腹渐宽，块渐溶，面色稍转，而黄日退，饮食津津有加，四肢微温有生气矣。惟两足浮肿不消，改用六君子汤加炮姜、茜根、滑石、青蒿调理而黑粪全无。一月精神复旧，里中谓予，此役匪得认病投剂为足称，且俾二宅释猜疑，排忿争，其雅谊尤足重也。", "6119": "予有表嫂小产后，腹痛晕厥，冷汗淋淋，遍身麻木，心怔怔动，左脉绝不应指，虚极故也。以当归三钱，川芎一钱五分，人参、荆芥穗灯火烧存性各一钱，益母草、泽兰吐各八分，甘草五分，水煎饮之。腹痛减，惟怔怔不宁。以四君子汤倍加黄耆为君，当归、香附、益母草为臣，川芎为佐，炮姜为使，两剂而安。", "6120": "陈士美，孤子也。年弱冠，由梦遗后患头疼发热，时值仲夏，医治不瘳。凡市中有名者率延致，转治转热，反加水泻口渴，日夜不得眠者旬日，众视为危。时有俞氏者用参耆白术为其敛汗止泻，而汗泻愈剧，呻吟不间昼夜，勺粒不入口，咳嗽胸痞，躁闷不宁，又四日矣。渠亲邵琼林交予，因凂邵逆予为治。诊其脉左弦长，右洪大俱七至，舌苔焦黄，体若火燎，神昏气促。予曰：此仲景伤寒热症也。邪在阳明少阳二经，其危不啻风中烛。胡时师不认症察脉，徒以梦遗受病，率投补剂，无怪乎转治转剧也。幸予至，设迟一日，大事去矣。用石膏五钱，柴胡、知母各三钱，炙甘草、白芍药、枳壳、桔梗、黄芩、天花粉各一钱，粳米一撮，急煎饮之。夜半热稍退，神稍静，脉之仍数甚。继以前剂进，天明乃得睡觉而热退神清，泻止膈宽。惟口尚渴。再用柴胡一钱五分，白芍药、麦门冬、知母各一钱，石膏三钱，甘草、五味子各五分，人参七分，服之舌润渴止，余热尽退，粥饮始入，渐向安矣。次日，忽两足指前一截痛如犬啮不能耐，以野蓼一握入明矾四两，煎汤熏洗，痛势稍缓。又以薏苡仁三钱，木瓜二钱，黄柏、牛膝各一钱，汉防己三分，一帖而愈。后又干咳嗽尽夜不住口，喉且疼，胸胀而体略热，此为误服参术太早之过。用马兜铃、百部、御米壳，各用蜜水制过一钱，五味子、甘草各五分，百合二钱，四帖而愈。", "6121": "程松逸兄，患酒疸，遍身皆黄，尿如柏汁，眼若金装，汁出沾衣如染，胸膈痞满，口不知味，四肢酸软，脉濡而数。以四苓散加厚朴、陈皮、糖球子、麦芽、葛根，倍加青蒿水煎，临服加萱草根自然汁一小酒杯，四帖其黄焕然脱去。", "6122": "太学岐原门下千人，名仲谏者，患跨马痈，大发寒热，红肿疼痛，呕恶不纳饮食。外科医月余，肿痛日加，饮食日减，肌肉日削，精神大惫，不能起止。岐原邀予，脉之六部数而无力，形气殊不胜息。时有专科唐氏为渠调剂将进，予诘何剂？唐曰：真人活命饮也，曾服四剂，今始加大黄。予复诘曰：前此何剂？唐曰：败毒散，黄连解毒汤。予晓之曰：此皆治初起有余之疾，据今症乃气血大不足者，法当大补托而出之，庶保终吉。唐曰：凡痛为实，痒为虚。今痛正盛，脉正数，饮食且不进，大补必加饱闷，饮食何由进？热毒何由出也？予正色语之曰：《素问》云，数脉所主其邪为热，其症为虚。今痛极者，皆由寒凉败毒之剂伤脾胃，凝气血，故饮食减而痛增也。又以败毒之剂进，是鸩之尔安望脓出而全其生乎？唐曰：补剂迨脓溃后或因脓清而后用之，今脓未出，安可谓虚而补之？吾为专门不敢任其责。予顾岐原曰：生死在此一剂，不可不慎。彼谓脓未出无补理，彼排脓内托散，十全大补汤非外科急剂乎？大抵凡病宁使有余后欲剥之，乃为易易，今狼狈若此，再株守成法，剥削后，何以措手？岐原曰：井蛙之见，岂知有天？惟叔命剂。予用黄耆三钱，人参二钱，川芎、当归各一钱，白芷、官桂、甘草、防风各五分，急煎饮之。一帖痛止而精神回，饮食进。再剂而脓溃。十帖肉生能动止矣。唐乃拊膺，啧啧语同列曰：今而后知补剂能出脓而加食也，吾侪外科当永识此以为法则。", "6123": "一妇咳嗽，痰中有红，大便一日五六度，饮食极难下膈，才下膈，腹中即不安，立时欲泻必尽泻出乃止，肌肉消瘦，下午发热，热将发时，四肢先麻，两足膝皆战摇。两寸关脉滑数，两尺沉细，此虚中有实疾痰饮之候也。脉虽数，午后虽发热，不敢轻用寒凉，特为温补下元，庶关门有守，泻可止也。山茱萸、菟丝子、人参、破故纸、杜仲、山药、茯苓、泽泻、桂心、砂仁服下甚安，四剂后下体不战摇矣。但饮食腹中微疼，即欲蹲厕，前方减去山萸加白术、肉果、木香，八帖愈。", "6124": "族侄煌，春温后忽鼻衄寒战，小水不利，舌上焦黄，目珠极红，六脉伏而不见，举室惶惶。予曰：此作汗之兆，由热极使然也。因先时汗未透彻，阳明余热在经迫血上行越出鼻窍，故有此症，以石膏、滑石、生地黄、升麻、赤芍药、牡丹皮、麦门冬、天花粉、甘草，煎而服之，汗出如雨，直至两踝，舌润而苔尽退，衄亦止，目珠色淡，脉乃渐出。改用人参、麦门冬、五味子、白芍药、甘草、知母、黄芩、柴胡、竹叶、石膏，服下。大便原五日未通，今亦始行，精神大转，饮食亦渐进矣。", "6125": "富昨汪氏妇，对河程门女也，年仅三八，经不行者半载，腹大如斗，坚如石，时或作痛。里医尽技以治月余，弗瘳。乃举歙友为翼，又治月余，腹转胀急，小水涓滴不通，乃仿予治孙仲暗法，而用温补下元之剂，则胀急欲裂，自经求尽。文学南瀛怜之，荐予，诊其脉两关洪滑鼓指，按之不下，乃有余之候也，症虽重，机可生。询其致病之源，由乃姑治家严而过俭，其母极事姑息，常令女童袖熟鸡、牛舌之类私授之。因䌹食冷物，积而渐成鼓胀。前任事者并不察病源，不审脉候，误作气虚中满治之，因胀而欲裂，宜其然也。乃用积块丸，三下之而胀消积去，后以丹溪保和丸调养一月而愈。积块丸列赤水玄珠第五卷虫蛊后。", "6126": "族侄孙仲登，因与堂兄构讼城中方归，时值二月末旬，醉后房事二，起而小溲随即脐下作痛，水泻肠鸣一日十数度，发热头痛。里医进理中汤，一帖反而呕逆，烦躁口渴。敦予诊之，左脉弦大，右洪大，俱七至，饮食不能下咽，昼夜不得睡，面赤唇燥，舌上黄苔深厚。诊毕语予曰：我房失后阴症伤寒也，小腹痛且漏底，幸叔祖救之。予笑而应曰：以子所言决为阴症，以予指下辨之当是春温阳症也。且外症亦阳，乌得为有房事而遽以理中进之乎？族中相知者交为予言，渠病的属阴症，故呕吐水泻，不可因其面赤便认为阳，顾戴阳症与此近似，幸加察之。吾辈正拟于理中汤内再加大附子、肉桂，庶可保全。予极言：不可。仲景有云，桂枝下咽，阳盛则毙，况附子理中者乎。阴阳寒热之间，辨之不真，生死反掌耳。兹当舍症而从脉也，以温胆汤加姜汁炒黄连，柴胡、干葛，与二帖，嘱令当夜饮尽，俾明日不它传也。予别后，渠一服而呕逆止，余症悉在。诘朝予诊，竟扣渠曰：夜来二药必未服完，不然何两手之脉洪大搏指如是？佥曰：因有竹茹、黄连，恐非房失后所宜，故仅服一。予曰：不服黄连，致热转剧，今日非石膏不能已。乃与白虎汤加竹茹两剂，临别嘱渠曰：今症非昨日可比，用石膏者岂得已哉!设当用不用，使经中之热传入于腑，非大黄不能瘳，切勿失时误事。讵知别后又有惑之者，仍只服一帖，泻即随止，余小腹之痛具在。次日予诊毕语渠曰：昨临行时嘱之再三，何乃又不服完？今脉洪长坚硬，邪已入腑奈何？奈何？对曰：众谓石膏大寒，恐小腹加痛，实只服一帖而已。予曰：惧服石膏，今且服大黄矣。皆失时误事之过。周金人铭云：荧荧不灭，炎炎奈何，其斯之谓欤。思非桃仁承气汤不可。乃觌面煎服，连饮二剂，下极黑燥粪五六枚，痛热俱减。再为诊之，六脉皆缓弱，迨是病方尽去，改以四君子汤加白芍药、黄连、香附，调养数日而愈。", "6127": "汪希明，竹山丈长君也。年弱冠，性多躁，素有痰火，旧曾吐红。张医用收涩之剂太早，以致痰与瘀血留滞经络，酿成病根，恬不知觉，且为灸肺俞、膏肓，撼动前疾。止涩无功，滋阴作壅，咳不能睡。又误作风邪而投发散风剂，不思火盛得风，其势愈炽，血从口鼻喷出，势如泉涌。延予为治，六部洪数，身热而烦，又时当三伏，内外之火夹攻，纵体质刚劲，宁能堪此销铄哉。予思非釜底抽薪之法难夺其上涌之势，乃以三制大黄三钱，石膏五钱，黄连、茜根、滑石各二钱，牡丹皮一钱，急煎饮之，大便微行二次，血来少缓。即用石膏、滑石、冬青子各三钱、旱莲草、茜根各二钱，黄连、山栀、贝母各一钱，甘草五分，茅草根五钱煎服，血乃全止。三日后大便结燥，火又上逆，咳咳连声，左关脉弦劲，右关洪滑，与当归龙荟丸下之，而咳始缓。改以栝蒌仁、茜根各一钱五分，贝母、旱莲草、麦门冬、知母各一钱，白芍药二钱，黄连、黄芩各七分，青皮、甘草各三分，仍加茅根。后每遇大便燥结即进龙荟丸，迹此调理三月大定，半载全瘳。书云：病有六不炙，火盛者不炙。此由误炙，几于不保，故特识之以为好炙者龟鉴。", "6128": "德兴文学祝弘吾公，祝令君叔祖也。在休衙，偶有阴阳之患，子午潮热，咳嗽痰多，汗流不止，胸膈不畅，大便燥结，动作喘乏口渴。以贝母、知母、栝蒌仁、桑白皮各一钱，枳壳、黄连、麦门冬各八分，桔梗、柴胡、前胡各五分，甘草三分，五味子十一粒服下，五更微汗，热退十之七，惟痰嗽喘乏，改用栝蒌仁二钱，余如前，外以七制化痰丸夜服热尽退。渠甚喜，以为自是以往，可勿药矣。予曰：未也，据脉弦数不减，恐防作疟，公未为然。予适东行半月，书报疟作，咳嗽转加，所出皆黄黏老痰。予曰：书云无痰不作疟。仍用前方倍加柴胡、贝母为君，加乌梅一个，四剂霍然良已。公曰：翁之视疾，应若桴鼓。古云：智者不治已病治未病。吾于翁言征之，乃以是备言祝令公。祝令公喜曰：孙君匪独得岐黄正脉，其雅谊足称，叔祖尚未前闻，予当赋诗以赠。于是欣然手书若干律以授予，其诗附后第六卷。", "6129": "汪链兄内人，经水久不止，内有紫黑血块。今则胃脘胸腹皆痛，玉户且肿，手足皆冷，绝不知饿，脐腹之下有一块坚如铁。脉左数，右沉涩，此血瘕症也。用糖球子五钱，玄胡索、五灵脂、香附、麦芽、青皮各一钱，水煎服。夜即痛减其半，手足渐温，后加丹参、川芎、蒲黄、益母草、当归，四帖而痛全止，玉户亦消。再四帖而经调。", "6130": "程相如丈令政，孕四月，头疼遍身皆痛，腰痛更甚，恶寒发热，咳嗽口渴，六脉浮数。以小柴胡汤加防风、羌活、葛根，姜、枣煎服。夜忽大发寒战，继而发热，五更又发战。告急于予，予曰：此作汗之兆。俄而汗出，口渴头痛，身热皆减。惟胸膈胀闷，此胎气上逼而为子悬，以大紫苏饮与之。紫苏、人参、白术、茯苓、甘草、当归、陈皮、大腹皮、川芎、白芍药，服后身冷而汗出不止，胸腹胀痛，急以夺命丹进服下，嗒然而睡。觉则痛止胀消，始能进食，身温汗止，骎骎向安。夺命丹用白术、茯苓、牡丹皮、桃仁、白芍药、桂枝，醋水煎服，止痛如神。", "6131": "余文台，壮年咳嗽吐红，腹中常痛，夜多口渴梦遗，背心作胀，两手脉短弱，两关弦大。左尺弱，右尺滑大。心血不足，中焦有痰积，膈间有瘀血，阴分有淫火。乃先为清肃上焦，用山栀仁、牡丹皮、丹参、茯苓、甘草、贝母、橘红、益元散，服十帖，背胀渐消。惟咳不止，改用黄芩、杏仁、半夏曲、益元散、黄连、栝蒌仁、甘草，十帖而嗽止。惟腹疼不除，再以遇仙丹同丹溪保和丸进之，大便下稠积痰甚多。后以人参、白茯苓、白芍药、紫菀、知母、麦门冬、甘草、当归、五味子调理而愈。", "6132": "金氏妇，苏双泉之亲妈也。旧秋患崩中，愈后方百日，时值上巳，因洗浴受风邪，外寒而束内热，前后心胀，四肢肿痛，面有浮气，恶寒发热，呵欠不时，大小便欲行不行，口内常甜，六脉浮大而数。以柴胡、紫苏、麻黄、桔梗、枳壳、大腹皮、厚朴、酒芩、姜黄服下，夜得微汗，胸腹稍安，四肢仍胀，再加萝卜子进之，觉烦躁且醋心。改用二陈汤加香附、大腹皮、桑白皮、姜连、枳壳、山栀子各八分，益元散二钱，薏苡仁三钱，吴茱萸三分，服下，四肢消半，面气全消。觉腰痛，嗳气，胸膈嘈辣，用六君子汤加薏苡仁、姜连、厚朴、知母、泽泻、郁金、砂仁、枳实，调养半月，四肢悉平，嘈杂寻愈。", "6133": "文学张云门三令郎，丁年偶发寒热，右胁有一块降起，疼痛，手不可近，下午至夜尤甚，额颅手心皆热，脉右关洪滑，两尺尤有力，日夜不得睡。乃仿推气散例，姜黄、桔梗、川芎各一钱五分，枳实二钱，白芍药一钱，粉草五分，姜、枣煎服，外以当归龙荟丸。其夜大便行一次，颇得睡。三更后，先发寒战，徐热，至五更微汗，而胁痛寒热悉减。再诊之，左脉略弦，舌有黄白厚苔，两胁重按微疼，大便燥结不行，以小柴胡汤减半夏，倍加栝蒌、鳖甲、牡蛎、胁疼全瘳，睪丸略硬痛，彼自以为无后恙矣。予语渠姐夫徐仲子伟曰：「病先起胁下，顾胁下为肝之经，后及睪丸硬疼，其睪丸亦肝之地，此余热未尽彻故也。而彼已厌药，以小愈为全安，不出浃旬，必有奇疾。」徐仲之曰：「奇者若何？」余曰：「此君性急好胜，若勉强作文，遇劳而发，憎寒壮热，非疟即囊痈也。予倘东行，子宜识之。」别后半月，果因作文，夜发寒热，囊渐肿大，其热如火。及予至，诊之六部皆数，两尺且近于洪，知其脓已成，必溃而后已。彼心甚恐，予曰：「无伤，易与耳。」急以营卫返魂汤加金银花为君，两帖而脓溃。再加人参，又两帖而肌生，十日痊愈。方用何首乌、赤芍药、当归、小茴香、甘草节、木通、金银花、贝母、枳壳、白芷，水与酒共煎服之。此方加独活治流注尤神。", "6134": "朱眷内眷，孕已八月，因送殡受惊，胸膈胀闷，呕逆不入食。城中时师，认为外感，为之发散，呕恶愈剧。举家恐胎有动，延予诊视。两寸脉皆洪滑，两尺弱，此亢上不下之候，胸膈胀者，盖由子悬而然，此一剂可瘳也。夫曰：「胎妇难任峻剂，觑其呕恶之状，胀闷之势，时刻不秪，一剂曷愈？」予曰：「请试之。」与温胆汤加姜汁炒黄连、大腹皮，水煎成送下姜汁益元丸，果一帖而呕止膈宽，即能进食，午后酣寝，怡然若未始有病者。其夫讶曰：「温胆汤何神若此，幸详其义。」予曰：「胎孕之症，重在足少阳，足少阳者，胆也。病起于惊，气逆痰随，胎气上逼，故脉亢上不下，在《难经》为溢候，由木火之性上而不下。经曰：上部有脉，下部无脉，其人当吐，不吐者死。予故用一剂可愈也。方名温胆者，此温字非温暖之温，乃温存之温。黄连、竹茹清其肝胆之火，同白茯苓而安心神，益元丸压其痰火下行，火下行而胎因之亦安矣。」筠皋公曰：「先生认症真，故投剂确，非神乎？药神乎用也。」", "6135": "胡邻泉令媛及笄后，患吐血，每吐碗余，下午倦怠，夜分潮热，呕吐不食，大便秘结，时师视为阴虚火动，投以滋阴之剂，反加饱闷，背心胀痛。予诊其脉，两寸洪大，两尺弱，知其有瘀血凝滞，以致新血不得归经，故满而溢也。法当消瘀为主，用白芍药、枳壳、前胡、益元散、桃仁、红花、牡丹皮、山栀子、贝母、水煎，临服入萝卜汁一小酒杯。服后呕吐如旧，大便仍秘，乃以龙荟丸通之，更以石膏三钱，橘红、半夏曲、姜连、茜根、竹茹、黄连、枳壳各一钱，白茯苓八分，甘草三分，服后大便行三次，吐止食进。后用二陈汤加滑石、丹参、丹皮、茜根、白芍药、香附。二十剂后，经行热退背胀悉愈。从此经调血不上逆。", "6136": "族侄孙君实，壮年，患遍身筋骨疼痛，肢节肿痛。其痛极，状如虎啮，大小便起止，非三五人不能扶，诸痛处热如火燎，食饮不入，呻吟床褥已经二候。有以疏风之剂投者，不应，又以乳香、没药活血止痛之剂投者，亦不应。延予诊治，六脉浮紧而数，予曰：此周痹也。势甚恶，俗名白虎历节风，乃湿热所致。丹溪云：肿属湿，痛属火，火性速，故痛暴猛若此。以生地黄、红花、酒芩、酒连、酒柏、秦艽、防风、羌活、独活、海桐皮、威灵仙、甘草，四剂而痛减大半，再加赤芍药、当归、苍耳子、薏苡仁，减去独活、秦艽，又八剂痊愈。", "6137": "叶子黑内人患疫，医为其汗，为其下，罄技不能起，尸寝者已浃旬。家事窭乏，亦不能复迎医。邻人睹其状，以生死在须臾间，群然发善愿，科敛助其殡敛之需。予闻，为之诊，六部俱微弱不充指，右关稍滑，精神昏惫，仅一息奄奄，四肢冷厥，口渴。予诊毕，语诸邻曰：「据症甚危，据脉邪已尽退，惟虚惫而神气弱，非大补不能也。诸君苟能以助殡者，助其市人参，庶几可起死而还之生也。诸君既怜其死，宁不以冀其生乎？予非毫有希觊，顾渠力不足瞻，愿与诸君共圆满好生善果耳。」诸邻固有善心，激于余言，益忻然相语曰：「惟先生命。」即以六君子汤，加归、芍补气血而化痰涎，以麦门冬、五味子复脉通心而生津液，以桂枝温其四体，午刻进药，晡刻四肢渐暖，精神涣发，尚无力开声，改以生脉汤加远志、归、芍、苡仁、山药，调理而愈。诸邻人大快。", "6138": "孙如亭令政，年过四十，眼偶赤肿，两太阳疼痛，大便不行者三日。平时汛期一月仅二日，令行四日犹且未止。里有开化余云谷者，自谓眼科捷手，医治逾候，肿赤不消而右眼内眦突生一白泡，垂与鼻齐，大二寸余，余见而骇走，以为奇疾，莫能措剂。又见其呕吐眩晕，伏于枕上，略不敢动，稍动则眩愈极，吐愈急，疑其变而不治。予为诊之，两寸关脉俱滑大有力，两尺沉微。予曰：此中焦有痰，肝胆有火，必为怒气所触而然。《内经》云：诸风掉眩皆属肝木，诸逆冲上皆属于火。盖无痰不作晕也。眼眦白泡乃火性急速，怒气加之，气乘于络，上而不下，故直胀出眼外也。古壮士一怒而目眦裂，与白泡胀出眦外理同。肝为血海，故血亦来不止。治当抑其肝木，清镇痰火，则诸症自瘳。先用姜汁益元丸压其痰火，以止其吐，再以二陈汤加酒连、酒芩、天麻、滑石、吴茱萸、竹茹、枳实，煎饮。一帖吐止晕定，头稍能动。改用二陈汤加芩、连、谷精草、香附、夏枯草、吴茱萸、薏苡仁两剂，赤肿消，白泡敛。四剂痊愈，血海亦净，从是后不发。", "6139": "吴勉斋，年近五十，有腹痛疾，或作或止，性极急，多躁多怒。今痛在当脐，不间昼夜，市里医者为下之已五日，大便虽泻，痛则尤甚，饮食不进，手足清冷，形神俱倦，脉仅四至，重按则伏而有力。此由攻克太过，寒凉伤脾，脾虚则中气不运，积反凝滞，以故大便虽泻而积不行，痛终不减也。治当建立中气为主，中气一回，痛当立止，先与王海藏五神丸一钱，滚水送下，以止其痛。此丸补接元气，安和五脏，升降阴阳，极有神应，故名五神丸。方出《医垒元戎》第十卷中。再用小建中汤调肝养脾。盖脐下乃肝经部位，唯此汤乃对症剂也。白芍酒炒三钱，炙甘草一钱五分，桂心一钱，加香附一钱，生姜三片，水煎服。午牌进药，未牌已报痛止，因其夜进粥太频，且食鸭汁，憾动余积，腹又作痛，且加胀闷，面有浮气，里急后重，与四平丸而渐定，外以二陈汤加香附、砂仁、苍术、厚朴、山楂，腹中始觉宽快，三日无恙。又纵恣口腹，大啖肥甘，糕、粽、肉、鸡之类，不饱不止，腹中大痛时刻难存，欲吐则食已下膈，欲泻则食尚未入肠，自喊叫云，可取木香槟榔丸、大承气汤急与我下之，虽死无憾。予谕之曰：据痛虽甚，腹则不坚，顾今日适届冬节，礼曰先旺于至日，闭关安静，以养微阳，曷敢以大寒峻剂，而汨天和乎？设不和已只须桕树东行根上白皮一钱，长流水煎饮之，一服可愈也。夜已二鼓，觅而煎服，天明泻三五行，痛减大半，仍以小建中汤和之，痛又旋减，唯脐下尚不脱然，常常以热手重熨之，大便欲行，及至厕，则又不解。知其血少而气不调，用熟地三钱，白芍一钱，杏仁二钱，乌药一钱，木香五分，水煎饮既，下黑粪甚多，十年腹痛沉疴从此不再复萌。此后勉斋常语人曰：吾得孙公五神丸、桕根皮、小建中汤三法，不啻脱胎换骨，数年来岂惟饮食增加，即步履轻便，捷若少壮，皆孙君赐也。亲友有求其三法者，畀而服之，捷若桴鼓，彼家谓予殆三生夙缘云。", "6140": "黄颐斋内子，产未弥月，醉犯房事，血来如崩，势不可遏，发热头晕，大小便俱热，六脉洪大。以竹茹、蒲黄、白芍药各一钱，香附、茯苓、侧柏叶、青蒿各七分，甘草、炮姜、艾叶各三分。血止大半，腰犹胀痛，下午胸膈饱闷，改以川芎五分，当归、茯苓、破故纸、蒲黄、香附各八分，姜炭、甘草各一分，陈皮七分，人参一钱，服此血全止，腰痛亦愈。", "6141": "程心章兄，颊腮红肿，呕恶，发热，不能进食，下午烦躁，口苦，夜不能睡，六脉洪大，此俗名鸬鹚瘟是也。乃少阳阳明二经之症，法当清解，以柴胡、贯众各二钱，干葛、竹茹、半夏曲各一钱，黄连、枳壳各七分，甘草四分，一帖而瘳其半，再服肿消，食进而安睡矣。", "6142": "上舍近洲，予族中至厚侄孙也，性拓落，豪放不羁。夏仲，在苕与诸友泛舟游于碧浪之间，兴至即百觥不辞，亦以是终为酒困也。呕恶，体热，胸胁胀闷，腹中疼痛，大便秘结，饮食大减。苕之名医如杨调元者，桥梓悉方，治之已三月，或愈或否，延至深秋，肌瘦神瘁，日进米仅二合，胸胁胀，腹中痛，漠然略无所减，懑然而不可支，两足皆有浮气，归谋于予。左脉沉弦而数，右关结实大如碧豆，因诘其在苕所服之剂。答曰：彼谓侄孙禀薄肌脆，宜当理脾，向服多理脾之剂。予曰：否。子所苦者，胸胁胀闷，腹中疼痛，大便燥结，其累大矣。理脾曷可以去此哉？适足以益病耳。经曰：塞者通之，又曰：通则不痛，其治此病之谓欤。乃取当归龙荟丸，三下之，大便行五六度，又与酒连、酒芩、青蒿、姜黄、槟榔、青皮、半夏、葛根饮之，豁然焦膈通达，呼吸开利，惟头略晕，足上浮未去，前方再加滑石、茯苓、薏苡仁、山楂与调中丸兼服，半月痊愈。近洲喜曰：人皆谓我症似中满，今不满者叔公力也，敢不德欤。予警之曰：吾闻君子之于身也，兢兢焉不敢轻父母之遗体，无伐天和，则疾疢不作；无反天常，则灾害不逢，蘧伯玉尝言，行年五十而知四十九年之非，况新愈后，尤当痛惩，庶保遐年，区区无足恃也。别未五年，予在宜兴闻讣，果以伤酒而卒。噫惜哉。", "6143": "甲午仲秋下旬，黄源金先生以中馈病急，谒予于市，貌甚惨，步立栗然，语其症，怔怔言涩于吻，不胜其忧。执族医尺一白予云：病自仲夏吐血二碗余，初以芩、连、栀、、柏、生地、芍药大寒之剂投之，一帖而止，未几则咳嗽彻昼夜。后师谓咳自吐血后，当以滋阴降火之治。逾两月，尽其法而罔效，反加喘促，泄泻，辰巳二时发热，烦躁，师告技穷，谓喘咳乃火刑肺金，泄泻乃脾胃已惫。保脾则火愈炽而喘咳增加；滋阴则泄泻绵绵而元气下脱。经书所记，嗽而下泄上喘者死，此症之谓也。似无可奈何矣，语竟泪潸潸下。予观其忡忡之状，心不觉惕然动也。市去渠宅五里许，即步去一视，观其面青，喘从抬肩撷项，息息连身而倒，胁背俱疼，日夜不得伏枕，脉之左涩右寸关滑大，诊毕，顾金兄犹泪盈眦，予抚其背曰：毋泪，尚可生也。适徐仲子同视，诘予曰：症若此，夫子曰可生何也？予曰：是非汝所知也，第观予治，俟奏功当语汝。遂以紫菀、茜根、牡丹皮、桃仁、益元散、桑白皮、茯苓、桔梗、栝蒌仁、桂枝、白前水煎，临服加韭菜汁半酒杯。服后背胁痛止，泻减半，乃得睡，但咳而声哑不除。次以杏仁、桔梗、紫菀、甘草、白前、五味子、栝蒌、干姜、款冬花、半夏曲、通草水煎服，服后声渐开，泻全止，惟嗽尚多。再以半夏曲、桔梗、茯苓、陈皮、甘草、杏仁、桑白皮、白前、苡仁、白芍、牡丹皮水煎。后以丹溪治咳吐方，用泻白散加青皮、人参、白茯苓、五味子，调理痊愈。次年诞一子。是役也，徐仲子之功居多，盖金为徐仲子友也。徐仲子治疾多奇中，乃笃信予而推毂之，初投剂，人多置议，仲子独赞之曰：其必有见也，人人辟易，彼许可生，安得不望生哉？故金任之不二。功成，余明甫、查仲修问予曰：病起于吐红，发热、烦躁、喘咳皆是火邪，前后之师滋阴降火，药法亦未爽，然而病转增剧，其故何也？予答曰：医不难于用药而难于认病。余明甫、查仲修曰：市人议先生治疾多不循方，每每师心。金之役，人皆视为火症而用寒凉，先生独用温药，虽成功，小人窃为先生恐。予曰：病原于火，其势之剧，以治之太峻致然。夫血之初来，势如涌泉，安能一吐遂尽？必有余血伏于经络，思不及此，而以大寒之剂一帖而止，夫大寒之剂岂能止血，适以凝其血耳。血凝经络，滞于气道，气滞血凝，日甚一日。气滞又复生痰，痰与瘀血两滞经络，则肺气不利，故咳嗽声哑。不加察而为消瘀化痰，导血归经，又以滋阴苦寒之剂施之，则痰瘀愈凝而气道愈不利也，久则胃寒脾弱，反增泄泻，昼夜喘促不能卧矣。书云：上热未除中寒复生，而为阴盛格阳之症，故咳而呕吐，予故始以桂枝、干姜之类温其胃，以桃仁、韭汁、丹皮、茜根之类活其血而消其瘀，故喘止而泻除。东垣曰：脾胃喜温而恶寒，信不欺也。古谓药不贵执方，而贵合宜，方即兵家之阵图，匠氏之规矩也。图可授人，而不能授人斗；匠可授人规矩，而不能授人巧。此岳武穆对宗留守云，运用之妙存乎一心也。予游方之外，亦不失方之内，惟不失方，窃谓知方。知方合法，岂区区能哉？观古人治虚怯之疾，即不治之症，亦能延之三五载。乃今治虚怯者，不半载而竟殒逝，犹驾言曰：殆今之天元运气使然，故人多不寿，愚谓天元运气，则人人皆如是乎？何予母八十有六，予父逾八望九，予伯母今九十有五，予表伯汪春元东台之父年九十余，强健不啻少壮。不思速夭之由，皆为滋阴降火之误，而反归咎于天，天何尤哉？缘滋阴降火之法起于丹溪，继而王节斋、何大英之流倡而和之，以成其风，此当今之大弊而人未之警也。我师祖汪石山先生揭而指之，惜乎未有继其言者，一齐众楚，故滋阴之祸，流而迨今，敝以继敝，无已时也，二三子其识之，徐仲子其闻之乎？仲修又问：先生何以认是症为中寒而非阴虚之火，而又认其喘为瘀血也。予曰：脉与症皆可考。《脉经》云：涩为气滞，气滞且血凝。盛吐之后，大寒之药一帖而止，其未尽之余血为寒凉所凝，滞于气道为喘。书云，从前来者为本，从后来者为标。兹用活血消瘀之剂治其本，以温热暖胃之剂治其标，故泻止而喘定也。若夫阴虚火动之脉，乃细数之候，今脉滑大，非阴虚之脉，阴虚喘嗽之症，潮热于夜，两颊皆红，今热在辰已阳分，而面色带青，由是以知其非阴虚之火，乃误用寒凉激其火而上行也。经曰：水流湿，火就燥，中气既寒，火愈不能下矣，正如雨骤雷烈则电光之火愈炽，日出而电光自息也。且阴虚火动，火起九泉，皆自足下涌泉穴起以渐上升，今膝下冷而上身热，两尺脉又弱，盖由咳而气升。经曰：形寒饮冷则伤肺。肺气为寒药壅遏不得下降，故咳而吐酸。《丹溪纂要》云：阴气在下，阳气在上。喘咳呕吐，泻白散加人参、茯苓、五味子、青皮。故不从河间，而用诸呕吐酸皆属于火之治，况今岁次甲午，为湿土司运，八月建酉，水土衰败之时。《内经》曰：毋违时，毋代化。且脾恶湿，湿多则泻，湿则生痰。前后之师不考运气月令，一概而用滋阴降火之剂，助湿生痰，安望其痰之愈也。《丹溪纂要》云：实脾土，燥脾湿，是治痰之本也。遵而用之，如鼓应桴，予故曰：医不难于用药而难于认病，有以也。", "6144": "族侄合溪，年当八旬，春初偶为寒袭，发热咳嗽。医与芎苏散，即汗出不止，呃呃连声，勺粒不入，昏愦经旬，汗日加，呃日甚，延予诊之。六部浮大无力，重按三五不调，六七至一止，右关近滑。诊毕，语嗣君敬所曰：尊翁由劳倦表虚感邪，脉故浮大无力，法当从东垣补中益气汤，一二剂可瘳也。医乃妄为表散，致汗漏、神疲、昏愦、发呃，高年值此，宁不殆乎？即可侥幸图安，亦不过千日养耳。敬所勃然俯而对曰：上已后为家君寿期，不虞构疾。羸惫若此，苟保百日，俾菽水之心，庶几少尽，叔祖之赐多矣。若千日，又出于望外也。予即以六君子汤，加竹茹、柿蒂以止呃，再加酸枣仁、石斛以敛汗，一进热退呃定，再进汗止食入，三进霈霈然，精神长矣。乃减去竹茹、柿蒂，加当归，半月全安。先是祝令君谓渠有耆德，请为介宾，以疾辞不及赴。迨季春，令君闻渠寿，即援例赐一级宠以冠带扁额，用彰恩典光于乡闾。后果三年而卒。", "6145": "孝廉方叔度令嫂江氏，年甫三旬，患胀满，诸名家或补、或消、或分利、或温、或寒，悉为整理一番，束手而去，举家惶惶无所适从。叔度曰：闻孙仲暗昔患此，众亦束手，比得孙生生者，治而起之，众皆敛衽钦服。仲暗伯仲适在馆中，盍咨访之，即发书，介予随绍向往。诊得左脉弦大，右滑大。予曰：此李东垣木香化滞汤症也，病从忧思而起，合如法按治，可保终吉。叔度喜曰：曩从事诸公悉云不治，先生谓可保终吉，此故仓公有言，拙者疑殆，良工取焉是也。幸先生早为措剂。予即照本方发四帖。服讫，腹果宽其半，继以人参消痞汤、琥珀调中丸调理二月全瘳。叔度信予从此始，每推毂予于诸相知，多有奇中，卒为通家之好。", "6146": "临溪吴天威丈，年七十有三，客邸远归，偶坠马跌伤，左胁作痛，随治而愈。后半年，忽左胯肿痛，憎寒作热，动止极艰，里中诸公有认湿痰者，有认风气者，有认湿热者，总罔效。闻歙外科洪氏能，且识杂病，迓以为治，居数日，视为疝气，率投荔枝核、大小茴香、川楝子、橘核之类，痛躁不可当，乃欲引绳自绝。诸子百般慰解，洪乃辞去，竟不知为何疾也。其婿汪开之，予之表弟也。邀予诊之，六脉浮而洪数，左寸尤甚，验其痛处，红肿光浮如瓠，抚之烙手。予曰：此便痈也，洪系外科专门，胡独忽此？盖渠素慎重，见患者年高，乌敢认为便痈治哉!此殆千虑一失，毋足怪。诸郎君闻予言皆骇然，诘予曰：家严不御色者十载，顾安得此，愿先生再思。予曰：此非近色而得，审胯属足厥阴肝经，肝为血海，乃昔时坠马，恶血消之未尽，瘀蓄经络，无门可出，化而为脓，由年高气虚，又被香燥克伐太过，不能溃而即出，故散漫浮肿。观其色，青中隐黑，浓已成腐，必须外用镵针，引而出之，内用千金托里，庶可排脓生肉。但予生平心慈，不能用针。予弟警吾，外科良手，可延而决之。至，即以镵针深入寸余，出青黑脓五六碗许，臭秽难近，即语诸郎君曰：使早决三日，可免一月之苦，今即日大补之，非百日不能痊，此俗名石米疮也。诸郎君及患者见脓色如是，始信予言不爽，急以请剂。予乃用内托十宣散，参、耆每帖三钱，后加至五钱，一日两进，两越月，脓尽肉满而愈。一市称奇。", "6147": "文贵者，善为族文学，岐原出入子母者也，寓长兴邸中，病发热，昼夜不止，口渴，齿燥，鼻干，舌苔黄厚，不得眠。服药不效。予适至雉城，岐原邀诊之。脉俱洪数，呕恶，胸膈痞懑，小水短而赤，大便下皆清水。予以石膏七钱、知母五钱，甘草一钱，软柴胡五钱，葛根三钱，黄芩二钱，枳壳、竹茹、桔梗各一钱，连进三帖，呕恶止，胸膈宽，热仍未退，无汗，泻未止也。时有问予者，谓胡不用柴苓汤而退热止泻也。服石膏故益泻耳。予戏之曰：予乃三脚猫耶，能认此为何症用柴苓汤也？仍以柴胡、石膏各七钱为君，葛根、知母各五钱为臣，黄芩、甘草各一钱为佐，生姜五片，速进二帖，汗则津津然出，热退泻止，口不渴而眠矣。予因他往，留药三帖而嘱之曰：胃气初回，势必思食，宜谨慎不可多进，若多则余热复作，必成食复，治将费手也。慎之!慎之!后五日，果以食不慎而复病。予又至，热较前为重，且加懊𢙐，夜谵语如见鬼状，口大渴，齿燥，舌焦黑有芒刺，势甚危急，以前方加枳实、栀了各三钱，淡豆豉二钱煎饮之，二帖懊𢙐止，余症犹然，夜更甚，前方减去豆豉，加黄连、麦冬、生地、白芍，一日二帖，舌以井水生姜擦去黑苔，用蜜调玄明粉涂之而胎去矣。服三日，始得微汗，诸症尽减，再四叮咛慎饮食，调理半月而全。岐原问曰：人始皆认此症为漏底伤寒，谓叔不用柴苓汤退热止泻，而用石膏为非，乃竟以石膏收功，何也？予曰：此问甚善。盖医贵认症，此症乃少阳、阳明合病也，柴胡、白虎汤、葛根为二经对症之药，服之可解肌热，止口渴。若柴苓汤为太阳、少阳合病之剂，内有五苓散，乃太阳经之里药，症非太阳，曷敢用之？且其内有人参、白术、肉桂，皆助热发燥之味，误投则必发斑。其齿燥舌干而焦黑，又何敢用茯苓、泽泻、猪苓利之，使益亡其津液耶？古人谓：以伤寒为大病，不察症而误投，则生死立见。《伤寒论》有言，不得汗，不得下，不得利小便，是谓三禁。故曰：少阳、阳明不从标本，从乎中治。小柴胡、白虎汤中治剂也。人徒见其大便作泻为漏底，不察泻皆清水无糟粕者，为热极所致，症乃春温时疫也。但为发散，使清气上升而微有汗，泻当自止。此泻岂五苓散所能止哉？止则误事。岐原曰：夜重如见鬼者，何以故？予曰：热入血室故也。岐原曰：男子亦有血室乎？予曰：血室男妇同之，冲任二脉为血之海，二脉附于阳明，今病乃阳明之热，遗入血海也。故加生地、白芍而效。余治伤寒，用柴葛解肌汤及柴胡白虎汤而热不解者，加此二味，则热无不退，汗无不出矣。且下午与夜又阴分主事，欲解血海之热，必投此二味以收其功，此亦予一得之愚也。岐原曰：善。愿记之，以诏后来。", "6148": "钟泽有程梦奎孺人者，年将五十，仅一子，念一岁而殁于痘。旦夕哭之，哀且弥月，揽镜自鉴曰：何子死而形色不瘁。如此因持铁如意捶其胸，绝粒断浆，肌容日瘁。时为初秋，寒热交作，呕哕，懊𢙐，遍身疼。夫为遍延诊视，却药不饮，诸医百荚开譬，拒而不听，媳与孙，跽而恳，姻族就而谕其不纳者，若罔闻也。惟合睫以待死。已而作色语其夫曰：病若此，汝曷不延名医一决生死乎？夫曰：所延皆名士。病者曰：昔常闻程方塘参军，患疯三年而起者谁？曰：孙君。又问：吴西源孺人病燥，揭痰喘三年，与程道吾内眷劳瘵晕厥，谁为起之？夫答如前。病者曰：何不请孙君决我生死？夫闻言，物色征予，五日而后至，则薄暮矣。病者犹疑为诞也。私至三家访予状，皆曰魁然长髯者也。诘朝觌面诊之毕，则问曰：何日死？予应曰：病势危，去死不远。病者喟然叹曰：死不足惜，第九华山香愿未了为恨耳。予曰：孺人大愿不思，何须以此小愿为孜孜也？孺人曰：无大愿。予曰：人之修短有数，今年之痘死者，不可胜计，令嗣之死亦数也。然有二孙可承宗祧，孺人能忍哀抚孙，使其成立，娶妇以蕃后胤，令嗣虽死犹不死也，而孺人亦有令名。若不此之思，忧伤以殒，夫君必娶，娶必少年，继室生子，则必厚其子而薄孺人之孙，晚娘晚爷之谣，独不闻之耶？孺人万金之家，使令孙不得其所，令嗣九泉之下，恐不能无憾，孺人忧死何益也？愿孰大于此者？予故谓未之思耳。孺人试思之，谁轻谁重，当自辨也。语毕，怃然曰：先生言至此，吾如寐者得醒矣。顾病势去死不远，何能得如吾愿？予曰：所谓近者，病也，非脉也。脉左弦细右关滑，故发热，体痛，呕哕，乃秋来疟症，非死脉也。若如前，执拗不服药，不进饮食，书谓绝谷者亡，殆非虚语，孺人诚听予言，以二孙为念，以大体为重。予以活血养血之剂而治其伤损，以小柴胡加竹茹、滑石，以和阴阳而止其呕哕，不一月而可无恙矣。奚忧哉？果从予言，而进饮食服药。五日寒热呕哕皆止。后以丹参、刘寄奴各三钱为臣，五加皮五钱为君，香附一钱为佐，入四物煎服。果一月而全可矣。程孺人病起，而闻者皆曰：七发起太子之病，观于孙君益信。", "6149": "歙潜口汪召南令郎，年十四，患蛊胀大如覆箕。经医三十余人，见症皆骇而走，独市之幼科汪养直者，调理数数见效。第此子溺于豢养，纵口腹，不守戒忌，病多反复。一日语召南曰：郎君之症，非求之孙生生者不能成功。召南曰：闻此公多游吴浙缙绅间，何可以月日致也？养直曰：归矣!吾有妹适罗田，为方与石丘嫂也，旧岁患症如蛊，治经弥岁无功，生生子立全之。吾推毂孙君者，岂有他肠，为郎君也。召南即凂罗田延予。予至，日已晡矣。观病者，腹胀大极，青筋缕缕如蚯蚓大，上自胸脯，至上脘而止，惟喜其不下现也。脐平，四肢面目皆浮大，两足胻骨上各裂开，大出清水，一日间数为更衣易被，阴囊光肿如泡，淫淫渗湿，发寒热，脉以手肿不能取，必推开其肿下指，重按浮而六至。予曰：症可谓重之极矣。仅可恃者，目瞳子有神耳，余皆险恶，将何以治？养直知予至，亟过相陪，宣言曰：病重不必言，引领先生久矣。幸为投剂，生死无憾。予曰：且先为理表，若表彻稍得微汗，使肺气少利，则小水可通。召南喜而亟请药。乃用紫苏叶、苏子、陈皮、麻黄各一钱，桑白皮八分，防风、杏仁各七分，炙甘草、桂枝各二分，生姜三片，水煎服之。五更乃有微汗，次早面上气稍消，胸脯青筋皆退，余症虽仍旧，机栝则可生矣。仍投前药，次日腹与四肢皆有皱纹，惟小水未利。乃改用破故纸、苍术、赤茯苓、泽泻、桑白皮、赤小豆、桂心、木香，二帖而小水利，骎骎已有生意，乃以饮食过度，大便作泻，又以四君子汤加苡仁、破故纸、泽泻、山楂、砂仁调理而全安。此症予阅历者不下数十，然青筋未有如此之粗。足时出水有之，未有出水处如鲇鱼口之大，而取效亦未有如此之速。盖此子体未破而真全，故症虽重而收功速也。数十人间有五六不能成功者，由其纵欲恣情，不守禁忌，非药之罪也，召南昆仲见人谈医，则以不佞为称首。予笑曰：君得无到处逢人说项斯者耶，乃汪养直亦医道中白眉，乃不收功于后，病者不忌口过耳，于养直何尤？养直不矜己之功，亦不忮人之功，所谓忠厚长者非耶？", "6150": "岩镇郑景南丈，病卧年余，百治不效。昔体丰腴，今瘦骨立，饮食少进，新都名士皆辞不治。其家闻昔年方士荣孺人蛊症，时师亦皆辞去，予为起之，因征余治。时则六月望也。诊其脉，左弦大，右关滑大，两尺俱无，恶心，腹瘦削状如仰瓦，肠鸣如雷，昼夜不住，小水不利，肌肤及眼珠色若黄金，腹中有块如碟，动跳不止，足膝以下皆冷，饮食不入。予详思其病机，昔肥而今瘦者，痰也。形虽瘦，而目炯炯有神，先以五饮汤姑试之，以观其势，再为加减。因用族复花八分，破故纸一钱，肉桂三分，白术、茯苓、泽泻、陈皮、半夏各八分，生姜三片，水煎服之。二帖，恶心肠鸣皆止。次早饮食稍进，举家欣欣色喜。令岳程钟山公，于予为石交，闻病有起意，心殊异之，不知为予，因而过访。见予，抚掌大叫称快，曰：吾固知是公也。指其甥而语之：此即所尝与尔曹言者，闻久为西吴缙绅递留，不意今归，城吾婿之幸也。相与谈对，两日而别。别之时，景南饮食稍加，小水利，肌肤面目黄气退，渐有生机。不虞逾半月，为拂意事所激而怒，复吐痰，不思饮食，家人惊惶无措，亟请予诊，两寸滑大，左关弦劲搏指，右关亦滑大有力，两尺沉微，予语之曰：病甚重，脉非前比，且不敢以万全许，第尽吾心尔。病以药力而回，君之福也。时为七月之朔，予因留视七日，日进一剂，剂以人参、陈皮、半夏、茯苓、香附、白豆仁、黄连、旋覆花、麦芽、甘草与服。服三日，恶心止，大便有稠痰下，其中间有瘀血，此皆大怒所致。故经云：怒则伤肝，甚则呕血。并下泄上吐，亦或有红点子在痰中吐出，是其征也。后改用六君子汤，加麦芽、黄连、枇杷叶、白扁豆调理，病势骎骎向安，腹中如碟之块亦渐消去，大仅如指耳。肌肉亦生，能下榻举足以步。市上之人称奇。", "6151": "孙文学子元，素多疮疥，近因沐浴，鼻涕出红，面足浮肿汗多。左脉大而有力，右寸亦大。据脉，多思而气不畅。以葛根、大腹皮、厚朴、赤茯苓、青蒿、泽泻、白术、郁金、升麻、木通、滑石、黄芩水煎饮之。浮肿渐消，惟鼻红尚在，口且渴，改用当归、白芍药、知母、甘草、石斛、麦门冬、五味子、山栀子、玄参调理而愈。", "6152": "一妇因夫荒于酒色，不事生计，多忧多郁，左跨疼痛，且及于膝。小水频数，大便频，并脐腹胀痛，口干。脉之，左手数，右手弱。近又发热恶寒，汗因痛出时刻不宁，此食积，痰饮、瘀血流于下部，足厥阳之经挟郁火而痛，恐成肠痈。与神效栝蒌散一帖。半夜后，痛即减半，汗也寻止。次日诊之，数脉稍退，小腹坚如石，按之且痛。再与前药，其夜环跳穴亦作痛，直至于膝，小腹稍软，小便仍痛，大便也未通利。仍与前药，每帖用大栝蒌二枚，加牡丹皮、莪术、五灵脂、金银花服下。大便利而热退痛止，小水亦长，诸症悉平。", "6153": "族侄孙君锡，头痛，胸背胀，饮食下膈便吐，咳嗽不住口，痰浊如脓，大便结燥。脉之，独右寸洪大。以二陈汤加竹茹、滑石、石膏、酒连、麦冬，连进四剂，夜与益元丸兼服，而嗽吐俱止。惟痰浊如脓色，且腥气触人，此将欲作肺痈，改用牡丹皮、麦门冬、山栀子、甘草、贝母、枳壳、桑白皮、紫菀、知母、当归、生地黄、桔梗四帖，全安。", "6154": "侄孙尔嘉内人，三孕而三小产，六脉滑数。乃气虚血热也。由其热故多滑下，因其血频下，心甚恐怖，终日偃卧，略不敢起身，稍起，血即大下。与生地、白芍药、白术、地榆、桑寄生、续断、甘草、升麻、椿根白皮、黄柏、条芩服之，而血三日不来，惟白带绵绵下。过五日后，因有不得已事，起身稍劳，血又大下。予谓：血滑已久，如水行旧路，若不涩之，必不能止。又思：血海甚热，亦肝风所致，防风子芩丸正与病对，宜制与之。又制白芍药六两，侧柏叶、条芩各三两，防风、椿根白皮各二两，蜜丸服之。从此血止胎安，足月而产一子。此后连产三子，并无胎漏之患。后遇胎漏，递用此法，莫不良已。附告同志，以便取用。", "6155": "梓林兄令眷，右手痛风，小水频迫，起身稍迟，即出不禁，足有浮气。年过六十，右寸关脉濡弱，左手和。此脾虚停湿之症。近且咳嗽，用六君子汤加苍术、石菖蒲、远志、大附子、晚蚕砂，倍加薏苡仁，缓治而平。", "6156": "一妇，经不行者三月，大便泻，腹胀嘈杂，吐酸水，时下白带，常恶心，自以为有孕。予脉之，候非有孕，乃脾经有湿热，心经有瘀血症也。与二陈汤加白术泽泻、猪苓、酒连、木通、吴茱萸、滑石、麦芽、山楂。泻止腹宽，经行腰腹作痛。以川芎三钱，当归五钱，香附、丹参、桃仁各一钱，水煎服之。经虽行，口中吐出黑血水甚多，且亦有如脓者，改用四物汤加牡丹皮、丹参、桃仁、红花、山栀、滑石，调理两月而痊。", "6157": "侄妇程氏，下午喉痛，近来痰多晕厥，一日二三发，头痛面赤，素未生育。左脉弦大，右寸关滑大有力。以荆芥、薄荷、甘草、桔梗、玄参、僵蚕、柴胡、枳壳、竹茹、贝母，水煎饮之，连进二帖，其夜得睡。惟背胀、怔仲、痰犹不清、面多热，用黄芩、枳壳、甘草、桑白皮、地骨皮、天花粉、玄参、前胡、半夏曲、橘红、山栀仁，调养而平。", "6158": "汪嗃兄，时疫热病，被发汗过度，热留胸中，烦躁不止，呕恶不安，汗竟不敛，口且渴。脉之，独两关洪大。此阳明之热尚在，当以白虎生脉汤为主，石膏五钱，知母三钱，人参、白芍药、甘草、石斛各一钱，麦门冬二钱，五味子十五粒。急煎饮之而热退。继以益元丸服之，而吐亦安。", "6159": "族侄元素，春温头痛发热，左脉弦大，右洪大，以小柴胡合白虎汤二帖而愈。乃为食复发斑，色紫，神昏，人事不省，身重不能转动。即水、火皆不自知，合目鼾睡，形如醉人。面赤发热，舌苔外黄内黑，皆有芒刺。三日后，予至脉之，六部俱浮洪以三黄石膏汤加枳实、鳖甲进之，稍得微汗，大便始有真粪。次日才开目言语，乃进粥一盏，改以小柴胡汤加山栀、枳实、鳖甲、白芍药调理而愈。", "6160": "仆子孙安，空晨出门，途次食面三碗，饥劳感疫，因内伤，表里皆热。及至绩溪衙中，昏闷谵语，头痛，身疼，腹痛。医不察为劳倦感疫，遽以遇仙丹下之，大便泄三四十行，邪因陷下，而为挟热下利之候。急归视之。舌沉香色，额痛，口干燥渴，烦闷，昏昏愦愦。脉左弦数，右洪数，但不克指，知为误下坏症。以柴胡、石膏各三钱，白芍药、黄芩、竹茹、葛根各一钱，天花粉、甘草各五分，山栀子、枳实各七分，葱白五茎，水煎服之。后半夜吐蛔一条，乃稍得睡。次早大便犹泻二次，呕吐酸水，腹乃痛。改用小柴胡加滑石、竹茹。夜热甚，与丝瓜汁一碗，饮既神顿清爽。少顷药力过时，烦热如前，再以丝瓜汁一大碗进之，即大发战。予谓此战非寒战，乃作汗之征耳。不移时，汗果出而热犹然。忆《活人书》云：再三汗下，热不退，以人参白虎汤加苍术一钱如神。迹此，再加玄参、升麻、柴胡、白芍药、黄连饮后，身上之斑，先发者紫，后发者红。中夜后乃得睡而热散，斑寻退去。腹中微疼，肠鸣口渴，右脉尚滑，左脉已和，再与竹叶石膏汤加白芍药、苍术，服后睡安，腹仍微痛。用柴胡、芍药各一钱，人参、酒芩、陈皮、半夏各六分，甘草三分，乌梅一枚，服此腹痛渐减，精神骎骎长矣。惟两跨痛不能转动，此大病后汗多而筋失养之故，宜当补益。人参、黄耆、白芍药、桑寄生、枸杞子、薏苡仁、桂心、牛膝、熟地黄，水煎服。后加木瓜、黄柏、当归，减去桂心，调养而痊。", "6161": "侄君孝，后谿兄次子也。三月患头项痛，腰脊强，遍身如被杖，脐腹也痛，口渴不寐，饮食不进，六脉浮数。吴医以为阴虚，为滋阴降火三投而三剧，反加呕恶。又与疏通，热尤不退，下午烦乱。延方和宇丈视之，以为外感拟进人参败毒散。吴争之，谓阴虚体弱，难再汗，仍用四物汤加柴胡、葛根、薄荷、黄芩、知母，而热如焚，神且昏冒矣。予时远出，促归诊之，六脉浮弦而数鼓指。语之曰：此春温症也。方诊良是。因复加内伤，以故病剧。滋阴之剂壅而作滞，且引邪入于阴分，宜乎热加而躁闷也。法当清解兼消可愈无伤，以二陈汤加羌活、柴胡、防风、麦芽、山楂，服下得微汗，热退其半。惟下午作潮，大便未行，腰脐之痛不止。用小柴胡汤加葛根、白芍药、青皮、黄连、山楂饮下，热又少退，大便已行，腰脐之痛也随减去。但不知饿，再以柴胡、甘草、青皮、枳实、麦芽、知母、黄芩、白芍药，诸症悉平。惟觉体倦乏力，加人参、白扁豆、薏苡仁，减去柴胡、青皮，调养而痊。", "6162": "族侄妇范氏，大参晞老女也。素有痰涎，胸腹痞胀。近因乳肿，大发寒热，欲成痈毒。以加味神效栝蒌散二帖，寒热虽退而肿不消，用贝母、白芷为臣，栝蒌为君，赤芍药、当归、连翘为佐，青皮、甘草、柴胡为使，痛虽减而肿仍不消。脉之近数，知已成脓，仍与内托十宣散加金银花、蒲公英两帖而脓溃。因脚上生疮而有浮气，前方去蒲公英、金银花，加薏苡仁、苍耳子，调理全安。", "6163": "孙竹野浙归，途次受暑，又为酒面所伤，因而作吐，胸膈痞闷。时师以消导之剂，燥动脾火，口渴，嘈杂，躁乱不宁，目珠如金，一身尽黄，已成疸症。诊独右寸脉洪大有力，先以温胆汤，倍加香薷、滑石、葛根解暑止□为君，黄连、麦门冬清热止渴为臣，使湿热散而黄自瘳也。连与三帖，吐止食进，黄也定矣。再与五苓散加青蒿、葛根、滑石、黄连、枳实八剂而黄释然。", "6164": "程菊泉，暑月患喘嗽，咳咳连声，浓痰滚滚，行动则喘促不宁。夜分口渴，胸膈胀闷，两寸脉滑而数，两关弦。此肺有宿痰、胆有郁火。内经云：火郁发之。又云：风寒外来者可发。用紫苏子、半夏曲、杏仁各一钱，石膏二钱，款冬花、桑白皮各八分，桔梗、枳壳各五分，麻黄三分，服下无进退。改以杏仁、陈皮、人参、贝母、款冬花、麦门冬各七分，薏苡仁一钱五分，桔梗、知母各五分，五味子十一粒，桑白皮一钱，陈皮六分，服下痰减大半，胸膈仍不舒，口仍干，脚仍热。前方减去款冬花、五味子，加枳壳、葶苈子两帖全安。", "6165": "程应祯兄，胸膈背心时常胀疼，头眩晕，脚软弱，手指痛，咳吐红痰。诊其脉，左关弦大，右寸关滑大。予谓此食饱后感于怒，老痰瘀血积在上焦，宜其胸背胀痛而热壅也，治当清化上焦，使新痰不生。宿瘀磨去，则万全矣。如落时套，用地黄、山茱萸等滋阴降火之剂，是以滞益滞，则热无由去，瘀无由消，而痰益增不去也。病者闻言，谔然曰：未见公时，业已服过一月久矣。疑其饮食损而热寻加，胸背胀痛递长哉。予曰：今反辙幸早耳，再迟则败事。亟以青皮、枳壳、陈皮快其气而疏其壅滞。盖痰随气行也。贝母、桑白皮以消余痰而清其嗽；牡丹皮、滑石、桃仁，消其瘀血，山栀仁开郁清热；白芍药伐肝补脾；甘草调和诸性，缓而理之，当见其去泰去甚也。别后半月复书报云：胸背之胀减三之二，血已十日止矣，痰如旧。改以山栀仁、牡丹皮、丹参、赤芍药、桃仁各八分，滑石三钱，五灵脂、当归尾各一钱，半夏曲、青皮各六分，诸症悉去，独足心热，再以黄柏、知母、苡仁、牛膝、甘草、白芍药、茯苓、陈皮、贝母、石斛、牡丹皮调之如初。", "6166": "虚山内人，胸胁胀痛，五更嘈杂，每一嘈杂则痛发更甚，左寸关脉洪滑，右关亦然，此肝胆有郁火，胃中有胶痰，乃有余之疾。内经云：木郁则达之。盖木火之性贵乎疏通，当以龙荟丸条而达之。顾痛则不通，通之则不痛也。服龙荟丸一钱五分，大便行一次，痛随殄迹。惟声不开，以陈皮、柴胡、贝母、茯苓、甘草、白芍药、酒芩、香附、杏仁、桔梗调之而安。", "6167": "一妇，当暑月小便不利而痛，玉户肿，且又便血，发热，左脉弦数，右寸短弱，此肺气不足，肝火太炽。盖肝为血海，肝又主小便，玉户为肝经所络之地，治当疏决肝经壅塞，俾气畅则新血得以归经，热解则小水可不痛，而肿亦可消矣。以滑石三钱，桃仁、当归、白芍药各一钱，柴胡、黄连、人参各八分，川芎六分，甘草、桂皮、白芷各三分，四剂而病如失。", "6168": "族弟妇戴氏，腹中痛多在脐腹，白带如注，四肢酸疼，大便里急后重，已成赤白痢矣。脉之，两寸关俱滑数，尺也数。以白芍药、当归、黄连、黄芩、木香、槟榔、桂皮、甘草、滑石、桃仁、桔梗，一剂而红止。惟小水短涩，下午发热，大便一日夜仍四行。改用白芍药、当归、白术、陈皮、滑石、甘草、茯苓、厚朴、酒连、酒芩、桔梗、柴胡、木香饮下，诸症悉愈。惟头痛腰疼，再以桂心、当归、白芍药、白术、茯苓、甘草、酒芩、酒连、破故纸、木通、黄柏煎服，全安。", "6169": "予弟淑南，额痛遍身痛，口干，舌苔黄厚，左脉浮大，六部俱数。时当仲秋初旬，以小柴胡合白虎汤加羌活，热仍不退。下午用六神通解散，以葱汤调服三钱，热稍退，至半夜后又复热，额痛，顶巅尤甚，舌根黄且焦黑，小水赤痛，烦躁不睡，遍身又痛，此三阳合病，暑症也。次日，以小柴胡大加石膏为君，藁本、白芷、竹叶、粳米、生姜、大枣。少顷，大汗出至足，热始尽退，犹烦躁不睡，仍以小柴胡汤加桂枝、山栀子、竹茹、竹叶饮下，烦躁宁而得睡，余热悉平，精神爽而向安矣。", "6170": "孙文约孺人，年八十有三，胃脘疼痛，手不可近，腹中饥而饮食不能下，两寸关脉滑大，两尺沉弱，此血虚气滞症也。先予积气丸，一服而痛减半，再用生白芍药、山栀子、五灵脂各一钱，酒炒白芍药二钱，粉草、山楂、香附各八分，一帖全安。", "6171": "应章族弟，三阴疟发于子、午、卯、酉、日，四越月矣。每发于夜，热多寒少，左脉微弦，右关滑大，以二陈汤加柴胡、黄柏、川芎、当归、黄连两帖，而热稍轻，饮食不进，四肢懒倦，脾气大虚。白术、何首乌各三钱，鳖甲二钱，青皮七分，乌梅一个，一帖而截。", "6172": "太学程好吾，倜傥博洽士也。季春患两太阳痛，胸胁稍疼，口渴，大便水泻，左脉浮弦而数，中按有力，右关滑大。予曰：春温症也。柴胡、前胡、葛根、粉草、青皮、黄芩、知母、桔梗、半夏曲、石膏，半夜后得微汗。因起大便，感风续又发热，依然口渴，更觉烦躁。石膏三钱，知母、柴胡各二钱，葛根，黄芩各一钱，粉草、桔梗各五分，竹叶二十片，两进而汗出热解，诸症悉平。四肢尚倦，口微干，语言乏力，以生麦汤加薏苡仁、石斛、甘草、白芍药、黄芩调养如初。", "6173": "令媳长卿之妇，腹中微疼，经行不流利，喉痛，四肢麻木作战，不知饥饿。右脉洪大如豌豆，以川芎、香附、麦芽、山楂、乌梅、粉草、桔梗、酒芩、防风、荆芥、白术、茯苓四剂而安。次月经水大行，十日不止，以黄耆、阿胶、蒲黄各一钱，白芍药二钱，粉草三分，一帖而止。此后但觉浊气下坠，屁从子户中出，以补中益气汤，加酒炒黄连调养而平。", "6174": "族子应章之弟，十月发三阴疟，至次年仲春未止。每发于辰戌、丑未日，午后寒多热少，夜有盗汗，左脉软弱，右关尽弦数有力。用白芍药、当归各一钱，白术二钱，柴胡、川芎、粉草、砂仁、桂枝、酒芩各三分，生姜三片，水煎服，再以何首乌、白术、鳖甲各三钱，柴胡一钱，青皮、酒芩、甘草各五分，乌梅一个，生姜三片，水煎，临发日五更服之，两帖而止。后半月，下身大生疮疖，以东坡四神丹调理而痊。", "6175": "油沄吴中岳孺人，先感风邪，后伤饮食，发热头疼，腹中作胀。医与巴豆丸泻之而热不减；后医又以大黄重泻之，而热也如初；再后医谓泻而热不退者为虚，大用参、耆、白术补之，补经四日，神气昏沉，不知人事。乃敦予诊，左脉弦数，右关尺沉数有力，舌尖沉香色，舌根焦黑芒刺，语言含舌不清，扣前服药，始知妄下妄补，不思饥谨之余，疫气为厉，误成坏症，危而且殆。姑以知母、柴胡各三钱，石膏六钱，枳实、天花粉各五分，粉草、黄芩、麦冬各一钱，山栀子、生地黄各七分，人参六分，竹叶三十片，生姜三片，水煎饮之。中夜后人事稍清，微有汗，舌稍柔和，语言已不含舌，骎骎然有生气矣。次日，前方减去地黄，加白芍药，舌心焦黑退尽，诸症十减其七。但大便五日未行，遍身尚痛，咳嗽，与七制化痰丸两帖，再以石膏二钱，麦冬、贝母各一钱，前胡、枳实、黄芩、栀子各六分，甘草三分，桑白皮八分煎服而安。", "6176": "元素侄令政，春温后经水适止，余热不退，口中甚渴，胸胁痛而耳重，脉左弦数，右滑大而数。小柴胡加石膏、知母、桔梗、枳壳、葛根、栝蒌、半夏曲服下，而热渴如旧。改用柴胡二钱，人参、甘草、天花粉、黄芩各七分，白芍药、红花、当归、牡丹皮、知母各八分，调理而瘳。", "6177": "朱氏子天送，时疾头疼，身若燔炭，口渴气促，申酉刻热潮更甚，舌心焦黑，遍体紫斑，语言含舌不清，时多发呃，耳聋。先治者误进藿香正气散而加呕逆水泻；又医以柴苓汤，呕益甚，热转增剧。迎予为诊，六脉俱洪数，此少阳阳明合病之疫，以石膏五钱，知母、柴胡各三钱，黄芩一钱五分，半夏曲、麦门冬、竹茹、橘红、葛根各一钱，粉草、枳实各五分，服下热退其七，舌不燥矣。再以柴胡、半夏曲、白芍药、竹茹各一钱，石膏三钱，麦门冬、知母各一钱五分，黄连、甘草、人参各五分，水煎饮之而斑退，诸症悉平。", "6178": "桂亭兄，壮年原有湿热、痰积。年遇艾偶坠轿，跌伤背胁。专科以草药敷贴于外，内以药酒攻之而愈。越十五年，左胁痛，手不可近，左脉弦数坚劲搏指，小腹也痛，知为旧瘀及痰积作祟。以青皮、赤芍药、黄连、当归尾各一钱，桃仁一钱五分，大黄二钱，滑石三钱，水煎，临服调玄明粉一钱。服下吐出痰涎碗余，大便仅行一次，而左胯及腿膝皆痛，夜睡不安，由小腹痛甚之故。此瘀物欲行而未能也。再与大黄、当归尾、红花、牡丹皮、赤芍药各一钱，桃仁二钱，滑石三钱，青皮八分，调玄明粉一钱，再下之。大便行三次，皆沉香色稠黏瘀物。腹痛虽除，胯痛仍在，用乳香、没药、归尾、红花各一钱，桃仁、滑石各三钱，大黄二钱，穿山甲、丹参各一钱五分。服后大便行四次，所下皆紫黑如筋膜者不可胜计，诸病悉减。因食鸡汤、牛肉，脐腹又痛。里急后重，此余积未尽。欲再下之，举家惊怖，谓六旬以外之年，以下数次，恐脾弱不能再下。予曰：医贵认病，何以年齿数下拘哉？今药力到而积已动矣，破竹之势可迎刃而解，若失时姑息，恐他日滋蔓，欲下难动也。行后而补，庶无反顾之忧。大兄然之。以红花、桃仁、当归尾、赤芍药、山栀仁、玄胡索、牡丹皮、穿山甲、滑石，煎调玄明粉，下二次紫黑瘀物。如前之半，腿胯小腹痛则俱释。次日用人参、茯苓、白芍药、粉草、陈皮、山楂、桂心、当归、半夏调养半月，精神、步履、饮啖一如旧矣。", "6179": "堂弟东里内子，咳嗽吐红，发热头眩，脚膝乏力，先已服滋阴降火十数剂不愈。饮食渐少，精神渐羸，恳予治之。两寸脉累累如贯珠，两尺俱软弱，此上盛下虚之候。上盛者，痰与瘀血也；下虚者，肾阴弱也。且生平好饮，不无助热，法当先清上焦，化去瘀血宿痰，然后以养阴药收功，则病根可刈，痨瘵可免也。用贝母、枳壳、桑白皮清肺化痰，滑石、桃仁、牡丹皮、小蓟消除瘀血，山栀子、甘草、白芍药养血以祛余热。三帖后，红渐稀少，前后心始不胀痛。惟痰嗽不止，大便结燥，减去滑石、桃仁、加栝蒌、黄芩、紫菀调养而平。", "6180": "由溪程竹坡孺人，年过六十，为疫所染，头痛口渴，舌苔前黄燥，后紫黑，身热沉重，人事昏愦，语言错乱，小水短涩，呕逆烦躁，合目不开，谚语不辄口，耳聋，胸胁痛。时五月初旬也。迎予为诊。左浮而弦数，右洪长而数。诊毕，仲君清夷问曰：何症？予曰：此热病类也。清夷曰：因体热便名热病乎？予曰：否。仲景谓春温过时为热病，矧兹又为热厉也。邪在阳明少阳二经。又问曰：可生乎？予曰：脉症对可生也。此症远迩染延甚伙，不足怪。清夷曰：适方和宇也云少阳阳明二经之病，二公所见既同，乞商确一方为幸。予与和宇诊多符合，即以柴胡、石膏为君，知母、麦冬、天花粉、竹茹为臣，黄连为佐，甘草、枳壳、桔梗为使，连进两帖。丑刻微汗，热退神清不虞，即进荤粥，下午又复大热，谵语昏沉，举家惊怖。予曰：此食复也。即以小柴胡汤加山栀子、枳实、淡豆豉、鳖甲四剂，复得汗，热从散去，神顿清爽，仍口渴烦躁。以生脉汤加黄连、香薷、竹茹、竹叶而安。", "6181": "程家内眷，藏溪汪氏女也。乃夫殁于疫疠，新寡七日，疫即及之。大热头疼，口渴，胸胁并痛。医与小柴胡汤，夜忽梦夫交泄而觉，冷汗淫淫，四肢如解，略不能动，神昏谵语，面如土色，舌若焦煤、强硬。迓予诊之，六脉沉弦而数，大小便俱秘，此亦阴阳易类也。疫后有是，危已极矣。予以生脉汤加柴胡、黄芩、桂枝、甘草，水煎成，将乃夫昔穿旧裤裆烧灰调下两剂而神醒，体温，汗敛，舌始柔和，焦也渐退。次日，仍以前方加酸枣仁、竹茹，四肢始能运动，乃饮粥汤。仅一子甫十岁，一女甫十四，继被疫困，均以六神通解散汗之而安。妯娌及婢辈六人皆六神通解散瘳之。举家德予，以为再造。", "6182": "族侄太学从明，夏初由客邸患滞下，调半痊而归，因食隔宿猪首而复，里急后重，昼夜三四十度，日渐沉困，口渴，胸膈焦辣，手必热，腹微痛，小水少。每解时先干哕，呕恶，汗出飞飞，下皆稠黏紫黑血，无粪。彼素知医，且慎重，不轻服人药。敦予诊之，脉左沉弦，右滑数，面色外黑内黄，饮食不入，肛门辣痛。予以渠原禀薄弱，今远归，途次不能无劳，不敢疏下。姑以胃风汤加黄连，与二帖不效，腹稍加胀。渠叮予曰：古云无积不成痢，顾积势胶固，切勿用补，无以体素弱为疑。予曰：诺!改用黄芩芍药汤三剂无进退。乃私语渠侄元亮曰：令伯之症，实实虚虚，热热寒寒，实不易治，且谷食噤口不入，干哕可虑，须得明哲参治。元亮从容言之，欲得方古墩为翼，诸相契及内眷递相赞言。太学不从。曰：吾岂不重命而吝费哉？顾新都之医，无如叔最明，吾之交无如叔最厚，舍叔安所倚？元亮曰，叔祖善矣，能用人之长，得一隽商榷，可无后虑。太学拂然曰：知莫过于知心，吾知其心久矣，专任勿疑也。予知渠信任坚若金石，益加研究，图欲先开胃口，使新谷食净宿秽压出，或补或攻，视缓急以为方略。乃背嘱元亮曰：令伯非人参不可，幸且勿露，俾予得以尽技。元亮曰：诺。乃仿朱丹溪法，用人参、黄连各二钱，煎浓，细细呷之，但得一呷下咽，胃口便开，哕恶便止。盖胃口虚热冲上为哕也。其日用之，哕恶即止大半。连与两日，觉胸腹胀，即以保和丸应之。觉小水不利，又以清六丸应之。里急后重以，参术加芩、连、木香、槟榔、滑石、桃仁应之。人参皆背加，太学不知也。渠每诊必叮予曰：日来疾稍平，叔之力也。幸忽遽补，恐废前功。予曰：如教。讵知人参已服过十日，计二两许矣。此后脉仅四至，软而无力。忆丹溪云：虚回而痢自止。又云：气虚甚者，非附子不能行参耆。乃以胃风汤加黄耆、附子、姜炭四剂而血全无，后重也止，惟大便泻而不实，所下俱黄粪。渠知积滞己尽，始欲理脾，用参苓白术散服十日，便仍不实。乃问予曰：补脾而泻不止奈何？予曰：据脉乃下元虚寒，殆肾泄非脾泄也，温补下元则固矣。盖肾者胃之关，初不敢用下剂者，虑有今日也。教以菟丝子、破故纸、杜仲、山茱萸、人参、大附子、白茯苓、泽泻，四帖全瘳。里中称太学能知人，而予不负所任也。", "6183": "查少川公，年四十三，夙有哮喘疾，每发则遍身如燎，气贲贲上腾，息息短促，候中痰声响若汤沸。经七昼夜，汗而渐平。居常嗜饮，通宵不辍，醉后纵欲，不避风寒。族中有教以石膏、麻黄、杏仁、枳壳、细茶各一两，作大剂饮之，名曰五虎汤，喘至即以此御之，随饮而止，屡发屡进，应若桴鼓。公喜甚，持为保命丹。寓大通一月，邑中麻黄、石膏为之缺市。讵知情欲无穷，胃中冲和有限，三年之间，饮五虎者殆不可以数计，而胃中之冲和者，亦不知损之何若也。因而腹大若复箕，两腿光肿如柱，内外臁、疥疮中清水涓涓流之不竭，昼夜腥气逼人，不能伏枕而卧者五越月。自仪（征）杨（州）医起，问京口（镇江）之医如何如何，张者最良，遍延治之弥月，卒无一验。又舍京口抵姑苏，历嘉杭，凡有名者，悉迎疗之，而势益剧，舁回至岩镇，镇医擅名者吴与方也。先诣吴，吴骇辞不治；就方，方诊视久之曰：公疾非常，必得非常人乃可已。公曰：先生世家大方，昔在两淮且人人引领，愿得先生一诊为快，何我弃而使需非常人也？今世非常人舍先生其谁？方曰：嘻，公贵邑孙生生者，名动三吴，今归不出，亟迎治之，或可无恙。公扣孙生生居何里，状何若，方书予姓氏里居与之。归即恳程公山氏绍介迓予，时长至后一日也。至则见公坐高椅之上，气高而喘，身热而烦，复以绵被，足纳火箱，前后左右，环火五盆，首戴绒帽，帽外笼以貂套，套外仍束一帕，鼻用绒套笼之。门设重幔，犹凛凛怯寒。诊其脉浮大无力，睇其色，白中隐青。徐问公曰：恶寒身热从何时起？公曰：十日。予曰：据色据脉，予已得其概矣，公历数府名家，认为何症，拟何汤剂，请详述之。公曰：众论落落不一，先生学博见真，愿惟命。予曰：公疾乃气虚中满，法当温补下元。人徒知利小水，不知小水不利者由下焦之气不充，不能渗从膀胱故道而行，若利之急，则汛滥而横流肌肤，下于阴囊，甚则胀裂，崩塌而出，若使下焦壮盛，则小水自通。譬之甑炊釜底，水火交旺，甑中之气自然蒸腾，若雾若露。《内经》曰：上焦开发，宣五谷味，熏身充肤、泽毛，若雾露之灌溉，是谓气。故曰上焦如雾也。清阳升则浊阴降，降下则为小水，故曰下焦如渎也。渎者，水也。言下焦为决水之官，水道出焉者是也。人之汗即此雾露之气，小水即降下之气。盖气者水之母，由气化而为水，故又曰气化则能出矣。融众理而观之，总由下焦元气壮盛，斯能升降变化，清阳升，浊阴降，即地天交之泰。阳不升，阴不降，即天地不交之否。痞者，塞也。此胀满之所由生也。公之疾起于五虎汤，致脏寒生满病也。公曰：善。吾乃今始知致病之源。第近来身热、手热、膈内焦辣，而外恶寒竟不解，孰为热、孰为寒也？予曰：仲景云伤寒必恶寒，由寒邪在表而然，合先散之。胸膈焦辣者，乃阴盛格阳，虚阳之火被寒气驱逼上行，非真热也。经云水流湿、火就燥，但得下元一温，热自下行。公曰：然，惟先生命剂。予以紫苏、马蹄莘、炙甘草、防风、白豆仁、苍术、陈皮、人参、羌活、生姜，一帖而得微汗。悉彻去环列之火，仅存足底一盆，首上所覆之帕也去。独鼻寒如初，乃用防风、黄耆二两煎汤置器中，令熏其鼻，饮顷而止，一日凡三熏，次日鼻套也除。呕恶不止，用人参温胆汤加丁香进之，一帖而止。又谓鲤鱼能利水，一日尽二斤半。夜胀极，乃告急于予。予曰：病势如是，固乃纵恣若此，等闭之剂曷能消释？沉思久之，以平胃散一两，入橄榄肉一两，水煎饮之，两剂而定。独腹胀，小水不利，不能伏枕为苦。乃以附子理中汤加砂仁、补骨脂、赤小豆、桂心，连进四帖，小水略长。继以尊重丸日三服之，每服五丸，五日后小水通利，可贴席而睡。守此调理，腹胀渐消，两月大平，三月而公出市。市中人信予实从公始。", "6184": "夏益吾，肢节肿痛，手足弯痛肿尤甚，不能动止。凡肿处皆红热。先起于左手右足，五日后又传于左足右手，此行痹症也。且喘咳气涌不能睡，左脉浮数、中按弦，右滑数，乃湿热风痰壅遏经络而然。以茅山苍术、姜黄、苡仁、威灵仙、秦艽、知母、桑白皮、黄柏、酒芩、麻黄水煎，服下而右手肿消痛减。夜服七制化痰丸而嗽止。乃得睡。再剂两足弯消其半。左手经渠列缺穴边肿痛殊甚，用苡仁、苍术、秦艽、甘草、天花粉、五加皮、石斛、前胡、枳壳、威灵仙、当归，旋服旋愈。", "6185": "初阳侄令政，先时咳嗽，诸治无功。且嗽急则吐，用碧玉散二钱，白汤调下立止。后半年复咳嗽，胸背隐隐疼痛，身常内热，咳出桃花脓不可胜计，腥秽之气甚恶。右胁并乳胀痛，脉洪数，大便燥、肌瘦骨立，此肺痈症也。用贝母、茜根、白芍药各一钱，知母、麦门冬、山栀子、紫菀各八分，桑白皮、当归、牡丹皮、杏仁各七分，薏苡仁一钱五分，甘草、葶苈子各五分，水煎服之，服止甚安，但要常服。若一缺药，其疾便发。据此，肺窍中痰积、瘀血尚多，未能即去，宜缓图之。书云俟脓去尽当自愈也。予谓丹溪虽有此言，也不可固执，设不以药消化之，必俟其脓自尽，恐岁月深而有他变。且中年之人何能当此？莫若清热润肺，消痰化瘀，久而服之，或早愈也。方、黄、吴诸公谓久咳伤肺，每每投补，屡被紊之。每补必增热，加痛，加咳，而脓转多。余晓之曰：诸公之意诚良，其如病加何是？姑息之谓也。古人不务姑息，惟以去病为安。夫姑息可以养病，非所以去病也。独汪无怀，然余言，守余法，二年良愈。肌长如初。", "6186": "族侄仲木内人，贤淑妇也。不育多郁，腹胀，左胁不能侧卧，也不能仰卧，仰侧卧即气涌。每午夜背心作胀，气喘，吐痰，发热，必起坐令人揩摩久之始定。面有浮气，右寸关脉滑大有力，此气郁食积痰饮症也。盖忧思伤脾，思则脾气结，气结不行，则五谷之津液皆凝聚为痰，故喘急作胀。先与定喘汤二帖，而无进退。继用核桃肉五钱，杏仁三钱，人参、桑白皮各七分，水煎服之，气喘乃定。惟腹中胀急，改用橘红、半夏曲、木香、白豆仁、郁金、萝卜子、姜连、香附、茯苓四剂，大便痰积随下，腹胀尽消而愈。", "6187": "侄婿陈东山，仲夏患休息痢，所下皆紫血，腹痛，迨清明犹不愈。医药备尝，体倦肌瘦，或三五日一发，或七八日一发，发必三日乃止。予为诊之，左涩而右滑，据脉有瘀血痰积。近来小水不利，姑用四君子汤加滑石、红曲、陈皮、山楂、泽泻、升麻服后，微觉有热，改用四君子汤加滑石、桃仁、红曲、酒连，神气稍旺，脾气始回。乃用番鸦胆三钱下之，果去紫黑血块及如败鱼肠者半桶，从此痛除痢止。次日，以六君子汤去半夏，加酒炒白芍药、山楂、红曲、滑石、桃仁、升麻调之。报云胸膈作胀，恐积滞未尽而服参术，欲再下之，予为再诊，两寸短弱，两尺洪大，前日滑涩两脉俱无，此阳虚下陷之候，宜当大升大补。以六君子汤大加黄耆为君，酒炒芍药为臣，升麻、桔梗为使，服此胸膈宽快，精神也好，惟肛门热，前方加酒连，减半夏，脱然平安。", "6188": "陈氏妇，肠鸣腹痛，大便溏泻，合目即汗出，下午潮热。医谓潮热盗汗，乃虚怯之症，加之泄泻，脾气坏矣，视为不治。浼予诊之，右脉濡数，左脉洪数。予曰：此郁火痰积症也。盖忧伤肺、思伤脾，饮食因而不化，积而生痰，故腹痛溏泻。但理中焦，消去痰积可瘳也。以四君子汤加半夏曲、滑石、红曲、麦芽、苡仁、酒炒白芍药、酒炒黄连、牡蛎、桔梗八帖，而病去如释。", "6189": "九德侄，耳鸣，气筑筑然闭而不通，鼻塞不利，口不知味，痰多而膈热不清，脉左浮而弦大，右滑大，俱数。《内经》云：头痛耳鸣，九窍不利，肠胃之所生也。此由胃中痰火上壅，热极生风，乃以蔓荆子、升麻、木通、赤茯苓、桑白皮、麦门冬、生地黄、前胡、甘菊花、赤芍药、甘草、石膏，生姜三片，枣子一枚，水煎饮之四帖，左弦虽减半，而症尚如前。再用甘菊花、橘红、半夏曲、茯苓、甘草、知母、白芍药、酒芩、麻黄、石膏、桑白皮、桔梗加姜枣，又四帖而诸症悉平。后以六君子加酒连、柴胡、川芎、白芍、麦门冬、升麻两帖，饮食亦甘味矣。", "6190": "陈觉宇丈，常山县人也。年四十有三，体肥患痰火，十年多矣。每月必一发，或劳心过度则二发，吐痰身热，吼喘，饮食不进，不能倒头而睡，合目则乱语，面赤头痛，遍身痰气走动，牵扯作痛，必俟吐出痰后则耳始不鸣，目始不泪。素服风痰药南星、半夏之类不效，后服参耆也仅止四五个月。诊其脉两寸洪滑，两尺沉微，殆上盛下虚之候，法当清上补下。以橘红、贝母、茯苓、甘草、桔梗、杏仁、前胡、钩藤、天麻、酒芩、枳壳水煎服之，夜进七制化痰丸，再以八味丸加人参、麦门冬、五味子、空心服之，半年而瘳。", "6191": "表嫂孀居二十年矣，右瘫不能举动，不出门者三年，今则神情恍惚，口乳语，常悲泣。诘其故，答曰：自亦不知为何故也。诊之两寸脉短涩，以石菖蒲、远志、当归、茯苓、人参、黄耆、白术、大附子、晚蚕砂、陈皮、粉草，服四剂精神较好于前，但悲泣如旧，夜更泣。予思仲景大枣小麦汤正与此对，即与服之，两帖而瘳。方用大枣十二枚，小麦一合，大甘草炙过三寸，水煎饮之。此忧伤肺脏，脏寒故多泣也。", "6192": "堂嫂王氏，两寸脉洪大，右关滑大，五六月间必吐紫黑血块，足跟焮肿痒痛，时流黄水，与牡丹皮、山栀子、玄参、甘草、白芍药、当归、陈皮、滑石、桃仁四剂而愈。", "6193": "仲暗侄孙，赴府考试，过食牛面且劳苦，因而发疟。城中医疟半月，形神俱瘦，疟愈而腹大如箕矣。健所黄夫人，仲暗岳母也。凡名家递为延至，率认疟后腹胀，其中必有疟母为祟也。诸消痞药尝之不效，又以五皮饮利之不应，将议攻下，而予适至。观其色黄口渴，小水短涩，腹胀不可言，足膝之下肿大不能行，两腿肿连阴囊，气壅不能卧，饮食绝少，脉才四至，大而不敛。予曰：此真气虚中满症也，法当温补下元而兼理脾，病犹可愈。若攻下是杀之也。渠父与予厚，今宦河南，予安得不为渠任其重哉!顾歙友所用之剂，乃皂荚、槟榔、三棱、莪术、姜黄、葶苈子、木通、枳实、陈皮、厚朴、山栀、大黄、牵牛、黄连等皆破敌有余之品，见之且骇然，但黄夫人荐来之医又不能拒，正踌躇间，幸渠乃伯溪亭公知予心，卒谢歙医而一任予治。予即以人参、白术各三钱，炙甘草五分，大附子、炮干姜、桂心各一钱，破故纸二钱、桑白皮、砂仁、茯苓、泽泻各八分，水煎饮之。其夜小水稍利，喘急稍缓，连饮五日，腹稍宽，皮作皱。因食猪肚子大早，依旧作胀，前方人参、白术加至五钱，再加陈皮八分，又二十剂而腹消其大半，乃能伏枕而卧，始能移步行动。改以参苓白术散加破故纸、肉桂调养而安。溪亭公问曰：腹胀如此，口渴如此，小水短涩如此，诸人悉认为热、为有余，乃今以温补收功何也？予曰：公不观古人以气虚中满名鼓胀耶？由气虚所以成中满，设气不虚，何中满之有哉？且鼓者，外皮坚紧而内空无物，若复泻之，真元脱矣，安能复生？故惟有补而已。口渴、小水少者，皆元气虚弱不能运转。清气不上升故口渴；浊气不下降，故无小便。乃天地不交之否。兹特补其下元，俾水火充实，阳气上腾，浊气下降，中气运动，而诸疾皆瘳也。", "6194": "朱怀竹壮年，客外不谨而生杨梅疮，恐人知之，又欲回家，乃求速愈。每日用药外熏，熏而不效，用药水频洗，洗而不瘳，乃以末药点之，一日凡服煎药三帖。如斯两月，不惟疮不能瘳，毒且赶入内。在下则肛脱二寸余，周匝疮满如蕈，弗克收入，因而不能行坐；在上则毒入于肺，喘咳气涌，胸膈胀闷，不能仰卧，内热而外恶寒，寝食俱废，合目即谵语。阴囊疙瘩红肿胀痛，两足疮延肿大，精神恍惚，软床舁归。乃兄少竹逆予为诊，六脉俱洪大而数。语少竹曰：病至重，幸壮年，犹可治也。今予尚未可敷药，俟彼胸中瘀血毒物出后乃可服。否则彼以予药动血而反致疑。顾城中诸友鲜有识此病者，一误则大事去矣。慎之，慎之!少竹素信予，固请予药而不与其服。怀竹见予不发药，乃延张、程两公为治。晌午服药，晡刻大发喘咳，吐出紫黑血块如脓之类碗余，满房腥秽不可近。怀竹心慌，少竹慰之曰：毋恐。孙君先已预言你胸中胀闷者由熏药逼毒入内，上迫于肺，痰与瘀血壅遏肺窍，将欲成脓，故喘咳不能伏枕。顾脉洪大而数，从可知也，必俟吐后乘而消之，极易为力。今果如孙君言，孙君药俱在，急煎饮之。药用牡丹皮、桑白皮、白藓皮、木通、前胡、枳壳、桔梗、甘草、杏仁、苡仁、葶苈子，服后大便里急后重者二十余次，所下黑紫脓血甚多，喘咳稍定，痰红稍淡。二三剂乃能伏枕而睡。改用白芍、当归、白藓皮、甘草、贝母、黄连、金银花、皂角子、苡仁、麦冬、木通，连饮二帖，足上跟踝疮肿渐消，其夜阴囊出臭脓血二碗许。次早诊之，两尺脉不洪大矣，仍用前剂加丹参又两帖。阴囊结靥甚厚，横裂一缝，三日后随缝连皮落下约重五六两，厚可半寸，色如猪肝，洞见两阴子，系一光薄白胞，令人骇然，此也亘千古稀见者。举家谓阴囊乃致命之所，且未有子，今烂去，即使复好，也不能育子矣。环哭甚悲。予谕之曰：此毒去也，而真元不伤，吾能使其生肉如故，也不妨于生育，毋过虑焉。举家将信将疑。予即用红粉霜加生肌末药敷上，一日三次，并不作痛，脓水立干。外以人参、当归、酒炒白芍、白芷、甘草、白藓皮、皂角子、苡仁、何首乌调理一月，囊肌全生，诸症悉愈。乃令日用土茯苓、猪肉各半斤同煮极烂，将肉入酱盐如常法食之，汤当茶饮，脱然全瘳。次年生女。", "6195": "查良本兄令眷，怒后偶食鱼头，骨梗于喉中，即以馒头粽肉等压之，骨虽下，便觉胸膈不快。又服消骨药两日，迨今乃七日矣。胸膈胀痛殊甚，饮食悉从背后而下，恶寒发热，六脉弦数。予思骨梗之后，用硬物压之，伤其胃脘，必有瘀血停留膈间，将食管逼在背后，故饮食觉从背后下也。今但消去瘀血，使食管复原，胸膈之痛可瘳矣。药以五灵脂为君，山楂、玄胡索、桃仁、枳壳为臣，赤芍药、牡丹皮、香附、山栀仁为佐，柴胡、石菖蒲为使，水煎临服入韭汁一酒杯饮之。其夜胸膈宽快，大便泻一次，痛减大半，饮食仍从右边而下。右边胸喉稍痛，吞物甚艰若，吐出痰皆血腥气。改以山栀、赤芍药、归尾、桃仁、刘寄奴、五灵脂、牡丹皮、穿山甲、煎，入韭菜汁服之，两帖全瘳。", "6196": "后谿大兄孺人戴氏，勤笃严谨人也。秋患痢，所下皆血及屋漏水，内有血子如赤小豆者不可计数，昼夜五六十行，里急后重，哕恶不住声者，五日。予以刘守真芍药汤与三剂而病无进退。适后谿兄在浙，侄女辈素信医博黄氏为女科专门，延而治之，投以芩、连、枳壳、槟榔、山栀、地榆、黄柏、滑石之类，服已五日，始虽哕恶，一日尚有碗粥，今则粒米不进，腹痛转加，必用重物压之乃稍定。神思昏弱，卧不能起，下午发热。女科仍以前剂加青皮、枳实。侄孙尔嘉持药见予曰：家姑酷信黄医为专门，今已任事五日，较前精神大瘁，叔翁为祖父至交，宁无一语启愚乎？子曰：吾非不言，欲诋黄，恐为妒妇之口，今子来，予可诊之。六脉滑大无力。诊毕，慌语尔嘉曰：事急，可速令人促乃祖归。否则，令姑女流，不谙医药，吾安能施其巧？比有西席汪带川闻之，决尔嘉曰：此事极要调停，留黄医以安女流心，黄发之剂，搁而不进，以东宿之剂作黄剂进之，内外无猜则妥矣。予然其言，以人参、白术、酒炒白芍各三钱，炙甘草一钱半，炮姜、肉桂各一钱，白茯苓、陈皮各八分，砂仁五分，大枣二枚，水煎饮之。哕恶减半，其夜痢减十之五，惟腹痛不甚减。次早诊之，脉稍敛。黄医以为渠功，大言自矜，药仍以芩连之类。予仍以前剂再加黄耆。其日下午始纳粥一茶盏，腹痛渐减。又次晨，黄医诊视，见夜来痢减其七，益得扬扬得志。语左右曰：寒家业医五代，似此大病也不多见。自以为非彼也无能治也。尔嘉诘曰：疟痢也寻常耳，何以为大？黄曰：丹溪云下痢身凉者生，身热者死；下痢纯血者死；脉洪大者死；如屋漏水者半死半生。今皆犯之，故云去也。尔嘉曰：然。然则今日当用何剂：黄曰：剂已投病，仍当确守前方，何敢轻改？尔嘉笑而点首，复向予求剂。予以理中汤倍加酒炒白芍药，以肉桂佐之。腹痛身热悉愈。痢十去九矣。后谿兄也浙回，尔嘉述病原，以黄方、予方呈看，后谿唏嘘叹息。乃辞谢黄而诘予曰：人言下赤痢者热，哕恶者热，又身热脉大，吾弟何独认为寒，而用此大热之剂成功，曷故哉？予曰：此虚虚实实之处，极能误人，尊嫂之热非真有余之热，乃内有虚寒逼真血火上行，故哕恶潮热耳。脉大而无力仍作虚看，且向服寒凉不效，当自知警也。后谿兄曰：微弟几败乃事矣。", "6197": "邵敬圃令眷，常胃脘痛，由气郁而起。近以产后下痢红白，而胃脘之痛不止，汗多，六脉滑大无力，法当收敛。以小建中汤为主，白芍药酒炒四钱，炙甘草一钱半，桂皮、五灵脂醋炒各一钱，香附、糖球子各八分，水煎饮之，痛减，汗未全敛。次日前方加御米壳醋炒过一钱，两帖全止。", "6198": "苏文学望台，患疟一日一发，先寒后热，热多寒少，胸膈痞闷，口渴，小便混浊，腥臊不可近。医五越月不效，面黄肌瘦，饮食减少，喘息呻吟，精神疲惫，起须人扶，乃敦予治。脉得沉弦而数。公问曰：是疟否？予曰：是。公曰：吾闻之，真病不治，治之无功。盖真者，死候也。疟，殆常病，不过寒热虚实表里。诸名家曾认为表症者，麻黄、羌活、柴胡等汗之矣；有认为里症者大柴胡汤辈下之矣；有认为痰饮者，常山、矾石吐之矣；有认为虚寒者，附子理中汤、人参服过三斤矣；有认为实热，用白虎汤、枳实、青皮、槟榔、草果消之矣。尽法备尝，绝无一应，疟岂亦有真而卒至于死耶？言讫泪潸潸下。予曰：观公色脉，疟将发矣，不暇辩，第饮予药不死也。以柴胡、滑石各五钱为君，鳖甲三钱为臣，黄连、知母各一钱为佐，枳实、甘草各五分，黑豆四十九粒为使。水煎送下昆布鳖甲丸，申刻疟至，戌初便止。公喜曰：向者，疟发未申，夜半尚不能止，即止犹倦怠懒言。适饮先生药，不两时而止，止便能言，先生之功也。予曰：偶耳。今日服药已晏，明日五更幸早服之。服讫竟日不发。又次日，前方加人参、白术，小水腥臊之气已无，精神徒长。公又喜曰：两日无苦，先生之功也。予曰：偶然耳。公曰：嘻，吾疟几半载，休、歙之名公莫不历试，卒无影响，先生一举奏奇，有而不居，益见所养，不审汤名何剂，乞指示之，以诏将来。予曰：公何以名为哉。老子曰：无名天地之始，矧医亦道也，即道亦是强名。医贵识病，苟识病，一、二、三品，便能成剂立功。经云：约方如约囊。又曰：方以类聚，方凭病立。苟不识病，即尽本草一千六百五十六品并而服之，未见其益也。疟固常疾，治亦不易。仲景有言曰：治疟当分六经。予谓即六经之中，又各有寒热虚实阴阳在焉，是六六而三十六也。即三十六之中又有挟痰、挟食、挟气者，禀弱者，曷能枚举？人与天地、阴阳一致，天地变化无穷，人身灾患不一，岂拘拘一百一十三方、三百九十七法所能概哉？王节斋曰：古人因病以立方，非立方以待病也。斯言深得轩岐立方大意。然予今日所用之剂，和剂也。仲景谓汗吐下后而邪热不减者，是为坏症。以小柴胡汤加鳖甲治之。予特仿仲景小柴胡例，加益元散撤邪热从小便中出。鳖甲虽治坏症，又能截疟。公曰：噫嘻，前此诸公看病不过曰寒、曰热、曰虚实而已，未尝有此妙论，诚空谷跫音也。吾闻先生从祝令君潘去华辈，六邑会中讨究理致，又曾览先生序大易彀、序翼飞，乃知先生融三教而萃于医。先生之医得之于性命窍中，故能全人性命也有如此。", "6199": "太塘徐公，讳客者，其子弱冠，肌肉瘦削，尻膝肿大，手肘肩髃皆肿，肿处皆痛而发热。时医有作风治者，有作湿痰治者，有作鹤膝鼓槌风治者，愈治愈重，伏床褥奄奄一息耳。举家仓惶而决之蓍，楪者释策曰：易象可不死，天医上卦，第远在东方，相去百里而遥，迎而治之无恙也。因访予而迎之治。予诊其脉，六部皆弦，观其色青而白，饮食少。时当长至，予曰：此筋痿症也。书云诸痿皆不可作风治，病势几危者，以前药皆风剂耳。风能伤血，血枯则筋愈失养，况弦脉乃肝木所主，搀前而至是肝有余而脾土受敌，脾为所伤，宜饮食少、肌肉削而势将危也。《内经》曰：诸痿独取于阳明为治。阳明者，肠与胃也。法当滋补肠胃，俾饮食日加，五脏六腑有所禀受，营卫流行，气煦血濡，调养至春，淑气司令，君火主事之时，宗筋润而机关可利也。病者年虽少，而能闻言相信，恳予为治。予立方：五加皮、苡仁、甘草、苍耳子、枸杞子、回阳、人参、杜仲、黄柏、黄耆、防风。服二十剂而精神壮，腰膂健，饮食加。惟间或梦遗，则为减去杜仲而加远志、当归，三十帖而全安。此余初发之治也。", "6200": "太溏程巢父文学，乃郎讳万里者，年十五。夏月患痢，族医为治弥月，痢止而筋骨肿痛，痛处发热，昼轻夜重，肌肉消，饮食少，烦躁。医者以白虎历节风治之，病剧而形削骨立矣。又有作鹤膝鼓槌风治者，法愈更而病愈甚。其家有程松谷者，博洽嘉闻君子也，为巢父族大父。以余在西吴治多奇中，命巢父迎余。予至诊之，脉皆细涩。曰；此痢后风也。盖由治痢不善，以致寒湿秽瘀凝滞经络，日久气血为痛所伤。此症虚虚实实极难认，而措药不易，欲补虚则肿愈剧，欲疏通则痛愈甚，惟《局方》大防风汤可愈此疾也。防风、熟地、黄耆、人参、白芍、当归、杜仲各一钱，白术一钱五分，羌活、牛膝、甘草、回阳各五分，川芎七分，加姜三片，水煎服，服三十帖而愈。", "6201": "叶润斋，年近四十。心膈嘈杂，好啖肉。尤好鸡。一日不能缺，缺则身浮力倦，神魂无措，必急得肉乃已。见则大嚼，及入腹，腹又大痛，痛极则吐酸水稠涎，然后定，稍定，又思肉啖也。其痛苦之态。喊叫之厉，难状见者酸鼻。而润斋则甘心焉。市人咸以为祟。或有谕之者曰：古云与其好肉而受痛，孰若绝肉以无楚也。久病脾虚，肉入难化，故使作痛。此妇人女子且知之，汝丈夫独不慎，何哉？润斋曰：吾岂不知绝肉之为愈也。盖痛虽苦尚能熬，若嘈杂则遍身淫淫苏苏，左右无可奈何，手足无所把捉，顷刻不能自存，有近于死不能熬，急须肉少苏，吾岂纵口求痛哉？不得已也。乃翁延予为诊。六脉大小不等，观其色，唇红脸黄。予曰：据色脉乃虫症，非祟也，予能拯之。先与雄黄丸一服，不瘳；改以腻粉五分，使君子末一钱，用鸡子打饼，五更空心饲之，辰刻下长蛲十条，内有二大者，长尺有咫，自首贯尾皆红，下午又下小虫百余。自此再不喜肉，而嘈杂良愈。", "6202": "程相如丈令政郑氏，孕逾七月，因食冷患痢，所下皆白脓，腹痛后重，小水不利，两关脉滑数。以艾叶、砂仁、白芍药、白术、厚朴、泽泻、滑石、甘草与之。痢如旧，小水仍不通利，夜更痢频。改用当归、白芍药各二钱，益母草、酒连、酒芩各一钱，滑石三钱，枳壳七分，木香、甘草各三分，艾叶二分。两帖而安。", "6203": "太塘程晓山，程松谷从弟也。客湖州，年四十，悬弧之日，湖中亲友举贺，征妓行酒，宴乐月余。一日忽言曰：近觉两手小指及无名指掉硬不舒，也不为用。口角一边常牵扯引动，幸为诊之。六脉皆滑大而数，浮而不敛。其体肥，其面色苍紫。予曰：据脉滑大为痰、数为热、浮为风。盖湿生痰、痰生热、热生风也。君善饮，故多湿。近又荒于色，故真阴竭而脉浮，此手指不舒，口角牵扯，中风之症已兆也。所喜面色苍紫，其神藏，虽病犹可治。切宜戒酒色，以自保爱。为立一方，以二陈汤加滑石为君，芩连为臣，健脾消痰，撤湿热从小便出；加胆星、天麻以定其风，用竹沥、姜汁三拌三晒，仍以竹沥打糊为丸，取竹沥引诸药入经络化痰。外又以天麻丸滋补其筋骨，标本两治。服二料，几半年，不惟病痊，且至十年无恙。迨行年五十，湖之贺者如旧，召妓宴乐者亦如旧，甘酒嗜音，荒淫而忘其旧之致病也。手指、口角牵引、掉硬尤甚，月余中风，左体瘫痪矣（瘫痪俗所谓半身不遂也）。归而逆予诊之，脉皆洪大不敛，汗多不收，呼吸气促。予曰：此下虚上竭之候。盖肾虚不能纳气归原，故汗出如油喘而不休，虽和缓无能为矣，阅二十日而卒。", "6204": "去予舍二里许，地名曰前坑口。一妇人清明前十日发热、头痛。医者以九味羌活汤、十神汤进之不效，而又加口渴，舌黑如煤。更一医以如神白虎汤、竹叶石膏汤进之亦不效，而加泄泻不止，人事昏沉，四肢厥冷，呼吸气微，米粒不进者十四日，其家为具含殓而待毙。适予扫祖墓而近其家。其子闻之，即告急于予，恳为一诊。其脉细如蛛丝。予曰：此疫症也。合理中生脉二汤饮之，连进二服，夜半神气稍苏，饮粥汤半盏。次早，六脉渐见。予喜语其子曰：可保无事。书云脉绝微续者生，仍以前药与之。至晚泻止，口不渴，舌心焦煤退，精神清爽，骎骎向安矣。再用人参、白术各五钱，炮姜、炙甘草各二钱半，麦门冬三钱，五味子十五粒，水煎不拘时服。不数日而痊愈。", "6205": "族侄孙子忠，患痢于湖之东双林，腹大痛日夜行百余次，下皆红脓，状若腐烂鱼肠，绝无粪。疼而喊叫，声震中外，由孟秋饥饱后，娼家纵欲而得也。一病即伏枕，已十余日矣。予时寓雉城，相去百里外。渠叔少崖邀予往视。诊其脉皆缓大无力。始用芎归各五钱，加人参、白芍药、桂心、木香、黄连，服四日不效。改用胶艾汤，也不效。大孔状如竹筒，物食而下不变色，犹原物，予思之，此脾经为寒湿所伤，脾不裹血故也。非附子理中汤加肉桂、肉果不可。进五六帖痢始减半，饮食稍进，但所下秽恶仍若前状，亦无粪。渠父仲珪家居闻报，即遍访徽之名家，佥嘱以切勿用补药。兼程而抵苕城，儆虞留款，因询近用何剂？儆虞曰：闻用附子理中汤，人参每帖三钱，仲珪骇而堕筋，亟使见予，潸然泪下。言曰：侄五旬仅此一子，症危如此，倘不测，后将何望？予曰：郎君险过矣，复何忧？亦以侄只此一子，故殚心力相扶也。仲珪曰：离家而徽之名公，俱嘱以勿轻用补，侄故兼程而来。竟以补收功，非叔几乎误事。吾儿自今以往之年皆叔之赐，侄父子何以报效？予曰：治疾如救焚，医家份内事。矧属在宗邻，且无德我之望，又何望报。第雉城之约不可失，若浼李钟泉邀吴荜斋代视数日，俾予得践雉城之约，庶两尽矣。而吴子疑而辞曰：病者危在旦夕，何孙公欲自脱手而愚我被恶声也？予闻而晒之曰：见何鄙哉!丹溪有言，虚回而痢自止。病者再五日可脱然矣。予也暂留，即以东垣和中胜湿汤与之，服七日即衣冠出市，报谢四邻。吴见之而悔。李钟泉靳之曰：孙公欲成尔名，尔欲自没没也。悔之何补。吴由是改容相敬，令其弟游予门，彼也纳交予而称莫逆。子忠始病也，其友李钟泉重交谊，日夕省候，督其仆事汤药，毋许离蛙步。所下秽物腥臭不可闻，皆用漆布拭之，昼夜用数十斤。悉其湔浣，了无难色。两月如一日也。此友也今时所稀观者，因并记之，以著其高。", "6206": "有邵兄而讳马者，年五十患呕吐，吐物如烂猪肺状，胸背胀。市上诸医皆以翻胃治之不效，而反加潮热烦躁，饮食不入口。歙医谓肺坏，辞去不治。延予治之。诊其脉两寸滑数，左关尺涩。予曰：此瘀血痰饮症也，非肺坏，果若肺坏，声音当哑，今声亮而独胸背作胀，瘀血痰饮明矣。此症殆由酒后怒发所致。盖肝藏血，脾统血，酒伤脾，怒伤肝，以故不能藏，不能统，血随气上积于胸膈，必吐出而胀斯宽也。法当消瘀血、调气化痰，气调瘀消，则新血始得归经，大本端而病根可除矣。乃为立方。滑石三钱，甘草五分，茜根二钱，小蓟一钱五分，桃仁、贝母、归尾、香附各一钱，山栀仁、枳壳、桑白皮各八分。服十帖而全安。", "6207": "许卓峰者，多酒多怒人也。上吐血，下溲血，咳嗽声哑。族医以为瘵，辞去不治。迎予诊之。其脉左关弦大，右寸下半指累累如薏苡子状。予曰：此有余症也。作瘵治者非。客有辨之者，谓此症人皆认为瘵，而先生独谓非瘵。然何以失血而声哑也？予曰：其为人也好酒，酒属湿热而助火生痰，火性炎上，迫肺不降，积而生痰，壅瘀肺窍，肺属金，主声。书云：金空则呜，金壅塞而不通，故哑。此痰壅之哑，非肺痿之哑也。其性又多怒。《内经》云：怒则伤肝，甚则呕血，并下泄。盖血随气行，气妄动血随之亦妄动而不归原，故上吐而下溲。法宜清热开郁化痰、导血归原，不半月而病可瘳也。若认为瘵症而以地黄、天麦门冬、牛膝、山茱萸之类，将甚其塞而益其热，声音何由而开？血随气行，气不清，血又何得归原哉？诸君试观之。予用滑石、青蒿解酒热为君，贝母、郁金、山栀仁、香附开郁为臣，杏仁、桔梗同贝母化痰为佐，丹皮、丹参、小蓟、甘草导血归原为使。服十帖，血果归原。又以贝母一两，童便浸一日，为末，柿霜等分，时时抄舌上化下。五日而声音开亮矣，计期不出半月。", "6208": "族嫂钧孺人，年六旬，孀居已十余年。患痢赤白俱下，腹微痛，昼夜二十余次，呕吐痰涎，粒米不入口者两月。日惟用薄白酒打鸡蛋花饮之。肌肉尽削，诸药不效。予归诊之，六脉滑数，知湿热痰火所致。以二陈汤加益元散，姜汁炒黄连，黄芩。服几四十帖而呕止痢瘳。其病也几危矣，予为治者，恃其神存。惟神存，虽形气不足不食，犹可不死，此也医者当察也。", "6209": "邵来仪丈令眷，咳吐红痰，或如桃花脓色，前后心稍胀痛，两寸脉洪滑，此瘀血痰火郁滞肺之气道，而欲成肺痈也。治当调气化痰，兼消瘀血，清理肺金。以山栀子、牡丹皮、贝母、桑白皮、赤芍药、麦冬各一钱，白滑石三钱，茅草根五钱，小蓟二钱，甘草五分，枳壳八分，四帖而瘳。", "6210": "程玄祖兄春温食复，人事昏沉，内热口渴，舌如焦煤，胁痛耳聋，身热如火，僵硬不能转动，尸寝者十日，口中喃喃，盖梦语也。城中时疫正盛，亲友咸不吊庆。予为脉之，左弦数，右洪大而数。以柴胡、石膏各五钱，黄芩、知母、葛根各二钱，山栀子、枳实各三钱，甘草五分，连饮三剂。额上微汗，腹中雷鸣，其夜大便泻三次，皆清水，热仍不退。次早脉之，右寸稍软，前方加人参七分，又二帖而汗出热退。身仍僵，口仍渴，耳仍聋，泻也不止，汗也不收，四肢如冰，勺粒不进者已十三日。人皆以为死矣，予独不忍弃。以人参、麦门冬、白芍药、石斛各一钱，五味子十一粒，当归八分，桂枝三分，黄柏、甘草各五分。后再诊之，左脉已弱。咳嗽，人事渐爽，粥饮稍进，乃能开目发声。泻已止，颇可转身，才有生气。后以四物汤加苡仁、甘草、陈皮、白术、石斛、百合、贝母，调理一月全瘳。", "6211": "汪郎兄，腹痛，呕吐不止，城中诸友毕力医治不痊。予为脉之，早晚、大小、缓急不一，知其为虫也。以干姜、槟榔、苍术各一钱，五灵脂三钱，乌梅三个，川椒三分水煎饮之，痛吐立止。", "6212": "查景川兄，遍身痱痤，红而焮痒，诸君以白蒺藜、荆芥、升麻、葛根、玄参、甘草、石斛、酒芩、甘草与之，不愈。又谓为风热，以玄参、蝉蜕、赤芍药、羌活、防风、甘草、生地、当归、升麻、苍耳子、连翘服之，饮食顿减，遍身发疮，痛痒不可言。予脉之，两手俱缓弱，以六君子汤减去半夏，加白扁豆、砂仁、苡仁、山药、藿香、黄耆。一饮而饮食进，四帖而痛痒除，十帖疮疥如蜕。", "6213": "吴见南令郎，心脾痛。因劳倦而致，每痛必得可口之物压之立止。两腿生疮，右脉滑，左脉弱，以白芍药三钱，甘草一钱五分，白蒺藜、碧胡麻各一钱，当归、黄柏各八分，石菖蒲、白茯苓各六分，四剂而痛止。仍用小建中汤，减去桂枝，加黄柏、苍耳子、白蒺藜、何首乌，炼蜜为丸，服之，疮也寻愈。", "6214": "族侄女，年甫八岁，腹高于胸，发热面红，咳嗽呕吐，甚则连血喷出。右关脉滑大有力。此风热羁绊于脾肺之间而然。以滑石二钱，枇杷叶一钱，麦芽、天麻、半夏曲各八分，枳实、枳壳、防风、青皮各五分，水煎服之，热退嗽定，吐也良瘳。", "6215": "从兄䤾，年近五十，左胁痛，手足抽搐，不能步履，两手脉俱软弱。用当归、白芍药、木瓜、石斛、苍耳子、枸杞子各一钱，薏苡仁二钱，人参、牛膝各七分，陈皮、白芥子各六分，红花三分，水煎饮之。其夜大便下黑血二升，乃得睡，痛搐俱缓。改用人参、当归、白芍药各一钱二分，薏苡仁四钱，牛膝、木瓜、石斛各八分，红花、酒芩各五分，其夜大便仍有黑物，从此精神和好，寝食俱安。后五日，因为怒忤，且加食伤，右手左足大搐，左足大腿疼痛，缩而难伸，伸则痛甚，左胁极痛，小水短。用山楂、青皮、防己、人参、半夏曲、陈皮、苡仁、川芎、苍耳子、杜仲、石斛，以栝蒌为君服下，左胁痛止，右手也不搐矣。惟左大腿内股筋痛，一搐则膝抵于口，此也事之异者。因改以人参、当归、薏苡仁、甘草、黄柏、白芍药、钩藤、牛膝、木通、山栀子，诸痛搐悉愈，口也不渴。后只以此法调理五日，随能纵步出户。", "6216": "族侄良诠，患血痢腹痛，里急后重。时师治以香连丸、黄芩芍药汤不愈，反增痛，面赤唇红，有似涂朱，喊叫之声，四舍悚骇。比有太学宁宇者，仁心为质人也。怜其家贫莫秪，拉予为诊。六脉洪大，伏于床间，两眼泪而不能言。太学会其意语予曰：症诚急，彼以后事无措而难于言。予曰：诺，吾能起之。以生熟白芍药六钱，生熟甘草二钱，干姜、肉桂各一钱，木香五分，枣二枚，水煎饮之。饮竟嗒焉而卧。太学心疑，归嘱家奴曰：倘有急，叩门可即报我。及明，见无动静，仍令人觇病者何若：复曰：夜来痢减十之五，痛减十之七，早间已啜粥半盏矣。太学喜而叩予曰：渠面赤唇红，脉大，所下皆血，症皆属热，叔乃复投热剂，吾甚恐一夜不能寐，乃今疾已减半，生有望焉。不卜今日用何剂？予曰：比昨剂差小耳，方仍昨也。太学曰：吾惑矣，何视热为寒耶？予曰：君知脉大为热，不知大而无力乃虚寒也。面赤唇红由中寒而火不能下，阴盛格阳之症。设是真热腹痛，其人体仰而舒，寒则引而伏，所下血色带晦，均是假热，寒症明矣，前剂果再进而全瘳。太学复书报予曰：昨闻虚实真假之论，非饮上池水者不能道也。幸注之以诏后世。", "6217": "一妇，年三十二，大发寒热，胸膈有痰，大便泄泻。以二陈汤加白术、桂枝、白芍药、柴胡、酒芩一帖而止。后因怒，早晨又复发热，吐血一盏，口渴，汗多，脉甚数。陈皮、知母、柴胡、杏仁、丹皮、酒芩、白术、人参、乌梅、青皮、槟榔，水煎服之。用此调理，数脉渐退，惟左脉尚弦，寒热已止，喉中痰声已定。后又因将息失宜，两胁痛，痰多，嗽不易出。脉较前不甚数。以栝蒌仁一钱半，贝母、白芥子各一钱，萝卜子、桃仁、滑石、牡丹皮、香附、山栀子各七分，青皮、赤芍药、甘草各四分，煎服。血绝不来，嗽热寝息而安。", "6218": "族侄妇戴氏，两寸脉滑大，两尺沉微，心痛彻背，背痛彻心，甚则必探吐其食乃已。近来每一痛必七日，仅进白水，粒食不能进，进则吐而痛更加，七日后痛渐已。如此者十七年所矣。始则一年两发，又一年六七发。今则一月一发。以积气丸治之，不终剂而断根。", "6219": "老仆来兴，咳嗽胸胁背心胀痛，如刀刃所痌。发热口渴，诸治不瘳。脉浮而数，此风寒鼓激，痰火上涌而然。前胡、麻黄、紫苏子散风邪为臣、以栝蒌仁治痰火为君，橘红、半夏、旋覆花、杏仁为佐，枳壳、桔梗、甘草为使，两剂而平。", "6220": "族侄孙媳程氏，双桂翁女也，年甫三旬，产曾五胎，今则经闭不行者八年，肌肉则丰肥于昔，饮食又倍加于昔，精采则艳美于昔，腹柔不坚，略无所谓病者。独经闭不行，不生育耳。专科率用四物汤、玄胡索、牡丹皮、诸通调剂，计服千余帖矣。又如三棱、莪术、干漆、桃仁、苏木之类，莫不概尝，罔有一应。访余为诊。六脉缓大有力。予曰：此脾湿生痰，脂满子宫，徒行血、活血、破血无益也。法宜调气消痰，燥湿熔脂，俾使清瘦，庶新饮食不复生痰，不助肥脂，复为经水，经不期行而自行矣。若被专科者流，局局然养血活血破血，而望其经行不也难乎？盖前剂皆滋湿生痰之味，非有湿痰者所宜。而肥人尤不宜用也。乃为订一方，以平胃散加滑石、桃仁、黄连、姜黄、丹参、南星、半夏作丸剂服之，半年而经行，次年生一子，后连生一子一女。", "6221": "熊成八官，江右南昌人也。早起行路，忽见邪火两团滚滚而来，大惊骇。次日腹中膨懑，渐成胀满，面白皮薄，两手瘦削，两足皆有浮气，按之窅然不起，行动气促，形神俱弱。医谓神弱气促，面白肌瘦，胸腹青筋缕缕如贯索，小水清长，形症如此，脾虚所致，以参苓白术散投之，十日，堵然如鼓，中有一块巍巍突出，坚若铁石，脐已平满，勺粒不入。医者复诊，与渠决曰：若疾，法在不治，盍早图归，毋作异乡鬼也。病者闻言，泪簌簌下。熊东溪怜而恳予为诊。脉沉弦有力。诊竟语渠曰：审脉验症，非气虚中满候也。前补太骤，适有助长。顾今霉雨途遥，即归，恐未能时刻可到；即到，未必遇良手，治稍异，则大事去矣。予有一药，尚可冀生。东溪力为之请。以琥珀调中丸，日二进之。一进甚甘，再进称快。十日腹渐宽，块渐熔，半月块尽消去，青筋俱敛。改以平胃散加萝卜子、姜黄、苡仁、砂仁、木香调养一月，饮食大加，帖然安寝。两足之浮亦并消释。", "6222": "从侄中叔太学，以暑月赴南雍，一日转班，出索茶饮，饮辄逆流，左鼻出茶，入腹者十之三。当迓白下名家调理者尽其人。几一月，不惟饮茶水为然，食粥与饭亦多从鼻出。太学生平喜精洁，日与交游皆缙绅、逢掖，遂以疾自惭，因告假图治。闻京口多名医，买舟访之。如何、如张、如团，无不谒治。然愈服药愈病，渐加恶心，头晕，肌肉削，四肢无力，心益惴惴。亟归就予治。予诊毕，因叩所见诸名公认何症、投何剂？中叔曰：诸君皆谓此疾板籍无载，治法无稽，徒揣度为胃火。谓诸逆上冲，皆属于火。故投剂非黄连解毒，即三黄、石膏、栀子、黄柏、知母、天花粉、葛根之属。侄也以初到白下苦酒，因酒动火，理或为然，听其治而不惶它计也。予曰：治病贵辨明经络与经络之出纳虚实，明脏象，察经度，究竟夫病机病能，此扁鹊所以随俗为变也。何常拘拘守方书哉？《内经》有云：咽喉者，水谷之道路也；喉咙者，气之所以上下者也；颃颡者，分气之所泄也。人之鼻渊涕出不收者，颃颡不开也。子之症也颃颡不开之类尔。颃颡不开，故气上而不下。会厌弱而不能掩其气喉。夫鼻与气喉相通，惟不掩故饮食逆从鼻窍而出。不见常人偶气逆而饮食自喷嚏出乎!即其例也。且右脉缓弱无力，气虚明矣。《内经》云：形寒饮冷则伤肺。又曰：脾胃喜温而恶寒。又云：视听明而清凉，香臭辨而温暖。子多服寒凉，此所以恶心、头晕、肌消也。予但为温补。盖肺属金而主气，金气旺则收敛下降，气下降则饮食从气下矣。以六君子汤加辛夷、桑白皮、苡仁、沉香一进而势缓，三进而止大半，七剂而全安。以此症旧无载，故笔之以俟后人采焉。", "6223": "程达庵四媳戴氏，产半月而腿疼。迎专科诊视曰虚，投以八珍汤，服十日，痛益甚。予赴邑候之召，道经其庐，达庵趋问：产后半月而腿疼，何症？予曰：两腿皆疼，独一疼也？达庵曰：右腿疼。予问疼处热否？曰：热。予谓切不可认虚认风。此产后败血凝滞血海，流于经络，不急治则血无从出、久必化脓成毒，或为肠痈，今腿痛是其征也。达庵默然而别。复迎专科，又曰风也。但丹溪有云，产后须当大补气血，虽有他症，以末治之。投以十全大补汤。痛转剧，大发寒热，小腹近胯果红肿出脓。外科又为生肌收口太早，致腰俞复发一毒，肿痛寒热如初。十日后大溃脓而不收口，精神萎顿，肌肉陡削。饮食不进，恶心怯寒，奄奄一息尔。外科曰：不可为也。专科曰：余但治胎前产后，今为肿毒所坏。皆辞去而不下药，达庵始悔不听予言，以致误事。因急予，予往视。六脉濡大无力，疮口流清水而无脓。予曰：势棘矣，不暇治疾，速为保脾。盖五脏六腑皆藉脾土以为养。然非大剂人参、附子不可。始以人参、白术各五钱，甘草、干姜、大附子各一钱，黄耆三钱，白芷、桂心各五分，以其能排脓止痛也。外科犹然阻曰：白术作脓恐不可服。予曰：脓不死人，饮食不入口则死人也。急进之。四帖而神气回，饮食进，诸症悉减，疮口成脓。予语之曰：生矣，改用参苓白术散，调理一月而安。达庵叩予曰：公何预知必为肿毒，当急治也？予曰：《内经》所谓脏象。又云：现症腿疼而热，症已现矣。生于产后非败血所致而何？于时急为疏通，不留经络，何毒之有？专科不察而补，是益其毒而助之溃也。外科不审虚实强弱，概以毒治之，奈何不使患者几危哉？达庵曰：专科之不足恃也。如此夫，虽然不如是，无以见公之高矣。", "6224": "学士徐检老，体丰厚，善饮，致有肠风，计下血不下数桶，因而委顿。己卯仲冬，右胁极疼痛，上至耳后，夜分尤甚，左右不能转动，转动则痛甚，饮食减，面色青，闭目汗出如雨，湿透衣被，故不敢合睫而睡。族医皆投以香附、青皮，及辛散之剂，痛愈甚，汗愈多，面愈青。逆予诊之，两寸短弱，左关弦而搏指，右关沉滑，六脉皆近七至。予曰：据痛在少阳经分野，始必动于怒，木火之性上而不下，故上冲耳后而皆痛也。夜痛甚者，盖夜属肝气用事，《内经》云：司疏泄者肝也。邪在肝胆，故阖目汗即大出，中焦原有湿痰，法当调肝清热解毒为主，兼利小便，不可遽止汗而使邪无出路。今脉大数，如遽敛汗，是逆其木火之性，不惟痛加，且将发肿毒而害非浅矣。《内经》云：膏粱之变，足生大疔，当预防之。公曰：何为敛剂而谓不宜？予曰；当归六黄汤内有地黄、当归、黄耆，皆滞痰闭气之味，桔梗亦非所宜。书曰下虚者及怒气上升者皆不可用，故当慎也。因以柴胡、黄连为君，白芍、甘草、天花粉为臣，红花、连翘为佐，龙胆草为使，服后汗虽仍旧，痛即减三分之一，不妨睡矣。次日仍用前药，痛又减半，第三日又服，左右转动如常，饮食也加。予未至，公已先迎姑苏盛氏，盛公幼时窗友也，家世受医。公初不急予，日引领期盛到，可刈枯铲朽也。盛至诊毕，遂诘曾用何剂，公出予发剂示盛，盛大叫称谬，谓当隆冬之候，汗多如此，阳气大泄，何敢以柴胡为君，喉中痰既未清，又何不用桔梗当归六黄汤。前贤已试之药置而不用，是舍纪律而务野战出。即取六黄汤加桔梗以进。公雅信盛，乃倾心以从，速煎服之，未逾时而旧病随作，色色加恶，左右复不能转动，自戌而至子丑，苦不能支。有内侍语之曰：服孙君药虽未全可，亦已去泰去甚，彼曾言二药不可用，何为轻犯而受此苦？宜急取孙君药煎饮，饮下即伏枕鼾鼾，达旦始寤。命使速予至而叩予曰：人言隆冬汗出不当用柴胡，而公用为君，何旨？予曰：胆与肝为表里，肝胆之火郁而不发故痛，痛极而汗，汗出而痛减者，是火从汗出，盖汗乃邪出之门也。予故曰：汗不可敛。本草云：柴胡泻肝胆火，而以黄连佐之。《内经》云：木郁则达，火郁则发。言当顺其性而利导之。势则易克。古人治火之法，轻则正治，重则从其性而升之者。以此，盖医贵通变，如阴虚火动而汗出者，内无有余邪，故以六黄汤敛而降之，常治法也。今内有余邪未出，遽敛降之，邪无从出，势必成毒，故变常而从治者，使邪有出路，木火之性不逆，则毒不成而痛可减也。公曰：善哉。孙君之剂，奇正相生，不下孙武子兵法，何轻以无纪律议之，愿投剂而奏凯也。予曰：公数日后疮疡大发，两胯且有兴块作痛，此毒出之征，公于时无恐。改用柴胡、白芍、甘草、丹参、苦参、茯苓、瞿麦、车前子、黄柏、金银花、连翘服三日，而痛全减，汗全收，左右不能转动矣。逾日，公谓肌肤甚痒，累累然似瘾疹，岂疮出欤，欲以药浴之可乎？予曰：可。再三日，两胯果发兴块，如棋子大者数枚，且痛。予业已制蜡矾丸以待，至是授服之。疮果遍身大发，两腿为甚，一月余而瘳。公始信予防毒之言不谬，披愫交欢，且作序识胜，期与终身不替云。", "6225": "吴仪制主政尚卿先生，柱史安节公公子也。弱冠时，病鼻塞不能喷者四年，且衄，寒月更甚，口渴，咽喉边有痰核，脉之右寸关洪滑。予曰：此肺经痰火症也。与前胡、秦艽、葛根、薄荷、石膏、天花粉、玄参、贝母、山栀子、甘草、白药子、桔梗、丹皮、四帖而衄止。夜与牛黄三清丸数粒噙之，鼻气即通利能嗅，噙未旬曰痊愈。先生初年绩学，心专志一，不知寒暑，致有塞衄疾。又万历己卯庚辰，郡邑试皆首选，如此者再，而皆不得籍名学宫，益郁然不适。予时把臂语之曰：先生何以一儒冠为汲汲。据脉，科甲当不在尊君下，即馆中二友亦金马客也。依愚见，史先登，公次之，吴又次之，日后当以斯言为左券，毋相忘。后三公先后登第，一如予言。万历戊戌春，余应吴宫詹召，公暨史玉老不爽前言，皆为予撰《玄珠》序，而纪其事，以见一时良遇云。", "6226": "宜兴宋令君，山东人也，太夫人年五十余，病胸腋胀痛。予时寓吴宫詹家，而绳庵安节二公，皆宋公年友，因二公而逆予。诊太夫人脉，右寸关洪滑弹指，如黄豆大，左三部散乱无绪，如解索状，两尺绝无神气。予不得其受病之源，而宋公亦不以病源告，卒然问曰：脉为何症？予曰：据左脉为虚弱久病，右脉似又为饮食所伤，必病小愈而又伤，反复之疾也。其势亦危。宋公闻言危，乃拂其意，貌似不恭，予见其貌，即辞出，至后堂，有各佐二及学博佘公在焉。佘公予乡人也，素亦知医。问曰：症候何如？予曰：不治。渠谓前诊者皆无难色，公何云然？予曰：两尺无神，如树无根，此《难经》所云也。左脉散乱，右脉如豆大弹指，不旬日当见，果后七日而卒，邑中乡先生士民相传，谓予能预决死生云。", "6227": "宜兴令君胡镜阳公尊堂太夫人，年七十二，脾泄十五年不愈，近加吐红，咳嗽痰多，痰亦不易出，申酉时潮热，胸膈壅塞不能就枕，饮食大减，且恶风，终日坐幔中。诸医谓发热吐红，法当寒凉。脾泄多年，气虚老蓐，法当温补。二病矛盾，难于投剂。又谓身热脉大，血家所忌。益束手无能为计，皆辞去。且归咎于长桥上拆屋，致正堂不利。以是前丁宋二公接迹忧去，邑中汹汹，因延予治。诊得两手脉皆浮而洪数，亦皆带滑。予曰：据脉洪数为热，滑为痰，浮为风邪在表，以伤风故恶风。仲景曰：当汗不汗必作衄症。法当清解，可无恙也。公以诸医二病矛盾之说为问。予曰：此暗于先后者也。夫脾泄已久，未尝为害，新病势炽，宜当速去，所谓急则治其标也。俟邪去之后，补脾未晚，且潮热为风邪所致之热，而非阴虚火动之热，血乃当汗不汗之血，亦非阴虚火动之血。《内经》云：夺血者无汗，夺汗者无血。当汗不汗，邪鼓血动，但得表解热退，血自止耳。公怃然曰：噫唏!畴昔老母过钱塘，遇风涛受惊，因发热咳嗽，血出痰多，今以公言质之，诚由风邪起病也。愿以药进。予用紫苏子、前胡、麻黄、薄荷解表为君，枳壳、桔梗、桑白皮、栝蒌、紫菀、贝母消痰治嗽为臣，酒芩、甘草为佐，连服二帖，五更微汗而热退，胸膈不壅，嗽也稍减，血止大半，始进粥。次日减麻黄，加白茯苓，夜服七制化痰丸，其夜痰嗽又减半，从是不恶风而去幔矣。前方再减枳壳，加薏苡仁，调理而安。", "6228": "曹同府东岗先生患右胁痛予以脉知其伤风伤食所致", "6229": "曹同府东岗先生，右胁痛。脉之左弦大，右滑大，此由外伤风内伤食所致也。又加咳嗽，夜更痛，体肥面青，寝食俱废。予以紫苏、柴胡解其表，白芥子、桂皮、香附治其胁痛，山楂、萝卜子消其食，杏仁、陈皮、半夏、栝蒌仁治其嗽，四帖，饮食进，嗽也除，胁痛减十之七，再与保和丸服之而安。", "6230": "宜兴令君镜阳先生，上焦有浮热，胃中有食积痰饮，平常好食热物，稍凉即腹痛泄泻，大便后，间有红，又因劳心动火，头面生疮疖作疼，脉左数，右滑数，以玄参、石斛、白芍药各二钱，甘草一钱，天花粉、连翘、贝母各一钱，茯苓八分，薄荷五分，四帖，疮疖皆愈。再以保和丸加姜连、滑石、红曲、白术丸与服，半月全安。", "6231": "吴鹉源先生，咳嗽口干，腹中如火滚动，不知饱饿，亦不思饮食，右胁痛，脉右滑数，左弦数，此中焦有痰积也。先以总管丸去其痰，而后养脾，服后大便下稠黏黄糜甚多，小水如血，此热下行也。继以保和丸理脾消余痰，又使新饮食不生痰也。外以桔红、贝母、天花粉、桔梗、酒芩、知母、葛根、甘草、滑石服之，其咳嗽也除。", "6232": "吴鹤洲先生太夫人八十六原有痰火大便日三四行夜两起肠鸣脐腹膨胀脉三四至一止七八至一止人皆不治予独起之", "6233": "吴鹤洲先生太夫人，年八十六，素有痰火，大便一日三四行，一夜两起，肠鸣，脐腹膨胀，脉三四至一止，或七八至一止，诸医不知温补，妄以平胃散加黄连、山楂、白芍一切苦寒之剂投之，克伐太过，因致腹疼。顾不咎其误，但谓年高而脉歇，至是为凶兆，辞去不治。逆予诊之。予曰：据脉书云：脉缓而止曰结，数而止曰促。今结脉非凶脉也。由寒湿之痰凝滞所致，法当温补下元，俾火得以生土，所谓虚则补其母者，当无恙矣。鹤洲公曰：寿算何如？予曰：两尺迢迢有神，寿征也，即百年犹未艾。以补骨脂、白术各三钱为君，杜仲二钱为臣，白茯苓、泽泻、陈皮、甘草各一钱为佐，肉豆蔻、益智仁各五分为使，四帖，大便实，唯肠鸣未止，减肉豆蔻加炮姜五分而安。寿果至九十有八。", "6234": "吴荆樵文学，恺悌君子也。左关尺脉甚弦，疝气半年，两胯结核硬痛，予以平疝丸消之，海藻、昆布、橘核各酒醋炒四两，玄胡索、山栀子仁、山楂核、小茴香、柴胡各一两，龙胆草酒炒五钱，醋打面糊为丸，梧桐子大，空心酒下三钱，服一月而消。", "6235": "吴鹤洲先生，中焦有痰，肺气不足，疟一日一发，热多寒少口渴，小水不利，倦怠，头疼，脉左弦大，右寸短弱，关尺滑大。以石膏、知母、黄耆同柴苓汤煎服。服后腹作泻，前方去石膏、知母、邪热减大半。唯仅潮热而口渴甚，改以人参、葛根、知母、麦门冬、柴胡、陈皮、甘草、白术、鳖甲，五更服之而愈。", "6236": "吴雪舫先生，左胁下红块大如鸡子，旁有小菩藟作疼，左脉弦大而数，右滑大而数，盖由生平嗜爆炙，以使肝胆二经有热毒也。用大栝蒌一枚，白芍三钱，当归、甘草、贝母各一钱，连进三帖，疼减其半，胁下红成一小疖，以解毒早，故硬块潜消，大毒不成也。仍当为活血清热，再用白芍三钱，当归一钱半，金银花、甘草各一钱，大栝蒌一枚，连翘、山栀仁各八分，红花、柴胡各五分，四帖而愈。", "6237": "吴孝廉球泉先生，心血不足，胃中有痰，下元阳气不充，脉六部皆弱，唯右关滑。以远志、枸杞子各四两，巴戟、菟丝子、破故纸、山茱萸各二两，五味子、白茯神、人参各一两，炼蜜为丸，空心淡盐汤送下三钱。外以固阳锁真丹助之，龙齿、益智仁各一两，黄柏二两，辰砂、甘草、莲花心各五钱，芡实粉打糊为丸，桔桐子大，每夜灯心汤送下一钱五分，极能固精。", "6238": "李思椿患胸膈胀痛，痰中有紫色瘀血，其原有酒积郁火也。脉两寸短，关滑，两手皆数，先与红六神丸服之，继以山栀、酒连、郁金、香附、橘红、茯苓、半夏曲、甘草、滑石、紫苏子，服后胸膈稍宽，仍以山栀仁、贝母、益元散各二两，牡丹皮、黄连、橘红各一两半，白茯苓一两，紫苏子、郁金、红曲各五钱，茜根三两，神曲打糊为丸，每早晚白汤送下二钱，调理而愈。", "6239": "吴双泉公，两尺脉洪大，两关滑，两尺沉微，此阳亢阴微之候，上盛而下虚也。上盛者，痰与火，下虚者，肾经真阴不足也。法当清上补下，上清则头目清利，耳鸣眩晕之症可除，下实则腰膝不酸，筋骨强健。清上用清中丸，贝母、橘红、枳实、海石、山楂、茯苓、白芥子、黄连、黄芩、滑石、青黛、神曲为丸，食后茶送下二钱。补下用既济丹，辰砂，磁石各一两，熟生地四两，黄柏、知母、菟丝子、柏子仁各二两，牛膝、枸杞子、白茯苓各一两半，炼蜜为丸，梧桐子大，空心淡盐汤送下八九十丸。", "6240": "李寅斋先生，患血淋几二年不愈。每发十余日，小水艰涩难出，窍痛不可言，将发必先面热牙疼，后则血淋。前数日饮汤水欲温和，再二日欲热，又二日非冷如冰者不可，燥渴之甚，令速汲井水连饮二三碗，犹以为未足。未发时，大便燥结，四五日一行，发则泻而不实，脉左寸短弱，关弦大，右寸下半指与关皆滑大，两尺俱洪大。据此中焦有痰，肝经有瘀血也。向服滋阴降火及淡渗利窍之剂，皆无效，且年六十有三，病已久，血去多，何可不兼补，治当去瘀生新，提清降浊，用四物汤加杜牛膝补新血，滑石、桃仁消其瘀血，枳实、贝母以化痰，山栀仁以降火，柴胡升提清气，二十帖而诸症渐减。再以滑石、黄柏、知母各一两，琥珀、小茴香、桂心各一钱半，玄明粉三钱，海金沙、没药各五钱，茅根汁熬膏为丸，每服一钱，空心及晚，茅根汤送下而愈。", "6241": "徐熙宇文学内眷，常患前后心痛，每痛必面赤手心热，耳鸣眩晕，即饮白汤，亦停膈间不下，且作酸呕逆，吐出皆酸水，五七日方止。四肢酸软无力，气逆上嗳，乃其常也。两手脉皆沉数，左弦，此上焦有痰饮故也。先以二陈汤加瓦楞子、滑石、吴茱萸、姜连、前胡、枳壳竹茹、香附、大腹皮服，后以橘红、半夏、滑石各二两为臣，白螺蛳壳煅过四两为君，茯苓、姜连各一两半为佐，旋覆花一两，吴茱萸三钱为使，面糊为丸，每服三钱，调理而愈。", "6242": "吴仰玄先生，患胃脘痛，痛则彻于背，以手重按之少止，痛时冷汗如雨，脉涩，此气虚而痛也。以小建中汤加御米壳服之而愈。", "6243": "粳芝岗文学，酒后近内，每行三峰采战、对景忘情之法，致成血淋。自仲夏至岁秋未愈，便下或红或紫，中有块如筋膜状，或如苏木汁色，间有小黑子，三五日一发，或劳心、或劳力，或久立、坐亦发，访医问道，百治不效。以吴中书汉源公交善，逆予治之。观其色白而青，肌肉削甚，诊其脉，左寸沉弱，关尺弦细，右寸略滑，据此必肺经有浊痰，肝经有瘀血，总由酒后竭力纵欲，淫火交煽，精离故道，不识澄心，调气摄精归沅之法，以致凝滞经络，流于溺道，故新血行至，被阻塞而成淋浊也。三五日一至者，科盈满溢故耳。先与丹参加茅根浓煎服，小便解后，以瓦器盛之，少顷即成金色黄砂，乃用肾气丸加琥珀、海金沙、黄柏，以杜牛膝连叶捣汁熬膏为丸调理，外以川芎三钱，当归七钱，杜牛膝草根煎服。临发时，用滑石、甘草梢、桃仁、海金沙、麝香为末，以韭菜汁、藕汁调服，去其凝精败血，则新血始得归源，而病根可除矣。三月痊愈。", "6244": "吴中翰汉源先生，肠风下血，腹中微痛，脉左寸短，右关滑，两尺弦大，以地榆、槐花、枳壳各三钱，荆芥穗、秦艽、青蒿、葛根各一钱半，黄连二钱，两剂而愈。", "6245": "大柱史安节公，脾肺二经有痰火，中焦有湿热，流于膀胱为淋浊，溲之前作痛，小便了而不了，脉左寸短弱，关弦大，右寸关滑，两尺洪大，六部皆数。法当先清上中二焦痰火，然后提清降浊，庶日后筋骨无疼痛之患。先与萆薢分清饮加山栀、黄柏、滑石服之，淋浊减半，改以二陈汤加山栀、黄柏、滑石、螺蛳壳、木通以去湿热，而消中焦之痰，再加柴胡、升麻、桔梗以提清气，四帖而愈。", "6246": "吴官詹少溪翁，原有酒积，且频伤于怒，致右胁之火冲上作疼，耳鸣眩晕，大便艰涩，脉右寸关滑数，左弦，以当归龙荟丸加牛胆南星治之而愈。", "6247": "吴孝廉球泉公内人，痢疾后感寒，又月水适至，大发热，口渴，遍身疼，胸膈饱闷烦躁，头微疼，耳亦聋，大便泻，舌上白苔，脉七八至，乱而无序。此三阳合病，春温症也。时师误以为漏底伤寒不治。予曰：病已危，医而不起者有矣，未有不医而起者也。且投三阳药服之，挑察征应，再相时而动。以柴胡三钱，葛根、白芍药各二钱，枳实、桔梗、酒芩、竹茹各一钱，天花粉八分，炙甘草、桂枝各五分，服后但觉遍身冷如冰，面与四肢尤甚，六脉俱无，举家及医者皆叹为物故矣。予独曰：非死候也，盖夜半阴极阳生，势欲作汗，比之天将雨而六合皆阴。球泉疑信相半，而诸医闻之皆笑去，四鼓后果战而汗出，衣被皆湿，四肢体面渐温，神思清爽，且索粥，举家欣欣，以为再生。次日惟耳尚聋，腹中大响，脉近六至，改以柴苓汤加乌梅，两帖而愈。", "6248": "万肃庵先生令郎，发热十一日，口渴，舌心色若沉香，且甚干燥，额上热极，两胁亦热，耳微聋，曾未有汗，亦已下二次，热不少除，小水绝少，神昏足冷，饮食不思。市医技穷，仍告急于予。予诊之，左脉中按数而有力，右脉软弱，据症为阳明少阳并病也。当以柴葛汤清其热，看汗有无，再当机而处。柴胡五钱，葛根三钱，白芍药、石膏各二钱，人参、升麻、天花粉各一钱，粉草七分，水煎服之。次早诊，数脉稍缓，热稍退，舌齿仍干，小水不利，神思尚昏沉，改用柴胡、粉草、天花粉、黄芩、人参、白术、茯苓、滑石、木通、泽泻。下午又觉微热，面赤，额上痛且重，即以益元散三钱服之。大便行一次，溏而色黄，热仍甚，面仍赤，服前药后，小水去二次。再诊之，寸关脉将和，两尺尚洪大，乃知邪热在下焦，唯利之而已。再与辰砂益元散五钱，口渴稍止，齿下盘虽润，上盘仍燥，神思昏沉，睡而不醒，睛彩不与人相当，又知热在心包络也。宜用陶节庵导赤散，二帖而神清，唯小水尚欠利，以四苓散加酒连、麦芽、木通煎服，再二帖而诸症悉退，饮食且进矣。", "6249": "大宗伯万履庵老先生夫人，右胁下疼，咳嗽喉干，间亦吐红，或一碗，或半碗，肠鸣泄泻，年六十外。原因头风坏目，性急躁。左脉弦数，右滑数。以栝蒌仁二钱，黄连、前胡、桔梗、枳壳、橘红、贝母、白茯苓各八分，甘草五分服之，次日红仍不止，唯胁疼减半。改用山栀仁、牡丹皮、香附、贝母、甘草、栝蒌、紫菀、滑石水煎服。方欲觅真郁金，苦不能得，唐凝庵老先生，乃夫人婿也，偶至闻之，应声曰：有。取磨三分，用煎药饮之，二帖而红止痛瘳。", "6250": "白仰云先生令眷，每触怒即晕厥，必闭门合目静坐，不留一人在房，手足皆冷，汗出如雨，气息俱微，越一时许，苏如常。原以颈生瘰疬，多服女医草头药，及专科用斑蝥等毒，因而脾胃损，元气亏也。年三十八，曾未生育，每日令二婢不住手敲两腿，俟其熟睡乃已。不然则睡不安，晚至二更后始睡，夜半心多惊跳不止，指甲皆无血色。经将行，小腹先疼二日，色紫有块，诸病虽如是，而肌肉饮食却如无事人，百治不效，慕予而请诊之。两寸短弱，左关大而有力，右关滑，左尺滑，右尺沉微，据脉肺气虚，肝木实，胃中有痰之症也。用六君子汤加丹参、酒连、青皮，外与珠母丸及独活汤二方调理而安。（二方出《医学纲目》）", "6251": "吴文学齐阳先生，笃志士也。以积学劳心，又有星士以己卯决科许者，其星士前许历历有验，至期疟发不能终场，遂心忧而成癫狂，日间或悲、或歌，或鼓掌，或顿足，甚则骂詈不避亲疏贵贱。乃叔邀予视之，面白而青，脉两寸短弱，关弦，右关滑，两尺平。予谓两寸脉既短弱，此心肺之神不足，志愿高而不遂其欲，郁结不舒，津液生痰而不生血，又攻痰克伐太过，心神愈不得养，故昏乱而无所摄持。《内经》云：主不明则十二官危。按此，则治宜补养，收敛心神，而兼之清痰，可万全也。用酸枣仁、人参、茯神、小草、丹参、当归以补心安神，黄连、竹茹以清肝胆之火，玄参佐之外以龙齿、珍珠、羚羊角、牛黄、胆星、天麻、青黛、辰砂、全蝎、水片、黄连、甘草膏为丸，金箔为衣，调理而愈。", "6252": "太史徐检老，向为𤻊疝所苦，而妨生育。辛巳孟秋，有江右陈苓泉者，以是症为专科，寓无锡，翁延而治，谓将烂药煮竹片夹阴囊，俾阴囊烂见子，又以烂药点开肾子，使其中蓄积臭水溃出，然后用生肌药长肉收功。翁以此治与道中诸友商之，无有劝者，而谋于予。予曰：翁疾非常疾，则治当非常治也。陈能为翁治于外，予当佐陈补于内，内外兼治，必可成功。翁因予言而决用陈，是时，予有湖州之役，而陈用其术治一月，囊烂子开，洞见水泡，第不能使泡破水出也。由是胸中气满，汗出如流，终夜不寐，饮食减三分之二，面青肌肉瘦其半，形气弱而大便艰涩，腰肾俱痛，苦不可殚述。将令人急予。予适自湖州至荆溪，主吴少溪公家。翁时杜门谢客，闻予至，大喜而促予，诊脉两寸软弱，右尺大，右关滑。予诊毕曰：向许佐陈治内，今其时也，比陈技已竭，而水不得出，翁又难于痛，业已用收口药矣。予曰：无伤，痛由元气虚惫，而汗亦因痛来，汗去多则心血不足，心血不足则神失养，故不寐，脾胃为痛所伤，故饮食减，今只大补血气，不惟痛止疾除，即水泡亦可出也。陈谓用补收口生肌，或可使泡出水，或未必然。予曰：三日后，当自见，翁曰：补甚善，奈生平不能服参何？予曰：翁体非昔比也。脉症皆可服，又何忧？乃用人参、黄耆各三钱，当归、白芍、石斛各一钱五分，陈皮、贝母、红花、粉甘草各八分，饮下即睡。次早汗敛，且索粥，胸膈顿宽。连服二日，痛减大半，饮食顿加，精神亦爽。乃陈恐予夺功，私谮之曰：孙君之药虽善，但非外科所急，服之恐生肌收口后，而水终不得出也。翁谓必如何而后可。陈曰：当于前药加羌活、防风、白芷、远志。减去石斛，则外内两得矣。翁然其说，且服其药，饮未半而痛立至，汗立出，头热如火，气逆上升，夜竟不寐，种种病复矣。极索予剂，予知陈之忌而行谮也。乃宣言曰：予实佐尔成功耳，尔何自败？尔知翁之痛乎，元气虚而毒药凝滞，故补而助之，活动其血，则毒药自行，药行则泡可溃，水方可出。翁之谢尔已有成议。予雅善翁，来者为义，非为利也，鄙见与寻常较不牟矣。陈闻言而语塞，亦以投剂无功，遂乘机而听予治。仍用前方，加酸枣仁、枸杞子、皂角刺各一钱，两帖而泡溃，出臭水五六碗，囊随消瘪。陈拊掌曰：今而后知用补之神，其老先生之福也。太史受补自此始。", "6253": "丁酉冬，宫詹少溪吴公，年七十二，以长君秋闱之捷，应酬贺者过劳过饮，又伤于犬肉，市医概用消导之剂投之，漠如也。反加内热。常州张氏，荆溪缙绅大家恃为锁钥者，至则谓公高年过劳，消剂峻而致内热，用补可愈也。因投人参，则右胁胀痛，尽夜难支。张又谓补法不瘥，唯少行气之味，故无功耳。于前药加木香、砂仁，辛热止痛之剂，益呕吐不止，胀痛转剧，而大便燥结。张不自咎不认病而误投，乃遍语缙绅相知曰：吴少翁老年膈食，非其所宜。丹溪复生，无能为也。少翁闻予在苕，而急予治，予兼程而往，至则脑之念一日也。诊其脉，左弦右滑，两手皆数，且搏指，谛视其色，神藏气固，唯肌肉略瘦，手心甚热。予曰：此内伤症，非膈食症也。公曰：诸君言吐而大便燥结，食不得下，非膈而何？予曰：否，公原不热不痛又不吐，由误饮药而使然耳。书云：通则不痛，痛则不通。大便既燥而用补，非也。经曰：食不得入，是有火也。尤用辛热，非之非也，以是而治，比之以油救火，益令其炽耳。予见与诸医不侔也。即与琥珀调中丸一帖，其夜胁痛稍缓，次早诊之，脉仍如前。予决谓非通不可，即以龙荟丸与调中丸兼服之，五日内下黑粪十五六次，诸症悉减，饮食大进，改以保和丸，调中丸调理。念七日，公即能巾栉，元旦命庖人治酒，榜人舣舟拉予泛于南门，持觞为予寿曰：与兄别者十六年，不惮劳涉险而赴吾急，自今以后之齿，皆兄之赐也。敢不铭心，为欢竟日。至谷日，予乃别而复之苕。", "6254": "别驾吴勉斋翁，体丰腴，嗜炮炙，任性纵欲，年六十七。极躁急。一日跌伤其齿，恬不为意，阅三日复跌，亦不为意，复跌之次日晚，左手足忽不能动，口眼歪斜。陆怀南先生，公通家友也。即往诊之，语公诸郎曰：此中风也，治不可缓，急取牛黄丸进之，诸郎皆有名博士弟子。延予为治。诊其脉，左洪大，右缓大，观其色苍黑，神昏鼾呼，呼长而吸短，呼至口气𠷺𠷺出不能回，终日偃卧如醉，人不能动。陆曰：此非半身不遂乎？予曰：症候甚恶，不特半身不遂也。半身不遂者，中风已过之疾，其势仍缓，亦有十余年无恙者，今才病，势便若此，乃中风之渐，方来且不可测。陆重厚长者，所诣亦精，闻予言，当下了然，即与予商确用药。始以六君子汤加全蝎、僵蚕、天麻，与之两日，神气仍未清，犹昏睡，睡犹呼吸，口边𠷺𠷺然，间作吐，粒米尚不进，前药再加竹茹。又两日，神始苏，欲言而舌难掉，嗫嗫不能出诸口，前药又加石菖蒲、远志、红花，始能进粥数口，日计亦可茶瓯许，夜与正舌散，同前药饮之。又三日，能坐，粥亦颇加，唯言尚謇涩，欲言以笔代口，写我左手甚痛，大小便艰少。又用四君子汤加陈皮、竹茹、当归、芍药、红花、钩藤、天麻，服三日，神思大好，饮食日加，以是方调理弥月，手痛减，稍能动，足稍能伸，扶起能坐，且能自按谱铺牌，语言十分清至八九，骎骎有万全之望。唯大便有七八日或十余日始一行。予曰：此血少之故，补养久当自全，幸无他用而速害。公常自言吾疾乃痰在膈间，何能得一吐为快，此医家有授之言也。予曰：公脉大虚，非余痰为害，况今以补养而渐安，此其明验，何敢轻试一吐，愿宁耐静俟，毋涉危险也。此戊戌九月念五，予以是日别往苕城，别不及旬，公复倾心而任张甲，张大言曰：公病可吐，早吐早愈，诸郎君始信予言，持议不可。彼曰：公病痰也，不可不吐，吐而后补，可全愈而无后患，不然必成痼疾。公欲速效，决意吐之。诸郎君不能阻，一吐而烦躁，犹曰吐不快耳，须大吐始可，再吐而神昏气促，汗出如雨，立时就殂，可叹可叹!", "6255": "少冢宰徐检老，以万历丁酉三月初旬，往贺长兴臧老夫人眉寿而发寒热，臀近肛硬处生一毒，红肿而痛，坐卧为艰，因归荆溪访治外科，即以镵针点开，插药线于内，涂以烂药，使脓血急溃，又于疮口上以生肌药敷之使易收口，可受谢而去，未半月，其傍之硬处，又红肿痛，寒热交作，几于成脓。以前医有功，遂复延之，至则又以向者之法治之，受谢而去。递医递患，递针而递插药，计其患者凡八遍，计其医之更者，如张。如鲁，如冯，凡八人，有陈外科者，则总其中而受谢独多，其时则丁酉三月至戊戌八月，几年半矣。于时，予赴吴少溪翁召，因知翁在褥，亟往谒于卧榻间，翁见予至，悲喜交集，备陈其历病之由，针刀之苦，伏枕岁月之深，辄为痛心，予闻之亦为鼻酸。谛观其色则青惨，诊其脉皆濡弱，把其手足，则冷如冰，问其饮食，减平日之六，究其所服之药，则槐角、黄柏、生地、凉血解毒之类。予骇然而语翁曰：此痔痈非痔漏也，痔漏当用挂线，以五灰膏点之可愈。今肿硬无定处，离肛门且远，况其初原无硬块，硬块由插药凝滞中来。谚云：剜肉做疮者非耶？假令非翁禀气厚，胃气壮，安能六十以外之年，而当此剥削哉!初只可大补气血，即有毒，只宜托出一脓而愈，未成者，使活动消散，不复生毒，此王道之治，不胜于针刀万万？诸君之治，如避影者，不知息阴而急趋以求避，则影益速，而气促敝矣，自迨之道也。翁初不逆予者，以非外科，至听予之论，幡然有悟，又见《玄珠》集有外科二卷，益信予之善外科，而听予治，予即以十全大补汤进之，四帖，而饮食加，手足暖，大便艰涩百方润而不能行者，今亦通利，而肛门如不知也。诸外科犹晓晓议补非是，予极言排之，翁惟予为听，予以何首乌四两，人参、枸杞子、黄耆、当归、熟地各二两，槐角、秦艽各一两，蜜丸服之。不终剂，其肿处少出脓而全瘳，旁亦不生硬块，益信向之硬块为插药之毒所致也。翁喜为谑曰：予病非孙君，诸外科视我疾为金穴，其取宁有已耶。呵呵!", "6256": "宫詹吴少翁，患痢，赤白兼下，里急后重，市医治半月，后重不除，饮食渐减，最苦者，下午发热呕吐，乃遣使往苕召予，予闻状心怖，即涉险而过太湖，一昼夜而至荆溪，翁卧榻已二十日，观其色，唇红面瘁，听其声，微弱不扬，但一两语，气即不接续，下午潮热，至丑方退，形神俱弱。诊其脉，两手俱大而无力，右关略滑。予曰：据此乃虚虚实实之候，不足中之有余也，治当补养，兼清兼消，缓以治之，庶可无恙。公深然之。以四君子汤加白芍药、黄连、山楂、滑石、陈皮、柴胡，两帖而潮热除，呕吐止。去柴胡，因口渴不止，加葛根，六剂而饮食渐进，血亦止，惟白脓不除。改用人参、白术各二钱，白茯苓、白芍药、当归、神曲各一钱，酒连、陈皮、泽泻各七分，滑石、山楂各一钱半，外以丸剂消息盈虚，调养半月，则神气回而饮食大进，肌肉渐生矣。少冢宰检翁问曰：诸医先谓老年痢非所宜，又呕吐饮食不进者，谓之噤口，且身热脉大为痢所忌。公不旬日而收功，岂诸医称书之忌皆幻妄哉？予曰：诸君所言，皆至言也，第非因时制宜耳。愚见以脾胃乃五脏六腑之仓禀，故曰纳谷者昌。又曰人身之内，谷气为宝，予姑舍痢不治，而先开胃口，俾进饮食，使新糟粕将宿秽压下，若见粪则后重除而痢易愈也。然又相其机宜，若食入而腹胀作痛，又量势略与疏通，通后或气虚下坠，又因势而略与升提。大抵以理脾开胃进饮食为先，此亦远交近攻之策，日虽多，功可万全矣。斯仆一得之愚，屡试而屡验者也。设不先开胃口，不审老弱，不揣缓急，一概治痢，虽有得未必无失，岂能胜算哉!公曰：善。", "6257": "臧少庚年五十，每饮食，胸膈不顺利，觉喉管中梗梗，宛转难下，大便燥结，内热，肌肉渐瘦，医与五香连翘汤、五膈丁香散，诸治膈之剂，尝试之不效。时予方有事于先冢，久未远出，臧则不远千里而就予治。观其色苍黑，目中神炯炯不眊，唯气促骨立，予知其有机心人也。其脉左弦大，右滑大。予谓之曰：据脉，乃谋而不决，气郁成火，脾志不舒，致成痰涎，因而血少便燥，内热肌消。张鸡峰有言：膈乃神思间病。即是推之，子当减思虑，断色欲，薄滋味，绝妄想，俾神思清净，然后服药有功，不然，世无大丹，而草根木石何足恃哉!子既远来，予敢不以肝膈相照，兹酌一方颇妥，归即制服，但毋轻示人，恐见未精者，妄为加减，乃败事矣。慎之慎之!臧曰：谨如教。其方用桂府滑石六两，炙甘草一两，真北白芥子、萝卜子、麝干、连翘子各一两半，辰砂五钱，以竹茹四两煎汤，打馒头糊为丸，绿豆大，每食后及夜，用灯心汤送下一钱半，一日三服，终剂而病如失。", "6258": "周礼姬公治书也，医、方技耳，而列之天官冢宰，此何说哉？盖天、生生者也。天能生生，不能使有生者尽尊其生，则生生之权于是乎穷，所以斡旋生理而佐化育，所不逮者，不得不寄于医。医、代天者也。故炎帝也而本草，轩岐也而《灵》、《素》，伊尹也而汤液，皆承天好生之德，而立天下万世民物之命。顾天所以生生者，惟是阴阳动静之气，变化顺逆之机，燥湿虚实之宜，而长桑家生生之方，皆原于是。苟识不能探其玄，且不能达天，而恶能代天。善乎孙思邈之言曰：不知易者不足以言太医也。新安有生生子文垣者，博极典籍，剖生克如列眉，固已登濂洛之堂，诸如柱下檀林，全生脱生之旨，靡不收为鼓吹之用。以故独观妙窍，而诊治之奇，驾和扁而轶其上，有声三吴者旧矣！余每见徐大史检老，辄啧啧生生子、生生子云。余窃私心乡往，迨戊戌南还，适有天幸，值孙君起吴宫詹疾，见其囊中光焰若发，意又有神物，索之，果得《医旨绪余》、《赤水玄珠》二书，展卷读之，命门右肾之辨，详而确也；十二经三焦之说，畅而明也；缘症投剂之方，精而当也。而尤精于相火一经。夫火者天以之生物，人以之生身，此生生之大者也。论者不翅聚讼，有认阴火为相火者矣，有以五志之火为相火者，有以龙雷之火为相火，又分天火为相火，人火为君火者矣。夫地二生火，天七成之，阴亦为主，何言相也。指五志则混君相，其失也杂，言龙雷则专肝肾，其失也偏，分天人则隔君相，其失也又支离决裂。惟心一动而万火奔驰。心，君也；十二经中，包络、三焦，相也。君至尊居中，主火之令。相守位列外，禀火之命。所谓君行意，相行令者也。经不云乎君火以名，相火以位。君相之名义，诚千古未发之奇也。斯论出而孙君生生之意，殆与火传而不尽者乎。闻其生平临症，殚精研虑，如梓人之削㹱，非誉巧拙不以间，如丈人之承蜩，天地万物不以易。圭匕之投，得心应手。而又随诊定方，缘方立案，笔之于帙，以为后日参考地，汇为六卷，名历验医案。余方倾注一日，其季君济孺，甫出以示余。曰：此家君终身苦心也，不肖兄弟，将付杀青，公生生之意于天下万世，徼先生一言为重。余受而翻阅，见其认症必合色脉，问动止，聆音声，察饮食，投剂则按寒暑，因虚实，定君臣佐使之宜，协七方十剂之妙，诚可羽翼《素》、《难》、与《绪余》、《玄珠》并行于世，亦鼎足之奇也。天有生生之权，而生生子代之，天有生生之理，而生生子泄之，于以列天官何忝焉。今以春秋高不能跋涉，其季君济孺甫绍明其家学于荆，荆之老稚，生死而骨肉，医济孺是赖，是生生之机相禅于不穷矣。余雅重其人，掇拾三书大旨，独详相火之论，弁于简端，以发明其生生之心云。", "6259": "穆叔称三不朽曰：太上立德，其次立功，其次立言。其论固矣。尝试思之，则有说焉！夐乎太上不可及也；其所谓次者，岂必勋树国家，伐勒彝鼎而后谓功，有能起疲癃,泽苍生,即功也。岂必典谟训诸，定保明征而后谓言。阐理窾，觉来兹，即言也。析之二而究之一也。何也？夫底迹之谓功，举其迹而纪之册，功亦言也。修词之谓言，据其辞而措之行，言亦功也。庸讵知功不可为言，言不可为功乎！孔门弟子独颜闵以善言德行称。亦以得于心而见之行，此非功与言合一之征乎！孙文垣氏，习儒骎骎有俊声矣。以尊人病痹，乃徙孔孟而肄轩岐。从事之始，即念业不以出乎众为心，曷时能出乎众哉。众，医众矣，吾不原从众而卑卑执方为也，彼丈人之承蜩，若掇之者，何以故？专一故也。于是坠肢体黜聪明，解心释神而大同乎溟滓，用能妙契《素》、《灵》，机洽仓、扁，不而张、李、王、朱之属，靡不咀英猎华而融会其神髓，因以得于心者运之治，察脉辨症，辍应手而奏奇功，声名郁勃起吴越间矣！已出独见而著《医旨》，辑试方而成《玄珠》，命门有图，相火有辨，三焦包络有说，十二经名义无不精详，发群贤未有之论，破千古未决之疑，治言述之古，不为袭旧，治法酌之己，不为师心。江左之显贵隐约，闾右穷檐，繄惟文垣是赖。此之为功，直一手一足之烈哉！所全治者多矣。不可不谓之功。今兹复从诸缙绅文学之请，以历验之成案板之，与《医旨》、《玄珠》并行于世。三书言皆凿凿可法，谓之立言溢美矣！夫以治之奇中者，成之案，缘其著之论者，施之行。功言立矣。即未能望太上之阃奥，谓之尚德哉，若人非耶，文垣其亦可以不朽哉！余故知其心于济人。而又嘉其志于公物，用次数言，以弁之首云。", "6260": "孙长公东宿先生，早业医名，江以南邑国，逢迎结辙相望。长公尝为《医旨绪余》数十卷，悬之国门，已考前言、搜往牒，为《赤水玄珠》数百卷，递行于世，医家者便焉。而长公意不但已。太史公之传仓公卢扁也，于病者主名症候脉理药物详焉，盖其重哉！由今而考之，则病不必雠脉，药不必雠病，方亦不必雠药，岂古今运气之异，南北风土之殊，其碍戾而赅格者，然乎哉！不佞早业医、日治病，拊脉之息以踵也，㕮咀之精以养也，毋敢妄庸而轻自用，问切则精神通病者，佐使则损益准先民。语功效，毋能居十全；语诖误，毋敢措一失。乃今逾耆而指使老矣，概其生平而毕藉之，其人可考而原，其脉可按而覆，其方可悉而数。民命亦大矣！岂嫌伐一时事，不以告后人而失当世。嗟乎！长公之用心良勤且笃矣！夫医家上轩岐而下四氏，比之儒术，六经百家，其难均倍，业者纷如，祗事剽窃，甚或师心自信，倍古昔而托无能，其不及于殆者几希？何所病之病不征也，病之于症，那刹变化，日久与病俱，而后无病病，视病以药用，而后无药药。故伛立而白首在门，貌荣而却视反走，彼其按图而坐索，执方而莽求，其不及于殆者几希。何所病之病不习也。长公故由儒徙医，轩岐四氏之书，穷二酉而彻千古，章栉句比，意契心通。足则吾能征之，殆无间然。舞象而医，手之拊人脉，多于握匕箸㕮咀之积，若丘陵然，以病病者霍然已，以不病者霍然已，不习无不利，于长公何多耶！余常从长公从子元素叙医旨以绪余，而多其谦德，乃今所籍则成案矣。语有之，医者意也，得意者亡法，案于何有？夫匠氏规矩，宫室所先，渔猎签蹄，鱼兔是获，夫非所可案者哉！关睢麟趾之意，周官攸行，皆此类耳！是案行，讵惟长公之功医家，与诸医家之功天下者，俱不浅也。不习为吏，视已成事，殆谓是乎。元素跃然曰：余从父之核案也，不知者以为任德施也，知者以为博名高也。知言哉，生生之心为养生主，吾子得之矣。乃属剞劂，载之首简，以布海内。", "6261": "族叔生生，抉《灵》、《素》之秘，挟其术而周游江左，治辄奇中，声称郁勃起吴越间，揆厥由，盖临症殚思，务以己之精神，通于患者之精神，对病投剂，匪苟然尝试漫为也。即举册而笔其症脉治法，以为后之参考，计积三十余年案牣箧笥，诸缙绅往往欲授梓人以公天下，叔顾自视焰然不欲自炫，而西吴见所公屡书督成之。谓：君昭彻理奥，熔铸古今，著论可羽翼轩岐而觉后学，仁者以博爱为公，君生平仁心为质，而亟济人，布其法之己试者，传之后，所济不尤奢乎。若梓工，余则捐俸任之，无预君也。不佞烨，因从旁赞之曰：古人成一家言类，藏之名山，以托不朽，叔于载籍未有之病机，与众人望之而却走者，皆得手应心起之，即以天下后世为藏室，何不可者。奈何硁硁乎持己见，而重违诸荐绅之请也。春秋且逾耆，河清难俟，与其徒著之册而托之空言，孰若身亲见人习而见诸行事者之为实哉！叔始因余言而翻然首肯，乃其二子泰来、朋来，欣欣色喜云：此不肖兄弟子职所当尽者，曷敢琐琐溷潘大夫暨诸公。为用肤箧仅得十之二三，以付剞劂，不佞获从事校阅，作而言曰：尝读史司马子长传太仓令高矣，第叙其察病之精，而治法未详。近诸名公，传世医文，接子长之统古矣，而论症与治，似有差池。今生生子所记历验之案，色脉病形，较若指掌，缘病立方，确如金石，修词或未入二公之室，乃成案则凿凿乎补前贤之未备，为后来之金针也。世之从事此业者，服而习之，其有益于民生，非渺小矣。叔亦可托之不朽哉！不佞次其锓梓之由如此，观者谂之。", "6262": "生生子曰：医案者何？盖诊治有成效，剂有成法，因纪之于册，俾人人可据而用之。如老吏断狱，爰书一定，而不可移易也。医家有案伙矣，或寂寥数语而法不备，或盘悦其辞，而于治法无当。何案之与有？尝窃慨焉！余兹举生平所偶中者笔之，著其症，详其脉，备述其治法，与药之君臣佐使，令之寒暑温凉，色之青红黑白，悉次而毕录者，固以识余临病不苟，投剂不妄，以一得之愚，就正有道。亦以俾我后人工是业者，一展卷间，较若指掌，可寻而从事矣。此予之意也，观者谂之。", "6263": "盖士君子有济世之心者，必托经世之术以运之，遇不遇无论也。何也？得时而驾，则宇内之休戚利害，隐然共之，视其患若切于身之疾痛疴痒，不措之安全不止。此士君子之心，得位以行之者也。不幸不获遇，泽不及物，而心不得施，有志君子，往往怀其道而隐于医。故是昔人谓济人利物，无位者不能，惟医以救死扶生为功，故业之者，可以推不忍之心及于物，而于道有益。有味乎其言之也。然医岂易言哉？吾闻其宗旨，自《内经》、本草以来，书之藏于有司者，一百七十九家。非博通巨儒，超悟上哲，颛攻其业，何能探讨，洞明其阴阳、寒热、静躁、虚实，消息盈缩之奥，而措之行事。夫人之待命于医，生死攸系，乃以未诰浅薄者尝试之，其不贼人之命者几希。医以济人，至于贼人，可不畏耶！此医之所以难言也。余顷多病，谒告山居，尝叹济物之衷未措于用。顾思延医以求济其身。然而医之良者，苦不一遇也。乃壬申秋仲，吴君柳溪，谈新安海阳有孙君东宿者，医可谓称良矣。余亟请而相印证之，耳其论沨沨乎《素》、《难》之旨，而表里夫张、刘、孙、李、丹溪、伯仁诸家，其视余疾也，未投药，先谈余之经络、色脉、机能，与受病之自，即勿药而余病爽然若失。及详察其端方之度，沉著之思，渊渊之阃奥，则杳焉莫竟其涯。非所谓深于道而隐于医者耶！余因诘之曰：神农尝百草，先天而命之药，黄帝、岐伯，后天而著之经。此天以神授，圣以神符，不可及矣。嗣后若和、扁、华佗、淳于意、仲景、思邈、河间、东垣、朱、滑，莫不簸弄化机，制人命于掌上，术亦神也。何今日之事是业者，不能踵其芳躅耶！抑世代之不同也？孙君勃然曰：古今人非不相及，用心殊尔。宋儒有言，古之仕者为人，今之仕者为己。不佞亦谓古之医者为人，今之医者为己，道不同而受病一也。夫士君子之视天下，与吾身血脉相流通，天下病，若痌瘝之切身，天下安，则惬然而无恨。虽以道为药石者，其济宏，以医为道术者，其济狭，其心一也。故古之医也，以救死扶生为心，其业专而用方也慎。专则精而造诣入室，慎则审而投药奏功。此和、扁诸名家，所以悉臻秘妙，称神奇。今之医，则异是也。将以市利，非以济人。黄、岐以来诸书，非不剽窃以资口说，乃其心则实胡越一膜，视天下，率以利之盈诎，为心之重轻。人之济与否，若与吾术不相关，此何以比古人而接其芳躅哉。不佞奎，何能造古贤哲之阃奥，第无愧于此心尔。余闻而喟然叹曰：孙君充是心而行是术，其将大有裨于时矣！虽隐而亦显也。因次其语而归之，爰以订夫业是术者，是为序。", "6264": "万历龙飞二年小春月，予始游苕之东双林。于时，族兄吉泉之友吴小峰，与其弟小川俱病目，专科者愈治愈重，其目始红肿，次加太阳痛，继则白星翳叠出。予不以目科名，而识者称予大方，因谋于吉泉曰：医以通变为良，昔秦越人过邯郸，闻贵妇人，则为带下医。过雒阳，闻周人爱老人，则为耳目痹医。闻东宿君国手也，必能随俗为变，愿一言去吾兄弟目疾。吉泉邀予，余曰：嘉靖间论医者，必首西吴，如周仲仁氏，凌汉章氏，王宾湖氏者，皆擅一时名，其家世必有传也，何需于予。吉泉曰：渠家慕弟久矣，且其尊人受博士易，为西吴名家，弟好易，幸一往，借此为谈易地，毋逊。胗其脉。小峰之脉，濡而缓大，两目血缕直贯瞳人，薄暮则疼。小川之脉，皆洪大鼓指，黑珠有浮翳瘼，隐涩难开，大小便皆不利。故于小峰用补，先以清肝散与之。夏枯草五钱，香附四钱，甘草一钱五分，细茶五分，以撤其痛。药两进而痛止。继用人参、白茯苓、熟地黄、枸杞子、桂心、牛膝、破故纸、白蒺藜、牡丹皮。服八日而愈。于小川用泻，内用泻肝汤，及当归龙荟丸。外用象牙、冰片为末点之，七日痊愈。其尊君我峰翁喜诣予曰：二目均病，年同齿，染同时，诸医同治而同不愈，先生一补一泻，而二病均愈，何哉？余曰：此阴阳虚实之辨也。经云：实者正治，虚者从治。令侄之症，惟厥阴肝火炽盛，肝尝有余，有余者泻之，正治也。郎君下虚，又为怒所激，怒则火起于肝，肝为藏血之地，故血丝贯瞳人，而薄暮作痛，方用夏枯草、香附为君，疏其肝气。经云：肝苦急，急食甘以缓之。故用甘草为臣，茶能清头目，用以为使，先为去此痛。经又云：水流湿，火就燥。故复用甘温补其下元之虚，俾火得归原，此从治也。若用苦寒降火之剂，不惟血凝而痛加，抑且激其火而使愈炽矣。我峰闻之，语人曰：孙君本阴阳而治寒热，是用易为医也。故补者补效，攻者攻效。语曰：不知易者，不可以为太医。孙君神于易而于医乎何有，愿于吾苕悬一壶也。余哂之，谓：昔韩伯休且不欲人间知其名，余又何壶之可悬哉。（一）", "6265": "万历甲戌，其年自仲秋祖冬，瘄子盛行。三月内，予所治男妇婴孩共七十二人，苕之望族沈最著，大中丞观颐公当考功时，幼君瘄，喘嗽不宁，声哑，发热，泄泻，斑紫不敛。予以小无比散愈之。夫人妊，腹痛昏厥者五日，名医如高、陈二公者，沈姻姬，无巨细悉任之，亦不能措手。予至诊之，两手脉皆洪大，法当下，众佥以妊难之。予曰：经云：有故无殒，亦无殒也。妊已九月，将解，即胎动奚伤。若当下不下，不独其痛难忍，而变且不测。考功是予言而请药，予即用小承气汤加苏梗、砂仁，下之而安。考功偶冒风，头痛倦怠，发寒热如疟，脉浮弦而数。予曰：此小柴胡汤症也，一剂而瘥。考功请告家居者二十年，笃好方书，予初之苕，苕人未知予，考功闻予，亟欲识之，谓予治病甚奇，又与予论伤寒痘疹胎产皆中窾，深然之。语人曰：良相良医等尔，如孙君所诣，即千金不足为其重，特撰医说书于册，以不朽孙君云。（二）张孝廉后渠，丁年，患大头疫。头大如斗，不见项，唇垂及乳，色如紫肝，昏愦不知人事。见者骇而走。其年疫甚疠，人畏传染，致废吊庆。张与考功公子，同受春秋于会稽陶春源所，陶邀予诊之。其脉皆浮弦而数，初以柴胡一两，黄苓、玄参各三钱，薄荷、连翘、葛根各二钱，甘草一钱。服三剂，寒热退，弦脉减，但洪大。予知其传于阳明也。改以贯众一两，葛根、天花粉各三钱，甘草一钱，黑豆四十九粒。一剂，肿消其半，再剂，全消。浆粒不入口者二十一日，再与小柴胡汤，两剂服之，始纳干糕如指者两条，次日进粥，而渐平矣。丁酉秋闱报捷。（三）", "6266": "吴江孙质庵老先生行人，时患痛风，两手自肩颙及曲池，以至手梢，两足自膝及跟尻，肿痛更甚，痛处热，饮食少，请告南还，而伏蓐者三年。里有吴君九宜者，沈考功西席也。见予起后渠疾，因语行人逆予。诊其脉，皆弦细而数，面青肌瘦，大小腿肉皆削。予与言：此病得之禀气弱，下虚多内，以伤其阴也。在燕地又多寒。经云：气主煦之，血主濡之。今阴血虚，则筋失养，故营不营于中；气为寒束，百骸拘挛，故卫不卫于外。营卫不行，故肢节肿而痛，痛而热，病名周痹是也。治当养血舒筋，疏湿润燥，使经络通畅，则肿消热退，而痛止矣。痛止，即以大补阴血之剂实其下元，则腿肉复生，稍愈之后，愿加珍重，年余始可出户。行人闻而喜曰：果如公言，是起白骨而肉之也。吾即未药，病似半去，惟公命剂。予先以五加皮、苍术、黄柏、苍耳子、当归、红花、苡仁、羌活、防风、秦艽、紫荆皮。服之二十剂，而筋渐舒，肿渐消，痛减大半。更以生地、龟板、牛膝、苍术、黄柏、晚蚕沙、苍耳子、苡仁、海桐皮、当归、秦艽，三十剂而肿痛全减。行人公益喜。予曰：病加于小愈，公下元虚惫，非岁月不能充实。古谓难足而易败者，阴也。须痛戒酒色，自培根本，斯饮药有效，而沉疴可除。据公六脉轻清流利，官必腰金，愿藻真以俟之，万毋自轻，来春气和，可北上也。乃用仙茅为君，枸杞子、牛膝、鹿角胶、虎骨、人参为臣，熟地黄、黄柏、晚蚕沙、茯苓、苍耳子为佐，桂心、秦艽、泽泻为使，蜜丸服，百日腿肉长完，精神复旧。又喜语予曰：贫官何以称报，撰次公济人泽物盛德于沈考功册后，以彰盛美云。后十年，行人官至江西副宪。（四）", "6267": "张文学子心，二尹可泉公长君也。自知医，弱冠病，吴下名医皆诊之，佥曰瘵，治久不效。子心亦自分必死，督家人具秘器，己沐浴，衣襚衣而卧正寝，断粒、绝药者二日。可泉闻予治其高第张星岳之婶奇，因访予曰：病心痹而尸寝浃旬者能起之，谁不啧啧称公高手，吾子病且革，幸怜而诊之。予至，诊其脉，左寸短弱，右关略弦，余皆洪大。其症咳嗽，下午热从两足心起，渐至头面，夜半乃退，而色青，形羸气促，多梦遗，交睫卧床褥奄奄一息耳。时则七月初旬也。诊毕，语可泉公曰：郎君病可治，不宜豫凶器也。可泉公曰：诸医佥谓火起九泉者，十不救一，大肉尽削者死，咳嗽加汗者死，脉不为汗衰者死，又当此铄石流金之候，又恐肺金将绝。豚子亦自谓无生理，先生何言可治也。予曰：汗多者，孤阳几于飞越也。可泉公曰：飞越亦死候也。予曰：几者，将成未成之辞也。症虽危，其色、其声音、其脉，尚有生意。终不可以一凶而废三善。两颧不赤，心火未焚也。声音不哑，肺金未痿也。耳轮不焦，肾水未涸也。相书云：面青者，忧疑不决，左寸短者，心神不足，关略弦者，谋为不遂。夫心者，万事万化之主，《内经》曰：主明则下安，主不明则十二官危。又肝主谋为，胆主决断。谋为不决，故色青。症与色与脉皆非瘵也。盖郎君志愿高而不遂其欲，殆心病，非肾病也。经曰：色脉相得者生。予故谓郎君之病可起也。病者闻言，明目语其父曰：吾今犹寐者初寐矣！从来未有此论沁吾心脾也。吾病由星士许决科于癸酉，是年予落第，而同窗者中，故怏怏至此。先生得吾心于色脉，神矣！此言可当药石，谨拜命。予为定方，煎方名调肝益神汤。以人参、酸枣仁、龙骨为君，丹参、石斛、贝母、麦冬、五味子为臣，山栀、香附为佐，服二十帖而病起。丸方则大龟板、熟地黄、枸杞子、人参、麦冬、五味、茯苓，蜜丸，服三月而精神健，肌肉完。次年生女。可泉公，苕中名士，奇予治，而延誉闻于大宗伯董浔阳公，宗伯交欢余者，由可泉公始也。（六）", "6268": "大宗伯董浔老，年六十七，有脾胃疾，翁以过啖瓜果而胸膈胀痛，时当处暑也。延予治。诊其脉，寸关弦紧，观其色，神藏气固。翁门下蒋虹桥、沈乐闲者，多艺人也，翁素亲信二公，诘予曰：症脉何如？予曰：症脉虽胸腹胀痛，然易瘳也。二公曰：翁生平不能素食，食辍泻，今不茹荤者半月，燕居好奕，好看书，好作诗文，即盛暑亦手一编不言倦，日永亦不瞌，今不亲笔砚者月余，不栉沐者七日，它一切无所事事，倦极矣。诸名家如沈竹亭、沈春宇、金樗丘者，剂备尝之无益也。而公何言易？予曰：诸公不过用二陈平胃，加山楂、麦芽等消导剂耳，与症何涉。盖翁伤于瓜果，而为寒湿淫胜。经云：寒淫所胜，治以辛温。然瓜果非麝香、肉桂不能消，此诸公所以不能愈翁疾也。予以高良姜、香附各一两为君，肉桂五钱为臣，麝香一钱为佐，每服二钱，酒调下之。药入腹，胸次便宽，再而知饿，三服而巾栉，交接宾客如未病者。翁语沈、蒋曰：孙君所见所养，度越诸人若是。往闻治张氏子，气绝两日而能活之，今于活吾病益信，诚临菑虢国之遗，特书一轴以彰其高，因以纪一时之良遇云。（七）", "6269": "大宗伯郎君董龙山公夫人，为宪副茅鹿门公女，年三十五而病便血，日二三下，腹不疼，诸医诊治者三年不效。予诊之，左脉沉涩，右脉漏出关外，诊不应病。予窃谓，血既久下，且当益其气而升提之，以探其症。乃用补中益气汤，加阿胶、地榆、侧柏叶，服八剂，血不下者半月。彼自喜病愈矣。偶因劳而血复下，因索前药。予语龙山公曰：夫人之病，必有瘀血积于经隧，前药因右脉漏关难凭，故以升提兼补兼涩者，以探虚实耳。今得病情，法当下而除其根也。龙山公曰：三年间便血，虽一日二三下，而月汛之期不爽，每行且五日，如此尚有瘀血停蓄耶！予曰：此予因其日下月至而知其必有瘀血停蓄也。经云：不塞不流，不行不止。今之瘀，实由塞之行也，不可再涩。古人治痢，必先下之，亦此意也。公曰：明日试卜之。予曰：卜以决疑，不疑何卜。公随以语夫人，夫人曰：孙先生非误人者，识见往往出寻常，宜惟命。盖夫人读书能文，聪明谋断，不啻丈夫，故言下便能了悟。即用桃仁承气汤，加丹参、五灵脂、荷叶蒂，水煎，夜服之，五更下黑瘀血半桶，其日血竟不来，复令人索下药。予曰：姑以理脾药养之，病根已动，俟五日而再下未晚也。至期复用下剂，又下黑瘀如前者半，继以补中益气汤、参苓白术散，调理痊愈。（八）", "6270": "大宗伯董浔老门下有马厨者。七月初旬病，病二十余日愈剧，而势甚獗。时宗伯对余奕正酣，而蒋虹桥、沈乐闲报曰：马厨危在旦夕。宗伯闻之，推枰叹息曰：吾命吾命！予叩其故，语曰：能厨者，不下二十人，独此厨适吾意，将恃之以怡晚节，今病不可起，奈何？予诘何病，翁顾蒋与沈曰：第详道其状。蒋、沈述其症，大发寒热，寒至不惮入灶，热至不惮下井，痢兼红白，日夜八十余行，腹痛，恶心，汗多，神气倦甚。究其脉，曰，脉不吉，下痢脉洪大者死，细微者生，今洪大逆也。予曰：痢固忌洪大，寒热亦非细微所宜，其中必有故。二公曰：幸一往决之。浔翁不可，谓何可以细人而劳长者。予曰：医寄人生死，何论巨细，矧事翁之人，犹不可坐视不救也。浔翁欣然握余手偕行，至宅后桥，余入门，同居数十家，皆执香拱立以伺。诊其脉，察其症，果如蒋、沈所言。其面色微红，汗淋淋下，予究病所由起，渠谓过客众，厨间燥热，食瓜果菱藕过多，晚又过饮御内，而寝于楼檐之下，次日即寒热复痛，因而下痢。虽得其病情，尚未融通一治法，因沉思之，不觉行至桥，而浔老犹立而俟予，见予无婉容，知病重，遂置不问，如前握余手而回，蒋、沈谓予可治否？予曰：侥幸先生宠灵，偶有一得，乃背水阵也。人参、白术、石膏、滑石各五钱，知母、炮姜各三钱，大附子、炙甘草各二钱，作一大剂煎之。蒋、沈将问予，浔翁即命近侍煎于其侧，不欲蒋、沈问也。熟则付饮之，饮讫即睡。老先生曰：服后何状为佳？予曰：倘得一睡，则阴阳始和，和则汗可敛，而寒热呕恶可止也。蒋、沈曰：闻已睡矣。明日巳刻，二公鼓掌来言，夜来痢减半，汗吐全无，脉亦敛矣。再用人参、石膏、白术、白芍药、滑石各三钱，炮姜、肉桂、知母各二钱，炙甘草、附子各一钱，服后疟止，痢又减半，饮食渐进，神气渐转。改用白芍药酒炒五钱，人参、白术、滑石各二钱，甘草、陈皮、炮姜、肉桂各一钱，三剂而痢全止，饮食加，渐就安矣。蒋、沈问曰：公寒热均投，此为何症？而剂何名也？予笑曰：此滑公所谓混沌汤也。浔老又问，予对曰：经云：夏伤于暑，秋必疟痢。白虎汤、益元散，皆解暑之剂。瓜果寒凉伤其中气，酒后御色，损其下元，附子理中汤，正所以温中补下者。《内经》又云：实者，邪气实也。故以白虎汤、益元散应之。虚者，正气虚也。故以理中汤应之。若以寒热均用为疑，而张仲景附子甘草泻心汤，既用大黄、黄连，又用干姜、附子，此何说哉！盖假对假，真对真也。浔翁跃然喜曰：先生惟是，故能起垂毙之人而生之，余诗册中临菑虢国之谈，非虚语矣。（九）", "6271": "吴江吴太仆长君肖峰令政，太宗伯董浔老次女也。患咳嗽，体倦，多汗，腹痛，呻吟不绝口者半月，吴江之医不效，访远近名最著者，如姑苏盛氏后湖，王氏后山，震泽沈氏竹亭，先后递治之而痛愈加。予适寓苕城，龙山公邀予乘快舡兼程而进，至则诊其脉，左手三五不调，右手沉弦，面色青而息甚微，腹中漉漉有声。予因问上年夏月曾病否？肖峰曰：曾头痛体多汗，动止无力，不能亲事，但不咳嗽，不腹痛。今五月初，病如上年，而市医谓伤风所致，用参苏饮表之，始咳嗽。沈为其清嗽，则加腹痛。王与盛谓通则不痛，以沉香滚痰丸下之，则势惫而不可支。予方殚思，谓此乃注夏病。仲景谓春夏剧，秋冬瘥者是也。而龙山公诘问：注夏何为咳嗽？予曰：原不咳嗽，由参苏饮而咳嗽也。汗多又重发汗，肺金受伤，故燥而嗽。何为腹痛？予曰：原不腹痛，因治嗽而寒其中气，腹故痛也。后事者，又不究其因寒而痛，乃谓通则不痛，而用寒凉滚痰之剂，重伤其中气，不思五月六阳之气皆散于外，汗而又汗，汗多则亡阳，夏至一阴将萌，腹中尚虚，虚而复下，下多则亡阴，阴阳俱亡，不惫何待。予欲酌一方以起之，恐从事者又将议其后。龙山促之，乃用酒炒白芍药五钱，甘草、黄耆各三钱，桂枝二钱，大枣二枚，水煎，临服加饴糖一合。吴下诸公，果群然又辩。龙山公曰：不必辩，病者望此以苏其生，速煎饮之。饮讫而睡，自巳至申不醒，先事者，皆摇首，命仆急携药囊将去，且语龙山公曰：夺令妹之速者，孙君也。《本草》云：夏不用桂，伐天和也。诸痛不补，助邪气也。故一饮而不醒，吾侪行矣。龙山公以其言语余，因诘病者之熟睡，予曰：所善者，以其睡也。睡则阴气生，阴生则汗可敛，痛可止也。假令药不对症，安得有此。又诘所投之剂何名，予曰：此仲景小建中汤也。出《金匮要略》。盖建者，立也，中者，阳明所主，今腹痛如缚，带脉急缩也，东垣治例，腹痛以芍药为君，恶寒而痛，加桂。甘草，缓带脉之急缩，用以为臣。经曰：急者缓之。面青脉弦，肝气盛也，肝属木，木盛则脾土受制，而又误下，因伤之极，故痛之猛也。经云：木得桂而枯。佐以黄耆，伐肝补脾，又能敛汗止痛，此建中之所由名也。语未竟，内报病者醒而索粥。予曰：与之，谷气进则有本矣。粥后又睡至天明，腹全不痛，惟稍咳嗽，加五味子、麦门冬，兼治注夏而全瘳焉。龙山公述病之始末，剂之药味，报大宗伯，宗伯公致书于予曰：足下以四味之常药，振不起之危疴，名震三吴，声溢两浙。昔宋景濂为朱丹溪立传，吾固不敏，幸先生以所治节条付之，俾序以传于后；俾工是术者，有所藉乎。予怃然语龙山公曰：何修而得老先生宠幸之深也。第令妹被克伐太过，阴阳俱亡，今病虽愈，而脉弦不退，犹可为虑，幸叮咛戒暴怒、节饮食，谢去人事，恬淡多补，庶可永年。不然亥月阴极阳生，恐不能保无患也，慎之慎之。后至期，与肖峰龃龉，怒而绝药，果以凶闻。苕人多予之直与先见云。（十）", "6272": "大光禄庞公子远，吴江人也。其太夫人病头痛恶寒，胸膈懑且痛，时发寒热，吴医工后山者，有时名，吴人最所笃信。延治五日不瘥。闻予居吴，礼致为治。诊其脉，右滑大，左浮弦而数，问服何剂？光禄公曰：不识，而有药在。予视之，偶失言曰：左矣！时有西席项姓者，闻言而厉声曰：此三吴最名士也。渠发剂而有议者，辄面唾之，幸不在尔。予笑曰：渠是而议者非，则当唾人，渠非而议者是，是自唾且不暇，何暇唾人。四物汤，玄胡索、牡丹皮、香附子，养血调经剂也。太夫人七十余矣，而有经可调哉！投剂之左，由生平守常套，而不知因人因症随俗为变也。项子曰：此何症？予曰：仲景有云，头痛恶寒，外感病也。浮弦而数，胸膈懑痛，少阳脉症俱在，右脉滑，饮食滞而为痰。彼用当归、地黄、芍药，皆滞痰闭气之味，内伤何由得消，外感何由得出。此症只宜用柴胡汤合平胃散，一二帖可瘳也。项犹有言，光禄公曰：勿辩，饮药而泾渭明矣。一饮而寒热除，再饮而胸膈泰。光禄喜曰：奇公名不虚附矣！予私问项子何极誉王，光禄曰：项初受业于王，未睹大方，而独是其师说，多见其识之不广也。（十一）", "6273": "光禄公后有事于庄所，值中秋，乘酒步月，失足一跌，扶起便胁痛不能立，昼夜不宁，行血散血活血之剂，一日三进，阅三月服二百余帖，痛不少减，因迎予治。诊之，脉左弦右滑数，予曰：此痰火症也。公曰：否，贱躯虽肥，生平未尝有痰，徒以遭跌，积血于胁间作痛尔。予曰：据脉，实痰火也，痰在经络间，不在肺，故不咳嗽，而亦不上出。脉书云：滑为痰，弦为饮。予据脉而认痰火。如瘀血，脉必沉伏，或芤或涩也，面色赤必带黄。前诸君以瘀血治者，皆徇公言，不以色脉为据。且多服峻厉克伐破坚之剂无效，此非瘀血之积明矣。公欣然请药，即用大栝蒌带壳者二枚，重二两，研碎，枳实、甘草、前胡各一钱，贝母二钱，与四帖，公以为少。予曰：愚见犹以为多，此症服此一二剂可瘳，又即报我，为制补益之药可也。公得药一更矣，仍煎服，五更腹中漉漉有声，天明大泻一二次，皆痰无血，痛减大半。再服又下痰数碗许，痛全止，随能挺立。三服，腹中不复有声，亦不泻，盖前由痰积泻也，今无痰故不泻。公曰：望闻问切四者，医之要务，人人皆著之口吻，有先生独见之行事，即予母子之疾，先有事者，皆吴之名流，微先生，吾殆撞壁矣！何能还辕而生哉，吾于是益服先生之高。（十二）", "6274": "进贤三尹张思轩公，与潘少保印川公，皆受室于施氏，称联襟云。施故富家，而张公夫人贤慧，治家勤笃，为人精洁周致，以产多而气血惫，又以婚嫁繁而费用不支，积忧，年将五十，因病心痹，发则晕厥，小水短涩，胸膈痛不可忍，烦躁干哕，恶内蒸热，气喷喷上腾，肌削骨立，月汛不止。苕城时辈，有认为气怯者，有认为隔食者，皆束手无措，尸寝浃旬，浆粒不入口者五日，凶具备而待毙，举家计无所之，惟神是祷。予适在潘府，逆予诊之，脉左弦大，右滑大而数。诊毕，予曰：可生也。《病机》云：诸逆吐酸，皆属于火；诸风掉眩，皆属于木。法当调肝清热，开郁安神。诸医群然目摄而背谑曰：书云骨蒸肉脱者死，形瘦脉大胸中多气者死，绝谷食者死。孙君独许其生，果药王再世哉。予若不闻，而捡药以进。竹茹、滑石各三钱，白豆蔻仁七分，半夏曲、橘红、姜、连、茯苓各一钱，甘草五分，水煎，令一口口咽之。服毕，哕止晕定。次日用温胆汤调辰砂益元散三钱，服之，胸膈顿开，渐进饮食，小水通长，烦躁尽减，骎骎然安若无事。后用逍遥散、六君子汤，加黄连、香附，三越月而肌肉全，精神如旧。苕人骇然曰：能起此病，信药王矣。（十三）", "6275": "马二尹迪庵公，年五十五，以扫墓而过食鳗肉卷饼，心腹胀痛，市医不知用吐，而遽用硝黄下之，大便不行，胀痛愈增。继至者，以用木香槟榔丸，继又有下以小承气汤者，有下以大承气汤者。十日多，胀痛益甚，饮食粒不能进，大便并不行，小水亦仅点滴。后医又以大黄、芒硝，多服不行。谓非白饼子不可，服五日，而胀痛尤加。又谓非备急丸不可，服三日，胀痛益不可当。又用甘遂、芫花、大戟、牵牛之属，服三日，不惟大便不行，并小便点滴亦无矣，胀不可言。众医大叫称怪。自三月初二日起，至是念二日矣。有名士王南野者，用灸法灸中脘三十余壮，毫不为动，因断其越三日为念五戌时，当弃人间。迪老四子皆逢掖，闻言涕泗。时有张太学怀赤者，迪老甥也，见予起张思轩夫人疾，喻亟请予。予至，观其色苍黑，神藏不露，声音亮，惟腹大如覆箕，不能反侧，诊其脉，两手皆滑大，两尺尤有力。究其受病之源，查其历服之药，予骇然以为未闻且见也。因思一治法，先用六君子汤，加木香、砂仁、参、术，俱用二钱。乃旁有钱小松者，自称家世受医，见剂争之。予曰：非若所知也。彼犹喋喋诘予，谓：人言中满者，泻之于内，大小便不利者，当先利大小便，然欤？予曰；非人言，《素问》云云也。又云：诸痛不得用参术，苍黑之人尤忌。先生既知《素问》，奈何不用通而用塞也？予愀然不答，顾迪老诸子言曰：钱君拘儒常见，何能起尊君病，尊君非中满胀症，内伤症也。当始伤时，犹在上膈，法当用吐，《素问》云：在上者，因而越之是也。不用吐而用下药，以伤其脾，脾气伤则失运动之职，是以愈下愈伤，愈伤愈胀。不思脾气伤而神不为用，药不能行，以峻厉味益下之，是遵何说也。予因脾伤，故用六君子汤以醒其脾，木香、砂仁助其运动，再用吐法，吐出前药，予剂非治尊君之病，治诸君药也。予初欲为诸君讳，何钱君激予，而使暴其短哉。且予不虑大便不行，独虑行之不止也。钱又谬言：急则治标，今法用尽不能使一行，何以不止为虑。予曰：君试思，常人能服硝黄几何，服巴豆、白饼子几何，今硝黄服过五斤，巴豆、白饼子之属服过五六两，又加甘遂、牵牛、芫花、大戟，至悍至急之剂，幸而大便未行，药性未动，尚可为计，若一行，而诸药性动，譬瓶水底漏，其中能蓄点滴哉，危矣！钱又诘：迪老多服下药，而大便不行何也？予曰：此易知之。始为食伤，继为药伤，所伤在上、中二焦，下元未损，故两尺脉尚有神气。《难经》曰：人有两尺，如树之有根也。《内经》曰：肾者，胃之关，盖肾主大便，观其色苍黑，神藏气固，皆由根本未动，赖此犹可为也。服药后，腹中大痛，予知其药力已动，改用人参芦、防风芦、升麻、桔梗各三钱，水煎服之，少顷，用鹅翎探喉中，令吐之。前服药物，一涌而出十数碗。病者以手加额曰：目前光矣。此巳时也。予曰：酉时大便必行，可预买人参数片，以备不虞，至午进至宝丹一帖，以温中气，未申间，腹中汩汩有声，浊气下滚，顷刻间，腹宽数寸。至晚，大便行一次，小水略通。予即用人参、白术各五钱，炮姜三钱，茯苓二钱，木香、甘草各五分，陈皮一钱，令急煎服。四鼓又大便一次，小水继至，胀痛渐减。次日大便泻十次余，因以前理中汤剂为丸，与煎剂兼补，腹胀全消，饮食渐进，共泻七十二日，服人参二斤余。苕人闻以补收功，群然异之。而钱小松始帖然心服。曰：奇哉！奇哉！人多用攻，孙君独用补，人多用下，孙君独用吐。由见之真，而所投者确也，医可易言哉。今而后，知孙君之高矣。（十四）", "6276": "舜田藏公，吴车驾涌澜公岳也，年将六旬，为人多怒多欲，胸膈否胀，饮食少，时医治以平胃散、枳术丸、香砂丸，不效。复以槟榔、三棱、莪术之类日消之，而大便溏泻，两足跟踝皆浮肿，渐及两手背，医又以其手足浮肿而认为黄胖者，以针砂丸与之，肿益加，面色黄且黑，自二月医至八月，身重不能动止，又有以水肿治者，车驾公雅善予，因延诊之，脉沉而濡弱，予曰：此气虚中满症也，法当温补兼升提，庶清阳升，则大便可实；浊阴降，则胸膈自宽。以人参、白术各三钱，炮姜、回阳、陈皮各一钱，茯苓、黄耆各二钱，泽泻、升麻、肉桂、苍术、防风各七分，三十帖而安。客有疑而诘予曰：此症，诸家非消导则淡渗，而先生独以温补收功，腹中积而为满为肿者，从何道而去也。予曰：胀满非肿满比也，故治不同。肿满由脾虚不能摄水，水渗皮肤，遍身光肿，今胀满者，先因中虚，以致皮胀，外坚中空，腹皮胀紧象鼓，故俗名鼓胀。盖由气虚以成中满，若气不虚，何中满之有，气虚为本，中满为标，是以治先温补，使脾气健运，则清浊始分，清浊分而胀斯愈也。（十七）", "6277": "金溪令净涵臧公尊堂太夫人，以季春眉寿，连看戏文二十余本，且多食鱼腥虾蟹，偶发寒热，三日不退，第四日，左耳前后及颊车皆红肿，第五日，右边亦肿，第六日，肿及满头，红大如斗，眼合无缝，昏愦不知人事，谵语若有邪祟，粒米不进者八日，举家惊惶，逆予为治。诊其脉六部皆洪长而数，予曰：此大头疫也。即以贯众、石膏各六钱，柴胡、葛根各三钱，赤芍药、天花粉各二钱，甘草一钱，黑豆四十九粒，水煎服之，日进二帖，脉始减半。第九日，方进粥饮半盅。前药除石膏，又四帖而安。是役也，人皆为予危之，谓八十之尊年，八日之绝粒，头大如斗，体热如燔炭，昏愦谵语，乃不去而治，何冥行不知止如此。而其婿闵怀海亦言病势如此，吾心亦危疑，见先生安闲而甘寝食，赖以少慰。予曰：此疾为阳明少阳二经热壅而然，夫阳明多气多血之经也，以高年故不敢用硝黄，惟投以轻清解散之剂，使因微汗而解。症脉相对，虽重可生。假如人言以高年病危而弃不治，岂惟非医之存心，于病家相托之意亦孤矣，可乎哉。（十八）", "6278": "丙申夏，见所潘公谒予于海阳邑邸，时霪浃旬，邑市水涨，公至，予惊问曰：公贵倨也者，何甚此？公曰：与君间者阔矣，且先君服阕，秋当北上，不卜补任南下，谒求一诊，他何计。予究何疾，公曰：无，第年甫逾疆，微觉阳萎。次早诊毕，语其随行俞金二字曰：公脉上盛下虚，上盛为痰与火，下虚为精元弱，切宜戒色慎怒，剂宜清上补下，不然，三年内恐中风不免。盖由痰生热，热生风也，谨之识之，乃为立方别去，公亦未暇制服。公次年八月，往返武林，不无劳怒，又届中秋，连宵酒色，平常色后，辍用鹿角胶三钱，人参一钱，酒送下。以连宵有犯，乃用鹿角胶五钱，人参三钱，空心服之，十七日薄暮，偶与社友谈诗，筵间，左手陡然颤动，把捉不住，随归房，左手重不能举，十八日早，左边半体手足皆不为用矣，亟令人逆予，予适在前丘吴宅，及至，公惊喜交集曰：君何先见若此也，先少保患在左体不遂者，三年而殁，不佞今亦左体，其风水致然欤！第先少保年七十余，不佞四十有七，先少保不能遇先生，不佞赖有先生，或可企无恙也。予始观面色赤，口微㖞向右，唇麻，手足軃拽，已成瘫痪。诊其脉左弦大，右滑大。先用乌药顺气散一帖，服后昏睡半日，醒觉面更加赤，㖞也稍加，知痰盛使然。即以二陈汤加全蝎、僵蚕、天麻、黄芩、石菖蒲、红花、秦艽，水煎。临服加竹沥一小酒杯，生姜汁五茶匙，一日两进，晚更与活络丹。服至第六日，手指梢头略能运动，足可倚棹而立。予喜曰：机动矣！改用归芍六君子汤，加红花、钩藤、天麻、竹沥、姜汁，服二十帖，行可二十步矣，手指先麻木不知痛痒，至是能执物。继用天麻丸，兼服全鹿丸，调理百日，病去十之九。次年二月，北上补任永清，公以病后，能戒色断酒，自知培养，故药功获奏。此症予历治历效者，良由先为疏通经络，活血调气，然后以补剂收功。惟经络疏通，宿痰磨去，新痰不生，何疾不瘳。此治类中风之法也。（十九）", "6279": "见所公弱冠，随尊君大司马印老治河居北。患白浊，精淫淫下，自北地山东、淮杨、镇江及江右三吴诸名家，医药三年不效。癸酉冬，礼予诊之。其脉两寸短弱，两关滑，两尺洪滑，观其人襟期潇洒出尘，而神色闲雅，真翩翩佳公子也。一接见，便就暱而信余请药。予曰：公疾易愈，第待来春之仲，一剂可瘳，而今时不可。公固请曰：先生大方，而善拯人之急。以大方而治小疾，试可立效，何待来年。予曰：非秘其术不售也。《素问》有云：升降浮沉必顺之。又曰：天时不可伐。公脉为湿痰下流症也。经曰：治痰必先理气。而脉书亦谓，洪大而见于尺部者，阳乘于阴也。法当从阴引阳，今冬令为闭藏之候，冬之闭藏，实为来春发生根本，天人一理。若不顾天时而强用升提之法，是逆天时而泄元气，根本既竭，来春何以发生。故《素问》曰，必先岁气，毋伐天和，必养必和，待其来复。公疾本小，而历治三年不效者，良由诸医不知脉、不识病、不按时也。公闻言唯唯。乃尊君所遣之医踵接，治竟无效，至春分而逆予。以白螺蛳壳火煅四两为君，牡蛎二两为臣，半夏、葛根、柴胡、苦参各一两为佐，黄柏一两为使，面糊为丸，名曰端本丸。令早晚服之，不终剂而全愈。公复书曰：贱疾果如先生言，今勿药也，何历治三年不效。窃谓天下无药，服端本丸而愈。又信天下有药矣。（二十）", "6280": "少司空凌绎老夫人蒋，适绎老无几，腹胀痛，发热，经过期不行者五日。诸医皆以经期作痛，为调经不效。而绎老召予诊，左寸洪滑，两尺皆滑数，左尺之外，更有神气。予喜而语绎老曰：经闭非病，孕也，产必男。绎老雅信予，因究其说。予曰：滑非经闭之脉，左尺尤有神气，是以知产必男也。绎老谓：果孕矣，奈发热腹痛何？予曰：何伤，气虚血热耳。以安胎饮加减调理即安也。用人参、白术、白芍药为君，川芎、当归为臣，香附、柴胡、苏梗、条芩、甘草为佐，四帖，腹痛减热除。至期果生子。绎老德予，而多推毂云。（二十一）", "6281": "金文学元岩之眷，产后两日，腹痛，下痢纯红，肠鸣三越月，时当孟秋，两脉皆软弱，用佛手散加减以治，川芎三钱，当归五钱，艾叶、炮姜各一钱，桂心五分，酒炒白芍药二钱，连进三帖，而疾减半。后因食新菱、新栗，又连为怒气所激，日晡晕厥，以生姜汤灌苏，腹胁大痛，手不可近，用二陈汤加香附、砂仁、桂皮、炮姜与之，痛亦不减。且胸膈胀甚。自以手探喉中，吐出菱栗，痛稍定。少顷复痛，又用手探吐，吐后泻三四次，而元气脱矣。脉皆散乱如解索状，神气惫而恍惚，循衣摸床，病势危急。用人参、白术各五钱，酒炒白芍药二钱，砂仁、炮姜、肉桂、甘草各一钱，急煎进之，痛乃稍定，精神清，仍泻二次，次日复进药，痛减泻止。加白术又四帖，而饮食进，精神勃勃兴起矣。此因初痢时，医者不以产后为重，徒以治痢苦寒之剂伤其中气，又为菱栗生冷所损，中气益坏然也，治可不慎哉。（二十二）", "6282": "沈三石别驾公夫人严，产三日而腹不畅，南浔女科陈姓者，为下之，大泻五六次，遂发热恶心，又用温胆汤止吐，小柴胡退热，服四日，热吐四日，粒米不进亦四日，又进八珍汤加童便，服后昏愦，耳聋，眼合，口渴，肠鸣，眼胞上下及手足背皆有虚浮。因逆予治。诊其六脉皆数，时五月初二日也。予曰：脉书云：数脉所主，其邪为热，其症为虚，法当以十全大补汤加炮姜进之。夜半稍清爽，进粥一盂，始开目言语，次日午时，以承值者倦而药不相接，且言语太多，复昏昧不知人事。初四日，以人参、白术各三钱，炮姜、茯苓、陈皮各一钱，甘草五分，煎服讫，体微汗，遍身痱痤，热退而神爽。下午又药不接，又动怒，昏昧复如前，六脉散乱无伦，状如解索，痱痤没而虚极矣。亟以人参、白术各五钱，炙甘草、炮姜、大附子各一钱，连进二帖。是夜熟寝，唯呼吸之息尚促，初六日，脉又数，下午发热不退，环跳穴边发一毒如碗大，红肿微痛，夫人父严翁，与陈女科交谮之，曰：向之发热恶心，皆此所致，由附子、干姜温补误也。须急用寒凉解毒之剂，予正色而谕以理曰：此乃胃中虚火游行无制，大虚之症，非毒也，若作毒治而用寒凉，速其死尔。《内经》云：壮者气行则愈，怯者著而成病。惟大补庶可万全。三石翁然予言，急煎附子理中汤进之，日夕两帖，参、术皆用七钱，服后痱痤复出，毒散无踪，热亦退，沾沾喜矣。复以参苓白术散调理而全安。皆由产后误用下药，致变百出。噫唏！彼不达变之专科，其可任哉。（二十三）", "6283": "诰封吴太夫人者，车驾涌澜公母也。年余六十，久患白带，历治不效，变为白崩。逆予治之。诊得右寸滑，左寸短弱，两关濡，两尺皆软弱。予曰：据脉，心肾俱不足，而中焦不湿。《脉经》云：崩中日久为白带，漏下多时骨木枯。今白物下多，气血日败，法当燥脾，兼补心肾。以既济丹补其心肾，以断下丸燥中宫之湿，则万全矣。服果不终剂而愈。", "6284": "吴北海太学令政，每月经行期之前，四肢累累发块，红紫胀痛，不思饮食，胃脘亦常痛，经水多不及期，诊其脉两手皆驶，以症脉参之，肝脾二经有郁火也。盖肝主怒、脾主思，多思多怒，隐而不发，郁滞于中，故临经累累发红肿于四肢也。以柴胡、川芎、香附、乌药、白芍药、青皮、丹参、玄胡索、郁金、酒炒黄连、山栀子，治之而愈。（二十五）", "6285": "吴之清客周皱玉者，豪放不拘，人言有晋人风，酒后益恣而好男色，因患白浊。吴医有以补中益气汤升提者，有以六味地黄丸补阴者，有以五苓散、六一散渗利者，有为降火者，有力温补者，不效。又以草头药乱进之，肌瘦如削，膝软如痿，患有年所矣。因绍介吴太学北海而谒余，恳为治之。诊其脉右寸关皆数。予曰：皆由酒后不检所致也，中宫多湿多痰，积而为热，流于下部，故浊物淫淫而下，久不愈矣。与以加味端本丸服之而瘥。白螺蛳四两，牡蛎、苦参、葛根、黄柏各二两，陈皮、半夏、茯苓各一两，甘草五钱，面糊为丸，令早晚白汤下三钱。（二十六）", "6286": "丁酉夏，予寓雉城顾乡宦宅。其门下竹匠妇，怀妊五月而患心痛。究其所由起，谓由失足坠楼也。始教饮韭菜汁一盏，而痛随止，其夫又从它医赎药二帖归，令煎服。服既，心复痛，吐鲜血盈盆，胸间忡忡上抵，疼不可言，危在顷刻。竹匠告急予仆孙安，安怜之，恳予诊治。六脉皆洪大，汗出如雨，喘息不相续，其妇楼居低小，予令亟移居楼下，随与益元散五钱，令用紫苏汤调服，又嘱之曰：今夜若睡，听其自醒，切勿惊动，汗止即苏也。服后果睡到晓，汗敛而胸膈不痛，喘息亦定，再与固胎饮一帖，煎服而全安矣。先是邻医诊其脉，谓吐血之脉宜沉细，今反洪大，而汗出喘息不休，危在今夜，及病起来，询余曰：妊妇不得汗、不得下、不得利小便，是谓三禁。昨日之剂悉犯之，而反获效，何哉？予曰：医贵审症，盖妇之患，非由病汗，以楼居低小，当酷暑而热逼故也。汗血去而胎失养，故忡忡上抵，喘息不续。移楼下以避暑气，益元散为解暑之圣药，而紫苏又安胎下气之妙品，气下则血归原而病痊矣。此对症之乐，法出王海藏《医垒元戎》中四血饮是也。特诸君检阅不遍，即检阅亦不知为胎产之治。余何能，不过融会前人之法，用之而不胶焉耳。邻医俯首，唯唯而退。（二十七）", "6287": "壬申秋仲，予东游槜李，而王松泉、吴小峰偕行。小峰语予：中秋至矣，此间一妓李姓者，行第七，殊可人意，须访之。晚令佐酒，至则见其态度果淡雅风致，坐少顷，连咳两声，少峰究其病曰：偶耳。小峰谓毋诳，孙公知人生死，不啻扁鹊，可求一诊。诊之，两寸短涩，两尺洪滑，关弦，予未语，而小峰问脉，予曰：脉甚怪，公可问经行否？曰：行仅一日，亦仅点滴。予曰：此脉在良家主梦遗，若不宜有也。妓曰：良然，即御客时亦或遗，遗则冷汗淫淫，体倦而不能支。小峰为请药，予曰：姑置之。小峰问何故？予曰：金木相胜，心神无主，法当不治。小峰谓人尚无恙，何得便至于此？予曰：弦为春令，当金旺之时，犹然猖獗，设在卯月木旺火相，肺金枯萎，水之上源已竭，且肾脉洪滑，妓以欲胜，阴血既亏，淫火愈炽，书云，阴虚则病，阴绝则死。今已咳嗽，其兆见矣，可治乎。次年二月果死。（二十八）", "6288": "有老妓金姓者，其嫂三月患头痛、身热、口渴，水泻不止，身重不能反侧，日渐昏沉，耳聋眼合，梦多乱语，嘉秀医者，历试不效，视为必死。予适吴江归，便道过槜李，访南溪、吉泉二兄，吉泉兄以是症见询，且言诸医有以补中益气汤进者，有以附子理中汤进者，二药已煎成未服，幸弟至，乞为诊之。六脉洪大，观其色内红外黑，口唇干燥，舌心黑苔，不知人事。予曰：此疫症也，法当清解。急以小白汤进之，犹可生也。若附子理中汤，杀之耳，安可用。南溪兄问：小白何汤也？予曰：小柴胡、白虎汤，合而一之是也。南溪兄谓：泄泻昏沉如此，恐石膏不可用也。予曰：此挟热下利，但使清阳上升，则泻止热退，而神气自清也。服讫，夜半神气苏醒，惟小水不利，热渴不退。予思仲景法谓，渴而身热不退，小便不利者，当利其小便。乃以辰砂六一散一两，灯心汤调服之，两帖而瘳。南溪兄曰：死生信乎命也，弟顷刻不至，必服理中汤，此妇不为泉下人哉！（二十九）", "6289": "有曹姓讳镗者，九月重阳，以胸膈不舒畅，而谒南溪兄为治，诊未竟，予至，南溪兄起语曹曰：舍弟高手，浼诊之。诊讫未有言。而南溪私问曰：曹何如脉？予曰：不治。会易货者沓至，予亦别去，曹果次年二月死。南溪兄问曰：何曹无它病，而弟见脉即断不治，何也？予曰：其脉两寸洪滑搏指，两关微弦，两尺微弱，《难经》所谓溢脉也。九月深秋，木凋零时也，不宜弦大，大则上盛下虚，至二月木旺，木能生火，火木性皆上升不下，下无真阴以相济，是有阳无阴，有升无降。《内经》曰：出入废则神机化灭，升降息则气立孤危。是以断曹子二月当呕吐而死也。（三十）", "6290": "嘉善之妓李双，号素琴，体虽肥，而性冲澹，态度闲雅端重，歌调娼家推其擅场，与予邑程芹溪处厚，患痛风，自二月起至仲冬，诸治不效，鸨母悭毒，遂视为痼疾，不为治。而芹溪固恳予诊之，六脉大而无力，手足肢节肿痛，两跨亦痛，不能起止，肌肉消其半，日仅进粥二碗，月汛两月一行，甚少。予曰：此行痹也。芹溪问：病可治否？予笑而应曰：君能娶，予能治之。芹溪曰：嫁娶乃风月中套语，公长者，乃亦此言。予曰：观此子虽堕风尘，实有良家风度，予故怜之，且君断弦未续，而彼有心于君，或天缘也。芹溪曰：诚吾素愿，恐鸨母高其价而难与言。予谓：乘其病而盟之，易与耳。芹溪以予言为然，乞为治之。以人参、白术、苡仁各三钱，当归、枸杞、杜仲、龟板、苍耳子各二钱，晚蚕沙、秦艽、防风各一钱，大附子、甘草、桂枝、黄柏各五分，十帖而痛止肿消。改用归芍六君子，加苡仁、丹参、红花、石斛、紫荆皮，三十帖而痊愈。芹溪娶之。善持家，举族称贤，而亦羡予知人焉。（三十一）", "6291": "沈别驾翁，有老仆，头痛，遍身骨节痛，面色黑，发热，口渴，胸膈膨胀，饮食七日不入，复感寒，人皆危之。予诊其脉，左弦数，右洪大，以藿香、苍术、防风、葛根、白芷、紫苏、甘草、陈皮、大腹皮、麦芽、枳实，服后胸膈稍宽，热与痛更甚，改以麻黄、葛根、柴胡各二钱，石膏、滑石各三钱，紫苏叶、白芷、苍术各一钱，甘草五分，姜三片，服后大汗出，而热痛皆除，惟口渴，又以白芍药、当归、石膏、知母、柴胡、黄芩、麦冬、葛根、陈皮，煎服痊愈。别驾翁喜诘予曰：老仆病甚重，无不谓其必死，先生三日起之，此何症？而何汤剂饮之使起也。予曰：此三阳合病，先为饮食所伤，予故先用藿香正气汤，加消导之剂治其本，又以六神通解散，加助表之药治其标，病虽重，年虽高，喜其色脉相对，故投以对症之药易愈也。翁曰：在先生然耳，若它人轻者且重，况重者乎！吾未见其能起也。（三十二）", "6292": "蔡中林文学内人，发热口渴，舌上燥裂，小腹痛，呕吐，药食不能入者七日，诸医之技殚矣。皆视为膈食而不可为。吴我峰翁固邀予诊，右寸脉绝不应指，关沉滑有力，左手弦数。予曰：此阳明少阳合病，邪热壅于上焦然也，非膈食，法当解散，数剂可愈，无恐。以软柴胡、石膏各五钱，半夏曲、枳实、黄芩、黄连、葛根、竹茹、人参各二钱，姜三片，煎服，药纳而不吐，五更下黑粪数块，热痛减半。次日仍与前药，右寸脉至是亦起，粥始进。改用小柴胡加橘红、竹茹、葛根，服三帖而全安。（三十三）", "6293": "吴九宜先生，每早晨腹痛泄泻者半年，粪色青，腹膨脝，人皆认为脾肾泄也。为灸关元三十壮，服补脾肾之药皆不效，自亦知医，谓其尺寸俱无脉，惟两关沉滑，大以为忧，以人言泄久而六脉将绝也。予为诊之曰：君无忧，此中焦食积痰泄也，积胶于中，故尺寸脉隐伏不见。法当下去其积，诸公用补，谬矣！渠谓：敢下耶？予曰：何伤。《素问》云：有故无殒亦无殒也。若不乘时，久则元气愈弱，再下难矣。以丹溪保和丸二钱，加备急丸三粒，五更服之，巳刻下稠积半桶，胀痛随愈。次日六脉齐见，再以东垣木香化滞汤，调理而安。渠称谢言曰：人皆谓六脉将绝为虚极，公独见之真而下之，由公究理深邃，故见之行事，著之谈论，皆自理学中来，它人何敢望其后尘。（三十四）", "6294": "沈大官，左膝肿痛，不能起止者年半，大便泻一日三次，诊其脉弦紧。予曰：此脾虚有湿热凝于经络，流于下部也。古谓肿属湿，痛属火。用苍术、黄柏、薏苡仁为君，泽泻、猪苓、五加皮为臣，炙甘草、防风、桂枝为佐，木通为使，四帖痛减肿消，泄泻亦止。改用苍术、苍耳子、五加皮、苡仁、当归、枸杞子、杜仲、丹参、黄柏、乌药叶。酒糊为丸，调理月余，步履如故。（三十五）", "6295": "沈继庵先生，下痢十二日，腹痛，脱肛，后重，嗳气，不知饥。一友用补中益气加白芍药，腹痛愈加，后重亦甚。予脉之，右关滑大搏指，曰：此积滞固结肠胃间，故后重脱肛也。当为推荡，以其素弱多郁，不敢，只为调气而兼消导。木香、山楂、槟榔、枳实、川芎、白芍药、黄连、黄芩、秦艽。服后稍宽。次日用七伤丸，二帖痊愈。", "6296": "沈睛岳先生，五更耳鸣，腹不舒畅，稍劳则烘然热，自汗。脉右关滑大有力，左脉和缓，原为当风睡卧而得，素来上焦有痰火，午后过劳或受饿，大作眩晕，冷汗津津，再不敢动，稍动则呕吐，此皆痰火所致，盖无痰不作晕也。先与藿香正气散一帖，以去表里之邪，继与温胆汤加天麻，服后眩晕呕吐皆止。次日诊之，右关脉仍滑，此中焦食积痰饮胶固已久，卒难动摇。姑以二陈汤加枳实、黄连、滑石、天花粉、天麻、竹茹调理，后以当归龙荟丸加牛胆、南星、青礞石，凡数帖痊愈。（三十七）", "6297": "潘景宇内人，后半夜不睡，面黄肌瘦，两太阳及眉棱骨痛，大便溏，稍劳动则体热，四肢无力。其脉左寸洪滑，自春至秋皆然。此由脾虚，肝心二经火盛然也。先用四君子加酒连、柴胡、白扁豆、泽泻、滑石调理，夜与钱仲阳安神丸数粒，灯心汤送下。服八日得睡，两太阳亦不痛。继用六君子加黄耆、秦艽、柴胡、泽泻、当归、白芍药、黄柏，全安。（三十八）", "6298": "臧六老，上吐血，下泻血，胸膈背心皆胀，原从怒触，又犬肉所伤，故发热而渴。医者皆作阴虚火动，而为滋阴降火，胸背愈胀，血来更多。予诊之，两关俱洪滑有力。谓曰：此肝脾二经有余症也，作阴虚治左矣！《内经》曰：怒伤肝。甚则哕血，并下泄。胸背胀痛，瘀血使然。脾为犬肉所伤，故不能统血。今误用地黄、麦冬、黄柏、知母等剂，是以脾益伤，而上焦瘀血愈滞也。惟调气健脾兼之消导，则万全矣。六老曰：人皆谓劳怯，故发热吐红，血上吐，阳络伤也；血下行，阴络伤也。阴阳俱伤，法当不治，公独认非阴虚何也？予曰：脉书云脉数无力者阴虚也。今脉固非阴虚。书又曰：凡阴虚之热，发于申酉戌间，夜半而退，明日犹是，如潮信然。以下午乃阴分主事，故曰阴虚潮热也。今热不分昼夜，而症亦非阴虚，故曰作阴虚治者左也。六老闻言大喜曰：公诚见垣一方者，幸惠一匕以生之。即与山楂、香附、枳实，调气消导为君，丹参、丹皮、桃仁、滑石、茅根化瘀血为臣，黄连、芦根，解犬肉之热为佐，四帖，胸背宽，血吐止，惟腹中不舒，仍以前药同丹溪保和丸与之，四帖，大便下极臭黑粪半桶，寝食俱安矣。（三十九）", "6299": "有臧氏之妇，原以有痰火，服降火之药过多，至秋痰积，因令气，下行而滞于大肠，脐边有硬块，按之甚痛，痢下红白八日，下惟点滴，日夜二十余行，腹痛潮热，口渴，小水不利，大便里急后重，饮食不进，身重不能转侧。予诊之，喜左脉皆有神气，即从刘守真之法，行血则便脓自愈，调气则后重自除治之。用白芍药、滑石、桃仁为君，当归为臣，木香、槟榔、山楂、酒芩、酒连、枳壳为佐，服下大便稍流利，腹中稍宽舒，次日仍与前药，则滞下大行，痢减大半。第三日，用芍药、当归、滑石、桃仁、炙甘草、酒连、木香，与保和丸同服，下午大便行，上午所服丸药，随粪而下。乃知积滞已尽，诸症悉减，惟脐边痛未全止。以仲景小建中汤加当归、木香，服之而安。（四十）", "6300": "丁耀川文学令堂，年四十四，常患胃脘痛，孀居十五年，日茹蔬素，其年七月，触于怒，吐血碗许，不数日平矣。九月又怒，而吐血如前，加腹痛。至次年二月，忽里急后重，肛门大疼，小便短涩，出惟点滴，痛不可言，腰与小腹之热，如滚汤泡者，日惟仰卧不能侧，一侧则左胯并腿作痛，两胯原有痛，小便疼则肛门之痛减，肛门疼则小便之痛亦减。肛门以疼之故不能坐。遇惊恐则下愈坠而疼，经不行者两月，往常经来时腰腹必痛，下紫黑血块甚多，今又白带如注，口渴，通宵不寐，不思饮食，多怒，面与手足发虚浮，喉中梗梗有痰，肌肉半消，诊之脉仅四至，两寸软弱，右关滑，左关弦，两尺涩。据脉上焦气血不足，中焦有痰，下焦气凝血滞，郁而为火。盖下焦之疾，肝肾所摄，腰胯肝之所经，而二便乃肾之所主也。据症面与手足虚浮，则脾气甚弱，饮食不思，则胃气不充，不寐，由过于愁忧思虑而心血不足，总为七情所伤故尔。《内经》云：二阳之病发心脾，女子得之则不月。此病近之。且值火令当权之候，诚可虑也。所幸者，脉尚不数，声音清亮，尤可措手。因先为开郁清热，调达肝气，保过夏令后，再为骤补阴血。必戒绝怒气，使血得循经，而病可痊。不然，则仓扁亦难奏功矣。初投当归龙荟丸，以撤下部之热，继以四物汤，龙胆草、黄柏、知母、柴胡、泽兰叶，煎吞滋肾丸。连服四日，腰与小腹之热始退，后以香薷、石苇、龙胆草、桃仁、滑石、杜牛膝、甘草梢、软柴胡，煎吞滋肾丸，大小便痛全减。（四十一）", "6301": "丁文学长令姊，常患晕厥，吐痰碗许乃苏，一月三五发，后又口渴，五更倒饱，肠鸣腹疼，泄泻，小水短涩，咳嗽。余脉之，两寸濡弱，两关滑大，此中焦痰积所致也。先与二陈汤，加苍术、山楂、麦芽以健脾去湿为臣，以白芍药止痛为君，以滑石、泽泻引湿热从小便出为佐，黄芩为裨佐。十帖，二阴之痛俱止，改以六味地黄丸加黄柏、知母、牛膝，服之全安。（四十二）", "6302": "有金良美者，年十八，患咳嗽吐红，下午潮热梦遗。市医进四物汤加天麦门冬、黄柏、知母之类，治半年，反加左胁胀疼，不能侧卧，声音渐哑，饮食辄恶心，肌肉大削，六脉俱数，医告技穷，因就予治。观其面色白，又隐隐有青气夹之，两足痿弱无力，予语之曰：此症气虚血热，而肝脉甚弦，弦则木气太旺，脾土受亏，不能统血，殆始怒气所触，继为寒凉之剂所伤，以致饮食恶心，肌肉瘦削。书云：脾胃一虚，肺气先绝。以肺金不足，则肝木愈不能制。浊痰瘀血凝于肺窍，故咳嗽声哑，滞于肝，故左胁不能贴席而卧，病势危矣。喜在青年，犹可措手。因急用人参二钱、鳖甲五钱为君，白术、白芍、陈皮、茯苓、通草、贝母各一钱为臣，甘草、牡丹皮各七分为佐，桔梗五分为使。二十帖，潮热止，咳嗽减大半。三十帖，声音开亮，左胁亦能贴席而卧。后以大造丸调理全安矣。乃嘱之曰：病愈虽可喜，而弦脉未退，须切忌怒气及劳心劳力之事。庶几可保无虞。苟不守予言，而劳怒相触，血来必不能御，戒之防之。此后精神日王，肌体丰肥，六年无事。一日遇事拂意，大怒，而又结算劳心，则血如泉涌，顷刻盈盆，上唇黑肿，汗出淋漓。急请予诊，脉乱无伦，诊毕，渠语近侍欲大解。予曰：此死征也，阴阳乖离矣。辞而出，未离门而气绝。父母哭谢予曰：始守翁训，苟活六年，一旦不戒，遂如翁所料，死生虽命，亦不自慎致之。其为人也，量窄而紧于财，因记此以戒世之重财轻生者。（四十三）", "6303": "王祖泉令政，患头疼夜热，洒淅恶寒，汗淋漓如雨，上身热，下身寒，渴不思饮，遍身疼，腹有一块，大如拳，硬如石，肠鸣，小水短少，饮食俱废。脉则右关滑，左弦数。究所由起，谓大怒后即伤于食，市医皆以地黄、门冬、芩连、黄柏之剂治之，热愈甚，脾气大虚。予治用平胃散，加山楂、麦芽、砂仁、香附、木香、川芎、枳实，连进四帖，中气稍能运动，而夜热如前。再与补中益气汤，寒热俱退矣。而腹痛里急后重。予知其积滞将行也，乃与白六神丸，而腹痛后重皆除，改进以参苓白术散，加香附、乌梅、山楂，服之病良已。（四十五）", "6304": "温巽桥子妇，吴车驾涌澜公长女也。发热恶心，小腹痛，原为怒后进食，因而成积，左脚酸已十日矣。南浔有陈女科，始作瘟疫疗治，呕哕益加，又作疟治，粒米不能进，变为滞下，里急后重，一日夜三十余行。陈技穷而辞去。且言曰：非不尽心，犯逆症也。下痢身凉者生，身热者死，脉沉细者生，脉洪大者死。今身热脉大，而又噤口，何可为哉。因请予治，脉之，两手皆滑大，尺部尤搏指。予曰：症非逆，误认为疫为疟，治者逆也。虽多日不食，而尺脉搏指。《内经》云：在下者，引而竭之。法从下可生也。即与当归龙荟丸一钱五分，服下，去稠积半盆，痛减大半，不食者十四日，至此始进粥一瓯。但胸膈仍饱闷不知饿，又与红六神丸二钱，胸膈舒而小腹软，惟两胯痛，小腹觉冷，用热砖慰之，子户中白物绵绵下，小水短涩。改用五苓散加白芷、小茴香、白鸡冠花、柴胡服之，至夜满腹作疼，亟以五灵脂醋炒为末，酒糊为丸三钱，白汤送下，通宵安寝。次日，精神清健，饮食大进，小水通利矣。而独白物仍下，再用香附炒黑存性、枯矾各一两，面糊为丸，每空心益母草煎汤送下二钱，不终剂而白物无，病全愈矣。专科赧然称奇而服，录其案验而去。（四十六）", "6305": "温一渠内人，平素血虚咳嗽，近为饮食所伤，不知饥饿。专科作阴虚治，而胸膈愈胀。予脉之，右关滑大，左手软弱。法当先健脾，消去饮食，然后治嗽。若为补阴降火，不惟咳嗽无功，恐脾胃转伤，腹胀泻泄，变将不测。何也？脾胃喜温而恶寒也。即以二陈汤加山楂、麦芽、枳实、白术、川芎、香附与之。一剂而胸膈宽，再剂而饮食进。继用桑白皮、地骨皮、甘草、陈皮、贝母、栝蒌仁、马兜铃、桔梗、紫菀，十帖而咳嗽脱然矣。（四十七）", "6306": "温天衢氏，冬月病目，医为发散太过，至春间吐血碗余。及夏，下午潮热咳嗽，胸膈胀疼，早晨冷汗淋漓，大便溏，一日两行，饮食少，肌肉消十之七，脉数，据症脉，法在不治。里中诸长老，以其素行端厚，群然恳予措剂。予以众恳不能辞，乃用泻白散加五味子、白芍药、贝母、马兜铃，服下，其夜帖然而卧，不嗽，惟大便溏。前药加白扁豆、山药、茯苓，汗亦渐止，复与泻白散，加石斛、马兜铃、贝母、陈皮、薏苡仁、白芍药、山药、五味子、桔梗，调理三月而痊。（四十九）", "6307": "温南溪内人，居常大便秘结，面赤，不思饮食，头时眩晕。诊其脉，右关尺滑大有力，此痰火症也。用栝蒌四钱为君，滑石三钱，枳实二钱，半夏一钱半为臣，萝卜子、姜黄各一钱为佐，两帖愈矣。又教以或遇大便秘结，每服当归龙荟丸，加牛胆、南星一钱立应。（五十二）", "6308": "潘敬斋令媳，原因经水不行，医投安胎之剂。越七月，经水忽大行，内有血块筋膜如手大者一二桶，昏冒困惫为剧，逆予治，其脉右关洪滑，左寸洪数，两尺皆洪大。病形夜分咬牙乱语，手心热，口噤，时手足皆冷，心头胀闷不快，面色青。始诸医皆谓难治。予曰：无恐，此浊痰流滞血海，以误服安胎之剂，益加其滞。夫血去多，故神魂无依，痰迷心窍，故神昏语乱。急为调气开痰，安神养血，可生也。即以温胆汤加石菖蒲、酒芩、天麻、酸枣仁、丹参与服。其夜子丑时，咬牙乱语皆减半，次日仍与前药，每帖加竹茹五钱，临睡，又与黑虎丹数粒，诸症悉去而愈。敬斋问曰：藉高手病痊矣，而每发于夜半何也？予曰：此心包络与胆经有痰热，故每至其时而发，单治此两经，痰既消，而神魂俱安也。敬斋曰：善。（五十四）", "6309": "臧七房二老夫人，年六十八，患痢，痢后过食熟菱与腐汤，以致大便滑泄不固，饮汤水，径直下不停，胸膈痞闷，语言无力，舌干口燥生疮，咽津液则喉疼。元气大虚而热，皆虚火所致。且长素二十余年，又当痢后，益知非有余之症也。脉又尺寸俱弱，两关滑大。《内经》云：清气在下，必生飧泄，浊气在上，必生䐜胀，此之谓也。法当提清降浊，补助元气。用四君子汤，加葛根、白芍药、黄连清虚热，止燥渴为君，桔梗辅佐葛根升提清气为臣，陈皮、麦芽降其浊气，以消胸膈痞闷为佐，加乌梅为使。上使生津，下使止浊，连服二剂，尺寸之脉稍起，饮食亦得停腹，骎骎然始有生气。仍以前方加白扁豆、神曲，打糊为丸，调理而安。（五十六）", "6310": "蔡乐川令眷，患头痛，痛如物破，发根稍动，则痛延满头，晕倒不省人事，逾半时乃苏。遍身亦作疼，胸膈饱闷，饮汤水停膈间不下。先一日吐清水数次，蛔虫三条。原为怒起，今或恶风，或恶热，口或渴，或不渴，大便秘，脉则六部皆滑大有力。予曰：此痰厥头痛症也。先以藿香正气散止其吐，继以牛黄丸、黑虎丹清其人事。头仍疼甚，又以天麻、藁本各三钱，半夏二钱，陈皮、白芷、薄荷、麻黄、生姜、葱白煎服，得少汗而头痛少止。至晚再服之，五更痛止大半，而人事未全清。予谓此中焦痰盛，非下不可。乃用半夏五钱，巴霜一分，面糊为丸，每服三十丸，生姜汤送下。下午大便行三次，皆稠黏痰积也。由此饮食少进，余症差可，惟遍身仍略疼。改用二陈汤，加前胡、石膏、藁本、薄荷、枳壳、黄芩、石菖蒲，调理而安。（五十七）", "6311": "周芦汀乃眷，患胃脘痛，手心热，呕吐不食者四日，昼夜叫痛不辍声，脉则两手皆滑数。予谓当以清热止痛为先，故先与清热止痛末药二钱令服之，不一饭顷，痛遂止而睡。家人皆色喜。予曰：未也。此火暂息耳，其中痰积甚固，不乘时而下之，势必再作。因与总管丸三钱，服下腹中微痛，再服二钱，又睡至天明乃寤，而腹痛亦止。大便下，痰积甚多。次日以二陈汤，加枳实、姜黄、香附、山栀、黄连与之，服后胃脘之痛全止，惟小腹略觉膨脝。予谓其痰积未尽也。再与总管丸三钱，夜服之，天明又行一次，痰积之下如前，而胃脘之痛亦绝不发矣。（五十八）", "6312": "施泾阳先生内人，年五十八，左胁有痰饮，每升至咽间，即胀闷不知人事，遍身皆胀，不能卧，小水赤。诊其脉，两寸关洪滑，六部皆数。予渭此痰火症也，痰生热，热生风，故每发人事不知尔。乃与牛黄清心、凉膈丸同黑虎丹服之，夜遂得睡，人事亦安静。再以二陈汤加滑石、竹茹、郁金、薄荷、黄芩、前胡，加灯芯、生姜煎服，全安矣。（六十）", "6313": "屠侍轩尊眷，产一日而触于怒，大便泄泻，昏愦不省人事，大热，气促，汗多。众医谓产后脉不宜大，今脉大左手散乱，又汗出喘促，法在不治。予曰：固然书云医而不起者有矣，未有不药而起者也。且不药而视其死，与药而或可图生者，孰优？予试之。亟与人参五钱，白术三钱，炙甘草一钱五分，炮姜二钱，肉果六分，五味子七分，煎服。其夜遂稍睡。予窃喜，补而得睡，其阴阳和矣。次早脉果稍收敛，喘促亦缓，大便前半夜泻三次，五更啜粥半盂，小便通利，大有生意也。再以人参、阿胶固元气、定喘为君，白术、炮姜补脾为臣，泽兰叶退产后之热，五味子敛神止汗，肉果止泻为佐，甘草和中为使，五帖而安。（六十一）", "6314": "屠学恒先生乃眷，以产后欠补养，而精神疲困，脾胃亦弱，腹中间作痛，作泻，脉两手皆濡软无力，以六君子汤加藿香、砂仁、香附、苍术、泽泻，调理而安。（六十二）", "6315": "周鉴泉令政，病伤寒。发热，谵语，口渴，咳嗽，胸膈痛，泄泻，呕吐，遍身发斑。诊之，六脉洪滑，予曰：此少阳阳明合病之症，势亦重矣。急以升麻葛根汤，加滑石、五味子进之。服后汗大出，下午即退凉而谵语止。晚进柴苓汤加五味子、滑石，其夜泻止，神思始清。次日左脉已和，右脉亦稍收敛。予喜曰：可无恙也。改用白芍药为君，陈皮、柴胡、酒芩、五味子、牡蛎、滑石、茯苓、泽泻、白术，服四帖而痊可。（六十三）", "6316": "大国博臧顾诸先生，病两耳掀痒，唇燥舌干，咳嗽吐浓痰，脉左稍浮弦，右洪滑。此胃中痰火流入肺经，郁积久而生热生风也。先以总管丸导其痰，又与黑虎丹祛其风热，继以天花粉、薄荷、郁金、葛根、白药子、甘草、黄连、连翘、蝉蜕，煎服而安。（六十四）", "6317": "王南岗，咳嗽，气涌不能伏枕，吐痰不已，下午微热，胸膈膨胀，不知饱饿，口干，舌上白苔厚，小水短少，大便里急后重，间有紫黑血。脉右关洪滑，左手涩。据脉症，胃中有瘀血痰积，而肺气亦虚也。法当先补而后泻，以人参、白术、白芍药、柴胡、黄连、陈皮、半夏、五味子、桔梗，与三帖后，察其肺脉已旺，乃与总管丸下之，去黑血屑极多，渚症悉减，再与红六神丸调理而痊。（六十五）", "6318": "张桃津乃政，原有小便癃闭之症，又小产后三日，脐下作疼，夜分发热，口渴，大便溏，日三四度。先与补中益气汤，加玄胡索、泽兰叶、牡丹皮服之，连进三帖，大便实矣。惟小便频数，滴滴不断，一日夜二十余次，夜分尤多，精神甚惫。脉虽五至，不甚充指。此血虚有热，而气亦滞也。湿热在气分，故口中渴，血虚，故脐下痛。法当峻补其阴，而淡渗其阳。以熟地黄三钱，黄柏一钱补阴为君，萆薢去湿热为臣，瞿麦穗、泽泻淡渗为佐，乌药调气，甘草为使。服下脐痛全止，小便其夜亦不起，连进三帖，病脱然矣。（六十六）", "6319": "溧水令君吴涌澜公尊夫人，每五更倒饱，必泻一次，腹常作胀，间亦痛。脉两手寸关洪滑，两尺沉伏。予曰：此肠胃中有食积痰饮也。乃与总管丸三钱，生姜汤送下。大便虽行，不甚顺利，又以神授香连丸和之，外用滑石、甘草、木香、枳壳、山楂、陈皮、白芍药、酒连，调理而安。（六十八）", "6320": "李悦斋先生夫人，胸胁大腹作疼，谵语如狂。寅卯辰三时稍轻，午后及夜痛甚，昼夜不睡，饮食不进者十八日。究其故，原有痰火与头疼、牙疼之疾，又因经行三日后，头疼发寒热。医以疟治，因大恶热，三四人交扇之，而两手浸冷水中，口噙水而不咽，鼻有微衄，又常自悲自哭，目以多哭而肿，痛时即壁上亦欲飞去，剧则咬人，小水直下不固，喉梗梗吞药不下。脉则左弦数，右关洪滑。予曰：此热入血室症也。误服治疟刚燥之剂而动痰火，以致标本交作。诸人犹谓：热入血室，当夜间谵语如狂，如见鬼，何至胸胁疼剧咬人也？予曰：仲景云，经水适来适止，得疾，皆作热入血室治之，治同少阳。而以小柴胡汤为主，加凉血活血之药，此古人成法可守也。痛极咬人者，乃胃虚虫行，求食而不得，故喉中梗梗然也。即以小柴胡汤加桃仁、丹皮，而谵语减，次日以安蛔汤与服，而疼随止，饮食进，遂骎骎有生意。（六十九）", "6321": "吴仲峰先生，邀予诊时为仲秋初二日也。六部皆沉微，而左尤甚，隐隐又如珠丝之细，症则原以肠风去血，过服寒凉，致伤脾胃，自春至秋，脾泄不愈，日夜十二三行，面色黄白带青，两颐浮肿，四肢亦浮，小水不能独利，利必与大便并行，肠鸣，四肢冷，口不渴，饮食大减，口唇龈肉皆白。其为人也，多忧思。夫四肢者，脾之所主，清冷为阳气不充。两颐乃肾经部位，浮肿益见肾气之不足也。脉沉微与面色黄肿，皆属于湿。书云：诸湿肿满，皆属脾土。合脉症观之，由脾虚不运积湿而然，虚寒明矣。病至此，势亦甚危，第形症相符，色脉相应，又能受补，庶几可生也。法当大温补升提，以东垣益胃升阳渗湿汤加减调理。人参三钱，白术五钱，黄耆二钱，茯苓、益智仁、苍术、泽泻各一钱，大附子五分，炮姜、炙甘草、升麻、防风各五分，连服八帖，诸症悉减。乃嘱之曰，病虽暂愈，宜戒生冷、忧思，庶服药有效，切勿轻犯，犯之非药石可回也。翁曰：诺，敢不唯命。（七十）", "6322": "府佐张五桥先生夫人，患喘嗽，夜分气壅不能仰卧，体素弱，脉右滑大，左细弱，每咳嗽，必连连数十声，痰不易出，甚至作吐。以东垣人参平肺散加减治之，四日而愈。人参、桑白皮、地骨皮、青皮、茯苓、五味子、知母、滑石、麦芽、天麻、粳米、甘草水煎服，夜与白丸子。（七十二）", "6323": "方东檒,患脊骨痛，牵引胸腹皆疼，舌上黄苔甚厚，脉沉滑而数。先以川芎、羌活、炙甘草、苍术、姜黄、防风、藁本、枳壳、桔梗、柴胡服之。服后背脊痛减，腹仍痛。与木香、槟榔、姜黄、香附、青皮、酒连、大栝蒌、柴胡、川芎服之，腹痛稍减，腰疼甚。知其痰积下行，欲去而不能也。即以木香槟榔丸下之，连行三四次，舌上黄苔始退，腹痛全止。脉亦软弱，改以人参、当归、白芍、甘草、茯苓、陈皮、白芥子、香附、柴胡、青皮、白术，调理而安。（七十三）", "6324": "张一尹近川翁。始以内伤外感，过服发散消导之剂，致胃脘当心而痛，六脉皆弦而弱，此法当补而敛之也。白芍药酒炒五钱，炙甘草三钱，桂枝一钱半，香附一钱，大枣三枚，饴糖一合，煎服一帖而瘳。（七十五）", "6325": "闵文川先生，肛上生一肿毒，月余脓溃矣，但稍动则出鲜血不止，大便结燥，胸膈饱胀，饮食不思。脉两寸短弱，关弦，尺洪滑，此气虚血热，陷于下部。法宜补而升提也者，不然痔漏将作，可虑也。黄耆二钱，归身、地榆、槐花、枳壳各一钱，升麻、秦艽各七分，荆芥穗五分，甘草三分。服后胸膈宽，惟口苦甚，前方加酒连、连翘各五分而愈。（七十六）", "6326": "李古愚先生，每食后即大便，腹皮稍胀急，胸膈饱闷。医与参术则痞闷愈甚，小水清而长。予脉之，左寸涩，右寸滑，按之如黄豆大，且鼓指，关尺之脉皆弦小，左尺脉迢迢有神气。据脉乃积痰郁滞于肺莫能出，以致大便之气不固也。法当效丹溪治乃叔用吐，吐去上焦痰积，而大便自实矣。先用苦梗、萝卜子各三钱，白豆仁、橘红、山栀仁各一钱，川芎五分，生姜三片，葱三根，水煎服之，取吐，服后半小时许，恶心，吐出清痰，心恶之势虽有，乃痰积胶固，犹不易出。又以萝卜子一合，擂浆水，加蜂蜜，与半碗饮之，始吐出胶痰二碗余。平日每小水则大便并行，吐后小水始能独利，连行三四次，而胸腹宽舒。初亦以吐为惧，至是豁然称快，大便五日不行。始以予言为不谬也。再以二陈汤加白术、旋覆花、麦芽，调理而全可矣。（七十七）", "6327": "姚惠斋先生，夜多泄泻，泻必三五次，甚且十数次，小腹时作疼，按亦疼，口不渴，小便长，医半年不愈。予诊之，左寸滑，余五部皆濡弱。此阳气大虚，虚中有寒也。治当温补下元，兼之升举。人参一钱半，黄耆、白术各二钱，白芍药酒炒三钱，大附子五分，肉桂一钱，杜仲、补骨脂各一钱半，升麻、防风各七分，姜枣煎服。其夜大便减半，次早虽泻，俱是白积，如生豆汁状，小腹痛止。再诊之，右脉稍起，连服四帖而瘳。翁喜言曰：抱病半年，药无虚日，今收功于四剂，何速哉！认病真而投剂确也，敢不铭心。（七十八）", "6328": "大京兆姚画老夫人，年几七十，右手疼不能上头。医者皆以痛风治不效，益加口渴烦躁，请予诊之。右手脉浮滑，左平。予谓此湿痰生热，热生风也。治宜化痰清热，兼流动经络可瘳也。二陈汤倍加威灵仙、酒芩、白僵蚕、秦艽，四剂而病去如脱。（七十九）", "6329": "一仆发热头疼，口渴，腹疼，小便赤，大便泻，日夜不睡者六日。予诊之曰：据脉，汗后浮数，热尚不减，乃疫症也。以滑石三钱，青蒿、葛根、白芷、片芩各一钱半，炙甘草，升麻各五分，一帖即得睡，热减大半，头痛全除。惟小水赤，头晕，脚膝无力。此病后血虚之故。以四物汤加青蒿、酒芩、薏苡仁，服之而安。（八十）", "6330": "一仆病与前类，而身如火烁，头痛如破，大便不泻，小水赤，口渴，鼻干，不得眠，胸膈膨胀，腹饥不能食，六脉弦而数。用竹叶石膏汤，加知母、枳壳、白芷、葛根，大加青蒿，一帖而热痛减半，胸膈亦宽。惟口渴，小水短涩，睡卧不安。又与化瘟丹三钱，井水化下，渴止，稍得睡，头晕脚软，喘急。与四物汤加青蒿、酒芩、薏苡仁、木瓜，服之全安。（八十一）", "6331": "马凤阳文学，五月患咳嗽，内热，额上多汗，恶风。脉左弦数，右滑数。予曰：据弦数为阴虚，滑为有痰。不亟调治，恐成虚怯。以白芍药、川归、茯苓、五味子、白术、甘草、陈皮、贝母、天花粉、酒芩、麦冬、知母、桑白皮，十帖，诸症皆瘳。七月复疟，间日一发，寒热相半，寒热亦俱极，渴甚，上身汗多。以石膏五钱，人参、黄耆、白芍药、麦冬、知母各二钱，柴胡三钱，桂枝、甘草、陈皮、贝母各一钱，竹叶三十片，一帖而愈。（八＋三）", "6332": "倪二南先生内人，小水不禁，一日二十余起，脉右寸洪而有力，左寸虚，右尺沉微。此心肾不交之症也。以当归、远志、丹参、牡丹皮、桑螵蛸、人参、山茱萸、益智仁、黄柏、知母为丸，服之，五日而安。后凡遇辛苦则发，以此服之立效。（八十四）", "6333": "柱史严印老长媳，少司空沈镜老女也。患腹痛有小块藟藟然，腹觉冷甚，两寸关皆滑数，两尺皆沉微，此脾气弱而饮食不消，又当秋令湿淫之候，不利亦泻，宜预防。与白术、苍术、茯苓、甘草、白豆仁、木香、半夏、陈皮、泽泻煎服。其夜果泻一度，次早又泻一度。小腹仍疼不少减，且里急后重。盖其禀赋素虚，当补中兼消兼利。白芍药三钱，桂心一钱，甘草、人参、茯苓、泽泻、陈皮、白术各八分，升麻、葛根各六分。服后脉皆软弱不滑，藟块亦消。改以人参、黄耆、白术、白芍药各二钱，炙甘草、陈皮、泽泻、葛根、柴胡、茯苓各一钱，调理而痊。（八十五）", "6334": "新市陈鹿塘先生，原有肠风脏毒之症，大便燥结，数日不能一行，痛苦殊甚。此胃寒肠热之症，其脉两寸皆数，两关皆弦而无力，两尺洪滑而左尤甚。诊毕，渠告予曰：病数年，百医不效，望生难矣。闻公治多奇中，冀一奇而生之，实再造之恩也。予怜其苦，而俯想久之。因思李东垣有云，大肠喜清而恶热，脾胃喜温而恶寒，以胃属土，而大肠属金也。今治肠胃相兼之疾，必寒非凄凄，热非灼灼始可。乃详酌一方，专以肠风脏毒之药为君主，外以养血之剂裹之，使不伤胃气。盖药先入胃，而后传入大肠，入胃时裹药未化，及入大肠则裹药化，而君药始见，庶几两不相妨，亦假道灭虢之策也。因以大黄酒浸九蒸九晒者二两，槐花三两，木耳二两，郁李仁、皂角子、象牙屑、条芩各一两，血余灰、升麻、荆芥穗各五钱，为末，炼蜜为丸，赤豆大，外以四物汤加蒲黄各一两为衣，米汤送下，空心及下午各服二钱。服此果然血止，而大便不燥，饮食日加。鹿塘大喜曰：古称用药如用兵，奇正相生，鲜有不克敌者，其公之谓乎。（八十六）", "6335": "张道南先生尊堂老夫人，以劳倦致早晨膈上有痰痞而恶心。每食热物，目中即出泪，脉右寸关皆滑，左寸短弱，此心血不足，而肺胃有痰也。以六君子汤加麦芽、白豆仁、旋覆花治之而愈。（八十八）", "6336": "马迪庵先生内人，原以饮食过伤，又为风寒外袭，以内伤外感治之后，复至五更发热，唇燥，胸中冲跳不已，手足皆冷，脉两寸俱滑数。予谓此奇痰症也。以小陷胸汤加白芍药、萝卜子、前胡、酒芩二帖，次早大便行，下蛔虫八条，胸中即不冲跳，但觉力怯。再诊之，两寸减半；尺脉稍起。以二陈汤加白术、白芍药、酒芩调理，后四帖加当归而痊愈。（八十九）", "6337": "大宗伯董浔老夫人，常眩晕，手指及肢节作胀。脉右寸软弱，关滑，左脉弦长，直上鱼际，两尺皆弱，此亢而不下之脉。《难经》所谓：木行乘金之候也。总由未生育而肝经之血未破尔。《内经》云：诸风掉眩，皆属肝木。兼有痰火，治当养金平木，培土化痰。以白术半夏天麻汤，正与此对。服两帖而眩晕平。与六君子汤加天麻、白僵蚕以治其晕，加白芍药以泻肝，麦门冬、人参以补肺金，麦芽、枳实、神曲、苍术以健脾，使宿痰去而新痰不生。少用黄柏二分为使，引热下行，令不再发。（九十）", "6338": "王谷泉，大便作泻，上身热，耳中壅塞，头眩晕，胸膈不宽，口渴，痰多，咳嗽，六脉俱濡弱，汗大出。此正气大虚，或由克伐太过所致，当以补养为先。人参、白术、白芍药酒炒，各四钱，柴胡、石菖蒲、陈皮各一钱，炙甘草五分，泽泻、茯苓各一钱。两服而神清膈宽脾健，惟汗不敛，眩晕未除。再与人参、白术、黄耆、酒炒白芍药各二钱，炙甘草五分，大附子五分，桂枝三分，泽泻一钱而愈。（九十三）", "6339": "方东檒，两胁痛，上壅至胸，发热，饮食不进。脉左手沉而弦数，乃积气也。右手滑，痰饮也。关脉濡弱，脾气不充也。据症或触于怒，故痛之暴耳。治当先去积热，消痰气，然后用补。栝蒌仁六钱，枳壳、姜连、半夏各一钱半，白芥子一钱，牡蛎二钱，炙甘草五分，柴胡一钱五分，二帖，诸症尽去，饮食进矣。然恐其复发也，与当归龙荟丸使行之，以刈其根，服下果行两次。（九十四）", "6340": "一妇人心痛，唇红，痛则大发热，头疼，少顷出汗，脉大小不一。予曰：此虫痛之症，痛吐白沫可征也。槟榔、川椒各二钱，杏仁一钱五分，石菖蒲一钱，乌梅七个，炮姜、草豆仁、陈皮各五分，山栀仁一钱。一进而痛减半，再进而痛全除。（九十六）", "6341": "倪少南内人，行经如崩，势不可遏，头晕眼花，脉右寸极软弱，左近驶，此气虚血热之候，由气虚而血不固也。仲景云：血脱益气。特用人参、黄耆各三钱，白术二钱，粉草五分，荆芥穗、蒲黄、侧柏叶、姜炭各一钱，三帖全瘳。（九十九）", "6342": "高仰山内人，痔血，里急后重，饮食入腹，大便即行，昼夜行五六度，五更咳嗽，喉中痰响，肌肉脱，口作渴。由服痔科凉血之药过多，致脾虚不能统血也。脉六部皆软弱无力。以四君子汤加荆芥穗、秦艽、陈皮、炮姜，四帖而饮食进，血全止，嗽定而睡宁。后减炮姜，倍加何首乌，又四帖，而数年不发矣。（一百）", "6343": "徐文学三泉先生令郎，每下午发热直至天明，夜热更甚，右胁胀痛，咳嗽吊疼，坐卧俱疼。医以疟治罔效。延及二十余日，热不能退。后医谓为虚热，投以参术为主，痛益增。逆予诊之，左弦大，右滑大搏指。予曰：《内经》：左右者，阴阳之道路。据脉肝胆之火为痰所凝，必勉强作文，过思不决，木火之性不得通达，郁而为疼。夜甚者，肝邪实也。初治只当通调肝气，一剂可瘳。误以为疟，燥动其火，补以参术，闭塞其气。书云：体若燔炭，汗出而散。今汗不出，舌上之苔已沉香色，热之极矣。设不急治，立见凶危。乃以仲景小陷胸汤为主。大栝蒌一两，黄连三钱，半夏曲二钱，前胡、青皮各一钱，水煎饮之。夜服当归龙荟丸微下之。诸公犹争之曰：病久而食不进，精神狼狈若此，宁可下乎？予曰：经云肝常有余。且脉亦为有余，故有余者泻之。前时误认为虚，投补左矣，岂容再误哉。服后，夜半痛止热退，两帖全安。（一百零三）", "6344": "王祖泉乃眷，朝饭后稍寒，恶风发热，遍身疼痛，汗大出不止，口中热，腹中不知饿，小水短，六脉皆涩。以白芍药五钱，白术二钱，桂皮、黄芩各一钱，甘草八分。二帖而汗止，寒热除，减去白术，加当归而遍身痛止。（一百零四）", "6345": "费一吾先生令政，妊已四月，夜不能睡，小便淋痛，痰嗽内热。脉右关滑，左寸微弱，两手皆数。与橘红、贝母、片芩、黄连、茯苓、泽泻、枳壳、苏梗、前胡，水煎服之。其夜即能安寝。次日再以四君子汤加当归、香附、贝母、陈皮、条芩、紫苏梗、前胡，调理足月而产一子。（一百零六）", "6346": "令弟媳六娘子，遍身痛，发热，汗大出，昏昏如醉，卧不能起。两寸脉短弱，两手皆数而无力，此劳倦之余，故汗大走也。黄耆三钱，白芍四钱，粉草一钱五分，桂皮八分，当归一钱，石斛二钱。一帖热除，痛、汗皆止。惟倦而不能起，仍以前方加人参、陈皮，两帖而痊。（一百零七）", "6347": "姚弁山老先生内人，自上年十月，左足不能履地。至十二月，产后忽好三日，复不能动，时常胸胁作痛，素多痰火，而治者卒以四物汤、天麦门冬为主，间服独参汤，服将弥年，而病如故。予诊之：两寸脉俱洪滑而数，夜分发热，此系湿痰凝滞，补塞太重，故迁延不脱。乃以二陈汤加苍术、黄柏、威灵仙、五加皮、生地黄、白芥子、白芍药、当归，两帖，胸胁痛止，热除，再加薏苡仁，八帖，而足能举步矣。（一百零九）", "6348": "李坦渠老先生令子室，十月发寒热起，一日一发，咳嗽，心痛，腰亦痛。至次年正月十七日，始间日一发，肌肉大瘦，喉疼，汗出如雨，白带如注，饮食减少，百试而汗不止，延予为诊。其脉右手软弱，左手散乱，此汗多而脉不敛，病势至此，危之甚矣。书云：火热似疟。此病之谓欤。以黄耆二钱，白芍一钱五分，粉草、阿胶各一钱，鳖甲三钱，桂枝五分，乌梅一个，水煎服。其夜汗止。次早诊之，左脉已敛，神气亦回。前方加何首乌、石斛、牡蛎。其日寒热亦不发，饮食稍加，骎骎然有幽谷回春之象。（一百十）", "6349": "太学周衡宇先生，吴江澜溪人，大冢宰白川公之令孙也。近来咯血色紫，胃中痰火素盛，壅于胸膈，作痞作疼，痰与瘀血挟而为热。脉左寸洪大，右寸关皆滑，两手尽数，此有余之候。总管丸四钱，再以滑石、桃仁各三钱，山楂二钱，枳壳、栀子、贝母、红花、丹皮各一钱，茅根五钱，水煎服之。次日大便行三次，痰积极多，内带瘀血。改以山栀子、紫菀、丹皮各一钱，滑石三钱，桃仁一钱五分，小蓟三钱，茅根五钱，水煎，加童便一酒杯，三帖全安。（一百十一）", "6350": "大参张公，分守杭嘉湖道，因丧夫人，衙中亡者八口，心中惶惶。因凌绎翁交厚，而礼予为诊。左寸脉短，关弦，右关滑，两尺亦弦。据脉心血不足，中焦有痰，流于下部，凝于经络，以故腰膝酸疼，居常背心作胀，头多眩晕，夜睡多汗，先时诸医悉投风剂，非所宜也。予以陈皮、白芍药、木瓜、牛膝、五加皮、苡仁、黄柏、酒芩、甘草、生地、当归、威灵仙调理，十剂，诸症悉愈。（一百十二）", "6351": "张丽川，咳嗽多痰，面青，潮热，肌瘦，性躁而多自用，以数考不利，悒悒成疾。又新婚之后，饮食不节。脉之右关滑大，余部皆无神气，且粪门已发瘘疮，溃流脓血。予曰：此阳病极而下也。法在不治，果不逾月而亡。（一百十五）", "6352": "陈仰山先生内人，小产后二月而血大下，白沫如注，五更泄泻，面虚浮，下午身热口渴，面色青黄，脉右手豁大近芤，左濡弱。据此，大虚之候，血海尚有瘀血不尽，以致新血不得归源，稍动气即下如崩。盖脾乃统血之经，虚则不能约束，且面浮食少，脾虚剧矣。急宜温补，势或可为。人参、白术各二钱，姜炭、粉草各五分，茯苓六分，香附八分，丹参炒过一钱，水煎服。四帖而泻止。再以人参、白术各二钱，茯苓、丹参、黄耆、蒲黄各一钱，姜炭、泽兰叶、粉草各五分，调理痊愈。（一百十六）", "6353": "张溪亭乃眷，喉中梗梗有肉如炙脔，吞之不下，吐之不出，鼻塞头晕，耳常啾啾不安，汗出如雨，心惊胆怯，不敢出门，稍见风即遍身疼，小腹时疼，小水淋涩而疼。脉两寸皆短，两关滑大，右关尤搏指，此梅核气症也。以半夏四钱，厚朴一钱，紫苏叶一钱五分，茯苓一钱三分，姜三片。水煎，食后服。每用此汤调理多效。（一百十七）", "6354": "溪亭子室，妊已七月。梦见亡过祖母，挥拳背打一下，惊醒即觉胎动不安，血已下，大小便皆急，腰与小腹胀疼者五日，此亦事之奇也。迓予为治。两寸脉俱短弱，此上焦元气大虚，当骤补之。人参、阿胶、黄耆、白术各二钱，当归、白芍、条芩、杜仲各一钱，砂仁、香附各五分，苎根嫩皮三钱，葱白六钱。一剂而血止，两剂诸症悉除，而神渐安。四帖后，减去苎根、葱白，调理旬日。足月而产一女。（一百十八）", "6355": "陈茂之，劳倦之后，勉强色欲，精竭而血继至。续感风寒，发热头痛，胸膈饱闷。始从太阳而传之少阳，胸胁痛而耳聋，哕逆口苦，咳嗽，六脉俱弦数，此少阳症也。以小柴胡汤加枳壳、桔梗、竹茹，而哕逆止，热退。因进粥早，复热口渴，小水不利，大便一日夜六七次，所行皆清水。日晡热甚，舌上黄苔，昏沉振颤。此食复之候。书云：渴而小便不利者，当先利其小便。以猪苓汤为主。猪苓、泽泻各二钱，滑石三钱，赤茯苓一钱，柴胡八分，升麻、木通各五分。连进两帖，小便利而大便实，但热不退，以六神通解散一帖，其夜热仍不退。次早诊之，左脉不弦数矣。两寸脉虚，以故服药无汗，口渴，漱水而不欲咽，咽热，此邪传阳明经，不急凉血，必作鼻衄。病势至此，可谓极恶矣。投黄芩芍药汤合生脉散，以止嗽渴。用葛根汤以解肌热。白芍药三钱，葛根、升麻、黄芩各一钱，人参一钱五分，麦冬、滑石各三钱，甘草、五味子各五分，乌梅一枚。急煎二帖饮之。日中大便下燥粪十数枚，始得微汗，就得睡矣。晚进粥一盂，夜卧向安。（一百十九）", "6356": "沈大参玉阳老先生，中焦有食积痰饮而作痞滞，以故大便了而不了，间或作胀。予脉之，两寸短弱，关滑，两尺沉滑有力。予曰：脾胃经有湿痰，蕴而为热，但清其中宫，使清阳升，浊阴降，而气血自旺，此不补之补也。以二陈汤加枳实、酒连、酒芩、滑石、姜黄、木香、干葛、山楂，两剂而愈。（一百二十二）", "6357": "王敬泉，头晕且痛，起则倒仆，胸膈胀闷如绳束缚，呕吐而食饮皆不得入，六脉俱涩，此痰饮挟木火之势而作晕也。先以济生竹茹汤而吐不止，且烦躁发呃、发热。再与芦根汤，连进二碗，气呃稍定。再以吴茱萸一两为末，以鸡子清调涂两足心，引火下行，外用二陈汤加姜汁炒黄芩、黄连、旋覆花、枇杷叶、丁香、白豆仁、槟榔、柴胡，水煎服之。服后热退，大便亦行，头晕呕吐皆止。惟胃脘有一块作痛，仍与前药两剂，而块亦消。（一百二十三）", "6358": "张二官发热头痛，口渴，大便秘结三日未行，脉洪大，此阳明少阳二经之症。用大柴胡汤行三五次，所下者皆黑粪，夜出臭汗，次日清爽，惟额上仍热。用白虎汤加葛根、天花粉。因食粥太早，复发热咳嗽，口渴殊甚，且恶心。用小柴胡加枳实、山栀子、麦芽。次日渴不可当。改以白虎汤加麦门冬、天花粉，外与辰砂益元散以井水调下五钱。热始退，渴始定。不虞夜睡失盖，复受寒邪，天明又大发热，不知人事，急用小柴胡汤加升麻、葛根、前胡、薄荷进之而汗出热退。神思大瘁，四肢皆冷，语言懒倦，且咳嗽。以生脉散加石斛、百合、大枣、白芍药，服后咳嗽寻止，精神日加，饮食进而向安矣。（一百二十四）", "6359": "大司马潘印川第三令子室，尚书蒋公孙女也。年二十五，体素弱，语言端谨。因难产伤力，继以生女拂意，后又女死悲戚，即时晕厥，醒而神思眯昧，手足瘛疭，目作上视。予更后始至，因瘛疭不能诊脉，细询之，自女落地，恶露绝无，比有女医在旁，乃昔所亲信者，时与人参大嚼，及独参汤并粥乱进，参与粥皆壅塞膈上不下，以故神昏瘛疭不已也。予教以手于喉中探而吐之，喜其随手吐出痰饮、粥、药盈盆，瘛疭方定。乃与川芎、山楂、泽兰叶、陈皮、半夏、茯苓、香附进之，稍得睡。予亦出中堂就寝，不虞女医又私与补药二帖。子丑时，陡然狂乱如降神之状，口中乱语云：我是观音大士降坛。所言皆儒雅官话，问答如流，声甚壮厉，殊无产后不足之态。生平不谙汉声，至是出语如生成者，人皆异之，目为神附，禳祷百般。予独净之，语诸左右曰：此恶露不尽，乃蓄血如见鬼之症，非真有神佛相附也。徐以正言叱之即缄默。继以清魂散加滑石、童便与之。至天明小水乃行，狂乱皆定。迨予出房少顷，讵知女医意欲要功，又不知与何药服之，少刻狂乱如前。再与川芎一钱五分，当归四钱，泽兰叶、益母草各一钱，临服加童便，连饮二帖不效。予逆思之，胸中必有余痰作滞，前剂中无佐、使之品，故药力不行也。即用前剂大加山楂与之，恶露稍行，神思即静，嗣后稍睡少时，手足微动，或自以手掌其面，或自以手捶其胸，昏乱不息。诊其脉近虚，早间面红而光，申酉时面色白，此血行火退，故脉虚而当补矣。与人参、川芎、泽兰叶各一钱，当归、山楂各二钱，茯苓、陈皮各八分，卷荷叶一片，煎熟调琥珀末子五分，服下半时许，嗳气二声。予喜曰：此清阳升而浊阴降矣。自兹安静，夜中恶露行，大便亦利，乃索粥饮。问其昨日汉声何来？答曰：不知也。诸君始信蓄血如见鬼之言为不诬。昔秦越人有言曰，病有六不治，信巫不信医一不治也。古称用药如用兵。以郭子仪之英明，而以鱼朝恩盐之，便不成功。予固非郭令公之俦，彼女医之误，则又有过于鱼朝恩矣。噫！宁不慎哉。（一百二十五）", "6360": "孝廉臧茗泉老先生，脉左弦数，右寸弱，关大，重则滑，右尺微。原以疟后复伤饮食，大便泻而变痢，一日夜虽只五六行，皆积滞无粪，腹疼后重难安。午未后发热，至天明始退，此夏伤于暑而秋为疟痢也。其热仍疟之余邪，当先解散，然后以补剂投之，则大便自愈矣。与神授香连丸一服。服讫，腹中肠鸣，须臾大便行，且较前更多，方有粪下。改以白芍药四钱，泽泻、黄连各一钱，滑石二钱，粉草、桂皮、木香各四分，山楂七分，两日后，乃与补中益气汤加木香、黄连、白芍药。调理半月，潮热、大便皆愈。（一百二十六）", "6361": "包继可先生令眷，孕三月而疟疾发，先寒后热，胸膈大胀疼，口渴，汤水入即吐，谵语，无汗，胎气上冲而成子悬。脉皆弦大，以川芎、柴胡、黄芩、知母、甘草、橘红、紫苏、枳壳、砂仁，水煎服之。吐止痛除。（一百二十七）", "6362": "一张氏妇，年才二十一，其夫延予诊之。左寸关短弱，尺滑，右寸亦滑，关濡弱，尺沉微。诊毕问予曰：脉何如？予曰：心神脾志皆大不足，肺经有痰。夫曰：不然，乃有身也。予曰：左寸短弱如此，安得有孕？夫曰：已七十日矣。予俯思久之，问渠曰：曾经孕育否？夫曰：已经二次，今乃三也。予问：二产皆足月否？男耶女也？夫曰：实不敢讳，始产仅九个月，手足面目完全，而水火不分，脔肉一片，生下亦无啼声，抱起已身冷矣。细检之，乃知其无水火也。次亦九个月，产下又无啼声，看时口中无舌。二胎之异，不知何故？闻先生能细心察人病，特祈审之。予方悟前二胎之不完者，由心脾二经不足所致也。今左寸右关之脉可见矣。乃为筹思一方，专以补心血为主，令其多服，以百帖为率。酸枣仁、远志、茯神各一钱，白术二钱，白芍药、当归、枸杞子各一钱五分，甘草五分，生地黄八分，艾絮二分，龙眼肉五枚，水煎服。足月而产一子。次年又有身，不以前事为意，至九个月，产下形体俱具，外有脂膜一片包其面，耳目口鼻不见，但不能去此脂膜。产下即殁。因思上年之子，为药之力也。因予久不至苕，其家以予方黏于壁间，一觉有身，即照方服之。后生二子一女。里中以此方为补天手云。（一百二十八）", "6363": "癸巳仲夏，吴比部凤麓父母，以次君弦台先生眼目红痛，恐学道按临，速于取效，乃听眼科罄寒凉而治，两越月无验。又眼科视之曰，目疾不宜多用寒凉，恐冰其血。以人参五钱，枸杞子一两，悉温补之剂。凡用人参、枸杞子五六斤矣。目肿如桃，绝不能开，又专科语之曰：红肿而痛，明是热症，误服温补，反助其热，宁不益肿。顾其势，即百寒凉亦不易瘳，捷径无如用下，此釜底抽薪法也。弦台惟其速效，一听下之，用大黄、芒硝、枳壳作大剂，下五六次，而饮食日减，恶心、畏风，则不能出房门矣。又专门谓前剂欠当，大泻之后，正合补也。又听补之。一补而目肿如旧，又有眼师云：目疾热症多，寒症少，只当滋补肾水，水升则火自降，火降而目疾斯愈矣。用是以滋阴降火之剂为恃，才数服而精滑不禁，一夜梦遗一二次，神气大脱。投补则目肿痛，用降则精元滑脱，屡试屡如是。诸医无策，悉谢而退。乃修书命使自淮阴之海阳，恳祝令君绍介，征予为治。予始以远为惧，祝再四为渠言，予亦素为渠重义，不得以远为辞，乃解行李向往。至即诊之，左寸脉甚短，右寸大而无力，左关弦弱，右滑，两尺亦滑。予见其坐在幔中，略不敢见风。问其日食几何？答曰三次，计二碗许，荤腥绝不能用。予曰：夜卧安否？答曰：迩来甚苦于睡，才合目即梦魇可畏，或被虎蛇交咬，或有鬼来勾摄，或落桥坠井，或与人争门而负。猛然惊悟，冷汗淋淋，四肢瘫软，不能动弹，少顷乃定。今幸公不远千里而临，足征素雅。予曰：足下始无大恙，只缘大推大搬，以致狼狈若是。彼专科者,不足恃也。经谓五脏精华皆上注于目。今专科局局然守其死法，安知五脏盈虚，阴阳消长，随时出入哉。以愚管见，但平平治之易与耳。据足下之脉，心神脾志互相不足，肝胆之火郁而不散，致生目痹。今为补养心脾，壮其神志，则饮食日加，寝卧安稳，而精元有守，神水盈溢，何目痹之不愈哉。弦台曰：善。惟先生命剂。乃以归脾汤减去黄耆、木香，加丹参而补心脾，以大安丸专助脾胃，而磨谷食。俾新痰不生，则气血可继日而旺矣。后五日而饮食加，十日而梦魇少。寻能出户，不畏风日，半月而肌肉生，目可观奕，津津然而有万全之兆。不虞专门张氏子复至，以白眼药日频点之，一日凡七八次，后此复不能开，睑肉风粟生满。适予有南都之往，卒为所误。后幸有李少塘，打去风粟，眼始能开。李虽手法精熟，然于轩岐阃奥，尚亦未窥藩篱。予后自南都至，见左目虽愈，右目终成内障。予故曰：彼专科者，不足恃也，岂虚语哉。（一百二十九）", "6364": "丘太守镇山翁令侄，淮阴人也。丁年患两手筋挛，指掉不能屈伸，臂肉瘦削，体瘠面白，寝食大减。市中诸友调治无验，乃任京口诸名家疗之半年，肉更消，色更瘁。闻予在吴比部衙中，敦予为治。诊其脉，六部俱弦，重按稍𫘝。诊竟，扣其受病之源，太守公曰：自上年冬底，偶发寒热，筋骨疼痛，迨于仲春，寒热虽退，而筋骨之疼不减。服药无虚日，甚之日三四进。肉渐消去，指掉不随，似有加于往昔。医之来者，一曰风，二曰风，三四五六皆曰风，即十数辈，又莫不皆曰风者。竭技尽方，卒无一应。奄奄床第，绝不知为何病。予对公曰：此筋痿症也，乃少年不谨欲而受风湿，邪气乘虚而入。医者不察天时，不分六经，概而汗之。仲景治风湿之法，但使微汗津津，则风湿尽去。若汗大出，则风去而湿存，由是血气俱虚。经云：阳气者，精则养神，柔则养筋。虚则筋无所养，渐成痿弱，乃不足之疾。故陈无择、朱丹溪、刘宗厚皆谓：诸痿切不可作风治，误则成痼疾。公闻言愕然曰：服风药几二百剂矣，顾今已痼，奈之何？予对曰：令侄青年，犹可图也。公曰：用何法？予曰：法当大补气血。经云：气主煦之，血主濡之。气血旺则筋柔而软，由是乃可以束骨而利机关也。抑何掉之有哉！病者闻言大喜曰：聆先生详病之源，治法之略，虽未服药，已觉沉疴去体矣！即请剂。予以五加皮、薏苡仁、红花、人参、鹿角胶、龟板、虎骨、当归、丹参、地黄、骨碎补、苍耳子之类。服两月，肌肉渐生，饮食大进，两手指掉亦平复。（一百三十）", "6365": "一书办，年过五十，糟酒纵欲无惮，忽患下消之症，一日夜小便二十余度，清白而长，味且甜，少顷凝结如脂，色有油光。治半年不验，腰膝以下皆软弱，载身不起，饮食减半，神色大瘁。脉之六部大而无力。书云：脉至而从，按之不鼓，诸阳皆然。法当温补下焦。以熟地黄六两为君，鹿角霜、山茱萸各四两，桑螵蛸、鹿角胶、人参、白茯苓、枸杞子、远志、菟丝子、怀山药各三两为臣，益智仁一两为佐，大附子、桂心各七钱为使，炼蜜为丸，梧桐子大，每早晚淡盐汤送下七八十丸。不终剂而愈。或曰：凡云消者皆热症也。始公具方，人多议之，今果以温补成功，此何故哉？予曰：病由下元不足，无气升腾于上，故渴而多饮。以饮多，小便亦多也。今大补下元，使阳气充盛，薰蒸于上，口自不干。譬之釜盖，釜虽有水，若底下无火，则水气不得上升，釜盖干而不润。必釜底有火，则釜中水气升腾，薰蒸于上，盖才湿润不干也。予已详著医旨绪余中，兹不多赘。（一百三十一）", "6366": "佥宪韩约斋老先生令子室，每动怒则夜卧不安，如见鬼魅，小水淋沥，今又大便秘结，腹中疼痛，腰胯胀坠如生产状，坐卧不安，因痛而脉多不应指。此肝经郁火所致，法当通利。以杏仁、桃仁各三钱，桕树根皮、山栀仁、青皮各一钱，槟榔五分，枳壳八分，水煎服之。少顷大便通，痛胀随减。（一百三十二）", "6367": "佥宪韩约斋老先生夫人，向来夜分脐腹疼极甚，必用炒盐熨之，两时久乃止。次日必头痛，两太阳如箍，遍身亦疼，此上盛下虚症也。先用柴胡、川芎、粉草、酒连、薄荷、天麻、橘红、茯苓、半夏、蔓荆子，水煎服。数帖头痛全止，惟咳嗽胸前略痛。两寸脉浮滑，两尺弱。再用鹿角霜、鹿角胶、补骨脂、远志、枸杞子、金铃子、香附子，炼蜜为丸，梧桐子大，每空心及下午食前，淡盐汤送下七十丸而瘳。（一百三十三）", "6368": "武进令君孙康字公子室，臧位宇丈女也。年十六，初产女，艰苦二日，偶感风邪，继食面饼。时师不察，竟以参术投之，即大热谵语，口渴，汗出如洗，气喘泄泻，泻皆黄水无粪，一日夜不计遍数，小水短少，饮食不进，症甚危恶。时当六月初旬，女科见热不除，乃投黄芩、芍药、黄连寒凉之剂，诸症更甚。又以参术大剂、肉果、干姜等止泻。一日计用人参二两四钱，泻益频，热益剧，喘汗转加，谵语不彻口，医各缚手辞谢曰：书云：汗出如油，喘而不休，死症也。又汗出而热不退，泻而热不止，且谵语神昏，产后而脉洪大，法皆犯逆，无生路矣。惟附子理中汤，庶侥幸于万一。适予为顾太守肖溪公延至，即过为一诊，六脉乱而无绪，七八至，独右关坚硬。踌躇久之，因思暑月汗出乃常事，但风邪面食瘀血皆未消熔，补剂太骤。书云：蓄血如见鬼。治当消瘀血、面食，解其暑气，犹可图生，勿遽弃也。有臧玉宇者，位宇堂兄也。医有雅致，深以予言为然，而速予措剂。予曰：剂凭症发，难拘常套，不常之症，须用不常之药。乃用益元散六钱，解暑气清热为君。仲景云：渴而小便不利者，当先利其小便。况水泻，尤当用之为君也。以糖球子三钱为臣；红曲、泽兰叶各一钱五分，消瘀血，安魂为佐；香附一钱五分为裨佐；橘红、半夏曲、茯苓，乃统理脾气为使；京三棱五分，消前参、术，决其壅滞为先锋。水煎饮之，饮下即稍睡，谵语竟止。连进二剂，其晚大便减半。次日仍用前剂饮之，其夜热大减，大便只二次，有黄粪矣。恶露略行黑血数枚。又次日诊之，脉始有绪，神亦收敛。进粥一盏，大有生意。前方减去京三棱、红曲，加白扁豆。其夜大便一次，所下皆黑粪。从此热尽退，大便亦实。改用四君子汤加益元散，青蒿、香附、白扁豆，酒炒白芍药、炮姜调理而平。（一百三十五）", "6369": "吴东星上舍，辰州太守公长君也。冒暑赴南都试，落第归而怏怏，因成疟。自八月中旬延至十月，疟虽止而腰痛白浊，日夜咳嗽，肌肉大消。药剂乱投，认为风者，以羌活、防风、续断等发散；认为虚者，以六味地黄丸为补；认为火者，以芩、连、栀子、黄柏、知母、天花粉、生地黄泻其火；认为半虚半实者，投以独活寄生汤；认为寒者，以大附子、肉桂、鹿角胶、参术温补之。痛剧欲死，叫撼四邻。予脉之，左弦细，右滑大，俱六至。口渴眼赤，予知其昔患杨梅疮，余毒尚伏经络，适因疟后气血不足，旧毒感动，故痛而暴也。以当归、芍药、甘草、牛膝、钩藤、苡仁、木通、白藓皮，用土茯苓四两煎汤代水煎前药。服下而痛止，咳嗽亦除，脉缓其半。连服数剂大效，精神渐复，乃起而督工视事。冬至日为酒兴鼓舞，纵欲无忌，次日腰如束缚，足面亦疼，左眼赤，小水短，足底有火从两胯直冲其上，痛不可言。予以当归、钩藤、甘草、白芍药、牛膝、苡仁、石斛、红花、生地、黄柏，调理三日，症已守定，略无进退。适大雪，寒冻殊甚，有女医为渠宅所亲信者，因其大便燥结，一日夜服玄明粉一两五钱，大便且不行，而腰痛愈猛，两足挛缩，气息奄奄，一语而三换气，面青惨，渠自觉危急，乃唤内人及弟叔嘱其后事。天明予至诊之，六脉俱伏，痛使然也。扣其由，乃知服玄明粉所致。予曰：症虽热，便虽燥，但公病不在肠胃，而在经络筋骨间，徒泻肠胃无益也。且冬月阳气闭藏，误泻则阳气亏乏，来春无发生根本矣。今四肢拘缩，腰胯痛剧者，由日来天令寒极，经络凝涩也。寒主收敛，法当温散寒邪之标，使痛定，然后复治其本，庶可保全。乃用桂心、杜仲、炙甘草、苍术、破故纸、五加皮，连与二剂，痛定而四肢柔和，饮食始进。予知渠宅素喜速效，予适有荆溪之往，乃宣言曰：足下之疾在经络，顾今天令严寒，幸宁耐以俟春和为足下拔去病根。渠宅不以予言为然，乃用张云溪调理，予亦赞张之可守，盖张氏药用养血清热，虽不去病，亦不害事。迨二月，太守公归，乃改用沈春宇，沈揣渠必以酒色而致阴虚。乃纯用滋阴降火之剂，以为旬日可奏功也。及调治月余，略无影响。予从荆溪归而谒渠，为三月初旬也。渠闻予至，即以沈药呈予，且语予：公许春和拔除病根，此其时也。予知太守公方笃信沈，随以温语慰渠曰：沈公名士也，可使彼展尽底蕴。沈又调理半月，以无功而行。沈去，予再以煨肾散进，大泻五六度，四肢冰冷，举家大恐，以予泻之为非也。予曰：病从此日减矣，夫奚忧。从进理脾药，服数帖，神气始转，腰胯柔和，可下床举数步矣。方始信而问予曰：人皆以补为治，公何得病源之真，于三月之前，先已预定，节节如公语也。予曰：此杨梅疮余毒伏于经络，岂补剂所能去哉。予故先为疏通湿热，然后以补剂收功，则无反复之患。后仍以威灵仙末子二钱，入猪腰子内煨熟食之。又泻一二度，病根尽拔。改用苡仁、当归、生熟地黄、白芍药、牛膝、黄柏、丹参、龟板，调理全安。（一百三十六）", "6370": "少司空凌绎泉翁，年已古稀，原有痰火之疾，因正月上旬，为令孙大婚过劳，偶占风寒，内热咳嗽，痰中有血，血多而痰少，痰坚不易出，鼻流清水，舌生芒刺，色焦黄，语言强硬不清，大小便不利，喘急不能睡，亦不能仰，惟坐高椅，椅前安棹，棹上安枕，日惟额伏枕上而已。市医环治半月不瘳，敦予诊之。两手脉浮而洪，两关滑大有力。知其内有积热痰火，为风邪所闭，且为怒气所加，故血上逆，议者以高年见红，脉大发热为惧。予曰：此有余症，诸公认为阴虚，而为滋阴降火，故不瘳。法当先驱中焦痰火积热，然后以地黄补血等剂收功，斯不失先后著也。翁以予言为然。用栝蒌、石膏各三钱，橘红、半夏曲、桑白皮、前胡、杏仁、酒芩、紫苏子，水煎，临服加入萝卜汁一小酒盏，一剂而血止。次日诊之，脉仍浮而洪大，尚恶寒。予曰：古云伤风必恶风，伤寒必恶寒，此其常也。只因先时失于清散，表中之热未彻，竟用滋阴之剂，又加童便收敛，降下太速，以致风寒郁而不散，故热愈甚也。改以定喘汤，一剂而喘急减半，再剂热退而不恶寒。复为诊之，两手浮体已无，惟两关之脉甚鼓指，此中焦痰积胶固已久，不可不因其时而疏导之。以清中丸同当归龙荟丸共二钱进之。其夜大便所下稠黏秽积甚多。予忆朱丹溪有云：凡哮喘火盛者，以白虎汤加黄连、枳实有功。此法正绎翁对腔剂也。与十剂，外以清中丸同双玉丸夜服，调理而安。（一百三十八）", "6371": "令郎采石先生，中焦湿热生痰，痞闷，五更倒饱，且下午两股或膝下筋脉抽掣疼痛，时常嗳气，面色带黄，间常梦遗。予以清气大安化痰丸，及猪肚丸二方调治而安。猪肚丸用白术五两，苦参酒炒二两，牡蛎煅过三两，为末，将雄猪肚子一具，摘去油，甘草汤洗过，将药装入肚中，缝其口，饭中蒸极烂为度，捣极匀为丸。此方极健脾去湿热，固精丸也。清气大安化痰丸用白术四两，橘红、半夏、山楂各三两，黄芩、黄连俱生姜汁炒，各一两五钱，枳实、栝蒌仁各二两，白芥子、萝卜子各炒一两，姜黄碱水煮干一两，青黛五钱，麦芽取曲打糊为丸，绿豆大，每食后及夜，茶送下二钱。（一百四十）", "6372": "闵文学蜃楼，患虚损咳嗽，昼轻夜重。乃政丁氏，长兴富翁女也。躯甚肥，性甚躁，患痛风，手不能沐栉，足不能履地。凡痛处略肿，呻吟喊叫。比有朱远斋氏，为时推重，夫好倚朱治者七越月，纤毫不减。吴九宜翁乃举予治。至其家，蜃楼大兄岳楼，旦暮与偕。诊毕，语岳楼曰：令弟之症，虽易见功，然非百日不能断根。丁氏症，十日便可刈其根，但恐不能尽五剂，奈何！岳楼曰：何谓也？予曰：令弟咳嗽，由肺火未清，误服参术太过而然。但为清肺利肺，咳可立止，止后以补心安神之剂养之，则万全矣。药用麦门冬、桑白皮、白药子、贝母、桔梗、甘草、黄芩、枳壳，十帖咳嗽全止。惟心血不足，神不固精，以酸枣仁、远志、麦冬、莲花心、丹参，调养百日，果能出户肄业。丁症乃湿痰凝滞经络作痛，朱公作血虚而投以地黄、芍药、当归、人参、牛膝之类，宜其痛愈加而病愈久也。今必须燥湿流动之剂，疏决一番，庶经络通畅。虽不服补剂，而五谷精华足以自充，但疏决之剂，不能止痛，恐其不余信而中止也。岳楼曰：先生既已言明，惟命是听。用二陈汤加乌药叶、苍术、僵蚕、海桐皮、南星、服至五帖，果不怿而欲止药。岳楼曰：孙君已先言十帖见功，今过半，何不勉强而使功亏一篑哉！又服一帖而止，百般强之不从。乃扬言曰：请医疗痛而反加痛，吾何药为，后四剂断断乎不敢奉命矣。时己申刻，予知其富家娇态，亦不强服。随以芫花醋炒过三分，海金沙一分为末，白汤调下。至晚泻一次，下稠痰半盆。足痛减大半，稍能动止。初更后吾辈酒犹未散，忽服云腹中大痛，促予进看。行至后堂，内中人出而止曰：病者卒矣，不劳进看。予曰：此必痛厥，非长逝也，乌可不进一看，至即冷汗淋漓，兀坐溺器，面青息断。执而诊之，手冷如冰，但六脉俱在，惟沉伏耳。知其为痛极使然，用生姜汤灌之而苏。徐语近侍女使曰：适来腹中痛甚耳，后火光溅出，肛门如焚，大响一声，不知泻下何物？众看之，乃血鳅一条，长六寸，阔半寸余，鳞目俱在，盆中尚能游动，众皆悚骇。岳楼问曰：此鳅下可好否？予应之曰：此尤物也，得下岂不好。但丁症实由痰作，予特为行痰，初不知其有虫，如是第药中有芫花，乃杀虫之物，故偶中，亦令弟之福也。次日手足皆动，仍以二陈汤加苡仁、红花、五加皮，四帖，脱然如故。闵宅以予不矜功而益重予。（一百四十二）", "6373": "金寄闲令堂，暑月患痢，小腹窘迫，胸膈膨胀，口舌焦渴。右寸关脉洪滑，左脉弦，乃气郁食积痢也。先与木香槟榔丸开而下之，微利一二度。因口渴食西瓜一片，即恶心而吐。昨日大便利后，胸膈宽快，就进饭一碗，致腹饱闷，兀兀欲吐，所吐皆痰涎。用以温胆汤加减治之，半夏四钱，枳实一钱五分，竹茹二钱，橘红、茯苓各一钱，甘草五分，姜连八分，生姜五片，水煎服之。一饮而胸膈舒畅，便能就枕而睡，恶心顿无，痢赤寻止。（一百四十三）", "6374": "徐中宇之妇，汗出如雨，昏昏愦愦，两手无所著落，胸要人足踹之不少放，少放即昏愦益甚，气促不能以息，稍近风则呕恶晕厥。与九龙镇心丹一丸，服下即稍定，少间则又发，始知胸喉中有物作梗而痛，汤水难入，即药仅能吞一口，多则弗能咽下。乃以苏合香丸与之，晕厥寻止，心痛始萌，昨日六脉俱伏，今早六部俱见，惟左寸短涩，知其痛为瘀血也。用玄胡索、桃仁、丹皮、丹参、青皮、当归、香附。其夜仍晕厥一次，由其痛极而然。再与玄胡、丹皮、桃仁、丹参、香附、青皮、乌梅、人参、贝母、桂枝、赤芍药，服此痛减大半。乃自云心虚，有热，头眩，加山栀仁。居常多梦交之症，近更甚，以其心虚故也。人参、石斛、丹参、贝母、当归、白芍药、酸枣仁、酒连、香附，调理全安。（一百四十四）", "6375": "金文学达泉先生令政，暑月患痢赤白，一日夜三十余度。后重腿急，口渴，小腹痛。孕已二月，幸而腰不痛。右手脉弦，左脉滑。与白芍药三钱，黄连、黄芩、当归、陈皮、香附各一钱，桂皮、木香各五分，水煎服。外与香连丸，服下后重稍轻。因进饭太早，其夜仍十数度。次早诊之，右弦减半。前药煎成，吞女金丹。一帖痢减大半，六脉已和，但软弱。此气血不足，宜从补养。用八珍汤加陈皮、香附、阿胶、条芩，一帖全安。凡孕妇痢疾，后重稍轻，腹痛稍减，独痢不止，必须补养气血为主，加调气之剂为佐，庶可保胎。斯亦丹溪虚回而痢自止之意也。（一百四十五）", "6376": "金元岩文学，下午发热，痢下红多白少，一日夜七十余度，后重下坠，饮食不思。左脉细数，右脉滑，此阴虚之候。询知二日前曾梦遗，续得痢疾，阴虚明矣。但滑脉，主食积。法当先补后攻。乃与小建中汤一帖，白芍药三钱，桂枝七分，粉草、酒连、酒芩各八分，当归一钱，槟榔五分，水煎饮之。夜半复诊，脉稍克指。改与枳壳三钱，桃仁一钱，当归四钱，煎熟，吞木香槟榔丸一钱五分。至天明大便泻三次，则见粪矣。次日午进饭，又食火肉，随即大便频，并后重如前。与山楂枳术丸一服不效。再为诊之，六部皆虚软无力，独右关滑，此进肉饭大早，脾弱不能消磨，宜健脾气兼为升举。人参、黄耆各二钱，白术一钱，升麻三钱，防风、藿香、炮姜、粉草各五分，白芍药一钱半，茯苓八分。连进两帖，痢减而后重宽。因食狗肉过多，复伤脾气。前方加砂仁、山楂，调理痊愈。（一百四十六）", "6377": "金文学达泉先生，因食肝白肠内伤，续又冒风，就成疟痢。日夜四十余度，小腹痛甚，每登厕汗出如雨，下迫后重，小水涩痛。头疼口渴，下午发热，天明始退。左脉浮弦而数，右软弱，中部稍滑。此内伤饮食，外感风邪，疟痢并作。法当速治，否则深秋阳气潜藏，邪因陷下，未易瘳也。乃先与柴苓汤一剂，小便即清，不痛。疟发时寒多热少。晚与人参败毒散加减。人参、干葛、防风、桂枝、粉草、茯苓、枳壳各五分，柴胡、白芍药各一钱，水煎饮之。次日头痛痢疾俱减，夜才起三次。改与补中益气汤加酒芩、桂枝、白芍药，其夜疟止，但微热。再改胃风汤，人参、白术、桂皮各二钱，白芍药四钱，当归一钱五分，茯苓、川芎各八分，酒芩、酒连各一钱，炮姜二分，地榆五分，服后寒热殄迹。夜起一次，已是真粪。前方减去桂枝，再三剂而巾栉出户矣。（一百四十七）", "6378": "金寄闲先生，七月既望，患头痛，口渴，汗大泄不敛，呕恶发寒热，间日一发，而发于阳日。乃为诊之，两寸洪大有力，左浮弦而数，右脉稍软，亦弦长。此少阳与阳明合并为疟。以柴葛解肌汤主之。柴胡、葛根各二钱，白芍药、石膏各三钱，粉草、桂枝各五分，知母一钱，姜三片，水煎饮之。次早左脉稍退。乃与补阴鳖血何首乌丸截之，又与黄耆芍药汤一帖，以防作痢。白芍药、石膏、黄耆各三钱，桂枝五分，知母、粉草各一钱，柴胡七分，姜三片，煎服。后加人参七分，疟竟全止而向安矣。（一百四十八）", "6379": "淮阴胡少泉翁，丽水县三尹也。令郎年弱冠患梦遗，百治不应。体倦而气弱，食少而汗多，四肢酸软，头眩，肌热，将成瘵疾。知予在理刑吴比部衙中，敦余为治。其脉两寸短，左寸尤甚，余部滑数。余曰：郎君之脉，心气大弱，盖心者，神之舍，神者，精之主。神旺始能固精。今遗不禁，由神弱不能固摄其精，致多妄泄。时近端阳，诸症丛集，乃兼注夏病也。法当养心安神，庶几不成瘵。翁曰：然，前此诸公，每为滋阴降火，多不见功，徒见损脾减食，今先生主以养神，愿以先生是听。乃与人参、黄耆、石莲子、酸枣仁、莲花心、石菖蒲、远志、当归补心安神为君。俾精固汗敛。经曰：汗者心之液。汗多则心血愈虚，故佐以甘草、白术、黄柏、麦门冬、五味子兼治注夏，使饮食加而四肢壮，缓而图之可万全矣。药进甚妥，竟以此方调理，果精固神全，肌热尽退。又令爱及笄，头痛微热，经水愆期，日多咳嗽，食渐减，肌渐消，口渴，睡卧不宁，喉中血腥，四肢不劳而疲，体不动而汗。六脉弦而且数，左关长出寸口。余以逍遥散加石斛、丹参、牡丹皮、酸枣仁、山栀子、麦门冬，调理而瘳。", "6380": "前丘一染匠之妇，腹痛两月矣。或以为寒，为热，为气，为虚，为食积，为虫，遽尝试之转加。一医与膏药如斗大者一个，满腹贴之，痛益剧。乃揭去膏药，即贴牢不可起，火熨油调，百计不能脱分寸，如生在肉上相类。无可奈何，知予在吴乡宦宅中，乃买舟就予诊。及抵吴门轿口，匠偕乃母乃姑四人尽力扶挽，绝不能动移一步。岸上环视如堵，莫不语匠曰：病势若此，时刻难抵，固乃强其起而欲污吾轿口耶，匠乃止妇舟中，起而恳予为治。至舟中，见其面色苍黑。及伸手求诊，皮肤燥若老松树皮之状。六脉皆洪数。问其腹中之痛何在？匠即为解衣露腹指其痛所，始知膏药黏牢之故，此甚希觏。叩其不能举步之由，妇曰：非力弱不能行，乃左脚不可动，动即痛应于心，是以一步不能举也。予俯思，若色若脉，皆非死候，胡治而益剧也。此必肠痈，左脚莫能举是其征也。与营卫返魂汤，加金银花为君，与四帖，酒水各一碗煎服。一帖痛稍减，二帖下臭脓半桶，痛全减。腹上膏药不须手揭，自脱而下。由热去而膏脱也。四帖完，其妇同匠诣吴宅拜谢予，并求善后之方。吴宅见之，一族皆惊。（一百五十一）", "6381": "王祖泉，大便里急后重，腹痛，日夜下紫黑稠黏三四十度。市中凡有名者，雷同痢治。自秋历冬，三越月不瘳。形色瘦瘁，匙箸厌举，即勉强，仅一盏而止，眼阖懒开，悉以为不治弃去。访予脉之，六部濡弱，观其所下之色甚晦，如芋苗汁之状。予曰：观此色，非痢，乃脏毒下血症。《医说》中人参樗皮散，正此对腔剂也。即制与之，其夜果减半，终剂全愈。方以人参、樗根白皮各二两，为末。每空心米饮调服二钱，忌肉汁、生菜、鱼腥。（一百五十二）", "6382": "癸巳秋仲，南都大司马袁洪溪老先生，以兼署工部都察院，操江印日，冲暑往来各衙门，而经略其政事，致发热燥渴。因解燥渴，而过食水浸瓜梨新藕，遂成泄泻，小水短少。医以胃苓汤加滑石、木通、车前子利之而泻止。大便又因之结燥，艰涩不堪。乃用润肠丸，复泻不止。又进以前通利之剂，泻虽止而小水竟不得流通直遂，脐下胀急。立起解之，则点滴不出，卧则流之不竭。以频取夜壶，致通宵不得寐也。治半月余，而精神削，寝食废。闻予寓崔勋部衙，而征予治。初见即告以受病之源。又谓都城诸医俱不识为何症，将认为癃，则立解时点滴不出；认为秘，卧则涓涓而流；谓为脾约，大便又不结燥；谓气虚下陷，心血不足，而补中益气汤与安神丸，服过十昼夜无益。雅闻先生高手，愿一诊以决之。探其脉，两寸短弱，关缓大，两尺洪大。语之曰：此余暑未解，而司马素善饮，湿热流于下部也。今已下午，恐诊之未准，俟明早细察而再定方。公曰：延颈吾子久矣，适所言近似，愿亟求一剂饮之，侥夜间一睡。予不得已，以益元散三钱，煎香薷汤进之，略无进退。次早复诊，六脉如昨。予思之而恍然悟。又语之曰：此症尿窍不对也。司马曰：名出何书？予曰：《内经）云：膀胱者，脬之室也。脬中湿热下坠，故立解而窍不对，小水因不得出，卧则脬不下坠，而尿渗出膀胱。亦以窍不对，小水虽涓涓而流，亦不能通达直遂，故了而不了也。治惟提补上中二焦元气，兼清下焦湿热，斯得矣。又有一法，今气虚下陷已久，一两剂未能取效，安得伏枕而睡。且此不寐，非心血不足之故，因著心防闲小便之了而不了而不敢寐也。暂将旧衣或布衬于席上，不必防而任其流出，又免取夜器而劳动其神，自然熟睡矣。以补中益气汤提补上中二焦之元气，加黄柏、知母，祛下焦之湿热。夫清阳升则浊阴自降，脬无湿热则不下坠，窍可对而病可瘳矣。司马忻然请药。夜如法衬之，果嗒然一睡，相忘其尿之出不出也。次早视衬布，虽湿而不甚。以久不阖目，得此一睡，神气顿回，胸臆爽快如未病者。调理四日而病全安。司马大喜，而欲留久住，缘漕运李公相延之亟，勿克也。差大马舡，鼓吹送予阡关而还。（一百五十三）", "6383": "崔百原公者，河南人也。年余四十矣，而为南勋部郎。患右胁痛，右手足筋骨俱痛，艰于举动者三月，诸医作偏风治之不效。驰书邑大夫祝公征予治。予至，视其色苍，其神固，性多躁急。诊其脉，左弦数，右滑数。时当仲秋，予曰：此湿痰风热为痹也。脉之滑为痰，弦为风，数为热。盖湿生痰，痰生热，热壅经络，伤其营卫，变为风也。公曰：君何以治？予曰：痰生经络，虽不害事，然非假岁月不能愈也。随与二陈汤加钩藤、苍耳子、薏苡仁、红花、五加皮、秦艽、威灵仙、黄芩、竹沥、姜汁饮之。数日手足之痛稍减，而胁痛如旧。再加郁金、川芎、白芥子，痛俱稍安。予以赴漕运李公召而行速，劝公请假缓治，因嘱其慎怒、内观以需药力。公曰：内观何为主？予曰：正心。公曰：儒以正心为修身先务，每苦工夫无下手处。予曰：正之为义，一止而已，止于一，则静定而妄念不生，宋儒所谓主静。又曰：看喜怒哀乐，未发以前，作何气象。释氏之止观。老子之了得一万事毕。皆此义也。孟子所谓：有事勿正、勿忘、勿助长、是其工夫节度也。公曰：吾知止矣。遂上疏请告。予录前方，畀之北归，如法调养半年，而病根尽除。（一百五十四）", "6384": "琼兄内伤饮食，外感风邪，洒淅恶寒发热，烦躁不宁，已经表汗泻吐之后，小水短赤，口渴，腹中疼，夜不能睡，耳聋气塞，神魂不安，懊𢙐不已。予脉之，两寸滑大，左关弦，右关滑，两尺皆弦，皆七至。据此乃少阳、阳明两经合病。仲景云：渴而小便不利者，当利其小便。先与柴苓汤加竹茹进之，耳稍聪，稍得睡，热仍不退，闻食气即呕，以济生竹茹汤加人参、麦冬、黄连，外与辰砂六一散三钱，服后神稍清，手足心仍热，用竹叶石膏汤，而热亦不退，且懊𢙐殊甚，合目即谵语。按仲景谓：伤寒汗吐下后，懊𢙐不得眠者，热在心胸之间，宜轻涌之。以栀子豆豉汤主之。服后晚间仍不得眠，两耳气塞难当。改以小柴胡汤合白虎汤进之，即得睡。睡中汗出二次，耳顿通利，因进食早，及发热口渴，舌上黄苔，此阳明余热复萌，乃用石膏七钱，甘草一钱，知母三钱，黄连一钱五分，百合、竹茹各一钱。竹叶三十片，急进而热全退，始得获安。（一）", "6385": "程龙丘翁，每行动即作热，发渴呕恶，腰与环跳常痛。脉左沉细，右寸滑，关尺濡弱。此上焦有痰火，下焦有湿热。治当流湿舒筋，然后施补。先用苡仁三钱，苍术、威灵仙、牛膝、黄柏、乌药叶、紫荆皮各一钱，红花、桂皮、防己各五分，水煎服。外以鹿茸、虎骨、晚蚕沙、仙茅、黄柏、龟板、苍术、牛膝、杜仲，蜜丸服之而安。（二）", "6386": "汪松岗翁，原伤于酒，夜分有热，咳嗽咯血，不思饮食，左胁气不调，左寸脉芤，关涩，尺弱，右寸短，关滑。此胃中痰火正旺，气血俱虚。宜先清胃保肺，然后大补。麦冬、知母、寒水石、甘草、紫菀、人参、牡丹皮、白芍药、当归、贝母、桑白皮，煎服一帖，红仍未止。加侧柏叶、茅根四帖而红止。过后四月，又为怒气所伤，血又动，左不能睡。桃仁、滑石、红花、当归、人参、贝母、山栀仁、甘草、香附、青皮、牡丹皮，煎服而安。予嘱渠令子曰：寄语令堂，诸凡得意事，可与尊翁知之，如不得意者，切不可使之闻也。盖肝为藏血之所，况血去多，肝火刚燥，心主不足。《内经》云：主不明则十二官危。不可不谨防之。且左不得眠，肝胀可知，予甚为尊翁虑。后三年果为怒复，乃命使迎予，予固辞谢曰：何曾叮嘱，今病之来，非不佞所堪任也。不逾旬而殁。（三）", "6387": "族妹经不行者八十日，每饮食入腹即疼痛，必尽吐出乃止，居常亦吐酸水。上焦热，下焦寒，大便半月始一行，食饮不进者四十日。六脉皆数，左滑，右软弱。妹能事者，以其夫多病，且不谙世故，由是悒悒，病从思虑而得，恐成膈症。今大便燥结，吐酸，乃膈之征，急宜拂虑，庶药有功。先与丁灵丸一粒而吐止，继用温胆汤，加大腹皮、姜、连，痛吐全安。改以二陈汤加香附、条芩、山栀仁、丹参、砂仁，调理两月经行，大便始润，而膈症斯不作矣。（四）", "6388": "孙华野，脉沉弦而数，喉痛颊车肿，两太阳作胀疼，遍身皆胀痛，憎寒发热。乃痰火上壅而变风热，将欲作毒也，宜急治之。薄荷、甘草、升麻、白芷、石膏、枳壳、天花粉、桔梗、大力子、连翘、玄参，一帖而愈。（五）", "6389": "显兄，每辛苦及酒多则咯血数口，脉二寸皆短弱，关尺洪数。此胃中有痰火，而下焦有阴火，由壮年酒色所伤故耳。以丹参、滑石各三钱，白芍药二钱，麦冬、贝母、桃仁、紫菀、牡丹皮各一钱，当归七分，甘草五分，煎服而安。（六）", "6390": "歙邑吴遂兄，木商也，在吴兴。年七十，因冒雨劳力汗出，又以冷水澡浴，因而发热，口渴，心与背互相胀疼，小水长而赤，舌上黄苔，夜不得卧，眼目如金，皮肤尽黄。吴兴之医见之远走，不敢措剂，谓其年高不宜此病，赞劝回家，乃敦访予治。诊得左脉浮数，右濡弱，两手皆有七至。予曰：此湿热发黄症也，病虽重，年虽高，有是症，当有是药，毋庸仓皇。乃以柴胡三钱，酒芩、葛根、青蒿、香薷、天花粉各一钱，人参七分，粉草五分。连进二帖，晚得微汗，即能睡。次早热退其半，舌苔稍淡润，不焦燥矣，胸膈余热作烦，身黄如旧。以竹茹、青蒿、葛根各一钱，人参、麦门冬、天花粉、知母各八分，白芍药六分。二帖热退食进，精神陡长。后与补中益气汤，加青蒿、麦门冬、天花粉。十帖而眼目肌肤之黄尽释然矣。吴兴诸公，悉服其精当，各录方而传。（七）", "6391": "族侄文学明之，以作文过劳，痰火上逆，大吐痰沫，因而哕血，一涌数碗，昏晕汗出，奄奄而卧，略不敢动，稍动即呕吐而血随出，色鲜红，饮食汤水皆不敢入，入即吐而眩运，血即随之。里有婺君程闻野氏为之诊，骇而走曰：血如涌泉，体热脉大，眩运而药食难入，似无佳兆。乃速予治。予诊视毕，语其乃兄勉之曰，可生也，何举家张皇若此！勉之以程言告予，予曰：看症要圆活，勿拘泥。据经云，心主血，肝藏血。又曰：怒则气上。又曰：脉虚身热，得之伤暑。今左脉弦大，右脉虚大，明之不独作文劳心动火，且亦被怒伤肝，抑又为暑所逼，以致木火上升，眩运作吐。经曰：诸风掉眩，皆属肝木。诸呕吐逆，皆属于火。又诸动属火，内为木火上冲，外为暑气所迫，故吐而汗多，血随吐出也。医贵识病，有是病则有是药。予特以白丸子三钱，解其暑气，清其痰饮，抑其冲逆，则吐可止。吐止气平，则血自能归经。服后果嗒然而睡。醒则吐止食进，眩晕寻已。继用滑石、香薷各三钱，甘草五分，黄连、白扁豆各一钱五分，竹茹一钱。四帖全安。（八）", "6392": "从嫂程氏，年近五十，患咳嗽吐臭脓血，一日一夜碗余，发热昼轻夜重，肌肉大瘦。六脉浮而洪滑且数，人皆谓呕血身热脉大，法在不治。予曰：此非吐血比也。此为酿酒伤肺，又为怒气所触，瘀血浊痰，滞于肺之气窍，无从而出，久之化而为脓，成肺痈也。治宜开肺窍，活血化痰，使脓尽，当自愈也。诸人治之二年不效，予教以白及、薏苡仁各三钱，牡丹皮、桔梗、茜根、归尾、山栀子、贝母、白芍药各一钱，甘草、葶苈子各五分，三十贴痊愈。后寿七十三，以他病而终，此疾再不复发。（九）", "6393": "族侄孙伍仲立年，善饮好内，小便血淋疼痛。予以滑石、甘草梢、海金沙、琥珀、山栀子、青蒿、茅草根，煎膏为丸，梧桐子大，每空心及食前灯芯汤送下三钱，不终剂而愈。后五年，因子迟，服补下丸药过多，血淋又发，小便中痛极，立而不能解，必蹲下如妇女小解样，始能解出，皆大血块，每行一二碗余，如是者半月。诸通利清热之剂，靡不遍尝不应。脉俱洪数。予以五灵脂、蒲黄、甘草梢各二钱，小蓟、龙牙草各三钱，水煎空心服，二帖而痛减半，血仍旧。改用瞿麦、山栀子、甘草各二钱，茅草根、杜牛膝、连叶车前草各三钱，生地黄、柴胡、黄柏、木通各一钱。四帖痛全减，血全止，惟小便了而不了，六脉亦和缓不似前矣。后以人参、葛根、青蒿、白术、茯苓、甘草、白芍药、升麻、黄柏、知母，调理万全。（十一）", "6394": "令眷辰州太守石峰公女也。吐红发热，经水二十日一行，或一月行二次，白带且多，胸膈饱胀，脉洪数。以丹参、生地、山栀子、白芍药、小蓟、鹿角胶，水煎，临服加入童便一酒杯，二十剂而瘳。（十二）", "6395": "侄孙少竹大学生也。眼红肿胀，余云谷以苦寒治时疾之剂与之，眼愈肿，且增两太阳痛。前药中再加石膏，不惟眼肿不消，头痛不止，且令遍身胀闷，寝食俱废。予为脉之，弦大而无力。乃用蔓荆子、桑白皮、柴胡、香附、夏枯草、甘草、芽茶，一帖而痛定，两帖肿消，四帖全瘳。（十四）", "6396": "华岳令堂，年五十余，向来小水短少，今则右背盐匙骨边一点痛，夜尤痛。已经半月，医治不效。辗转加剧，即于右边手臂肢节皆胀痛，筋皆暴起，肌肉上生红点子，脉两手皆滑数，右尺软弱。乃湿热伤筋而成痛痹。以东垣舒经汤为主。羌活、升麻、桃仁、麻黄、红花、当归、防风、甘草、独活、猪苓、黄柏、防己、知母、黄连，两帖痛减肿消，再亦不发。（十七）", "6397": "由溪程两峰丈内人，患血痢。里急后重，呕吐不纳谷，两寸脉洪大，以竹茹温胆汤，加姜连、滑石、橘红、酒芩，水煎服二帖，大便结实，脓血皆止，惟后重。与枳壳、当归、芍药、生地、桃仁、条芩、甘草、滑石、酒连，四帖全安。（十八）", "6398": "由溪程七护兄，脐腹右边疼痛，小水短少，大便四日未行，呕吐不能进食，舌上白苔，面青手冷，势甚危急。脉之左沉伏，右滑大有力。予曰：此痰格中焦，气闭下焦，故大小便秘而不利，气逆呕吐也。不急治即无救矣！与桕树东行根皮二钱，滑石三钱，桃仁、青皮、枳实、槟榔各一钱，水煎服之。夜半吐出胶痰碗余，大便未行，痛亦不减，次日改用玄胡索五钱，水煎，临服调下玄明粉三钱。辰刻服下，午刻痛减大半，未刻大便始行，右脉平而左脉起矣，觉体倦无力，以生脉散，加甘草、山栀仁、黄柏、芍药、苡仁、陈皮，调理如故。（十九）", "6399": "由溪程社贵兄，先醉酒，后御色，次早四肢冷，胃脘痛极。脉仅四至，先医以郁火为治，投以寒凉，痛更增极。三日前所食西瓜，仍吐出不化，乃翁以为阴症伤寒，欲用附子理中汤，不决，逆予治之。予观其面色青惨，叫痛而声不扬，坐卧烦乱。予曰：此霍乱兼蛔厥症也。先当止痛安蛔，后理霍乱，可免死也，迟则误事矣！急用五灵脂醋炒三钱，苍术一钱五分，乌梅三枚，川椒、炮姜、桂心各五分，水煎饮下。痛减大半，下午以大腹皮、藿香、半夏、陈皮、山楂、五灵脂、茯苓，两帖全安。（二十）", "6400": "孙熙宇肢节肿痛，痰多呕恶，胸中气不畅达，语言亦不清利，梦皆亡人野鬼追陪，精神惨恶，惊恐不安，且汗多不止，饮食减三之二，远近名家医治逾月不应。敦予为治。诊其脉，左手甚弱，汗多故也。右手滑大，痰饮湿热而然。法当补敛，前医皆作风治，而用疏散，泄其元神，将成柔痓。予以人参、麦门冬、五味子、白芍药、当归、苡仁、陈皮、石斛、木瓜、甘草、白术、桂枝，服此汗大敛而神思稍清，吐亦止矣。惟饮食不思，夜梦与亡人同游为恶耳。改用人参、黄耆、枸杞子、苡仁、白术各一钱五分，当归、远志、茯苓、木瓜、陈皮各一钱，甘草五分，水二钟，入雄猪心血一枚，煎作八分饮之，四帖乃能睡。始梦生人，不复梦亡人矣。（二十五）", "6401": "爱泉，上年十月因伤风咳嗽，即时声哑，继闻父丧过忧，右边不能帖席而睡。医以滋阴降火之剂，治之半年，肌肉大削，大便溏泻，饮食减少，咳嗽声哑有加。喉且疼痛。迎予为治。诊得六脉俱弦数，此忧伤肺，思伤脾症也。危急甚矣。以白术、茯苓、陈皮、粉草、苡仁、桔梗、柴胡、桑白皮、酒炒白芍药、泽泻、麦芽、山楂，煎服一日，再以荆芥、桔梗、玄参、甘草、茯苓、白芍、酒连、扁豆、山药、山楂、木通，服此而右边可睡矣。改用参苓白术散加白芍药、乌梅、诃子、酒连、山楂，调理而愈。（二十六）", "6402": "侄妇戴氏，有孕已五月矣，忽血大下，午后发战，六脉俱数，左寸滑大，右关搏指，左关软弱。予以白芍药二钱，生地、阿胶、人参、蒲黄各一钱，柴胡、香附、地榆、荆芥穗各七分，甘草五分煎服。午后发寒热，每夜凡三次，头痛恶心，腹中块硬，所下血块甚多，心下怯力，此虚无疑也。以补中益气汤加阿胶、炮姜、白芍药、乌梅煎服，下午右眼白珠发一白泡，光肿下垂，而面亦肿，此虚火游行无制之症。其夜大发寒热，指爪皆黑，唇白，汗大出，腹中作痛，牵引两乳皆痛。仍以补中益气汤加阿胶、白芍药、桂枝、五味子、麦冬，服后热退汗止渴除，神气稍定，乃有生气。次日咳嗽而胎坠，即以独参汤继服，其夜肠鸣泻二次，以人参、白术各三钱，炙甘草一钱五分，炮姜一钱，桂心、茯苓各五分，陈皮七分，莲子、大枣煎服。后因咳嗽，以四君子加炮姜、五味子、紫菀，调理而愈。（二十七）", "6403": "歙溪南吴人峰先生内人，两胁胀急，抵于胃脘作痛。痛一阵则汗出一番。两颧红，唇口亦红，饮食汤水，饮之立吐，不受者三日夜矣。予为诊之。两寸脉洪大，两尺沉微。予以井水半碗，白滚汤半碗和之，名曰阴阳汤，用此调玄明粉一钱五分，服之不惟不吐，痛减半矣。少顷大便行二次，因食豆腐及粥太早，而痛复萌，唇脸皆红，此必有虫故如是也。与白芍药、桂枝、粉草、乌梅、花椒、五灵脂、杏仁，水煎，痛乃定其大半。再与苍术、厚朴、山楂、枳实、茯苓、玄胡索、香附，一帖全止。但心背皮肤外疼，不能著席而睡。以川芎、当归、白术、厚朴、大腹皮、粉草、茯苓、香附、陈皮、半夏，调养痊愈。（二十九）", "6404": "程石洲乃眷，因产难子死，忧闷，小腹有块作痛，下午发热，不思饮食。次早诊之，脉右大于左者三倍，且数。与芎归汤，加糖球子、泽兰叶、肉桂。次日下午，腰腹胀痛，诘之，晌午食圆眼一斤矣。从此小腹渐胀，大便三日未行，早晨鼻衄，夜间极热口渴，脉大无绪，势甚危急。用川芎、当归、红花、桃花、桃仁、青皮、槟榔、莪术、山楂，水煎，调玄明粉二钱，服后大便稍行结粪二枚，安而就寝。醒后进粥稍多，又复胀痛，腹大如斗，坚如石，气促不安，势危至此，亦已极矣。乃与五灵脂、糖球子各四钱，凌霄花二钱，赤芍药一钱，服后大便通，腹软气定，始可进粥，渐有生气。但脉仍鼓指，此腹中积滞尚多，不可不因其时而驱去也。用糖球子、大黄各三钱，桃仁二钱，桂心、红花各五分，炙甘草七分，水煎，临服调玄明粉一钱五分，其夜下黑粪四次，热始退。上腹虽消，脐下仍大。仍以桃仁承气，加山楂、滑石、红花煎饮之。五更大便行，脐腹胀又渐减。后与积块丸调理全消。是役也，女流只知女科专门为仗，故前发热腹痛之时，彼专门不察虚实，即以常套十全大补汤投之。讵知圆眼肉初入腹之时不觉，少顷渐渐胀开，故腹亦因之而胀也。且其味甘，尤能作滞。复加地黄、参、术，宁不塞其塞哉。由是而成大满大坚之症。《内经》谓：中满者，泻之于内。良以此。夫彼亦泥乎丹溪产后，须当大补气血之误也。（三十一）", "6405": "文学程道吾先生令眷，夜为梦魇所惊，时常晕厥，精神恍惚，一日三五发，咳嗽，面色青，不思谷食，日惟啖牛肉脯数块而已。时师屡治无功。吴渤海视为寒痰作厥，投以附子、肉桂，而厥尤加。逆予为治。诊左脉弦，右脉滑，两寸稍短。道吾先令眷二，皆卒于瘵，知其为传尸瘵症也，不易治之。乃权以壮神补养之剂，消息调理，俟饮食进，胃气转，始可用正治之法。姑用人参、茯苓、柏子仁、石菖蒲、远志、丹参、当归、石斛，以补养神气。以陈皮、贝母、甘草、紫菀，化痰治嗽。服半月而无进退。乃为制太上浑元丹，药用紫河车一具，辰砂、鳖甲、犀角各一两，鹿角胶、紫石英、石斛各八钱，沉香、乳香、安息香、茯苓、紫菀、牛膝、人参各五钱，麝香五分，炼蜜为丸，赤豆大，每早晚盐汤或酒送下三十六丸。又制霹雳出猎丹，药用牛黄、狗宝、阿魏、安息各一钱，虎头骨五钱，啄木鸟一只，獭爪一枚，败鼓心破皮三钱，麝香五分，天灵盖一个，炼蜜为丸，雄黄三钱为衣，每五更空心葱白汤送下五分，三五日服一次，与太上浑元丹相兼服。才服半月，精神顿异，不似前时恍惚矣。但小腹左边一点疼，前煎药中加白芍药一钱，服之一月。精神大好，晕厥再不发矣。次年生一女，其宅瘵疾从此再亦不传。（三十三）", "6406": "参军程方塘翁，年六十四，向以殈㣧，服温补下元药太多，冬月下身著单裤，立溪边督工，受寒，致筋骨疼痛，肩井缺盆、脚膝跟踝、手肘掌后及骨节动处，皆红肿而痛，卧床褥三年。吴中溪视为虚而用虎潜丸，吴渤海视为寒而用大附子、肉桂、鹿茸。徐东皋认为湿。周皓认为血虚。张甲认为风。李乙认为历节。百治不瘳，腿间大肉尽消，惟各骨节处肿大而疼。予适在程道吾宅，乃逆予诊之。其脉弦涩有力，知其为湿热痰火，被寒气凝滞固涩经络也。节为药剂不对，故病日加。所取者，目中精神尚在，胃气仍未全损。但小水解下以瓦盆盛之，少顷则澄结为砂，色红而浊。两膝下及脚指，皆生大疮，疮靥如靴钉状。此皆平昔服温补春方所致。病虽久，年虽高，独为有余之疾。不可因高年疾痼，弃不治也。乃特为先驱逐经络中凝滞，然后健脾消痰。俾新痰不生，气血日长，最后以补剂收功，斯得矣。翁生平好补畏攻，故进门者皆务迎合，予独反之。以新取威灵仙一斤，装新竹筒中，入烧酒二斤，塞筒口，刮去筒外青皮，重汤煮三炷官香为度。取出威灵仙，晒干，为末，用竹沥打糊为丸，梧桐子大，每早晚酒送下一钱，一日服二次。五日后大便泻出稠黏痰积半桶，肿痛消去大半，改以人参、石斛、苍术、黄柏、苡仁、苍耳子、牛膝、乌药叶、龟板、红花、犀角屑、木通，煎服二十帖。又用前末药服三日，又下痰积如前之半。仍以前煎药服半月，又将末药服三日，腹中痰渐少，乃为制丸药。以虎骨、晚蚕沙、苍术、黄柏、丹参、杜牛膝茎叶、苡仁、红花、五加皮、苍耳子、龟板，酒打面糊为丸，梧桐子大，每空心白汤送下七八十丸。外以丹溪保和丸食后服。半年痊愈。腿肉复完，步履如故。（三十五）", "6407": "江东之丈，七月初旬自浙归，连日与客手谭过劳，口中生疮，医以香薷饮、清胃汤、泻黄汤、三黄丸、黄连解毒汤、白虎汤、凉膈散，凡治上焦热症之剂，竭寒凉而进之者十一日矣。口疮日甚一日，不但饮食不进，即药亦难下咽，因疮延及于喉也。逆予为诊，其脉六部俱豁大无力。诊罢，有外科陈氏者，自称喉舌专门，炫其口疳敷药之妙。予曰：汝试为口中一洗，看是何状，才开口，见涎沫迷漫不能得见肉色，陈以荆芥汤洗而引之，搅出稠涎一二碗余，倾于地上，偶有二鸡争啄之，二鸡立毙。其毒何如，此亦疾之奇者。予嘱陈曰：汝用药只可吹入喉中，切不可敷其必俟喉中全好，然后敷舌，待舌好，再敷口唇，甚毋得概敷，恐毒无出路，反攻入喉，极为误事。陈曰：诺。予对乃翁曰：令郎之疾乃虚阳口疮也。翁曰：当用何剂？予曰：附子理中汤，煎热待冷饮之可救，如它药，不能立功。翁曰：疮乃热症，况上身已热，又天时酷暑，大热之剂，其敢进乎？予曰：此阴盛格阳之症，初未尝如此，因服寒凉过剂激之使然耳，翁不看其两足膝下皆冷乎？翁用手探足果冷，乃欣然听用人参、白术各三钱，大附子、炮姜、炙甘草各一钱，水煎冷与之。服后即鼾睡达旦，次早便能食粥半盏，足膝下渐暖。药仍如前，早饭后予与二三友散步山溪，午刻归来，乃见举家大恸于地。见予至，哭语予曰：不可为矣。本是热病，误服热药，含舌肿大，塞满口中，不能言语，死在顷刻。奈何奈何！予骇然应曰：安得有是不祥语也，今晨诊脉，与昨不二，适往返不过二时许，何倏尔有此大变乎？待予再诊决之。及诊六脉渐敛，较昨大有神气，面色亦和，独舌胀大。予心知为陈寒凉敷药所致也。乃诘陈曰：我别后可用敷药否？陈点首曰：已二次矣。予抚翁及诸人曰：无恸，立看予为翁消之，急取官桂研末五钱，用生姜自然汁调涂舌上，才涂上，但见眼泪双流，鼻中涕出，口内涎垂，舌顿消去，语近侍曰：我无事矣。诸环侍者，男妇不下二十，皆面面相觑，以为神奇。予曰：可即取粥与食使压之，庶虚火不再升，适舌胀满者，乃敷药寒凉闭其毒气，毒无从出，故作胀耳。桂皮乃辛热之物，又以姜汁调涂，取辛散之义也。诸人皆服其论。（三十七）", "6408": "东之丈令眷，妊已六月，为伤风咳嗽，腹中吊疼，痰壅，喉音不清，头且眩运。脉左滑数，右寸弱，关滑，左尺有力，右尺弱。予以人参、白术、陈皮、贝母、茯苓、桔梗、桑白皮、紫苏、粉草、黄芩、前胡，四帖而病痊愈。（三十八）", "6409": "吴东渠，年五十又七，因上年患疟，胸痞作胀，肌肉大削，因连服攻克太重，脾胃败坏，膝跟踝皆浮肿，遍身发热口渴，小水短赤，舌上黄胎，舌心焦煤干燥，误服寒凉，大便连泻五六次，目不能开，手足无力，倦于言语。予诊之，六脉俱浮大，按之豁然空虚。饮食不进，此中气大虚，元神俱脱，可畏之甚。即以人参、白术、茯苓、粉草、木香、葛根、酒炒白芍药，水煎服之。连进二帖，始能开目，渐出声言语，后以六君子汤去半夏，加葛根、白扁豆、山药、藿香、苡仁、白芍药、石斛，调理而愈。（三十九）", "6410": "吴斗一丈，歙溪南人也。八月初旬，自新都往湖州途次，偶感风邪，发热多痰，且又腹痛下痢，里急后重。原有肠风下血之疾，又以旧年乃翁痢疾发热卒于湖州，心甚恐怖。予脉之，两关滑大有力，尽寸俱不足。乃以白芍药一半生一半酒炒，五钱，止痛为君；当归活血，酒连、酒芩、柴胡、桔梗，清热升提阳气为臣；枳壳、槐花，兼治肠风为佐；益元散、木香以实大肠；山楂以消瘀血；调肝安脾为裨佐。一贴热减半，痢稍轻。次日仍用前药，外与丹溪保和丸调理，五日而出户。（四十五）", "6411": "族侄云岳患偏坠，脐腹腰俞俱胀而痛，左关脉弦大鼓指。用小茴香、甘草、苍术、益智仁、防风各五分，荔枝核、橘核、糖球子、柴胡各一钱，山栀子、青皮各七钱，服后其痛如旧，脉且转数。恐作囊痈，急为解毒。栝蒌五钱，当归、甘草节、金银花各一钱，连翘、柴胡、青皮各七分，水煎服之。痛定肿消。因食鸡鱼太早，次日脐腹又作胀痛，发热不能睡，昨日囊消后弦脉尽退，今复弦矣。改以山楂、栝蒌各二钱，金银花、柴胡、连翘各八分，甘草节、黄连、当归各五分，青皮七分，两帖而愈。（四十八）", "6412": "一妇时方妙龄，表虚易感风寒，致成鼻渊，流清涕不止，便觉头晕，两太阳常作痛，且多喷嚏，脉之两寸洪大，用秦艽、酒芩、桑白皮、马兜铃各八分，白芍一钱，滑石、石膏各二钱，枳壳、蔓荆子各五分，甘草三分。四帖涕止病愈。（四十九）", "6413": "程两峰丈，偶与乃侄稍有介蒂，其晚饮于侄家，归觉腹中胀满，呕哕不宁，次日眼珠面色皆黄，恶寒发热。时当仲秋，正疟痢为疠之候，医作疟治，五心加热，下午潮热烦躁，似呕不呕，且鼻衄腹痛，大便黑如墨，吐出黑血如烂猪肺者然，约碗余，有谓所吐之物如此，大便之黑又如彼，似有中蛊之象，心疑乃侄毒之也。正欲与乃侄争辩，予仲子泰来适在渠宅，徐语渠诸郎君曰：尊翁症尚可起，顾不为救症，而务与人哄，何舍重而图轻耶！渠家素不急予，仍迓所亲信者率相视之，见目珠如金，面若熏橘，腹大如斗，其中有块大如碟，坚如石，两足下皆浮肿，四肢且冷，小水赤，饮食不思，莫不面面相觑，辞而不药。举家闻言，通宵号泣，惟欲攘臂争哄，仲子泰来又语之曰：家君固不敏，其知识量不出诸公下，昨自华阳归，迓而诊之，当必有说。举家欣然，敦予求诊，其脉左涩右滑。予曰：据滑脉主痰饮，涩主有瘀血也。今所吐所下皆瘀之征，断非蛊也，使得早从事，曷有此猜忌、此号泣哉！两峰曰：吾生平颇谨疾，瘀自何致？予曰：《内经）云：怒则伤肝，甚则呕血，不呕则积，积而瘀于经隧，满而溢也！两峰曰：若谓从怒而致，则此语恰当吾病源矣！敢请剂。予用当归尾三钱，赤芍药、牡丹皮、川芎各一钱五分，玄胡索、五灵脂、桃仁各一钱，滑石、茜根各二钱，水煎饮之。所下黑物甚多。腹中仍痛，块犹未软。前方再加青皮、山楂、酒蒸大黄服之，大便行三次，黑瘀及痰不计其数，从此腹渐宽，块渐熔，面色稍转，而黄日退，饮食津津有加，四肢微温，有生气矣。惟两足浮肿不消，改用六君子汤加炮姜、茜根、滑石、青蒿调理，而黑粪全无。一月精神复旧。里中谓予此役匪独认病投剂为足称，且俾二宅释猜疑，排忿争，其雅谊尤足重也。（五十）", "6414": "予有表嫂，小产后，腹痛晕厥，冷汗淋淋，遍身麻木，心怔怔动。左脉绝不应指，虚极故也。以当归三钱，川芎一钱五分，人参、荆芥穗，灯火烧存性各一钱，益母草、泽兰叶各八分，甘草五分，水煎饮之，腹痛减。惟怔怔不宁，以四君子汤倍加黄耆为君，当归、香附、益母草为臣，川芎为佐，炮姜为使，两剂而安。（五十一）", "6415": "陈士美，孤子也。年弱冠，由梦遗后患头疼发热。时值仲夏，医治不瘳。丹市中有名者，率延致，转治转热，反加水泻口渴，日夜不得眠者旬日，众视为危。时有俞氏者，用参、耆、白术为其敛汗止泻，而汗泻愈剧，呻吟不间昼夜，勺粒不入口，咳嗽胸痞，躁闷不宁，又四日矣！渠亲邵琼林交予，因凂邵逆予为治。诊其脉，左弦长，右洪大，俱七至，舌苔焦黄，体若火燎，神昏气促。予曰：此仲景伤寒热症也，邪在阳明少阳二经。其危不啻风中烛，胡时师不认症察脉，徒以梦遗受病，率投补剂，无怪乎转治转剧也。幸予至，设迟一日，大事去矣。用石膏五钱，柴胡、知母各三钱，炙甘草、白芍药、枳壳、桔梗、黄芩、天花粉各一钱，粳米一撮，急煎饮之。夜半热稍退，神稍静，脉之仍数甚，继以前剂进，天明乃得睡，觉而热退，神清，泻止，膈宽。惟口尚渴，再用柴胡一钱五分，白芍药、麦门冬、知母各一钱，石膏三钱，甘草、五味子各五分，人参七分，服之舌润渴止，余热尽退，粥饮始入，渐向安矣！忽两足指前一截痛如犬啮，不能耐，以野蓼一握，入明矾四两，煎汤薰洗，痛势稍缓。又以薏苡仁三钱，木瓜二钱，黄柏、牛膝各一钱，汉防己三分，一帖而愈。后又干咳嗽，昼夜不住口，喉且疼，胸胀而体略热，此为误服参术太早之过，用马兜铃、百部、御米壳，各用蜜水制过一钱，五味子、甘草各五分，百合二钱，四帖而愈。（五十二）", "6416": "程松逸兄患酒疽，遍身皆黄，尿如柏汁，眼若金装，汗出沾衣如染。胸膈痞满，口不知味，四肢酸软。脉濡而数，以四苓散加厚朴、陈皮、糖球子、麦芽、葛根，倍加青蒿，水煎，临服加萱草根自然汁一小酒杯。四帖，其黄涣然脱去。（五十三）", "6417": "太学岐原门下干人，名仲谏者，患跨马痈，大发寒热，红肿疼痛，呕恶不纳饮食，外科医月余，肿痛日加，饮食日减，肌肉日消，精神大惫，不能起止。岐原邀予脉之。六部数而无力，形气殊不胜息。时有专科唐氏，为渠调剂将进，予诘何剂？唐曰：真人活命饮也。曾服四剂，今始加大黄。予复诘曰：前此何剂？唐曰：败毒散、黄连解毒汤。予晓之曰：此皆治初起有余之疾，据今症仍气血大不足者，法当大补，托而出之，庶保终吉。唐曰：凡痛为实，痒为虚。今痛正盛，脉正数。饮食且不进，大补必加饱闷，饮食何由进，热毒何由出也？予正色语之曰：《素问》云：数脉所主，其邪为热，其症为虚。今痛极者皆由寒凉败毒之剂伤脾胃，凝气血，故饮食减而痛增也。又以败毒之剂进，是鸩之尔。安望脓出而全其生乎？唐曰：补剂迨脓溃之后，或因脓清而后用之。今脓未出，安可谓虚而补之？吾为专门，不敢任其责。予顾岐原曰：生死在此一剂，不可不慎。彼谓脓未出无补理。彼排脓内托散，十全大补汤，非外科急剂乎？大抵凡病宁使有余，后欲剥之，乃为易易，今狼狈若此，再株守成法剥削，后何以措手？岐原曰：井蛙之见，岂知有天，惟叔命剂。予用黄耆三钱，人参二钱，川芎、当归各一钱，白芷、官桂、甘草、防风各五分，急煎饮之。一帖痛止而精神回，饮食进，再剂而脓溃，十帖肉生能动止矣。唐乃拊膺，啧啧语同列曰：今而后知补剂能出脓而加食也。吾侪外科当永识此，以为法则。（五十四）", "6418": "一妇咳嗽，痰中有红，大便一日五、六度，恶心，饮食极难下膈。才下膈腹中即不安，立时欲泻，必尽泻出乃止。肌肉消瘦，下午发热。热将发时，四肢先麻，两足膝皆战摇，两寸关脉滑数，两尺沉细，此虚中有食积痰饮之候也！脉虽数，午后虽发热，不敢轻用寒凉，特为温补下元，庶关门有守，泻可止也。山茱萸、菟丝子、人参、破故纸、杜仲、山药、茯苓、泽泻、桂心、砂仁，服下甚安，四剂后，下体不战摇矣！但饮食腹中微疼，即欲登厕。前方减去山茱萸，加白术、肉果、木香，八帖愈。（五十五）", "6419": "族侄煌，春温后，忽鼻衄寒战，小水不利。舌上焦黄，目珠极红，六脉浮而不见。举室惶惶。予曰：此作汗之兆，由热极使然也。因先时汗未透彻，阳明余热在经，迫血上行，越出鼻窍，故有此症。以石膏、滑石、生地黄、升麻、赤芍药、牡丹皮、麦门冬、天花粉、甘草，煎而服之，汗出如雨，直至两踝。舌润而苔尽退，衄亦止，目珠色淡，脉乃渐出。改用人参、麦门冬、五味子、白芍药、甘草、知母、黄芩、柴胡、竹叶、石膏，服下，大便原五日未通，今亦始行，精神大转，饮食亦渐进矣。（五十六）", "6420": "富昨汪氏妇，对河程门女也。年仅三八，经不行者半载，腹大如斗，坚如石，时或作痛，里医尽技以治，月余弗瘳。乃举歙友为翼，又治月余，腹转胀急，小水涓滴不通。乃仿予治。孙仲暗法，而用温补下元之剂，则胀急欲裂，自经求尽。文学南瀛怜之，荐予。诊其脉，两关洪滑鼓指，按之不下，乃有余之候也。症虽重，机可生。询其致病之源，由乃姑治家严而过俭，其母极事姑息，常令女童袖熟鸡牛舌之类私授之，因魆食冷物，积而渐成鼓胀。前任事者，并不察病源，不审脉候，误作气虚中满治之，胀而欲裂，宜其然也。乃用积块丸三下之，而胀消积去。后以丹溪保和丸，调养一月而愈。积块丸列《赤水玄珠》第五卷虫蛊后。（五十七）", "6421": "族侄孙仲登，因与堂兄构讼，城中方归。时值二月末旬，醉后房事二，起而小溲，随即脐下作痛，水泻肠鸣，一日十数度，发热头痛。里医进理中汤一帖，反而呕逆烦躁口渴。敦予诊之。左脉弦大，右洪大，俱七至，饮食不能下咽，昼夜不得睡，面赤唇燥，舌上黄苔深厚，诊毕语予曰：我房失后，阴症伤寒也。小腹痛，且漏底，幸叔祖救之。予笑而应曰：以子所言，决为阴症，以予指下辨之，当是春温阳症也。且外症亦阳，乌得为有房事而遽以理中进之乎！族中相知者，交为予言，渠病的属阴症，故呕吐水泻，不可因其面赤便认为阳，顾戴阳症与此近似，幸加察之。吾辈正拟于理中汤内再加大附子、肉桂，庶可保全。予极言不可。仲景有云：桂枝下咽，阳盛则毙。况附子理中者乎！阴阳寒热之间，辨之不真，生死反掌耳！兹当舍症而从脉也。以温胆汤加姜汗炒黄连，柴胡，干葛，与二帖。嘱令当夜饮尽，俾明日不它传也。予别后，渠一服而呕逆止，余症悉在，诸朝予诊，竞扣渠曰，夜来二药必未服完，不然何两手之脉洪大搏指如是。佥曰：因有竹茹、黄连，恐非房失后所宜，故仅服一。予曰：不服黄连，致热转剧，今日非石膏不能已。乃与白虎汤加竹茹两剂。临别嘱渠曰：今症非昨日可比，用石膏者，岂得已哉。设当用不用，使经中之热传入于腑，非大黄不能瘳。切勿失时误事。讵知别后，又有惑之者，仍只服一帖，泻即随止，余小腹之痛具在，次日，予诊毕，语渠曰：昨临行时嘱之再三，何乃又不服完？今脉洪长坚硬，邪已入腑，奈何奈何！对曰：众谓石膏太寒，恐小腹加痛，实只服一帖而已。予曰：惧服石膏，今且服大黄矣！皆失时误事之过，周金人铭云：荧荧不灭，炎炎奈何，其斯之谓欤！思非桃仁承气汤不可，乃觌面煎服，连饮二剂，下极黑燥粪五六枚，痛热俱减。再为诊之，六脉皆缓弱，迨是病方尽去，改以四君子汤加白芍药、黄连、香附，调养数日而愈。（五十八）", "6422": "汪希明，竹山丈长君也，年弱冠，性多躁，素有痰火，旧曾吐红，张医用收涩之剂太早，以致痰与瘀血留滞经络，酿成病根，恬不知觉。且为灸肺俞、膏肓，撼动前疾，止涩无功，滋阴作壅，咳不能睡。又误作风邪，而投散发风剂。不思火盛得风，其势愈炽。血从口鼻喷出，势如泉涌，延予为治。六部洪数，身热而烦，又时当三伏，内外之火恶夹攻，纵体质刚劲，宁能堪此销铄哉！予思，非釜底抽薪之法，难夺其上涌之势。乃以三制大黄三钱，石膏五钱，黄连、茜根、滑石各二钱，牡丹皮一钱，急煎饮之。大便微行二次，血来少缓，即用石膏、滑石、冬青子各三钱，旱莲草、茜根各二钱，黄连、山栀子、贝母各一钱，甘草五分，茅草根五钱，煎服，血乃全止。三日后大便结燥，火又上逆，咳咳连声，左关脉弦劲，右关洪滑。与当归龙荟丸下之，而咳始缓。改以栝蒌仁、茜根各一钱五分，贝母、旱莲草、麦门冬、知母各一钱，白芍药二钱，黄连、黄芩各七分，青皮、甘草各三分，仍加茅根，后每遇大便燥结，即进龙荟丸，迹此调理，三月大定，半载全瘳。书云：病有六不灸，火盛者不灸。此由误灸。几于不保，故特识之，以为好灸者龟鉴。（五十九）", "6423": "德兴文学祝弘吾公，祝令君叔祖也。在休衙偶有阴阳之患，子午潮热，咳嗽痰多，汗流不止，胸膈不畅，大便燥结，动作喘乏，口渴。以贝母、知母、栝蒌仁、桑白皮各一钱，枳壳、黄连、麦门冬各八分，桔梗、柴胡、前胡各五分，甘草三分，五味子十一粒，服下，五更微汗，热退十之七，惟痰嗽喘乏，改用栝蒌仁二钱，余如前，外以七制化痰丸夜服，热尽退，渠甚喜，以为自是以往，可勿药矣！予曰：未也，据脉弦数不减，恐防作疟，公未为然。予适东行半月，书报疟作，咳嗽转加，所出皆黄黏老痰。予曰：书云无痰不作疟。仍用前方，倍加柴胡、贝母为君，加乌梅一个，四剂，霍然良已。公曰：翁之视疾，应若桴鼓。古云：智者不治已病治未病。吾于翁言征之，乃以是备言祝令公，祝令公喜曰：孙君匪独得岐黄正脉，其雅谊足称，祖叔尚未前闻，予当赋诗以赠，由是欣然手书若干律，以授予。其诗附后第六卷。（六十）", "6424": "汪炼兄内人，经水久不止，内有紫黑血块，今则胃脘胸腹皆痛，玉户且肿，手足皆冷，绝不知饿。脐腹之下有一块，坚如铁。脉左数右沉涩，此血瘕症也。用糖球子五钱，玄胡索、五灵脂、香附、麦芽、青皮各一钱，水煎服。夜即痛减其半，手足渐温，后加丹参、川芎、蒲黄、益母草、当归，四帖而痛全止，玉户亦消，再四帖而经调。（六十二）", "6425": "程相如丈令政，孕四月，头疼，遍身皆痛，腰痛更甚，恶寒发热，咳嗽口渴，六脉浮数。以小柴胡汤加防风、羌活、葛根、姜枣煎服。夜忽大发寒战，继而发热，五更又发战，告急于予。予曰：此作汗之兆。俄而汗出，口渴头疼身热皆减，惟胸膈胀闷，此胎气上逼而为子悬。以大紫苏饮与之。紫苏、人参、白术、茯苓、甘草、当归、陈皮、大腹皮、川芎、白芍药，服后身冷而汗出不止，胸腹胀痛。急以夺命丹进，服下嗒然而睡，觉则痛止胀消。始进饮食，身温汗止，骎骎向安，夺命丹用白茯苓、牡丹皮、桃仁、白芍药、桂枝，醋水煎服，止痛如神。（六十三）", "6426": "余文台，壮年咳嗽吐红，腹中常痛，夜多口渴，梦遗，背心作胀。两手脉短弱，两关弦大，左尺弱，右尺滑大。心血不足，中焦有痰积，膈间有瘀血，阴分有淫火。乃先为清肃上焦，用山栀仁、牡丹皮、丹参、茯苓、甘草、贝母、橘红、益元散，服十帖，背胀渐消，惟咳不止。改用黄芩、杏仁、半夏曲、益元散、黄连、栝蒌仁、甘草，十帖而嗽止。惟腹痛不除，再以遇仙丹，同丹溪保和丸进之。大便下稠积痰甚多。后以人参、白茯苓、白芍药、紫菀、知母、麦门冬、甘草、当归、五味子，调理而愈。（六十四）", "6427": "金氏妇，苏双泉之亲妈也。旧秋患崩中，愈后方百日，时值上巳，因洗浴受风邪，外寒而束内热，前后心胀，四肢肿痛，面有浮气，恶寒发热，呵欠不时，大小便欲行不行，口内常甜。六脉浮大而数，以柴胡、紫苏、麻黄、桔梗、枳壳、大腹皮、厚朴、酒芩、姜黄，服下，夜得微汗，胸腹稍安。四肢仍胀，再加萝卜子进之，觉烦躁，且醋心。改用二陈汤，加香附、大腹皮、桑白皮、姜连、枳壳、山栀子各八分，益元散二钱，薏苡仁三钱，吴茱萸三分，服下，四肢消半，面气全消，觉腰痛嗳气胸膈嘈辣。用六君子汤，加薏苡仁、姜连、厚朴、知母、泽泻、郁金、砂仁、枳实，调养半月，四肢悉平，嘈杂寻愈。（六十六）", "6428": "文学张云门三令郎，丁年偶发寒热，右胁有一块，降起疼痛，手不可近，下午至夜尤甚，额颅手心皆热，脉右关洪滑，两尺尤有力，日夜不得睡。乃仿推气散例，姜黄、桔梗、川芎各一钱五分，枳实二钱，白芍药一钱，粉草五分，姜枣煎服。外与当归龙荟丸。其夜大便行一次，颇得睡，三更后，先发寒战，徐热，至五更微汗，而胁痛寒热悉减。再诊之，左脉略弦，舌有黄白厚苔，两胁重按微疼，大便燥结不行。以小柴胡汤减半夏，倍加栝蒌、鳖甲、牡蛎，胁痛全瘳，睪丸略硬痛，彼自以为无恙矣。予语渠姐夫徐仲子伟曰：病先起胁下，顾胁下为肝之经，后及睪丸硬疼，其睪丸肝之地，此余热未尽彻故也。而彼已厌药，以小愈为全安。不出浃旬，必有奇疾。徐仲子曰：奇者若何？余曰：此君性急好胜，倘勉强作文，遇劳而发，憎寒壮热，非疟即囊痈也。予倘东行，子宜识之。别后半月，果因作文，夜发寒热，囊渐肿大，其热如火。及予至诊之，六部皆数，两尺且近于洪，知其脓已成，必溃而后已。彼心甚恐，予曰：无伤，易与耳！急以营卫返魂汤，加金银花为君，两帖而脓溃。再加人参，又两帖而肌生。十日痊愈。方用何首乌、赤芍药、当归、小茴香、甘草节、木通、金银花、贝母、枳壳、白芷，水与酒共煎服之。此方加独活，治流注尤神。（六十七）", "6429": "朱宅内眷，孕已八月，因送殡受惊，胸膈胀闷，呕逆不入食。城中时师认为外感，为之发散，呕恶愈剧。举家恐胎有动，延予诊视。两寸脉皆洪滑，两尺弱，此亢上不下之候。胸膈胀者，盖由于悬而然，此一剂可瘳也。夫曰：胎妇难任峻剂，觑其呕恶之状，胀闷之势，时刻不止，一剂曷愈？予曰：请试之，与温胆汤，加姜汁炒黄连、大腹皮，水煎成，送下姜汁益元丸，果一帖而呕止膈宽，即能进食，午后酣骎，怡然若未始有病者。其夫讶曰：温胆汤何神若此？幸详其义。予曰：胎孕之症，重在足少阳，足少阳者胆也，病起于惊，气逆，痰随胎气上逼，故脉亢上不下。《难经》为溢候，由木火之性上而不下。经曰：上部有脉，下部无脉，其人当吐，不吐者死。予故云一剂可愈也。方名温胆者，此温字非温暖之温，乃温存之温，黄连、竹茹，清其肝胆之火，同白茯苓而安心神，益元丸压其痰火下行，火下行而胎因之亦安矣！筠皋公曰：先生认症真，故投剂确，非神乎药，神乎用也。（六十八）", "6430": "胡邻泉令媛及笄后患吐血，每吐碗余，下午倦怠，夜分潮热，呕吐不食，大便秘结。时师视为阴虚火动，投以滋阴之剂，反加饱闷，背心胀痛。予诊其脉，两寸洪大，两尺弱，知其有瘀血凝滞，以致新血不得归经，故满而溢也。法当消瘀为主，用白芍药、枳壳、前胡、益元散、桃仁、红花、牡丹皮、山栀子、贝母水煎，临服入萝卜汁一小酒杯。服后呕吐如旧，大便仍秘，乃以龙荟丸通之。更以石膏三钱，橘红、半夏曲、姜连、茜根、竹茹、黄连、枳壳各一钱，白茯苓八分，甘草三分，服后大便行三次，吐止食进。后用二陈汤，加滑石、丹参、丹皮、茜根、白芍药、香附，二十剂后，经行热退，背胀悉愈。从此经调，血不上逆。（六十九）", "6431": "族侄孙君实，壮年患遍身筋骨疼痛，肢节肿痛。其痛极，状如虎啮，大小便起止，非三五人不能扶，诸痛处热如火燎，食饮不入，呻吟床耨，已经二候。有以疏风之剂投者不应，又以乳香、没药、活血止痛之剂投者亦不应。延予诊治，六脉浮紧而数。予曰：此周痹也。势甚恶，俗名白虎厉节风，乃湿热所致。丹溪云：肿属湿，痛属火，火性速，故痛暴猛若此。以生地黄、红花、酒芩、酒连、酒柏、秦艽、防风、羌活、独活、海桐皮、威灵仙、甘草，四剂而痛减大半。再加赤芍药、当归、苍耳子、薏苡仁，减去独活、秦艽，又八剂痊愈。（七十一）", "6432": "叶子黑内人患疫，医为其汗，为其下，罄技不能起，尸骎者已浃旬。家事窭乏，亦不能复迎医，邻人睹其状，以生死在须臾间，群然发善愿，科敛助其殡敛之需。予闻为之诊，六部俱微弱不充指，右关稍滑，精神昏惫，仅一息奄奄，四肢冷厥，口渴。予诊毕语诸邻曰：据症甚危，据脉邪已尽退，惟虚惫而神气弱，非大补不能也，诸君苟能以助殡者助其市人参，庶几可起死而还之生也。诸君既怜其死，宁不以冀其生乎。予非毫有希觊，顾渠力不足赡，愿与诸君共圆满好生善果耳。诸邻固有善心，激于予言，益忻然相语曰：惟先生命。即以六君子汤加归芍，补气血而化痰涎，以麦门冬、五味子，复脉通心而生津液。以桂枝温其四体。午刻进药，晡刻四肢渐暖，精神涣发，尚无力开声。改以生脉汤，加远志、归、芍、苡仁、山药，调理而愈。诸邻人大快。（七十二）", "6433": "孙如亭令政，年过四十，眼偶赤肿，两太阳疼痛，大便不行者三日。平时汛期一月仅二日，今行四日，犹且未止。里有开化余云谷者，自谓眼科捷手，医治逾候，肿亦不消，而右眼内眦突生一白泡，垂与鼻齐，大二寸余，余见而骇走，以为奇疾，莫能措剂。又见其呕吐眩运，伏于枕上，略不敢动，稍动则眩愈极，吐愈急，疑其变而不治。予为诊之，两寸关脉俱滑大有力，两尺沉微，予曰：此中焦有痰，肝胆有火，必为怒气所触而然。《内经》云：诸风掉眩，皆属肝木。诸逆冲上，皆属于火。盖无痰不作晕也。眼眦白泡，乃火性急速，怒气加之，气乘于络，上而不下，故直胀出眼外也。古壮士一怒而目眦裂，与白泡胀出眦外理同，肝为血海，故血亦来不止，治当抑其肝木，清镇痰火，则诸症自瘳。行用姜汁益元丸，压其痰火，以止其吐，再以二陈汤加酒连、酒芩、天麻、滑石、吴茱萸、竹茹、枳实，煎饮一帖，吐止运定，头稍能动。改用二陈汤加芩、连、谷精草、香附、夏枯草、吴茱萸、薏苡仁，两剂赤肿消，白泡敛，四剂痊愈。血海亦净，从是后不发。（七十三）", "6434": "吴勉斋年近五十，有腹痛疾，或作或止，性极急，多躁多怒，今痛在当脐，不间昼夜。市里医者为下之，已五日，大便虽泻，痛则尤甚，饮食不进，手足清冷，形神俱倦，脉仅四至，重按则伏而有力，此由攻克太过，寒凉伤脾，脾虚则中气不运，积反凝滞，以故大便虽泻，而积不行，痛终不减也。治当建立中气为主，中气一回，痛当立止。先与海藏五神丸二钱，滚水送下，以止其痛。此丸补接元气，安和五脏，升降阴阳，极有神应。故名五神丸（方出《医垒元戎》第十卷中）。再用小建中汤，调肝养脾。盖脐下乃肝经部位，惟此汤乃对症剂也。白芍酒炒三钱，炙甘草一钱五分，桂心一钱，加香附一钱，生姜三片，水煎服。午牌进药，未牌已报痛止。因其夜进粥太频，且食鸭汁，撼动余积，腹又作痛，且加胀闷，面有浮气，里急后重。与四平丸而渐定。外以二陈汤加香附、砂仁、苍术、厚朴、山楂，腹中始觉宽快，三日无恙。又纵恣口腹，大啖肥甘糕粽肉鸡之类，不饱不止，腹中大痛，时刻难存，欲吐则食已下膈，欲泻则食尚未入腹，自喊叫云，可取木香槟榔丸、大承气汤，急与我下之，虽死无憾。予谕之曰：据痛虽甚，腹则不坚，顾今日适届冬节，礼曰：先王于至日，闭关安静以养微阳，曷敢以大寒峻剂而泪天和乎？设不得已，只须桕树东行根上白皮一钱，长流水煎饮之，一服可愈也。夜已二鼓，觅而煎服，天明泻三五行，痛减大半。仍以小建中汤和之，痛又旋减，惟脐下尚不脱然，常常以热手重熨之，大便欲行，及至厕，又不解，知其血少而气不调。用熟地三钱，白芍一钱，杏仁二钱，乌药一钱，木香五分，水煎饮既，下黑粪甚多，十年腹痛沉疴，从此再不复萌。此后勉斋常语人曰：吾得孙公五神丸，桕根皮，小建中汤三法，不啻脱胎换骨，数年来，岂惟饮食增加，即步履轻便，捷若少壮，皆孙君赐也。亲友有求其三法者，畀而服之，捷若桴鼓，彼家谓予殆三生夙缘云。（七十四）", "6435": "黄颐斋内子，产未弥月，醉犯房事，血来如崩，势不可遏，发热头晕，大小便俱热，六脉洪大。以竹茹、蒲黄、白芍药各一钱，香附、茯苓、侧柏叶、青蒿各七分，甘草、炮姜、艾叶各三分。血止大半，腰犹胀痛，下午胸膈饱闷。改以川芎五分，当归、茯苓、破故纸、蒲黄、香附各八分，姜炭、甘草各一分，陈皮七分，人参一钱，服此血止，腰痛亦愈。（七十五）", "6436": "程心章兄，颊腮红肿，呕恶发热，不能进食，下午烦躁，口苦，夜不能睡。六脉洪大，此欲名鸬鹚瘟是也。乃少阳阳明二经之症，法当清解。以柴胡、贯众各二钱，干葛、竹茹、半夏曲各一钱，黄连、枳壳各七分，甘草四分，一帖而瘳其半，再服，肿消食进而安睡矣。（七十六）", "6437": "上舍近洲，予族中至厚侄孙也。性拓落，豪放不羁，夏仲在苕，与诸友泛舟游于碧浪之间，兴至，即百觥不辞，亦以是终为酒困也。呕恶体热，胸胁胀闷，腹中疼痛，大便秘结，饮食大减。苕之名医，如杨调元者，桥梓悉方治之已三月，或愈或否，延至深秋，肌瘦神瘁，日进米仅二合，胸胁胀，腹中痛，漠然略无所减，懑然而不可支，两足皆有浮气，归谋于予。左脉沉弦而数，右关结实，大如碧豆，因诘其在苕所服之剂。答曰：彼谓侄孙禀薄肌脆，宜当理脾，向服多理脾之剂。予曰：否，子所苦者，胸胁胀闷，腹中疼痛，大便燥结，其累大矣！理脾曷可以去此哉？适足以益病耳！经曰：塞者通之。又曰：通则不痛。其治此病之谓欤！乃取当归龙荟丸三下之，大便行五六度，又与酒连、酒芩、青蒿、姜黄、槟榔、青皮、半夏、葛根饮之，豁然停膈通达，呼吸开利、惟头略晕，足上浮未去，前方再加滑石、茯苓、薏苡仁、山楂，与调中丸兼服，半月痊愈。近洲喜曰：人皆谓我症似中满，今不满者，叔公力也。敢不德欤。予警之曰：吾闻君子之于身也，兢兢焉不敢轻父母之遗体，无伐天和，则疾疢不作。无反天常，则灾害不逢，蘧伯玉尝言：行年五十，而知四十九年之非。况新愈后，尤当痛惩，庶保遐龄，区区无足恃也。别未五年，予在宜兴闻讣，果以伤酒而卒。噫！惜哉！（八十一）", "6438": "甲午仲秋下旬，黄源金先生以中馈病急，谒予于市，貌甚惨，步立栗然。语其症，怔怔言涩于吻，不胜其忧。执族医尺一白予云：病自仲夏吐血二碗余，初以芩、连、枝、柏、生地、芍药，大寒之剂投之，一帖而止，未几则咳嗽彻昼夜。后师谓咳自吐血后，当以滋阴降火之治。逾两月，尽其法而罔效。反加喘促泄泻，长巳二时，发热烦躁。师告技穷，谓喘咳，乃火刑肺金，泄泻乃脾胃已惫。保脾则火愈炽而喘咳增加，滋阴则泄泻绵绵而元气下脱。经书所记，嗽而下泄上喘者死。此症之谓也。似无可奈何矣！语竟泪潸潸下。予观其忡忡之状，心不觉惕然动也，市去渠宅五里许，即步去一视，观其面青，喘促，抬肩撷项，息息连身而倒，胁背俱疼，日夜不得伏枕。脉之左涩，右寸关滑大，诊毕顾金兄犹泪盈眦。予抚其背曰：毋泪，尚可生也。适徐仲子同视，诘予曰：症若此，夫子曰可生，何也？予曰：是非汝所知也，第观予治，俟奏功，当语汝。遂以紫菀、茜根、牡丹皮、桃仁、益元散、桑白皮、茯苓、桔梗、栝蒌仁、桂枝、白前，水煎，临服加韭菜汁半酒杯。服后背胁痛止，泻减半，乃得睡，但咳而声哑不除。次以杏仁、桔梗、紫菀、甘草、白前、五味子、栝蒌、干姜、款冬花、半夏曲、通草，水煎服，服后声渐开，泻全止。惟嗽尚多。再以半夏曲、桔梗、茯苓、陈皮、甘草、杏仁、桑白皮、白前、苡仁、白芍、牡丹皮，水煎，后以丹溪治咳吐方，用泻白散，加青皮、人参、白茯苓、五味子，调理痊愈，次年诞一子，是役也，徐仲子之功居多。盖金为徐仲子友也。徐仲子治疾多奇中，乃笃信予而推毂之，初投剂，人多置议，仲子独赞之曰：其必有见也。人人辟易，彼许可生，安得不望生哉！故金任之不贰。功成，余明甫、查仲修问予曰：病起于吐红发热，烦躁喘咳，皆是火邪，前后之师，滋阴降火药，法亦未爽，然而病转增剧，其故何也？予答曰：医不难于用药，而难于认病。余明甫、查仲修曰：市人议先生治疾多不循方，每每师心，金之役，人皆市为火症，而用寒凉，先生独用温热，虽成功，小子窃为先生恐。予曰：病原于火，其势之剧，以治之太峻致然。夫血之初，来势如涌泉，安能一吐遂尽，必有余血伏于经络。思不及此，而以大寒之剂，一帖而止。大寒之剂，岂能止血，适以凝其血耳。血凝经络，滞于气道，气滞血凝，日甚一日。气滞又复生痰，痰与瘀血两滞经络，则肺气不利，故咳嗽声哑，不加察而为消瘀化痰导血归经，又以滋阴苦寒之剂施之，则痰瘀愈凝，而气道愈不利也。久则胃寒脾弱，反增泄泻，昼夜喘促不能卧矣！书云：上热未除，中寒复生，而为阴盛覆格阳之症。故咳而呕吐，予故始以桂枝、干姜之类温其胃，以桃仁、韭汁、丹皮、茜根之类活其血而消其瘀，故喘止而泻除。东垣曰：脾胃喜温而恶寒，信不欺也。古谓药不贵执方而贵合宜，方即兵家之阵图，匠氏之规矩也，图可授人，而不能授人斗。匠可授人规矩，而不能授人巧。此岳武穆对宗留守云，运用之妙，存乎一心也。予游方之外，亦不失方之内，惟不失方，窃谓知方，知方合法，岂区区能哉。观古人治虚怯之疾，即不治之症，亦能延之三五载。乃今治虚怯者，不半载而竟殒逝。犹驾言曰：殆今之天元运气使然，敌人多不寿。遇谓天元运气，则人人皆如是夫？何予母八十有六，予父逾八望九，予伯母今九十有五，予表伯汪春元东台之父，年九十余，强健不啻少壮。不思速夭之由，皆为滋阴降火之误，而反归咎于天，天何尤哉！缘滋阴降火之法起于丹溪，继而王节斋、何大英之流，倡而和之，以成其风，此当今之大弊，而人未之警也。我师祖汪石山先生揭而指之，惜乎未有继其言者。一齐众楚，故滋阴之祸流而迨今，敝以继敝，无已时也。二三子其识之。徐仲子其闻之乎。仲修又问：先生何以认为是症为中寒而非阴虚之火，而又认其喘为瘀血也？予曰：脉与症皆可考。《脉经》云：涩为气滞，气滞则血凝。盛吐之后，大寒之药一帖而止，其未尽之余血，为寒凉所凝滞于气道为喘。书云：从前来者为本，从后来者为标。兹用活血消瘀之剂治其本，以温热暖胃之剂治其标，故泻止而喘定也。若夫阴虚火动之脉，乃细数之候，今脉滑大，非阴虚之脉。阴虚喘嗽之症，潮热于夜，两颊皆红，今热在辰巳阳分，而面色带青，由是以知其非阴虚之火，乃误用寒凉，激其火而上行也。经曰：水流湿，火就燥。中气既寒，火愈不能下矣。正如雨骤雷烈，则电光之火愈炽，日出而电光自息也。且阴虚火动，火起九泉，皆自足下涌泉穴起，以渐上升，今膝下冷而上身热，两尺脉又弱。盖由咳而气升。经曰：形寒饮冷则伤肺。肺气为寒药壅遏不得下降，故咳而吐酸。《丹溪纂要》云：阴气在下，阳气在上，喘咳呕吐，泻白散加人参、茯苓、五味子、青皮。故不从河间，而用诸呕吐酸皆属于火之治。况今岁次甲午，为湿土司运，八月建酉，水土衰败之时。《内经》曰：毋违时，毋代化，且脾恶湿，湿多则泻，湿则生痰。前后之师，不考运气月令，一概而用滋阴降火之剂，助湿生痰，安望其痰之愈也。《丹溪纂要》云：实脾土、燥脾湿，是治痰之本也。遵而用之，如鼓应桴。予故曰：医不难于用药，而难于认病，有以也。（八十二）", "6439": "族侄合溪，年当八旬，春初偶为寒袭，发热咳嗽，医与芎苏散，即汗出不止，呃呃连声，勺粒不入，昏愦经旬，汗日加，呃日甚。延予诊之，六部浮大无力，重按三五不调，六七至一止，右关近滑。诊毕，语嗣君敬所曰：尊翁由劳倦表虚感邪，脉故浮大无力，法当从东垣补中益气汤，一二剂可瘳也。医乃妄为散表，致汗漏神疲，昏愦发呃，高年值此，宁不殆乎？即可徼幸图安，亦不过千日养耳。敬所勃然俯而对曰：上巳后为家君寿期，不虞构疾，羸惫若此，苟保百日，俾叔水之心，庶几少尽，叔祖之赐多矣。若干日又出于望外也。予即以六君子汤，加竹茹、柿蒂以止呃，再加酸枣仁、石斛以敛汗，一进热退呃定，再进，汗止食入，三进，霈霈然精神长矣。乃减去竹茹、柿蒂、加当归，半月全安。先是祝令君谓渠有耆德，请为介宾，以疾辞不及赴，迨季春令君闻渠寿，即援例赐一级宠，以冠带扁，额用彰恩典，光于乡闾，后果三年而卒。（八十三）", "6440": "孝廉方叔度令嫂江氏，年甫三旬，患胀满。诸名家或补或消，或分利，或温或寒，悉为整理一番，速手而去，举家惶惶，无所适从。叔度曰：闻孙仲暗昔患此，众亦束手，比得孙生生者治而起之。众皆敛衽钦服。仲暗伯仲适在馆中，盍咨访之。即发书介予，随绍向往。诊得左脉弦大，右滑大。予曰：此李东垣木香化滞汤症也，病从忧思而起，合如法按治，可保终吉。叔度喜曰：曩从事诸公悉云不治，先生谓可保终吉，此故仓公有言：拙者疑殆，良工取焉是也。幸先生早为措剂，予即照本方发四帖，服讫，腹果宽其半，继以人参消痞汤，琥珀调中丸，调理二月全瘳。叔度信予从此始，每推毂予于诸相知，多有奇中，卒为通家之好。（八十四）", "6441": "临溪吴天威丈，年七十有三，客邸远归，偶坠马跌伤，左胁作痛，随治而愈。后半年，忽左胯肿痛，增寒作热，动止极艰。里中诸公有认湿痰者，有认风气者，有认湿热者，总罔效。闻歙外科洪氏能，且识杂病，迓以为治。居数日，视为疝气，率投荔枝核、大小茴香、川楝子、橘核之类，痛躁不可当，乃欲引绳自绝。诸子百般慰解，洪乃辞去。竟不知为何疾也。其婿汪开之，予之表弟也，邀予诊之。六脉浮而洪数，左寸尤甚。验其痛处，红肿光浮如匏，抚之烙手。予曰：此便痈也。洪系外科专门，胡独忽此？盖渠素慎重，见患者年高，乌敢认为便痈治哉！此殆千虑一失，毋足怪。诸郎君闻予言，皆骇然，诘予曰：家严不御色者十载，顾安得此，愿先生再思。予曰：此非近色而得，审胯属足厥阴肝经，肝为血海，乃昔时坠马恶血，消之未尽，瘀蓄经络，无门可出，化而为脓。由年高气虚，又被香燥克伐太过，不能溃而即出，故散漫浮肿，观其色青中隐黑，脓已成腐。必须外用镵针，引而出之，内用《千金》托里，庶可排脓生肉。但予生平心慈，不能用针。予弟警吾，外科良手，可延而决之。至即以镵针深入寸余，出青黑脓五六碗许，臭秽难近。即与诸郎君曰：使早决三日，可免一月之苦，今即日大补之，非百日不能痊，此俗名石米疮也。诸郎君及患者，见脓色如是，始信予言不爽，急以请剂。予乃用内托十宣散，参耆每帖三钱，后加至五钱，一日两进，两越月，脓尽肉满而愈。一市称奇。（八十五）", "6442": "文贵者，善为族文学岐原出入子母者也。寓长兴邸中，病发热昼夜不止，口渴齿燥鼻干，舌苔黄厚，不得眠。服药不效。予适至雉城，岐原邀诊之。脉俱洪数，呕恶，胸膈痞懑，小水短而赤，大便下皆清水。予以石膏七钱，知母五钱，甘草一钱，软柴胡五钱，葛根三钱，黄芩二钱，枳壳、桔梗、竹茹各一钱，连进三帖，呕吐止，胸膈宽，热仍未退。无汗，泻未止也。时有问予者，谓胡不用柴苓汤而退热止泻也，服石膏故益泻耳！予戏之曰：予乃三脚猫耶，能认此为何症而用柴苓汤也。仍以柴胡、石膏各七钱为君，葛根、知母各五钱为臣，黄芩、甘草各一钱为佐，生姜五片，速进二帖，汗则津津然出，热退泻止，口不渴而眠矣。予因他往，留药三剂，而嘱之曰：胃气初回，势必思食，宜谨慎不可多进，若多则余热复作，必成食复，治将费手也。慎之慎之。后五日，果以食不慎而复病。予又至，热较前为重，且加懊𢙐，夜谵语如见鬼状，口大渴，齿燥，舌焦黑，有芒刺，势甚危急。以前方加枳实、栀子各三钱，淡豆豉二钱，煎饮之。二帖懊𢙐止。余症犹然，夜更甚，前方减去豆豉，加黄连、麦冬、生地、白芍，一日二帖。舌以井水生姜擦去黑胎，用蜜调玄明粉涂之，而苔去矣！服三日始得微汗，诸症尽减。再四叮咛，慎饮食，调理半月而全。岐原问曰：人始皆认此症为漏底伤寒，谓叔不用柴苓汤退热止泻，而用石膏为非，乃竟以石膏收功，何也？予曰：此问甚善，盖医贵认症，此症乃少阳阳明合病也，柴胡白虎汤，葛根为二经对症之药，服之可解肌热，止口渴。若柴苓汤，为太阳少阳合病之剂，内有五苓散，乃太阳经之里药，症非太阳，曷敢用之？且其内有人参、白术、肉桂，皆助热发燥之味，误投则必发斑。其齿燥舌干而焦黑，又何敢用茯苓、泽泻、猪苓利之，使益亡其津液耶！古人谓以伤寒为大病，不察症而误投，则生死立见。伤寒论有言，不得汗，不得下，不得利小便，是谓三禁。故曰，少阳阳明，不从标本，从乎中治，小柴胡白虎汤，中治剂也。人从见其大便作泻为漏底，不察泻皆清水无糟粕者，为热极所致。症乃春温时疫也。但为发散，使清气上升，而微有汗，泻当自止。此泻岂五苓散所能止哉？止则误事。岐原曰：夜重如见鬼者。何以故？予曰：热入血室故也。岐原曰：男子亦有血室乎？予曰：血室男妇同之，冲任二脉，为血之海，二脉附于阳明，今病乃阳明之热遗入血海也。故加生地、白芍而效。余治伤寒，用柴葛解肌汤及柴胡白虎汤，而热不解者，加此二味，则热无不退，汗无不出矣。且下午与夜，又阴分主事，欲解血海之热，必投此二味以收其功，此亦予一得之愚也。岐原曰：善，愿记之以诏后来。（八十六）", "6443": "钟泽有程梦奎孺人者，年将五十，仅一子，念一岁而殁于痘，旦夕哭之，哀且弥月，揽镜自鉴曰：何子死而形色不瘁如此，因持铁如意捶其胸，绝粒断浆，肌容日瘁。时为初秋，寒热交作，呕哕懊𢙐，遍身疼。夫为遍延诊视，却药不饮，诸医百策开譬，拒而不听，媳与孙跽而恳，姻族就而谕其不纳者，若罔闻也。惟合睫以待死，已而作色语其夫曰：病若此，汝曷不延名医一决生死乎？夫曰：所延皆名士。病者曰：昔尝闻程方塘参军患疯三年而起者谁？曰：孙君。又问：吴西源孺人病燥揭痰喘三年，与程道吾内眷劳瘵晕厥，谁为起之？夫答如前。病者曰：何不请孙君决我生死。夫闻言，物色征予，五日而后至则薄暮矣。病者犹疑为诞也。私至三家访予状，皆曰：魁然长髯者也。诘朝，觌面诊之毕，则问曰：何日死？予应曰：病势危，去死不远，病者喟然叹曰：死不足惜，第九华山香愿未了为恨耳！予曰：孺人大愿不思，何须以此小愿为孜孜也。孺人曰：无大愿。予曰：人之修短有数，今年之痘死者，不可胜计，令嗣之死亦数也。然有二孙可承宗祧，孺人能忍哀抚孙，使其成立，娶妇以蕃后胤，令嗣虽死，犹不死也。而孺人亦有令名，若不此之思，忧伤以殒，夫君必娶，娶必少年，继室生子，则必厚其子，而薄孺人之孙，晚娘晚爷之谣，独不闻之耶。孺人万金之家，使令孙不得其所，令嗣九泉之下，恐不能无憾。孺人忧死，何益也，愿孰大于此者。予故谓未之思耳。孺人试思之，谁轻谁重当自辨也。语毕怃然曰：先生言至此，吾如寐者得醒矣！顾病热去死不远，何能得如吾愿？予曰：所谓近者病也，非脉也，脉左弱细，右关滑，故发热体痛呕哕，乃秋来疟症，非死脉也。若如前执拗不服药，不进饮食，书谓绝谷者亡，殆非虚语。孺人诚听予言，以二孙为念，以大体为重，予以活血养血之剂而治其伤损，以小柴胡加竹茹、滑石，以和阴阳而止其呕哕，不一月而可无恙矣。奚忧哉？果从予言而进食服药，调理五日，寒热呕哕皆止。后以丹参、刘寄奴各三钱为臣，五加皮五钱为君，香附一钱为佐，入四物煎服，果一月而全可矣。程孺人病起，而闻者皆曰：七发起太子之病，观于孙君益信。（八十七）", "6444": "歙潜口汪召南令郎，年十四，患蛊胀，大如覆箕，经医三十余人，见症皆骇而走。独市之幼科养直者，调理数数见效，第此子溺于豢养，纵口腹，不守戒忌，病多反复。一日语召南曰：郎君之症，非求之孙生生者不能成功。召南曰：闻此公多游吴浙缙绅间，何可以月日致也？养直曰：归矣！吾有妹适罗田，为方与石丘嫂也，旧岁患症如蛊，治经弥月无功，生生子立全之。吾推毂孙君者，岂有他肠，为郎君也。召南即浼罗田延予，予至日已晡矣。观病者腹胀太极，青筋缕缕如蚯蚓大，上自胸脯，至上脘而止，惟喜其不下现也。脐平，四肢面目皆浮大，两足胻骨上各裂开，大出清水，一日间数为更衣易被，阴囊光肿如泡，淫淫渗湿，发寒热，脉以手肿不能取，必推开其肿，下指重按，浮而六至。予曰：症可谓重之极矣！仅可恃者，目瞳子有神耳，余皆险恶，将何以治。养直知予至，亟过相陪，宣言曰：病重不必言，引领先生久矣！幸为投剂，生死无憾。予曰：且先为理表，若表彻稍得微汗，使肺少利，则小水可通。召南喜而亟请药，乃用紫苏叶、苏子、陈皮、麻黄各一钱，桑白皮八分，防风、杏仁各七分，炙甘草、桂枝各三分，生姜三片，水煎服之。五更乃有微汗，次早面上气稍消，胸脯青筋皆退，余症虽仍旧，机栝则可生矣！仍投前药，次日腹与四肢皆有皱纹，惟小水未利。乃改用破故纸、苍术、赤茯苓、泽泻、桑白皮、赤小豆、桂心、木香，二帖，而小水利，骎骎已有生意。乃以饮食过度，大便作泻，又以四君子汤，加苡仁、破故纸、泽泻、山楂、砂仁，调理而全安。此症予阅历者，不下数十。然青筋未有如此之粗。足胻出水有之，未有出水处如点鲇鱼口之大。而取效亦未有如此之速。盖此子体未破而真全，故症虽重而收功速也。数十人间有五六不能成功者，由其纵欲恣情，不守禁忌，非药之罪也。召南昆仲，见人谈医，辄以不佞为称首。予笑曰：君得无到处逢人说项斯者耶。乃汪养直亦医道中白眉，乃不收功于后，病者不忌口过耳。于养直何尤，养直不矜己之功，亦不伎人之功，所谓忠厚长者非耶。（八十八）", "6445": "岩镇郑景南丈病卧年余，百治不效。昔体丰腴，今瘦骨立。饮食少进，新都名士，皆辞不治。其家闻昔年方士荣孺人蛊症，时师亦皆辞去，予为起之，因征予治。时则六月望也。诊其脉，左弦大，右关滑大，两尺俱无，恶心，腹瘦削，状如仰瓦。肠鸣如雷，昼夜不住。小水不利，肌肤及眼珠色若黄金。腹中有块如碟，跳动不止。足膝以下皆冷，饮食不入。予详思其病机，昔肥而今瘦者，痰也。形虽瘦而目炯炯有神，先以五饮汤姑试之以观其势，再为加减。因用旋覆花八分，破故纸一钱，肉桂三分，白术、茯苓、泽泻、陈皮、半夏各八分，生姜三片，水煎服之。二帖，恶心肠鸣皆止，次早饮食稍进，举家欣欣色喜。令岳程钟山公，于予为石交，闻病有起意，心殊异之。不知为予，因而过访，见予，抚掌大叫称快曰：吾固知是公也。指其甥而语之，此即所尝与尔曹言者，闻久为西吴缙绅递留，不意今归，城吾婿之幸也。相与谈对，两日而别。别之时，景南饮食稍加，小水利，肌肤面目黄气退，渐有生机。不虞逾半月，为拂意事所激而怒，复吐痰不思饮食。家人惊惶无措，亟予诊。两寸滑大，左关弦劲搏指，右关亦滑大有力，两尺沉微。予语之曰：病甚重，脉非前比，且不敢以万全许，第尽吾心尔。病以药力而回，君之福也。时为七月之朔，予因留视七日，日进一剂，剂以人参、陈皮、半夏、茯苓、香附、白豆仁、黄连、旋覆花、麦芽、甘草与服，服三日恶心止，大便有稠痰下，其中间有瘀血，此皆大怒所致。故经云：怒则伤肝。甚则呕血，并下泄上吐，亦或有红点子在痰中吐出，是其征也。后改用六君子汤，加麦芽、黄连、枇杷叶、白扁豆调理，病势骎骎向安。腹中如碟之块亦渐消去。大仅如指耳，肌肉亦生，能下榻举足以步，市上之人称奇。", "6446": "孙文学子元，素多疮疥，近因沐浴，鼻涕出红，面足浮肿汗多。左脉大而有力，右寸亦大。据脉多思而气不畅。以葛根、大腹皮、厚朴、赤茯苓、青蒿、泽泻、白术、郁金、升麻、木通、滑石、黄芩，水煎饮之，浮肿渐消，惟鼻红尚在，口且渴。改用当归、白芍药、知母、甘草、石斛、麦门冬、五味子、山栀子、玄参，调理而愈。（九十）", "6447": "一妇因夫荒于酒色，不事生计，多忧多郁，左胯疼痛，直下于膝，小水频数，大便频并，脐腹胀疼，口干。脉之左手数，右手弱，近又发热恶寒，汗因痛出，时刻不宁，此食积痰饮，瘀血流于下部，足厥阴之经，挟郁火而痛，恐成肠痈。与神效栝蒌散一帖，半夜后痛即减半，汗亦寻止。次日诊之，数脉稍退，小腹坚如石，按之且痛。再与前药，其夜环跳穴亦作痛，直到于膝，小腹稍软，小便仍痛，大便赤未通利。仍与前药。每帖用大栝蒌二枚，加牡丹皮、莪术、五灵脂、金银花，服下大便利而热退痛止。小水亦长，诸症悉平。（九十一）", "6448": "族侄孙君锡，头痛胸背胀，饮食下膈便吐，咳嗽不住口，痰浊如脓，大便结燥。脉之独右寸洪大。以二陈汤，加竹茹、滑石、石膏、酒连、麦冬，连进四剂，夜与益元丸兼服，而嗽吐俱止。惟痰浊如脓色，且腥气触人，此将欲作肺痈。改用牡丹皮、麦门冬、山栀子、甘草、贝母、枳壳、桑白皮、紫菀、知母、当归、生地黄、桔梗，四帖全安。（九十三）", "6449": "侄孙尔嘉内人，三孕而三小产。六脉滑数，乃气虚血热也。由其热，故多滑下，因其血频下，心甚恐怖，终日偃卧，略不敢起身，稍起，血即大下。与生地黄、白芍药、白术、地榆、桑寄生、续断、甘草、升麻、椿根白皮、黄柏、条芩服之，而血三日不来，惟白带绵绵下。过五日后，因有不得已事，起身稍劳，血又大下。予谓血滑已久，如水行旧路，若不涩之，必不能止。又思血海甚热，亦肝风所致。防风子芩丸，正与病对，宜制与之。又制白芍药六两，侧柏叶、条芩各三两，防风、椿根白皮各二两，蜜丸服之。从此血止胎安，足月而产一子。此后连产三子，并无胎漏之患。后遇胎漏，递用此法，莫不良已。附告同志，以便取用。（九十四）", "6450": "梓林兄令眷，右手痛风，小水频迫，起身稍迟，即出不禁。足有浮气，年过六十。右寸关脉濡弱，左手和。此脾虚停湿之症。近且咳嗽，用六君子汤，加苍术、石菖蒲、远志、大附子、晚蚕沙，倍加薏苡仁，缓治而平。（九十八）", "6451": "一妇经不行者三月，大便泻，腹胀嘈杂，吐酸水，时下白带，常恶心，自以为有孕。予脉之，候非有孕。乃脾经有湿热，心经有瘀血症也。与二陈汤加白术、泽泻、猪苓、酒连、木通、吴茱萸、滑石、麦芽、山楂，泻止腹宽，经行，腰腹作痛。以川芎三钱，当归五钱，香附、丹参、桃仁各一钱，水煎服之。经虽行，口中吐出黑血水甚多，且亦有如脓者。改用四物汤，加牡丹皮、丹参、桃仁、红花、山栀、滑石，调理两月而痊。（九十九）", "6452": "侄妇程氏，下午喉痛，近来痰多晕厥，一日二三发，头痛面赤。素未生育。左脉弦大，右寸关滑大有力。以荆芥、薄荷、甘草、桔梗、玄参、僵蚕、柴胡、枳壳、竹茹、贝母，水煎饮之，连进两帖，其夜得睡。惟背胀怔忡，痰犹不清，面多热。用黄芩、枳壳、甘草、桑白皮、地骨皮、天花粉、玄参、前胡、半夏曲、橘红、山栀仁，调养而平。（一百）", "6453": "汪𬬮兄时疫热病，被发汗过度。热留胸中，烦躁不止，呕恶不安，汗竟不敛，口且渴。脉之，独两关洪大，此阳明之热尚在，当以白虎生脉汤为主。石膏五钱，知母三钱，人参、白芍药、甘草、石斛各一钱，麦门冬二钱，五味子十五粒，急煎饮之而热退。继以益元丸服之，而吐亦安。（一百零一）", "6454": "族侄元素，春温头痛发热，左脉弦大，右洪大，以小柴胡合白虎汤，二帖而愈。乃为食复，发斑色紫，神昏，人事不省，身重不能转动，即水火皆不自知。合目鼾睡，形如醉人，面赤发热。舌苔外黄内黑，皆有芒刺。三日后，予至脉之，六部俱浮洪，以三黄石膏汤，加枳实、鳖甲进之，稍得微汗，大便如有真粪，次日才开目言语。乃进粥一盏，改用小柴胡汤，加山栀、枳实、鳖甲、白芍药，调理而愈。（一百零三）", "6455": "仆子孙安，空晨出门，途次食面三碗，饥劳感疫，因面内伤，表里皆热，及至绩溪衙中，昏闷谵语，头痛身疼腹痛。医不察为劳倦感疫，遽以遇仙丹下之，大便泻三四十行，邪因陷下而为挟热下利之候。急归视之，舌沉香色，额疼口干，燥渴烦闷，昏昏愦愦。脉左弦数，右洪数，但不克指，知为误下坏症。以柴胡、石膏各三钱，白芍药、黄芩、竹茹、葛根各一钱，天花粉、甘草各五分，山栀子、枳实各七分，葱白五茎，水煎服之。后半夜吐蛔一条。乃稍得睡。次早大便犹泻二次，呕吐酸水，腹仍痛。改用小柴胡加滑石、竹茹，夜热甚，与丝瓜汁一碗。饮既，神顿清爽，少顷药力过时，烦热如前。再以丝瓜汁一大碗进之，即大发战。予谓此战非寒战，乃作汗之征耳。不移时，汗果出而热犹然。忆《活人书》云：再三汗下热不退，以人参白虎汤加苍术一钱如神。迹此，再加玄参、升麻、柴胡、白芍药、黄连，饮后身上之斑先发者紫，后发者红，中夜后，乃得睡而热散，斑寻退去。复中微疼，肠鸣口渴。右脉尚滑，左脉已和。再与竹叶石膏汤，加白芍药、苍术，服后睡安，腹仍微痛。用柴胡、芍药各一钱，人参、酒芩、陈皮、半夏各六分，甘草三分，乌梅一枚，服此腹痛渐减，精神骎骎长矣。惟两胯痛，不能转动，此大病后汗多而筋失养之故，宜当补益。人参、黄耆、白芍药、桑寄生、枸杞子、薏苡仁、桂心、牛膝、熟地黄，水煎服。后加木瓜、黄柏、当归、减去桂心，调养而痊。（一百零四）", "6456": "侄君孝，后谿兄次子也。三月患头项痛，腰脊强，遍身如被杖，脐腹亦痛，口渴不寐，饮食不进，六脉浮数。吴医以为阴虚，为滋阴降火，三投而三剧，反加呕恶。又与疏通，热尤不退，下午烦乱。延方和宇丈视之，以为外感，拟进人参败毒散。吴争之，谓阴虚体弱难再汗。仍用四物汤，加柴胡、葛根、薄荷、黄芩、知母，而热如焚，神且昏冒矣。予时远出，促归诊之，六脉浮弦而数，鼓指。语之曰：此春温症也，方诊良是。因复加内伤，以故病剧，滋阴之剂，壅而作滞，且引邪入于阴分，宜乎热加而躁闷也。法当清解兼消，可愈无伤。以二陈汤，加羌活、柴胡、防风、麦芽、山楂，服下得微汗，热退其半。惟下午作潮，大便未行，腰脐之痛不止。用小柴胡汤，加葛根、白芍药、青皮、黄连、山楂，饮下热又少退，大便已行，腰脐之痛亦随减去，但不知饿。再以柴胡、甘草、青皮、枳实、麦芽、知母、黄芩、白芍药，诸症悉平，惟觉体倦乏力。加人参、白扁豆、薏苡仁，减去柴胡、青皮，调养而痊。（一百零八）", "6457": "族侄妇范氏，大参晞老女也。素有痰涎，胸腹痞胀，近因乳肿，大发寒热，欲成痈毒。以加味神效瓜蒌散二帖，寒热虽退，而肿不消。用贝母、白芷为臣，栝蒌为君，赤芍药、当归、连翘为佐，青皮、甘草、柴胡为使，痛虽减而肿仍不消，脉之近数，知已成脓。乃与内托十宣散，加金银花、蒲公英，两帖而脓溃。因脚上生疮，而有浮气，前方去蒲公英、金银花，加薏苡仁、苍耳子，调理全安。（一百一十）", "6458": "孙竹檒,浙归，途次受暑，又为酒面所伤，因而作吐，胸膈痞闷。时师以消导之剂，燥动脾火，口渴嘈杂，躁乱不宁，目珠如金，一身尽黄，已成疸症。诊独右寸脉洪大有力。先以温胆汤，倍加香薷、滑石、葛根解暑止吐为君，黄连、麦门冬清热止渴为臣，使湿热散而黄自瘳也。连与三帖，吐止食进，黄亦定矣。再与五苓散，加青蒿、葛根、黄连、枳实，八剂而黄释然。（一百一十三）", "6459": "程菊泉，暑月患喘嗽。咳咳连声，浓痰滚滚，行动则喘促不宁。夜分口渴，胸膈胀闷。两寸脉滑而数，两关弦。此肺有宿痰，胆有郁火。《内经》云：火郁发之。又云：风寒外束者可发。用紫苏子、半夏曲、杏仁各一钱，石膏二钱，款冬花、桑白皮各八分，桔梗、枳壳各五分，麻黄三分。服下无进退。改以杏仁、陈皮、人参、贝母、款冬花、麦门冬各七分，薏苡仁一钱五分，桔梗、知母各五分，五味子十一粒，桑白皮一钱，陈皮六分，服下痰减大半。胸膈仍不舒，口仍干，脚仍热。前方减去款冬花、五味子，加枳壳、葶苈子，两帖全安。（一百一十四）", "6460": "程应桢兄，胸膈背心时常胀疼，头眩晕。脚软弱，手指痛。咳吐红痰。诊其脉左关弦大，右寸关滑大。予谓此食饱后感于怒，老痰瘀血积在上焦，宜其胸背胀疼而热壅也。治当清化上焦，使新痰不生，宿瘀磨去，则万全矣。如落时套，用地黄、山茱萸等滋阴降火之剂，是以滞益滞，则热无由去，瘀无由消，而痰益增不去也。病者闻言谔然曰：未见公时，业已服过一月久矣，疑其饮食损而热寻加，胸背痛胀递长哉。予曰：今反辙幸早耳，再迟则败事。亟以青皮、枳壳、陈皮快其气而疏其壅滞，盖痰随气行也，贝母、桑白皮以消余痰而清其嗽，牡丹皮、滑石、桃仁消其瘀血，山栀仁开郁清热，白芍药伐肝补脾，甘草调和诸性。缓而理之，当见其去泰去甚也。别后半月，覆书报云：胸背之胀减三之二，血已十日止矣。痰如旧。改以山栀仁、牡丹皮、丹参、赤芍药、桃仁各八分，滑石三钱，五灵脂、当归尾各一钱，半夏曲、青皮各六分，诸症悉去，独足心热。再以黄柏、知母、苡仁、牛膝、甘草、白芍药、茯苓、陈皮、贝母、石斛、牡丹皮，调之如初。（一百一十五）", "6461": "虚山内人，胸胁胀痛，五更嘈杂。每一嘈杂，则痛发更甚。左寸关脉洪滑，右关亦然。此肝胆有郁火，胃中有胶痰，乃有余之疾。《内经》云：木郁则达之。盖木火之性贵乎疏通。当以龙荟丸条而达之。顾痛则不通，通之则不痛也。服龙荟丸一钱五分，大便行一次，痛随殄迹。惟声不开，以陈皮、柴胡、贝母、茯苓、甘草、白芍药、酒芩、香附、杏仁、桔梗，调之而安。（一百一十六）", "6462": "一妇当暑月，小便不利而痛，玉户肿。且又便血发热。左脉弦数，右寸短弱。此肺气不足，肝火太炽，盖肝为血海，肝又主小便，玉户为肝经所络之地。治当疏决肝经壅塞。脾气畅，则新血得以归经。热解，则小水可不痛。而肿亦可消矣。以滑石三钱，桃仁、当归、白芍药各一钱，柴胡、黄连、人参各八分，川芎六分，甘草、桂皮、白芷各三分，四剂而病如失。（一百一十七）", "6463": "族弟妇戴氏，腹中痛，多在脐腹。白带如注，四肢酸疼，大便里急后重，已成赤白痢矣。脉之两寸关俱滑数，尺亦数。以白芍药，当归、黄连、黄芩、木香、槟榔、桂皮、甘草、滑石、桃仁、桔梗，一剂而红止，惟小水短涩，下午发热，大便一日夜仍四行，改用白芍药、当归、白术、陈皮、滑石、甘草、茯苓、厚朴、酒连、酒芩、桔梗、柴胡、木香，饮下，诸症悉愈，惟头痛腰疼。再以桂心、当归、白芍药、白术、茯苓、甘草、酒芩、酒连、破故纸、木通、黄柏，煎服全安。（一百一十八）", "6464": "予弟淑南，额痛遍身疼，口干，舌苔黄厚，左脉浮大，六部俱数。时当仲秋初旬，以小柴胡合白虎汤加羌活，热仍不退。下午用六神通解散，以葱汤调服三钱，热稍退。至半夜后，又复热，额疼，顶巅尤甚。舌根黄且焦黑，小水赤痛，烦躁不睡，遍身又痛。此三阳合病暑症也。次日以小柴胡大加石膏为君，藁本、白芷、竹叶、粳米、生姜、大枣，少顷，汗大出至足，热始尽退，犹烦躁不睡。仍以小柴胡汤，加桂枝、山栀子、竹茹、竹叶，饮下，烦躁宁而得睡，余热悉平，精神爽而向安矣。（一百二十）", "6465": "孙文约孺人，年八十有三，胃脘疼痛，手不可近。腹中饥而饮食不能下。两寸关脉滑大，两尺沉弱，此血虚气滞也。先与积气丸，一服而痛减半，再用生白芍药、山栀子、五灵脂各一钱，酒炒白芍药二钱，粉草、山楂、香附各八分，一帖全安。（一百二＋二）", "6466": "应章族弟，三阴疟发于子午卯酉日，已四越月矣。每发于夜，热多寒少，左脉微弦，右关滑大。以二陈汤，加柴胡、黄柏、川芎、当归、黄连，两帖而热稍轻。饮食不进，四肢懒倦，脾气大虚。白术、何首乌各三钱，鳖甲二钱，青皮七分，乌梅一个，一帖而截。（一百二十三）", "6467": "太字程好吾，倜傥博洽士也。季春患两太阳痛，胸胁稍疼，口渴，大便水泻。左脉浮弦而数，中按有力，右关滑大。予曰：春温症也。柴胡、前胡、葛根、粉草、青皮、黄芩、知母、桔梗、半夏曲、石膏，半夜后得微汗。因起大便感风，续又发热，依然口渴，更觉烦躁。石膏三钱，知母、柴胡各二钱，葛根、黄芩各一钱，粉草、桔梗各五分，竹叶二十片。两进而汗出热解，诸症悉平。四肢尚倦，口微干，语言乏力。以生脉汤，加薏苡仁、石斛、甘草、白芍叶、黄芩，调养如初。（一百二十四）", "6468": "令媳长卿之妇，腹中微疼，经行不流利，喉痛，四肢麻木作战，不知饥饿。右脉洪大如豌豆。以川芎、香附、麦芽、山楂、乌梅、粉草、桔梗、酒芩、防风、荆芥、白术、茯苓，四剂而安。次月经水大行十日不止，以黄耆、阿胶、蒲黄各一钱，白芍药二钱，粉草三分，一帖而止。此后但觉浊气下坠，屁从子户中出。以补中益气汤，加酒炒黄连，调养而平。（一百二十五）", "6469": "族子应章之弟，十月发三阴疟，至次年仲春未止。每发于辰戌丑未日，午后，寒多热少，夜有盗汗。左脉软弱，右关尺弦数有力。用白芍药、当归各一钱，白术二钱，柴胡、川芎、粉草、砂仁、桂枝、酒芩各三分，生姜三片，水煎服。再以何首乌、白术、鳖甲各三钱，柴胡一钱，青皮、酒芩、甘草各五分，乌梅一个，生姜三片，水煎，临发日五更服之，两帖而止。后半月，下身大生疮疖，以东坡四神丹，调理而痊。（一百二十六）", "6470": "油潭吴中岳孺人，先感风邪，后伤饮食。发热头疼，腹中作胀。医与巴豆丸泻之，而热不减。后医又以大黄重泻之，而热亦如初。再后医谓泻而热不退者为虚，大用参、耆、白术补之，补经四日，神气昏沉，不知人事。乃敦予诊。左脉弦数，右关尺沉数有力。舌尖沉香色，舌根焦黑芒刺。语言含舌不清。扣前服药，始知妄下妄补。不思饥馑之余，疫气为厉，误成坏症，危而且殆。故以知母、柴胡各三钱，石膏六钱，枳实、天花粉各五分，粉草、黄芩、麦冬各一钱，山栀子、生地黄各七分，人参六分，竹叶三十片，生姜三片，水煎饮之。中夜后人事稍清，微有汗，舌稍柔和，言语已不含舌，骎骎然有生气矣。次日，前方减去地黄，加白芍药，舌心焦黑尽退，诸症十减其七。但大便五日未行，遍身尚痛，咳嗽。与七制化痰丸二帖，再以石膏二钱，麦冬、贝母各一钱，前胡、枳实、黄芩、栀子各六分，甘草三分，桑白皮八分，煎服而安。（一百二十七）", "6471": "元素侄令政，春温后经水适止，余热不退，口中甚渴，胸胁痛而耳重。脉左弦数，右滑大而数。小柴胡加石膏、知母、桔梗、枳壳、葛根、栝蒌、半夏曲，服下而热渴如旧。改用柴胡二钱、人参、甘草、天花粉、黄芩各七分，白芍药、红花、当归、牡丹皮、知母各八分，调理而瘳。（一百三十一）", "6472": "朱氏子天送，时疾头疼，身若燔炭，口渴气促，申酉刻热潮更甚，舌心焦黑，遍体紫斑，语言含舌不清，时多发呃，耳聋。先治者误进藿香正气散，而加呕逆水泻。又医以柴苓汤，呕益甚，热转增剧。迎予为诊。六脉俱洪数，此少阳阳明合病之疫。以石膏五钱，知母、柴胡各三钱，黄芩一钱五分，半夏曲、麦门冬、竹茹、橘红、葛根各一钱，粉草、枳实各五分，服下热退其七，舌不燥矣。再以柴胡、半夏曲、白芍药、竹茹各一钱，石膏三钱，麦门冬、知母各一钱五分，黄连、甘草、人参各五分，水煎饮之而斑退。诸症悉平。（一百三十二）", "6473": "桂亭兄，壮年原有湿热痰积，年逾艾，偶坠轿，跌伤背胁，专科以草药敷贴于外，内以药酒攻之而愈。越十五年，左胁痛，手不可近。左脉弦数，坚劲博指，小腹亦痛。知为旧瘀及痰积作祟。以青皮、赤芍药、黄连、当归尾各一钱，桃仁一钱五分，大黄二钱，滑石三钱，水煎，临服调玄明粉一钱，服下吐出痰涎碗余，大便仅行一次，而左胯及腿膝皆痛，夜睡不安。由小腹痛甚之故，此瘀物欲行而未能也。再与大黄、当归尾、红花、牡丹皮各一钱，桃仁二钱，滑石三钱，青皮八分，调玄明粉一钱，再下之。大便行三次，皆沉香色，稠黏瘀物。腹痛虽除，胯痛仍在。用乳香、没药、归尾、红花各一钱，桃仁、滑石各三钱，大黄二钱，穿山甲、丹参各一钱五分。服后大便行四次，所下皆紫黑如筋膜者，不可胜计。诸病悉减。因食鸡汤牛肉，脐腹又痛。里急后重，此余积未尽，欲再下之。举家惊怖，谓六旬已外之年，已下数次，恐脾弱不能再下。予曰：医贵认病，何以年齿数下拘哉？今药力到而积已动矣，破竹之势，可迎刃而解。若失时姑息，恐他日滋蔓，欲下难动也。行后而补，庶无反顾之忧。大兄然之。以红花、桃仁、当归尾、赤芍药、山栀仁、玄胡索、牡丹皮、穿山甲、滑石，煎调玄明粉，下二次，紫黑瘀物如前之半，腿胯小腹痛则俱释。次日用人参、茯苓、白芍药、粉草、陈皮、山楂、桂心、当归、半夏，调养半月，精神步履饮啖一如旧矣。（一百三十四）", "6474": "堂弟东里内子，咳嗽吐红，发热头眩，脚膝乏力。先已服滋阴降火十数剂不愈。饮食渐少，精神渐羸，恳予治之。两寸脉累累如贯珠，两尺俱软弱。此上盛下虚之候，上盛者痰与瘀血也；下虚者肾阴弱也。且生平好饮，不无助热，法当先清上焦，化去瘀血宿痰。然后以养阴收功，则病根可刈，痨瘵可免也。用贝母、枳壳、桑白皮清肺化痰，滑石、桃仁、牡丹皮、小蓟消除瘀血，山栀子、甘草、白芍药养血以祛余热。三帖后，红渐稀少，前后心始不胀痛。惟痰嗽不止，大便结燥。减去滑石、桃仁，加栝蒌、黄芩、紫菀，调养而平。（一百三十六）", "6475": "由溪程竹坡孺人，年过六十，为疫所染，头疼口渴，舌苔前黄燥，后紫黑，身热沉重，人事昏愦，语言错乱，小水短涩，呕逆烦躁，合目不开，谵语不辄口，耳聋，胸胁痛，时五月初旬也。迎予为诊。左浮而弦数，右洪长而数，诊毕，仲君清夷问曰何症？予曰：此热病类也。清夷曰：因体热便名热病乎？予曰：否！否！仲景谓：春温过时为热病。矧兹又为热疠也。邪在阳明少阳二经。又问曰：可生乎？予曰：脉症对，可生也。此症远迩染延甚伙，不足怪。清夷曰：适方和宇亦云少阳阳明二经之病，二公所见既同，乞商确一方为幸。予与和宇诊多符合，即以柴胡、石膏为君，知母、麦门冬、天花粉、竹茹为臣，黄连为佐，甘草、枳壳、桔梗为使。连进二帖，丑刻微汗，热退神清。不虞即进荤粥，下午又复大热，谵语昏沉，举家惊怖。予曰：此食复也，即以小柴胡汤，加山栀、枳实、淡豆豉、鳖甲，四剂复得汗，热从散去，神顿清爽，仍口渴烦躁。以生脉汤，加黄连、香薷、竹茹、竹叶而安。（一百三十七）", "6476": "程家内眷，藏溪汪氏女也。乃夫殁于疫疠，新寡七日，疫即及之。大热、头疼口渴，胸胁并痛。医与小柴胡汤，夜忽梦夫交泄而觉，冷汗淫淫，四肢如解，略不能动，神昏谵语，面如土色，舌若焦煤，强硬。迓予诊之。六脉沉弦而数，大小便俱秘，此亦阴阳易类也。疫后有是，危已极矣。予以生脉汤，加柴胡、黄芩、桂枝、甘草，水煎成，将乃夫昔穿旧裤裆，烧灰调下，两剂而神醒，体温，汗敛，舌苔柔和，焦亦渐退。次日仍以前方，加酸枣仁、竹茹、四肢始能运动，乃饮粥汤。仅一子，甫十岁，一女，甫十四岁，继被疫困，均以六神通解散汗之而安。妯娌及婢辈六人，皆六神通解散瘳之。举家德予，以为再造。（一百三十八）", "6477": "族侄太学从明，夏初，由客邸患滞下，调半痊而归。因食隔宿猪首而复。里急后重，昼夜三四十度，日渐沉困。口渴，胸膈焦辣，手心热，腹微痛，小水少，每解时，先干哕呕恶，汗出飞飞，下皆稠黏紫黑血，无粪。彼素知医，且慎重，不轻服人药，敦予诊之。脉左沉弦，右滑数。面色外黑内黄，饮食不入，肛门辣疼。予以渠原禀薄弱，今远归，途次不能无劳，不敢疏下，故以胃风汤加黄连，与二帖不效。腹稍加胀，渠叮予曰：古云无积不成痢，顾积势胶固，切勿用补，无以体素弱为疑。予曰：诺。改用黄芩芍药汤，三剂无进退，乃私语渠侄元亮曰：令伯之症，实实虚虚，热热寒寒，实不易治。且谷食禁口不入，干哕可虑，须得明哲参治。元亮从容言之，欲得方古墩为翼，诸相契及内眷递相赞言，太学不从。曰：吾岂不重命而吝费哉。顾新都之医，无如叔最明。吾之交，无如叔最厚，舍叔安所倚？元亮曰：叔祖善矣。能用人之长，得一隽商确，可无后虑。太学拂然曰：知莫贵于知心，吾知其心久矣，专任勿疑也。予知渠信任坚若金石，益加研究。图欲先开胃口，使新壳食将宿秽压出，或补或攻，视缓急以为方略。乃背嘱元亮曰：令伯非人参不可，幸且勿露，俾予得以尽技。元亮曰：诺。乃仿朱丹溪法，用人参、黄连各二钱，煎浓细细呷之。但得一呷下咽，胃口便开，呕恶便止，盖胃口虚热冲上为哕也。其日用之，呕恶即止大半，连与二日，觉胸腹胀，即以保和丸应之。觉小水不利，又以清六丸应之。里急后重，以参、术，加芩、连、木香、槟榔、滑石、桃仁应之。人参皆背加，太学不知也。渠每诊必叮予曰：日来疾稍平，叔方力也。幸勿遽补，恐废前功。予曰：如教。讵知人参已服过十日，计二两许矣。此后脉仅四至，软而无力。忆丹溪云：虚回而痢自止。又云：气虚甚者，非附子不能行参、耆。乃以胃风汤，加黄耆、附子、姜炭，四剂而血全无，后重亦止，惟大便泻而不实，所下俱黄粪。渠知积滞已尽，始欲理脾，用参苓白术散，服十日，便仍不实。乃问予曰：补脾而泻不止，奈何？予曰：据脉乃下元虚寒，殆肾泄，非脾泄也。温补下元则固矣。盖肾者胃之关，初不敢用下剂者，虑有今日也。教以菟丝子、破故纸、杜仲、山茱萸、人参、大附子、白茯苓、泽泻，四帖全瘳。里中称太学能知人，而予不负所任也。（一百三十九）", "6478": "查少川公，年四十三，夙有哮喘疾，每发则遍身如燎，气贲贲上腾，息息短促，候中痰声响若汤沸，经七昼夜，汗而渐平。居常嗜饮，通宵不辍，醉后纵欲，不避风寒。族中有教以石膏、麻黄、杏仁、枳壳、细茶各一两，作大剂饮之，名曰五虎汤。喘至即以此御之，随饮而止，屡发屡进，应若桴鼓。公喜甚，恃为保命丹。寓大通一月，邑中麻黄、石膏为之缺市。讵知情欲无穷，胃中冲和有限，三年之间，饮五虎者，殆不可以数计，而胃中之冲和者，亦不知损之何若也。因而腹大若覆箕，两腿光肿如柱，内外臁疥疮中清水涓涓流之不竭，昼夜腥气逼人，不能伏枕而卧者五越月。自仪杨医起，闻京口之医，如何、张者最良，遍延治之弥月，卒无一验。又舍京口抵姑苏，历嘉杭，凡有名者，悉迎疗之，而势益剧。舁回至岩镇，镇医擅名者，吴与方也。先诣吴，吴骇辞不治。就方，方诊视久之曰：公疾非常，必得非常人乃可已。公曰：先生世家大方，昔在两淮，且人人引领，愿得先生一诊为快。何我弃而使需非常人，舍先生其谁。方曰：嘻，公贵邑孙生生者，名动三吴，今归不出，亟迎治之，或可无恙。公叩孙生生居何里，状何若。方书予姓氏里居与之，归即恳程公山氏绍介迓予。时长至后一日也。至则见公坐高椅之上，气高而喘，身热而烦，覆以绵被，足纳火箱，前后左右环火五盆，首戴绒帽，帽外笼以貂套，套外仍束一帕，鼻用绒套笼之，门设重幔，犹凛凛怯寒。诊其脉，浮大无力。睇其色，白中隐青。徐问公曰：恶寒身热从何时起？公曰：十日。予曰：据色据脉，予已得其概矣。公历数府名家，认为何症，拟何汤剂，请详述之。公曰：众论落落不一，先生学博见真，愿惟命。予曰：公疾乃气虚中满，法当温补下元。人徒知利小水，不知小水不利者，由下焦之气不充，不能渗从膀胱故道而行。若利之急，则汛滥而横流肌肤，下于阴囊，甚则胀裂崩塌而出。若使下焦壮盛，则小水自通。譬之甑炊，釜底水火交旺，甑中之气，自然蒸腾，若雾若露。《内经》曰：上焦开发，宣五谷味，熏身充肤泽毛，若雾露之灌溉，是谓气。故曰：上焦如雾也。清阳升则浊阴降，降下则为小水，故曰：下焦如渎也。渎者水也。言下焦为决水之官，水道出焉者是也。人之汗，即此雾露之气，水小即降下之气。盖气者水之母，由气化而为水。故又曰：气化则能出矣。融众理而观之，总由下焦元气壮盛，斯能升降变化。清阳升，浊阴降，即地天交之泰。阳不升，阴不降，即天地不交之否，否者塞也。此胀满之所由生也。公之疾，起于五虎汤，致脏寒生满病也。公曰：善。吾乃今始知致病之源，第近来身热手热，膈内焦辣而外恶寒，竟不解孰为热，孰为寒也？予曰：仲景云：伤寒必恶寒。由寒邪在表而然，合先散之。胸膈焦辣者，乃阴盛格阳，虚阳之火，被寒气驱逼上行，非真热也。经云：水流湿，火就燥，但得下元一温，热自下行。公曰：然，惟先生命剂。予以紫苏、马蹄辛、炙甘草、防风、白豆仁、苍术、陈皮、人参、羌活、生姜。一帖而得微汗，悉彻去环列之火，仅存足底一盆。首上所覆之帕亦去。独鼻寒如初。乃用防风、黄耆二两，煎汤置器中，令薰其鼻，饭顷而止。一日凡三薰。次日鼻套亦除，呕恶不止，用人参温胆汤加丁香进之，一帖而止。又谓鲤鱼能利水，一日尽二斤半，夜胀极，乃告急于予。予曰：病势如是，固乃纵恣若此，等闲之剂，曷能消释。沉思久之，以平胃散一两，入橄榄肉一两，水煎饮之，两剂而定。独腹胀小水不利，不能伏枕为苦。乃以附子理中汤，加砂仁、补骨脂、赤小豆、桂心，连进四帖，小水略长。继以尊重丸，日三服之，每服五丸。五日后，小水通利，可贴席而睡。守此调理，腹胀渐消，两月大平，三月而公出市，市中人信予，实从公始。（一百四十）", "6479": "夏益吾，肢节肿痛，手足弯痛肿尤甚，不能动止。凡肿处皆红热，先起于左手右足，五日后，又传于左足右手，此行痹症也。且喘咳气涌不能睡。左脉浮数，中按弦，右滑数。乃湿热风痰壅遏经络而然。以茅山苍术、姜黄、苡仁、威灵仙、秦艽、知母、桑白皮、黄柏、酒芩、麻黄，水煎服下，而右手肿消痛减。夜服七制化痰丸，而嗽止，乃得睡。再剂，两足弯消其半。左手经渠列缺穴边肿痛殊甚。用苡仁、苍术、秦艽、甘草、天花粉、五加皮、石斛、前胡、枳壳、威灵仙、当归，旋服旋愈。（一百四十一）", "6480": "初阳侄乃政，先时咳嗽，诸治无功，且嗽急则吐。用碧玉散二钱，白汤调下，立止。后半年，复咳嗽，胸背隐隐疼痛，身常内热。咳出桃花脓，不可胜计，腥秽之气甚恶，右胁并乳胀痛，脉洪数，大便燥，肌瘦骨立，此肺痈症也。用贝母、茜根、白芍药各一钱，知母、麦门冬、山栀子、紫菀各八分，桑白皮、当归、牡丹皮、杏仁各七分，薏苡仁一钱五分，甘草、葶苈各五分，水煎服之。服此甚安，但要常服，若一缺药，其疾便发。据此肺窍中痰积瘀血尚多，未能即去，宜缓图之。书云：俟脓去尽，当自愈也。愚谓丹溪虽有此言，亦不可固执，设不以药消化之，必俟其脓自尽，恐岁月深而有他变。且中年之人，何能当此。莫若清热润肺，消痰化瘀，久而服之，或早愈也。方黄吴诸公谓久咳伤肺，每每投补，屡被紊之，每补必增热加痛加咳而脓转多。予晓之曰：诸公之意诚良，其如病加何，是姑息之谓也。古人不务姑息，惟以去病为安。夫姑息可以养病，非所以去病也。独汪无怀然予言，守予法，二年良愈，肌长如初。（一百四十二）", "6481": "族侄仲木内人，肾淑妇也，不育，多郁，腹胀，左胁不能侧卧，亦不能仰卧，仰侧卧即气涌。每午夜背心作胀。气喘吐痰发热，必起坐令人揩摩久之始定。面有浮气。右寸关脉滑大有力，此气郁食积痰饮症也。盖忧思伤脾，思则脾气结，气结不行，则五谷之津液皆凝聚为痰，故喘急作胀。先与定喘汤二帖，而无进退。继用核桃肉五钱，杏仁三钱，人参、桑白皮各七分，水煎服之，气喘乃定，惟腹中胀急。改用橘红、半夏曲、木香、白豆仁、郁金、萝卜子、姜连、香附、茯苓，四剂，大便痰积随下，腹胀寻消而愈。（一百四十三）", "6482": "侄婿程东山，仲夏患休息痢，所下皆紫血，腹痛，迨清明犹不愈，医药备尝，体倦肌瘦，或三五日一发，或七八日一发，发必三日乃止。予为诊之。左涩而右滑。据脉有瘀血痰积。近来小水不利，姑用四君子汤，加滑石、红曲、陈皮、山楂、泽泻、升麻，服后微觉有热，改以四君子汤，加滑石、桃仁、红曲、酒连，神气稍旺，脾气始回。乃用番鸦胆三钱下之，果去紫黑血块及如败鱼肠者半桶。从此痛除痢止。次日，以六君子汤，去半夏，加酒炒白芍药、山楂、红曲、滑石、桃仁、升麻调之。报云：胸膈作胀，恐积滞未尽，而服参术，欲再下之。予为再诊。两寸短弱，两尺洪大，前日滑涩二脉俱无。此阳虚下陷之候，宜当大升大补。以六君子汤，大加黄耆为君，酒炒芍药为臣，升麻、桔梗为使。服此胸膈宽快。精神亦好。惟肛门热。前方加酒连，减半夏，脱然平安。（一百四十六）", "6483": "陈氏妇，肠鸣腹痛，大便溏泻，合目即汗出，下午潮热。医谓潮热盗汗乃虚怯之症，加之泄泻，脾气坏矣，视为不治。浼予诊之，右脉濡数，左脉洪数。予曰：此郁火痰积症也。盖忧伤肺，思伤脾，饮食因而不化，积而生痰，故腹痛溏泻。但理中焦，消去痰积可瘳也。以四君子汤，加半夏曲、滑石、红曲、麦芽、苡仁、酒炒白芍药、酒炒黄连、牡蛎、桔梗，八帖而病去如释。（一百四十七）", "6484": "九德侄，耳鸣，气筑筑然，闭而不通，鼻塞不利，口不知味，痰多而膈热不清，脉左浮而弦大，右滑大，俱数。《内经》云：头痛耳鸣，九窍不利，肠胃之所生也。此由胃中痰火上壅，热极生风。乃以蔓荆子、升麻、木通、赤茯苓、桑白皮、麦门冬、生地黄、前胡、甘菊花、赤芍药、甘草、石膏，生姜三片，枣子一枚，水煎饮之四帖，左弦虽减半，而症尚如前。再用甘菊花、橘红、半夏曲、茯苓、甘草、知母、白芍药、酒芩、麻黄、石膏、桑白皮、桔梗，加姜枣，又四帖而诸症悉平。后以六君子加酒连、柴胡、川芎、白芍、麦门冬、升麻，两帖，饮食亦甘味矣。（一百四十八）", "6485": "陈觉宇丈，常山县人也，年四十有三，体肥，患痰火十年多矣。每月必一发，或劳心过度则二发。吐痰身热，吼喘，饮食不进，不能倒头而睡，合目则乱语，面赤头痛。遍身痰气走动，牵扯作痛。必俟吐出痰后，则耳始不鸣，目始不泪。素服风痰药南星、半夏之类，不效。后服参、耆，则亦仅止四五个月。诊其脉，两寸洪滑，两尺沉微。殆上盛下虚之候，法当清上补下。以橘红、贝母、茯苓、甘草、桔梗、杏仁、前胡、钩藤、天麻、酒芩、枳壳，水煎服之，夜进七制化痰丸，再以八味丸，加人参、麦门冬、五味子、空心服之，半年而瘳。（一百四十九）", "6486": "表嫂孀居二十年矣。右瘫不能举动，不出门者三年。今则神情恍惚，口乱语，常悲泣。诘其故，答曰：自亦不知为何故也。诊之，两寸脉短涩。以石菖蒲、远志、当归、茯苓、人参、黄耆、白术、大附子、晚蚕沙、陈皮、粉草，服四帖，精神较好于前，但悲泣如旧，夜更泣。予思仲景大枣小麦汤，正与此对。即与服之，两帖而瘳。方用大枣十二枚，小麦一合，大甘草炙过三寸，水煎饮之。此忧伤肺脏，脏寒故多泣也。（一百五十三）", "6487": "堂嫂王氏，两寸脉洪大，右关滑大，五六月间，必吐紫黑血块，足跟焮肿痒痛，时流黄水。与牡丹皮、山栀子、玄参、甘草、白芍药、当归、陈皮、滑石、桃仁，四剂而愈。（一百五十五）", "6488": "仲暗侄孙，赴府考试，过食牛面，且劳苦，因而发疟。城中医疟半月，形神俱瘦。疟愈而腹大如箕矣。健所黄夫人，仲暗岳母也。凡名家为延至，率认疟后腹胀，其中必有疟母为祟也。诸消痞药尝之不效。又以五皮饮利之，不应。将议攻下，而予适至。观其色黄口渴，小水短涩，腹胀不可言，足膝之下，肿大不能行。两腿肿连阴囊，气壅不能卧。饮食绝少，脉才四至，大而不敛。予曰：此真气虚中满症也。法当温补下元，而兼理脾，病犹可愈。若攻下是杀之也。渠父与予厚，今宦河南，予安得不为渠任其重哉。顾歙友所用之剂，乃皂角、槟榔、三棱、莪术、姜黄、葶苈子、木通、枳实、青皮、厚朴、山栀、大黄、牵牛、黄连等，皆破敌有余之品，见之且骇然。但黄夫人荐来之医，又不能拒。正踌躇间，幸渠乃伯溪亭公知予心，卒谢歙医，而一任予治。予即以人参、白术各三钱，炙甘草五分，大附子、炮干姜、桂心各一钱，破故纸二钱，桑白皮、砂仁、茯苓、泽泻各八分，水煎饮之。其夜小水稍利，喘急稍缓。连饮五日，腹稍宽，皮作皱。因食猪肝子太早，依旧作胀。前方人参、白术加作五钱，再加陈皮八分，又二十剂。而腹消其大半，乃能伏枕而卧，始能移步行动。改以参苓白术散，加破故纸、肉桂，调养而安。溪亭公问曰：腹胀如此，口渴如此，小水短涩如此，诸人悉认为热，为有余，乃今以温补收功，何也？予曰：公不观古人以气中满名鼓胀耶？由气虚所以成中满。设气不虚，何中满之有哉。且鼓者，外皮坚紧而内空无物。若复泻之，真元脱矣，安能复生？故惟有补而已。口渴小水少者，皆元气虚弱，不能转运，清气不上升，故口渴；浊气不下降，故无小便。乃天地不交之否。兹特补其下元，俾水火充实，阳气上腾，浊气下降，中气运动，而诸疾皆瘳也。（一百五十八）", "6489": "朱怀竹，壮年客外不谨，而生杨梅疮。恐人知之，又欲回家，乃求速愈。每日用药外熏，熏而不效，用药水频洗，洗而不瘳。乃以末药点之，一日凡服煎药三帖，如斯两月，不惟疮不能瘳，毒且赶入内。在下则肛脱二寸余，周匝疮满如蕈，弗克收入，因而不能行坐。在上则毒入于肺，喘咳气涌，胸膈胀闷，不能仰卧，内热而外恶寒，寝食俱废，合目即谵语。阴囊疙瘩红肿胀痛，两足疮延肿大，精神恍惚，软床舁归。乃兄少竹，逆予为诊。六脉俱洪大而数。语少竹曰：病至重，幸壮年，犹可治也。今予尚未可付药，俟彼胸中瘀血毒物出后，乃可服。否则彼以予药动血，而反致疑。顾城中诸友，鲜有识此病者，一误则大事去矣，慎之慎之。少竹素信予，固请予药而不与其服。怀竹见予不发药，乃延张程二公为治。晌午服药，晡刻大发喘咳，吐出紫黑血块如脓之类碗余，满房腥秽不可近。怀竹心慌，少竹慰之曰：毋恐。孙君先已预言，汝胸中胀闷者，由熏药逼毒入内，上迫于肺。痰与瘀壅遏肺窍，将欲成脓，故喘咳不能伏枕。故脉洪大而数，从可知也。必俟吐后，乘而消之，极易为力。今果如孙君言，孙君药具在，急煎饮之。药用牡丹皮、桑白皮、白藓皮、木通、前胡、枳壳、桔梗、甘草、杏仁、苡仁、葶苈子，服后大便里急后重者二十余次。所下黑紫脓血甚多。喘咳稍定，痰红稍淡。二三剂乃能伏枕而睡。改用白芍、当归、白藓皮、甘草、贝母、黄连、金银花、皂角子、苡仁、麦冬、木通，连饮二帖，足上跟踝疮肿渐消，其夜阴囊出臭脓血二碗许。次早诊之，两尺脉不洪大矣。仍用前剂，加丹参，又二帖。阴囊结靥甚厚，横裂一缝。三日后，随缝连皮落下，约重五六两，厚可半寸，色如猪肝。洞见两阴子，系一光薄白胞，令人骇然，此亦亘千古稀见者。举家谓阴囊乃致命之所，且未有子，今烂去，即使复好，亦不能育子矣！环哭甚悲。予谕之曰：此毒去也，而真元不伤，吾能使其生肉如故，亦不妨于生育，毋过虑焉。举家将信将疑。予即用红粉霜加生肌末药敷上，一日三次，并不作痛，脓水立干。外以人参、当归、酒炒白芍、白芷、甘草、白藓皮、皂角子、苡仁、何首乌，调理一月，囊肌全生，诸症悉愈。乃令日用土茯苓、猪肉各半斤。同煮极烂，将肉入酱盐如常法食之，汤当茶饮。脱然全瘳，次年生女。（一百五十九）", "6490": "查良本兄令眷，怒后偶食鱼头，骨梗于喉中，即以馒头、粽肉等压之。骨虽下，便觉胸膈不快。又服消骨药两日，迨今乃七日矣。胸膈胀痛殊甚，饮食悉从背后而下，恶寒发热，六脉弦数。予思骨梗之后，用硬物压之，伤其胃脘，必有瘀血停留膈间，将食管逼在背后，故饮食觉从背后下也。今但消去瘀血，使食管复原，胸膈之痛可瘳矣。药以五灵脂为君，山楂、玄胡索、桃仁、枳壳为臣，赤芍药、牡丹皮、香附、山栀仁为佐，柴胡、石菖蒲为使。水煎，临服入韭菜汁一酒杯饮之。其夜胸膈宽快。大便泻一次，痛减大半。饮食乃从右边而下，右边胸喉稍痛，吞物甚艰苦，吐出痰皆血腥气。改以山栀、赤芍药、归尾、桃仁、刘寄奴、五灵脂、牡丹皮、穿山甲，煎入韭菜汁服之，两帖全瘳。（一百六十）", "6491": "后谿大兄孺人戴氏，勤笃严谨人也。秋患痢，所下皆血及屋漏水，内有血子如赤小豆者，不可计数。昼夜五六十行，里急后重，呕恶不住声者五日。予以刘守真芍药汤，与三剂而病无进退。适后谿兄在浙，侄女辈素信医博黄氏为女科专门，延而治之。投以芩、连、枳壳、槟榔、山栀、地榆、黄柏、滑石之类，服已五日。始虽呕恶，一日尚有碗粥，今则粒米不进，腹痛转加，必用重物压之乃稍定。神思昏弱，卧不能起，下午发热。女科仍以前剂加青皮、枳实。侄孙尔嘉持药见予曰：家姑酷信黄医为专门，今已任事五日，较前精神大瘁，叔翁为祖父至交，宁无一语启愚乎？予曰：吾非不言，欲诋黄，恐为妒妇之口，今子来，予可诊。六脉滑大无力，诊毕，慌语尔嘉曰：事急，可速令人促乃祖归。否则令姑女流，不谙医药，吾安能施其巧。比有西席汪带川闻之，决尔嘉曰：此事极要调停，留黄医以安女流心，黄发之剂，阁而不进，以东宿之剂作黄剂进之，内外无猜则妥矣。予然其言，以人参、白术、酒炒白芍各三钱，炙甘草一钱半，炮姜、肉桂各一钱，白术、酒炒白芍各三钱，炙甘草一钱半，炮姜、肉桂各一钱，白茯苓、陈皮各八分，砂仁五分，大枣二枚，水煎饮之，呕恶减半，其夜痢减十之五，惟腹痛不甚减。次早诊之，脉稍敛。黄医以为渠功，大言自矜。仍以芩连之类。予仍以前剂，再加黄耆。其日下午始纳粥一茶盏，腹痛渐减。又次晨，黄医诊视，见夜来痢减其七，益得扬扬得志。语左右曰：寒家业医五代，似此大病，亦不多见。自以为非彼亦无能治也。尔嘉诘曰：疟痢亦寻常耳，何以为大？黄曰：丹溪云：下痢身凉者生，身热者死。下痢纯血者死。脉洪大者死。如屋漏水者，半死半生。今皆犯之，故云云也。尔嘉曰：然则今日当用何剂？黄曰：剂已投病，仍当确守前方，何敢轻改？尔嘉笑而点首。复向予求剂。予以理中汤，倍加酒炒白芍药，以肉桂佐之。腹痛身热悉愈，痢十去九矣。后谿兄亦浙回，尔嘉述病源，以黄方予方呈看。后谿唏嘘叹息。乃辞谢黄而诘予曰：人言下赤痢者热，呕恶者热。又身热脉大，吾弟何独认为寒，而用此大热之剂成功，曷故哉？予曰：此虚虚实实之处，极能误人。尊嫂之热，非真有余之热，乃内有虚寒，逼真虚火上升，故呕恶潮热耳。脉大而无力，仍作虚看，且向服寒凉不效，当自知警也。后谿兄曰：微弟几败乃事矣。（一百六十一）", "6492": "邵敬圃令眷，常胃脘痛，由气郁而起。近以产后下痢红白，而胃脘之痛不止。汗多，六脉滑大无力。法当收敛。以小建中汤为主，白芍药酒炒四钱，炙甘草一钱半，桂皮、五灵脂醋炒各一钱，香附、糖球子各八分，水煎饮之。痛减，汗未全敛。次日前方加御米壳醋炒过一钱，两帖全止。（一百六十二）", "6493": "苏文学望台患疟，一日一发。先寒后热，热多寒少。胸膈痞闷，口渴，小便溷浊，腥臊不可近。医五越月不效。面黄肌瘦，饮食减少。喘息呻吟，精神疲惫，起须人扶。乃敦予治，脉得沉弦而数。公问曰：是疟否？予曰：是。公曰：吾闻之，真病不治，治之无功。盖真者，死候也。疟殆常病，不过寒热虚实表里。诸名家曾认为表症者，麻黄、羌活、柴胡等汗之矣。有认为里症者，大柴胡汤辈下之矣。有认为痰饮者，常山、矾石吐之矣。有认虚寒者，附子理中汤，人参服过三斤矣。有认为实热，用白虎汤、枳实、青皮、槟榔、草果消之矣。尽法备尝，绝无一应，疟岂亦有真而卒至于死耶！言讫泪潸潸下。予曰：观公色脉，疟将发矣，不暇辩，第饮予药不死也。以柴胡、滑石各五钱为君，鳖甲三钱为臣，黄连、知母各一钱为佐，枳实、甘草各五分，黑豆四十九粒为使，水煎，送下昆布鳖甲丸。申刻疟至，戌初便止。公喜曰：向者疟发未申，夜半尚不能止。即止犹倦怠懒言。适饮先生药，不两时而止，止便能言，先生之功也。予曰：偶耳。今日服药已晏，明日五更幸早服之。服讫竟日不发。又次日。前方加人参、白术，小水腥臊之气已无。精神陡长。公又喜曰：两日无苦，先生之功也。予曰：偶然耳。公曰：嘻，吾疟几半载，休歙之名公，莫不历试，卒无影响，先生一举奏奇，有而不居，益见所养，不审汤名何剂，乞指示之，以诏将来。予曰：公何以名为哉。老子曰：无名天地之始。矧医亦道也，即道，亦是强名。医贵识病，苟识病，一二三品便能成剂立功。经云：约方如约囊。又曰：方以类聚，方凭病立。苟不识病，即尽本草一千六百五十六品，并而服之，未见其益也。疟固常疾，治亦不易。仲景有言曰：治疟当分六经。予谓即六经之中，又各有寒热虚实阴阳在焉。是六六而三十六也。即三十六之中，又有挟痰、挟食、挟气者，禀弱者，曷能枚举。人与天地阴阳一致，天地变化无穷，人身灾患不一，岂拘拘一百一十三方，三百九十七法所能概哉。王节斋曰：古人因病以立方，非立方以待病也。斯言深得轩岐立方大意。然予今日所用之剂和剂也。仲景谓：汗吐下后，而邪热不减者，是为坏症。以小柴胡汤加鳖甲治之。予恃仿仲景小柴胡例，加益元散彻邪热从小便中出。鳖甲虽治坏症。又能截疟。公曰：噫嘻，前此诸公，看病不过曰寒、曰热、曰虚实而已。未尝有此妙论。诚空谷跫音也。吾闻先生从祝令君潘去华辈，六邑会中讨究理致。又曾览先生序大易彀、序翼飞，乃知先生融三教而萃于医。先生之医，得之于性命窍中，故能全性命也有如此。（一百六十三）", "6494": "大塘徐公讳客者，其子弱冠，肌肉瘦削，尻膝肿大。手肘肩颙皆肿，肿处皆痛而发热。时医有作风治者，有作湿痰治者，有作鹤膝鼓槌风治者。愈治愈重，伏床蓐奄奄一息耳。举家仓皇而决之蓍揲者，释策曰：易象可不死，天医上卦，第远在东方，相去百里而遥，迎而治之无恙也。因访予而迎之治。予诊其脉，六部皆弦。观其色青而白。饮食少，时当长至。予曰：此筋痿症也。书云：诸痿皆不可作风治。病势几危者，以前药皆风剂耳。风能伤血，血枯则筋愈失养。况弦脉乃肝木所主，搀前而至，是肝有余而脾土受敌。脾为所伤，宜饮食少，肌肉削而势将危也。《内经》曰：诸痿独取于阳明为治。阳明者，肠与胃也。法当滋补肠胃，俾饮食日加，五脏六腑有所禀受。营卫流行，气煦血濡，调养至春，淑气司令，君火主事之时，宗筋润而机关可利也。病者年虽少，而能闻言相信，恳予为治。予立方五加皮、苡仁、甘草、苍耳子、枸杞子、回阳、人参、杜仲、黄柏、黄耆、防风，服二十剂而精神壮，腰膂健，饮食加。惟间或梦遗，则为减去杜仲，而加远志、当归，三十帖而全安矣。此余初发之治也。（一百六十五）", "6495": "太溏程巢父文学乃郎讳万里者，年十五，夏月患痢。族医为治弥月，痢止而筋骨肿痛，痛处发热，昼轻夜重。肌肉消，饮食少，烦躁。医者以白虎历节风治之。病剧而形削骨立矣。又作鹤膝鼓槌风治者，法愈更而病愈甚。其家有程松谷者，博洽嘉闻君子也，为巢父族大父，以余在西吴治多奇中，命巢父迎余。予至诊之，脉皆细涩。曰：此痢后风也。盖由治痢不善，以致寒湿秽瘀凝滞经络，日久气血为痛所伤。此症虚虚实实极难认，而措药不易，欲补虚则肿愈剧，欲疏通则痛愈甚。惟《局方》大防风汤可愈此疾也。防风、熟地、黄耆、人参、白芍、当归、杜仲各一钱，白术一钱五分，羌活、牛膝、甘草、回阳各五分，川芎七分，加姜三片，水煎服，服三十帖而愈。", "6496": "叶润斋，年近四十，心膈嘈杂，好啖肉，尤好鸡，一日不能缺。缺即身浮力倦，神魂无措，必急得肉乃已，见则大嚼。及入腹，腹又大痛。痛极则吐酸水稠涎然后定。稍定，又思肉啖也。其痛苦之态，喊叫之厉难状。见者酸鼻，而润斋则甘心焉。市人咸以为祟。或有谕之者曰：古云与其好肉而受痛，孰若绝肉以无楚也。久病脾虚，肉入难化，故使作痛。此妇人女子且知之。汝丈夫独不慎，何哉？润斋曰：吾岂不知绝肉之为愈也。盖痛虽苦，尚能嗷。若嘈杂，则遍身淫淫苏苏，左右无可奈何，手足无所把捉，顷刻不能自存，有近于死不能熬，急需肉少苏，吾岂纵口求痛哉！不得已也。乃翁延予为诊。六脉大小不等，观其色，唇红脸黄。予曰：据色脉乃虫症，非祟也。予能拯之。先与雄黄丸一服，不瘳。改以腻粉五分，使君子末一钱，用鸡子打饼，五更空心饲之。辰刻下长蛲十条。内有二大者，长尺有咫，自首贯尾皆红。下午又下小虫百余。自此再不喜肉，而嘈杂良愈。（一百六十八）", "6497": "程相如丈令政郑氏，孕逾七月，因食冷患痢。所下皆白脓，腹痛后重，小水不利。两关脉滑数。以艾叶、砂仁、白芍药、白术、厚朴、泽泻、滑石、甘草与之。痢如旧，小水仍不通利，夜更痢频。改用当归、白芍药各二钱，益母草、酒连、酒芩各一钱，滑石三钱，枳壳七分、木香、甘草各三分，艾叶二分，两帖而安。（一百六十九）", "6498": "太塘程晓山，程松谷从弟也。客湖州，年四十。悬壶之日，湖中亲友举贺，征妓行酒，宴乐月余。一日忽言曰：近觉两手小指及无名指，掉硬不舒，亦不为用。口角一边，常牵扯引动，幸为诊之。六脉皆滑大而数，浮而不敛，其体肥，其面色苍紫。予曰：据脉滑大为痰，数为热，浮为风。盖湿生痰，痰生热，热生风也。君善饮，故多湿。近又荒于色，故真阴竭而脉浮，此手指不舒，口角牵扯，中风之症已兆也。所喜面色苍紫，其神藏，虽病犹可治，切宜戒酒色，以自保爱。为立一方，以二陈汤加滑石为君，芩连为臣。健脾消痰，彻湿热从小便出。加胆星、天麻以定其风，用竹沥、姜汁、三拌三晒，仍以竹沥打糊为丸，取竹沥引诸药入经络化痰。外又以天麻丸滋补其筋骨。标本两治，服二料，几半年，不惟病痊，且至十年无恙。迨行年五十，湖之贺者如旧，召妓宴乐者亦如旧，甘酒嗜音荒淫，而忘其旧之致病也。手指口角牵引掉硬尤甚。月余中风，右体瘫痪矣（瘫痪俗所谓半身不遂也）。归而逆予诊之。脉皆洪大不敛，汗多不收，呼吸气促。予曰：此下虚上竭之候。盖肾虚不能纳气归原，故汗出如油，喘而不休。虽和缓无能为矣。阅二十日而卒。（一百七十）", "6499": "去予舍二里许，地名曰前坑口。一妇人，清明前十日，发热头痛，医以九味羌活汤、十神汤进之不效。而又加口渴，舌黑如煤。更一医，以如神白虎汤、竹叶石膏汤进之，亦不效。而加泄泻不止。人事昏沉，四肢厥冷，呼吸气微，米粒不进者十四日。其家为具含敛而待毙。适予扫祖墓而近其家。其子闻之，即告急于予。恳为一诊。其脉细如珠丝。予曰：此疫症也。合理中生脉二汤饮之。连进二服，夜半神气稍苏，饮粥汤半盏，次早六脉渐见。予喜语其子曰：可保无事。书云：脉绝微续者生。仍以前药与之。至晚泻止，口不渴，舌心焦煤退，精神清爽，骎骎向安矣。再用人参、白术各五钱，炮姜、炙甘草各二钱半，麦门冬三钱，五味子十五粒，水煎，不拘时服。不数日而痊愈。（一百七十二）", "6500": "族侄孙子忠，患痢于湖之东双林，腹大疼，日夜行百余次，下皆红脓，状若腐烂鱼肠，绝无粪。疼而喊叫，声震中外。由孟秋饥饱后，娼家纵欲而得也。一病即伏枕，已十日余矣。予时寓雉城，相去百里外，渠叔少崖，邀予往视。诊其脉，皆缓大无力。始用芎、归各五钱，加人参、白芍药、桂心、木香、黄连，服四日不效。改用胶艾汤，亦不效。大孔状如竹筒，物食而下不变色犹原物。予思之，此脾经为寒湿所伤，脾不裹血故也。非附子理中汤加肉桂、肉果不可。进五六帖，痢始减半，饮食稍进。但所下秽恶仍若前状，亦无粪。渠父仲珪，家居闻报，即遍访徽之名家，佥嘱以切勿用补，兼程而抵苕城。儆虞留款，因询近用何剂，儆虞曰：闻用附子理中汤。人参每帖三钱。仲珪骇而堕箸，亟驰见予。潸然泪下。言曰：侄五旬仅此一子，症危如此，倘不测，后将何望？予曰：郎君险过矣，复何优。亦以侄只此一子，故殚心力相扶也。仲珪曰：离家而徽之名公，俱嘱以勿轻用补。侄故兼程而来。竟以补收功，非叔几于误事。吾儿自今以往之年，皆叔之赐。侄父子何以报效。予曰：治疾如救焚，医家分内事，矧属在宗䣊。且无德我之望，又何望报。第雉城之约不可失，若浼李钟泉邀吴荜斋代视数日，俾俾予得践雉城之约，庶两尽矣。而吴子疑而辞曰：病者危在旦夕，何孙公欲自脱手，而愚我被恶声也。予闻而哂之曰：见何鄙哉。丹溪有言，虚回而痢自止。病者再五日可脱然矣，予亦暂留。即以东垣和中胜湿汤与之。服七日，即衣冠出市。报谢四邻。吴见之而悔，李钟泉靳之曰：孙公欲成尔名，尔欲自没没也，悔之何补！吴由是改容相敬，令其弟游予门，彼亦纳交予而称莫逆。子忠之始病也，其友李钟泉重交谊，日夕省候，督其仆事汤药，毋许离蛙步。所下秽物腥臭不可闻，皆用漆布拭之，昼夜用数十斤，悉其湔烷，了无难色，两月如一日也。此友亦今时所希睹者，因并记之，以著其高。（一百七十四）", "6501": "有邵兄而讳马者，年五十，患呕吐。吐物如烂猪肺状，胸背胀。市上诸医，皆以翻胃治之不效。而反加潮热烦躁，饮食不入口。歙医谓肺坏，辞去不治。延予治之。诊其脉，两寸滑数，左关尺涩。予曰：此瘀血痰饮症也。非肺坏。果若肺坏，声音当哑，今声亮而独胸背作胀，瘀血痰饮明矣。此症殆由酒后怒发所致。盖肝藏血，脾统血，酒伤脾，怒伤肝，以故不能藏，不能统。血随气上，积于胸膈，必吐出而胀始宽也。法当消瘀血，调气化痰。气调瘀消，则新血始得归经，大本端而病根可除矣。乃为立方：滑石三钱，甘草五分，茜根二钱，小蓟一钱五分，桃仁、贝母、归尾、香附各一钱，山栀仁、枳壳、桑白皮各八分，服十帖而全安。（一百七十六）", "6502": "许卓峰者，多酒多怒人也。上吐血，下溲血，咳嗽声哑。族医皆以为瘵，辞去不治。迎予诊之。其脉左关弦大，右寸下半指累累如薏苡子状。予曰：此有余症也。作瘵治者非。客有辨之者。谓此症人皆认为瘵，而先生独谓非瘵，然何以失血而声哑也。予曰：其为人也好酒，酒属湿热而助火生痰，火性炎上，迫肺不降，积而生痰，壅瘀肺窍，肺属金，主声。书云：金空则鸣。金壅塞而不通，故哑。此痰壅之哑，非肺痿之哑也。其性又多怒，《内经》曰：怒则伤肝，甚则呕血并下泄。盖血随气行，气妄动，血随之亦妄动而不归原，故上吐而下溲。法宜清热开郁化痰，导血归原，不半月而病可瘳也。若认为瘵而以地黄、天麦门冬、牛膝、山茱萸之类，将甚其塞而益其热，声音何由而开。血随气行，气不清，血又何得归原哉。诸君试观之。予用滑石、青蒿解酒热为君，贝母、郁金、山栀仁、香附开郁为臣，杏仁，桔梗同贝母化痰为佐，丹皮、丹参、小蓟、甘草导血归原为使。服十帖，血果归原。又以贝母一两，童便浸一日，为末，柿霜等分，时时抄舌上化下。五日而声音开亮矣！计期不出半月。（一百七十七）", "6503": "族嫂钧孺人，年六旬，孀居已十余年，患痢，赤白俱下，腹微痛，昼夜二十余次。呕吐痰涎，粒米不入口者两月。日惟用薄白酒打鸡蛋花饮之。肌肉尽削，诸药不效。予归诊之，六脉滑数，知湿热痰火所致。以二陈汤加益元散，姜汁炒黄连，黄芩，服几四十帖，而呕止痢瘳。其病亦几危矣，予为治者，恃其神存。惟神存，虽形气不足不食，犹可不死。此亦医者当察也。（一百七十八）", "6504": "邵来仪丈令眷，咳吐红痰，或如桃花脓色，前后心稍胀疼，两寸脉洪滑。此瘀血痰火郁滞肺之气道，而欲成肺痈也。治当调气化痰，兼消瘀血，清利肺金。以山栀子、牡丹皮、贝母、桑白皮、赤芍药、麦门冬各一钱，白滑石三钱，茅草根五钱，小蓟二钱，甘草五分，枳壳八分，四帖而瘳。（一百七十九）", "6505": "程玄祖兄，春温食复。人事昏沉，内热口渴，舌如焦煤，胁痛耳聋，身热如火，僵硬不能转动，尸寝者十日，口中喃喃，盖梦语也。城中时疫正盛，亲友咸不吊庆。予为脉之。左弦数，右洪大而数。以柴胡、石膏各五钱，黄芩、知母、葛根各二钱，山栀子、枳实各三钱，甘草五分，连饮三剂，额上微汗，腹中雷鸣，其夜大便泻三次，皆清水，热仍不退。次早脉之，右寸稍软。前方加人参七分，又二帖而汗出热退。身仍僵，口仍渴，耳仍聋，泻亦不止，汗亦不收，四肢如冰，勺粒不进者已十三日。人皆以为死矣。予独不忍弃，以人参、麦门冬、白芍药、石斛各一钱，五味子十一粒，当归八分，桂枝三分，黄柏、甘草各五分。后再诊之，左脉已弱。咳嗽人事渐爽，粥饮稍进，乃能开目发声。泻已止，颇可转身，才有生气。后以四物汤，苡仁、甘草、陈皮、白术、石斛、百合、贝母，调理一月全瘳。（一百八十）", "6506": "汪郎兄，腹痛，呕吐不止。城中诸友，毕力医治不痊。予为脉之。早晚大小缓急不一，知其为虫痛也。以干姜、槟榔、苍术各一钱，五灵脂三钱，乌梅三个，川椒三分，水煎饮之，痛吐立止。（一百八十一）", "6507": "查景川兄遍身痱痤，红而焮痒。诸君以白蒺藜、荆芥、升麻、葛根、玄参、甘草、石斛、酒芩、甘草与之，不愈。又谓为风热，以玄参、蝉蜕、赤芍药、羌活、防风、甘草、生地、当归、升麻、苍耳子、连翘，服之饮食顿减，遍身发疮，痛痒不可言。予脉之，两手俱缓弱。以六君子汤减去半夏，加白扁豆、砂仁、苡仁、山药、藿香、黄耆，一饮而饮食进，四帖而痛痒除，十帖疮疥如蜕。（一百八十二）", "6508": "吴见南令郎心脾痛。因劳倦而致，每痛必得可口之物压之立止。两腿生疮。右脉滑，左脉弱。以白芍药三钱，甘草一钱五分，白蒺藜、碧胡麻各一钱，当归、黄柏各八分，石菖蒲、白茯苓各六分，四剂而痛止。仍用小建中汤，减去桂枝，加黄柏、苍耳子、白蒺藜、何首乌，炼蜜为丸，服之疮亦寻愈。（一百八十五）", "6509": "族侄女年甫八岁，腹高于胸，发热面红，咳嗽呕吐，甚则连血喷出。右关脉滑大有力。此风热羁绊于脾肺之间而然。以滑石二钱，枇杷叶一钱，麦芽、天麻半夏曲各八分，枳实、枳壳、防风、青皮各五分，水煎服之，热退嗽定，吐亦良瘳。（一百八十七）", "6510": "从兄𠹚年近五十，左胁痛，手足抽搐，不能步履。两手脉俱软弱。用当归、白芍药、木瓜、石斛、苍耳子、枸杞子各一钱，薏苡仁二钱，人参、牛膝各七分，陈皮、白芥子各六分，红花三分，水煎饮之。其夜大便下黑血二升，乃得睡，痛搐俱缓。改用人参、当归、白芍药各一钱二分，薏苡仁四钱，牛膝、木瓜、石斛各八分，红花、酒芩各五分，其夜大便仍有黑物，从此精神和好，寝食俱安。后五日，因为怒忤，且加食伤，右手左足大搐，左足大腿疼痛，缩而难伸，伸则痛甚。左胁极痛，小水短。用山楂、青皮、防己、人参、半夏曲、陈皮、苡仁、川芎、苍耳子、杜仲、石斛，以栝蒌为君，服下左胁痛止，右手亦不搐矣。惟左大腿内股筋痛，一搐则膝抵于口，此亦事之异者。因改以人参、当归、薏苡仁、甘草、黄柏、白芍药、钩藤、牛膝、木通、山栀子，诸痛搐悉愈，口亦不渴。后只以此法调理五日，随能纵步出户。（一百八十八）", "6511": "族侄良诠，患血痢腹痛，里急后重。时师治以香连丸、黄芩芍药汤不愈，腹反增痛。面赤唇红，有似涂朱。喊叫之声，四舍悚骇。比有太学宁宇者，仁心为质人也。怜其家贫莫秪，拉予为诊。六脉洪大，伏于床间，两眼泪而不能言。太学会其意，语予曰：症诚急，彼以后事无措，而难于言。予曰：诺！吾能起之。以生熟白芍药六钱，生熟甘草二钱，干姜、肉桂各一钱，木香五分，枣二枚，水煎饮之。饮竟嗒焉而卧。太学心疑，归嘱家奴曰：倘有急，叩门可即报我。及明见无动静，乃令人觇病者何若：复曰：夜来痢减十之五，痛减十之七，早间已啜粥半盏矣。太学喜而叩予曰：渠面赤唇红脉大，所下皆血，症皆属热，叔乃复投热剂，吾甚恐，一夜不能寐。乃今疾已减半，生有望焉。不卜今日用何剂？予曰：比昨剂差小耳。方仍昨也。太学曰：吾惑矣，何视热为寒耶？予曰：君知脉大为热，不知大而无力乃虚寒也。面赤唇红，由中寒而火不能下，阴盛格阳之症。设是真热腹痛，其人体仰而舒，寒则引而伏。所下血色带晦，均是假热，寒症明矣。前剂果再进而全瘳。太这复书报予曰：昨闻虚实真假之论，非饮上池水者不能道也。幸注之以诏后世。（一百九十）", "6512": "一妇年三十二，大发寒热。胸膈有痰，大便泄泻。以二陈汤加白术、桂枝、白芍药、柴胡、酒芩，一帖而止，后因怒，早晨又复发热，吐血一盏，口渴汗多，脉甚数。陈皮、知母、柴胡、杏仁、丹皮、酒芩、白术、人参、乌梅、青皮、槟榔，水煎服之。用此调理，数脉渐退，惟左脉尚弦。寒热已止，喉中痰声已定。后又因将息失宜，两胁疼，痰多，嗽不易出，脉较前不甚数。以栝蒌仁一钱半，贝母、白芥子各一钱，萝卜子、桃仁、滑石、牡丹皮、香附、山栀子各七分，青皮、赤芍药、甘草各四分，煎服。血绝不来，嗽热寝息而安。（一百九十一）", "6513": "族侄妇戴氏，两寸脉滑大，两尺沉微，心痛彻背，背痛彻心，甚则必探吐其食乃已。近来每一痛必七日，仅进白水，粒食不能进，进则吐而痛更加，七日后痛渐已。如此者，十七年所矣。始则一年两发，又一年六七发。今则一月一发。以积气丸治之，不终剂而断根。（一百九十五）", "6514": "老仆来兴咳嗽，胸胁背心胀痛，如刀刃所剚。发热口渴，诸治不瘳。脉浮而数。此风寒鼓激痰火上涌而然。以前胡、麻黄、紫苏子散风邪为臣，以栝蒌仁治痰火为君，橘红、半夏、旋覆花、杏仁为佐，枳壳、桔梗、甘草为使，两剂而平。（一百九十六）", "6515": "族侄孙媳程氏，双桂翁女也。年甫三旬，产曾五胎。今则经闭不行者八年。肌肉则丰肥于昔，饮食又倍加于昔，精采则艳美于昔。腹柔不坚，略无所谓病者，独经闭不行不生育耳。专科率用四物汤、玄胡索、牡丹皮，诸通调之剂计服千余帖矣。又如三棱、蓬术、干漆、桃仁、苏木之类，莫不概尝，罔有一应。访予为诊。六脉缓大有力。予曰：此脾湿生痰，脂满子宫，徒行血活血破血无益也。法宜调气消痰，燥湿溶脂，俾使清瘦，庶新饮食不复生痰，不助肥脂，复为经水，经不期行而自行矣。若彼专科者流，局局然养血活血破血，而欲望其经行，不亦难乎。盖前剂皆滋湿生痰之味，非有湿痰者所宜，而肥人尤不宜用也。乃为订一方，以平胃散加滑石、桃仁、黄连、姜黄、丹参、南星、半夏，作丸剂服之。半年而经行。次年生一子，后连生一子一女。（二百）", "6516": "熊成八官江右，南昌人也。早起行路，忽见邪火二团，滚滚而来，大惊骇。次日腹中膨懑，渐成胀满。面白皮薄，两手瘦削，两足皆有浮气，按之窅然不起。行动气促，形神俱弱。医谓神弱气促，面白肌瘦，胸腹青筋缕缕如贯索，小水清长，形症如此，脾虚所致。以参苓白术散投之，十日堵然如鼓。中有一块，巍巍突出，坚如铁石。脐已平满，勺粒不入。医者复诊，与渠决曰：若疾法在不治。盍早图归，毋作异乡鬼也。病者闻言泪簌簌下。熊东溪怜而恳予为诊。脉沉弦有力。诊竟语渠曰：审脉验症，非气虚中满候也。前补太骤，适有助长。顾今霉雨，途遥即归，恐未能时刻可到。即到又未必遇良手。治稍异，则大事去矣。予有一药，尚可冀生。东溪力为之请。以琥珀调中丸，日二进之，一进甚甘，再进称快，十日腹渐宽，块渐熔，半月块尽消去，青筋俱敛。改以平胃散加萝卜子、姜黄、苡仁、砂仁、木香，调养一月，饮食大加，帖然安寝，两足之浮亦并消释。（二百零一）", "6517": "从侄中叔太学，从暑月赴南雍，一日转班出，索茶饮，饮辄逆流左鼻出，茶入腹者十之三。当迓白下名家调理者尽其人。几一月，不惟饮茶不为然，食粥与饭亦多从鼻出。太学生平喜精洁，日与交游皆缙绅逢掖，遂以疾自惭，因告假图治。闻京口多名医，买舟访之。如何如张如团，无不谒治。然愈服药愈病，渐加恶心，头晕，肌肉削，四肢无力，心益惴惴。亟归就予治。予诊毕，因叩所见，诸名公认何症，投何剂？中叔曰：诸君皆谓此疾，板籍无载，治法无稽，徒揣度为胃火。谓诸逆上冲，皆属于火。故投剂非黄连解毒，即三黄、石膏、栀子、黄柏、知母、天花粉、葛根之属。侄亦以初到白下，苦酒，因酒动火，理或为然，听其治而不遑它计也。予曰：治病贵辨明经络，与经络之出纳虚实，明藏象，察经度，究竟夫病机病能，此扁鹊所以随俗为变也。何常拘拘守方书哉。《内经》有云：咽喉者，水谷之道路也。喉咙者，气之所以上下者也。颃颡者，分气之所泄也。人之鼻渊涕出不收者，颃颡不开也。子之症，亦颃颡不开之类耳。颃颡不开，故气上而不下。会厌弱而不能揜其气喉。夫鼻与气喉相通，惟不揜，故饮食逆从鼻窍而出。不见常人偶气逆，而饮食自喷嚏出乎，即其例也。且右脉缓弱无力，气虚明矣。《内经》云：形寒饮冷则伤肺。又曰：脾胃喜温而恶寒。又云：视听明而清凉，香臭辨而温暖。子多服寒凉，此所以恶心头晕肌消也。予但为温补，盖肺属金而主气，金气旺则收敛下降。气下降则饮食从气下矣。以六君子汤加辛夷、桑白皮、苡仁、沉香，一进而势缓，三进而止大半，七剂而全安。以此症旧无载，故笔之以俟后人采焉。（二百零二）", "6518": "程达庵四媳戴氏，产半月而腿疼。迎专科诊视，曰虚。投以八珍汤，服十日，疼益甚。予赴邑候之召，道经其庐。达庵趋问：产后半月而腿疼，何症也？予曰：两腿皆疼，独一疼也。达庵曰：右腿疼。予问疼处热否？曰：热。予谓切不可认虚认风。此产后败血凝滞血海，流于经络。不急治，则血无从出。久必化脓成毒，或为肠痈。今腿痛是其征也。达庵默然而别。复迎专科，又曰风也。但丹溪有云：产后须当大补气血，虽有它症，以末治之。投以十全大补汤，痛转剧，大发寒热。小腹红胯果红肿出脓，外科又为生肌收口太早，致腰俞复发一毒。肿痛寒热如初。十日后大溃脓而不收口。精神萎顿，肌肉陡削。饮食不进，恶心怯寒，奄奄一息尔。外科曰：不可为也。专科曰：余但治胎前产后，今为肿毒所坏。皆辞去而不下药。达庵始悔不听予言，以致误事。因急予。予往视，六脉濡大无力，疮口流清水而无脓。予曰：势棘矣，不暇治疾，速为保脾。盖五脏六腑，皆藉脾土以为养，然非大剂人参、附子不可。始以人参、白术各五钱，甘草、干姜、大附子各一钱，黄耆三钱，白芷、桂心各五分，以其能排脓止疼也。外科犹然阻曰：白术作脓，恐不可服。予曰：脓不死人。饮食不入口，则死人也。急进之，四帖而神气回，饮食进，诸症悉减，疮口成脓。予语之曰：生矣！改用参苓白术散，调理一月而安。达庵叩予曰：公何预知必为肿毒，当急治也？予曰：《内经》所谓脏象。又云：现症腿疼而热，症已现矣。生于产后，非败血所致而何。于时急为疏通，不留经络，何毒之有？专科不察而补，是益其毒而助之溃也。外科不审虚实强弱，概以毒治之。奈何不使患者几危哉。达庵曰：专科之不足恃也，如此夫。虽然，不如是，无以见公之高矣！（二百零三）", "6519": "学士徐检老，体丰厚，善饮，致有肠风，计下血不下数桶，因而委顿。己卯仲冬，右胁极疼痛，上至耳后，夜分尤甚，左右不能转动，转动则痛甚，饮食减，面色青，闭目汗出如雨，湿透衣被，故不敢合睫而睡。族医皆投以香附、青皮、及辛散之剂，痛愈甚，汗愈多，面愈青。逆予诊之。两寸短弱，左关弦而搏指，右关沉滑，六脉皆近七至。予曰：据痛在少阳经分野，始必动于怒，木火之性上而不下，故上冲耳后而皆痛也。夜痛甚者，盖夜属肝气用事。《内经》云：司疏泄者肝也。邪在肝胆，故阖目汗即大出，中焦原有湿痰，法当调肝清热解毒为主，兼利小便，不可遽止汗而使邪无出路。今脉太数，如遽敛汗，是逆其木火之性，不惟痛加，且将发肿毒而害非浅矣。《内经》云：膏粱之变，足生大疔。当预防之。公曰：何为敛剂而谓不宜？予曰：当归六黄汤内有地黄、当归、黄耆，皆滞痰闭气之味，桔梗亦非所宜。书曰：下虚者，及怒气上升者，皆不可用。故当慎也。因以柴胡、黄连为君，白芍、甘草、天花粉为臣，红花、连翘为佐，龙胆草为使，服后汗虽仍旧，痛即减三分之一，不妨睡矣。次日仍用前药，痛又减半，第三日又服，左右转动如常，饮食亦加。予未至，公已先迎姑苏盛氏，盛公幼时窗友也，家世受医。公初不急予，日引领期盛到，可刈枯铲朽也。盛至诊毕，遂诘曾用何剂，公出予发剂示盛，盛大叫称谬，谓当隆冬之候，汗多如此，阳气大泄，何敢以柴胡为君，喉中痰既未清，又何不用桔梗当归六黄汤？前贤已试之药置而不用，是舍纪律而务野战也。即取六黄汤加桔梗以进，公雅信盛，乃倾心以从，速煎服之，未逾时而旧病随作，色色加恶，左右复不能动，自戍而至子丑，苦不能支。有内侍语之曰：服孙君药虽未全可，亦已去泰去甚，彼曾言二药不可用，何为轻犯而受此苦？宜急取孙君药煎饮，饮下即伏枕鼾鼾，达旦始寤。命使速予至而叩予曰：人言隆冬汗出不当用柴胡，而公用为君，何旨？予曰：胆与肝为表里，肝胆之火郁而不发故痛，痛极而汗，汗出而痛减者，是火从汗出，盖汗乃邪出之门也。予故曰：汗不可敛。本草云：柴胡泻肝胆火，而以黄连佐之。《内经》云：木郁则达，火郁则发。言当顺其性而利导之。势则易克。古人治火之法，轻则正治，重则从其性而升之者。以此，盖医贵通变，如阴虚火动而汗出者，内无有余邪，故以六黄汤敛而降之，常治法也。今内有余邪未出，遽敛降之，邪无从出，势必成毒，故变常而从治者，使邪有出路，木火之性不逆，则毒不成而痛可减也。公曰：善哉。孙君之剂，奇正相生，不下孙武子兵法，何轻以无纪律议之，愿投剂而奏凯也。予曰：公数日后，疮疡大发，两胯且有兴块作痛，此毒出之征，公于时无恐。改用柴胡、白芍、甘草、丹参、苦参、茯苓、瞿麦、车前子、黄柏、金银花、连翘，服三日而痛全减，汗全收，左右不难转动矣。逾日，公谓肌肤甚痒，累累然似瘾疹，岂疮出与，欲以药浴之可乎？予曰：可。再三日，两胯果发兴块，如棋子大者数枚，且痛。予业已制蜡矾丸以待，至是授服之。疮果遍身大发，两腿为甚，一月余而瘳。公始信予防毒之言不谬。披愫交欢，且作序识胜，期与终身不替云。（一）", "6520": "吴仪制主政尚卿先生，柱史安节公公子也。弱冠时，病鼻塞不能喷者四年，且衄，寒月更甚，口渴，咽喉边有痰核，脉之右寸关洪滑。予曰：此肺经痰火症也。与前胡、秦艽、葛根、薄荷、石膏、天花粉、玄参、贝母、山栀子、甘草、白药子、桔梗、丹皮、四帖而衄止。夜与牛黄三清丸数粒噙之，鼻气即通利能嗅，噙未旬痊愈。先生初年绩学，心专志一，不知寒暑，致有塞衄疾。又万历己卯庚辰，郡邑试皆首选，如此者再，而皆不得籍名学宫，益郁然不适。予时把臂语之曰：先生何以一儒冠为汲汲。据脉，科甲当不在尊君下，即馆中二友亦金马客也。依愚见，史先登，公次之，吴又次之，日后当以斯言为左券，毋相忘。后三公先后登第，一如予言。万历戊戍春，余应吴宫詹召，公暨史玉老不爽前言，皆为予撰《玄珠》序，而纪其事，以见一时良遇云。（二）", "6521": "宜兴宋令君，山东人也，太夫人年五十余，病胸腋胀痛。予时寓吴宫詹家，而绳庵安节二公，皆宋公年友，因二公而逆予。诊太夫人脉，右寸关洪滑弹指，如黄豆大，左三部散乱无绪，如解索状，两尺绝无神气。予不得其受病之源，而宋公亦不以病源告，卒然问曰：脉为何症？予曰：据左脉为虚弱久病，右脉似又为饮食所伤，必病小愈而又伤，反复之疾也。其势亦危。宋公闻言危，乃拂其意，貌似不恭。予见其貌，即辞出，至后堂，有各佐贰及学博佘公在焉。佘公予乡人也。素亦知医。问曰：症候何如？予曰：不治。渠谓前诊者皆无难色，公何云然？予曰：两尺无神，如树无根，此《难经》所云也。左脉散乱，右脉如豆大弹指，不旬日当见，果后七日而卒。邑中乡先生士民相传，谓予能预决死生云。（三）", "6522": "宜兴令君胡镜阳公尊堂太夫人，年七十二，脾泄十五年不愈，近加吐红，咳嗽痰多，痰亦不易出，申酉时潮热，胸膈壅塞不能就枕，饮食大减，且恶风，终日坐幔中。诸医谓发热吐红，法当寒凉。脾泄多年，气虚老蓐，法当温补。二病矛盾，难于投剂。又谓身热脉大，血家所忌。益束手无能为计，皆辞去。且归咎于长桥上拆屋，致正堂不利。以是前丁宋二公接迹忧去，邑中汹汹，因延予治。诊得两手脉皆浮而洪数，亦皆带滑。予曰：据脉洪数为热，滑为痰，浮为风邪在表，以伤风故恶风。仲景曰：当汗不汗必作衄症。法当清解，可无恙也。公以诸医二病矛盾之说为问。予曰：此暗于先后者也。夫脾泄已久，未尝为害，新病势炽，宜当速去，所谓急则治标也。俟邪去之后，补脾未晚，且潮热为风邪所致之热，而非阴虚火动之热，血乃当汗不汗之血，亦非阴虚火动之血。《内经》云：夺血者无汗，夺汗者无血。当汗不汗，邪鼓血动。但得表解热退，血自止耳。公怃然曰：噫嘻！畴昔老母过钱塘，遇风涛受惊，因发热咳嗽，血出痰多，今以公言质之，诚由风邪起病也，愿以药进。予用紫苏子、前胡、麻黄、薄荷解表为君，枳壳、桔梗、桑白皮、栝蒌、紫菀、贝母消痰治嗽为臣，酒芩、甘草为佐，连服二帖，五更微汗而热退，胸膈不壅，嗽亦稍减，血止大半，始进粥。次日减麻黄，加白茯苓，夜服七制化痰丸，其夜痰嗽又减半，从是不恶风而去幔矣。前方再减枳壳，加薏苡仁，调理而安。（五）", "6523": "曹同府东岗先生，右胁痛。脉之左弦大，右滑大，此由外伤风内伤食所致也。又加咳嗽，夜更痛，体肥面青，寝食俱废。予以紫苏、柴胡解其表，白芥子、桂皮、香附治其胁痛，山楂、萝卜子消其食，杏仁、陈皮、半夏、栝蒌仁治其嗽，四帖，饮食进，嗽亦除，胁痛减十之七，再与保和丸服之而安。（六）", "6524": "宜兴令君镜阳先生，上焦有浮热，胃中有食积痰饮，平常好食热物，稍凉即腹痛泄泻，大便后间有红，又因劳心动火，头面生疮疖作疼，脉左数，右滑数。以玄参、石斛、白芍药各二钱，甘草一钱，天花粉、连翘、贝母各一钱，茯苓八分，薄荷五分，四帖，疮疖皆愈。再以保和丸加姜连、滑石、红曲、白术丸与服，半月全安。（七）", "6525": "吴鹉源先生，咳嗽口干，腹中如火滚动，不知饱饿，亦不思饮食，右胁痛，脉右滑数，左弦数，此中焦有痰积也。先以总管丸去其痰，而后养脾，服后大便下稠黏黄糜甚多，小水如血，此热下行也。继以保和丸理脾消余痰，又使新饮食不生痰也，外以橘红、贝母、天花粉、桔梗、酒芩、知母、葛根、甘草、滑石服之。其咳嗽亦除。（八）", "6526": "吴鹤洲先生太夫人，年八十六，素有痰火，大便一日三四行，一夜两起，肠鸣，脐腹膨胀，脉三四至一止，或七八至一止，诸医不知温补，妄以平胃散加黄连、山楂、白芍，一切苦寒之剂投之，克伐太过，因致腹疼。顾不咎其误，但谓年高而脉歇，至是为凶兆，辞去不治。逆予诊之。予曰：据脉书云：脉缓而止曰结，数而止曰促。今结脉非凶脉也，由寒湿之痰凝滞所致。法当温补下元，俾火得以生土，所谓虚则补其母者，当无恙矣。鹤洲公曰：寿算何如？予曰：两尺迢迢有神，专征也，即百年犹未艾。以补骨脂、白术各三钱为君，杜仲二钱为臣，白茯苓、泽泻、陈皮、甘草各一钱为佐，肉豆蔻、益智仁各五分为使，四帖，大便实，惟肠鸣未止。减肉豆蔻加炮姜五分而安。寿果至九十有八。（九）", "6527": "吴荆樵文学，恺悌君子也。左关尺脉甚弦，疝气半年，两胯结核硬痛，予以平疝丸消之，海藻、昆布、橘核各酒醋炒四两，玄胡索、山栀子仁、山楂核、小茴香、柴胡各一两，龙胆草酒炒五钱，醋打面糊为丸，梧桐子大，空心酒下三钱，服一月而消。（十二）", "6528": "吴鹤洲先生，中焦有痰，肺气不足，疟一日一发，热多寒少，口渴，小水不利，倦怠，头疼，脉左弦大，右寸短弱，关尺滑大。以石膏、知母、黄耆同柴苓汤煎服。服后腹作泻，前方去石膏、知母，邪热减大半，惟仅潮热而口渴甚，改以人参、葛根、知母、麦门冬、柴胡、陈皮、甘草、白术、鳖甲，五更服之而愈。（十三）", "6529": "吴雪舫先生，左胁下红块大如鸡子，傍有小蓓蕾作疼，左脉弦大而数，右滑大而数，盖由生平嗜煿炙，以致肝胆二经有热毒也。用大栝蒌一枚，白芍三钱，当归、甘草、贝母各一钱，连进三帖，疼减其半，胁下红成一小疖，以解毒早，故硬块潜消，大毒不成也。仍当为活血清热，再用白芍三钱，当归一钱半，金银花、甘草各一钱，大栝蒌一枚，连翘、山栀仁各八分，红花、柴胡各五分，四帖而愈。（十四）", "6530": "吴孝廉球泉先生，心血不足，胃中有痰，下元阳气不充，脉六部皆弱，惟右关滑。以远志、枸杞子各四两，巴戟、菟丝子、破故纸、山茱萸各二两，五味子、白茯神、人参各一两，炼蜜为丸，空心淡盐汤送下三钱，外以固阳锁真丹助之，龙齿、益智仁各一两，黄柏二两，辰砂、甘草、莲花心各五钱，芡实粉打糊为丸，梧桐子大，每夜灯芯汤送下一钱五分，极能固精。（十五）", "6531": "李思椿患胸膈胀痛，痰中有紫色瘀血，其原有酒积郁火也。脉两寸短，关滑，两手皆数，先与红六神丸服之，继以山栀、酒连、郁金、香附、橘红、茯苓、半夏曲、甘草、滑石、紫苏子，服后胸膈稍宽，仍以山栀仁、贝母、益元散各二两，牡丹皮、黄连、橘红各一两半，白茯苓一两，紫苏子、郁金、红曲各五钱，茜根三两，神曲打糊为丸，每早晚白汤送下二钱，调理而愈。（十六）", "6532": "吴双泉公，两尺脉洪大，两关滑，两尺沉微，此阳亢阴微之候，上盛而下虚也。上盛者，痰与火，下虚者，肾经真阴不足也。法当清上补下，上清则头目清利，耳鸣眩晕之症可除，下实则腰膝不酸，筋骨强健。清上用清中丸，贝母、橘红、枳实、海石、山楂、茯苓、白芥子、黄连、黄芩、滑石、青黛、神曲为丸，食后茶送下二钱。补下则用既济丹，辰砂、磁石各一两，熟生地四两，黄柏、知母、菟丝子、柏子仁各二两，牛膝、枸杞子、白茯苓各一两半，炼蜜为丸，梧桐子大，空心淡盐汤送下八九十丸。（十七）", "6533": "李寅斋先生，患血淋，几二年不愈，每发十余日，小水艰涩难出，窍痛不可言，将发必先面热牙疼，后则血淋。前数日饮汤水欲温和，再二日欲热，又二日非冷如冰者不可，燥渴之甚，令速汲井水连饮二三碗，犹以为未足。未发时，大便燥结，四五日一行，发则泻而不实。脉左寸短弱，关弦大，右寸下半指与关皆滑大，两尺俱洪大，据此，中焦有痰，肝经有瘀血也。向服滋阴降火及淡渗利窍之剂皆无效，且年六十有三，病已久，血去多，何可不兼补，治当去瘀生新，提清降浊，用四物汤加杜牛膝补新血，滑石、桃仁消其瘀血，枳实、贝母以化痰，山栀仁以降火，柴胡升提清气，二十帖而诸症渐减。再以滑石、黄柏、知母各一两，琥珀、小茴香、桂心各一钱半，玄明粉三钱，海金沙、没药各五钱，茅根汁熬膏为丸，每服一钱，空心及晚，茅根汤送下而愈。（十八）", "6534": "徐熙宇文学内眷，常患前后心痛，每痛必面赤手心热，耳鸣眩晕，即饮白汤，亦停膈间不下，且作酸哕逆，吐出皆酸水，五七日方止。四肢酸软无力，气逆上嗳，乃其常也。两手脉皆沉数，左弦，此上焦有痰饮故也。先以二陈汤加瓦楞子、滑石、吴茱萸、姜连、前胡、枳壳、竹茹、香附、大腹皮服，后以橘红、半夏、滑石各二两为臣，白螺狮壳煅过四两为君，茯苓、姜连各一两半为佐，旋覆花一两，吴茱萸三钱为使，面糊为丸，每服三钱，调理而愈。（十九）", "6535": "吴仰玄先生，患胃脘痛，痛则彻于背，以手重按之少止，痛时冷汗如雨，脉涩，此气虚而痛也。以小建中汤加御米壳服之而愈。（二十一）", "6536": "秔芝岗文学，酒后近内，每行三峰采战、对景忘情之法，致成血淋。自仲夏至岁杪未愈，便下或红或紫，中有块如筋膜状，或如苏木汁色，间有小黑子，三五日一发，或劳心，或劳力，或久立、坐亦发，访医问道，百治不效。以吴中书汉源公交善，逆予治之。观其色白而青，肌肉削甚，诊其脉，左寸沉弱，关尺弦细，右寸略滑。据此必肺经有浊痰，肝经有瘀血，总由酒后竭力纵欲，淫火交煽，精离故道，不识澄心调气摄精归源之法，以致凝滞经络，流于溺道，故新血行至，被阻塞而成淋浊也。三五日一至者，科盈满溢故耳。先与丹参加茅根浓煎服，小便解后，以瓦器盛之，少顷即成金色黄砂。乃用肾气丸加琥珀、海金沙、黄柏，以杜牛膝连叶捣汁熬膏为丸调理，外以川芎三钱，当归七钱，杜牛膝草根煎服。临发时，用滑石、甘草梢、桃仁、海金沙、麝香为末，以韭菜汁、藕汁调服，去其凝精败血，则新血始得归源，而病根可除矣。三月痊愈。（二十二）", "6537": "吴中翰汉源先生，肠风下血，腹中微痛，脉左寸短，右关滑，两尺弦大。以地榆、槐花、枳壳各三钱，荆芥穗、秦艽、青蒿、葛根各一钱半，黄连二钱，两剂而愈。（二十三）", "6538": "大柱史吴安节公，脾肺二经有痰火，中焦有湿热，流于膀胱为淋浊，溲之前作痛，小便了而不了，脉左寸短弱，关弦大，右寸关滑，两尺洪大，六部皆数。法当先清上中二焦痰火，然后提清降浊，庶日后筋骨无疼痛之患。先与萆薢分清饮加山栀、黄柏、滑石服之，淋浊减半，改以二陈汤加山栀、黄柏、滑石、螺狮壳、木通，以去湿热，而消中焦之痰，再加柴胡、升麻、桔梗以提清气，四帖而愈。（二十四）", "6539": "吴宫詹少溪翁，原有酒积，且频伤于怒，致右胁之火冲上作疼，耳鸣眩晕，大便艰涩，脉右寸关滑数，左弦数，以当归龙荟丸加牛胆南星，治之而愈。（二十五）", "6540": "吴孝廉球泉公内人，痢疾后感寒，又月水适至，大发热口渴，遍身疼，胸膈饱闷烦躁，头微疼，耳亦聋，大便泻，舌上白苔，脉七八至，乱而无序。此三阳合病春温症也。时师误以为漏底伤寒不治。予曰：病已危，医而不起者有矣，未有不医而起者也，且投三阳药服之，挑察征应，再相时而动。以柴胡三钱，葛根、白芍药各二钱，枳实、桔梗、酒芩、竹茹各一钱，天花粉八分，炙甘草、桂枝各五分，服后但觉遍身冷如冰，面与四肢尤甚，六脉俱无。举家及医者皆叹为物故矣。予独曰：非死候也，盖夜半阴极阳生，势欲作汗，譬之天将雨而六合皆阴。球泉疑信相半，而诸医闻之皆笑去，四鼓后果战而汗出，衣被皆湿，四肢体面渐温，神思清爽，且索粥，举家欣欣，以为再生。次日惟耳尚聋，腹中大响，脉近六至，改以柴苓汤加乌梅，两帖而愈。（二十六）", "6541": "万肃庵先生令郎，发热十一日，口渴，舌心色若沉香，且甚干燥，额上热极，两胁亦热，耳微聋，曾未有汗，亦已下二次，热不少除，小水绝少，神昏足冷，饮食不思。市医技窍，乃告急于予。予诊之，左脉中按数而有力，右脉软弱，据症为阳明少阳并病也。当以柴葛汤清其热，看汗有无，再当机而处。柴胡五钱，葛根三钱，白芍药、石膏各二钱，人参、升麻、天花粉各一钱，粉草七分，水煎服之。次早诊数脉稍缓，热稍退，舌齿仍干，小水不利，神思尚昏沉。改用柴胡、粉草、天花粉、黄芩、人参、白术、茯苓、滑石、木通、泽泻。下午又觉微热，面赤，额上痛且重，即以益元散三钱服之，大便行一次，溏而色黄，热仍甚，面仍赤，服前药后，小水去二次。再诊之，寸关脉将和，两尺尚洪大，乃知邪热在下焦，惟利之而已。再与辰砂益元散五钱，口渴稍止，齿下盘虽润，上盘仍燥，神思昏沉，睡而不醒，睛彩不与人相当。又知热在心包络也。宜用陶节庵导赤散，二帖而神清，惟小水尚欠利，以四苓散加酒连、麦芽、木通煎服，再二帖而诸症悉退，饮食且进矣。（三十）", "6542": "大宗伯万履庵老先生夫人，右胁下疼，咳嗽喉干，间亦吐红，或一碗，或半碗，肠鸣泄泻，年六十外，原因头风坏目，性急躁，左脉弦数，右滑数，以栝蒌仁二钱，黄连、前胡、桔梗、枳壳、橘红、贝母、白茯苓各八分，甘草五分服之。次日红仍不止，惟胁疼减半，改用山栀仁、牡丹皮、香附、贝母、甘草、栝蒌、紫菀、滑石，水煎服。方欲觅真郁金，苦不能得，唐凝庵老先生，乃夫人婿也，偶至闻之，应声曰：有。取磨三分，用煎药饮之，两帖而红止痛瘳。（三十一）", "6543": "白仰云先生令眷，每触怒即晕厥，必闭门合目静坐，不留一人在房，手足皆冷，汗出如雨，气息俱微，越一时许，苏如常。原以颈生瘰疬，多服女医草头药，及专科用斑蝥等毒，因而脾胃损，元气亏也。年三十八，曾未生育，每日令二婢不住手敲两腿，俟其熟睡乃已。不然则睡不安，晚至二更后始睡，夜半心多惊跳不止，指甲皆无血色，经将行，小腹先疼二日，色紫有块，诸病虽如是，而肌肉饮食却如无事人，百治不效。慕予而请诊之。两寸短弱，左关大而有力，右关滑，左尺滑，右尺沉微，据脉肺气虚，肝木实，胃中有痰之症也。用六君子汤加丹参、酒连、青皮，外与珠母丸及独活汤二方，调理而安。（二方出《医学纲目》）（三＋二）", "6544": "吴文学霁阳先生，笃志士也。以积学劳心，又有星士以己卯决科许者，其星士前许历历有验，至期疟发不能终场，遂心忧而成癫狂，日间或悲或歌，或鼓掌，或顿足，甚则骂詈不避亲疏贵贱。乃叔邀予视之，面白而青，脉两寸短弱，关弦，右关滑，两尺平。予谓两寸脉既短弱，此心肺之神不足，志愿高，而不遂其欲，郁结不舒，津液生痰而不生血，又攻痰克伐太过，心神愈不得养，故昏乱而无所摄持。《内经》云：主不明，则十二官危。按此，则治宜补养，收敛心神，而兼之清痰，可万全也。用酸枣仁、人参、茯神、小草、丹参、当归以补心安神，黄连、竹茹以清肝胆之火，玄参佐之。外以龙齿、珍珠、羚羊角、牛黄、胆星、天麻、青黛、辰砂、全蝎、冰片、黄连、甘草膏为丸，金箔为衣，调理而愈。（三十四）", "6545": "太史徐检老，向为𤻊疝所苦，而妨生育。辛巳孟秋，有江右陈岭泉者，以是症为专科，寓芜锡，翁延而治，谓将烂药煮竹片夹阴囊，俾阴囊烂见子，又以烂药点开肾子，使其中蓄积臭水溃出，然后用生肌药长肉收功。翁以此治与道中诸友商之，无有动者，而谋于予。予曰：翁疾非常疾，则治当非常治也，陈能为翁治于外，予当佐陈补于内，内外兼治，必可成功。翁因予言而决用陈，是时予有湖州之役，而陈用其术治一月，囊烂子开，洞见水泡，第不能使泡破水出也。由是胸中气满，汗出如流，终夜不寐，饮食减三分之二，面青，肌肉瘦其半，形气弱而大便艰涩，腰肾俱痛，苦不可殚述。将令人急予。予适自湖州至荆溪，主吴少溪公家，翁时杜门谢客，闻予至，大喜而促予，诊脉两寸软弱，右尺大，右关滑。予诊毕曰：向许佐陈治内，今其时也，比陈技已竭，而水不得出，翁又难于痛，业已用收口药矣。予曰：无伤，痛由元气虚惫，而汗亦因痛来，汗去多则心血不足，心血不足则神失养，故不寐，脾胃为痛所伤，故饮食减，今只大补血气，不惟痛止疾除，即水泡亦可出也。陈谓用补收口生肌，或可使泡出水，或未必然。予曰：三日后，当自见。翁曰：补甚善，奈生平不能服参何？予曰：翁体非昔比也，脉症皆可服，又何忧，乃用人参、黄耆各三钱，当归、白芍、石斛各一钱五分，陈皮、贝母、红花、粉草各八分，饮下即睡。次早汗敛，且索粥，胸膈顿宽，连服二日，痛减大半，饮食顿加，精神亦爽。乃陈恐予夺功，私谮之曰：孙君之药虽善，但非外科所急，服之恐生肌收口后，而水终不得出也。翁谓必如何而后可？陈曰：当于前药加羌活、防风、白芷、远志，减去石斛，则外内两得矣。翁然其说，且服其药，饮未半而痛立至，汗立出，头热如火，气逆上升，夜竟不寐，种种病复矣。亟索予剂，予知陈之忌而行谮也。乃宣言曰：予实佐尔成功耳，尔何自败。尔知翁之痛乎，元气虚而毒药凝滞，故补而助之，活动其血，则毒药自行，药行则泡可溃，水方可出，翁之谢尔已有成议。予雅善翁，来者为义，非为利也，鄙见与寻常较不牟矣。陈闻言而语塞，亦以投剂无功，遂乘机而听予治。仍用前方，加酸枣仁、枸杞子、皂角刺各一钱，两帖而泡溃，出臭水五六碗，囊随消瘪。陈拊掌曰：今而后知用补之神，其老先生之福也。太史受补自此始。（三十六）", "6546": "丁酉冬，宫詹少溪吴公，年七十二，以长君秋闱之捷，应酬贺者过劳饮，又伤于犬肉，市医概用消导之剂投之，漠如也，反加内热。常州张氏，荆溪缙绅大家恃为锁钥者，至则谓公高年过劳，消剂峻而致内热，用补可愈也。因投人参，则右胁胀痛，尽夜难支，张又谓补法不差，惟少行气之味，故无功耳。于前药加木香、砂仁，辛热止痛之剂，益呕吐不止，胀痛转剧，而大便燥结，张不自咎不认病而误投，乃遍语缙绅相知曰：吴少翁老年膈食，非其所宜。丹溪复生，无能为也。少翁闻予在苕，而急予治，予兼程而往，至则腊之念一日也。诊其脉，左弦右滑，两手皆数，且搏指，谛视其色，神藏气固，惟肌肉略瘦，手心甚热，予曰：此内伤症，非膈食症也。公曰：诸君言吐而大便燥结，食不得下，非膈而何？予曰：否，公原不热不痛又不吐，由误饮药而使然耳。书云：通则不痛，痛则不通。大便既燥而用补，非也。经曰：食不得入，是有火也。尤用辛热，非之非也，以是而治，譬之以油救火，益令其炽耳。予见与诸医不侔也，即与琥珀调中丸一帖，其夜胁痛稍缓，次早诊之，脉仍如前，予决谓非通不可，即以龙荟丸与调中丸兼服之，五日内下黑粪十五六次，诸症悉减，饮食大进，改以保和丸，调中丸调理。念七日，公即能巾栉，元旦命庖人治酒，榜人舣舟拉予泛于南门，持觞为予寿曰：与兄别者十六年，不惮劳涉险而赴吾急，自今以后之齿，皆兄之赐也，敢不铭心，为欢竟日，至谷日，予乃别而复之茗。（三十七）", "6547": "别驾吴勉斋翁，体丰腴，嗜炮炙，任性纵欲，年六十七，极躁急。一日跌伤其齿，恬不为意，阅三日，复跌，亦不为意，复跌之次日晚，左手足忽不能动，口眼歪邪。陆怀南先生，公通家友也，即往诊之，语公诸郎曰：此中风也，治不可缓，急取牛黄丸进之，诸郎皆有名博士弟子，延予为治。诊其脉，左洪大，右缓大，观其色苍黑，神昏鼾呼，呼长而吸短，呼至口气𠷺𠷺出不能回，终日偃卧如醉，人不能动。陆曰：此非半身不遂乎？予曰：症候甚恶，不特半身不遂也，半身不遂者，中风已过之疾，其势仍缓，亦有十余年无恙者，今才病，势便若此，乃中风之渐，方来且不可测。陆重厚长者，所诣亦精，闻予言，当下了然，即与予商榷用药，始以六君子汤加全蝎、僵蚕、天麻与之两日，神气仍未清，犹昏睡，睡犹呼吸，口边𠷺𠷺然，间作吐，粒米尚不进，前药再加竹茹。又两日，神始苏，欲言而舌难掉，嗫嗫不能出诸口，前药又加石菖蒲、远志、红花，始能进粥数口，日计亦可茶瓯许。夜与正舌散，同前药饮之。又三日，能坐，粥亦颇加，惟言尚蹇涩，欲言以笔代口，写我左手甚痛，大小便艰少。又用四君子汤加陈皮、竹茹、当归、芍药、红花、钩藤、天麻，服三日，神思大好，饮食日加，以是方调理弥月，手痛减，稍能动，足稍能伸，扶起能坐，且能自按谱铺牌，语言十分清至八九，骎骎万全之望，惟大便有七八日或十余日始一行。予曰：此血少之故，补养久当自全，幸无他用而速害。公常自言吾疾乃痰在膈间，何能得一吐为快，此医家有授之言也。予曰：公脉大虚，非余痰为害，况今以补养而渐安，此其明验，何敢轻试一吐，愿宁耐静俟，毋涉险为也。此戊戌九月念五，予以是日别往苕城，别不及旬，公复倾心而任张甲，张大言曰：公病可吐，早吐早愈，诸郎君始信予言，持议不可，彼曰：公病痰也，不可不吐，吐而后补，可全愈而无后患，不然必成痼疾。公欲速效，决意吐之。诸郎君不能阻，一吐而烦躁，犹曰吐不快耳，须大吐始可，再吐而神昏气促，汗出如雨，立时就殂，可叹可叹！（三十八）", "6548": "少冢宰徐检老，以万历丁酉三月初旬，往贺长兴臧老夫人眉寿而发寒热，臀近肛硬处生一毒，红肿而痛，坐卧为艰，因归荆溪访治外科，即以镵针点开，插药线于内，涂以烂药，使脓口急溃，又于疮口上以生肌药敷之，使易收口。可受谢而去，未半月，其傍之硬处，又红肿痛，寒热交作，儿于成脓，以前医有功，遂复延之，至则又以向者之法治之，受谢而去。递医递患，递针而递插药，计其患者凡八遍，计其医之更者，如张，如鲁，如冯，凡八人，有陈外科者，则总其中而受谢独多，其时则丁酉三月至戊戌八月，几年半矣。于时，予赴吴少溪翁召，因知翁在蓐，亟往谒于卧榻间，翁见予至，悲喜交集，备陈其历病之由，针刀之苦，伏枕岁月之深，辄为痛心，予闻之亦为鼻酸。谛观其色则青惨，诊其脉皆濡弱，把其手足，则冷如冰，问其饮食，减平日之六，究其所服之药，则槐角、黄柏、生地，凉血解毒之类。予骇然而语翁曰：此痔痈非痔漏也。痔漏当用挂线，以五灰膏点之可愈。今肿硬无定处，离肛门且远，况其初原无硬块，硬块由插药凝滞中来。谚云：剜肉做疮者非耶？假令非翁禀气厚，胃气壮，安能六十以外之年，而当此剥削哉！初只可大补气血，即有毒，只宜托出一脓而愈，未成者，使活动消散，不复生毒，此王道之治，不胜于针刀万万？诸君之治，如避影者，不知息阴而急趋以求避，则影益速，而气促敝矣，自迨之道也。翁初不逆予者，以非外科，到听予之论，幡然有悟，又见《玄珠》集有外科二卷，益信予之善外科，而听予治。予即以十全大补汤进之，四帖而饮食加，手足暖，大便艰涩百方润而不能行者，今亦通利，而肛门如不知也。诸外科犹哓哓议补非是，予极言排之，翁惟予为听，予以何首乌四两，人参、枸杞子、黄耆、当归、熟地各二两，槐角、秦艽各一两，蜜丸服之。不终剂，其肿处少出脓而全瘳，傍亦不生硬块。益信向之硬块为插药之毒所致也。翁喜为谑曰：予病非孙君，诸外科视我疾为金穴，其取宁有已耶。呵呵！（三十九）", "6549": "宫詹吴少翁，患痢，赤白兼下，里急后重，市医治半月，后重不除，饮食渐减，最苦者，下午发热呕吐，乃遣使往苕招予，予闻状心怖，即涉险而过太湖，一昼夜而至荆溪，翁卧榻已二十日，观其色，唇红面瘁，听其声，微弱不扬，但一两语，气即不接续，下午潮热，至丑方退，形神俱弱，诊其脉，两手俱大而无力，右关略滑。予曰：据此乃虚虚实实之候，不足中之有余也。治当补养，兼清兼消，缓以治之，庶可无恙。公深然之。以四君子汤加白芍药、黄连、山楂、滑石、陈皮、柴胡，两帖而潮热除，呕吐止。去柴胡，因口渴不止，加葛根，六剂而饮食渐进，血亦止，惟白脓不除。改用人参、白术各二钱，白茯苓、白芍药、当归、神曲各一钱，酒连、陈皮、泽泻各七分，滑石、山楂各一钱半，外以丸剂消息盈虚，调养半月，则神气回而饮食大进，肌肉渐生矣。少冢宰检翁问曰：诸医先谓老年痢非所宜，又呕吐饮食不进者，谓之噤口，且身热脉大为痢所忌，公不旬日而收功，盖诸医称书之忌皆幻妄哉？予曰：诸君所言，皆至言也，第非因时制宜耳。愚见以脾胃乃五脏六腑之仓廪，故曰纳谷者昌，又曰人身之内，谷气为宝。予姑舍痢不治，而先开胃口，俾进饮食，使新糟粕将宿秽压下，若见粪，则后重除而痢易愈也。然又相其机宜，若食入而腹胀作痛，又量势略与疏通，通后或气虚下坠，又因势而略与升提，大抵以理脾开胃进饮食为先，此亦远交近攻之策，日虽多，功可万全矣。斯仆一得之愚，屡试而屡验也者。设不先开胃口，不审老弱，不揣缓急，一概治痢，虽有得未必无失，岂能算哉！公曰：善。（四十）", "6550": "臧少庚年五十，每饮食，胸膈不顺利，觉喉管中梗梗，宛转难下，大便燥结，内热，肌肉渐瘦，医与五香连翘汤、五膈丁香散诸治膈之剂，尝试之不效。时予方有事于先冢，久未远出，臧则不远千里而就予治。观其色苍黑，目中神炯炯不眊，惟气促骨立，予知其有心机人也。其脉左弦大，右滑大。予谓之曰：据脉，乃谋而不决，气郁成火，脾志不舒，致成痰涎，因而血少便燥，内热肌消。张鸡峰有言：膈乃神思间病。即是推之，子当减想虑，断色欲，薄滋味，绝妄想，俾神思清净，然后服药有功，不然，世无大丹，而草根木石何足恃哉！子既远来，予敢不以肝膈相照，兹酌一方颇妥，归即制服，但毋轻示人，恐见未精者，妄为加减，乃败事矣。慎之，慎之！臧曰：谨如教。其方用桂府滑石六两，炙甘草一两，真北白芥子、萝卜子、射干、连翘子各一两半，辰砂五钱，以竹茹四两煎汤，打馒头糊为丸，绿豆大，每食后及夜，用灯芯汤送下一钱半，一日三服，终剂而病如失。（四十一）", "6551": "（案1）右半身不遂，脉来虚软，元气不足也。法宜温补。", "6552": "（案3）症属偏枯，内热脉数。", "6553": "（案6）右肢偏废，六脉模糊，乃阳气虚而湿痰内滞。拟燥土涤痰，佐以活络法。", "6554": "（案7）肢麻言蹇，脉来无力，此阳气亏而痰滞脉络也，殊非小恙。", "6555": "（案10）沈，左。人之所以能运动者，先天之真阳也。阳之清者为魂，灵机出焉。阳生阴，脾阳根命火，心营君火，所生火，下交肾出。阳衰则大弱，阴无从生，心脾失养，舌胖少液，艰于语言，灵机时窒。脉和，两尺濡细。拟方专主温补。", "6556": "（案11）徐，左。脾开窍于舌，又舌为心之苗。病后液亏，心脾失于滋养，舌大而蹇，脉浮弦略数。拟用温养。", "6557": "（案12）心脾气液两亏，舌根蹇涩，脉形濡涩。专主培补，参豁痰利窍。", "6558": "（案13）徐。舌根于心，而其运动之机在脾。气液两亏，心脾失调，舌本蹇涩，语音不清，症本于虚，阻之者疫气也。目系在心，而为肝窍，目不能转，亦属于虚，脉濡而涩，并不弦急。专主培补，当审其机，更须节劳调养。", "6559": "（案14）张，左。肝肾阴亏，筋脉失养，寒从下袭，由足指及两踝痛，发战连次。此由禀体素弱，精血不足，当用温养。脉弦而长。拟方常服：", "6560": "（案15）胡，右。脾主四末，肝主筋，营液内亏，风寒乘虚袭人，右偏肢节酸楚，脉濡左略弦。此症以胃气为主，阳明为百络之长，谷食少则生血无多，运药亦不甚得力，惟当长夏已和，较易见效。拟方甘平柔润，养胃和肝，冀其渐复。不用味苦气劣之品，恐碍胃气也。", "6561": "（案16）秦，左。燥烦过度，营液内亏，心肝失养，加之素体脾虚，痰酒中积，起患偏中。右偏手足不仁，现虽渐次平复，而脉络牵掣，艰于举动，右脉尚和，左寸关略见弦动，面赤唇红。虽气血并亏，究系血虚失养，浮火上炎。凡经络之药多温，积气成热。此症凉则滞络，热则燥津。惟以平剂滋养，久服得效。", "6562": "（案17）脉左数右弦缓有年。形盛气衰，冬春之交，真气不相继续，内风日炽，左肢麻木不仁，舌歪言蹇，此属中络。", "6563": "（案19）舌为心之苗，又脾开窍于舌，心脾液亏，内失滋养，舌强语涩，脉来濡细。滋补脾阴，兼舒心系。", "6564": "（案20）舌强音不清，心脾液亏，脉来濡细。专主滋补。", "6565": "（案2）肝藏血，用心过度，心不能生，肝之所藏亦耗，木不滋则邪亢，亢必侮土，胃气本虚，脘次作痛，连及两胁，肝之络也。木郁达之，木枯宜培养。脉右濡而调，左大不弦。拟方以剂进，参以温煦，从春令也。", "6566": "（案3）盛，右。心藏神，肝藏魂，心不生血，肝木失养，魂不得安，木郁不达，必致侮土，脾中虚，土弱则木益不荣，气升不降，君火被扰，神灵无主，阴盛而阳无所附，时觉虚烦，近乎痫厥。血为心所生，必得离火之化。按脉左弦大而虚，右濡涩不调，统观大象，营气并亏，中无实火，拟甘温之剂。补气调营，兼理奇脉。心为离，君火衰则无主；肝为震，木亢则厥。药必温补，不可用苦寒重镇之品。", "6567": "复：肝胆震巽，同属于木，木郁不达，四火动心。心，阴火也。木火引动君火，营液内耗，木失滋养，中空无主，烦扰不安，肝藏魂，血少则夜不得眠。魂，阳气之最灵者也。胆主决，营虚则怯，症纯属于虚。虚者可补，而其关于七情者，则非药力之所及。右脉紧细而弦，右关浮大，寸略濡。拟方以叶剂静摄。", "6568": "复：大象与前相同，而气候则升，天寒气燥，时当敛藏，脉左大而时见虚弦，右浮大而濡，并无数象亦劲急。心主血而藏神，思虑生于脾，肝藏魂而胆主决，脾阳中虚，气不帅血，血失无次，内失滋养，神魂不安，心无主而事不能决，与痫症异，与怔忡亦异。总之，气旺则神有所归，气能生血，则肝脾调而行止有序。仍拟补，参用温疏。", "6569": "（案4）肝脾不调，正弱则本邪时亢。近感外风，兼挟积酒，留滞于太阳、少阳二经，蒸郁不达，日晡发热，脘次不舒，时或胀闷。右脉见涩。未宜进补，姑拟疏泄。", "6570": "（案6）右。肝风挟痰，上冲包络，气滞则厥，先笑而后肢节牵动，脉来弦细。包络与肝同为厥阴，故厥；近心，故笑。拟用开法。", "6571": "（案8）左。太阳感风兼挟寒湿，始因颈项不便，流入左臂，渐觉酸楚。加以敷治臂，臂松又发头风。肝阳未旺，外风引动内风，留滞于络。风为阳属，无定处也。脉涩，素体气虚，多痰，现患尚轻。宜拟宣理。", "6572": "（案10）头风频发，太阳少阳兼症，营液素亏，脉来弦细。难许脱根。治风先治血，肝脾兼理。", "6573": "（案13）营虚风动，跷脉为病，足挛，难于行走，脉来促数，急切难愈。", "6574": "（案14）肝脾不调，脘次作胀，气阻于络，络血外溢，头风时发，脉来细涩。当用宣理。", "6575": "（案17）土不培木，虚风上升，脉来弦大。当用调补。", "6576": "（案19）膈胀呕恶，饮食顿减，肝风患胃也。诊脉象弦大。暂拟苦泄法。", "6577": "（案21）头晕心悸，六脉不静，虚风内动也。须安养调摄。", "6578": "（案22）头晕多痰，脉来滑大，由肝风内扇所致。理柔肝熄风。", "6579": "（案1）失血后气喘咳逆，脉来细数。水亏火动也，恐久延成怯。", "6580": "（案4）积劳，内伤咳血，延至气喘，脉来软弱，阴损及阳也。防其虚脱。", "6581": "（案5）咳血便溏，六脉无力，怯之渐也。当用补土生金法。", "6582": "（案7）失血后咳呛便溏，六脉少力。不但阴络有伤，而阳气亦不足也。宜扶阳以生阴。", "6583": "（案8）遗精咳血，络脉空虚，腰背作痛，神色㿠白，怯症之根也。当以甘温补剂。", "6584": "（案9）失血后，咳逆自汗，脉数无力。乃阴液内亏，阳气无依也。姑以潜阳摄阴以幸功。", "6585": "（案14）失血后咳逆不休，间有寒热，诊六脉数虚。此由阴损及阳也，症已延入怯门，草木焉能振顿？", "6586": "（案16）彭，左。相火分寄于肝、肾，在肾者，坎中之阳；其在肝者，雷火也。水亏不足以制火，从上升，烁金则咳，伤及阴络则动血。火愈旺，水愈耗矣。脉浮数，时觉虚弦，重切则无力。是不特阴亏，真阴亦弱矣。益气则助火，滋阴又恐滑脾，当於潜阳育阴之中使之，两不相悖，更得静养，方冀渐愈。木令后，继以火令，总须加意调摄。", "6587": "彭。又，火邪可清，真火宜养，阴精藉阳气以生，畸于阳则助火，畸于阴则秋冬不能生物。寒润之品，必致伤脾。按脉大而不和，虽无促数之象，而不能敛摄，肾之下虚可见矣。虚则火升，烁金则咳，现当炎令，惟静可以存阴，拟方：以体阴用阴之剂，填补真元。庶乎有济。", "6588": "（案17）气虚不任补，所谓「热之不热，是无火也」，当责其阳，补火乃能生土。脉虚无力。后恐见喘急之象，急宜温补。", "6589": "（案18）命火下衰，气不生阴，脾肾并虚，精液亦耗，精依于气，气依于神，虚则两无所附，左脉见涩，右濡弱无力，而尺为甚。现交肃令，阳气渐藏，恐难藉草木之灵潜资化育也。", "6590": "（案19）钱，左。内中之候，无脾痰壅冲，亦与肝风牵扰，此属肾脱，景岳所诏，非风也。现瘥轻减，肾命亦虚，气与阴未能骤复，时有不相筦挕之势。脉迁变不常，随气之升降为衰旺。然尺脉总小，或大或濡，右大于左，有虚无实。拟以体阴用阳之品，滋纳下焦，肾与脾本自为关键也。", "6591": "（案21）左。始由风寒袭络，肩背入掣痛。近散入于络，全归厥阴之部。由两胁连及于背，咳呛则痛，痰中带红，此属木火。脉数，左略弦。养血则恐其腻，温燥助火。姑拟轻剂宣泄。", "6592": "（案22）劳乏伤阴，烦火内动，络热瘀积，咳呛狂溢，吐痰渐腥。血由阳明火动烁肺，金令不肃，阴亏愈无以制火，脉形见芤，夏令防其加剧，静养为要。", "6593": "（案23）劳倦内伤，气陷阴中，腰膝酸楚，兼之便浊，脉来浮大。当用滋补。", "6594": "（案24）脾不统血，失血之后，神倦色黄，渐觉肌削，脉濡涩不调。现当夏令，炎暑郁蒸，恐其加剧。益气为主，补气乃能生阴。", "6595": "（案25）心虚则生血之源不旺，肝脾液亏，木火烁金，咳呛有痰，络伤失血，见症在肺胃，实则心肝二脏受病，最称神倦色粹。脉濡不数，正气亦亏，内无实火，拟柔剂滋养。", "6596": "（案26）沈，左，复。肺主上气，脾主中气，甘，丹田命火属右肾，为气之根，所谓元海也。脾为坤土，肾为坎水，右肾，水中之火，非土不能克水，非火不生土，火即阳也，亦即气也。气所不至即肿。太阳膀胱，阳水也。气不化，则水道不行，甚则茎肿，日晡神倦，阳陷于阴也；举动气喘，肾不纳也；至寅丑时而喘甚，阴甚阳不能达人也；大便溏泄，脾虚则传化失宜，肾虚则关门不固；脉濡细，气升，即泻下焦也。总皆火衰。拟用温补。", "6597": "（案2）金不生水，津液二亏，三消之症已具，脉大而濡。专拟滋补。", "6598": "（案2）风温伤肺化热，气逆咳呛，痰多色黄，脉来右寸浮大。暂用泻白散。", "6599": "（案3）血溢后咳呛不止，咽痛失音，诊六脉弦数。此肝络伤而津不上承也，殊非浅恙。", "6600": "（案4）久咳不已，畏风，脉数。乃腠理疏而精液亏也。固养育阴兼治。", "6601": "（案6）华，右。脾胃气虚，素有痰湿，中虚则表阳亦弱，畏风多汗，冬肺感外邪，起患咳呛，淹久不止，心跳目眩，纳减嘈杂，夜不安寐，土不生金则肺虚，金不生水，肾阴亦弱，气不下摄，脉右濡。拟培土生金，金水相管摄，则气降而呛自止，不专治肺。", "6602": "（案7）肺感风寒，卫不能与营和，渐寒忽热，咳呛有痰，左胁连肋掣痛，气分不舒，纳减便结，舌中腻黄边红而碎，天寒气燥，兼挟食滞，左脉略弦，右浮濡。恐其喘急，不宜过散，益气生津，参以宣络润下。", "6603": "（案8）肺虚不降，咳呛无痰，舌胖渐白。此属湿蒸，非火旺烁津也。脉虚弦。当用宣泄。", "6604": "（案9）咳呛喘急，肝风大虚，高原之水不降，肾阳亦衰，下不能摄，二足作肿，脉左弦而右濡。拟方专主温养。", "6605": "（案10）先患咳呛，后兼下痢，暑湿未清，脾阳已亏。入冬感受风寒，痢止而咳呛又剧，畏寒热，纳减无味，神倦色悴，右脉濡涩，而左虚弦。急切难效，脾肺兼治。", "6606": "（案1）咳频震络，络伤而痰带血出，脉来弦大。只宜薄味以清上焦。", "6607": "（案2）咳血见红，脉来洪大。此肺胃之火迫血妄行也。治以甘寒。", "6608": "（案3）内伤失血，血虚则气喘，脉涩。阴不变阳也。以致下午身热饮食渐减，乃下损及中，最难痊愈。", "6609": "（案8）络血狂溢，营络大空，阴火潜动，气随上升，阴不能维阳矣。向患痰喘，清肃之不降，金不能生水，肾气亦亏，下亦不能管纳，左脉浮数见芤，阳明为生血之原，全赖水谷以化。拟方以纳气为主，参用养胃。", "6610": "（案9）吴，左。心生血，脾统血，肝藏血，包络为海，冲脉为江河，水谷入胃，渗精于脾，得少阴阴火之化为血，滋养肝脾，灌输百脉。此症始患失血，连次发作，近兼心跳，少阴时有火升，素日掺心，加之劳乏，营络内伤，气阻于络，络血上行，生源不旺，统脏失职，脏燥动火，真阴被铄。左脉虚弦而数，右数而濡。现当燥令，拟用滋补，参以味络。", "6611": "（案10）叶，三家村，左。咳呛失血，冬春以来淹绵不止，寒热往来，手足作酸，胸闷不舒，纳减便泄。其中未免风温湿邪留滞于络，郁热不泄，脉退凉后，浮濡，右涩不数，热时数而略弦。姑拟轻剂清泄。", "6612": "（案11）咳呛失血，阳明络伤，脉来细涩。肺叶张动，则必动络，胃为多血之府，随痰咯出，与阴虚火旺者有别，未宜腻补。", "6613": "（案12）朱，左。阳明为多血之府，太冲应亏，冲脉主一身之血，脾胃中虚，气不能摄，血从外溢，连吐不止，微有咳呛，左胁以下牵动即至，脉大而弦，少冲和之象。恐其气逆狂吐，骤见虚脱。血脱者补其气，与寻常阴亏火旺血不归经者有别，不可过服纯阴及通络之剂。拟方慎补，更须静养为要。", "6614": "（案13）张，左。肝肾阴亏，木火用事，素日嗜饮，肺胃郁热，咳呛失血，连次发作。月初兼见身热，现已凉静，惟咳未减，血止，痰稠，火旺烁金则呛，络伤则咳血，脉细涩，火动则数。此方专主清降，从肝、肺、胃三经调治。", "6615": "（案3）杨，左。操烦过度，君火引动相火，虚阳不潜，阴精易泄，左脉弦数，右滑大。此方专主滋摄。", "6616": "（案1）便浊，脉数。湿热下注也。法当分利。", "6617": "（案2）湿热下注，兼努力伤络，腰膂酸痛，尿血茎痛，脉涩少神。宜破瘀分利。", "6618": "（案3）努力滞气，下归厥阴，兼涉太阳，营络受伤，起患尿血，阴茎结痛，左脉略见虚弦。拟用滋摄，当节劳调养。", "6619": "（案4）症患尿血，太阳少血，皆肝脾阴络内伤，渗入下焦者也。脉浮大而数。养营为主，参用清络。", "6620": "（案5）气不摄血，血无所归。归于厥阴则为尿血，随时发作，脉来弦大。培补为主，参以温宣。", "6621": "（案6）劳力伤络，左偏少腹结痛，小便见血，脉形濡涩。肝脾两伤，急切难效。", "6622": "（案7）劳乏伤气，气陷下焦，少腹作痛，便浊囊胀，脉来弦濡。厥阴少阳兼治。", "6623": "（案8）周，左。肾水为脏，膀胱为阳水，少腹以下为厥阴之部，水中火动，下不能摄，相火寄焉，尿道召阻，脉弦右涩。滋补为主。", "6624": "（案9）湿热下注，厥阴气陷，少腹滞痛，水道有阻，起患膏淋。现在略减，唯茎中不畅，左囊作胀，左脉略弦，右数而紧。宜用疏理。", "6625": "（案10）湿热滞于下焦，尿道通而艰出口。脉大数。而拟用清理，更须节劳。", "6626": "（案11）素体劳乏，气滞下焦，肾虚不摄，气化无权，小便淋沥，少腹胀痛，神倦色悴，脉弦而涩。恐其腹满，急宜滋补。", "6627": "（案4）腹胀气喘，脉不应指，此脾肾阳衰也。仿金匮肾气法。", "6628": "（案5）腹鸣作胀，脉来弦软，脾阳衰也。法当温补。", "6629": "（案6）周，左。命阳下衰，火不生土，脾阳亦弱，痰湿阻滞，胱节作肿，连及肾囊，随气之所别为转移，肺虚咳呛，时或喘急，高原亦不行矣。左脉濡涩，右尺亦弱。拟从下焦温补。", "6630": "（案7）蒋，左。素体阴虚，肝木失养，时或侮土，脾阳已弱，土不胜湿，腹胀足肿，渐至饥削，营液亦亏，郁蒸络热。现在肿势略减，胃能纳而艰于化，脉虚弦而数。恐其虚不能复，拟方以扶胃为主。", "6631": "（案8）脾主中州，肾为水脏，火弱则无以生土，阴水不行，腹胀作肿，两足连囊，举动喘急，脉涩，左略见虚弦。拟从中下二焦温理。", "6632": "（案9）邱，左。大腹属脾，少腹属厥阴之部，类疟淹久，肝脾失调，气阻经腠之间，水道不畅，腹胀纳减，大便溏而小便短涩，右脉滑浮，左虚数略弦，重切皆濡。神色、胃气俱好，当无鼓痰之虞。拟用温通。", "6633": "又脘次已舒，大腹之坚实如旧，绕脐为甚，明系脾虚木亢，气滞于中，水道有阻也。惟脉来左虚弦，右数动，直来直往。此则营气二亏，中无涵蓄，似于此症不符。恐其胀满，始拟培土柔肝，温疏下焦，冀其渐复，攻补皆须斟酌。", "6634": "（案10）朱，右。始因外感宿病作胀，渐致腹满，近日益剧，腹鸣便泄，肌削色黄，胃能纳而脾不能运，纳少辍胀，木亢乘土，脾阳大衰，黄为中央正色，虚极则现，非因湿也。舌光脱液，渴不多饮，饮入即不舒，脉濡不弦。补则胀，攻则益虚，寒则伤阳，温则耗液，处方殊难，𨈻而病退，大虚之后亦难言复，况目前不能即退耶。姑拟轻剂，乘间投之，以觇其机，因胃虚不能受重药也。", "6635": "又脾主肌肉，肌削色黄；肾主五液，液耗舌干。肝木独亢，腹胀而坚，胃能纳，食入即胀，症属虚鼓。脉形濡细。极难理治，姑拟疏补并进。", "6636": "（案12）左。《内经》云：诸气𪱥郁，皆属于肺。此言上焦之气也。今由腹中上升，直从下焦丹田出矣。脾土中虚，肝木不达，其所以鼓动之者，皆由厥阴腹胀便泄，脉形濡细。拟方先宜振定中州，佐以温疏之品。", "6637": "（案13）操烦过度，心血先亏，肝脾不滋，木亢侮土，胀而兼痛，随时发作，木托根于土，土润泽则发荣，土燥则木槁，按脉右濡涩，左虚弦，亦见涩象，血少则涩，营不行于脉中也。土弱则濡，发时宜温疏之。时宜甘润之剂滋养，温春气也，木逢春然萌蘖，际此时艰，更须达观。", "6638": "（案14）肾阳下虚，火不生土，气陷于下，少腹不坚，手足俱肿，舌乾红少液，真阴亦亏，脉濡细而涩。滋阴则滞气，补火则烁阴，恐成虚鼓，诸惟善遣为要。", "6639": "（案15）脾肾阳衰，腹胀足肿，随退随发，肌削色黄，脉形弦细。症属虚鼓，正气旺乃能胜邪，屡经克伐，元气大伤，骤难见效，惟有温补一法，参金匮肾气丸。", "6640": "（案16）脾主中州，肾为水脏，火弱则无以生土，阴水不行，腹胀作肿而足连囊，举动气喘，脉涩，左略见虚弦。拟从中下二焦温理。", "6641": "（案17）素体阴亏，肝木失养，时或侮土，脾阴已弱，土不胜湿，腹胀足肿，渐致肌削，营液亦亏，郁蒸终热。现在肿势略减，胃能纳而艰于化，脉虚弦而数。恐其虚不能复，扶胃为主。", "6642": "（案19）土不胜湿，归于肌腠之间，蒸郁成黄，脉形浮濡。温健为主，参用淡渗。", "6643": "（案20）服温剂，色黄更甚，黄为土之正色，因湿外现，右脉虚弦。培土为主。脾主肌肉，肺主皮毛，仍拟温利。", "6644": "（案21）脾胃中虚，土不胜湿，气阻作胀，左胀不舒，脉大略滑。培土为主，参用泄木。", "6645": "（案22）肾为水脏，真阳下虚，阴翳日积，囊、足肿，脉形浮濡。参肾气法。", "6646": "（案23）木郁乘土，腹胀色黄，近感暑湿，寒热类疟，胀势加剧，舌白而少液，脉细见涩。先疏其气，然后达邪，否则恐其中满。", "6647": "（案24）诸症见于下痢之后，其专属于脾可知，脾主四末，虚则湿滞于络，而肢节酸楚，气不行也。脾统血，其阳为气，当由火化，其阴即血也，所谓土膏也。土为润泽，故能生发滋长，若土燥，岂能生物者，以血之润泽，得气之和煦，温分肉，灌百脉，则筋得能养，而肝木亦平，故此症总宜治脾为主，人知脾土宜燥，而不知脾阴即血，往往歧而二之，东垣主脾胃之论，然而但言气而不及血，其方率皆升阳，取地气上升之义，而其究终为燥土，则亦未尽善也。拟方主温健。", "6648": "（案2）痞结为患，延至腹痛，食减，便溏，脉软无力。此脾土阳衰，殊非轻候。", "6649": "（案4）胡，左。阴疟淹久，现虽截止，而余邪未清，营液素亏，肝脾失养，疟后气弱，而营血益耗。舌中脱液，宿痞作胀，甚则呕逆，肌削色黄，脉形濡细。恐其中满，培中为主，参用疏达。", "6650": "（案5）肝为先天，冲带皆为所主，木亢乘土，虚邪结痞，营络阻滞，八月愆期，去秋起患阴疟，现虽已至，肝脾益亏，日后渐恐腹满。右脉略涩，左见虚弦。不必急于通经，健脾养肝，俾得渐复，平日忌服酸冷等物，并戒气恼。", "6651": "（案7）肝邪结痞，侮土作痛，甚则呕逆，木托根于土，土弱则木病，则侮土，右脉大而见濡，左部亦弱，并无弦急之象。此系积劳内伤，营气二亏，木失养所致，惟已病多经年，急切不能见效。拟以温养之剂扶脾柔肝，济以恒力，更能颐养，或可渐次就痊也。", "6652": "（案8）柴，左。胃气素旺，过食易伤，夏秋不无暑湿，中脘结痞，气陷下趋，则便泄成利，胁腹掣痛，左脉弦，右沉实。土弱木亢，消补参用，佐以辛温升降之品。", "6653": "（案9）营液内亏，血不营筋，因风牵掣，木邪结痞，时或作胀，表虚则多汗，心跳时眩，脉弦促不伦。拟用滋补，专理肝脾之阴。", "6654": "（案10）寒热之后，厥阴气滞，小腹痞痛，归于右偏，脉弦紧实者，宜疏。", "6655": "（案11）病后未复，肝脾已乏，痞胀腹膨，近兼复感寒热之后，色黄而泛，脉形浮濡。阴亏内热，恐其肌削，当加意调摄。", "6656": "（案12）肝邪结痞，侮土作痛，脉弦而促。气弱而营液亦亏，酌进滋养。", "6657": "（案2）纳食呕吐，脉来细软，土衰木乘也。宗仲景法。", "6658": "（案5）胃阳中虚，土不培木，肝邪必亢，时或作胀，甚则呕逆，味酸而苦，右脉浮濡，左促数略弦。培中为主，参用温疏。", "6659": "（案6）气郁伤中，食入作呕，阻于胃口之下，脉形濡弱。中焦不应无火，所阻者气。体弱境难，恐其不健。", "6660": "（案7）向患痰喘，近兼呕逆，胃气大虚，纳食减少，脉形见涩。暂拟和降。", "6661": "（案8）纳减呕逆，胃气中虚，土不生金，兼患咳呛，神倦色悴，脉来濡弱。酌培补，冀其渐复。", "6662": "（案9）疟后未复，木邪克土，中气受伤，胃阴亦耗，痞胀作呕，舌中脱液，脉形濡细。恐其中满。", "6663": "（案1）胸次作痛，六脉模糊。乃由湿痰所阻，清阳不运也。仿平胃法。", "6664": "（案2）胸闷作痛，短气，脉沉。此属清阳失展，气机不利也。宗《金匮》法。", "6665": "（案1）喘逆自汗，脉数无力。此阴涸阳浮，气衰失纳也。法当收摄固元。", "6666": "（案3）脉沉气喘，背冷腰痛。肺肾虚寒也。法当温补。", "6667": "（案4）举动喘促，脉来细软。此属元海无根，气逆上泛，理宜补纳。", "6668": "（案5）喘急多痰，右脉弦滑，中气虚而停饮上逆也。法当燥土祛邪。", "6669": "（案7）陈，右。脾阳中虚，土不生金，肃令不降，咳痰喘急，两足渐肿，脉来细涩不弦。肺主高原，脾主中州，而出纳则肾主之。拟方先从气分调治。", "6670": "（案8）肺主金，恶燥，金弱则肾亦虚。表属肺，虚则易感，咳呛多痰，感邪发作，近乎哮喘。此症难于脱根，邪由俞穴而入，其痰有窠，非药力所能达也。素体不足，脉见虚弦。肺肾兼治。", "6671": "（案10）祝，左。肺主金，金为秋令，清肃下行者也。真阴本亏，虚火上炎，肺受其烁，兼外邪，起患喘急，愈发愈密，痰热上蒸，有升无降，所谓金苦气上逆也。脉数右更浮。金为水母，益气为主，佐以凉泄。", "6672": "（案11）陶，右。肺俞感寒，起患痰喘，近发益密，表虚则外感易入，气弱则顽痰日蒸，发则上逆，脉形濡弱。现当平复，益气滋阴，冀得希发。", "6673": "（案2）肝风挟痰。肢麻头晕，右脉弦数。惟恐仆跌。", "6674": "（案5）脾胃气虚，湿痰中积，附于皮膜之间，流注脉络。现当湿令，以益气为主，参用疏涤。", "6675": "（案6）濮，左。脾胃气虚，土不生金，湿痰作呛，近兼嘈杂，此胃中虚火烁津，所吐之痰皆胃汁也。脉形浮大。拟温润之剂，益气生阴。", "6676": "（案7）肾阴下虚，水不滋木，木火偏亢，虚痰结核，现已溃脓，右耳出水，脉左弦数，右涩。素体有湿，火必兼风，蒸热上升。拟方滋摄。", "6677": "（案8）脾虚多痰，脉络壅滞，肝木不达，引动内风，风与痰凝，清阳内陷，症发为癫。此与阴维所发异而实同，脉濡数仆数。中无实火，益气为主。", "6678": "（案9）向患痰火，肺气本虚，金不制木，肝邪偏亢，左胁掣痛，连及腰脊，脉形浮濡。拟用培补，参以宣络。", "6679": "（案1）痰饮上泛，纳食艰运，中下焦阳微也。脉象沉弱不扬。治以通阳涤饮法。", "6680": "（案2）肝属木，为风，为火，主筋，托根土中，藉血以滋脾土。先虚，起患积饮。土弱则木不荣，藏血少则槁，虚火妄动，筋燥则牵掣，气升为眩，上盛下虚，脉细涩而濡，右部略弦，积年既久，非寻常草木之力所能速效。木之生也土，须润泽，而非春气之温则不萌，虽生于水，而实藉所藏之营血以养。故治木之要，不外培土养阴。木能克土，中阳必亏，故必佐以辛温，平时更须调饮食，慎喜怒，气得平。虽不脱根，自可渐复。", "6681": "（案4）清晨吐水，乃觉酸，此名悬饮，犹水之瀑布也。胃虚气弱，湿积不化，按之作水喜，其中有窠，药难径达，色白而浮，脉左虚弦，右濡。拟用培补涤饮等法。", "6682": "（案1）脾阳中虚，气弱则寒，土不生金，肺气亦弱，向患喘咳，痰滞上膈，本症如此。春夏以来，感受外邪，曾发寒热，元虚未复，余邪归于三阴，从少阳发，起患阴疟，骤不能止，色青略瘦，邪不甚重，正气已虚，脉涩略弦，右部未和，胃气渐复。此方补气和营，参以辛温。另开方专治疟。", "6683": "（案2）阴疟，寒热已不准期，营气并亏，骤不能复，面黄体软，舌干少液，纳减时呕，脉形濡弱。当用培补。", "6684": "（案3）始由暑湿郁蒸，寒热发疹，以致结毒溃脓，真元已亏，自后连次发疟，至今未止。疟归少阳，而寒热则由营卫，日久脾虚，色黄而浮。肢节酸麻，汗出不禁，嘈杂能食，脉随寒热为紧数，总之虚弦而促。气弱而营液亦耗，有虚无实，急宜培补。", "6685": "（案4）向患咳呛，去秋由寒热转阴疟，至今未止。冬春感寒，呛亦加剧。入夏来，诸恙略减，胃气能纳，即发热时亦不疲乏。惟金不生水，肾阴先亏，水不生木，肝阴亦弱。疟为少阳之邪，与厥阴同部，久疟必虚，势不可散，惟有和理营卫而已。再将柔润之品滋养金水，待其自复，脉形濡细，左部略数，并无虚急之象。总之，宜补不宜攻。", "6686": "（案5）少阳疟邪，因腠理致密，汗不得泄，失表内陷，寒热每日递迟，发则烦躁，胃不纳谷，延至二十余日，伏邪渐深，胃中津液被烁，舌苔乾红脱液，邪未出而正先伤矣。汗下二法既不能施，又无实热可清，拟先补气生阴，进生脉法。虽尚未平安，而舌苔不化，疟亦不减，诊脉左关尺微弦，右关见弱，谷气太少。方书云：有胃气则生。目前惟以养胃为主，有胃气，然后能生津液，亦可攻邪。拟方候高明酌用。", "6687": "又方疟后营气二亏，心、肝、脾三脏失养，浮阳上升，清浊倒置，症见心烦健忘，头痛耳鸣，左脉虚弦，右关较大。心藏神，肝藏魂，虚则神魂不安，拟以养心为主。", "6688": "（案6）暑湿外感，寒热发疟，初起间日，后转三阴，现在外象已轻，神倦色黄，舌光脱液，痰随气涌，胃不思纳，右脉少冲和之气，左更濡弱。正气先亏，久而津液亦耗。湿伤脾，暑伤气。古人于暑症皆用生脉，即治湿亦用健脾升阳。姑拟数味，高年虚乏过甚，恐难为力耳。", "6689": "（案7）阴疟寒热，肝阴内伤，络热动血，脉弦而数。参一柴胡法。", "6690": "（案8）久疟伤脾，色黄而脉虚弦，阳弱则阴无所附。拟用温补，不心专治少阳。", "6691": "（案9）阴疟淹久，脉形濡弱。阳衰不能卫外，中气亦弱。拟用温理。", "6692": "（案10）肝阴内亏，疟久不止，血随火升，举动鼻衄，左脉略弦，右濡。拟用填补，不专治疟。", "6693": "（案11）阴疟淹久，现虽截止，而余邪未清。营液素亏，肝脾失养，疟后气弱，而营益耗。舌中脱液，宿痞作痛，甚则呕逆，肌削色黄，脉形濡细。恐其中满，培中为主，参用疏达。", "6694": "（案12）阴疟淹久，肝阴内亏，寒重热轻，心跳头痛，脉来弦细。和营兼泄少阳。", "6695": "（案15）久疟不已，咳逆盗汗，色脉少神。殊非轻候。", "6696": "（案17）暑湿伤气，寒热，腹痛兼胀，脉不条达。太阴疟也。", "6697": "（案2）久泻不止，色脉少神，此脾肾阳衰，清不升也。殊非轻恙。", "6698": "（案7）久痢延至腹胀，六脉细软，阴阳两伤也。必须温补。", "6699": "（案8）久痢脉微，命阳衰也。若不急进补，惟恐延成肿胀。", "6700": "（案11）湿热内侵，痛泻，脉数。", "6701": "（案12）症属痢疟，寒热有往来之势，胸闷呕逆，舌糙白，不渴，向患头风，痛归左偏，脉弦右甚，似非所宜，营液素亏，骤不能补。姑拟和解太阳兼少阳治。", "6702": "（案13）脾虚挟湿，营液亦耗，近因外感，起患下痢，暑邪挟暑饮，令积寒气，陷下焦，脾土肌肉既弱，不能达邪，脉形濡弱。先以培中为主，接进疏化之法。", "6703": "又方暑湿伤脾，气弱不化，茶瓜之冷，由面之消，中焦阻滞，起患下痢，日数十行，里急后重，舌黄而腻，脉右濡左不弦而涩。凡痢皆因气陷，今脾阳既虚，不能达邪。先培补，清升则浊降，拟用疏化之品，此方主之。", "6704": "又方脾胃两虚，起患下痢，大势已减，胃亦渐开，时觉嘈杂，中虚气之虚可知。肾为胃关，脾主中州，暑湿之邪虽未净，然不培本原，徒事疏化，断不能定也。右脉虚弱，冲和之气自在，左部略大。拟用培补，补则清阳自升，略参疏品。", "6705": "（案14）暑湿伤脾，疟后兼利，患症经年，大便仍泄，肌削色黄，食不甘味，脾土中虚，清阳下陷，脉促数而弦，尚有郁火。培土为主，参用疏达。", "6706": "（案15）暑湿蒸热，因疟转痢，气滞于下，里急后重，舌白渐黄，右脉略数。升清为主。", "6707": "（案17）脾虚下痢，久必传肾，肾气素亏，关门不固，脉来见濡，左略弦。拟用培补，多服见效。", "6708": "（案18）肾为胃关，实主二便，久痢脾虚，气陷于下，少腹增痛，脉见虚弦。拟用温摄。", "6709": "（案19）便泄淹久，时或带血，肛门作痛，此属脏毒，由脾肺气虚下陷。脉形濡弱。参真人养胃法。", "6710": "（案20）夏秋暑湿郁久不泄，入冬又感寒邪，归于小肠，发为阴疟，疟止患痢，时或带红，脾虚则气陷。凡余邪之蕴于中者，势必下趋，左脉弦涩。参败毒及清暑益气等法，升其清气，不必纯补。", "6711": "（案21）脾命阳衰，火不化土，表阳亦于下焦，便泄淹久，兼之畏风，右脉浮濡。拟方培补，作丸子调理。", "6712": "（案1）遍体作酸疟后营虚，偏体作酸，两足为甚，体弱纳减，脉形弦细。拟用培养。", "6713": "（案2）心腹痛寒邪阻滞，心腹结痛，脉弦细而紧。拟用温通。", "6714": "（案3）疝气寒邪滞于下焦，起患疝气，少腹结痛，脉来弦细。拟用温疏。", "6715": "（案4）肺虚咳呛肺虚不降，咳呛有痰，体软纳减，脉来细涩。拟用疏理。", "6716": "（案5）血症咳呛淹久，血症时发，两胁掣痛，脉数而弦。当用清降。", "6717": "（案6）腹满肝脾内伤，渐致腹满，两足微肿，体软肌削，舌红脱液，脉濡，右略弦。拟用温理。", "6718": "（案7）积湿积湿下注，小便短塞作痛，舌白纳减，脉来濡细。当用疏理。", "6719": "（案8）外感咳呛肺感外风，咳呛有痰，脉濡。暂拟疏降。", "6720": "（案9）咳呛失血劳乏伤气，时觉体软，气不生阴，营液内耗，脉络失养，久而火动，木旺克金，起患咳呛，胁痛失血，宿痞时动，脉来浮濡。拟用培补。", "6721": "（案10）泄泻素无荤血脂膏之养，脾阴先亏，土不培木，肝邪亦亢，侮其所胜，土受木克，益形困之传化矣。宜先肿而胀，后遂便泄，甚则完谷，小肠为坎之阳火，火衰不化，营卫出于脾，营不能与卫和，时觉潮热，君火衰则相火亦弱，火不化土，故便泄。右脉略促，少冲和之象；左浮濡，沉部不摄。拟方培补，参以酸辛。", "6722": "（案11）脘痛脘痛偏左，每发必在午后，至亥方止，经术士剖开分向，将牛角吭出稠痰两碗许，不愈，卧床半年。后瓦楞子得止，久亦不效，迄今四年。右脉濡弱，左关见革。此木邪侮胃，其肝脏必有一叶枯者，惜乎华元士为之割补也。", "6723": "（案12）惊后便秘惊后得疾，每日默坐，问之不应，或作非对。惟母与语，对答如常。大便闭结，得解而愈，现在复发，手足先痉，定后，症如前状，此目惊动魄，肺藏魄，下通大肠，魄门之下为幽门，气为厥阴所阻，故便结，脉沉涩。拟通幽门。", "6724": "（案13）肿满肺为阴金，属兑，兑为泽，太阳坎之阳水，而下焦为厥阴之部，气陷不升，水道有阻，渐致肿满，脉来沉数。当降高原以通沟渎，兼泄巽风。", "6725": "（案14）郁证肝藏血，血虚则卫脉失调，加之躁烦，未免多郁，郁则木不达而营液亦耗，火动络，热迫血妄行，偶然咯吐，并不咳呛，肢节觉酸，心跳多寐，脉左寸紧，关弦。养心滋肝兼调奇脉。", "6726": "（案15）产后产后一月有余，向有肝气营血骤热。肝脾失养，木亢克土，气滞则下陷，大腹胀满，下及两足，水道有阻，厥阴之络与太阳相联，兼涉任脉，脉弦细紧。拟以疏肝升清阳为主。", "6727": "（案16）痰壅脾虚挟湿，微感外风，蒸痰壅，症近乎痫，脉形涩滞。暂拟开泄。", "6728": "（案17）鼓胀肿胀不减，脾肾两衰，阴翳不化，脉来濡细。大势不浅，拟用温疏。", "6729": "（案18）腹痛肝脾气滞，绕脐腹痛，脉见虚弦。从下焦温疏。", "6730": "（案19）痞结肝脾气滞，左腹结痞，大便带红，左脉弦大。拟用疏理。", "6731": "（案20）挟湿气虚挟湿潮热畏寒，体软无力，脉形浮濡。拟用培补。", "6732": "（案21）肢节酸楚营虚失养，肢节酸楚，时觉心跳，腹中不舒，脉弦。仍拟宣理。", "6733": "（案22）痞宿痞气滞，少腹作痛，经阻带下，面浮肌削，脉形濡涩。拟用温疏。", "6734": "（案23）失血失血后，肝脾营络内伤，体软色黄，脉来濡细。骤不能复，当用培补。", "6735": "（案24）痞痞痛腹胀，肝脾两亏，潮热肌削，近兼咳呛，脉形濡细，左弦。病久元虚，现当木令，恐其加剧。", "6736": "（案25）鼓胀肝脾内亏，木邪侮土，腹胀作痛，色黄而浮，脉形濡细。当用温疏。", "6737": "（案26）痫脾阳本亏，湿痰内蒸，心火不静，入夜少寐，脉大而濡。拟用疏理泄。", "6738": "（案27）疟母疟后结痞，肝脾已伤，近因积湿滞气，先肿后胀，土不培木，木来乘土，气阻则水亦不行矣，脉形濡细。暂用温通。", "6739": "（案28）便血疟后未复，肝脾已亏，气泄便泄，络伤带血，此由虚不能摄，非尽因暑湿也。脉濡不弦。拟用培补。", "6740": "（案29）嗳哽厥阴之脉贯胃循喉，中气本亏，营液亦耗，血不足以养肝，木亢侮土，不纳不饥，少纳即嗳，咽间时哽，左脉弦细，右濡略浮。暂拟疏泄，以动其机。", "6741": "覆：胃气弱而胃汁亦亏，肝无血养，兼其克中焦，阻滞，纳减，时嗳上冲，咽哽，左脉弦细，右濡。培中为主，参用和阴。", "6742": "（案30）肤痒阴亏火旺，木失所养，下焦郁热，肤中作痒，时觉虚烦，火盛则泄，脉弦紧。拟从苦降。", "6743": "（案31）阴疟肾阳素亏，气不生精，营阴亦耗，肝木失养，外感风寒，入于少阳，起患阴疟，淹久不止，中气弱而表阳亦共，卫不能与营和，纳减少味，舌腻白微黄，脉濡不弦。此方和解，参以益气。", "6744": "复：气生精，精化气，气者相维，素体不足，真阳先亏，加之阴疟，现尚未止，色悴脉濡。正不胜邪。此方专主温补。", "6745": "（案32）头眩经停营液内亏，肝脾失养，疟后未复，冲脉不调，肝邪时亢，心跳头眩，癸水不至，脉涩。拟用滋补，参用温养。", "6746": "（案33）遗精肝肾阴亏，精不能摄，时或遗精，虚风上升，发则眩仆，脉浮大而濡。拟用填补。", "6747": "（案34）表虚表阳根于中阳，虚则外感易入，畏寒不热，由于气弱，非纯外感也。脉形濡细。拟用温补。", "6748": "（案35）下血下血，脉弦，阴络内伤。培土和肝，略参苦坚之味。", "6749": "（案36）腹胀命肠下衰，真气运迟，肝邪侮土，兼挟肾气，腹胀时痛，左偏为甚，脉见虚弦。拟方培补，参以温疏。", "6750": "（案37）心虚操烦过多，心血本亏，阴疟之后，肝脾亦弱，夜不安寐，时觉嘈杂，体软肌削，诸形疲乏，脉来濡弱。心为火，于象离。古人治法，心血虚则补血，心火旺则泻火，并未言及火衰，不知心火固有衰时，心虚即火衰，人知心生血，而不知血得离火之化而生也。现症：神疲气弱，入夜不安寐，是阳弱不能入阴，当补心火以助生原。拟方常服，古惟人参养营汤得其意，而不能明言。", "6751": "（案38）筋掣劳乏伤营，筋失所养，外感风寒，引动内风，络脉牵掣，有触觉痛，曾患便血，脉来弦大。拟用滋养。", "6752": "（案39）腹胀肝脾不和，腹胀时痛，近兼感风，咳呛有痰，肺气不宣，右脉略浮。暂拟疏降。", "6753": "（案40）脘痛呕逆肝邪偏亢，气不条鬯，脘痛作胀，连胁及背，时或呕酸，脉弦属实。拟用疏泄。", "6754": "（案41）失音咳呛失血，咽痛失音，恐成喉痹，脉浮不甚数。肺阴大亏，拟用甘平清金，乃能生水。", "6755": "（案42）头风由营虚失养，头风时发，胸闷不舒，偏体肢节酸楚，脉来濡弱。拟用疏散。", "6756": "（案43）冬温身热无汗，咳呛多痰，两胁时痛，舌干少液，胸闷便闭，症属冬温。太阳阳明兼涉肝肺之络，防其气急，脉浮而数。中以化热，不可过散，以致劫津。拟用疏降，参以宣络。", "6757": "（案44）咳痰呕逆肝胃不和，近兼外感咳呛，痰腻并黏，时或呕逆，脉浮而弦。拟用疏降。", "6758": "（案45）咳喘肾命下虚，气不摄阴，咳呛喘急，色黄，脉弦。仍拟纳气。", "6759": "（案46）脾泄寒热未止，大便溏泄，纳减少味，脾阳本虚，传化失宜，兼受木克，营卫亦禀于脾，虚则胃不和，脉左略弦，右涩。脾泄不止，胃不得开，胃弱更不受重剂。拟方培补于气，胃开酌之。", "6760": "（案47）内闭病中多服重剂之品，舌强不语，脾窍不灵，此属内闭，脉涩不数。宜用开泄。", "6761": "（案48）咳呛肺肾本虚，微感外风，咳呛多痰，肃令不降，脉来弦滑。不可过散，暂拟滋摄。", "6762": "（案50）喘咳肺虚易感，咳呛喘急，肃令不降，脉右涩。此症难许脱根，暂拟疏理。", "6763": "（案51）咳呛劳乏伤营，失血之后骤不能复，体软纳减，微有咳呛，脉涩不数。酌进调补。", "6764": "（案53）腹痛素体劳乏，肝脾失调，气滞不达，腹痛便血，近感寒邪，痛势加剧，随起寒热，咳呛胁痛，舌白而腻，脉大而滑。暂拟温疏。", "6765": "（案54）肺虚痰喘略平，肺气大虚，脉浮濡无力。素力劳乏，当用培补。", "6766": "（案55）气阻作呕中焦气阻，微感外风，脘次不舒，时或作呕，畏风，微热。肝胃不和，肺亦不达。脉右涩。拟用和解。", "6767": "（案56）血症肺虚咳呛，血症后复发，火升发热，脉数而弦。真阴本亏，拟用宣络。", "6768": "（案58）结痞劳乏伤脾，兼受木克，少腹作痛，左偏结痞，纳多时胀，脉左弦，右濡涩。久恐成臌，拟用温疏。", "6769": "（案60）疝气疝气为患，右肾作胀，厥阴气滞，陷于下焦，纳食略减，右脉濡细，左不弦。拟用温疏。", "6770": "（案61）音闪咳呛淹久，微觉音闪，体软纳减，土不生金，津液内耗，脉来浮濡。拟用滋养，参以益气。", "6771": "（案62）腹痛努力伤络，厥阴气滞，腹痛连胁，曾经见红，左脉略弦。", "6772": "（案64）咳痰胁痛腹痛已减，身热无汗，咳痰胁痛，舌白不渴，脉涩。当泄表疏中。", "6773": "（案65）盗汗咳呛多痰，时或气升，舌干少液，多出盗汗，肝肾两虚，幸脉不弦大。拟用补摄，参以疏降。", "6774": "（案67）便浊肝肾本虚，湿热下注，小便带浊，左脉见弦。酌进滋养，参以疏剂。", "6775": "（案68）脘痛肝肾内伤，中焦气阻，脘次时痛，纳食坚化，畏寒微热，脉滑而弦。当用温疏。", "6776": "（案69）浮阳上越肝膨阴亏，水不济火，浮阳上越，脉数而动。当以体阴用阳之品。", "6777": "（案70）经迟腹胀痛，经迟。奇脉失调，当补肝肾。", "6778": "（案71）咳呛操劳过度，营液内亏，感受风寒，咳呛有痰，微寒忽热。肺主表，表虚则营不和，兼阳维右脉略数。拟用疏降。", "6779": "（案72）痞脾胃气虚，肝邪不平，腹中作痛，宿痞时发，脉弦而促。酌进调养。", "6780": "（案73）咳呛寒热已久，势不甚壮，近兼咳呛，胁痛气逆，宿痞时升，肌削多汗，脉数，左略弦。病久必虚，恐其喘急，骤见脱象。", "6781": "（案74）湿热积湿蒸热，中焦不舒，面色微黄，咳呛有痰，脉滑而弦。拟用疏泄。", "6782": "（案75）脘痛脾胃气虚，中焦阻滞，脘次作痛，纳减少味，肌削痛剧，脉濡。拟用温补。", "6783": "（案76）咳呛身热多汗，咳呛有痰，大便仍溏，肌削神倦，脉形濡弱。久病必虚，当用培补。", "6784": "（案77）痞痞胀腹痛，纳减少味，脾虚木克，素体劳乏，脉见虚弦。恐其中满，仍拟温疏。", "6785": "（案78）脘痛气陷中寒气滞，脘次作痛，气陷下焦，脉弦而涩。益气为主，参以疏达。", "6786": "（案79）呃中虚木郁，脘次时呃，畏寒不热，脉濡。当用温理。", "6787": "（案80）阴疟脾胃气虚，虚则体寒，素多痰湿，起患阴疟，疟属少阳，而此则兼涉太阴。脉涩不甚弦。当以通阳为主。", "6788": "（案81）肝脾失养滋养肝脾，兼理奇脉。", "6789": "（案83）失血微咳有痰，胁痛失血，脉浮略滑。肺胃郁热，凉泄为主，参用宣络。", "6790": "（案84）冬温身热无汗，咳呛痰多，左胁掣痛，痰中带血。症属冬温，惟不传经。脉浮不弦。恐其气升，暂拟宣理。", "6791": "（案86）脘痛中虚多寒，脘次作痛，肌削加剧，脉形濡弱，当用培中。", "6792": "（案87）咳呛咳呛气升，咯痰难出，舌光少液，纳减色黄，脉来濡弱。肺肾两亏，当用滋补。", "6793": "（案88）失血络伤失血，劳乏所致，当从肺胃宣理，脉芤，势未定也。", "6794": "（案89）便闭病邪已解，中气大亏，肠胃津液亦耗，大便久闭，胸闷时呕，下不通则返乎上，脉濡细。培中为主，参以润下。", "6795": "（案90）游风游风上面，归于左边，色红而肿，小便不利，营液内亏，风邪郁热，脉浮数。当用凉泄。", "6796": "（案91）夜不安寐肝阴内亏，脾肾之阳已弱，纳食不旺，夜不安寐，脉来虚弦。拟用培补。", "6797": "（案92）咳呛感风咳呛，淹久不止，肺阴已亏，上焦郁热，脉数而浮。暂拟清理。", "6798": "（案93）纳减盗汗疟后未复，宿痞时胀，体软，纳减，现出纳减盗汗，脉来弦细。肝脾内亏，骤不能补，拟和理。", "6799": "（案94）湿阻积湿阻中，脾虚化迟，纳减无味，脘次不舒，脉弦不和。拟通阳为主。", "6800": "（案95）失血咳痰失血，阳明络伤，脉见虚弦。知肝脾不足，不专在肺也。", "6801": "（案96）咳呛痰秽咳呛淹久，肝阴内亏，咳痰带秽。上焦郁热，恐其成痈。脉濡涩不数。现当燥令，清金为主。", "6802": "（案97）肺肾亏虚兼感风寒肺肾两亏，兼感外风寒，身热痰多，气升体软，纳减，脉形细数。恐见脱象。", "6803": "（案98）脘胀中寒气弱纳食化迟，脘次时胀，右脉见涩，左略弦。当用疏消，参以辛温。", "6804": "（案99）发热秦，左。素体气虚，表阳根于中阳，虚则卫分不固，畏风发热，色黄，脉濡。益气为主，太阳阳维兼治。", "6805": "（案100）虚人外感向患便血，肝脾两亏，近兼畏寒，表阳亦弱，左脉弦细，右濡。风寒外感，暂疏理。", "6806": "（案103）外感咳呛胃阳本虚，肺感外风，肺气不达，微有寒热，咳呛有痰，甚则呕逆，脉数右浮。拟用疏降。", "6807": "（案104）咳痰带红咳痰淹久，曾经带红，甚则呕急，脉濡细而数。肺阴内亏，肃令不降，拟用清养。", "6808": "（案105）肺燥咳呛咳呛淹久，外感风邪，兼挟木火，肺金被烁，现当燥令，脉浮数，左弦。暂拟清金，后养营。", "6809": "（案106）胁胀痛肝邪偏亢，胀而兼痛，脉来弦大。当用温疏。", "6810": "（案108）血痢脾肾两虚，伤及阴络，血痢淹久，天寒加剧，右脉浮濡。火不生土，肾为胃关，仍用温健。", "6811": "（案109）嗳气阳明络伤，先患失血，现在血止，胃气中虚，纳食不减，时或作嗳，胸膈时觉气滞，脉形濡涩，舌干少液。气不生阴，久恐成格。拟温补。", "6812": "（案110）脾虚作胀脾阳中虚，土不培木，又无血养，肝邪偏亢，侮土作胀，肺金亦生于土，金弱则不能克木，木反乘金，肌削色黄，脉来浮濡。当用滋培。", "6813": "（案111）发瘰脾虚积湿，郁热伤营，偏体发瘰，便溏带血，脉形濡弱。当用滋补，参以宣络。", "6814": "（案112）痰喘气虚痰喘，风寒易感，咳呛气促，右脉浮数，左略紧。暂拟疏降，后当进补。", "6815": "（案113）畏风潮热肝郁侮土，中阳不达，营络不和，太阳主表，厥阴之脉与阳维相联络，畏风潮热，卫外之阳不固，营液亦亏，不能充周，虚邪时亢。右脉见弦。益气和营，兼理奇脉。", "6816": "（案114）齿龈根痛肝邪略平，宿痞时痛。外感风寒，归于阳明。兼挟风燥，齿龈作痛，脉形濡数。参用疏泄。", "6817": "（案115）腰酸腹痛冲带为病，腰节酸楚，气滞腹痛。左脉弦，右涩。拟用疏理。", "6818": "（案116）音哑音哑略清，咳呛不减，右脉浮而左涩。肺肾两虚，金不生水，当用滋养。", "6819": "（案117）肝胀脾虚木旺，邪亢作胀，肌削色黄，脉来弦细。仍拟疏理。", "6820": "（案118）血痢下痢带红，阴络内伤，脉来弦细。当用肝脾调养。", "6821": "（案120）脘胀木亢侮土，脘次时胀，脉弦而紧。现当平复，酌进调补。", "6822": "（案121）咳呛身热不凉，咳呛有痰，气升呕逆，两胁掣痛，脉来浮数，肺虚不降。防其喘急，更不可散。酌进调补，参以疏降。", "6823": "（案122）痰咳失血脾胃气虚，中多痰湿。气升咳呛，曾经失血。表虚畏寒，气不摄血，时或便血，脘次嘈杂。肝脾主气其阴血。脉见虚弦，右略数。归脾、六君主之。", "6824": "（案123）胀营液内亏，肝失所养。木火上升，咽间作痛，膈次不舒，近兼咳呛，脉数而弦。冬寒气燥，姑拟甘润。", "6825": "（案124）胀血不养肝，木亢乘土，时或作胀，奇脉不调，脉来濡细。拟用滋养。", "6826": "（案125）腹胀腹胀不减，中寒木郁，兼挟湿邪，恐其成鼓，脉形濡细。拟用温疏。", "6827": "（案126）痰喘痰喘有根，感风发作，气升不降，脉数略浮。现当燥令，暂宜降肺，未能进补。", "6828": "（案127）痰咳土不生金，积湿蒸热，身热已止，咳痰带红，体软色黄，脉形濡浮。恐其成肺痿。", "6829": "（案128）下痢寒湿侵脾，腹痛下痢。风邪入肺，咳痰音哑，甚则呕逆，右脉浮滑。当用疏化。", "6830": "（案129）外感咳痰风邪外感，咳痰，胁痛，脉形浮数。暂拟疏降。", "6831": "（案130）痞胀宿痞作胀，脘腹不舒，脾阳中虚，木郁不达，脉形浮濡。当用温疏。", "6832": "（案131）痞胀宿痞时胀，肝木侮土。中气未和，纳减少味，畏寒不热，右脉见弦。疏补并进。", "6833": "（案132）产后瘀阻腹痛产后失调，瘀阻未清，时觉腹痛。脉右涩。调养肝脾，兼理奇脉。", "6834": "（案134）肿胀湿从下受，两足先肿。渐及大腹，连囊。面浮色晦，近兼咳呛。土不能胜，高原不行矣。脉形濡涩。拟用温理。", "6835": "（案135）阴液亏虚营液内亏，肝脾失养。木邪时亢，冲带不病，舌光脱液。脉形濡涩。拟用柔剂。", "6836": "（案136）痰喘咳痰喘急，有感即发，脉数而弦。暂拟疏降。", "6837": "（案137）潮热疟止潮热，时觉畏风，肢节酸楚，营虚失养，舌干少液，脉濡数。从肝脾调养。", "6838": "（案138）失血木火作呛，络伤失血。现当气燥，肃令不降。脉弦而数。从肝脾清养。", "6839": "（案139）呕逆肝脾不和，浮阳上越，气不调畅，时或呕逆，腰节酸楚，脉形弦数。拟用调补。", "6840": "（案140）下痢痢久不止，微有寒热。腹痛连胁，纳减少味，脉来濡涩。疏补并进。", "6841": "（案141）气虚咳呛外感已解，气虚未复。体软无力，纳减少味，兼之咳呛，大便仍溏，脉形濡弱。酌进调补。", "6842": "（案142）虚火作呛肝肾两亏，水不济火，阴火上升，射肺作呛，左脉弦大不静，右数亦弦。拟用滋补。", "6843": "（案143）外感咳呛疟后肝脾内亏，气不调畅。近因外感，咳呛有痰，脉形濡涩。暂拟平调益气，参以和营。", "6844": "（案144）潮热咳呛畏寒潮热，咳呛有痰。时或带红，体软脉濡。酌进培补。", "6845": "（案145）吐血肝脾营虚，木亢乘土，内失滋养。心跳时眩，咯血上行，脉来濡弱。拟用培补。", "6846": "（案147）便血便血不止，肝脾阴络内伤，下焦不摄。脉来沉细。拟用温健。", "6847": "（案148）阴亏咳呛咳呛略减，肺阴内亏。肃令不降，脉数右浮。天寒气燥，清金为主。", "6848": "（案149）痰喘失血本患痰喘，肺气自虚，操烦过度，心液内亏，时致失血。天寒气燥，肺金受克。脉右浮数。暂拟清养，参以宣络。", "6849": "（案150）痰喘金水两亏，痰喘之症时发，脉数而浮。阴分有火，拟用滋养。", "6850": "（案152）音哑时邪发热，愈后未清，归于太阳。厥阴木火潜潮，致音哑不咳无度。脉弦略数。厥阴之脉循候，滋养为主。", "6851": "（案153）营液内亏操烦过度，营液内亏，肝脾不滋，虚邪时亢。纳减便溏。营虚不能与卫和，故热胜无汗。营卫出于脾，厥阴之脉与阳维相联络，脉虚弦略数，营虚生热，不宜过于温燥。", "6852": "（案155）腹胀足肿肝肾素亏，微有外感。咳呛有痰，气逆时喘，左胁掣痛，腹胀足肿，左脉弦细，右浮濡。恐其气升多汗，急宜温通。", "6853": "（案156）上闷素体气虚，内风妄动，顽痰上壅，目瞪舌蹇，艰于言语，呼吸尚调，脉亦如常。此系上闷，暂拟开泄。", "6854": "（案158）产后咳呛产后感寒，腹痛便泄已愈。气升咳呛，面浮脉涩。益气为主，参以疏降。", "6855": "（案159）喘咳肺主降气，肾主纳气，气之根在肾。由下焦不摄，上升喘急，近兼咳呛，脉见虚弦。阴阳相为维系，虚则防脱。拟用补纳。", "6856": "（案160）下痢身热下利已减，身热不退，脉来见弦，表阳不充。现感外邪，纳食不旺。酌进调补。", "6857": "（案161）便溏劳乏伤营，畏寒时热。大便溏泄，脉络不舒。益气为主，参以疏泄。", "6858": "（案162）咳喘脉弦而促，弦为木旺，旺则克土；促为气不舒。土不生金，肃令不降。咳痰喘急，甚则呕逆，肺主表，虚则易感，畏寒微热。拟用滋补。", "6859": "（案163）肺热咳呛肺热蒸痰，咳呛时发，痰中带红，两胁掣痛。脉形弦，右数。宜用清降。", "6860": "（案164）肺痈肺胃两虚，土不生金，咳呛淹久，咳痰带腻秽，肺虚成痈。脉濡，神倦，素体劳乏，恐其不支。", "6861": "（案165）阴亏内热目得血而能视。肝肾阴亏，水不制火，心阳时亢，神火有亏，素日操烦，木火内炽，脉数不静。暂拟滋养，后当进补。", "6862": "（案166）头汗头为诸阳之首，湿火上升，气蒸多汗。汗为心液。阳明多汗，太阳卫疏者亦多汗。湿蒸而火炎上，则归巅顶，脉形濡滑。现当燥令，拟用静剂。", "6863": "（案167）喉痒心脾液亏，内失滋养。郁火时炽，喉间作痒，舌根多发红点，心跳时眩。脉络不舒，脉形见涩。养营为主，更须静养。", "6864": "（案168）肝胀土不培木，加之气郁，肝邪时亢，胀而兼痛，大便时溏，心跳腰楚，脉濡而涩。拟用温疏。", "6865": "（案169）痞胀脾虚木亢，宿痞作胀。纳食不安，体软肌削，肢节酸楚，脉濡不弦。久恐腹满，当用温疏。", "6866": "（案170）下痢失血痞胀腹痛，肝脾内伤，微有外感，下痢畏寒。服疏化之剂，遂起失血，痢少减，此属积瘀从络外溢，脉虚弦而细。素体劳乏，两者不能兼顾，酌用培补。", "6867": "（案171）下痢失血下痢不止，咳呛多痰，失血，肝肺络伤，神倦，脉濡，素日劳乏，气不摄营，仍拟培补。", "6868": "（案172）肺痿咳呛淹久，渐致音哑。咳甚呕逆，胃不开纳，脉来濡浮。症属肺痿，恐其加剧，拟以和胃为主。", "6869": "（案173）营卫不和肝郁侮土，中阳不达。营络不和。太阳主表，厥阴之脉与阳维相联络。畏风潮热，卫外之阳不固，营液亦不能充周，虚邪时亢。左脉见弦。益气和营，兼理奇脉。", "6870": "（案174）阴疟中虚作恶，近兼阴疟。少阳之脉贯胃，发则必呕。舌黄而干，外邪未清。调营卫兼泄少阳。", "6871": "（案175）失血阳明络伤，血从外溢，现在已止。胃气中虚，纳食不减，时时作嗳。胸膈时觉气滞，脉形濡涩，舌干少液。气不生阴，久恐成格，拟用温补。", "6872": "（案176）阴亏咳呛右脉弦数而紧，左部虚弦。咳呛不减，肺阴内亏，兼挟郁火。酌进滋养，更须节劳。", "6873": "（案177）血热血热伤营，肤燥发痒，便溏带红，脉濡右数。拟用苦燥。", "6874": "（案178）咳喘肺肾两虚，气不下摄。咳痰喘急，左脉弦数，右濡。拟用滋补。", "6875": "（案179）气阴两亏向患痰喘，现在平复。素体气虚，肝脾失养，营液亦亏，奇脉为病，脉形濡细。拟用滋养，不专治肺。", "6876": "（案181）气阴两虚脾胃中虚，气不生阴。营液亦耗，内失滋养。体软色悴，食不甘味，大便时溏，脉形濡弱。益气为主，兼和营络。", "6877": "（案182）阴疟风寒挟湿，时发阴疟。肝脾不调，左脉濡弱。和营卫兼泻少阳。", "6878": "（案183）痰喘表阳先亏，卫外不固，风寒入肺，痰喘之症时发，脉来濡弱。当用温补。", "6879": "（案185）肿胀命阳下亏，积湿不化。肿胀连囊，兼之咳呛，脉濡细。急切难效，参肾阴法主之。", "6880": "（案186）阴火阴火上越，不能归根，脉形濡而不数。当用消息阴中之阳。", "6881": "（案187）阴火脾胃中虚，气不摄阴，阴火上升，离不交坎。起患梦泄，脉浮濡，不甚数。拟用培补，不宜纯阴之剂。", "6882": "（案188）便溏脱肛肺虚痰喘，有感即发，旧症如此。近因外感寒湿，大便溏泄，时时脱肛。色黄浮肿，脾肾二亏，火不生土，幸脉不弦，拟用温补。", "6883": "（案189）咳呛失血木火烁金，咳呛有痰，络伤失血，时或便溏。脾受木克，肺与大肠亦为表里。畏风时热，微致肌削，脉形濡细。酌进调补。", "6884": "（案190）癃闭素日劳乏，兼挟积湿，气陷下焦，先患便浊，现浊止而患癃闭，少腹作胀，太阳气化无权，脉滑大而数。益气化湿，参滋肾法。", "6885": "（案191）阴疟阴疟淹久，肝阴内亏，木亢侮土，脘次结痞。现疟止而寒热间作，营卫二虚，少阳之脉与厥阴相联络。营虚不和，中气亦弱。咳呛失血，肝肺络伤。脉濡，左略弦。拟用调养。", "6886": "（案192）产后腹泄产后营虚，肝脾失养。气滞不达，腹痛便泄，腰节酸楚，心跳头眩，脉濡细。当用温疏。", "6887": "（案194）咳呛胁痛咳呛胁痛，脘次不舒。肝阴内亏，气不得达。木火乘金，脉数而弦。久恐成怯。", "6888": "（案195）汗多表虚多汗，兼患便血，肌削脉弦，急切难效。", "6889": "（案196）疟疟久伤营，木火内动，肝脾失养，大便带红，脉弦而大。和营为主，参一小柴胡法。", "6890": "（案197）产后泄泻产后十朝，外感寒邪，腹痛便泄，色黄，脉略浮涩。拟温理下焦。", "6891": "（案198）便溏长夏暑湿起患便溏，时有寒热淹久不止。冬天气寒，脾阳先虚，土不培木肝阴亦弱，侮土，时胀，泄仍未止。日内寒热加剧，纳食少减。舌不甘味，脉濡涩不数。培中为主，兼和营卫，胃气能旺，更得春阳之助，可冀渐复。", "6892": "（案199）痰呛脾胃气虚，湿痰作呛，甚则喘急，有感即发，脉大而濡，并不弦急。拟用益气。", "6893": "（案200）失血络伤失血，连次作呛，胁痛。左脉见弦，右濡不数。从肝胃滋养，参以理肺。", "6894": "（案201）发热风寒外感，咳呛身热，微觉胁痛，现咳止而热仍不退，神昏谵语，循衣摸床，左脉弦大，右较细数，舌苔腻白，时带灰。中焦阻滞，表邪亦未解。渴不索饮，邪归阳明，尚未化热，素体劳乏，正不胜邪。恐其风动发厥，拟用散而兼疏。", "6895": "得汗后热仍不解，神昏谵语，舌干唇燥，脉弦而数。阳明里症渐入少阳。津液被烁，恐其内陷，未为稳境。仍拟疏散，参用化热。", "6896": "（案202）呕逆脾胃中虚，气阻呕逆，或酸或苦，脉来弦滑。旧恐成格，当用温理。", "6897": "（案203）肝郁咳呛肝郁气滞，木邪乘金，兼感外风，肺虚咳呛，入夜多汗，时觉腹痛，脉弦而数，肝肺兼理。", "6898": "（案204）肺虚痰喘痰喘略平，肺气本虚，肃令不降，脉形濡弱。酌进调补。", "6899": "（案205）脘胀气郁伤肝，木邪偏亢，侮土作胀，纳减味不甘，舌干少液，脉弦而涩。拟用调养。", "6900": "（案206）产后腹泄产后失调，脾虚木亢，腹痛便泄，脉来濡涩。拟从下焦温理，兼理奇脉。", "6901": "（案207）腹痛腹痛中痞，痛自腰连脊，归于左偏，脉络不舒，肌削脉濡。拟用温宣。", "6902": "（案208）潮热咳红潮热淹久，畏寒微汗，咳痰带红，脉来濡弱。从肝脾兼理。", "6903": "（案209）阴虚咳呛真阴下亏，火旺烁金，咳呛淹久，脉左弦，右数。拟用滋养。", "6904": "（案210）营亏火升营液内亏，肝脾失养，木火上升，心跳时眩，筋脉不舒，脉数略弦。拟用柔剂。", "6905": "（案211）失血阳明络伤，血从外溢，微有咳呛，脉弦而数。宜用宣理。", "6906": "（案212）咳喘肺感风寒，咳痰喘急，有感即发，脉濡而数。当用疏降。", "6907": "（案214）津亏咳喘咳呛有痰，气升喘急。肺肾二亏，金不生水。津液内亏，舌干生糜，脉不弦大，可无汗脱之虞。拟从下焦滋补。", "6908": "（案215）下血粪后下血，肛门作痛，脉大而弦。养脾阴兼理阳明。", "6909": "（案3）经下颇多，心烦口渴，阴亏阳亢也，诊六脉不静。议以滋养。", "6910": "（案5）肝强脾弱，胸腹作胀，癸水不行，脉来细软。理宜调气和血。", "6911": "（案7）阴虚内热，经漏淋漓。仿仲景复脉法。", "6912": "（案8）产后结瘕，少腹胀痛，此属肝肾络虚，非有形所阻。况自汗屡泄，六脉无力，岂可投以攻剂？理宜疏通为要。", "6913": "（案11）中虚肝郁，腹胀食减，色脉少神。仿逍遥法。", "6914": "（案12）脾胃中虚，血多气少，土不培木，肝邪郁滞，结瘕少腹，发则上升，胀而兼痛，犯胃则呕，味多带酸，脉濡涩不弦。当用温疏。又发时腰脊酸楚，此产后失调，兼涉奇脉。当于平时调补。", "6915": "（案13）血不养肝，木亢侮土，素体如是。外感寒湿，胎前下痢，产后不止，中气已虚，兼受木克，腹胀时痛，津不上承，口干唇燥，舌黄而干。左脉促而弦，右大而濡。虚中挟实，攻补两难。拟用温剂。", "6916": "（案14）脾统血，肝藏血，奇脉统于肝肾。而脾为枢纽，冲主血，任主妊，中气旺则足以摄营。中虚有火，舌光脱液，津液不上承，微觉腰楚，左脉数动，右大略弦。拟方专主培补。", "6917": "（案15）肝脏脾胃主不和，积湿蒸热，中气不达，郁火时升，脉形濡数，左略弦。仍拟疏泄，未宜腻补。", "6918": "（案16）腰楚带下，带脉病也，筋掣而腹中引痛，任脉病也，水不滋木，邪亢侮土，脾胃素虚，受侮益弱，脘腹作痛，微觉坚实，筋脉酸楚，舌光脱液，肝主筋，血少则失养。按脉，右部濡弱，中虚也；左亦濡而不弦，知肝无藏血。腹胀亦属虚邪，气液并耗，调摄为难，姑拟柔剂。", "6919": "（案17）包络如海，冲脉如江河，通行血络者也。肝脾内亏，冲脉失调，心悸属营虚，腹胀属肝气，头眩耳鸣属厥阴，少阴风火上升，经到则络空，故见诸症耳，拟用滋摄。", "6920": "（案18）产后失调，淹久未复，肝脾之阴皆血，血少则不足以充肌肤，色悴而燥，脉见虚弦。土得润泽，木能发荣，拟进滋补。", "6921": "（案19）症由产后血之事也，起患肿胀，脾土根于命阳，肾为水脏，阳弱则阴翳不消，现在胃纳已开，肿退未净，右脉尚见浮大。仍当扶肾阳以生脾土，壮脾气以统营血，肝木托根于土，土厚则木荣。温健为主，参用调营之品，春和可渐复矣。", "6922": "（案21）产后营虚，先患手指麻木，渐至二足酸楚，自足以上连及二胁，一筋牵掣，有触即痛，艰于举动，二胁皆然。淹至年余，服纯补之剂不效。夫气与血，流行者也。血非气则壅，气非血亦滞。今非纯虚，不相和也。肝藏血，主筋，行经之血有余，荣筋之血不足，乃气滞而不能为之充布也。此症重则为筋极，亦或延而为痿。脉弦略数，观神色未为痿顿，胃气亦尚可支。阳明为百络之长，血之所由生也，胃旺则肝木亦和。拟方以温宣为主，此避实击虚之法。", "6923": "（案22）产后失调，土不生金，虚则肿，咳痰气升，宿痞时胀，荣虚本亢，脉来见涩。清高原兼培中州。", "6924": "（案23）产后作肿，退而复发，举动喘急，脉来濡涩。肺虚则高原不行，脾虚则堤防不固，肾为水脏，真阳下衰，泛滥无制。恐其上升，急宜温纳。", "6925": "（案24）产后失调，营虚气陷，少腹时胀，小便淋沥，症属太阳，而其部归厥阴。色黄而浮，此系营分湿热，脉濡而涩，养营为主。仍拟通利，以佐气化。", "6926": "（案2）恶寒发热，头痛身疼，脘闷无汗，脉来弦紧。乃卫阳疏而风邪外袭，例用辛温解表。", "6927": "（案4）邪伤阳经，形寒身热，头疼脘闷，舌白脉紧。先宜汗解为要。", "6928": "（案5）素体发热，头胀胸闷，舌布白苔，脉来弦劲。邪势郁于气分，不汗化达，宜疏解法，侯政", "6929": "覆：得汗之后，邪势不解，烦渴少寐，脉数舌干。伏邪未清，津液养伤，法当先宜清解为要。", "6930": "（案7）湿热伤阴，舌红脉数。仿玉女煎法。", "6931": "（案9）湿邪内陷，四肢厥逆，想热深厥亦深也。顷诊六脉沉数，谵语神昏，大便三候不解，乃病久元虚，邪归胃腑，甚为辣手重疾，勉拟陶氏黄龙汤法。以图幸攻。附方政用", "6932": "（案10）冬温乘阳虚而发，身热不得汗解，脘闷咳逆，舌白脉弦。邪郁表分，尚未施张，法当治以辛散。", "6933": "（案11）暑湿伤其气分，脘闷腹痛，上吐下泻，四肢厥冷，舌腻脉微。此霍乱之候，理用正气法。", "6934": "（案13）暑风伤肺，发热汗少，头胀咳呛，舌布白苔。脉左弦数。此属闭暑之候，姑拟辛解。", "6935": "（案15）脉弦数，暮热朝凉，汗解渴饮。治从少阳。", "6936": "（案17）症属湿温，起十余日，斑点已见，身热不退，神昏谵语，时见痉象。兼之呃逆，舌不能伸，腻白而渴，大便闭结。表未达而腑气亦未通。脉左濡浮，右涩，不甚数。凡斑皆湿热蒸郁而成。既见而热不退，逆境也。姑拟此方，以专进之。", "6937": "又得解后，身热未净，仍有谵语，舌苔薄白中焦，素日劳乏，心营本亏，脉左略弦，右大而不摄。邪轻而正不能复，当用滋养。", "6938": "（案19）风邪化热郁于太阳，阳明身热，咳呛，唇燥而肿，脉形浮濡。拟用清泄。", "6939": "（案20）素体中虚，近感暑湿，中焦阻滞，起患寒热，经旬不退，甚则呕逆，舌光而干，饮不解渴，肢节酸楚，时或谵语，三阳俱见，邪郁尚未透达，胸闷不舒，食冷则不安，此非实热，其舌光亦非阴亏，由中阻气不上乘也，左脉见弦。拟用疏中，参以泄表，加人参以助气机。", "6940": "（案21）暑湿侵脾，蒸郁成热，中阳不运，气不达邪，体软色黄，四肢不能运动，身热淹久，汗出发疹，仍不退凉。舌薄白而大，右脉浮大而濡，左大而不弦，热甚见数。此中焦内闭之象，湿伤脾，伤其气也，暑亦伤气，拟以益气为主，参以疏化。", "6941": "（案22）暑伤气，湿伤脾，暑为阴邪，湿亦属阴，蒸郁日久，中阳被遏，身热见疹，色黄体软，右脉浮大少力，左部亦滞。外蒸之象，皆浮而实，则中寒不运。急宜益气，佐以辛温。", "6942": "（案23）暑湿蒸热，红白疹，俱郁邪未清，归于阳明少阳，热在肌表，中阻而外亦不解，脉数见弦。不可更散，解肌，参用清泄。", "6943": "（案24）暑湿之邪，蒸郁成热，由阳明渐入少阳，身热不退，疹见未透，脘次痞结，时或谵语，而津液渐亏，舌光脱，脉弦细，右数，恐入厥阴，见昏厥等象。拟用养阴，参以疏化。", "6944": "（案25）病属湿温，郁火蒸热，邪由阳明归于少阳，逼入厥阴血分，神昏谵语，舌绛根黄，疹点已见，身热不退，咽痛咳血，右脉数而有力，左大略濡，津液已亏，恐风动见厥。姑拟清泄。", "6945": "（案26）风温上受，肺气不宣，咳呛音哑，喉痛，头晕，脉弦，舌白尖红。法当化邪清金。", "6946": "（案27）暑温挟湿，投辛散，邪未除净，蕴久，阴分受损，寒起背肢，热从心炽，久咳痰腻，命门火衰，肺失升降之权，脉数，舌白尖红。法当和阴潜阳，兼理清化。", "6947": "（案1）肝胆郁热，扰乱神明，时发多言妄笑，脉来弦劲。拟用苦泄柔镇，接服养肝清心法。", "6948": "（案4）肌肤燥裂，六脉弦数，血热外游。治以滋补。", "6949": "（案6）久患溺血，气不摄阴。禀体本虚，近感暑邪。身热多汗，舌红作渴。右脉浮濡，左较细，并无数象。古人治暑未有不用补者。拟方酌进，参清暑益气法。", "6950": "（案7）肝主筋，肾主骨。其阴内亏，失于滋养。脉络不调，时或酸楚，现当夏令，脉细不甚数。拟用滋补。", "6951": "（案8）肝阴内亏，少阳火郁，潮热淹久，时吐涎痰，脉形浮数，左略弦。参逍遥法。", "6952": "（案9）血虚生热，热生风。长夏湿蒸，风湿皆归营分，多发㾦瘰。脾主肌肉，肺主皮毛，仅在外形及筋脉。此症尚浅，拟方以养营为主。丸方：", "6953": "（案10）真阴内亏，水不制火，郁热内蒸，肛漏溃脓，肢节酸楚，脉数略弦。拟用滋养。", "6954": "（案12）营阴素亏，少阳真气亦弱，虚痰结瘿，聚于颔下，舌干，少阴虚火不潜，脉形濡细。拟用柔剂滋补。", "6955": "（案13）气与血斗，血虚者多寒，此症血多于气，有时作颤，但寒不热，脉形细。以益气为主。", "6956": "（案15）气泛少腹，上冲至心，此属肾邪，名奔豚。惟真阴素亏，舌红脱液，左关尺脉弦大不摄。拟用温纳之法。更须静养为妙。", "6957": "（案16）奇脉皆统于肝肾，肾虚则水不生木，肝木不荣，内失滋培，诸脉皆病矣。肾为水精所藏也。气生精，精化气，阴非阳不生，肝为木，相火所寄也。必得春温之气，方能萌蘖。故治肾当补阴中之阳，然后火不上越，元海归根；治肝当补血中之气，然后土不受克，中州镇定。脉平时渐见冲和气。动则弦，总带涩象，拟方政用", "6958": "（案18）肝肾阴亏，少阳虚火蒸痰结疬，发于二项，前曾失血，渐有咳呛，脉浮濡，不甚数。总属于虚，酌进培补。", "6959": "（案19）黄为中央之土正色，脾虚挟湿，真色外现，不甚鲜明，此为阴黄。中无热象，脉左弦，右濡涩。久恐中满，拟用温泄。", "6960": "（案21）血不胜湿，流及脉络，多发湿疮，脉形见数。凉血为主，参用苦燥。", "6961": "（案23）积湿入络，归于营分，肢节发瘰，脉弦略数。拟用疏理。", "6962": "（案25）积湿下注，足胫发瘰，脉来略弦。参用益气，使之下达。", "6963": "（案27）湿邪未清，脾虚不胜。其流滞于脉络者，半已结痂。气旺则复，酌进培补。", "6964": "（案28）伏暑挟湿挟滞，身热，咽喉渐痛，口腻作恶，目黄溲热，大便色黑，素有鼻衄之患，昨今两日，衄血甚多，舌干苔糙，脉来弦数，近七至，夜不成寐。邪滞化火扰荣，症势非轻，慎防变幻。方侯正之", "6965": "（案2）脾肾阳衰，纳谷不运，脉来沉细。近乎格矣。", "6966": "（案3）纳食梗塞，大便艰难，脉来软弱无力。此系积劳内伤，阳结于上，阴凝于下。是为关格之渐。姑拟温疏，以图幸功。", "6967": "（案5）胃中阳虚，纳食难化。阻于下口，下不通则返乎上，时或攻冲，肌削色悴。胃阳为气，胃之阴为汁。气弱而汁亦槁，恐其成络。脉涩而濡。拟用温润。", "6968": "（案1）阴虚内热，肠红脉数。", "6969": "（案6）凡痔皆由肝肾阴亏，下不能摄，而其部则归于手阳明大肠。阳明属干金，现交燥令，火旺则烁金，水不能制。其脱属虚，其胀属热，脉来浮大。当滋补。", "6970": "（案7）肾主二便，胃关在肾，膀胱气化，亦由命火。肾阴先虚，气陷下焦，肛痔不收，小便时闭，神倦色黄，脉来浮濡。补纳为主。", "6971": "（案8）肾、命二虚，气不摄阴。肛痔时发，腰节酸楚，脉虚弦不静。肝、脾之阴皆血，阴络伤则下行。拟用填补。", "6972": "（案1）两足酸软，六脉浮数无力，症属骨痿，由阴虚内热所致。宗虎潜法。", "6973": "（案2）此筋痿候也，由厥阴郁热所致。诊左脉弦数。宜清营热以疏筋。", "6974": "（案5）四肢不用，脉沉少力，脾肾虚寒也。急宜温补。", "6975": "（案8）肝肾阴亏，筋脉失养。右足酸楚，脉形濡弱，恐其成痿。精不足者，填之以味。", "6976": "（案3）阴虚挟湿，两足肿痛。六脉弦数，病势非轻。", "6977": "（案5）下体痹痛，脉来细软。此属水中无火，法当温补。", "6978": "（案7）膻中无阳，气阻上焦。胸膈作痛，此属气痹。右脉濡细，左略滑。培中为主，佐以辛温。", "6979": "（案8）气痹即胸痹也。膻中无阳，上焦不运。脘次作痛，连及于背。脉形濡细。静为阴，气聚而痛；动为阳，散而痛止。拟培中阳，参用宣络。", "6980": "（案9）肝肾阴亏，初冬患恙。尚未全复，入春感风兼寒，咳呛潮热，咯痰带血，近更咽痛，厥、少二阴之脉循喉。咳则气升，阴火随动。右脉弦而略数，左部濡。久恐延成喉痹。不宜过于清润，酌进养阴，平时更须静摄。", "6981": "（案10）脾胃气虚，痰湿素积，入夏外感暑湿郁蒸，发热随起，咽痛，近入厥阴之络。两足酸楚，艰于举动。肤色及目俱黄。此属湿热，左脉略弦，右较大，重按见涩。恐其成痹，姑拟轻剂宣理。", "6982": "（案2）金不生水，津液两亏，三消之症也已具。脉大而濡。专主滋补。", "6983": "（案3）劳乏内伤，气不生阴，体软色黄，消渴引饮，脉形弦紧。益气为主。", "6984": "（案1）阳下交阴，寤不成寐，饮食日减，脉来弦数。暂用半夏泻心法。", "6985": "（案3）心烦头晕，寤不成寐，五火内炽也。诊左脉弦大。治以苦泄。", "6986": "（案4）营液内亏，血不养肝，木火烁金，咳呛音哑。肝藏血，血少则外不能与卫和，故潮热。夜寤则魂藏于肝阴，虚火旺，魂不安矣，故少寐。而神或惝恍，色黄肌削，脉濡不甚数。现当夏令，恐其加剧，拟静滋摄。", "6987": "（案5）向患梦泻去精，过入夏来时热之后，至今不能寐，心跳不安。心藏神，肝藏魂，夜卧则魂藏于肝，离坎不交，阳弱而阴无所丽，脉形濡弱。法当以阳引阴，姑拟数味，以觇进止。", "6988": "（案1）痫频发，心悸脉数。由肝郁气乱使然。先清后补。", "6989": "（案2）肝胆郁热，膈张神昏，六脉弦紧。惟恐痫厥。", "6990": "（案3）素体气虚，脾胃不足，自因心悸，心胆虚怯，近乎痫症。由阳亏阴盛，脾窍不灵，中枢不能健运。脉虚弱。拟用通阳。", "6991": "（案4）脾阳虚而心营亦耗，时或神昏，近痫症之象，脉来濡涩。培补为主，参用开泄。", "6992": "（案1）脾阳中虚，兼受木克，脘次作胀，时有寒热，色黄脉弦。恐其中满。", "6993": "（案2）暑邪挟湿，脘次作胀，右脉见紧。当用疏化。", "6994": "（案3）脘次结痛，连及腰脊。肝郁侮土，兼入奇脉，素体多湿，脉来弦紧，右涩。拟用温宣。", "6995": "（案4）素患脱肛，系气阴两亏，下不能摄。近兼脘次作痛，服药后，中焦通而渐及下焦。其为厥阴气滞无疑。脉右尚和，左部略见弦象。拟从下焦滋纳。", "6996": "（案5）胃为艮土，土受木克，脘次作痛，甚则呕逆。时发时止，此次较前为剧。脘满作痛，食入即呕，呕多痰稠，此胃汁也。现差平复，惟中闷少纳。大便坚结，胃阳虚而阴亦耗矣。右脉濡涩，左虚弦，少冲和之象。急宜培补温润为主，佐以辛甘。", "6997": "（案6）木郁气滞，脘腹作痛，连及胁背，所谓肝痛无定处也。脉来见弦。宣络为主。", "6998": "（案7）胃阳中虚，虚则多寒，脘痛呕酸，积年已久，曾经吐瘀二次。胃主纳而化在脾，木托根于土，土衰则邪亢，而必致侮中。右脉濡弱无力。中年不应火衰，皆寒湿所伤耳。拟用温补。", "6999": "（案12）胃痛食减，脉来细软，中阳失运也。治以温通。", "7000": "（案2）腹痛脉微，阳气衰也。法当温理。", "7001": "（案8）肝肾阴亏，下焦不摄。向患肛痔，近兼腹痛。此肝木失养，厥阴气滞所致。脉来弦细，当用温纳。", "7002": "（案10）绕脐腹痛，时或便泄。下焦为厥阴之部，而腹又任脉所系。寒湿滞气，木郁不达。脉左弦细，右涩。拟用温疏。", "7003": "（案11）素体心形并劳，脾阳先亏，气从下陷，外受暑，腹痛便溏，兼之脱肛，色黄而浮，脉形濡弱不振。拟补火生土，清升则浊自降。", "7004": "（案12）厥阴气滞，专归下焦，绕脐腹痛，脉数略弦，此木邪归于本部而不侮土者。拟用宣达。", "7005": "（案2）腰痛脉虚，肾阳不足也。当用温补。", "7006": "（案5）暑风蒸热，归于阳明少阳之部。头痛右偏，目亦而小，脉形浮濡。拟用轻剂凉泄。", "7007": "肝主风，巽之象也。脾虚则土弱，营液少则失养。外风牵引内风随动，脉来濡涩。拟方培补，常服取效。", "7008": "（案7）肾为坎，肝为巽。坎水滋木，虚则木失养而风火妄动，外风引之，头风时发，连及脉络则肢节酸麻。左脉弦细，尺脉右浮大而濡。此方拟用宣泄。", "7009": "（案8）血不养肝，邪亢侮中，脘次时发胀，现在平复，惟冲脉失调，时或衍期，风动头痛，脉来弦细而紧，营不贯于中也。拟用滋养。", "7010": "（案1）头晕脉滑，内风挟痰也。肝胃同治。", "7011": "（案3）头晕耳鸣，六脉弦滑，乃肝火挟湿兼痰为患。先清后补。", "7012": "（案6）头晕自汗，六脉弦软，此阳不恋阴也。法当培补。", "7013": "（案7）烦劳头晕，六脉软细。此属水不涵木，厥阴化风。当从肝肾图治。", "7014": "（案8）心生血，血为离火所化，非温不生，血少则肝失养而胆亦怯，左脉虚弦。营不贯于中也。仍参养营法。", "7015": "（案10）肝阴内亏，虚风上扰，时发胸膈不舒，脉见虚弦。内风之动必因外风。此症难许脱根，平日当以养营为主。", "7016": "（案11）肝脾二虚，气弱则顽痰不化，虚风妄动，眩晕发厥，随时发作，脉濡涩，中无实火。培土为主，参用开泄。", "7017": "（案12）土不培木，肝风易动，气滞则厥，时或眩晕，脉来濡细，左部见弦。平时当滋补肝肾之阴。", "7018": "（案3）脾胃气虚，痰湿中积。土薄则木不营，入春以来，虚风易动，时觉耳鸣，脉来浮大，左寸略弦。拟用培补。", "7019": "（案4）气虚多痰，近兼湿火上升，左耳时鸣。湿属脾，火属少阳。脉和。拟方专主清降。", "7020": "（案5）脾虚多湿，木旺动风，风扰湿则上升，左耳时鸣，耳后微觉牵掣，此属少阳之络，脉涩，左略弦。从肝脾补摄。", "7021": "（案7）肝肾阴亏，木火上升，络热蒸痰，结核溃脓，右耳出水，头额多汗，左脉弦数，右略浮现。夏令积湿，亦能蒸热。仍拟滋补。", "7022": "（案3）头晕鼻衄，脉来弦数。水亏火旺也。治宜育阴潜阳。", "7023": "（案5）鼻衄大发，六脉弦数。由阴亏阳亢所致。", "7024": "（案6）胆热积脑，鼻流秽涕，脉弦数。治以辛凉。", "7025": "（案8）风燥化热，从肺入脑。咳呛有痰，时或带血，左鼻涕带绿色，脉涩不甚数，素体劳乏。姑拟清泄。", "7026": "（案10）肝肾阴亏，阴火上升，脑热则流秽涕，脉数而弦，专从下焦滋摄。", "7027": "（案11）阴亏火升，时患鼻渊，脑热也。脉浮数而动。当从肝肾滋摄。", "7028": "（案12）肺开窍于鼻，鼻通天气，火旺则烁金，肺热鼻塞，脉左弦。阴分本亏，拟用培补。", "7029": "（案13）脾阴内亏，湿火上升于头，鼻渊痰热，郁于上膈，脉数而弦。养营为主，兼清脾肺。", "7030": "（案14）肝阴内亏，鼻衄时发，脉形濡细。当用培补。", "7031": "（案1）咽痛失音，咳痰不爽，左脉弦紧。木火刑金也。仿仲景法。", "7032": "（案8）暑湿蒸热，咽喉微痛，久而津液被劫，进而兼腐，难于下咽，近乎喉痹，右脉濡数。气阴并亏，急切难效。", "7033": "（案2）牙痛口干，脉来弦数，水亏火动也。拟与滋养。", "7034": "（案3）齿龈及下唇均属阳明，热则动血，右脉数大。当养阴为主，水足制火，则营络自清。", "7035": "（案4）木火上升，必在寅卯二时。今又值寅卯之月，春令渐旺。营液素亏，内失滋养。少阳之脉贯胃，阳明发热，或受外风，齿龈出血。此方专主清泄。", "7036": "（案5）血不归经，在阳明则为牙宣、肠红，入太阳则为尿血。由气弱不能通摄也。二足酸软，兼挟微湿，脉大而略弦。补气为主。", "7037": "（案8）木郁侮土，脾胀时痛，浮阳上升，齿痛咽塞，奇脉为痛，脉形濡细。拟柔剂滋补。", "7038": "（案2）大便闭结，脉来沉迟，下焦阳气失运化也。治以温润。", "7039": "（案4）肾为水脏，膀胱为阳水，少腹以下为厥阴之部。水中火动，下不能摄，相火寄专，尿道有阻，脉弦，右涩。滋补为主。", "7040": "（案5）肾气本虚，阴无由化，下焦管摄无权。太阳气化亦由肾主，虚则通塞不常，小便癃闭，现当夏令，未免暑伤。脉濡右略细。肺肾并理，益气生阴。", "7041": "（案6）素体劳乏，气陷下焦，水道召阻，脉形濡细。益气为主。", "7042": "（案2）睪丸为肾之外候，下焦虚寒，厥阴气滞，渐致胀大，并无痛楚，脉濡细。拟用温疏。", "7043": "（案3）肝肾本虚，寒滞下焦，童年起患狐疝，时上时下，时或作痛，脉来濡细。温疏为主。", "7044": "（案2）阳气素虚，中气虚则痰湿日积，表气虚则卫不固而多汗，素体如此。兹因外感风邪，郁久化热，由阳明传及少阳，渐次入里，但热不寒，入夜为甚。自汗，阳明本症也。谵语为阳明里症。耳鸣为少阳里症。邪已去表，故不头痛，恐其伤厥阴，致见昏厥之象。右脉尚和，左脉大而见浮，知为风热无疑。", "7045": "热势已退，所有余邪可用淡渗从小便出，不必清矣，转过清恐碍胃。惟脾胃本虚，多痰多湿，邪退之后，正气未能骤复，加之表虚，际此炎令，天气郁蒸，汗多不止，自当酌进培补，峻补又恐壅气，脉浮迟而濡，拟六君法益气，参用和阴，冀胃纳渐增，夜得安寐，日就平复矣。", "7046": "（案3）脾阳中虚，表气亦弱，盗汗过多，外不能固，神倦脉濡。专主滋补。", "7047": "（案4）脾胃气虚，气即火也，虚则阳弱。脾阳根于命火，表阳根于中气。症患嘈杂，善饥，腹坚，气随火升，发则肤胀，多汗，四末不举，皆阴盛而阳不能运也，脉涩而弦。治法宜补不宜攻，宜温不宜凉，拟方培进。", "7048": "（案5）营液内亏，郁火时升，潮热召汗，色赤发瘰，脉形浮数，兼之咳呛。从肝肺胃三经清理。", "7049": "龙光幼从庭训专心制艺兼习算学均未能入室登堂造乎极地二十七岁患阳虚弱症咳嗽痰多神疲食少肌肤瘦削举步维艰历经名手调治芩连清热参术补虚方药杂投病势日剧亲戚朋友皆为予危适吾家又有病感者敦请一世交前辈诊视而前辈故意留难百端推托龙因忿而矢志习医思利己以利人必不蹈时医恶习也遇同学王吟江先生精通医术阅书既广求理亦深为开书单指以门径龙乃照单购办诵习讲求注伤寒者阅视二十余家逐条比校择其精当者另为摘录若金匮则专论杂证者也夫杂证亦有六经表里之辨凡论杂症须从伤寒条例分经施治方能得当而伤寒论中所不能包者仲景乃著金匮以补之故金匮之文多片言居要索解最难后世就金匮而谭金匮语非隔膜即属支离古今注金匮者卒鲜善本江西喻嘉言医门法律辨论病情深入显出妙义环生实金匮之功臣也医有三大法门一为伤寒六经病一为金匮之杂症一为叶氏之温病伤寒杂症由仲景入手下及刘李朱张历朝名家专集比拟考求自能发明其理若温病有内伏有外受前贤议论多未得当即喻嘉言黄元御亦未能透澈此关椎叶天士王士雄阐发经文独树一帜温热经纬一书极为简明精当若能时时参究亦思过半矣然龙读书十余年关书数十种辨别病情参详脉理抚躬自问业已殚尽心力而于临症时凭脉辨症尚未能一一了然乃知人之病证变化万端方书所论一证仅就一证而言不能穷其变化因思此非明师益友随症指点不能尽其神妙不测之奥乃在左近名医处留心考察实存私淑于人之心孰意负盛名者竟鲜其实类皆拘守套方以药试病孰能见理明决预定病势之吉凶先言愈期之早暮哉而所以得时名者有三术焉一则见病势稍重便有防变推托之辞为日后愈则居功变则诿过之地步此其一也一则专选平淡和平之药动曰为某某汤头所加减以博稳当之名可告无罪于天下此其二也一则和颜悦色温语婉词动效奴仆之称求媚于妇女庸愚之辈使至死不悟此其三也得此三术众口揄扬而成名医之身价矣举世悠悠孰分泾渭而我辈欲求明师益友安可得哉思索再三翻然有得曰与其求师于此辈仍不如效法于古人因添购医书广搜医案见李东垣汪石山陆养愚孙一奎等著述辨症精详应变神妙分真伪于毫厘之际显神效于广座之前数语破的可以释无限疑团是皆名师之指示也即见闻之阅历也龙又参究数年略开会悟然终不敢自信若得明哲之口传当更有甚于此者但见闻既陋限于偏隅因筹一法焉将历来诊治之病除寻常不录外凡病势危剧或病情隐晦其设法救转真救之不转者略刻数十条举以问世徜有学问深纯见识明敏指我之疵破我之惑一一批出加以案语由邮局奇赠鄙处龙则束装就教拜列门墙若路途辽远有愿难偿亦必馨香祝之奉为师表不胜幸甚士君子毋以不材见弃置之不论不拟之条则所赐多矣存心如此同志览诸", "7050": "我中国医学精深广大见理之真似胜西人医学而今日凌夷甚矣非医学不善也由于行医者多非其人亦由于习医者不得其法学者肄业之初必须由浅而深由外而内先明躯壳之血脉经络而后推及于脏腑知脏腑之功能测气血之行度能识未病时之形状始能得已病时之真情此入手工夫最为切实者也中国剖割不行无从实验方书所载躯壳脏腑等件均模糊无线之词即古人选本所云浅近者又皆按症略载数语将病之曲折隐微虚实寒热名贤辨别之处精当之理概行删去有如经验良方于人之形体病之浅深又无一语论及故中国医学绝少入门考据之书以开其智慧此惟西医论之既详且尽入手之功夫须让西人独步既由外而推内复验实而攻虚学者有形迹可求步步皆有准的及入理既深凭脉辨症推测病情则中医较胜吾故曰西医为前半功夫中医为后半功夫彼此皆不可厚非尝见人涉猎西书识得药水便极力表彰西学诽谤中医此等人非特不知中学之浅深亦并不知西学之浅深也", "7051": "凡病分两种一曰客感一曰杂症客感中虽伤寒温热不同而温病之理仍具于仲景伤寒之内苟能参究伤寒之六经豚证辨别表里之寒热虚实再读叶天士所论温热诸集便能洞澈了然惟杂症一门最难种类纷繁变动莫测金匮一书既未全备且论症又甚简略其除精深之理散见于先贤专集之中就中风一症言刘李朱张认症不同言理各别学者根柢未深断不能折衰一是转致目眩心迷茫无把握世人往往抱一家之言以为主宰或攻或补或凉或温喜攻者遇虚症亦攻喜补者遇实症亦补喜凉喜温者亦不审症之阴阳概以素所执持者窃试阅历未深胶于成见误人而不自知误治而不能改俗云熟读王叔和不如临症多此乃世医欺人之语非确论也心中无此理解即临症百千仍属茫然不悟所以多读名贤专集为第一义又千金方外台秘要证准治绳等书兼收博采搜罗富有实医学之大观然所载方药汤头最为广博而古人辨论之处转略而不详其专论脉症而不及方注者如巢氏病源等书则条目太繁语少厄要亦非善本现为后人医学计须仿外台准绳体例专集前贤论说及医案中议症之词为之平情判断加以案语录其所长删其朋短辨其同异序其浅深或会通焉或井存焉令学者一目了然循序渐进人人皆可自底于成则中国名手自不乏人余存此志久矣而学识尚浅力有未逮惟有望于世之同志者", "7052": "古者名手治病均能预断吉凶其无病者每戒以死期其重病者每告以愈期其言无不应验有若神明此非通术数之学预卜先知乃由脉症中参详而出的当无疑确不可易其理讲明却平淡无奇妇孺皆能解识也今人无此学问一见病之重者便推托张皇故作惊人之语以为诿过地步若遇脏气已离未见于外者则茫然不觉漫为开方未逾多日而所言危者安矣所言安者死矣人见医者之言多不可凭则不凭于医而凭于命以为医能医病不能医命也若间有学术稍深独具只眼者人亦以寻常视之不知其为庸中矫矫也且若而入者不肯苟就不屑逢迎不为利动不为势屈多有不同流俗之处人见其行藏独异事少圆通转不免众口之讥评矣此亦医学不明泾渭不分之故也", "7053": "古者名手治病全凭望闻问切以为准绳若切脉而不问又无所见断然不能认症伤寒论中浮数脉见于汗前则为实见于汗后则为虚汗前汗后不问为能得知素有痞结不得发汗素有动气不得用下素日旧疾不问又焉得知闻呼吸呻吟始知寒热见气色神形始知吉凶则是一病当前非目见耳闻口问手诊四事合参虽歧黄复生亦不能辨认今之时医挟欺人之术禁病人开口自许切脉便能知症略言一二却能与病相符病家亦遂以此试医家手段甚至富贵妇女有病蔽以帐幔只伸两手任医家切脉病情则使仆妇略为告知讵知此等诊法仲景为医家之圣亦不能洞见病情期其必效凡切脉便能知症者知其外不知其内知其粗不知其精按脉之浮沈迟数便知表里诸症之大略肌润则知有汗肌燥则知无汗面赤则知有热面黄则知多湿眉常绉蹙则知头痛喉有动气则知咳嗽腰常下曲则知腹痛凡由推测而知者笔难尽述皆无关于病之实际者也仅能动庸愚之耳目耳故曰此乃欺世欺人之术也如医家不肯问病家不肯言则自误误人将以人命为尝试也世人戒之", "7054": "丁酉年四月有蔡姓父子开杂货铺于郡城内其子二十余岁素有腿患发则针刺紫筋数处出血便瘥此次刺而不应针眼翻开如翻花状逾二日大发寒热请医诊治服九味羌活汤两帖热势加重易医而用银翘散加桑白皮等又服两帖则势转危笃举室仓皇病者之叔岳萧佑廷余契友也为迓予治入室见病巳热极离床二三尺便觉热气袭人神昏躁扰舌向唇外铦咂所异者满面红光油积一二分许以白纸拂拭满纸皆油若自油内拽出者然小便六日不解大便则日夜百数十次始而粪继而水继而皆白沫左腿上有大白水泡百余根盘皆红左膀微有润气余均干热而燥脉皆洪大而数右寸尤甚诊毕问起病之由及所服之药此等重症会未闻见书亦无考独坐沉思约一时许乃忽悟曰此本伏邪温症热积下焦已久得九味羌活汤温升重剂鼓动积热上升胸膈适当其冲故心肺如焚势成焦痿后服桑白皮枳壳等重伤肺气肺热无处宣泄其上半身之真精由肺逼而上出于面故面有油积其下半身之津液由肺逼而下出于腿肺主皮毛且肺在右气行于左得高屋建瓶之势故左腿水泡皆由津管逼出者也左膀则位高气隔津气难到故仅有润气耳肺有上窍无下窍膀胱有下窍无上窍一有降力一有吸力雨脏时相感应肺气绝则膀胱不化故小便不通肺与大阳相表里肺热极则逼迫水谷下行故始而粪是肠中宿垢皆下也继而水是肠中垢去胃中蓄水皆下也又继而白沫是肠胃皆空肺脏之沫亦皆下也病势至此亦云极矣惟声音尚朗脉尚有力是一线生机尚未全绝但非大剂养阴不能回其枯槁之势乃用杭鲜生地绞汁八两渣入药煎沙参二两麦门冬四两天门冬四两元参四两知母五钱黄芩五钱秋石五钱化水与前汁另存和服令药入大沙锅内贮满河水用炭火煎熬数沸后便以小茶杯装药频频与服毋急进毋间断尽一日夜全行服下亦莫断火药煎至无汁为度肺位最高药入易过病所惟缓缓进之而用浸灌之法最为得力明日复诊果油敛泡□神清脉转大便亦少连服三剂人事安妥便止溺行改方调理一月始能扶杖出门逾年而生子肥白可爱", "7055": "蒋阶平内眷刘氏病患旬余历经名手医治反至沉困余族小湖为之敦请数次因往诊视乃知患病已十八日每日酉刻发寒四肢冷至肘膝三更转热亦仅四肢发烧五更始退面色微红口渴而不欲饮食久不进小便一日一次色赤而少大便十七日不行诊其脉六部沉微舌色嫩红苔黏滑心中烦热胀闷坐卧不安前医视为阴虚火结用青蒿鳖甲汤重剂十余服反致危笃断以不治予思沉微之脉阴脉也四肢为诸阳之末四肢独冷阳微也寒热在阴分之时交阳分则退属阴邪也渴不欲饮舌红苔滑面有红光心中烦闷阴盛于内逼阳于外也大便不通小便赤涩阴结于内输机失职也此症定属水饮而外显假热之象若用阴药是以阴益阴为助邪也以苓桂术甘汤加细辛厚朴与服是夜病退甚早肢冷亦轻三服后小便清畅大便下行多水舌苔满布舌色转白脉亦起矣再用六君子汤调理寝食如常而安", "7056": "阶翁夫人病后二年生女未存又因不遂意事心常悒悒产后又病请吾前辈调洽因前辈兴蒋亦世交又是紧邻且素有时名故生死倚之服药无效日见加重前辈嘱令邀余商治前辈向余曰此病无寒热亦无痛楚但饮食不进已有多日终日啼哭百劝莫解舌色淡紫苔多剥落是胃气已绝万无生理已嘱办后事君盍往诊再商一治法聊以尽心而已往诊其脉右三部浮数无力左三部弦数无力舌色红而兼紫苔剥落余思脉证均非死候然不能吸言因复命曰诚如君言子亦不敢措手前辈不许属门二陈以搪塞服讫仍如故明日复诊诊后拟至前辈家商酌适前辈之令郎在坐请余主持不必往商竭力阻余余思此病尚可挽回究以人命为重要不必避此嫌疑乃用炙甘草五钱小麦一合大枣十二枚令多煎缓服一贴哭泣便减舌苔复生三贴全愈此盖脏燥症也金匮云妇人脏燥喜悲伤欲哭象如神灵所作者甘麦大枣汤主之即此症也脉症相符故取效最速此症黄八种内论之精详发明金匮之奥诚金匮之功臣也", "7057": "阶翁夫人逾二年又生一女产后经水止乳汁甚多二不乳经仍不行乳间结核而痛间又吐血血色鲜红幸不甚多余因内人病故由鄂返里至蒋宅有事其姑邀予为诊余告以脉象不佳宜善调摄且切勿断乳为要至季冬病者卧床不起矣复请予诊见其干咳无痰汗多不歛下午潮热饮食不思脉则弦数而疾私谓其姑曰法在不治其在来年春分前后乎果殁于来年春分前三日盖此人体弱性傲肝木本旺产后乳多非血气有余乃肝脾两经之血为肝火鼓而上行逼化为乳循厥阴经至乳间而出血虽暗伤而肝木转遂其疏泄之性故经不行而反无病及断乳后其肝木上冲如故也逼血化乳如故也而乳窍已闭欲泄不得故乳中结核胀痛矣其未化为乳之血肝火逼而上出故吐而见诸口矣血久上行便成熟路以化乳上出为顺转以化经下行为逆故欲经行必不可得矣医者不察以乳瘫常法治之木火愈旺金气伤则干咳无痰土气败则饮食不思血不化乳乃化为汗则上身大污淋漓脉又弦疾劲强是胃气将绝阳越于上阴竭于下矣有阳无阴有升无降内经曰出入废则神机化灭升降息则气力孤危卯月木气发生下无真阴以济之何以为生身之本乎故必死于春分前后也在断乳胀痛时脉弦数尚未搏指舌鲜红尚有薄胎若用苦剂歛其血以入内而下通于冲脉则经自行血自止乳核自消再以和平养阴之剂植其根本肝自柔和何至及此乎医者能不认症乎", "7058": "徐姓有遗腹子名遗儿叔平胞侄也年十岁夏间病寒热如疟日发一次医治两月末获一效其母恳治于余诊其脉两寸关俱虚软无力两尺俱滑大每日疟发寒不成寒热不成热退热无汁热退又不能尽饮食减少神倦无力二便俱通面色青黄舌色淡紫无苔似有亮光惟舌根两边有两条白苔口中微渴已服藿香正气散数十剂矣余与表弟蔡律初同诊因与商曰此子体质本弱暑邪深伏不能托邪外出又为药伤正气愈虚阴阳已有两亡之象若再驱邪邪将内陷乃不可为矣惟阴阳雨补扶其正气则邪不待驱而自解表弟所见亦同因用六君子汤加石斛终冬白芍服两帖便寒热分清热因汗解口味稍开前医见而阻之日再服此药定致喘满不救为开藿香正气散方又服两帖病复如旧其母知误仍求治于余余曰以吾前方服五六帖便愈四帖后果寒热止饮食进舌生薄苔豚有起色后开八珍糕方令终年常服数年来俱无病幼侄纲儿堂弟逸清之子也方十岁八月下旬初病一二日便昏睡不醒呼之间或一应间之则又不答四肢厥冷身亦不温不食不便小解黄涩面黄色暗舌苔蒲白而干唇白而燥裂两手脉沉微重按则滑余思昏睡肢厥身冷舌苔薄白唇白均属阴象然苔干唇裂便闭溺涩又与阴症不合问病前食生冷否云食菱藕甚多前一日又食柿子四枚余乃得其解矣曰病本伏暑邪热积于下焦为生冷停于胃口者所阻冷积不得下行热邪不得上达冷积为热所薰蒸愈团结愈不解阳气无由外达故见阴象中焦津气大伤故见阳症而成外阴内阳之候也用全瓜蒌一两文蛤五钱以生津清热黄芩知母贝母枳壳泽泻茯苓各二钱以清热利气加肉桂三分丁香二分麝香少许以化水果积和服一帖肢体渐温人事渐清二帖便大解畅行各病俱咸后改方调理月余始能健旺发落而秃矣此戊戌年事乡盛行此疫死于医手者不可胜纪惨矣冤哉", "7059": "赵少希余至好也其太夫人贤德知大体治家动谨夏间忽患温症一发寒热则抽掣难堪通身疼痛颐痛如锥心中烦躁不饥不渴不便舌本深紫无苔右脉弦数无力左豚弦数有力余曰邪之中人乘虚而入如水之就下也此症由阴虚之体受时令温邪深入阴之血分故一发则心肝两脏为邪所伤因见烦躁抽掣寒热往来脉象弦数等脉症温热经纬中论此症最为详明余因按法施治用鲜生地（五钱）麦冬（二钱）元参心（三钱）青蒿（三钱）赤茯苓（一钱半）银花（二钱）连翘（三钱）山栀仁（三钱酒炒）白芍（三钱）甘草（五分）当归（五分）竹叶（卷心者八片）莲子心（八分）连进（四帖）寒热抽掣身痛俱止舌苔渐生惟懊𢙐心跳体软咳嗽痰多脉象柔和是阴分温邪已退见脾虚痰泛之象适吾发旧患不能出门乃请吾乡推许之王某名医继吾诊治见吾前方颇不满意云时气之病为有开首便养阴而用血分药者（此等名医均守常套以试病不知辨脉症以立方所恃者汤头歌脉诀而已）改用凉膈散去硝黄连服四帖愈觉疲困值少翁由店回来因邀予往诊其脉仍如前余曰不妨此脾虚较前稍甚耳用六君子汤加厚朴八分缓以调理不难全愈此时少希二妹亦病四日服王君方亦四帖王君在余前一刻诊视尚云病将退矣较母病轻甚一二日便可全愈余俟其去而入房诊视见病者勉强坐起讶其躁扰不安有类阴躁面色夭白两颧皆红身亢热四日未得一汗唇与舌本皆白而无血色上有薄苔焦枯板贴肉上问夜能睡否曰日夜烦臊两夜不能瞑目矣两脉沈细而数一息约十二三至出房私谓其兄曰令妹之病法在不治其变即在早暮阳越于外故身热无汗烦躁不寐阳越于上故舌白苔焦颧红面夭脉数至十余是阳越而阴竭矣凡阳虚之体误服凉药多致孤阳脱出而飞越于巅顶之上与肌肤之外反显热象而变动极速此为不治之症矣王名医见令堂哼喊不安故云病重见令妹安睡无声放云病退此智者千虑之一失乎越一日僵卧如尸又一日寂然而逝此女心牲和平见地明达调停家事实阿母之良佐也早二三年夏间患疟间日一发市医为治月余罔效后挽予诊服药二三剂便愈愈后便止药药止便又发发即服药而愈如此又迁延月余适少希回来访问病情并屡止屡发之故余曰令妹之疟与时疟不同时疟多由痰食积滞所致令妹实由脾阳不足故疟来寒多热少先由手足冷起无头疼身痛口渴便秘等症惟面色痿黄身倦肢软恶食汗少脉来濡弱加之前医多用克伐之剂脾气伤而又伤余用六君子汤加附子一钱温补脾阳故服二三剂便愈然疟虽愈而虚未能回故药一止则病复至矣若连服十余剂虚气亦回便不再发少希因日煎一剂与服连服八日果不再发为开丸方调理二年无病是年死于七月因断丸药半年初病时又服苦寒药致真阳飞越阴火焚身可哀也夫", "7060": "赵少希夫人经停三月疑有孕因劳动下血疑欲产召余往诊两寸关脉俱滑两尺脉沈弱余曰胎孕之脉以尺部为主今沈微非有孕亦非欲产据寸关滑脉而言是脾胃二经痰湿太重始因气滞而经停继因气虚而血泄宜健脾化湿以行其气亦与胎产无碍此十一月事也来春余有事出门四月反里赵府急来召余其时经下无时或多或少心内颇不安适诊其脉寸关仍滑两尺则数大鼓指舌色鲜紫苔则黏垢满布予曰中焦痰湿皮极阻滞气机而下焦热亦盛极无由上达恐病有他变甚可虑也视前所服药均大辛大温大补肝肾之剂予知脉症之变皆由此耳明日已刻果患崩下血块血水约有桶许是日镇上适行东岳会人皆外出吾得信而往已至中刻病者鼻额间汗出如珠气促神疲吾见势急矣急令觅人参（一钱）生地炭（三钱）地榆炭（三钱）速令煎服此脱血益气之法也服讫汗敛气平血来稍缓二日而止但此后调理极难头运不能坐起肢软神疲食少乃中焦痰湿极重下焦阴血极虚欲补下焦之血则助中焦之滞欲化中焦之滞则伤下焦之阴筹思久之惟乘机利导之法最为得当用煎剂丸剂各行其经以取胜即互相为用以见功择清轻微阳之药为煎剂以开痰择重浊培阴之药为丸剂以养血服煎剂后约半点钟时乘此痰气暂开之际随服丸剂如决水转石已过关隘而迳入下焦填补阴血则两得其力而不相妨碍矣以此调理两月果体充神完寝食俱安吾内人于戊戌年秋间患血崩症不足一日而卒病情悉如少希夫人之症惜吾在湖北未得救治之法故数时气绝此亦数也赵少翁之表嫂解姓孤苦零丁无所依靠常住赵府其人寡言语慎举止朴实动劳得少翁令堂之怜爱秋初患白痢里急后重小腹瘀痛异常冷汗淋漓初意志在必死誓不服药数日彼求死不得痛又难忍故听予诊治其脉沈微似无似有面青神惫汗多恶寒肢厥均属阴盛阳微之象乃用熟附片（五钱）白术（五钱）炙甘草（三钱）炮姜（一钱）肉桂（一钱）酒白芍（三钱）青皮（一钱）木香（八分）二帖而愈予问赵府曰此阴寒之疾今骤得此当必有故答曰表嫂刻刻求死日饮冷水食冷饭吃冷粥夜卧当风不覆厚被不穿棉衣已有年余前日初病时自喜曰可以死矣与诸人永别矣至痛极难挨始肯诊耳予闻之不胜怆然逾二年又病红白痢服藿香正气散六剂未愈闻余回里急迎为治六脉俱弦数两尺尤有力唇红口渴腹痛下坠余曰前次乃病寒此次乃病热也用酒炒黄连二钱酒沙黄芩二钱酒炒白芍三钱青皮六分香附六分柴胡四分亦二剂而愈", "7061": "宦治桐性诚笃工写真长媳王氏秋季患温症因有孕七月未敢服药延至七日病势卮笃来恳予诊询知恶热七日曾未一汗面红有光胸闷躁扰诂妄叫喊人事间或清醒大小便俱闭呕哕连声滴水不能入喉诊其脉两寸洪滑两关尺弦数舌本深紫潮滑无苔合脉症黍之定属温病然口不渴舌潮滑滴水不能入喉则又何也就此推测而知此为温病之水结胸如伤寒水结胸之病也但伤寒由于寒而误治此由于热而自成水气因热上升填塞胸膈故舌润而洪滑之脉见于两寸也上窍为水气所闭则下窍亦闭如壶内贮茶大口盖紧小口即点滴不出故便溺俱无也水气上冲气亦上逆故呕哕不止而水难下喉心为水逼神明无主故人事不清且面红为温有光为水但泻水之药均能损胎虽有故无陨亦无陨也然与流俗难言之故婉言辞谢嘱请高明乃桐翁再三相恳又邀王炳南为作说客为用葶苈子三钱杏仁泥三钱枳壳一钱半法半夏二钱大黄三钱芒硝三钱水煎与服因嘱之曰此方皆损胎之药然有病则病当之于胎无伤也若胎气未动则病去胎存最为妙事若胎气已动则胎病俱去亦属无伤若不服药则胎去病存人必不保互方毋轻示人恐听人言而自误也药煎出一碗竟能缓缓服下无一滴呕出事亦奇矣历一时余腹中大痛其翁复来问治余曰上焦开发气下行矣无害也又历时许痛定安寝至天明小便下行甚多大便又下行多水果汗出津浑身倦欲卧病大退矣反致众口沸腾谣诼四起吾闻之因不再诊后医治不中窍余邪未净逾年余转别症而殁冬月生子亦未能存此病后失于清理安胎之未得法耳", "7062": "范自信三令郎患单腹胀服药二十余剂愈医愈剧迎予为治诊其脉沉弱而迟面黑而黄身体黑瘦四陂尤瘦削惟腹大而坚硬精神疲惫饮食不进大便溏小便清利夜间尤多纯是脾阳大虚之候前所服药又皆五皮五苓之类致脾虚气散腹日坚硬也为用理中汤加厚朴砂仁益智仁肉豆蔻驱阴益阳服三剂腹软食进八剂全安", "7063": "余姻亲蒋伯渠之侄女年二十秋间病寒热市医为之表散二剂而愈隔二日天将明时忽来叩门而速予往予至则病者神识昏迷已如尸寝据云三更时一觉烦闷便目闭神昏气绝片刻则醒醒片刻又绝半夜已气绝五次诊其脉六部俱无面色一团黑滞舌苔秽浊而厚此本伏邪因受感而见寒热一为表散便解其伏邪犹未动也然是即药线也为今夜发病之兆矣其秽浊有形之邪伏藏既久蓄势必紧如地雷火发势之暴烈难以言喻故一发则上犯心肺五脏皆邪气弥满焉得不神昏窍闭如尸寝乎但邪在胸膈难用下夺之法令急召康老剃头匠刺痧闭症颇效）刺其四末透风泄邪另用黄连等极苦极辛之剂以清降上焦俾浊邪下行神气稍清然后再接法正治刺后即连灌煎药两剂果神气梢转明日复诊脉仍未出病仍如旧乃仿达原饮方用川厚朴（三钱）苍术（三钱）草果仁（打碎后下一钱）枳壳（二钱）川黄连（一钱五分）黄芩（二钱）大黄（五钱）芒硝（四钱）木香（一钱）水煎与服周时始得大解粪如烂酱臭恶不堪人事始清但下徒恶寒战栗床帐动摇举家忙乱予初闻之亦颇惊骇以下后复作寒战古人谓为犯忌在下后三戒之内继而自悟曰此病与伤寒大承气症有别承气症邪热焕粪结于肠胃一下则热清结解不当再见表症若再见寒热非认病不真下之不当即正虚而成坏症放下后忌此也此病乃伏邪为患秽浊污垢之气蓄之既久非独脏腑间邪气积满即经络中邪气亦皆充斥脏腑窒塞之时气机壅闭经络之邪无可发泄故病虽极重而无寒热头痛症也今大便一行腑气稍通经络之邪始得外发此刻既有大寒寒后定有大热热后定有大汗通身外邪皆可因之解散实此症之幸事也大热大汗汗直至足果如所言是日即未服药第四日复诊脉则浮弱而数不甚受按面上黑滞未退肢体软弱心烦腹痛溺仍未清舌苔仍垢腻舌本深紫此邪气尚重也原方加大腹皮二钱与服至三更行大便甚多仍臭恶不可近第五日复诊各症俱咸面色稍转脉反实大数而有力舌苔厚腐浮起知其积滞已动乘势利导不难扫除尽净也原方咸去芒硝二钱再与服一剂服讫连行大便两次几有半桶舌苔退尽脉来弱小人事安妥亦能稍食薄粥前此数日粒米未能入口也但神虚体弱终日欲寐恶闻响声知邪去正虚为制健脾利气之方加以饮食调理月余始能起床两月始能健旺其受病之深发病之重不多见也若非体壮年轻何可望其生全哉", "7064": "陈道生忠厚人也与其父皆以好义见称数年淹蹇事多掣肘患关格症服药数十剂病势日重予自鄂回闻其病而往视之见其面色痿黄饮食入腹即吐午食至戌则出暮食至早则出所吐皆酸腐清食绝无新食一粒兼有痰涎甚多大便十余日一次有如马粪小便赤涩诊其脉两关滑大而迟重接无力余部均不应指前所服药类皆苦寒一派余曰此非真关格也乃胃气虚弱运化失职阴霾之气晦塞三脘痰水涎沫填满胃中饮食入胃为痰涎所裹不能运化精微时久则味变酸腐为胃所恶新食芳香为胃所喜故新食一入则宿食去而新食留且胃失健运其渣滓无由下达大肠津水无由渗入膀胱故大便艰小便涩势所必然若用理中以振胃阳用重药以镇胃气脾阳一复便可挽回乃用潞党参五钱白术五钱附子三钱干姜二钱炙甘草一钱五分以补脾阳煎出另用赤石脂细末五钱以镇胃气方出市医窃议曰大便已艰极再服此补涩之药大便当不通矣余嘱令煎服毋为人言所惑也服三剂果便溺通利服六剂果便泻痰水日十余次食粥不吐惟硬物不能食两关脉已敛寸尺俱起但濡弱耳余曰可望生矣胃中阴邪由大便下行其势最顺然浊邪一去则寥阔空虚有如新造之区故硬物不能消受其先大便结硬愈服苦寒下剂则愈窒今服补涩之剂则反下泄者是脾阳已回胃气已复中下焦阴霾之气痰水之积皆无地可容盘踞不得如红日一升群魔避舍有此气势此所以用补涩药而大便反泻之理也若再服十余剂将空洞填满胃复升降脾复健运便复其常矣讵料其妻进红灵丹与服又请王名医诊治视为湿痰用三仁五苓等汤不十日坏症复见两月而逝死后家徒四壁子不克家律以天道诚茫茫矣岂可问哉同族熙斋之岳丈孙步翁老先生任西码镇病两月为医药所误神识昏惑间有谵语二便俱闭口不欲食手足振颤日轻夜重熙斋挽予往诊雇船同往诊其脉俱濡弱而迟两尺滑大而迟舌苔白滑满布神昏而倦肢体软弱寒热日发一次头汗出颈下无汗视所服药类皆辛凉如黄连羚羊角等亦服多剂余曰此寒湿之症也本不神昏𧮪语因凉药助邪浊气薰蒸所致本不振颤因凉药阻滞经络所致本不便闭因凉药拥遏谷道所致幸体质坚固不易动摇为用川厚朴三钱苍术二钱草果仁一钱煨姜一钱枳实一钱陈皮一钱木香一钱藿香一钱生甘草五分滑石三钱一剂便通搐定三剂各症俱退人事向安后服丸剂调理月余精神复旧", "7065": "西码乔梓阁王捷庵二令媳年二十余四月患病直至九月初间历易名手数辈百治莫效奄奄一息已豫备凶器余在孙府再三敦请至其家有张君润之陪余诊视告余曰初病发寒热间日一次咳而微喘身疼头眩连饮食渐减肢体软弱心中动悸所服方药甚杂如建中汤桂枝汤桂枝加能骨牡蛎汤而养阴平肝之方不可记忆渐至身𥆧动手足搐搦粒米不进心跳神惫卧不能起如弱症矣余进内诊脉搐搦无定其夫执持手膊任余诊之脉则似有似无阳微实甚面色白而微黄舌苔薄白而润有水气体瘦如柴皮肤尚润寒热均在支于阴日逢阳日则稍安亦可略进米饮余商曰此极重水气病也伤寒曰心下有水气干呕发热而咳又日咳而微喘发热不渴又曰其人仍发热心下悸头眩身𥆧动动振欲擗地者皆水病也此症俱见矣水气入经格故搐搦振颤水气凌心故动悸头眩时久又为药误故阳气衰微神疲倦怠得支于之阳以助之则安得支于之阴以劫之则重是本体阳微求助于天时之阳气也若补阳驱水尚可救治请张润翁执笔为开真武汤加细辛一钱与服竟日有起色得获全愈其功全在张君张君本泰州名秀才医理亦精此次非辨症不实乃因名手之见均不相合不得独行其志及闻予言力赞其成动主家毋为人言所惑故得病愈生全皆张君润翁之力也其雅量不超人一等乎", "7066": "堂婶严氏燮和四叔夫人也病寒热往来大便难小便赤喉痛恶心不欲食烦躁请王佩廷先生来诊方用藿香正气散加减内有厚朴八分服讫面红气急喉痛烦躁有加因更请名手王十七（通呼为十七聋子名字忘却实胆大妄为之辈也）诊视力诋前方燥热之误乃用银翘散加黄芩寒水石等连服四剂面愈赤气愈急心烦躁扰愈不能耐且兼呃逆阖宅煌恐适予由西码回急往视之诊得两寸脉浮数无力两关脉滑大而缓两尺脉沉滑时寒时热身未得汗头颈间有汗出头如里身重不能转侧神迷欲寐便闭溺涩口苦不渴舌苔油黄滑腻而满布胸闷腹满予曰据脉症参之种种皆属太阴寒湿中焦之滞下焦气郁而心阳上浮此内有真寒而外显假热之象见未精者每为所惑而误治伤生王佩翁用药甚当但厚朴等分两太轻不能宣化寒湿使心火下降反助心阳之势以上升故反见热象王十七则不知辨症不知凭脉谬执成见漫议前医妄用寒凉致拥者愈拥升者愈升寒湿结于中心阳化火而上迫故烦躁面赤愈甚胃气不能下降必与心火上逆故气急呃逆愈加如煤火然以水由炉底浇上则浮火上升一二尺许即此理也为用川厚朴三钱苍术茯苓陈皮泽泻各二钱草果仁黄芩知母枳实各一钱半滑石五钱生甘草黄连姜汁炒各五分车前草一株服一剂热象全退转见寒象连进八剂始便通饮食渐进月余始能健旺其胞弟严桂龄受业于先君与余同意三载因清晨空腹为姊吹喉药传染病症如一而轻不信予言延一前辈而有时名者诊治生死倚之前辈迳用寒凉而不知返渐至粒米不进小便不通面赤气喘躁扰不安日夜不寐两月余舌黑如墨润滑光亮如镜恣饮梨汁蔗浆致脾阳全败龙雷阴火上升舌苔由黑而燥而裂燥裂之下尚有潮气其气急神扬刻不能耐叫喊之声四邻皆震目赤直视心内火焚苦楚万端令人不忍闻见也又越二日而卒由起病至死共三月余此症由寒湿而化热而化火直至上升巅顶阴阳脱离津液耗尽始得神亡而逝阔时既久受苦最深吾见病此死者甚多余故志之以告天下凡病家医家皆当以此为炯戒云", "7067": "中至好姚小湖精明谨慎人也秋初患寒热继则但热无寒神昏诂语狂躁不安余适在大港有事及余回里已有弃衣而走登高而歌之势面赤气急大便不通大渴引饮舌苔厚黄而焦燥诊其脉数大有力前所服药均辛凉轻剂其主持医治者余前辈也就而商之曰小湖之恙为温邪胃宾之症症实脉实俱属浊邪化热失下便有烂肠腐胃之虑故温病下宜早非如伤寒下宜迟也硝黄非重用两许不能胜下夺之任伊云小翁之堂兄胞弟均不在此若用重剂谁能担承余曰脉症既已如此且闻病前数日所食浓厚甚多不用重剂不能去病吾兴彼既属一家又是至好且吾又知医倘有差忒吾独任之于前辈无与为请用大黄五钱芒硝三钱即加入尊方内讵知前辈不以为然虽勉加硝黄各二钱俟吾等回后仍嘱病家减去且嘱令毋使余知吾回时巳过二更不能为之调药第二日清晨往视见脉症如故心窃疑之细访而得其情因病家尽属女流以耳代目难以理折徙唤奈何而已病家至三官殿求仙方方中有大黄二钱连服二剂大便略通日行一次病即渐咸一月后病似全愈而神仍疲困口不欲食面有滞色医家为制丸剂补养令再以饮食消息之遂日以鸡鸭鱼蹄劝进而病蓄食不知味勉强食之又觉不能消化十月初因小湖家喜来往贺小湖仍坐床上托予诊脉余曰六脉俱沉滞惟左关弦数而沉面色仍滞而日进补药恣食厚味此事大可虑也贵恙在七月势等燎原未用重剂急下至一月后诸症始退积滞始去然去之太缓有形之邪去矣无形之邪未去也聚于肠胃者去矣溢入肝胆者未去也肠胃与肝胆部位虽分功用虽别而处处有门户相通血气津液平时增能透入其胃家浊邪荡涤不速则秽浊之气全行透入肝胆故病愈数月未能健旺进食职是之故加以厚味补剂闭固愈深恐郁遏既久一旦外发其势不可当也小湖闻余言将信将疑十月十八日忽然头痛如破急来召余余往大港因仍请前辈为用表散风药一服后头痛更不能当乃求前辈设法前辈曰虚极矣非人参不救三日连服人参三钱人事昏迷如尸寝矣二十二日余回家闻而往视其仰卧于床四肢僵直面色红赤眼睁甚大黑珠旋转不停神光外露百呼莫应亦不知食撬开牙关舌本深紫如胭脂色苔则厚浊两脉实大而数惟两寸独不应指余思此症始而积邪由胆穴上犯于脑故头痛及服风药则木火之邪得风益烈故头痛愈甚肝胆与心脏属母子木邪上犯无不先入心络及服人参三钱心窍壅闭实甚包宫之邪永无出路故神明无主如痴如寐矣胸中宗气为周身之主宗气闭则周身隧道俱闭故人如木偶不知痛苦矣逾数日而殁殁后一日始殓周身温热尚如常人其死于实不死于虚可知矣", "7068": "殷春台为余至好善青乌术既博学而又得真传每谈地理明白晓畅似甚平常而精义即在其中余先君及先室皆任其一人经理又如江西陈纶阁浙江俞廙杆两位老先生均深信而委任焉其二令妹患喉痛邀余往诊其脉濡弱无力畏寒恶食舌苔白滑余向春翁曰凡喉疼齿痛妇孺皆知为热而令妹之恙独不然若吾用药定不肯服盖请他医为治不效吾再进剂不迟乃请市医为诊果视为肺胃之热用石膏黄芩等与服二剂后喉痛加剧胸鬲板塞烦闷全不知饥滴水不入复挽予治予曰令妹本脾虚多湿寒痰闭肺窍之喉痛一两剂便可见效以川厚朴杏仁生意仁大贝母各三钱茯苓陈皮苍术白术各二钱砂仁枳壳桑白皮莱菔子各一钱半紫苑一钱生甘草五分与服一剂胸宽食进两剂全愈", "7069": "殷春台夫人产后失调迁延年除服药罔效时时畏寒咳嗽痰清肢体倦怠夜不欲寐口不欲食神疲不离枕席时吐白沫胸中闷塞经水久闭诊其肺两寸弦紧搏指两足俱微弱舌本淡紫苔白厚而干余曰此上实下虚之候也上实者脾中之痰湿拥于上焦下虚者阴中之真阳虚于下焦惟下焦真阳不足不能蒸水上潮肺气无权脾湿又将窍隧阴塞故舌干而白沫时吐血不能生气不能利故经闭而倦怠也为用丸剂清上膏剂补下以白术炙草枳壳橘红贝母桑白皮等水叠丸食后服之以肉苁蓉枸杞杜仲鹿角胶鹿角霜等熬膏空心服之一月余颇见安好忽又延毕医诊视服滋阴降火两帖反觉沉困因仍服吾之丸剂膏剂八月余经水始通诸症皆瘳饮食渐加吾嘱令多服为是王炳南通命理训蒙秋初病疟仅发两次用俗传截疟法止住吾曰邪未退而截住定有后患十日后腹胀而痛身倦怠饮食咸尚不为意一月后支持不住邀余诊治其脉两寸部滑弱两关部弦两尺部弦劲搏指而缓腹中疼小腹硬如铁石而冷小便清利大便滞用补中益气汤与服两帖寸脉稍起余仍如故余思阴邪结于至阴之处非温不开非下不去乃用附子三钱干姜小茴香吴茱萸各一钱肉桂当归各一钱半川椒盐妙八分大黄酒制三钱为一剂与服一帖大便畅行一次腹内稍宽三帖后一夜大下二十余次色晦臭恶如鱼肠状人不能近彼甚恐黎明来召余急往诊其脉六部微弱而平静间小腹如何云小腹已温暖而软痛亦止余曰脉平邪退愈矣何恐为适余有西码之行彼食松菌汤面肢体浮肿服朱医补剂两日喘满不安余回而向予零涕余曰无伤也令服防己黄耆汤二帖肿消喘定日向安好", "7070": "逾二年冬月炳南又病呕逆汤水入喉即吐喉中微疼市医为治服银翘散两帖呕逆愈甚时时哕恶喉小破烂滴水不能进口胸中胀闷手足无力举动维艰四肢冷厥满脸白屑人皆谓无生理矣自度亦不能免彼以孤身寓镇无所倚赖故见吾流泪而口不能言为诊其脉两寸俱微关尺小紧因慰之曰无尤也吾立起之此属胸痹脉症相符有此病即有此药用鲜薤白六钱桂枝二钱生炙甘草各三分白豆蔻后下四分以水酒各半煎服一帖和二帖已此病载在金匮脉症治法极其详明而时医多不能辨漫用凉药致变生他故者往往不免吾不知名医而何以得成时名乎", "7071": "宋子默簪缨旧族吾世好而亲戚也二令媳李氏产后身体违和头疼食减自以为虚而兼恼怒伤肝市医亦云阴虚肝气用养阴降火之剂连服十八日头痛转剧自觉热甚渐搐搦晕厥初尚时厥时醒继则厥去不醒举宅仓皇子翁以病情来告余曰令媳体丰多湿平时而黄阴不暴虚火不至骤盛恐为医药所误也子翁默然而退请近处名手数辈而未能至与子翁至戚而居同门者吾表弟蔡律初也医术最精子翁恳为诊治律初转嘱邀予予往诊其脉滑大有力而缓面色黄内隐青口鼻两颊滞气尤重舌苔满布秽滑而白昏睡不管人事不抽不折气息尚平手足尚温产后两句余瘀未甚行且闻产后饮食亦甚庞杂余与表弟商曰脉症如是定系痰食瘀血互结于胸腹之间加以阴药壅滞闭固愈深经络不通阻其宗气神明无主百骸无所禀命故病至是极耳表弟云病者且有客感每饱食当风而卧外邪内邪互结不解故危笃如此余曰此理当极吾未想到因商用滑石桃仁当归尾元胡索枳壳磨汁槟榔磨汁姜黄姜连等为煎剂另用当归龙荟丸减麝香与煎药同服以下其积滞瘀血一服便神清而醒三帖后积滞俱下如胶如膏而瘀血亦行人事安适诸病霍然第四日因梳头劳动搐搦小发阿母作主请伊所亲近之赵医月药多不伦类幸邪退不至为害只多费时日之迁延耳", "7072": "方家湾有凌姓者家小糜无子以内侄为嗣已带养媳吉期择在十月而九月初忽病温症医治罔效至八日病势热极神昏𧮪语烦躁不安叫喊发狂家人以雪水灌之便神识昏迷不省人事仰卧如尸手脚僵直口张手撤适余下乡觅地托一薛姓者恳余为诊具时已僵卧一日呼吸甚微脉象微细如丝不受重按面色夭白绝无热象脉症均无温病情状惟舌本深紫干燥无苔上有绉纹如猪腰风燥者然余思阴邪断无此舌坐筹久之悟此病必温邪陷入血分时医治未中窍血热盛极致发狂烦踪及灌以雪水与病虽不相当而热势稍杀邪正俱衰致仰卧如尸而成虚备阴血为热邪所灼血枯阴绝经脉无血以丽之故脉来微弱心主血脉心经无血以养之故心神莫主魂无所依必至昏然第四日因梳头劳动摔溺小发阿附作主请伊所祝近之魑医用药多不伦猎幸邪退不至为害只多费时日之巡延坏方家湾有凌姓禽家小糜无子N内侄为删L带夤媳吉懈绎在十月而九月初忽病温症医泊板效于入（病势熟极神外讷冶他踪不安叫喊发扑家人以雪水灌之匝神织昏迷不富人小仰卧如N手脚偶立n恢手撒邋余下乡宽地托一薛姓者恳余为沽其时已碍卧一n呼吸占微豚象微细如丝不受市按面色天白绝无效艰脉症均无温病悄吠惟舌本深紫纥燥无苔上有绉纹如溅腰风燥当然余忍阴邪瞰怃此舌碓鸳久之悟此病必温邪陷入血分时医治未中窍血热盛极致发狂烦踪及灌川～水呶病虽不相常而热势稍杀邪正俱获致仰卧如尸而成虚懑阴血为然邪所物血枯阴绝纠脉獭血似丽之故脉来微弱心主血脉心经无血川费之放心神莫主魂怃浙依必至昏迷不醒而手足不为所用此病刘河间论之极详极当诚万世之师也用党参黄耆各二两鲜生地麦门冬天门冬各四两白芍药三两当归炙甘草各五钱酸枣仁八钱石菖蒲三钱秋石六钱化水和服以养血滋阴令用铜锅多水熬煎时村濯之服一夜至天明目转动午刻能言咨身能反侧十月完姻行礼履止如常", "7073": "许家村有老妇陆姓年近六旬秋间病感愈医愈剧迓予为治寒热日发一次午前发寒二更始退胸闷腹满气逆心烦夜不成寐终日迷困粒米不进二便皆通诊得在职弦弱右脉滑大而空三五一停日轻夜重举家忙乱已备办棺衾矣阅其前方多疟门例药因告之曰脉却不佳然为药所误脾胃大伤气尚未绝急和胃补脾犹可救治以六君子汤加肉果仁益智仁抚芎桔梗为剂连服两帖热退能寐知饥欲食其时伊至亲俟景文说胸痞须加黄连枳实方得奏效陆老翁执以告余余曰令媳本虚症也断不可用此以戕其生乃止又加减前方健脾阳驱浊阴三帖而愈余初次入诊见有少妇侍立床侧满面泪痕尤思外现余疑为女也访焉而知为媳其太翁曰自其姑起病直至于今日夜不离左右抚摩侍奉未尝稍间且眼泪不知流几许矣后病势日退便日有喜色不意农家者流得此佳妇其至性天成当愧死天下之为子者", "7074": "陆家有女子年二十余嫁于夏家湾之夏氏夫死产一遗腹子八日而病为医所误势颇剧陆姓求治于余余怜其孤而贫且恐母死而子必不保因往诊焉房中秽气熏人不堪立足见其喘急气促呼长吸短言不能成声食不能入口日夜危坐苦楚万状汗大如雨一诊脉时二毛巾皆湿如由水内拽起舌本青紫苔全剥落绝粒已经三日脉两面三刀手浮大滑急重按坚数前所服药均四物等类余曰此本温病医者不知辛凉解散而反用阴滞之药壅塞隧道致有此内闭外脱之候若不开其闭必不能固其脱也以磨槟榔汁二钱磨枳壳汁二钱绞萝卜生姜汁各半酒杯另用桑白皮苦桔梗苦杏仁金苏子赤芍元胡索生甘草飞滑石煎出对汁和服一帖喘汗皆减二帖喘汗皆止大小便通畅易方调理共服八帖而痊母子安好现子已五岁肥壮可爱矣", "7075": "萧佑廷余契友也为人笃实可靠因店事往通起程数日夫人忽发热烦躁夜间尤剧病已四日余由东乡返舍佑翁之兄托致电召弟速回以备后事余曰无恐侯诊后再酌往见病人烦躁面赤通身亢热无汁干呕气粗胸中胀闷大便不通小便赤涩不寝不食有两日夜脉则滑数无力尺部洪盛余曰此气分不足湿热凝滞经络之症凡湿邪重症往往日轻夜重何仓皇至是曰不食不寝已属可怕夜间躁扰乱语人人皆曰不宜前医亦曰病不应药十不救一故忙乱如是耳余曰无伤也以清热化湿而通经络之剂使之连服四帖汗出热退夜能安寝诸症渐愈矣", "7076": "予族中熙斋之女年十四岁秋间病寒热日发一次至热剧时则鼻中出血有如泉涌顷刻盈盖色鲜紫而厚日三四次不等初则有寒有热继则纯热无寒热乃不退精神疲惫心中烦闷头眩眼花身疼不能起床病者日夕思余一诊虽死亦心服矣予闻而怜其幼失怙恃急往诊之其脉则左手浮洪而数按之则弦右手则浮数而弱予曰尔以阴虚之体而受暑热既重陷入血分致有此候尔无恐两剂可愈用鲜生地麦冬元参鲜青蒿鲜泽兰叶各三钱茜根桃仁赤芍侧柏叶各一钱茅草根一撮鲜荷叶一个煎出调益元散五钱与服一剂便热减血缓两剂便愈后为调理而痊", "7077": "赵少希之令堂体弱事繁有恙均吾调治秋间患左腿疼痛筋脉牵掣畏风寒实甚八月已穿夹裤外加棉套裤一件然至窗口便觉冷风澈骨晚间进被便觉冷气袭人自疑寒湿拟进虎骨酒及艾火针灸等法余往诊之左脉弦数右脉滑数余曰此非寒湿也乃阴虚肝旺痰火妄行之故肝主筋肝脉行身之侧上行至头下行至足寒痰多凝滞一处热痰多妄走周身寒痰多属于脾热痛多合于肝今肝木既旺痰火循肝经下行至足经络壅遏筋无所养阳不下达故牵掣疼痛而畏风寒也针灸热药均非所宜为用酒当归酒白芍姜黄连炙甘草牛膝僵蚕姜黄贝母乌药叶秦艽等为末竹沥姜汁叠丸空心开水服三钱服至一月忽沥泻溏粪一夜共五十余次腹不痛不胀明日便止腿痛大减不畏风寒矣吾见此症极多热痰入经络卫气不通阳气不到每畏风寒痛麻抽掣不能举动若作寒寒用辛温之药或作虚寒用温补之药致破烂而流脓血者有之又壅塞而为痿痹者有之重则伤生轻则残废如此者不可胜计医者可不凭脉认症而漫用套方以误人乎堂兄寿山之姨侄女年十九岁夏季患疟午初发寒当即转热二更始退发寒热时心中烦躁懊𢙐便不能支其苦楚情状自己亦形容不出面赤气急身微有汗大便如常小便色赤两手脉俱弦数惟左寸独滑如豆数而有力舌色鲜红上有淡薄白苔余思此症惟心中独苦楚难受脉惟左寸独滑数如豆是乃邪气攻心而成心疟也夫邪由四面而攻心脏幸年轻初病心血未虚心气未馁时时与邪相攻击而邪气犹未敢遽来相逼只四面围绕而已如贼人围城城中兵精饷足未敢遽来薄击仅能远远围困而城中防范维严日无宁晷势难安枕故疟症一来则心中苦楚万端职事故耳然此亦难恃也孤城坐守外无救援饷耗力疲势难持久若一旦溃散其祸便不可测故宜及早图之因用蜀漆三钱为冲锋陷阵之将直破贼垒而解其围使兵民将帅溃围而出故以为君用生地连心麦冬元参心当归酸枣仁以养心气而厚其兵力使贼邪不战而自溃故以为佐使但服讫疟来时当更加剧须忍耐两时之久则自愈矣此药服下果如所言是日疟退甚早汗亦出透从此便愈即嘱令勿药而安马子扬吾亲戚也家贫病重余往视之见其面色黄黑身冷肌消舌肥胖胀大日间知人事而口不能言舌苔厚腻满布二便不通囊已上缩至黄昏则寒颤转筋人事昏沉至亥子时则烦躁狂叫手足躁扰至寅卯时则安卧无声神思疲惫饮食不进口亦不渴据云病如此重已三日矣诊其脉两关弦紧两寸尺微弱不甚应指前医以舌卷囊缩为厥阴温邪用犀角羚羊角等药矣抑知此症全因误治而然也其先本时邪中之寒湿症服凉药太多损脾之阳滞胃之气症变阴寒阳明主润宗筋今阳明无主则宗筋不润而短缩故肾囊缩入腹内与厥阴之囊缩迥异脾之脉络舌本今脾阳大败浊阴上犯循脾脉而上萦舌本故舌本胀大而不能言与厥阴之舌短舌必缩小者迥异阴邪弥满阳气不行至日落则阴气用串故神昏寒战至亥子则阴阳剥复故烦躁不安至寅卯则阳复用事便向安矣与温症又异为用附子苍术各三钱白术五钱干姜厚朴当归各二钱草果仁白芷川芎各一钱党参三钱为一剂与服连进两帖神情便解身温能言夜能安寝诸症俱退而病家轻信人言复箐王名医调治用药不当延宕半年浊邪闭窍致神痴耳聋如废人矣吾等虽无居功之意然信任不坚自误其事良可恨也故时医可为名医不可为诚哉是言", "7078": "吾寓武昌有浙江绍兴人翟正信专售各种报纸其子自上海来患喘症已经二医为治服药四帖视其方一为养阴一为养阴兼收敛余入房病者尚能下床就诊语言清晰二便如常饮食减少病起八日年方三十人皆以为无碍然余见其形容枯槁神气脱离诊得左脉浮大数疾重按则无右脉沉小而疾吾知此病本肾虚之故肾虚于下则痰壅于上医者不知补下清上反用甘寒收涩之剂滞肺气而助痰今脉败神离肾将无根而上脱其行期当不远矣因私谓其父曰令郎之恙甚属危剧前医用药已误不可再误余亦见浅术疏不堪胜任望急请高明或可补叙其父拟送回籍余曰乘轮下驶亦须十日恐变在半途各事棘手祈自裁之其父尚犹疑未定隔二日早间症变昏溃大汗顷刻便逝", "7079": "武昌杨干臣翰林也其次子十四岁二月放风筝冒风咳嗽多痰医者谓其体弱阴虚令服滋阴降火药三剂而瘳旬余又发又进二剂而瘳如是已屡发瘘愈矣至五月则干咳无痰咳仅三五声声亦不扬尚不为意后渐肢体倦怠夜间发热饮食日减肌肤日瘦遂复迎前医为治云阴虚甚矣因养阴补气不效而易医数辈方药杂投百无一应吾同事殷东屏为之介绍延予为诊予往见其形容黑疲骨削如柴汗多不敛喘急气逆不能伏枕日夜需人拥护喉中痰呜腹大如瓜大便溏泻小便涩少口渴喜饮善饥不能多食舌本紫而发青诊其脉浮大而弱重按则小尚未绝也余曰此症全因误治以至此极先因风邪屡为阴药阻遏风邪内闭胃气先伤故倦怠肌消夜热食减也后医又不知辨症补泻温凉用之不当风邪未去中气大衰升降无权失其常度胃气本当下行传糟粕于二便今不下行而反上犯致浊痰填塞肺窍而喘促不寐脾气本当上行升津液以润心肺今不上行而反下陷致阴液下出谷道而泄泻口干脾胃既亏真气散失则腹胀肌消风邪内扰与肝热相煽则善饥喜饮病势至此已不可为矣然坐以视死盍设法救之以冀万一乎为用清肃化痰之剂以治上焦食后服之又用理中汤加木瓜白芍以收脾胃之气加荆芥防风以祛风邪水煎食前服之挽回中气若三服后稍见功效则可设法进步若无效则非吾所知矣仅隔一日忽闻其死吾骇异之至意此病乃土败中虚之症现在夏令不当遽殂吾所开方虽不能期其必效亦不至速其死也托东翁为我访之始知未服吾药信巫者之言饮画符生水两大碗当即毙命呜乎杨公翰林也读书明理人也以爱子而误于庸医之手医理未明犹有说也若巫者能治病圣经贤传皆可废矣歧黄胡为者明理者如是乡愚妇女更何可问哉", "7080": "秀才尤小亭之四令弟夏患温病头痛身痛发热无汗口渴而不欲饮大便略通小便黄少两脉俱弦数两尺洪实舌本淡紫无苔余曰此伏邪症也病不易透势难遽解毋望速效幸耐之为用辛凉清热之剂以透其邪连服四帖脉已渐平已有解势第六日申刻予往复诊见且面色大变皮肤僵硬四支冰冷卧床烦躁反复辗转而人事不知百呼莫应两脉则沉小而疾余思此病不应有此变局实因天时亢热所居房屋狭小内热外暑两相胶结成此卮险之痧症夫人身津管血管通行周身而津血之中俱有咸味则俱有卤气故汗与小便其味皆咸是其征也若经气隧道为暑邪壅闭阳气郁而成火煎熬津血其中卤气结为砂子塞于管内则周身气血不行故肢厥身冷色变肉僵心主血脉血结为砂则心血阻滞神不安舍故痧症无不烦躁者重则昏迷轻则清醒故针刺透其络气可愈也芳香开其心窍亦可愈也冬季寒气闭窍亦成痧症但治之稍异耳今此病伏热未解加之外暑逼迫焉得不成极重之痧症令先召康老针刺出血吾急取药磨汁以灌两时许人事大清气平安静又得大便一次去积垢甚多明日热势复炽臃仍弦数浮起为用甘寒重剂两帖而愈吾见痧症极多时医讳言之不知何故因此伤身者不可胜纪病家志之", "7081": "尤小亭之三令弟年二十二岁患吐血症体倦食少面黄胸闷腹胀便溏小便清利脉濡弱血色黑紫而兼痰水余曰此脾虚湿重血不归经故也用白术淮山药白藊豆黑炮姜杏仁桑白皮当归赤芍红花与服六剂而愈再以六君子汤加当归白芍为之调理逾一月余送来复脉自言饮食起居如常亦无所苦惟神气不足倦怠日甚故请治耳余见其形容憔悴神气虚赢色黑肌消几如骨立诊其脉则寸关濡弱两尺弦小而疾重按始得余问遗精否有妄想否皆不对而去因告其兄曰令弟脉症甚属不妙外显气虚之象内得阳脱之征是必心有所思时时动念引动真火火发九泉阴液暗伤真阳脱出此为枝叶未有害本实先拨也法在不治再三请药余曰在吾见浅无法可施绝非借词推托切勿延宕致误当延学问高远者治之或可挽回亦未可知此在七月中旬至十月乃卒凡内伤之症惟色欲伤精最为难治但精生于血或以饮食自养或以甘温培阳十中可以救五惟妄想意淫伤心肾之精气百难救一盖无形之斫丧实基于有形之斫丧万万也", "7082": "予表姐朱姓二子授室多年仅得一孙视如拱璧年七岁夏季患时气病五六日往视之见其脉症舌苔温邪已剧医者方亦平稳不至害事余因朱便措手第二日其老妈告余曰小相公神色大坏请往救之俟雨止而往已至酉刻见其面色□滞口闭无言神已昏愦而心中烦甚卧床躁扰两面转侧二便俱无身凉肢厥两脉沈小而疾余曰势急矣盍求名手拯救其祖母曰适邻家请王名医先生余抱去就诊其方已著人代去购药余坐待许久始见其方余惊而告之曰误矣令孙本极市温症现热邪内陷窍闭津枯心肝火炽满腹如焚故神昏躁扰如是也内热盛极阳气陷于内则反不能外达故身冷肢厥如是也不然口燥唇裂二便不通脉来数疾是何故也胡王名医未辨咏症而漫用厚朴砂仁诸辛燥之药乎此药入腹二更定当不保现病危时晏无处觅医吾为立方以救其命用大瓜蒌二两石菖蒲一钱槟榔枳壳各二钱浓煎另磨紫金锭半枚和入灌之服下二时许神清开口遍呼家人明日热退未净汗出津津口干咳嗽余为咸瓜蒌一两去菖蒲加生地元参麦冬以滋阴保肺三帖进食而愈令勿服药", "7083": "陈道生江西人两淮候补也其尊翁纶阁老先生办镇江洋务多年忠厚和平春初仙逝遗暨在人吾乡每津津乐道焉道翁夫人冬月病感医治十余日病势剧甚殷春台为之介绍而逐予为治其时病经半月申酉潮热天明不汗而退通夜不能瞑目心中闷胀烦躁大便未得一通小便赤涩头左大痛如裂五心干热汁未一出粒米不进口亦不渴神气虚羸面色青薄舌色鲜红舌尖如竹刺搔破隐见血痕舌根有黄苔左手关尺脉弦数搏指右手虚数视前所服药均辛燥重剂余曰肝火旺极阴血伤极若不急养阴血速清肝热恐火燃血耗将见亡阴之象矣以青蒿三钱鳖甲五钱鲜生地捣汁二两麦冬元参各五钱酒白芍三钱生甘草莲心各一钱水煎和汁与服一帖便安卧两时之久诸症俱灭两帖后大便日行五次每次下结块一二枚逍请恐病下利商治于余余曰血益阴回肝木得养折其上升之性转而下行是肝得疏泄之职而脏气复其常矣无下利尤也脉亦平惟右脉弱甚为减鳖甲加白术白藊豆建莲以养脾气服两帖诸症俱退脉亦柔和", "7084": "谈鸿钧年三十余为人谨慎和平精明爽直在镇城外开铜锡器铺抱恙年余历治罔效就诊于予云初病似痢非痢日夜约五六次溏粪兼水至今未愈腹胀微痛气时下坠身体倦怠手足软弱心中悒悒不乐饮食减少胸有酸水凡食后历两刻则酸气上犯心如浸入酷中若再进食则酸止一二刻而复作见风亦然故恶食畏风无法可免自为虚医者亦认为虚然补亦不效不知何故予视其厚润微黄之舌苔淡紫之舌本诊得沈滑有力之尺脉因告之曰贵体壮伟丰厚既未戕贼伤身又无客邪剧病为得遽虚此必水气积伏下焦也肝肾被郁舌多紫色热邪则紫兼红阴邪则紫兼黑今淡紫兼黑苔厚而潮面色且又晦暗定是水积肝肾部位而兼溢入经络他两尺脉沈滑有力亦阴邪盘踞肝肾之征肝以困而上逆肾以郁而下泄肝困则疏泄失职故有上逆之势肾郁则闭藏失职故有下泄之虞所似伤寒论以吐逆为厥阴经症下利为少阴经症也阁下土气深厚气滞而湿化为水肝因水困则性喜冲逆水为热蒸随木气以化酸即随木火以上逆惟食入则酸水被压而暂止及食下行则反助其焰而加剧其所以吐不出者因气滞而阻于胸膈之间不能上及于喉也风木一气若受外风则内风同气相应风性升腾水必与俱而心如浸醋矣肾主二便水气伤肾则肾不能藏而下粪水其水行不畅不能由大便尽去者亦因气滞窍闭无扫除之力也此非重剂不能奏功予为措方毋示人而为之訾议耳乃用苍术四钱大黄防已各三钱葶苈子一钱川椒盐水炒黄速各一钱全用燥烈刚猛之味直入下焦趋水定能取效服一剂历十二时畅行大便一次服两剂历七八时畅行大便二次服三剂历一二时畅行大便三次其所下尽如胶水又有红水约行去半桶臭恶不堪腹内爽怏知饥欲食肢体有力进食当风胸无酸气年余痼疾三日去之欣喜异常为复诊似尚未净吾为易方调理嘱之三五日后再来诊视恐积去未精宜再下也后却未来当已全愈新入邑庠之陈凤翔吾友沈少湘之高弟也好学深思温文儒雅其令尊年六旬患腿与胯骨皆痛医治两月病转沉困医皆曰虚极矣汗脱定在朝暮辞去不治沈少翁为迓余诊以视吉凶何若余胃雨雪而往见其精神困惫脉象败坏乃脏气壅遏气散神离之候与脱症迥异病在不治却非三二日所能变也少翁曰陈君之死势在必然然坐以待毙曷若尽心力以救治作一侥幸之想乎余为立方以图攻补兼施煎丸并进数日后似已应验惜其中服药未能如法脉未能转神未能回余因辞去又越数日而逝由始诊至此共二十余日吾为之竭尽心力自问已无愧矣今将病情详志于此盖翁平日肌体丰盈饮食强健惟大便数日一行行亦不畅其气体之壮由于此而患病之根亦伏于此凡人入多出少其饮食化精微者多始有此气固神完之候其饮食化渣滓者则全由前后二阴而出清者出于前浊者出于后则是渣滓又全由后阴而出今出孔比入孔尤约则渣滓无由尽泄而化为浊痰秽气潜伏于骨空经隧及脏腑膈膜之间日积月累而已不能知及气血稍有凝滞则伏者外发经脉阻塞故腿痛作矣而饮食神气尚如故也若此时一为疏通经络清化痰浊数剂自能全愈再为理脾润肠使腑气通畅便能免其后患乃医者计不出此反谓高年腿痛多属肾虚遂与补肾养血之药服至数十帖讵知壅者益壅滞者益滞痛伤胃则饮食日减补滞脾则肌肤日削气因阻而渐散神以逼而渐离闭固愈深生机愈少医治两月而不可为矣予进诊时见其形容消瘦气体虚羸面色黄白而有浮光两眼皮破烂眦泪甚多神清而口懒言目常瞑有类昏愦倚被而卧因下体皆痛体不能舒畏风恶食终日似醒不醒汗出津津黏手惟寅卯二时上体汗多五心烦热卧不能安舌苔油黄满布而滑两手脉浮沈皆无惟左关重按至骨时或五七至弦小而疾据脉症言之眼胞属脾其破烂多泪脾湿重而为热上蒸也寅卯二时属木内应乎肝肝为脾困无由上达一至其得令之时则上冲乎心胸外泄乎皮肤稍遂其升发之性故过此则仍困而止矣左关脉时或一至亦是此故其余脉症面色舌苔均脾伤水困壅闭晦塞之象也医者不知为闭而以为脱诚以北为南指水为火矣余以理脾为君利气疏肝为佐制煎剂与服另以丸剂疏通下焦壅滞与之后服服至八九日行大便两次痛减卧安五更烦汗皆止乃以通络化浊之药为散以易丸剂令与煎药同服乃侍疾者与煎剂则止末药明日与末药则停煎剂如此数日其病家虽喜渐愈而脉未能起食未能进吾知不足恃也余辞去数日果闻凶耗甚矣虚实之难辨也极实之症脏腑窒塞经络壅滞肢体倦怠精神困惫有类乎虚各脏为浊邪所遏各脏之神无由返舍必至游行而外散如燃灯然灯中有油则光亮油过灯头则光灭与油尽光灭者同一灭也而所以灭者则不同也人第知灯灭而不辨其油多油尽也此所以虚实之难分也", "7085": "越河圩王益之长媳徐耀庭之侄女也亦吾表兄夏德生之亲戚秋初患痢治愈后而夜不成寐近处名手遍请诊治而病转危笃拟勿药而待毙矣忽闻吾名托夏德兄为之介绍敦恳再三予往诊时目不交睫者已近三月口不能食者已有月余家人勉以鸡肚浓汤发进强咽数口反觉胀闷所最难堪者抽搐惊恐两事一经大抽大搐震动跳跃则气绝僵卧静待片刻便苏日夜抽厥共二十余次其惊恐则如在刀剑业中即数人挟持拥护胆亦不能稍壮头眩连不能坐起二便俱通身无寒热但面色通赤肌未消瘦中心烦热多汗腹胁胀闷经水久闭其舌本深紫无苔而光亮如镜其脉则立寸关注小而沈右寸关濡弱两尺部滑大满指重按有力视前所服药惟治痢用木香槟榔之类余皆滋阴平肝养血敛神之剂数医一辙约服七八十帖故病势至此极耳病者有小叔王寿禄亦学中人予因与之论病曰令嫂痢症本肝经血痢服木香槟榔等气分之药邪在血分者反深藏不现故痢止而不能寐矣人寐则魂藏于肝肝有伏邪是魂之舍为邪所居魂无窟宅之所阴阳不能相抱以致夜不成寐与心脾血虚神魂飘荡之不寐症迥不相侔此时若为清理血分使邪外散数剂便愈乃医者反用辛凉补涩之剂而血为上凝痰为之滞肝胆之气壅塞不通肝主筋筋挛则抽搐大作肝心两脏木火相连肝邪上逆则心窍闭而气绝僵卧胆府清净则气壮心安胆为邪据则气饥心怯而惊恐特甚木来克土而痰又滞脾故腹胁胀大饮食不思得鸡肚之汤而反不适肝脾壅滞升降失职肾水不能上潮致心阳独亢于上故面赤烦热心如火烧方书云舌光如镜胃阴将亡但亡阴之舌色必嫩红而滑此色之深紫血之瘀也其亮如镜痰之光也非热非虚故肌肤未消脉亦不数且尺部滑大有力显是有形之痰血伏积于下焦肝胆之部今二便尚通脉未大坏胃气尚存犹可为也王寿翁以予言为是因立方用柴胡滑石各五钱桃仁四钱大贝母醋炒五灵脂半夏盐水煮姜黄各三钱枳壳桑白皮陈皮丹皮茜根山栀仁各二钱生甘草一钱为煎剂另制当归龙荟丸八钱分两次服煎剂日服一帖两日乃大便畅行每日两次所下痰积瘀滞甚多经水亦通夜能安寝更许抽搐止惊恐愈人渐向安煎方服十帖脉亦大起尺部渐平此冬月下旬事也病家因丧不延缓至今正复诊人已虚甚脉尚未净为用甘温补益之药为君以利气清邪为佐服数帖后周身发疮饮食渐加精神渐旺令仍以前方调理似可无虑矣吾适有江西之行未能终事心常念念也", "7086": "吉安庐陵令江绍棠号云卿桐城人也接篆后政绩劳心抱病未能调摄且医治多误历三月末愈始而咳嗽痰多畏风胸闷饮食减少两目干涩继则精神疲惫肢体软弱左手足酸痛麻痹胯骨亦痛小便不禁下体皆冷自疑手足痹痛为血虚小便自流下体冷为肾虚前服温补之剂已两月余病反加剧不知何故今征治于余其意亦在补虚也诊得两寸脉滑如豆转关濡尺沉滑而小重按搏指面色黄白苔黄滑满布口亦不渴余曰以脉症言非虚也血虚症当申酉潮热脉浮数或细数或芤涩肾虚症当面黑尺脉虚微或洪大而空今皆不然咳嗽胸闷寸脉滑转如豆均痰结上焦之故食少神疲四肢软弱均中气不运之故脾胃者营卫之原左右者阴阳之路脾胃健旺则营卫通利阴阳出入之道自无阻滞今脾胃为痰湿所壅萤卫不通道路皆阻此左体痹痛之由也贵体阳本不旺今上中二焦壅塞气不下行即阳不下达此下体皆冷小便不禁之本也先为清肃上焦化痰利气以薏仁蔻仁枳壳贝母桑白皮紫苏叶苏子前胡姜黄连川厚朴加姜汁仲服二剂咳止胸宽复诊云翁仍以下虚为虑意在用补余曰贵恙本有余之候壅遏不通若温补郁而化热阳愈不能下达遗溲畏冷更甚且痰得热而妄行其祸有不可胜言者惟健连中焦化痰通络为最合法以姜黄连川厚朴枳壳生意仁茯苓白术陈皮法半夏秦艽乌药叶岁灵仙牛膝白僵蚕与服数剂诸症皆愈竟脱然矣", "7087": "江云卿之三令弟患目年余干涩无光继又喘嗽气急不能伏枕陈医为治一月病已危笃迎余往诊见其凭几而卧被大声呼醒醒则神色仓皇其魂似已离体形容枯槁有如木偶耳轮焦黑唇齿干燥目有绿膜舌青紫雅苔是形存而神亡矣脉则寸关俱绝尺部重按至骨微小而疾指稍起则不应指此败脉也视陈君方尚用桂附等且云望病之转全在此剂呜乎病势至此尚以桂附作侥幸之想乎此公早年不慎毒气深藏血耗津伤不自知觉现年高体弱肝血伤而目盲医者不知治本而用目疾冽方引毒气上攻肺气伤而喘逆不能伏枕然疮毒无不发于头面肌肤而破烂者此独内伤而不外现者因血已暗蚀无水行舟不能送毒外出故反内攻乎脏而脏何堪乎此时若为养血毒自外散目自愈喘自定矣乃见喘治喘肺气重伤而脾胃之阴不足供其挹取阴火日炽五内如焚血耗津亡而遗此枯槁骨立之形体尚能任桂附之辛热乎余不肯措剂其至戚马君乞开方以慰女流因开数味嘱其勿服逾两日而竟逝矣", "7088": "吉安康文卿开隆昌木号其夫人二十余岁五日节因多食糕粽椒姜而患温症又服医家香窜大热之药遂身热无汗腹痛胁胀胸闷吐血人事昏沉语多谵妄手足搐搦大便不通小便赤涩日轻夜重躁扰不寐王升甫为迓余治诊得左脉弦数右脉滑数其神如痴问曰经水何如曰初病经水便来现尚未止共来六日矣余曰此温病热入血室而兼食积也为用柴胡一钱半黄连一钱全瓜蒌一两青蒿山查子麦芽赤芍丹皮生地各三钱枳实元明粉各二钱令与煎服或言太寒瓜蒌黄连各减一半服后热减复诊时升翁私以告余余曰热邪重极血分大伤血燥津枯大便如何下达今用瓜蒌八钱余仍旧一剂果大便畅行热退神清惟腹胀溺赤右脉仍滑数此食积未行也为去柴胡半夏加酒曲五分又两剂诸症皆愈安寝如常又为易方调理", "7089": "长沙严桐君神岗山厘卡司事也初病寒热服药两帖而止数日复发加腹痛囊坠又服丁香吴萸茴香术附等两剂便身大热汗大泄胸中板塞囊坠筋牵其痛尤甚小腹亦胀闷而痛入夜手足躁扰喘急面赤语言谵乱壮热不寐诊得脉左三部弦数有力右三部滑数有力尺部尤盛面色晦滞舌苔厚腻余曰此本痰湿之体而内有伏热又服燥烈之味致热势暴炽鼓动痰火上犯扰乱神明故躁妄胀闷辛温之味迳入下焦致热无可泄逼入肝经之筋与络故囊坠筋牵痛甚凡湿温之症俱属阴邪化热故入夜反剧为用姜黄连川厚朴各一钱半枳实杏仁薏仁贝母黄芩各三钱知母泽泻茯苓各二钱益元散五钱白蔻仁八分加白萝卜汁一酒杯为引两剂热退神清囊消筋舒二便通畅又易方调理而痊", "7090": "汪济舟本徽籍迁居扬州多年吉安分销盐局司事也抱病三四月未愈就治于余曰近半月中口不能食亦不知饥精神疲惫胸闷腹胀痛大便久闭烦热多汗卧不安寐口渴身倦诸多不爽难以言喻自觉非下不可诊其脉左弦数右滑数尺脉圆大如筋到指有力三五至一止止片刻复来类促脉而非促脉舌苔黄燥而厚秽余曰此因思虑伤脾气滞而郁痰火甚重枢连无权气机皆塞虽用硝黄下之不能通也若勉强通之脏真反损其祸滋深吾为清热利气大便不求通而自通方以枳壳贝母桑白皮黄连黄芩知母滑石青皮丹皮槟榔磨汁冲服二剂而便通热退胀痛皆消脉亦和柔惟弦肺未退为去槟榔枳壳桑白皮加青蒿白芍生甘草生地丹参调理而愈（又曰前服陈姓方内有大黄八钱便未能通何故余曰吾前已言之幸大便未行耳）", "7091": "彭璞山令郎年二十患腹痛每日申刻发热腹乃大痛上及胸胁烦躁不安夜不成寐至天明则热退痛上无汗微渴余见其色黑而瘦两脉弦数无力饮食不进不能起床者已念多日前所服药均术附香砂之类因语之曰此木火久郁木来克土则腹痛而及胸胁者皆肝脾部位也至申酉便发者大气已困至金气得令之时木气又为金伤而不甘于受制则热发痛作因木以愈困而愈横也少阳厥阴经症无不皆然为用小柴胡汤加酒白芍五钱二剂热退痛减四剂全愈吉安人专喜温补有病无病皆常服药药铺最多生意极旺附子消路尤广其色洁白煮出无色无味余服五钱并不觉热因漂制太过汁已出尽故也恐重症难以见功误用仍能贾祸吾若欲用断不取是耳吉安医家凡见感症无不以麻桂为主杂症无不以桂附为主余如香燥温补之剂亦常间用病家亦非温药不服余居吉安三月凡遇温热病为用辛凉阴虚症为用滋润病家问药店中知是凉药便不敢服至死不知悔悟其愚实属可悯有老学究刘姓者年五十余娶补房年二十余凡近内时稍一动念精便先泄不能自主日对佳冶不能忘情而又不能尽情自疑肾虚服八味等汤数百剂未能稍效吾为诊之因诘之曰先生有大拂意事心思不遂积久而成此病也然乎否乎曰然余曰肝脉弦心脉数此肝因郁而生热引动心火心火一动则转借肝热下迫逼精下出与肾虚迥异宜服温补不效也为用疏肝气清心火之剂并无苦寒之药已畏其凉而不敢服矣噫吾亦无如之河矣", "7092": "耿璧翁夫人年四旬自颇知医春初患病历夏徂冬叠经名手医治即孟河费马诸名家亦皆亲往就诊服药百余剂病日加重冬月下旬已回家待毙矣后闻吾名而来就治曰始只食少体倦腹胀溺涩白带时下现白带如注小便极难努挣许久只有点滴浑浊如膏小腹坠痛几欲自尽腹不知饥口不能食每日早晨神气稍清至午则疲惫不能动作医药备当百无一应吾已自知不起而罪实难受不如早去为妙请诊视而示我死期耳吾见其肌消气弱目钝无神诊其脉六部俱微惟两尺略滑余曰病久神伤因误治而致此幸脉症相符非死候也彼曰吾不畏死先生毋诳我余曰我非行道者流不求名不求利欲赚尔何为贵恙本脾虚湿重故溺滴腹胀医见小便不利为用五苓利湿讵知脾阳不健湿气壅遏愈服淡渗之剂脾阳愈伤壅遏愈甚浊气下流清气亦因之下陷医虽屡更药仍一辙故愈治而病愈重也又或因饮食日减肢体倦怠认为脾虚用参术等味讵知脾湿已重参术不能补脾反来助湿是脾愈困而湿愈生腹胀便秘恶食愈甚也今清气下陷浊气下壅痰湿下流故白物淫淫而下小便艰涩坠痛中虚而有阻滞则心肾不交故不寐肢冷先为升清化浊后为交通心肾须至木气得令春温升发之时方得全愈用川厚朴枳壳陈皮半夏牡蛎苦参破故纸升麻柴胡柏树东行根皮煆白螺蛳壳煎服连进六剂果坠痛减小便通为易方常服又开丸方补心肾令日日间服至三月果愈张春山患血淋偏坠已返二旬服药十余剂未效吾燮和叔之亲戚也为恳予诊至则药煎出未服予令姑缓诊后再酌诊得两脉弦数有力约七八至小解痛如刀割所下皆血现血止而点滴不出小腹有筋扛起痛甚直入茎中左囊下坠因痛甚而目不交睫者十余日往来寒热口渴烦躁面色通红前医所用均柴葛及香窜之味余曰前方误矣不可再服此少阳温症而兼血瘀溺管也肝之脉络阴器肝热重极致筋暴露囊下坠溺管为瘀所阻而又为肝热所迫故小便刻刻欲解而痛涩不能解出为清解少阳而化瘀通络则自愈矣以青蒿山栀仁丹皮赤芍丹参侧柏叶茅草根为煎剂以滑石甘草稍琥珀海金沙鲜牛膝捣汁为丸与剂同服连进三剂小便通痛止筋舒寒热亦解惟囊坠如旧乃去丸剂于前方中如荔枝核橘核山查子又服三剂而愈", "7093": "谏壁镇地保江荣患咳嗽痰多痰有臭味医家或言肺痈或不言肺痈而又不能认症漫治一月豚败神伤已不可为矣其妻恳治于余因往视之见前所服药均滋阴补肺之剂脉案中认为肺痈者十之九不言肺痈者十之一然用药则一也余曰痈者壅也痰血壅滞为热所蒸乃生痈焉况肺痈则痰血热三邪重极始得化腐成脓而生痈为有余极热之症皮外生痈尚痛肺痈则胸中刺痛尤甚今胸中不痛非痈也痈由热成口必渴苔必黄溺必赤面必红痰必稠厚脉必滑数而实今病者口不渴不喜饮茶舌苔薄白而潮滑小便清长面色黄白痰清稀而胶黏微带青色脉则右微滑不能应指左弦紧俱属阴象以脉症言断非肺痈而痰臭者何故盖致病之原则因恼怒伤肝思虑伤脾脾伤则生湿肝伤则生热湿与然合则妄行且脾主诸臭脾湿入肺则腥臭入心则焦臭入肝则腐臭自入本脏则为秽臭此痰臭之由与肺痈痰臭者势正相反现头面四肢皆肿湿外泄于皮肤也咳嗽喘急湿上阻其气道也脾气既败脉症俱逆是为坏症未可挽回服吾药两帖病势大减举家欣喜余曰病转而脉不起非佳兆也凡弱症过时失治真阳脱矣真气绝矣乌能收效后果然未越十日而毙矣", "7094": "吾乡今春行小儿疫症初组长寒发热寒热止便烦躁不管人事后乃面黄如杏身软如绵手撒口开眼合肢厥僵卧不动若不治或治不得法其气便奄奄而绝自起病至死不出一日吾乡死于此症者不可胜纪吾医治三儿均获渐愈一仇氏子十岁已面黄昏愦见其齿干唇燥舌苔黄垢两脉俱无吾思此必伏邪内发有秽浊实邪上犯心胸堵塞清窍始有此险恶之候凡人胸中为宗气最为紧耍故喻嘉言有宗气论语语精当胸中窒塞宗气不行神明无主百骸俱废或体软神昏绝无知觉或搐搦发狂不省人事若邪气久闭不能自开或用药不当无法宣通由闭而绝本不出数时疫症病死之速职此故也此病通降为第一著因用紫金锭磨出对姜汁灌服约一时许脉渐出眼渐开面色渐转为制清热化浊之剂加酒曲煎出与服是夜大便行一次人事大清颇为安妥是晚伊有亲戚来至木行道者三更时又与辛温表剂明早又与以香燥时丸乃引伏热入阳明经中身大热心烦气急面赤多言口渴喜饮六脉浮洪而数小便五六时不解颇有登高而歌弃衣而走之势赖吾旧友倪新甫至为之推拿四五次果溺通热退而愈（吾幼女病痰喘及吾乡患重症暴症经新翁推拿无不立愈较药尤速神效可爱）一系侄女挹清弟之二女也症亦同上以紫金锭和姜汁灌下半夜始苏行小便一次手足躁扰狂叫不安第二日为用清热化滞药加酒面与服此日忽厥逆忽烦扰各一次至晚行大便一次人始向安第三日复小便不通昏卧不醒面色青惨脉微弱欲脱余曰虚象也急煎补中益气丸二两加滑石二钱与服约两时许溺通人事渐清但言背脊骨痛余曰阳明经邪未去也用补中益气丸一两加葛根一钱半升麻八分服下痛止惟唇舌焦干苔黄而燥余曰阳明虚热在上也用补中益气丸一两加麦冬三钱沙参二钱五味于五粒与服便舌润苔退人事大安诸症愈矣又治许家村一孤子七岁病情治法均与侄女相同得获安好无恙吾因此症访问数家皆因病前恣食汤同入腹未化复为邪气所冲填入胸中致有此候故方中用酒药丸以化糯米之积无不应验也", "7095": "冬温十四日，身似凉，脉仍大有数意，而久按无力，是属邪减退，舌亦滑润，尚灰，两边黄，面红，目白红色，口舌自觉燥，仍属肝肺之余热未净也。查温病，古有葳蕤汤，其意首存津液也。此症病中经，至未经通走，故致肝热而作惊多怒，汤中有白薇，能定惊凉血，拟以治此。", "7096": "大便以增液而解，可知其沸阴之热，精液得滋润，必不以苦寒而燥之也。诊脉左手已细软，右关已大去而尚有数象，舌苔尚黑燥。然有脱象，喉舌尚燥，再当遵《条辨》法，养其肺阴，用清燥汤。", "7097": "两太阳与腰痛，稍有咳嗽喉哑痛，脉左关反大，而舌苔燥，当用从症不从脉法。", "7098": "诸筋骨痛，咳嗽，无味，脉涩，当滋血息风。", "7099": "痛瘥而作泻，胃不开，舌尚黄，脉左手关尚弦，再以肝法建中汤法。", "7100": "寒热往来，出汗已有四个月，脉弦细，此属肝虚。当用清骨散。", "7101": "气急是老病，今伤风半个月，自然气愈急，咳嗽无痰，脉左手大，右手弱，尚身热头痛。拟清金平木法。", "7102": "背冷气急，腰痛舌黄，口燥，有汗，脉浮弦大，当属少阳经感风。", "7103": "少阳症，身已凉，舌黄，口渴，咳嗽，痰厚，诸筋尚痛，脉平，当祛余风热。", "7104": "胸中痛兼及腰间，作呕黄水作苦，已有一月，诊脉弦细，咳嗽寒热，此属少阳厥阴之合病。", "7105": "诊脉已大起，惟全涩，涩属血虚，惟舌稍黄，且有肝气。拟滋补肝阴气分复入舒肝。", "7106": "产后又温邪后，脉左手小且调，是属吉象。惟有数意，寐回冷汗，耳响，皆虚也。", "7107": "产后病外感，愈后迄今，五个月期未至，述饮食起居均好，脉亦右手好，左手沉小。虚是属肝血之虚，当调其肝。", "7108": "初起身热，至今八日，面红头痛，口渴，舌黄滑，小便赤短，解时大便如水随出，诊脉左手数大，右亦然，而脾尤觉大，当属冬温，冬温用三焦法。至左胁与背筋掣，与左边头尤痛，是素有肝气，此时由外感带起。又温病往往有大便作泻，乃肺移热于大肠，由湿体之故，并非挟热下利。", "7109": "暑湿从无大便攻泻之理，此症患经二十余日，历服枳壳蒌仁多剂，昨日又以制军，致舌苔雪花呃逆，昨用益阴固脾，泻瘥呃减，惟舌尚雪花，若胃口日开无碍，脉仍弦，再拟复脉加减。", "7110": "暑湿误下，致舌雪花，口燥甚，大便已止，呃已去，出冷汗，脉左手已小，右手尚大，再以前法。", "7111": "疟后或间日，或日日，已两个月，热转轻有汗，汗后又冷，汗后嗜卧，转侧身重，舌白苔滑，或有时黄滑，口燥不能饮，饮后呕黄水，嗳风，腹痛，口味淡且滞，胃久不开，诊脉皆滞缓，热时之数不作凭。此属太阴经湿疟，为日已久，且在秋中，拟温劫湿邪。", "7112": "患肚痈后致弱，所以脉虚小之至，嗣后逢吃力，必咳嗽失血，又腰足骨酸，是可知肝肾阴分至虚。", "7113": "肝病胀均差，而如崩亦减而带甚，脉仍弦数，再以调肝。", "7114": "久咳痰臭气急，口味甜，小溲红，诊脉弦大，当属肺分风热。", "7115": "久嗽，用药臭痰已瘥，口味尚甜，脉尚弦而已小，再以甘寒。", "7116": "上焦肺胀，已有一年，咳嗽痰少，口渴，舌黄，大便痛泻，小溲少，脉弦细，当治上焦。", "7117": "动则气喘，属肾虚，烟气亦咳喘，属肺分气冲，脉弦细是肝冲。大抵肝肾之气冲肺，而肺气亦虚。", "7118": "肝痛已瘥，左脉尚弦数，述患经一年，曾经期至如崩，现尚早而如崩，腹中痛而胀，口渴，是可知其血之热而不摄。", "7119": "咳嗽背冷，身上觉胀，脉弦浮，舌净，当属肺胀，用上焦法。", "7120": "久嗽舌黄，脉弦数，气急发热，当属伤风带起肝气，又有重感。", "7121": "大流鼻衄，甚至成桶，今已止而面色痿白，耳响，两太阳痛，腰酸，舌黄，脉弦细，当用甘寒肺金。", "7122": "又外感，脉弦细，仍属少阳症，已有三日。", "7123": "两耳停痛且聋，而又痛响作泻，以肝胆法，耳痛已去，惟尚流脓，即腹痛亦去，而口渴作响，改为水泻，脉尚弦，再以风木法。", "7124": "十八龄咳嗽失红，已有两年，寒热已有十月，舌黄，咽中曾经艾炙，肋痛腹中痛泻诊脉浮弦小数。大抵五月间起病，初时由于暑风湿热，久则传入厥阴，清金平木法。", "7125": "胃中痛先流涎，呕清水味酸，每发如此。现尚不发，惟嗳气，舌白燥，胃不开，诊脉沉涩，法当滋肝舒气。", "7126": "作泻已有四个月，舌黄，口微渴，腹响，诊脉平，小溲如常，是当调其脾胃。", "7127": "冬温十二日，舌中间灰色，两边白滑（是湿体故滑，）大便作泻，喉痛，述口舌燥，是仍在肺阴，怕热而不寒，可用甘寒法，手牵动，足筋痛，易于发怒，是仍属肝风之动，舌尖红，是心经之虚热。最怕作蒙，查清金可以制木，而肺与心同为上焦，再拟生津去热，复入利水之药，小溲清长，其病自愈矣。又脉沉大而滞，是湿体之象，数属化热，而大属阳脉，于病不悖，若小溲一长，其从无汗泄者，即可得汗而解。", "7128": "正月二十六日起，寒热咳嗽痰红，脉弦细，舌白，口渴，气急。此属风温失红（三月初一日）", "7129": "风温十天，咳嗽作泻，腹痛，舌黄口渴，脉弦数，是已化火，尚冷作热，当表里均解。", "7130": "初时喉痛，作冷作热，已有十日，欲呕胸肋痛，咳嗽，尚无汗出，脉弦细，舌黄，是少阳经感风热，当用逍遥散。", "7131": "风温后又感风邪，致作冷出汗，舌白，脉弦，再当甘寒。", "7132": "风温后，邪已净，惟胃不开，稍有咳痰，两脉甚虚。", "7133": "腹腰作痛，期早而多如崩状，脉弦大，当调其肝。", "7134": "身已凉，大便已解而不畅，惟咳嗽与痰气急，咳时肋尚痛，舌苔尚黄厚，口燥而不渴，六脉弦小数，多梦话，再当凉肝息风。", "7135": "身热三日，出冷汗，咳嗽有痰，胃不开，口燥头眩，诊脉弦，当用甘寒。", "7136": "久经失红，咳嗽右肋痛，总怕失红复起，少寐即血分之虚，脉弦细，再当清金润肺。大抵劳力持重之体，未有不虚者。", "7137": "咳嗽失红，虽从去年发作，然昨诊六脉弦数，决其出于肺脏。今日述胃不开，逢食即吐，不能起床，势必夹有风温。拟再用风温失红例治。", "7138": "自七月间起病，初时间日，今成两发，小溲赤，足酸，腹中痛，肋痛，诊脉弦细，当属厥阴大疟。", "7139": "夜多盗汗，舌黄滑，大便溏，胃亦不开，诊脉弦小数，当益阴调土。", "7140": "寒热十三日，胸胃塞痛，脉弦细，当用逍遥散。", "7141": "二月上旬身热，今已凉，咳嗽多痰，冷汗，舌黄口燥，大便溏，气急，诊脉弦数，当属风温，久则化火之候。", "7142": "喉痒燥则呕，间有稀水，味不酸，头筋胀痛，腹胀，脉右手调，左手有数意，舌黄，大抵湿热为病。", "7143": "风邪解后，尚有余热，诊脉稍弦滞，舌黄，干咳作空呕，出汗。拟用甘寒以解余邪。", "7144": "湿疟用温燥脾经已效，第疟症虽口渴，亦当用温，况舌黄而滑，脉未滑利，据理仍当温燥中焦，兼以通阳。", "7145": "舌白体肥，胃不甚开，大便易溏，或时作嘈，诊脉短涩。在抵脾胃多湿痰，拟祛痰益脾。", "7146": "伤风日久，痰黏喉中有声，脉弦，当用甘寒法。", "7147": "暑邪二十二日，舌上已有雪花，六脉弦大，是属病久阴亏，断无下攻之理，乃以制军伤其脾分，据书速须救阴，今且呃逆，是肝气亦起，病属棘手之至。姑拟救法，合否乞高明裁之。", "7148": "生地炭（六钱）炒白芍（三钱）生苡仁（五钱）清炙甘草（三钱）炒麦冬（一钱半）炒怀药（五钱）阳春砂（八分，同煎）陈皮（八分）地骨皮（四钱）旋覆花（三钱，包煎）此复脉加减是救法。", "7149": "诊脉惟右关已起，各脉欠有精长之象，大抵病后不复元，虽冬令脉宜静小，第总由血不应脉，再拟两益肝脾。", "7150": "怕冷去，咳嗽亦瘥，痰有，舌净，惟胃不开，诊脉弦小，当用甘寒法。", "7151": "头胀，背间怕冷，腰肋咳时作痛，胸膈塞闷作呕，诊脉浮微，右手中部稍数而涩，舌净，当属肺邪。", "7152": "用白虎汤瘅疟已减，舌黄退而未净，头眩腰足重滞皆去，脉服虚小皆去，而尚数，中沉之滞大已除，大便溏，小溲长，口渴去而燥，再拟凉肺通溲法。", "7153": "风温身热退，昏语去，泻止，惟尚咳嗽有痰，脉尚弦，胃口不开，当用甘寒。", "7154": "身热七八日，咳嗽有痰，水泻腹痛，有昏语，口大渴，舌鲜红，诊脉弦小数，是邪在心肺之间，当用上焦法。其泻在肺，与大肠相表里也（上焦以邪入心包为重症。）", "7155": "病久属虚，逢劳则发，谓之劳复，古用补法，今脉虽数，而沉虚作冷，因乎坐久，责之阳虚，第筋骨作酸，总属血事，再拟归脾汤加减。", "7156": "十三龄室女，去冬患下焦肝痛，六脉弦数，当用张石顽先生法。", "7157": "肝痛在胃，已有月余，舌苔，脉弦数，怕冷，当用河间法。", "7158": "休息痢已有四年，用药痛尚在，而已少解，脉尚弦，舌尚黄，再当前法。", "7159": "咳嗽已去，惟右乳曾经作突，嗣后则成小疮，今则延走乳上近腋下，诊脉弦小，此属肝风郁热。", "7160": "寒势往来，已有半年，头痛，冷汗，咳嗽，腹作痛泻，六脉弦小细数，无汗者用逍遥散。有汗者当以清骨散。", "7161": "五月先肝气作痛，后即咳嗽失红，且腹痛作泻，或如痢，或水泻，舌黄脉弦，少有寒热，鄙见总当用清肝法。", "7162": "休息痢已有四年，尚腹痛，胸腹与足皆肿，解出如墨水，脉弦细，当属痢在厥阴。（两剂已效。）", "7163": "因跌胸痛，业经呕出瘀血多，多乃不当必泛作呕，或痰或饮，诊脉弦细，是当调其肝胃。", "7164": "病经月余，舌白，腹痛作溏，气急，咳嗽痰多，夜汗，此属冬温失治致此，诊脉弦小，当用外寒内热之法。", "7165": "腹痛响作泻，以风木法，泻已止，而痛尚未去，舌净，诊脉左关当起，是肝气之未净也。", "7166": "久嗽声哑，痰臭脉大，当用甘寒。", "7167": "重风温已有六日，咳嗽气急，口渴舌黄，背冷自汗，诊脉弦大，当用辛凉。", "7168": "曾经失经至年余，现在寒热往来，口苦，胸胀欲呕，咳嗽，诊脉弦细，舌净，是属肝病。当用清骨散法。", "7169": "肝风射肺，既经嗽血，又复痛泻，脉弦细，再当用土中拔木法。", "7170": "胸中痛，胃下开，脉弦数，当用河间法。", "7171": "八月间初发疟，属间日至，今仍间日，盗汗，诊脉左手弦大，右手弦，是久疟必虚。又汗多者，求无汗而愈，当遵柯氏法。", "7172": "高年素有咳血，兹又发作，肋背抽痛，痰中带血，脉弦细，舌白，有寒热，当用肝风射肺法。", "7173": "产后左手脉应细虚，而右手弦大，喉燥，肌热，动则有汗，肌肤作肿，当属血虚，肝风为病。产已弥月，身子尚未干净，服药后经多且旺，其色红，间有黑块，恐日久致成崩漏也。", "7174": "目科分五轮八廓，若现物不清，是肾轮之事，方书以目力之衰，以石决明五味子同用，可使目视得力，用之颇效。惟脉弦细，药不宜过重。", "7175": "大疟后，咳嗽，舌黄，盗汗，腹痛响泻，脉弦大，当属出于厥阴。", "7176": "肺疟无补法，久则必邪不净。兹身上有汗已透，而头上尚不至流，诊脉右手尚弦大，左关独数，胃口两便均好，鄙见总属肺疟。", "7177": "六脉滞大，大便作溏，掌心作热，当属肺分有湿热，嗜卧者，即其征也。", "7178": "肺疟寒热已去，而大便响泻，初时痛，今已不痛，今日舌苔尚黄，脉弦数去，而右手滞大，左手已有滑利之象。大抵暑净而湿热未除，再从肺治。", "7179": "冬温后，尚有余热作躁，脉细数，右关少带滞象，舌黑苔已浮起，两边黄去而微白滑，喉燥喜饮，面色红，左太阳与目牵痛，耳孔痛。吴氏以温邪治肺，余热由于肺阴之虚，故曰根生地，可以除血中之热。此症由于病中经至，血分更虚，所以从无汗出，法当滋其肺阴。阴分一滋，则表里皆辍矣。至目牵耳痛，总属夹有肝风与火，再拟滋肺阴，息肝风火。", "7180": "感风在肝，业经出汗，且有冷汗。然六脉弦数，舌黄燥，有肺分之热邪未净也。小溲有时黄，大便亦有时溏，今年秋暑太酷，未必不夹有湿邪也。", "7181": "出瘄已有三日，舌黄无嗽与泻，惟身热大汗，背上已见，脉弦滞，当托风热。", "7182": "瘄后已无余嗽，惟素泻仍有，乃又有寒热，无物不呕，舌黄薄，诊脉弦数，较前已大，当属肝阳之犯胃，即作呕。亦当责之风木乘脾，脾胃两受，是木邪之盛，当先除其呕，与喉梗胸痛，进退法。", "7183": "瘄后身初凉，大便溏，咳嗽痰少，知苔少，胃不开，脉已缓，再从肺治，甘寒法。", "7184": "身热已有四日，昨日已三天，有汗，是逢年经得泄，即瘄轻。今日诊脉尚数，当未净，面色红，喉痛，舌上无苔，当用肺风热法。", "7185": "久泻舌净，腹中响，间有作痛之时，诊脉弦数，是必有肝脾。然响较多痛少，泻如水，是脾虚甚，再拟舒肝扶土法。", "7186": "出瘄已满月，而又受风，身热有汗，头胀舌燥，口夜间渴，小溲热，诊脉弦数，已有四日，舌微黄而燥，腹中有时痛，拟辛凉合甘寒法。", "7187": "瘄后脉虚，舌尚黄，大便素有泻病，是肾虚。当先祛外感之风热下移。", "7188": "经停三个月，曾经患暑邪十五日。今邪净胃开，而六脉弦大，稍有数意，是素属阴虚有热之体，若以孕论，脉欠静缓。大凡孕脉，初时喜静小也，过于有力，每服不稳。兹尚未确，宜以凉滋肝分。", "7189": "舌黄，胃不开，脉滞，因食面而作泻，南面善助湿热，且动肝气。拟除面积，兼以调胃。", "7190": "今日右手颇有收敛之象，而关脉颇滑利有神，左关较前亦当收小，是属震象矣。兹惟有时腹中痛，且胃胀，再拟调肝保元法。", "7191": "凡出瘄，叶氏曰，须按时令治之。春令用风温法，风温净则风瘄自已。兹已六日，身热五日后出瘄，以背上有为齐，大便泻，舌燥白，诊脉弦数，当用辛凉合甘寒法。", "7192": "诊脉涩且大，左手尤涩，涩属血虚，当益血分。", "7193": "凡病之起于产后，总属虚症，以去血过也，转侧则淋如注，而大便之难，古人每以益血润肠如攻下，殆今之产科每不知也。至肠上下有块，按之不痛，属肝气之不舒，自觉气闷，不能消遣，即此再拟前法加减。脉弦是肝病之象，蛔虫属肝，虫由于湿热。", "7194": "胃口稍减，由于饭时淘气，且致左肋下作胀，转矢，气不畅，诊脉稍数，舌苔右黄，当以香砂法加减。", "7195": "暑邪五天，舌已黄，晚间作热有汗，热甚则言，脉左手尚数，右手已缓，适逢期至，当用热从血泄法。", "7196": "气急咳嗽无痰，汗甚多，诸筋抽痛，饭不得下，诊脉浮弦，口渴，小便热，是属肝喘。", "7197": "咳嗽舌黄，已有十日，下午作热，脉弦细，两肋痛，当属肝风之妨肺。", "7198": "痛泻已去，寒热亦减，舌净，脉仍弦，再当调肝，述腹中有块梗痛，胃不开。", "7199": "寒热往来，头痛胸肋痛，咳嗽气急，舌黄，已有五日，脉弦细，口苦欲呕，当属少阳受风之症。", "7200": "六脉全芤，妇人崩漏，兹小产后，血分大虚，故有此脉。冷气上冲，丹溪曰：凡自觉冷者，非真冷也，此属肝气之逆。", "7201": "六脉已起，胃口亦开，是病已净尽，若论补法，则惟凉滋肺胃，是热病之后路。", "7202": "肺气感冒，三日是半经，业经大汗，据理应凉净，若未净，当再三日，然亦无大苦，有汗者，不应再汗，况头眩足滞痛皆瘥，脉数已流利，拟再清肺。", "7203": "右脉已滑，有力有神，左寸亦然，惟左关尚涩，是总由肝血之虚，再当补其肝血，兼以养络。", "7204": "诊脉甚流利而缓，缓即属脾脉之本象，所谓脉贵有神者即此，非可进热，再用益阴健骨法。", "7205": "发时纯热，口大渴有汗，总属瘅疟。今日移早，疟本将愈，惟不令出汗，明日须再至。饮后胸微胀，是水不速下，舌苔较昨厚，仍微黄色，口喉燥甚，是热伤肺津。白虎汤本生津去热之药，祛热生津，于病本合，先有头眩肢重，本有湿热痰，脉数不滞，断非伏暑，再拟白虎汤复入祛湿消痰，兼以生津。", "7206": "用白虎汤后，大热大汗已止，舌苔前半已去，而根尚有黄色，口苦且腻，掌心尚热，小溲赤，诊脉左手已小，右手稍有滞象，惟皆数，数属邪未净，想瘅疟由于暑邪之在肺，再拟肺入法，惟素有湿邪，复入祛湿。", "7207": "昨日又劳，今日又有寒热，舌黄口渴脉数。凡寒热，有出于肺与少阳胆者，有出于肝者，有出地募原者，有出营卫之和者，今逢劳则发，当责营之卫不和，出汗大便溏，卫病也。干呕或有清水，肝病也。今日先拟调和营卫法。", "7208": "舌净脉平，惟鼻间尚有红色，当益其阴。", "7209": "伏邪论每至下午，或纯热，或纯寒，或寒热相间，日日如是。今身热三日，凉后第六日又热，第七日出汗身凉，诊脉已缓，舌白燥，小溲赤短，是汗后。书以汗多者禁利小便，口味淡，胃火未净，口气亦然，鄙见仍属肺分受风化火之候，头不胀，胸不闷，脉虽滞，腰腿虽酸，总非伏邪。再拟清凉肺胃法。", "7210": "肺风感冒，身已凉，舌已净，脉小数，口渴少寐，头眩痛瘥，指木腰痛，呼吸腰间痛，是筋中病，大便不解已有四日，是夹有劳乏。", "7211": "前日寒热头胀，今日又冷且战后热，热时无汗，头上与身尚觉木，腰背穿痛，舌黄滑，诊脉两手皆滞，书以木属湿痰，合脉怕作伏邪，第冷时作战是疟象，而疟属肝分。拟用肺分法，勿用小柴胡引贼也。", "7212": "肝风齿痛月余，右肿去而左又肿，头额痛，诊脉尚弦，总由血虚生风。", "7213": "由瘅疟后，带起胃湿热邪，现在舌黄已减，而根未除，目筋尚红，鼻柱色膏，卧不安口巳燥，而食后水运，诊脉稍有滑象，是湿热未罢之候，祛疾务尽，再用前法。", "7214": "失红右肋下痛，舌黄，大小溲均热，诊脉右手弦，左关独起，是必由于热伤肝络。", "7215": "身热出汗，小溲赤短，头痛且眩，两足滞，诊脉浮弦数，已有三日，尚渴，身上不怕冷而热，舌上无苔微白。书以无苔者邪在肺，身热有汗者属风，头尚痛者邪未净。头眩者湿痰，两足滞两手木者，亦属湿痰。拟祛肺分之风热湿痰。", "7216": "今日诊脉皆起，惟欠长，且有数意，总属血分之虚。张氏书以脉洪大者可重用地黄，惟脉小者不能，以脉小为不能载重药也。再拟前法。", "7217": "诊两手脉皆滞，舌苔根黄厚，头胀虽瘥而未除，胃开气冲，至喉作痒而干呕，所患者是肝胃不和，头胀是阳气不达颠顶，故有起落，而据脉与苔，恐有湿病之起，故以越鞠丸加减。", "7218": "间日疟后，胃开脉弦数，舌黄，想间日疟后，仍当温肝，惟夹有外风在肺，打嚏咳嗽有痰，喉中觉热，复入清肺可耳。", "7219": "右边肋间穿痛，且痛时作嘈，必欲食之，诊脉弦细，舌中黄，是属络中肝痛，而夹有胃热与痰。", "7220": "齿痛已有月余，大痛亦三四日，两太阳痛，诊脉数，舌白燥，当用肝分法。", "7221": "感风出瘄，已有五日，业经有汗，无须辛期。舌黄，口渴。脉数，当用凉剂，且素属火体，是气有余，血不足，兹姑先祛外邪。", "7222": "伏邪十日，冷颤虽去，汗虽有，而小溲未长，口中尚腻脉弦滞，当清其肺湿。", "7223": "寒热已有三四日，头胀咳嗽，小溲赤，脉右寸弦浮数，当属上焦暑风，因新感风寒引起。", "7224": "先泻十余日，止后反腹痛，且有寒热，脉滞大，是皆湿热不得开廓之故。", "7225": "前日受寒，昨日先冷作颤，热转神昏，至今早始凉，此刻诊两手脉弦细，舌白口苦胃不开，是邪尚未化火，怕成疟疾。", "7226": "下午发热，不作冷，汗不透澈。脉数弦，舌黄，口不渴，小溲赤，已有两三天，当属伏邪之轻者，当用上中焦法，五日可望解，十天可已。", "7227": "胃中梗塞，或酸或苦，无物不呕，已有三月，舌黄厚，脉弦细，当属肝阳犯胃。", "7228": "伤风，脉弦滞去而稍数，舌仍黄，耳响聋。咳嗽与痰尚有，再当前法。", "7229": "感风肌热已久，今已有汗，而舌黄口燥，咳嗽痰如水，喉痒，诊脉弦数。据书风温日久，表里均热，当用甘寒。", "7230": "少腹痛，气升作呕，诊脉两关尺独大，咳嗽多痰，患经四载，此属奔豚，当用石顽先生法。", "7231": "外感去后，带起肝痛作呕，口渴，脉弦数。", "7232": "诊脉沉弦，五更腹痛作溏，当用建中加减。", "7233": "厥阴大疟自愈后，左肋生有疟母且多，咳嗽痰少，诊脉右手已调，右关弦数。大凡疟母，久则必失红，且块形日增痛，今已患有咳嗽，岂已愈之事，故用薛氏法八剂未效。鄙见仍须进之，药足其疟母自消。", "7234": "三吴古多良医，明清之世，松江李中梓、常熟缪希雍、吴江徐大椿、吴县叶桂、元和陆懋修，闻望著述，后先辉映，虽所诣有纯驳，可谓卓然能树立者矣。其后乃有无锡张聿青先生，先生讳乃修，父工医，先生少承家学，益孟晋，醰思博稽，以仲景之书为宗，而斟酌刘李朱薛诸家之说，论病处方，变化万端，非姝姝守一先生之言者。平生论述甚多，散佚不存，仅得其诸论一二，其论霍乱云、霍乱热多寒少，孟英固自言之。但其论寒热二证，有一定之据，如热病则于未病之前数日，先有目中溜火肛门灼热等象。然历见患病者，一吐一泻，无不肢冷黏汗，脉伏不起，大烦大渴，螺文缩陷，甚则失音目陷，虽投白虎得生之热证，未必于未病之前如孟英所云也。而投理中四逆得生之寒症，未必不烦不渴，神情狂越，与热证相似也。村医每见肢冷脉伏，不问口渴，不验舌色，妄投四逆而霍然向愈。亦有肢冷脉伏，大烦大渴，渴而能饮，投白虎地浆而竟毙者。余以三十年阅历，始知热证于未病前先见火象之说，殊难为信。惟一经芳开，热象发现，对病用药，方无误治。盖热症有湿邪外遏，寒证为阳气闭塞，芳开之法，亦分温清。然热证而投以温开，亦可透发，寒证而投以清开，则反凝涩，此大害也。尤可恶者，随意呼名，如绞肠、吊脚、瘪螺之类，霍乱之甚者，螺文无不瘪，经云、卫气者所以温分肉，充皮肤，肥腠理，司开合者也。霍乱则卫气闭塞譬如纳手于水，湿气抑遏卫气不行亦致螺陷，即此意也其论燥曰、秋分以后或病咳热，或渴或否，其变险也，气喘痰鸣，痰厚而稠，毙者甚多，论者目为风温，此燥症也。秋令久燥，金乘所胜，所不胜来复其克金也势若燎原壮火食气，则肺气伤火烁津液则肺阴伤。黏痰即被熬之津液也，然痰色多黄则又挟湿火为燥之复，气湿即燥之化气也。吴鞠通谓伏气为火，化气为湿，复而且化，故痰兼湿黄化少复多，故湿不能济其燥。是知复气伤肺，由内而起之枯燥，与天气清冷之燥，判若霄渊有舌可验，有脉可凭，有象可稽也。晚年居沪上，名益重，远方求治者踵相接。当是时，天下大医，群萃上海，青浦陈莲舫、武进费绳甫尤著，其人善夤缘冒进，借声势，或称御医以撼庸俗、饵高糈，然其术亦浅。无虑内伤外感虚实寒热，一切以不关病之药，羼孴成方，以尝试而已。先生初至少知者。一日林某喘作，人有言先生至，御医陈莲舫在焉，慢不为礼，视其方皆玉蝴蝶溷沌衣厚朴花等一派似药非药者先生曰、下材浅薄请有所问，厚朴花性味何等也陈曰、本草详之耳。曰、本草多矣。若某某若某某，吾皆诵习之，未见有此药也，敢问何出。陈语塞，久乃言曰、大约与厚朴相似耳。先生正色曰、愿君诫之。治病非儿戏，陈唯唯不能答。先生遂定方，用熟地肉桂等。陈与病家皆难之。先生毅然曰、如不信，啜二之一，夜半知，明日继进，失事抵吾命可也。如其言尽剂而安。由是论者翕然，佥谓先生之学，实有本矣。今略述其他治案以备观览。朱葆三病脘痛吐涎水。脘中漉漉，得呕而快。西医治之不效。先生曰、此水饮伤胃也，乘其元气未虚，尚可攻逐。用半夏黄连干姜腹皮茯苓枳实竹茹控涎丹，服后泻出冷水，呕即平复，用苓桂术甘加椒目数剂，脘舒溲行，尚有嘈杂，用芩连橘半桂芍蒺藜杏仁，通降抑木而瘳丁姓温邪大热大渴，烦躁神昏红疹隐约，医用羚羊牛黄等剂不应。先生视其目不瞑，知有痰浊，加远志竺黄，病不减，再诊舌绛中有薄白，时嗳气肢冷知为湿遏热伏，改用三仁去朴，加黄芩知母菖蒲，躁闷大退，红斑遍发，用化斑汤重用犀角石膏而愈。龚氏妇咳嗽吐血咽痛失音，内热口燥，诸医投养阴法无效，日羸削，先生询其病得之感寒，瞿然曰、此谚所谓寒包火也。投麻杏甘膏蝉衣象贝桑叶茯苓黑归藕节，咳退音清，继进清咽宁肺而安。劳某，不寐经年，某名医谓虚阳不敛投养阴法及珠粉，屡服二十剂，胸闷胃钝，仍不得寐。先生曰、此痰火也。予温胆汤而瘳。杨子萱湿温三候，汗㾦不得畅，背脊恶寒，热势起伏，群医束手。先生曰、此宜坚壁清野法，勿犯谷气以郁金杏仁桔梗藿香薏苡通草滑石半夏等连服使邪与湿分气行汗畅而愈。粤商林不纳不饥便闭四旬一行医谓阳虚，进苁蓉肉桂及半硫丸仍不效。先生曰、此胃阴虚也。投甘凉而痊。巨商丁剧饮后醉而不醒。搐搦痉厥，医谓挟阴伤寒先生曰、此酒热引动肝阳耳。与咸降法一剂知二剂已。龙湛霖患不寐，他医初投温补，继以育阴，皆不验先生曰、此痰热内阻心肾不交也。用玳瑁珠母龙齿羚羊胆星半夏栝蒌竹茹，二剂病失。方维卿痢剧发呃，七日夜不止，将治木矣。先生诊其脉沉弦，审知有脘痛病，用泻心加黑白丑丁香，一剂呃止复用清六饮加二苓薏滑香砂琥珀，痢亦止。凡先生治验，就所知者止此，及门百人，或更有悉其详及神于此者，要其剖析豪铓，洞彻症结，原本经论超然神解，不外乎此先生卒年六十余，至今称张氏医法。", "7235": "黎（左）气虚多湿之体，加以劳顿掣动阳气，致阳气挟痰上升，清旷之区，灵明之府，悉为浊所弥漫，以致神情呆顿，迷沉多睡，右手足运行不利，口眼㖞斜。脉弦而滑，苔白质腻。此由肝气挟痰，阻于心脾之络为类中之症刻在鸱张之际，恐阳气复上而不语神昏，痰从内闭姑先开窍涤痰，以备商进。", "7236": "二诊神情略为灵爽，沉迷多寐之象，亦觉稍退，脉象柔和，未始不为起色。但右手足不能运用自如，口眼㖞斜，舌强言蹇，不饥不纳，时见嗳噫，似呃非呃。右关脉沉滑有力，舌苔白腻，中心焦黄。浊痰之弥漫，心窍之闭阻，固得稍开，而火风鼓旋之势，尚在炽盛。总期药能续效，风火庶可敉平耳。方草商之。", "7237": "七诊脉症相安，病势逐日减退，幸矣幸矣。但饮食起居，急宜加意谨慎。若稍有感触而至复中，则非才疏者所敢许治。", "7238": "冯（右）肝风挟痰，中于府络，骤然手足偏左不遂，口眼歪斜，言蹇舌强。若以中络而论，尚无关于大局。但心中烦懊，烙热如燎，时索凉物，有时迷睡，神识时清时昧，呃忒频频。脉弦大而数，舌苔白腻。府络既阻，而痰火风复从内扰，神灵之府，为之摇撼，所以懊𢙐莫名。痰在胸中，与吸入之气相激，所以频频呃忒，饮食不得下咽。若再复中心络，必至神昏不语，诚极险又极可虞之际也。勉拟清镇护神，以御其痰火风之直入，再参降胃化痰熄肝，即请商酌行之。", "7239": "二诊神迷转清。烦懊较定，痰得咯吐而出，未始非松动之象。然心胸之热，虽减于前而犹团聚不化，时带呃忒。脉形弦滑，舌苔厚浊。眩晕不能转侧。火风挟痰上旋，犹恐发痉发厥。再泄木火以清痰热。", "7240": "三诊心中热炽，日见轻松，舌强短缩，已能伸出牙关，略能进食，身体转动，略为轻便呃忒亦减，种种转机之象。泄热凉肝化痰，固属一定之理。但头昏眩晕，略一转侧，辄昏昏欲厥。脉形弦大。肝火风鸱张不熄，恐阴分劫烁，而舌起糜腐。", "7241": "四诊昨诊痰火风劫阴，恐舌起糜腐，实症变成虚症。今诊脉弦大渐转细弱，舌胎果起白腐，上腭两腮，均布糜点呃忒虽止，而多言妄笑五志之火，尽从上亢，而真水欲竭，不能相济。一波未平，一波又起，恐药力不足抵制。勉拟救阴泄热，清护神明。", "7242": "五诊糜腐较化，多言妄笑稍定，略思纳谷而食入中脘作痛。脉细弦转大。阴分稍复，而火风鸱张之下，风木干土。再育阴化痰，兼平肝木。", "7243": "十二诊平素偶服参苓，辄胃纳加增，神情振卓，其阳明中气之虚，未病先露。此次病发，忽然眩晕，左肢不遂，病发于左，口歪于右，一时神识昏乱，多言妄笑，不时目窜发厥，呃逆频频，显系火风挟痰上旋，乘阳明脉络之虚，抵隙而入，首方言中于府络者，即阳明大府之络也。叠进降火消痰熄热，火之内扰者渐平，风之上旋者自熄，眩晕由此而定，神情由此而清，发厥亦由此而止。岂知痰热甫平，而虚火挟湿上腾壅于胃口，以致通口糜腐，危险之境，较前更甚。遂导热下行，兼用外治，糜腐次第而退，脉弦滑得以渐柔，饮食渐次而进。惟左手足不能举动，不知痛痒。吾人左半属血，右半属气。左半之血，还行于右是为气中之血。右半之气还行于左，是为血中之气。今风火郁阻络中，左血虽得右行，而右气不能左入，则偏左半身有血无气，所以望之如常，抚之无异，欲举而动之，则无气以运也。无气以运，欲动得乎。其祛风舒筋活络之品，似为必用之药。殊不知风不自生，血不行然后生风也。筋络不自病，有所以阻之者，然后筋不舒而络不宣。则是病在经络，而病之本实在阳明之络空，火风阻之。经云、治病必求其本拟通补阳明化痰清络。", "7244": "徐（左）体丰于外，气弱于内。气弱则饮食酿痰，阻于心脾之络，风阳挟痰，乘势内煽，遂致舌强难言，右手足运行不利，神呆悲感，不能自主，喜笑无常。苔胖质腻，脉左弦右滑，而不分明。痰得风而愈炽，风挟痰而益旺，类中之渐势恐复中变生不测。姑拟补气之不足泻痰之有余，佐以熄风宣络冀神清为幸。", "7245": "陈（右）年近古稀气血亏损，虚风暗动，心胸牵及咽喉热辣，环口作麻四肢运用不便。脉象虚弦舌光无苔。为类中根源。惟有培养气血，作保守之计。", "7246": "朱（右）先自肝阳犯胃，呕吐不止，继则神昏发厥，左手足弛纵不仁，右手引动不止，目开手撒遗溺，舌伸不收。脉象虚弦。此由呕吐太过。阳明胃液耗残，遂致肝风乘阳明脉络之虚，猝然中络，胃脉通心，神机因而不运。类中之症，虚多实少。勉用救阴熄风，以尽人力。", "7247": "某偏右不遂，舌强言謇。脉象弦滑少力。此气虚挟痰化风中络。", "7248": "王（左）四肢不遂言语謇涩。脉濡而滑。此气虚而湿痰入络。类中之症，难望近功。", "7249": "二诊中湿之后，络隧未和。温通和络泄湿，脉症相安，守效方出入再进。", "7250": "何（左）痰湿素盛，于五日前陡然口眼㖞斜，左手指伸屈不利。左关脉弦，右关脉滑。此痰湿阻于阳明之络，类中之先声也。急宜戒饮，以酒性上升而热故也。", "7251": "二诊脉症相安，然手仍带肿，经谓湿胜则肿。究之诸病之作，皆风火之所为也。", "7252": "尹（左）语言謇涩。脉象左弦，右关带滑。此惊痰入络，机窍被阻，中厥之先声也。", "7253": "陈（右）高年精血亏损，肝风鸱张头晕心中震痉。脉细弦尺涩。为类中之渐，图治非易。", "7254": "左脉象弦滑。左臂作麻。此湿痰过盛，营卫之气，为之阻蔽，有痱中之虞。", "7255": "某眩晕耳鸣，四肢麻木。脉形弦滑。此胃有湿痰，胆木不降，有类中之虞。", "7256": "左左半主血。然血中无气，则血不流。今左臂作麻。脉形弦滑。无非痰湿阻遏，荣卫不宣。仿石顽法。", "7257": "三诊投剂之后，脉症相安。然四肢酸软，筋惕少寐。良由痰湿阻络，甲木之气，不能下降。前法出入再进。", "7258": "右脉濡滑，左关微弦。面色浮黄，四肢酸软，心悸少寐。此由中气不足，湿土生痰，郁阻络隧，为痱中之根。", "7259": "陈（右）风温八日，身热咳嗽，左胁作痛，日来神昏不宁，甚则迷昧，气升痰嘶，痰色稠黄，齿垢颧红，自汗渴饮。脉数浮弦，舌红苔黄。日前痰中屡屡见红。此由风邪化热，灼烁肺胃，所有津液，尽为火热熬炼，皆化为痰肺为热炎所熏，肺叶煽动，有喘厥之虞。用竹叶石膏汤加味。", "7260": "二诊情神之迷昧较清。舌苔亦化，气升较轻，然痰仍黄厚，痰声如潮。脉数弦滑。肺胃为热所灼，津液尽化为痰，痰随气升，气随痰逆。前意参上病下取法。", "7261": "三诊上升之气，大为平定，讝语亦退，烦懊亦减。虽已出于望外。但脉象滑数而软，舌苔浮糙，上腭糜腐星布。痰热化火灼阴，一波未定，一波又起矣。再化痰热，参入甘凉。", "7262": "四诊痰喘渐平，热亦大减而白腐渐多，却不甚作渴。脉形软滑。阴分亏损，浊随气火上浮，虚多而实少矣。急和其阴，而参清化气热。", "7263": "五诊痰喘全平，腐糜忽少忽多。舌质呆紫苔，淡黄而掯，望之干毛，却不燥渴。胸次如哽如阻。脉形软滑。此的属阴分伤损，浊蒸不化。治多棘手。勉再以清化并行法，以图万幸。", "7264": "祝（十五岁）饮食内伤，时邪外感。从泄泻而至发热，热势甚炽，纤毫无汗，神情懊烦，频渴不多饮。脉象郁数，舌红苔黄罩灰。此由邪湿相合，三焦均受。恐邪湿交蒸，邪化为火，而湿化为燥。用薛氏升泄法。", "7265": "二诊用薛氏升泄之法，便泄稍减，咳嗽增多，热势渐减，苔灰大化。虽属转轻之象，而未得汗邪无出路，所以热仍不解，心中时觉𩠎烦。病起之际，即耳窍闭塞。良由脾土素弱，所以感受风邪，上阻清窍，下趋大肠。但风脉必浮，今脉不以浮应，似非风象。殊不知风在表则浮，今风入肠胃，病既入里，则脉不以浮应矣。仿喻嘉言先生逆流挽舟法。", "7266": "三诊引邪外达，正气虚微，不能托送，未能得汗，便泄有黏腻，色白带赤，热势得见退轻，而迷沉欲寐，有时夹杂谵语。脉象糊滑，重按少力，苔黄，近根仍带灰润。此由中气不足，外感之风，氤氲之湿，熏蒸之热，炼液成痰，弥漫神机。里虚内陷之象，恐神昏发痉。拟扶助中阳，兼清湿热而化浊痰。", "7267": "四诊昨进扶助中阳，兼清热而化浊痰，热势发扬于外，表热稍甚，迷蒙较退，时觉懊烦。自病起至今，耳窍闭塞，今则时兼谵语，口渴欲饮。舌红，后半灰霉，脉象稍起，而软数微弦。风燥之气，上阻清窍，而风与湿合，遂成熏蒸之局，神机为之弥漫。恐邪不外越，复从内窜。拟清化法。必得邪从外越，方是退步，然不易也。", "7268": "六诊疏泄风邪，清化气热，便泄渐定，解出溏粪带黑，热之象也。风为阳邪，不从外越，从中化热，热灼肺胃，咳嗽不爽，懊烦不宁。热扰神明，言语妄乱。热劫津液，神机不运，所以不为烦懊，即为迷睡。阳明热胜则目赤颧红，口渴欲饮脉数微弦，舌红苔色深黄，根带霉黑。种种见端，皆风邪化火劫烁阴津之象。症方一候，邪势鸱张，恐阴津日干，而神昏发痉。拟救阴泄热。", "7269": "七诊脉象沉细软弱，较昨稍起。神志较清，懊烦略定，迷睡略退，咳嗽增多，痰出黏腻。舌红稍淡，灰霉略化阴津渐回，而喉有痰声。良由津液为热邪所炼，即化为痰，前贤谓痰，即有形之火，火即无形之痰，非虚语也。拟凉肝泄热，兼清肺胃，以保阴液。", "7270": "八诊脉渐起，咳嗽较爽。内陷之邪，还于肺胃，所以神志渐清，热势递减，口渴稍定，舌苔灰霉较化。惟仍眠多醒少，还是神机欠运，胸中之热弥漫。再泄热和阴，兼宣肺气，以引邪外出。", "7271": "九诊口渴渐定，热势渐轻，舌红渐淡，苔黄转白，灰霉渐退，右脉稍起，皆热化津回之象。理应神清气爽。而眠多醒少，仍复如前，耳聋不爽，大便不解。病之初起，原属风温夹湿，邪既化热，劫烁阴津，虽有湿邪，亦成燥火。今津回热化，燥仍为湿，余热与湿，弥漫胸中，如雾氤氲，所以眠多醒少。拟清泄火风，参以化痰。", "7272": "十诊昨进化痰泄热，咳嗽稍甚痰不甚多，而痰中带红，左颊红赤。苔霉近根全化，而舌心黄又带霉黑，大便不行。脉数右大。还是肺胃热胜。痰既得出，仍守清胃养津。即请商裁。", "7273": "十一诊迷睡稍退。胸中弥漫之热。略得扩清大便欲解不出。脉象右大。再参增液以望便行。", "7274": "十二诊大便畅行。然津液为热所耗，木火升动懊烦口渴，左颊红赤。耳鸣窍闭，咳嗽咽痒。脉数，重按微弦。风温之邪化火劫津，幸数日以来，舌未焦燥，神未昏糊。泄热存阴，似难更动。", "7275": "十三诊多眠渐退，两次得汗，咳嗽渐轻，痰亦渐少内陷之邪，仍还于表，是为正色。但热仍未解，耳聋不聪。脉数舌质淡红，苔淡黄，灰霉未尽。肺胃余热，未能遽澈。存阴泄热，并不表汗而汗自出。良以津液。来复，所以液能化汗。拟乘此疏风泄热，以望邪有出路。", "7276": "十四诊内陷之邪，还于肺胃。咳嗽身热，耳聋，音声雌腻。脉数右大，舌质淡红，淡黄灰霉之苔逐步化轻。病既由深而浅，宜再辛凉散风微苦泄热。", "7277": "十七诊内陷之邪，还于肺胃，而从汗出。耳窍闭塞已开，身热亦退。脉静苔化，大局已定。宜和中醒胃。", "7278": "十八诊脉静苔化，胃开思食。久热之下，阴津不能遽复。宜和阴益肾。", "7279": "陆（左）咳嗽不爽，发热汗出不解，气从上逆，大便溏泄。脉数右大，苔厚心黄。风温袭于肺胃，症方七日，为势甚炽。", "7280": "三诊轻宣肺气而化湿邪，每晨汗出，上焦之湿，理当从汗而解，乃日晡仍然似疟，便不畅行，腹膨脘痞欲呕，频转矢气。脉形滑数。此必有形之积，阻而不化。拟导滞兼清湿热。", "7281": "恩（左）温邪将及两候，发热有汗不解，夜甚无寐，胸闷不舒，烦渴而不欲饮。脉数，右部沉郁，左部弦大，舌红苔黄，根带灰霉。无形之邪，有形之湿，熏蒸不化，遂致清津不能上供，阴液由此渐亏。恐化燥而神机不运，渐成昏蔽。拟退热泄湿。即请商裁。", "7282": "二诊流湿润燥，参以退热，热势外扬，能得微汗，口渴大减。然大便不行，大腹满痛，频转矢气。脉象滑数。正合阳明病频转矢气之条，以丸药缓下。即请商裁。", "7283": "三诊热势递减，仍然起伏，大腹满痛，频转矢气，大便不行。脉数左弦，舌尖红绛。阴伤热恋，宿滞不达。再泄热利湿，参以磨滞。", "7284": "谢（右）辛凉疏泄，汗未畅达，热仍不解，头胀耳鸣。脉数右大。风温袭于肺胃，不能外达，三日正炽。", "7285": "二诊疏泄肺胃，得汗甚畅，邪从汗解，热势大减，胀痛渐松。苔黄较化，脉亦略缓。然炉烟虽熄，余烬未消，身热尚未尽退。还宜疏泄余邪。", "7286": "包（左）温邪将及二候，上焦之热，移入大肠，发热便泄，懊烦不寐，频渴欲饮，耳窍失听。舌光无苔，干燥无津，脉左大，重按无力。邪热不从外达，灼烁于内，阴津损伤，往往有液劫而神昏者，不可不知。拟养津泄热。", "7287": "二诊便泄已止，热势虽不甚盛，而仍神烦少寐，口渴欲饮，舌燥无津，既干且腻，右目红赤作痛。脉数左大。风温夹湿化热，由大肠还于肺胃，气燥津伤。拟流湿润燥，开泄风热。", "7288": "左时病八日，始则发热便泄，继而呃逆频频，便泄虽止，而表热入里，遂致里热神烦，频渴欲饮，面色浮红。舌苔焦黑无津，脉象细数。此由邪热不从外达，转从内陷，劫烁阴津，所以满舌焦干，气火上冲，吸气不得入，所以频频呃逆，将有神昏发痉之变。勉拟存阴救津，兼清龙相，以平其冲逆之威。能否应手，非敢所知也。", "7289": "方（左）风温两候，风化为火，火风内旋，由壮热懊烦而致瘛疭。叠经泄热和阴，火风渐平，烙热亦定，乃大便通行之后，频见溏泄，咽痛鼻红，咳嗽痰多稠黄，耳窍闭塞。脉象数大，重按带弦，舌红苔黄。沸腾之风火虽熄，而气分之热，何能遽化。风痰为热所灼，自然色变黄稠。气燥则清窍不利，自然两耳失聪。咽通于胃，喉通于肺，今肺胃两经，为风热渊薮，自然咽中作痛。大肠与胃相联续，与肺相表里，热盛之下，府气失通，肺胃之热，乘热下移，再以牛乳横助其虐，所以大便为之频泄。为今之计，惟有清化肺胃，以清肠热。与式训仁兄大人同议方。", "7290": "浦（左）咳嗽头胀发热，寤难成寐，知饥欲食。脉数而弦。风温袭于外，肝火炽于内。姑疏风泄热。", "7291": "秦（左）发热烦渴，胸闷气逆，频咳痰多，神烦少寐。脉数糊滑。此风温挟湿，郁蒸肺胃。症逾两候，恐致昏喘。", "7292": "二诊气逆稍定，热亦渐减，而脉仍滑数。还是肺胃之湿未楚也。再为降化。", "7293": "顾（左）发热咳嗽多痰，喉间霍霍有声，胸闷神烦。脉数而滑。此温邪挟湿，蒸于肺胃。七日正炽。", "7294": "居（童）先是口碎作痛，四日前忽然热起，势甚炽张，胸闷懊烦，鼻衄便泄，兹则咽中作痛。舌红苔白，脉数滑大。此风邪先袭于上，复以时令之邪与湿相合，致一阴一阳之火，俱结于上。病属风温，方在五日，邪势炽甚之际，当是易进难退之时也。", "7295": "二诊前进辛以散风，苦以泄热，汗出邪势从外而泄。而肺胃之热蕴结，痧疹并发而不少衰，痛不少减。脉数滑大，舌红边绛。喉关以内，白腐满布，喉肿关小微咳。此炉烟甫熄，余烬复燃，肺胃之热，冲斥于中，喉疳重症，出入极为迅速。恐火烁肺金，而致气喘。商请专门名家酌夺。", "7296": "三诊昨进大剂泄热，热势大为轻减，喉肿较退，痛势大轻。涎水之自涌者，至此渐能下咽。脉洪大略收火风之灼铄肺胃者，已退三舍，当乘胜而助鼓再进。", "7297": "某气喘不定，痰多稠厚。苔白转黄，舌边尖红绛，唇朱颧赤，脉数至六至以外。夫风为阳邪，阳邪易于化火，所有痰浊，尽从阳化，华盖之脏，独当其炎，所以清肃之令不行，右降之权尽失。痰鸣气喘，讝如梦语，将有耗气伤阴等变矣。", "7298": "某风温大势已解，而痰热未清，咳恋痰稠黄厚，火升少寐。右寸脉独大。良以邪热灼肺，手太阴清肃无权，则足太阴转输失职，致热蒸而炼液成痰，痰火因而内炽。鼻准清冷，乃气机之闭郁，以兼症之中，别无元阳衰脱之见端也。拟清化痰热而肃肺气。", "7299": "贾（左）症起四日，壮热无汗，肢体烦疼，头胀作痛，痰多口腻。脉数右部浮大。夫热重而至炙手，自必懊𢙐烦闷，此时尚无烦懊情形，其热之尚在肌表，显然可见。考太阳为六经之首，主皮肤而统卫气。今风邪在表，阳气屈曲不伸，故发热头疼。其所以不能作汗者，良由湿痰素盛，内壅不宣，则表邪难达，吴又可先生所谓水注闭其后窍，则前窍涓滴，此正发汗之义也。肢体之痛，左胁为甚，肝藏居左，风气通于肝也。拟于疏解之中，参入化痰，必得汗泄方能推散，然不易也。", "7300": "二诊汗出，肌表之邪，由此外达，热势大退，遍体烦疼亦止，神情亦觉爽适。但脉仍带数，热退未楚，偏左瘕积阻滞，气道失宣，气短腋痛。脉数微滑，邪势渐去，湿热未清。再舍其标而治其本。", "7301": "某风温之后，恣食甜腻，酿湿生痰，肺降痹阻，以致热退不清，痰鸣气急，不能安眠。苔白不渴，脉左大，右部软滑。心胸不舒，气弱生寒，阳不旋转。恐喘甚汗脱。", "7302": "邹（右）天燥太过，肺胃风热内烁，更兼肝火凌金，咳痰带血，沉迷多睡。脉数而滑。盖阴虚则火炽，其热势内蕴胸中，如姻雾弥漫，所以沉迷而多睡也。恐昏痉等变。从云瞻兄方中，参入扩清胸中之热。", "7303": "左风温袭于肺胃，咳嗽壮热神烦，更兼天气亢燥，温燥之邪，化气为湿，以致肺热脾湿相蒸，痰黄而稠。日来热恋不解，咳亦不止，形色瘦削。脉数小软。营气日亏，邪势留恋，若再缠绵，必生变局。治法惟有泄化邪湿，庶可保全元气耳。", "7304": "徐（右）咳剧身热，痰稠头目昏晕，胁痛神烦不寐。脉数弦滑此风温袭肺，化热内灼。适值经来，有暴喘之虞。", "7305": "二诊咳嗽大减，而仍凛寒身热，汗不多达，痰色黄厚。脉数带滑，苔白心黄。邪热郁于肺胃。夹经未净，还恐神昏气喘之变。", "7306": "二诊身热已退，而脐上作痛，大便不行。脉象沉弦。寒滞内阻，宜小承其气。", "7307": "锦（翁）由咳嗽咽痛，而致身热不解，汗出不能透渥，胸闷神烦少寐。脉象数滑，舌红苔白质腻。此风热之邪，与湿相合，蒸腾于肺胃之间。症属风湿，恐其化热。", "7308": "张（左）初起伤食吐泻，风温之邪，乘势而发，平素内伏之痰，与热相合，熏蒸于肺胃之间，以致热不外扬，咳嗽痰稠。上中两焦，为痰气所遏，则清津不能上升，口渴舌干少津，中心灰炱，小溲作痛。脉数而滑。症属风温挟痰，化热伤阴，今方旬日，恐转候之际，痰热内闭而致神昏发痉。拟清化痰热，参以救阴。即请商裁。", "7309": "二诊清化痰热，舌苔炱，燥转润，中心霉黑亦化，溲痛已退，气逆亦平，脉亦稍缓。然内热未楚，还宜清化。", "7310": "三诊咳嗽气逆已定，胃纳亦得稍起。然肺胃之间，痰热未化，气不流布，津液不行，以致口燥舌干欲饮。右脉滑大虚火挟痰，熏蒸胃口，恐起口糜再引津上升而导热下行。", "7311": "顾（右）冬温九日，发热懊烦无汗，胸膺发出赤斑，不克透露，神识迷糊，指节引动。邪郁不达，挟温蒸腾，神机为之弥漫。脉形细数，苔白心黄质腻。有内窜昏痉之虞。勉拟泄化邪湿，芳香宣窍即请商裁。", "7312": "某冬温十一朝，邪化为热，炼液为痰，郁阻肺胃，以致甲木不降，乙木独升，烦热火升颧红。气从上冲，则恶心欲吐，胸次窒闷异常。寤难得寐，惊惕耳聋，四肢有时震动。脉数弦大，舌红苔白心灰。时邪引动本病，恐风火内旋，而神昏痉厥。经云、上焦不行则下脘不通。拟开展气化，仍不失清金可以平木之意。", "7313": "左肺热津亏，理宜燥渴，昨诊并不口渴，显系肺虽燥热，脾胃仍有湿邪遏伏。所以流化湿邪，俾清津可以上承，喻氏所以有流湿可以润燥之谈也。无如风化为火，尽壅于肺叠进清肺育阴，竟如杯水车薪。热循肺系内犯膻中，以致时为谵语。火郁于内发现于外则两颧红赤，唇口朱红，红极发紫，脉数竟在六至以外。此时为之清金泄热存阴，固属定理殊不知火从风化，其热也釜中之火也，其风也、釜底之薪也，蒸热之势稍衰，釜底之薪未撤，薪在即火在，所以日前历历转轻，仍云不能把握者为此。刻下脉数，气口虽属带浮，按之似属少情。如欲解散其风，而撤其薪，以缓其燎原之势，救者自知不逮。不得已再拟清肺饮合清宫汤，以尽绵力。", "7314": "邱（右）症逾两候先发红疹，继透白㾦，又复经行邪势未始不从疹从㾦而稍泄，所以数日前病有退机，烦热口渴已得大定。然既疹既㾦，营气两液，必然暗虚。而方寸愁虑，木火升动，邪热从而转炽，烦热复盛，耳鸣耳窍闭塞，喉有痰声，俨如梦语，手指引动，少腹气坠作胀。脉数滑带弦，舌红苔黄。邪湿未化，木火暗升，炼液成痰，神机不运，有神昏发痉之虞。勉拟透热凉肝化痰宣窍。", "7315": "二诊透热凉肝，化痰宣窍，烦懊大减，寐亦略安，四肢引动较定，少腹作胀亦松，红疹略为化淡。脉弦稍柔，舌红黄苔化薄。今晨咯痰三口，颇觉爽适，自觉胸中尚有痰黏之状的是肝胆之火与邪热交炽，炼液成痰，遂令痰火相煽。神昏发痉，岌岌可虞。前药进后，未及一周，未便操之太激。拟清化邪热，参以化痰。", "7316": "冯（左）温邪七日，热炽神迷肢节引动，脉见歇止舌黑质红，颧颊红赤，喉间霍霍痰鸣，气粗短促。此热炽于内，而痰湿抑郁，热不得泄，转从内窜之象，有痰涌昏喘之虞。", "7317": "周（左）进泻肺开痰，导热下行，上升之气，十退三四，痰亦稍爽，然热势仍不见衰，左肋痛减，而痰色黄稠，频渴欲饮，神烦胸闷舌质转红，边尖大有绛意。讝如梦语两颧红赤。脉数滑大左部小濡，右部搏指。良由蕴结之气分渐开，而霍霍痰鸣，肺胃之邪热尚炽火与痰激，故霍然有声。热灼津亏，故频渴而欲饮。症势较前略定，而鸱张之下，非大有起色，不足以全大局。刻下所急者，痰鸣气逆，最关重系。然邪势不泄，液即为痰，古人所谓痰即有形之火，火即无形之痰，正此意也。拟清金肃肺之中，参以辛凉重剂，必得应手始臻妥洽耳。", "7318": "某昨投泄热透邪，今午续得微汗，烦渴较昨略退，面色浮赤较淡。然天气乍冷，阳气阻郁，赤色瘀滞不匀，邪湿羁留，未能遽解。上焦之气不展，胸中窒闷不舒。口腻苔白舌红，脉数糊滑。化湿泄邪，固属定理。但除感冒带病酬应外，热甚不退者九日，邪湿熏蒸之势，尚在鸱张，总望转候大得退机耳。", "7319": "二诊叠得自汗胸中之窒闷稍开，尚未安寐，口燥而腻。脉数舌红，苔白淡黄。胃中之浊与湿交蒸，不能遽化。症经旬日，惟有泄之，化之俾免内蒙为幸耳。", "7320": "三诊疏泄太阴，兼以通腑，宿滞下行，胸痞腹满较舒。然热势仍起，下午为甚，面色晦黄，口渴而复黏腻咳嗽较退，寤难成寐。脉数而带糊滑，舌边绛赤，中心依然白腻足见邪势由浅而深。然从无不可达之邪，亦从无不可泄之热，其所以解之不汗，清之热不泄者，以夹杂湿邪，相持于内也。再以泄化为主。冀邪与湿分，不致蒸痰从中弥漫为上。", "7321": "周（左）花甲之年，兼嗜紫霞，其命火之衰，湿痰之盛，不问可知。昨食甘寒之物，脾胃之阳为之暗伤，致湿痰弥漫三焦，旋转运行之阳，为湿所遏，以致发热在里，热势不扬。湿胜则脾土不能分化，其水液应入于膀胱者，至此而淆入于大肠，所以便注下迫。气愈内闭，则毛窍外开。所以淋淋汗出矣。湿痰停阻，就使引动伏邪，亦不过湿热之常病。而舌无华色，脉沉细涩，右脉略大而混数不扬，一派正不胜邪之象。病在初起，又无遽培元气之理。方拟分理三焦勿以发散攻消为事，以湿与痰皆不可力制，惟有化之为宜。", "7322": "以翁昨诊内窍欲蒙，及服药之时，神已糊乱。今日竟尔神昏，手暖足厥，脉糊滑并不甚数，苔白腻并不焦黑，身热并不炽甚。此由湿盛之极，中阳不运，致湿蕴成痰，痰蒙清窍。与火热之甚，扰乱神明，而致神昏者不同。勉拟芳香通神，辛开苦降，为背城之一。谋事在人，成事在天。", "7323": "张（左）湿温旬日，烦热无汗，赤疹隐约不透，胸次窒闷异常，咳不扬爽，时带谵语，频渴不欲饮，饮喜极沸之汤。脉数糊滑，苔白心黄，近根厚掯。此由无形之邪，有形之湿，相持不化，邪虽欲泄，而里湿郁结，则表气不能外通，所以疏之汗之，而疹汗仍不能畅。热与湿交蒸，胸中清旷之地，遂如云雾之乡，神机转致弥漫。深恐湿蒸为痰内蒙昏痉。", "7324": "二诊昨进辛宣淡化，上焦之气分稍开，熏蒸之热势稍缓，神识沉迷转清，谵语指搐已定，烦闷亦得略松，舌苔较退。但气时上冲，冲则咳逆，脉数糊滑。良以郁蒸稍解，而邪湿之势，尚在极甚之时，虽有退机，犹不足济。肺胃被蒸气难下降，所以气冲欲咳，仍未俱减也前法之中，再参疏肺下气。", "7325": "三诊胸闷懊烦，气冲咳逆，次第减轻，咯吐之痰，亦觉爽利。舌苔亦得大化，但脉仍不扬。其肺胃之间，尚是熏蒸之地，表不得越，邪无出路，还难恃为稳当也。", "7326": "四诊咳嗽气逆大退，痰亦爽利，谵语热烦亦得渐减，特小溲清而不爽，大便不行，频转矢气，脉数糊滑，苔化而中独厚。犹是湿痰内阻，邪难泄越再导其滞。", "7327": "五诊大便畅行，燠烦大定，热亦较轻，口渴亦减。但赤疹虽布，甚属寥寥汗不外达。脉象较爽，舌根苔白尚掯。邪湿之熏蒸，虽得渐松而未能透泄。须望其外越方为稳妥也。", "7328": "六诊熏蒸弥漫之势虽松，而湿性黏腻不克遽行泄化，里气不宣表气难，达汗㾦不得发越，咳嗽气逆小溲不爽。脉数滑苔白，邪湿互相犄角，尚难稳当。", "7329": "按此症湿温胸闷，始起即有讝语。张骧云先诊，以其高年神志不清，案有防其内闭痉厥之语。首方用青蒿橘络猩绛之类，继用豆卷牛蒡赤芍前胡竺黄朱翘茯神玉雪救苦丹之类，不效续请巢崇山，案载咳不爽，渴欲饮热由气分内陷厥少，讝语风动之险象。方用豆卷蝉衣生薏前胡光杏郁金青蒿桔梗翘心至宝丹。既而热势仍炽，案有邪火内窜心胞之势，倘其势甚防动内风。改用羚羊芦根紫雪之属，仍不效。乃请师去。诊其脉糊数苔白腻，审其神，则沉迷，投开展气，化轻描淡写，服一剂后，即有松机。窃观此案，何以沪上诸名家于湿温一症，尚亦茫然，无怪偏僻之区，悉以清蒿黄芩鲜斛等一派阴柔之品，为自保声名唯一之妙术也。不竟为之怃然三叹。（清儒附志）", "7330": "蒋（右）流化湿痰，以开郁结，热势大减，烦懊亦定，神识亦得爽慧。脉较缓和，舌红转淡，边尖转润，惟中心仍属干燥，而又觉甜腻。邪退三舍，湿痰有欲化不化之意，而气机遏伏，津液犹难流布。稍稍经行，治当兼顾。", "7331": "二诊昨晚热势又起，湿被热蒸，胸中为之弥漫，神情不如昨日之爽慧。脉数糊滑。清空之地，悉皆秽浊所占。泄化之中参以芳化。", "7332": "热不甚之理，其所以淹淹者，邪轻于湿，湿重于邪也。湿蕴肺胃，胃气不降，所以饮汤入口，似有噎塞之状，并作恶心。热蒸则口渴，而湿究内踞，所以仍不欲饮。湿为水属，得暖则开，所以喜进热饮。大便一日数次，皆是稀水，内经所谓湿胜则泄也。湿郁之极，阴阳不通，以致振寒而战。郁极而通，得以汗泄，肌表之风，随湿外越，发为白疹，虽属邪湿之出路，然肌肤分肉之事，于三焦之熏蒸，依然无益耳窍不聪，浊邪之害清也。鼻起烟霉，是熏蒸之炎，有诸内形诸外也。刻下神情呆钝，时带错语，若以热扰神明，灵机被塞，自必有一种昏愦情形。今似糊非糊，似爽非爽，皆是无形之邪，与有形之湿，蒸腾弥漫，其胸中清旷之地，遂成烟雾之区，大有蒙闭之虞。脉象沉细不爽，舌苔淡黄掯腻，尤为湿郁热蒸之确据。兹拟辛以开，苦以泄，芳香以破浊，淡渗以引湿下行。", "7333": "二诊投药之后，神情大为灵爽，耳窍略聪，便泄亦减，湿之如雾迷蒙者，得化稍开而蕴蓄之热，亦于此勃发，所以午后甚为烦热，不若日前之沉迷罔觉也。脉象较爽，苔亦略化，然中心黄掯。脐下作痛拒按，频转矢气，口渴欲饮。良由湿积交蒸，不能泄化，还恐昏燥等变。", "7334": "四诊以燥治燥，津液果回，其为气湿郁遏，清津无以上供，固无疑义。复下数，次腹胀已松，少腹偏左之痛已退，偏右按之仍痛。脉细沉数，舌心干毛。幸边道已润。良由郁蒸渐解，气机渐得施化，津液渐得通行，而余滞积湿，犹未尽达。将及三候，元气支离，未便叠次峻攻，暂为退守待稍能安谷，再商续下可耳。", "7335": "蒋（左）神识已清，热亦大减，然频频呃忒，胸脘不舒。舌苔炱黑，脉数糊滑。内闭之热已开，而痰湿滞交阻不化，虽略转机，尚不足恃也商进。", "7336": "杨（左）外感风寒，卫阳被郁，先发微寒，阳郁暴伸，遂发壮热，汗出邪泄，阴阳洽和，得以脉静身凉。惟热气一蒸，里湿悉动，邪虽外达，蕴湿未清，所以胃纳不复，舌苔未化。宜理湿和中。至于头痛昏眩。腹满心悸，乃平素肝阳之偏亢，由于血虚不能养肝而来。当置缓议。", "7337": "某呕吐已止，而气湿不化，烦热仍然不退，耳聋不聪，时带讝语。脉糊数不扬。此湿邪弥漫，清窍被阻。", "7338": "薛金楣湿痰素盛，复感时邪，邪与湿蒸，发热不解湿邪相持于内，表气不能外通，旬日已来，未经畅汗，邪势正炽之际，更兼误食面包，胃口为之壅实，湿痰因而弥漫，清津被抑不能上供，以致神识迷糊。舌干无津，苔黑而舌质淡白。斑点隐约不透，大便不行。脉形滑数。邪湿化燥，弥漫神机，内窜昏厥，指顾间事也。与子范仁兄大人同议宣通郁遏。以望神机通灵，清津流布，然恐难得也。", "7339": "二诊昨进开通蕴遏，流湿润燥舌干转润，迷糊稍清，面色稍淡，郁遏较开。清津得以上供，所以舌燥转润。表气渐得外通，斑点略为透露。然仍大便不行，迷蒙如睡。脉象糊滑，舌苔灰滞垢腻。胃中之浊邪，闭郁尚盛，胃脉通心，还恐昏痉。与子范兄同议苦辛泄化，参以劫痰。大敌当前，成败非所知也。即请商裁。", "7340": "三诊苦辛通降，参以化痰，神识略为清爽，而仍迷蒙如寐。日前神情安静，今则时揭衣被，颇有懊烦之意。清津既回之后，津液复劫。舌苔焦黑，舌质深红，脉弦滑而数。良由痰湿积蕴遏，渐化为火，火劫阴津，胃脉通心，深恐热入胞络，症极郑重。勉与子瞻仁兄大人同议急下存阴法。即请商裁。", "7341": "四诊投剂之后，大便畅行，神情大为清爽，痰亦爽利。而日晡后又复渐见迷蒙，脉形转细。舌干质红苔黑，以汤润之，则浮糙浊苔满布，齿垢唇焦。斑点虽渐透露，而未畅达。良由邪浊化火，遂令阳明热炽，劫烁阴津。仍恐热从内窜，而神昏痉厥。勉拟泻南补北，泄热透斑。留候子范仁兄酌夺。", "7342": "五诊泻南补北，泄热透斑，斑点渐畅，神识较清，脉亦稍起，舌津稍回，稍稍饮汤，舌质即腻。清津虽回，而痰浊昏蒙，气不能化，津不上升。与子范仁兄大人共议，乘此津液稍回之际，急急流化气分，以通津液，仍以化痰宣窍参之。", "7343": "六诊神识较清，而烦热复盛，欲揭衣被不时讝语。脉象弦数，舌苔黑质红，仍然少津。斑点未畅，而已经化淡。邪热内郁，与浊交蒸，化火劫津，所谓火必为烦也。还恐内窜。以透热救阴，仍参化痰留候子范兄商政。", "7344": "八诊用增液兼清下焦湿热，大便未行，小溲作痛，涓滴不爽，气粗颧红，懊烦不宁。脉沉实，舌干苔黑，中心有断纹。邪热挟积，复聚阳明，劫烁津液，有昏厥之虞。拟调胃承气以抽釜薪。留候子范仁兄商政，并请高明裁夺。", "7345": "九诊昨用调胃承气合增液法，小便已通。而积热仍聚阳明，不能曲折而下，大便仍然未行，腹满拒按作痛，频转矢气。舌干苔黑，脉沉，重按有力。大肠与胃相联属，阳明胃脉上通于心，肠胃为积所阻，则阳土之气，尽化燥火，劫液烁津。热气自胃上冲，则心胸之间，遂成氤氲之地，所以不为烦燥，即为迷蒙。病中盗食面包，前次畅下，似不应再有余积。殊不知大肠之垢滞虽行，而后进之食，为热熏蒸，自然燥结于中，不克盘旋而下，所以前人有复下之法也。前法再展一筹。留候子范仁兄裁夺，并请高明商之。", "7346": "陈（幼）湿温逗留日久，湿蒸阳明，微寒里热。脉数糊软，苔白。邪湿日恋，原气日伤，将延入损途。", "7347": "二诊宣泄肺气，表气自通，不表而汗，不透而㾦，肌表之风，太阴之湿，因之外解。然脉仍带数。余烬尚恋，虽得转机，犹不足恃也。", "7348": "凌（左）类疟数次，少阳之邪，并归阳明，遂致不寒但热，发疹发㾦，唇口牵动，讝语神乱，风动之后，继以发厥。今大势虽定，而热恋不解，大便经月不行，酸涎上涌，胸脘不舒，吐出酸水，略觉稍适，渴不多饮。舌红苔白花糙，左脉弦大，右脉濡滑，俱重按少力。久热之下，肝胃阴伤，胃失通降，所有湿邪，不能旋运。恐虚中生变。拟甘凉育阴，酸苦泄热复入辛燥为之反佐。即请诸高明商进。", "7349": "二诊甘寒育阴，酸苦泄热，复入辛燥为之反佐，酸涎上涌已定。左脉弦大稍收，而苔白花糙，退而复起，竟是糜腐情形。不饥不纳，稍进糜饮，胸脘辄觉难过，而又并非被阻。小溲结滞不爽，临溲之际，往往中止。大便不行。无非肝胃阴伤，肺津并损，致虚火挟膀胱湿热，熏蒸胃口。既为虚火湿热熏蒸，则不纳不饥，胸脘不适。小肠与膀胱手足相应，膀胱之湿热，既随虚火上蒸胃口，则小肠火府，自然秘结，大便因而不行。深入重地，聊明其理，以尽人力。即请诸高明商进。", "7350": "三诊糜腐稍化，热邪减轻，小溲略爽，脉亦较缓。然仍不饥，稍进糜饮，仍觉气冲。气阴并亏，何能遽复，浊蒸胃口，何能遽化。惟有循理按法，以觇其后。", "7351": "五诊大府得通，并有黏腻之物带出，糜腐较昨大化，口渴较数日前大减。然中州郁郁不舒，时有痰涎随气上冲，饮喜暖热。右脉糊滑。阴液虽虚，而胃中之痰湿郁结不化，遂令清津转难上升，气火无从下降。病至于此，首尾无从兼顾。非辛不开，非苦不降，拟泻心法。虚家善变。势不暇顾矣。即请商进。", "7352": "六诊病久阴气兼亏，木火夹浊蒸腾，胃糜舌腐。阴液既亏，则不化气，浊不得化，气火内烁，热从内陷。左脉弦细急促，右脉濡滑，不耐重按。深入重地，勉与崇山先生同议方以尽人力。", "7353": "某湿温旬日，有汗不解，胸闷不舒，甚至气逆塞至咽喉，呼吸难于流利，脐旁按之漉漉，今日忽又便泄小溲不通。脉数糊滑，舌苔薄白，而底质甚腻。此湿郁三焦，恐其转痢。", "7354": "洪（左）湿温七日，烦热胸闷恶心，汗出至颈而还。脉沉细涩，苔黄罩灰。邪湿郁蒸，湿遏热伏，有内闭神昏之虞。", "7355": "二诊发出斑痧，而烦热仍然不减，至暮神昏谵语。脉糊不爽，苔霉虽化而底质白掯。还是邪湿郁蒸，欲泄而不能即泄。恐内闭昏痉。", "7356": "三诊汗出颇畅，身热遂解，但脉形不爽。蕴湿未清，还当泄化。", "7357": "林（幼）水痘之后，邪虽外达，余热未清。饮食频进，胸中之余热，与谷气交蒸，热绵不退，渐至愈蒸愈重。湿邪遏伏，津不上布，曾见舌苔干白，而并不渴饮。旬日以来，热势转有起伏，手清时暖，耳聋不聪。脉象右部糊数，左部弦大。当午火升，而热势夜重。舌红温甚，苔白湿甚。咳不扬畅。此由湿热熏蒸，湿多热少，湿在胃中，阳明少降，致少阳之木火，挟浊上腾，遂令清窍为之蒙阻，若蒙闭内窍，便成棘手重证。然火升暮热，神烦耳聋，釜中之沸也。如烟如雾蕴酿熏蒸，釜底之薪也。拟流化三焦，以分其清浊，作抽薪之计，暂观动静。诸高明以为然否。", "7358": "三诊流化气机，气通表达，发出白㾦，背部为多，背俞属肺，肺气先得宣泄。然阳明之热，太阴之湿，不克遽化，熏蒸之势，犹然难解，热仍起伏，伏则迷蒙多寐，胸中清旷之区，竟为湿热熏蒸之地，神机自难转运。舌淡红，苔白腻，右脉糊数。还是邪湿溷处之象。再从流化之中，参入芳香，以破秽浊。即请商裁。", "7359": "王（左）症交八日，热重汗不畅达，红疹发而未透，邪难外泄，热蒸湿动，湿阻气机，恶心脘痞，稍进汤饮，自觉停聚中州，里湿相搏，表气更难开泄，神情懊烦。苔白不渴，脉象糊数。恐邪湿交蒸，而致内蒙昏痉。拟宣化开泄。", "7360": "二诊宣化开泄，汗出甚畅，热势大减，并能得寐，烦懊因而大定，胸痞转舒，恶心亦止。但脉仍糊数，热犹未解。舌红苔薄白。气分之邪，依然留恋。再为宣化。", "7361": "三诊热势递减，寐亦稍安，脘痞已舒。然不悲而泣，不恐而惊，痰稠色带灰黑。脉象糊滑而数，苔白质红。腹中攻撑，便带溏薄。邪从外达，痰被热蒸，蕴而不化，胆胃之气从而失降，以致胆木漂拔。再从宣化之中参清气化痰。", "7362": "四诊脉静身凉，稠痰渐少，思谷知味，胃气渐开，悲泣惊恐亦定。宜和中以清余蕴。", "7363": "五诊苔白已化，胃开思纳。惟脉形左大。头重眩晕，肝阳挟痰上逆。再熄肝化痰。", "7364": "丁（左）热不外扬，神情烦闷，中脘痞阻，哕恶呕吐，不能容纳，头目晕眩，渴喜沸饮。左脉弦滑，右部糊滞。此肝阳上逆，挟停饮窒塞气机。恐发痉发呃。", "7365": "江苏抚军吴病湿温下虚，缠绵两月有余，仆以病近膏肓，恐药石难于奏效，以未便立方辞。主人坚恳至再，不得已勉尽绵力，将病脉症因，方治宜忌，变方案之式，为之分列各条，备诸方家及主政采择之。一、久病湿热，化燥化火，而藏气虚微，脉至少神，症属难治。循例告辞者为此。一、病既沉重，不能袖手，惟有细究其理，勉为调治。一、口燥舌黄带灰，时喜凉饮，非胃中热甚，安得有此。一、讝语错语，病涉于心。盖阳明胃脉，上通于心，胃热上乘，则心神为之扰乱。一、胃中燥火，原从湿热所化。夫湿热何以致燥。盖津之与液，清浊攸分，升降异致。浊之清者为津，清之浊者为液，液从上而下降，津从下而上升，滋养涵濡，悉赖津液敷布。今湿邪抑郁，则津液不布，燥是其标，湿是其本。一、救阴即是润燥，降火即是清心，无如津不上承，清之养之，仍苦扬汤止沸。一、大腹饱满，按之而软。谓之虚膨，虚者何，脾虚也。脾有气血，有阴阳，虚膨不运，脾虚其阳，确有可见。一、胃有燥火，而脾虚其阳，勉欲挽回，动辄矛盾。一、泻胃热而仍顾虑脾阳，前人有连理汤一方，兹仿其意。一、连属苦燥，姜属辛燥，似有抱薪救火之弊。但火从燥化，燥从湿化，燥为假燥，湿为真湿，正治从治，例得权宜。一、养阴救津，甘凉之品，有益于胃，即损于脾。再仿前人药露之法，专取其气，以润其津，于脾无损。", "7366": "谈（左）热势日轻暮重，热起之际，懊烦闷乱，神识模糊，目赤颧红，而所饮之汤，独喜沸热，烦甚则气逆似喘。脉闷数不扬，舌红苔白厚而罩灰黑。此暑热之气，从内熏蒸，而湿热之气，从外遏伏。所以暮重者，以湿为阴邪，旺于阴分也。湿性弥漫，清窍被其蒙蔽，是以神情糊乱。肺为华盖，热蒸湿腾肺当其冲，是以气逆似喘。深恐热势复起，而神昏暴喘。勉拟辛开其湿，苦泄其热，参以豁痰。总望抑郁之邪湿得开，方为转机之境。", "7367": "二诊昨日热起势较平定，神识亦未昏糊，今晨及午自觉甚舒，下午渐又烦闷。所最甚者，中脘之上，心胸之间，似觉一团结聚，于是欲呻不能，欲嗳不得。将寐之际，辄作惊跳。频渴欲饮，虽极沸之汤，不嫌为热。此痰湿蕴结，上焦之气郁痹不宣。脉较数，苔略化，似有松动之机。但极盛之时，虽略转机，尚难足恃，神昏发痉，当预防也。", "7368": "三诊胸膺臂膊，发出赤疹隐约，尚是发泄于外者少，郁结于里者多，所以热势减轻而仍起伏。烦闷频渴，渴不多饮，虽极沸之汤，不嫌为热。良以湿热郁遏，津液不能布散于上，不得不引外水以济其急，与热烁津枯者不同。脐下板满，按之作痛。痰气阻府，里气郁遏，表气难宣，势不能以斑疹忌下为例。脉数糊滞，苔白罩灰。还恐内闭神昏，而发痉厥。再辛以开，苦以泄，缓下痰积，以备商进。", "7369": "盛（幼）暑与湿合，湿重暑轻者为湿温。身热起伏，屡次得汗，热仍不解，口腻渴不多饮，渐致迷蒙多睡，耳窍不聪，胸项间痱疹密布。脉形糊滑，苔虽不厚，而舌质滑白。似属邪与湿蒸，熏蒸之气，弥漫胸中，所以时多迷睡。浊占清位，清窍不宣，所以耳聋不聪。恐由湿而蒙，由蒙而闭。即请商裁。", "7370": "某（左）热盛之时，心胸窒闷，则呼吸之气，有出无入，呼吸烦扰，刻刻欲厥。而脉虽数，甚觉沉细，苔虽浊多半白腻，舌心黑，仍属浮灰。安有如此烦热，已经旬日，而不克化火者。显系中阳不足，而痰湿郁遏。叠进辛开，胸间喘呼，虽得稍平，脉转糊滑，苔白转黄，颧红目赤，稍一交睫，辄觉惊跳。此湿蒸成痰，热郁成火。亟为清泄，参以化痰，俾免痉厥。事济与否，非所敢知也。", "7371": "二诊前进直清肝胆，大势稍定，略能安寐，懊烦扰乱，亦稍退轻。脉数较爽，舌苔焦黄亦化。但热仍起伏，起则依然烦扰，面赤目红。舌绛苔黄，赤疹密布。肌表之风，三焦之暑，太阴之湿，悉经化火，充斥三焦。非大苦不足以泄热，非大寒不足以胜热也。", "7372": "夏（左）风热感受于上，伏暑窃发于内，胃气闭郁，阳郁不伸。发热甚重。暑蒸湿动，热与湿合，熏蒸肺胃，遂致咳嗽气逆如喘。痰多稠厚，有时带红，左胁肋作痛，唇焦口渴欲饮。舌红苔黄，隐然有霉燥之意，脉数浮弦。风为阳邪，本易化火，伏暑既深，尤易化热，两邪相并，化热生火，上迫肺金，阴伤络损，所以左胁为之作痛也。症方五日，邪势正炽，有昏喘之虞。拟和阴肃肺，导热下行，即请商裁。", "7373": "金（童）外感风邪，引动伏暑。发热得汗不解，面色带红，微作恶心，胸闷不寐。脉数糊滑，苔白黏腻。外感之邪，才从汗解，而伏暑内发，夹湿熏蒸，蕴于肺胃，症方两日，势甚炽张。以泄化为法。", "7374": "温明远微寒热甚，热在心胸，肌表并不炙手，一味烦懊，邪气交会于中宫，恶心欲呕。脉忽大忽小忽歇，舌苔白掯。此伏暑之邪，为湿所抑，不能泄越。虽有津气，不克上承，所以恶燥喜润也。与云瞻先生议流化气湿，参以芳香破浊法。", "7375": "二诊稍稍得寐，胃府略和之象。烦闷虽甚，较昨稍安。但脉仍歇止。频渴欲饮，饮则呕吐。气湿未能流化，清津安能上供。燥也，皆湿也。从昨法参入苦辛合化。", "7376": "三诊辛开苦降，气通汗出。其郁遏亦既开矣，其脉气宜如何畅爽，而乃闷细如昨，右部仿佛沉伏。汗收则烦懊复盛，汗出之际，肌肤发冷。足见闭郁欲开而未能果开，卫阳已经亏损。内闭外脱，可虞之至。勉拟连附泻心法。以备商榷。", "7377": "四诊昨进连附泻心法，烦懊大定，渴亦大退，汗稍出不至淋漓，肤冷较温。六脉皆起。但仍歇止。足见正虚邪郁，营卫几不相续，虽为转机，还怕里陷。", "7378": "六诊此方服后，脉之细涩，转为弦滑，舌之剥痕，已被浊苔满布，未始不为退象。同汪君议方。", "7379": "八诊寒热虽不甚盛，而仍有起伏。大波大折之余，邪热与湿，不能遽楚，不问可知。所可异者，脉又转细，神情亦少爽利，胸闷不舒，时仍有烦懊情形。当其脉见歇止，甚至隐伏，其时进以连附泻心，脉即顿起，数日甚属和平。撤龟甲，脉未变。撤草彻芍，脉亦未变。昨方之中，补中气，扶中阳，并未撤防，而脉情转异。谓是气不足而不能鼓舞，则参须虽为大参之余气，其时隐伏之脉，尚足以鼓之而出，今竟不足以保守旧地，于情于理，有所不通。细询其今日咯吐之痰，不及昨日之多，倦睡较昨为甚，是否上中两焦之湿热未清，弥漫于中，遮蔽脉道，不能鼓舞。质之艺香先生，以为何如。并请云瞻老宗台定夺。", "7380": "九诊气湿开通，脉歇及数象皆退，大便畅行。胃气将起，惟祈谨慎。艺香先生商定。", "7381": "陈（右）伏邪晚发，湿重邪轻，邪从汗泄，湿蕴未化，热退胸宽之后，黏腻之痰未净，饮食不慎，浊痰蕴聚，熏蒸复热，中脘痞满难舒。昨忽于脐上脘下突起一条如梗，作痛异常，按之摩之，其形较软。刻下痛势暂定，而形梗之处，按之跳动，心胸之间，汩汩作酸，滴水入口，亦觉阻碍。脉象弦滑，舌红苔白而浮。良由脾胃为浊痰所遏，胃土不能通降，脾土不克运旋，遂致肝藏之气，不能疏泄，浊气阻而不行，突起一条，以冲脉起于气街，而贯于胸中故也。胸中作酸，以曲直作酸也。今水湿之邪，干犯土位，肝木之气，郁于土中，诚恐气郁之极，而暴伸为喘，不可不虑。兹拟苦辛通降法，疏其土滞，而木之郁者，或由此条达，然不易也。备商。", "7382": "二诊苦辛合化，通降阳明，中脘略舒，稍能安谷。然脐之偏右，有形攻筑，心中嘈杂，呕吐痰涎。询悉日前曾吐青绿之色。今诊左寸细弱，关部弦滑，尺中小涩，右寸濡软，关尺虚弦，重取竟空豁无根。此中气虚微之兆。中无砥柱，肝木之气，自得摇撼其中州，此所以为嘈为杂也。木无土御，肝浊自得上泛，所以呕恶，为吐青绿之色。木郁土中，故肝病而聚形偏右。种种见端，皆由病伤根本而来，右脉空豁，即是木无胃气，大为可虑。勉拟六君以扶持胃气，合梅连煎出入，以泄胃浊而柔肝木。备商。", "7383": "三诊扶持胃气，兼泄胃浊而柔肝木，胃纳略有起色，吐水嘈杂，较前大减，结块攻撑已定。特饮食仍难多进，多进则中州仍觉痞满，痰犹上涌。脉象稍觉黏指，然仍涩数。此胃气既已空乏，胃阴亦已耗伤，虽见转机，尚难深恃也。仿戊己汤出入，参入甘寒益阴之品。备商。", "7384": "四诊呕吐嘈杂已止，稍能安谷。特块之攻撑虽定，而不能泯然无形，所以于聚形之处，气分总觉窒滞。脉象濡细而涩，舌光无苔。良由气阴并亏，肝木之气，与平索之饮气互结。大便两旬未行，亦脾土不能鼓舞运旋耳。衰羸之症，尚未稳当。", "7385": "五诊呕恶全定，大便亦行，胃纳渐次加增，聚形已泯然无迹，攻撑亦止，音声稍振。虽属转机之象，但小溲作酸，脉尚细涩，舌苔薄白而掯，时犹嘈杂。良以中气未复，肝虚撼扰，肾阴亦亏，气化不及州都。大节恰临，还有意外之虞。", "7386": "六诊诸恙已退，惟尚有嘈杂之意，谷食较寻常所少无几。然匝月以来，仅能转侧不假于人，而仍未能起坐，偏左头颊作痛。脉濡而滑，左部细弱，舌淡少华频渴。正合内经谷入多而气少之例，其为血液衰脱，不及告复，确然可见。仿复脉法。", "7387": "某伏邪晚发，热甚寒微，经水适来适断，冲脉气阻。夫冲脉起于气街，布散于胸中，此响彼应，遂致中州痞满，痰湿停聚，哕恶呕吐，自觉中脘之间，似有一团凝结，滴水入口，皆聚于此。心火下降，肾水上升，水火交通，才得成寐。今中州阻痹，则水火相济之道路，阻隔不通，坎离不接，彻夜不能交睫。脉象滑大而数，沉取濡软，舌淡红，苔白且掯。邪湿痰气，交会中宫，而正气渐虚。所虑神昏发呃。气湿之结，前人谓非辛不能开，非苦不能降，拟泻心为法。", "7388": "某口鼻吸受暑邪，内藏于骨髓，外舍于分肉之间，至旬前感触秋凉，内伏之邪，由此而发。不寒但热，热则懊烦胸闷，索饮瓜水，而口渴仍喜暧饮，纤毫无汗，频带哕恶，中脘板痛，齿垢唇焦。而舌红苔白干毛，脉象糊数不扬。此邪湿滞交蒸，伏邪欲从外达，而气湿相持于内，所以叠经疏解，而未能作汗。暑必归心，所以懊烦闷乱。将及转候，深恐内闭神昏，发痉发厥。", "7389": "荣（左）三疟已久，复感暑邪，旬日来热势起伏，初起尚觉微寒，今不寒但热，热甚之时，烦懊不堪，思吃瓜水以救燎原，而所进汤饮，仍喜暖热，胸闷哕恶频频。脉数糊滑，苔白糙腻异常。汗不畅达。此由暑邪与湿痰相合，三焦之气，尽行窒塞。痰湿相持于内，则里气不能外通于表，所以不能作汗。湿阻中州，则为哕恶。暑必为烦，所以懊𢙐不堪。湿与暑相蒸，暑与湿交煽，若不从外达，即从内闭，将至神昏发痉发厥。急化其里，使蕴遏之湿痰开展，暑邪从湿中外透，是为大幸。", "7390": "二诊烦闷大减，热之起伏亦得稍衰，哕恶较定，神情亦得爽慧。日前屡屡发厥，自昨至今，厥亦未作，不可不为转机。但脉数犹带糊细，舌苔大化，白色渐次转黄，近根微霉。湿痰之郁遏稍开，而暑湿相蒸，何能遽化。上中二焦，犹是邪湿交炽。将及两旬，还恐化燥昏厥之类。请正。", "7391": "孙（左）头痛遽见退轻，而每至热蒸，其痛辄甚，咽中牵腻，频作恶心，窒闷尤甚。脉数糊大。良以暑湿内蒸，火风随之上旋，肺胃之气，不能开降。病起即发白㾦，气分素虚。恐湿热交蒸，致内窜昏厥。再从三焦宣化，参以清泄。", "7392": "二诊轻清泄化，热势微轻，懊烦较定，大便通行，并不溏泄，极为正色。但舌苔稍化，而中心仍觉黄掯。暑湿蒸腾于胃，湿蕴为热，肺脉通心，所以时作懊烦。前方已经应手，宜再扩充。候专门名家商用。", "7393": "李（右）每至下午，辄凛寒而热，热势不扬于外，而甚于里，胸闷中脘痞阻，恶心呕吐，渴不多饮，少腹作痛。脉数沉郁不扬。咳嗽痰多。苔黄质腻。暑邪夹湿，郁阻气分，肺胃之气，不克下行，开合因而失度。症起旬日，病邪方盛，恐再转剧。姑开泄气机，以通三焦而致开合。即请商裁。", "7394": "二诊中脘痞阻已舒，恶心亦减，凛热退轻，咳亦稍松，故气逆因而大定。然下午仍有微寒，痰多胶腻。脉象稍扬，而带糊滑，舌红苔白不匀。上焦微通，而湿蕴成痰，弥漫肺胃。再参清化。", "7395": "荣（右）木郁已久，兹兼暑湿内伏，风邪外束，脾胃受困，骤然吐泻。伏暑风邪，乘此而发，不能外泄，郁于肺胃之间，以致咽赤作痛，肌痒发痧，烦热不解。热迫下注，大便频泄。胃热上冲，咽中牵腻，干恶连绵。又当天癸临期，经行不爽。脉细弦数，舌红无苔。热郁阴伤，势多变局。拟清咽滋肺汤进退。", "7396": "二诊利膈清咽，热态稍安，而咽中赤碎痛甚，环口发出热泡，两腮碎痛，烦渴欲饮。经色紫黑。左脉弦紧，舌红边尖绛刺。邪热化火，熏灼肺胃，阴津暗伤。恐热入血室，而致昏喘。", "7397": "四诊咽痛略定，气逆较平，痰稍爽利，烦热亦轻，而肌肤仍然作痒，口渴喜凉饮，咽中白腐不退。左脉细弦而数，右脉细数微弱，舌白质红，舌尖满布红点。火热劫烁肺胃，阴津大伤。咽通于胃，喉通于肺，肺为辛金，在色为白，金因火旺，其腐为白，金之色也。还恐火刑金烁，而致肺喘。再清肺胃之热，而救肺胃之阴。", "7398": "六诊咽痛白腐布满，项侧耳后肿胀作痛，热势不衰，肝胆之火，势若燎原。大苦泄热，大寒胜热，咽痛略减，白腐略退。然热势仍炽，经紫色不净，脐下按之板滞。脉象弦数，舌红起刺。肝胆之火风，交炽于上，欲行未行之血，凝滞于下，营郁则热，亦属定理。再从清泄之中，兼和营滞。以备商酌。", "7399": "八诊辛凉重剂，原为清热解毒，救液熄风而设，何以喉间更痛者。曰、红炉泼水，烈焰飞腾也。何以少腹痞硬者。大气欲泄而不泄，肠间之气，反为痹阻也。经云、其始则异，其终则同。斯之谓欤。今诸款见松，喉腐亦定，痛势且缓，独是遗毒胀痛，更甚于前。脉小数弦，口干作渴，唇吻燥痛。分明郁伏之邪火，由脏出腑，由腑出经，痛虽不堪，而症则由此转顺矣。所嫌者本质阴虚，又当邪火燔灼之余，气伤液耗，热犹未已，而遗毒之痛，亦起心火，则火化风而劫液，实为可虑。急急存阴清热，导腑解毒，安内攘外之法，未识当否。", "7400": "王（右）伏暑感新凉而发，凛寒而热有起伏，胸闷恶心欲呕，适及经来，少腹不舒。脉细数而滞，舌苔白腻。此伏邪夹湿，郁阻气机，深恐内闭昏痉。", "7401": "二诊热势起伏不减，胸闷恶心，每至热起，辄觉头昏晕冒，汗不获畅。脉滞数不扬，舌苔淡黄，而中带干毛。无形之暑，有形之湿，交蒸不化，心胸遂成氤氲之乡。更以经来涩少，血因热滞，深虑内窜昏厥。", "7402": "三诊今日热起，大为减轻，恶心亦得较定，昏晕烦渴，与昨迥殊。足见伏气与湿交蒸，心胸即如云雾矣。但脉仍糊数。邪势尚甚，还恐起伏生波也。", "7403": "四诊热势虽未大起，而犹恋恋未退，胸闷恶心，脐上作痛，经事已净，较诸寻常尚觉涩少。脉左关弦大。良以暑湿交蒸于气分，肝胃之气，亦由此失和。再参调气。", "7404": "张热势起伏，起则烦扰不宁，语言错杂，胸闷频渴欲饮，汗多不解。舌红苔白，脉濡。此暑从内发，暑为天之热气，所以一经熏灼，即乱神明。经水适来，深恐热入血室，而致昏厥。", "7405": "翰臣症起七日，先寒后热，寒则震战，热则烦渴，恶心胸闷，汗出溱溱，而气味甚秽。脉象弦滑，苔白质腻。病起之际，适值失精，若论邪势直入阴经，则喻氏治黄长人房劳后伤寒论极详细。此盖由时感之邪，与湿混合，阻遏于少阳阳明，名曰湿疟。所恐少阳之邪，并入阳明，而转但热不寒，或热而不退，便多变局，以少阳主半表半里，无出无入，而阳明胃络，上通于心也。若有寒有热，当无大患耳。用小柴胡以和解表里，合达原饮以达募原之邪。即请商政。", "7406": "周（江阴）久咳屡次见红，痰阻营卫，阴阳不能交通，寒热三日而至，其营卫郁勃之气，欲借阳经泄越，间有衬交，气血由此凝滞，偏左有形。脉象弦滑而带微数。阴气有渐伤之虑。欲和阴阳，当通营卫之痹。", "7407": "某大疟而转寒热叠来，汗多而气酸带秽。右脉濡软，左部细弦。此由痰湿不运，熏蒸阳明，营卫阴阳，亦为之阻。宜和中化痰，兼通营卫。", "7408": "二诊畅汗热达，痰热未净，夜寐不安。苔根黄腻，脉弦滑转甚。拟加味温胆法。候正。", "7409": "贾（左）寒热间作，脉糊不爽，此湿疟也。和以化之。", "7410": "沈（左）久疟屡止屡发，刻虽止住，而食入不舒，左胁下按之板滞，胃钝少纳。脉濡，苔白质腻。脾胃气弱，余邪结聚肝络。拟和中运脾疏络。", "7411": "二诊脉濡滑，苔白质腻。胃钝少纳，形体恶寒，饮食入胃，命火蒸变，则胃如大烹之鼎，旋入旋化。今湿有余阳不足，胃气呆钝，亦所不免。拟化湿和中，温助阳气。脾胃能得转旋，则络邪亦归默化也。", "7412": "某寒热稍减，寒势甚微，而热则五心烦躁，喜得凉饮。脉细数，左部微弦。营卫阴阳不和，皆由阴虚而木火内炽。再和阴而参酸苦涌泄。", "7413": "周（左）疟症必有黄涎聚于胸中，故曰无痰不成疟也。脉弦主痰饮，故曰疟脉自弦。疟疾湿痰未清，以西药止截，遂致腹满肤肿面浮，为疟胀重症，未可轻视。", "7414": "陈（左）大便通行，热仍起伏，汗出即解。脉象溷数，苔腻心黄。有形之积，虽已下达，而湿热氤氲，极难泄化。从泄化之中，参入辛温寒以通营卫。", "7415": "二诊昨晚寒热分明，阳明之邪，并归少阳，极为正色。阳明胃脉，上通于心，而少阳胆经，无出无入，虽有邪居，不能蔓延脏腑，从此不虑病变矣。", "7416": "张（左）寒热五日一来。脉形左大。邪在表里之间。宜为和化。", "7417": "左痰多，自觉身热，而脉不甚数。此痰湿有余，郁遏阳气。", "7418": "周（左）每至日晡，辄作漫热，热不退清，汗出稍松，痰多，脉濡滑。气虚痰阻，遂致阴阳开合失其常度。年近花甲，不宜见此。拟苦辛寒合方，以开阴泄热。", "7419": "三诊脉象濡滑。运化迟钝，便溏不实。舌苔中心黑润。痰湿不运，脾阳不克鼓舞。拟温中而蠲饮。", "7420": "左久嗽不止，痰稠厚腻，甚则色带青绿，寒热往来。脉软而数。此肝肾素亏，而脾胃之痰热，熏蒸于肺，阴阳开合之机，悉为痰阻，此所以为寒为热也。将入劳损之门，不易图治。", "7421": "某气虚多痰之质，偶食黏腻窒滞之物，气由此不行，湿由此不运，痰由此不化，营卫由此而阻，阴阳由此而乖，遂至阴阳相争，先寒后热。郁极而通，两次大汗，阴阳稍得协和，热势因之渐缓。然脾肺升降，仍为痰气所阻，右胁作痛，痰鸣带咳。盛纳在胃，运化在脾，所谓窒滞者阳明也。气之不行，胃气之不行也。湿之不运，胃湿之不运也。脾为生痰之源，胃为贮痰之器，肺为出痰之窍，痰之不化，是胃中之痰不化也，阻于斯，滞于斯。寒热交争之下，热虽循减，而胃中之痰湿，已被熏蒸，于是随其阳土之性而欲化燥，舌苔为之焦黑。舌色如此，而不甚热，不烦闷，不口渴引饮者，独何欤。以痰湿熏蒸，化燥化热，皆由气机郁遏，津液不行，不若时邪之症，温气化热之后，烁液劫津而成燥也。阳明胃络，上通于心。今胃中为痰湿弥漫之区，所以神机为之不运，神倦如寐，中脘板硬。脉象左寸微浮，关部溷滑，尺部沉细，右寸细滞，关弦，尺弱。证由痰湿食停阻，传变化燥，以平素气弱，而致化火不足。化燥不足。惟恐里气一虚，而湿痰内陷，以致神迷。拟疏化痰湿，参入苦降辛开，即阳土宜清阴土宜温之意。备诸方家采择。", "7422": "二诊疏降胃府，苦辛开通，脉数稍退，舌焦黑顿化十七。郁蒸之热，已退三舍。大便虽未通行，而中脘略软频转矢气，亦属府气欲通之象，不可不为起色。但热仍未退，右胁仍痛，痰鸣欲咳，还是痰湿交蒸，不可遽化，所谓伤食类伤寒者，即此是也。再拟疏化一法，而步步顾其中阳，以防内陷神昏之变。备方家采择。", "7423": "六诊脉象和缓。但小溲有时仍痛，还是余热未尽。再清泄以澈之。", "7424": "陈（左）痛泻之后，继以呕吐，中州不舒。脉形沉细。此寒湿内阻。", "7425": "郁（左）带病入闱，病邪未澈，昨复啖饭二次，复食冷柿三枚，寒食交阻，胸中阳气逆乱，阴阳之气，一时挥霍变乱。泄泻稀水，继而复吐。阳气闭郁，肢厥脉伏，汗出不温，目陷音低。频渴欲饮，中脘不通，胸中大痛。中阳毫无旋转之权，有内闭外脱之虞。拟黄连汤以通胃中阴阳，参以芳化而开闭郁。", "7426": "二诊用仲景黄连汤以和胃中阴阳，参以芳化而开气机，六脉俱起，肢厥转温，胸痛亦止，泄泻亦减。病虽转机，而湿热何能遽楚，以致湿化为热，劫烁阴津。舌苔干黄，毫无津液。频渴欲饮，时带呃忒，小溲全无，神识迷沉。极为危险。勉拟辛咸寒合方，参以芳开。", "7427": "题臣饮食内停，寒热杂感，致清浊相干，三焦闭塞。始则上吐下泻，今则欲吐不出，欲泻不爽，腹笥板滞，按之满痛噫出卵臭，脉伏肢厥，螺瘪目陷清浊溷淆，湿食停阻，吐泻虽得稍停，而浊积更加闭塞，气道不宣，阳不敷布。危险已极，勉与显卿仁兄先生同议苦辛开通，降泄浊积。即请高明商进。", "7428": "金（左）春温疫疠之邪从内而发。发热咽痛，热势甚炽，遍身丹赤，痧点连片不分，咽痛外连颈肿。右脉滑数左脉弦紧，舌红边尖满布赤点。此由温疫之邪，一发而便化为火，充斥内外蔓延三焦。丹也，痧也，皆火也。刻当五日，邪势正盛，恐火从内窜，而致神昏发痉。拟咸寒泄热，甘凉保津。", "7429": "金（右）头胀恶风发热，头面四肢已透痧点，咽中微痛。脉数，苔白。风温之邪，袭于肺胃。适值经来，恐热入血室，不可与寻常并论也。", "7430": "三诊痧虽畅透而不肯化，经事淋沥未已，舌燥咽中干痛。脉象细数。此由经水适来，血室空虚，血分暗为热迫。再泄热凉营。", "7431": "八诊脉静身凉，履夷出险，幸甚幸甚。拟清养肺胃，以澈余炎。", "7432": "金热势甚重，咽肿作痛，丹痧透露未畅，胸闷神烦。脉形紧数而弦。时疫之邪，郁于肺胃。恐邪化为火，致生枝节。", "7433": "某春温疫疠之邪，由募原而入胃腑，邪化为火，熏蒸于肺，充斥上下，蔓延内外。以致热炽丹痧密布，上则咽赤肿痛，下则协热下利。脉象紧数，舌红无苔。今则渐增气喘，危象已著。勉拟黄连解毒汤出入。即请高明商榷行之。", "7434": "张（左）外风引动温邪，邪从内发，即化为火。喉风发痧，舌心焦黑，黏痰缠扰咽中，咯吐不尽。脉数弦滑。时行急病，变端不测。", "7435": "严（右）咽痛红肿，丹痧已透三朝，上至头面，下至足胫，是为透足。邪从痧出，热随邪达，理当病退十七，乃热势仍然不减。咽痛稍轻，仍然赤肿。脉象滑数，舌红无苔。足见邪势太重，半发丹痧透露于外，半化火热郁于肺胃。况当经水适行，若肺胃之热，乘血分之虚，袭入营中，便是热入血室。今当出入之际，治法不可不细论也。经云、火郁发之。则开泄之药，在所必用。又云、热者寒之。则清化之药，在所难缓。而白喉忌表。殊不知白为金色，火热亢盛之极，金受火刑，所以喉间结成白点，甚者起出白条。凡表药之性，皆带升泄，恐升动火热，所以忌用。即非白喉，如喉风喉疳喉蛾之甚者，往往亦有白腐，其为火甚刑金，则一也。刻下咽痛较前昨稍轻，白点似有若无，喉症之势已得稍缓。而痧点渐化，热势不减，其火热之渊薮，不在喉间，而蕴于肺胃。显然可见。肺主皮毛，则开泄肺气，是散邪，即散火也。清泄上中，是化热。即防其入血室也。拟清泄一法。即请商榷行之。", "7436": "二诊辛凉解表，微苦泄热，参以和营，遍身痧点畅发，邪从痧透，怫郁之热自得稍松，喉间赤肿大退，热势略得减轻。然脉仍滑数，舌红无苔，不时恶心，还是胃火逆冲，胃气不降。良由邪势太重，泄者虽泄，留者仍留，总望痧退之后，继之以汗，热势步退，方为正色。再拟清化法。即请商裁。", "7437": "三诊热势递减，咽痛亦轻。然痧点出而不化，寤难成寐，多言而时有错语。脉数细弦，舌红无苔，边尖皆布红点。此由热甚之时，经水适行，血海空虚，邪热乘虚而入血室，神藏于心，魂藏于肝，而心主血，肝藏血，今热扰血中，所以神魂不能安贴，灵明渐次为之扰乱，二十二日案中早经提及，正为此也。恐致神昏痉厥，不得不为预告也。拟养血凉营，以宁神志。即请商榷行之。", "7438": "顾（童）风温发痧，痧邪太重，邪热与风，半从外出，半从里陷。痧邪本在肺胃二经，然肺与大肠表里相应，大肠与胃，又系手足阳明相合，所以陷里之邪，直趋大肠。以致泄痢无度，痧点欲回未回，咳嗽不爽，遍身作痛。脉数，重按滑大，舌红无苔。上下交困，极为恶劣。勉用薛氏升泄一法。即请明贤商进。", "7439": "二诊昨用升泄之法，陷里之邪，略得升散，脾之清气，稍得升举，泄泻大减，白冻亦退，神情亦略振作。舌红绛较淡，脉滑大稍平。种属转机之象，守前法扩充，续望应手。即请商裁。", "7440": "三诊下痢稍疏，然昼夜当在二十次之外，所下黑黄居多，肛门烙热，肌表之热，并不甚盛。而脉数竟在七至以外，舌红起刺。良以陷里之邪，与湿相合，悉化为火，仿金匮协热下痢法。即请商裁。", "7441": "金（幼）时疫七日，丹痧回没太早，火热内灼，口疳咽痛，热胜则肿，面目肢体虚浮。脉象弦数。恐变肿胀。", "7442": "陈（右）久咳根蒂不除，去秋燥气犯肺，咳而失血，金水由此而亏，连绵内热，肉脱形瘦。脉细数而促。理宜壮水救阴，清金保肺。然舌淡少华，中气薄弱，稠腻之药，不能多进。症入劳损之途，不能许治。勉拟金匮麦门冬方备质高明。", "7443": "二诊用金匮麦门冬汤，咳嗽稍减，然清晨依然咳甚。脉细弦数。盖寅卯属木，金病而遇木旺之时，病势胜矣。药既应手，未便更章。", "7444": "三诊神情稍振，胃亦渐起。然咳嗽仍然未定，甚则哕恶欲呕，上午清晨为甚，辰巳之交，往来寒热。脉细数，舌红苔黄。还是肝肾阴虚，气难摄纳，自下及上，阴阳不能和协。虽略转机，不足为恃。", "7445": "某金匮云、心下悸者有水气。未病之先，心下先悸，水饮早已停阻，复因感邪，遂起咳嗽，邪虽渐解，三焦气伤。以致形色淡白，咳恋不止，甚至形寒内热。盖肺为相传，有分布阴阳之职，肺气一虚，阴阳之分布失其常度，是以寒热往来。金所以制木也，金病则木无所制，所以气撑不和，得矢气则松，肝藏之气，不能扶苏条达，有可见者。脉象虚弦，舌白少华，苔腻。此伤风激动伏饮，邪去而饮复阻肺，肺气日虚，肝邪日旺，将成虚损之症。冠翁先生不降肺而和胃平肝，隔一隔二之治，所以卓卓人上。无如病久根深，未克奏效。兹勉从经旨久咳不已则三焦受之之意，用异功为主。管窥之见，深恐贻笑于方家耳。尚乞斧正是荷。", "7446": "胡（左）肺感风邪，邪郁肺卫。以致咳嗽不已，身热连绵。肺合皮毛，肺邪未泄，所以凛凛畏风。因邪致咳，因咳动络，络损血溢，日前咯血数口，血止而咳逆如前。脉细而数，右寸关微浮。此即伤风成劳是也。咳因邪起，因咳成劳兹则去其邪而保其正，明知鞭长莫及，然人事不得不尽。备方就质高明。", "7447": "陈（在）失血之后，久嗽不止，每交节令，辄复见血，面色桃红，时易怒火，然每至天寒，即恶寒足厥。脉形沉细而数，颇有促意，其为血去阴伤，龙雷之火不能藏蛰，阴火逆犯，肺降无权。清肺壮水益阴，固属一定不易之法。然药进百数十剂，未见病退转觉病进。再四思维一身之中，孤阳虽不能生，而独阴断不能长，坎中之一点，真阳不化，则阴柔之剂不能化水生津，阴无阳化，则得力甚微。意者惟有引导虚阳，使之潜伏，为万一侥幸之计。拙见然否。", "7448": "二诊壮水益肾，兼辛温为向导，脉数稍缓，火升之际，足厥转温。但交节仍复见红，龙相之火尚未安静。前方出入再望转机。", "7449": "某痰饮多年，加以病损，损而未复，气弱不运，饮食水谷尽化为痰。以致气喘肿发，两月方定。今神情痿顿，肢体疲软，吸气则少腹触痛。脉细濡而苔白无华。呼出之气，主心与肺，吸入之气，属肝与肾，一呼一吸，肺肾相通之道，必有痰阻。诚恐损而不复。", "7450": "朱（左）先自经络抽掣，继而吐血盈碗，血从脘下上升。今血虽渐定，而呛咳气逆。脉象虚弦。肝肾阴虚，虚火载血上行，遂至阴不收摄。恐咳不止而致入损。", "7451": "二诊吐血仍未得定，血散鲜赤，食入胀满，气冲作呛。脉象虚弦。阴虚木火上凌，激损肺胃之络，络损血溢。再降胃凉营止血，参以降气，所谓气降即火降也。", "7452": "郑（右）由咳嗽而致见红，咳嗽由此更甚，内热连绵，春间复发肛痈，月事由此停阻，心中烦懊，咳甚咽中微痛。脉细弦而数，舌红心剥。肺肾并损，不能许治。以金水双调法，聊作缓兵之计而已。", "7453": "二诊脉稍柔缓，内热略减，咽痛亦轻，胃气稍振。然咳嗽时轻时重。金水并损，何能遽复。姑踵效方以观其后。", "7454": "六诊脾肺肾三脏并亏，脾不能运则生痰，肺不能降则呛咳，肾不能收则气逆，虚损不复，痛泄咽疼诸恙，时轻时重。脉数细急。聊望缓兵耳。", "7455": "周（左）温胆以致开合，形寒已退。而气阴并亏，咳嗽痰多，左胁肋气觉上逆。脉细，关弦。一派虚损情形，不敢许治也。", "7456": "二诊呛咳稍减，脉亦稍缓。药既应手，再为扩充。", "7457": "又膏方阴分素亏，嗜饮激动阳气，肝肾之血，随火上逆，曾吐紫黑厚血，由此顿然消瘦。兹于秋燥行令，忽起呛咳，数月不止。投金水双调，呛咳竟得渐定，其为虚火凌上烁金显然。脉细而数，舌苔黄糙。真阴安能遽复。培养下元，更须保养，或可徐徐复元耳。", "7458": "胡（左）伤风夹湿，而致损肺。咳嗽不已，痰色稠黄，不时见红。兹则痰血日甚，脉数内热，肛门漏管。此阴虚挟湿，湿热熏蒸，肺胃之络，为之所损，痿损情形，聊作缓兵之计而已。", "7459": "三诊痰红虽减于前，而咽中隐隐作痛。咽喉虽属肺胃，而少阴之脉系舌本循喉咙，则是咽痛一层，其标在肺，其本在肾也。肾为先天之本，恐非草木之功，所能挽狂澜于既倒也。", "7460": "吴（左）经云、面肿曰风，足胫肿曰水。先是足肿，其为湿热可知。乃久久方退。足肿甫退于下，咳嗽即起于上，痰色带黄，稠多稀少，未几即见吐血。此时湿热未清，风邪外乘，所以风邪易入难出，为其湿之相持也。邪湿久滞，咳而损络，络血外溢。迨血去之后，阴分大伤，遂令金水不能相生咳不得止。兹则声音雌喑，咽痛内热，所吐之痰，黄稠居多。脉细数有急促之意，而右关尚觉弦滑。所有风邪，悉化为火，肾水日亏，肺金日损，胃中之湿热，参杂于中，熏蒸于上。深恐咽痛日甚，才疏者不能胜任也。", "7461": "二诊风湿热相合，熏蒸损肺。前方引导湿热下行，缓其熏蒸之炎，即所以救其阴液之耗损。脉症尚属相安姑踵前意，以尽人力。", "7462": "沈（左）嗜饮伤肺。屡次见红，久咳不止。脉数微促。金水并亏，症入损门，虽可苟安于目前，难免颓败于日后也。", "7463": "二诊肝阴肾水，亏损已极，致肝风上翔，冲侮胃土，风翔则浪涌，以致呕吐复作。营液既亏，气分亦耗，两腋下发出白㾦。脉虚苔腐。此欲脱之兆也。勉拟补气育阴，亦尽人事而已。", "7464": "江（左）咳嗽不减，内热口渴便赤，脉象细数，饮食少思。肺金肾水交亏，将恐不支。", "7465": "二诊久咳气逆难卧。脉细如丝，舌苔腐烂。肾虚之极，肾火挟浊上浮。危在旦夕，勉方图进。", "7466": "三诊气喘大定，痰亦略爽，而糜腐时退时来。脉形虚弦关部独大。饮化为痰，痰化为燥，燥化为火，所有阴津，尽行劫夺。虽略转机，尚不足恃。", "7467": "黄（左）吐血之后，剧咳多痰，痰皆稀白。脉细沉苔白无华。三焦之气已虚，劳损根深，鞭长莫及。", "7468": "某本是先天不足，肾脏空虚，湿热下注，发为漏疡，理宜培补之不暇矣。乃肺感风邪，邪恋不澈，遂致咳久不止，咽痒痰多音闪，脉数内热。本虚表实，竟是劳损情形，非学浅才疏者，所敢许治也。勉拟化痰润肺以备商用。", "7469": "二诊肺气稍得下行，咳嗽略减，音声亦较爽利，不可不为起色。但时犹燥热。脉象带数，仍未敛静。阴液已耗，还恐缠绵不复。", "7470": "某天下无倒行之水，故人身无逆上之血，水有时而倒行，风激之也，血无端而逆上，火激之也。体无端而有火，木所生也，木何以生火，郁则生火也。血阴气阳，吐血之后，阴虚阳旺，必然之道。此时滋助水源，即是治血治火之正道。盖火有虚火，非若实火可以寒胜，可以凉折也。乃以凉治热，血止热平。而阴分不复，因耗成损因损成虚，遂致金水不能相生，肾气不能收摄，呼吸之气，渐失其肺出肾纳之常。咳嗽气逆，内热连绵，液被热蒸，尽成胶浊，痰多盈碗。脉象数，左关细弦，尺部缓急不齐，舌红苔。薄白肺津肾水，中气脾阳，一齐亏损。金为水母，养肺必先益肾，中气下根于肾，治脾胃亦必先治肾也。拟金水并调法即请商裁。", "7471": "杨（右）产后久咳，复产更甚，吐血时止时来，不能左卧，甚至音声雌喑，左胁漉漉有声，咽痒有时呕吐。脉细弦数，舌红少苔。阴虚木旺，木叩金鸣。证入损门，不敢言治。", "7472": "周（左）屡次吐血，渐至久咳不止，内热火升，右颊红赤。脉细弦而数。音闪不扬。阴虚木火凌金，金被火铄，生化不及，即水源日涸。恐损而难复。", "7473": "二诊音闪渐扬，咳仍不减，内热火升。舌红，苔糙白，脉细弦数。吐血之后，阴虚已甚，冲阳挟龙相上炎。再金水并调。", "7474": "顾（右）心悸肢节作痛，皮寒骨热。脉象细弦。营血亏损，遂致营卫失和，营血不能濡养经络。宜养血和营。", "7475": "韩（左）抑郁阳升不寐，木火刑金，而致吐血复发。血止之后，营阴亏损，营卫循环失度，倏寒倏热，头晕火升，口渴。舌红少苔，脉象细弦。皆阴虚不复之象。急为和阴，以冀渐复。", "7476": "庄（左）吐血之后，阴分未复，操劳动作，阳气升腾，头目昏晕，寐中辄轰然而热，有汗出之意。脉形左大。宜育阴熄肝。", "7477": "王（右）先是肝胃不和，木郁土中，中脘作痛，痛势甚剧。至仲春忽尔面目肢体发黄，小溲红赤，漩脚澄下，则黄如柏汁。至今时痛时止，口吐涎沫。脉沉弦带涩。考中脘为胃土所居之地，阳明又为多气多血之乡，今久病而气滞于络，气多血多之处，气亦留阻，血亦瘀凝，相因之理，有必然者。夫至血凝气滞，则流行之道，壅而不宣，木气横行，土气郁阻，所以为痛为黄。实与黄疸有间。拟宣络化瘀法。", "7478": "二诊中脘较舒，痛亦未甚，未始不为起色。然面目色黄不减，脉仍弦涩。无非络阻气滞，气血不行。药既应手，宜守前意出入。", "7479": "沈（右）产后气血亏损，不能制伏肝木，以致木乘土位，饮食稍一过节，辄作便泄，中脘作痛，噫出腐气。脉象细弦，舌苔腻浊。肝强土弱，拟温中运中，所谓将欲升之，必先降之也。", "7480": "二诊温中运中，脉症相安。肝强土弱，脾胃升降失常，所以上则噫腐气，下则便溏泄。脾宜补，胃宜通，拟养脏疏腑。", "7481": "陈（左）中虚夹痰，胆胃失降，甲木升浮，头胀眩晕，有时火升，身体似觉升浮，四肢作麻。脉形濡滑。虚里跳动。宜化痰而扶持中气。", "7482": "沈（左）中虚湿阻，不纳不饥，脾土不运，胃土不降，二土气滞木气遂郁，如种植然，其土松者其木荣，其土坚者其木萎，土病及木，大概如此。今诊六脉细弦，均有数意，舌红苔黄，微带灰霉。谷食不进，气冲哕恶。若以痰浊上泛，则脉象应当滑大，今细弦而数，其为土虚木乘无疑。夫土中有木，木土相仇，虽饮食倍常者，且将由此而减，而况先从脾胃起点乎。欲求安谷，必先降胃，欲求降胃，必先平肝，金匮厥阴篇中每以苦辛酸主治，即宗其意，以观动静如何。方草即请厚甫先生商政。", "7483": "二诊哕恶少定，胃纳略觉增多，寐稍安稳。舌红略淡，灰霉已化，脉象细弦，仍有数意。中脘微痛，土中有木，即此可知。中气素虚，胃浊素重，然浊虽中阻，而缠绵二月，和中化浊，屡投频进，而何以浊不得化，胃不得和。良以木火犯中，浊被火蒸，则胶滞难化，胃中之浊气不降，则胃中之清气不升，不纳不饥，势所必至。前投扶土熄木，尚合机宜，再拟扶持中气，化浊和中，仍参熄木，以望肝胃协和，清升浊降，胃气从此鼓舞，然不易也。方草即请商裁。", "7484": "子厚兄人之一身，气血阴阳而已。血阴气阳，气中之血，阳中之阴也，血中之气，阴中之阳也。病从暑温而起，变成外疡，其湿热之盛，不问可知。乃疡肿而溃，溃而不敛，脓水去多，气中之血既虚，血中之气亦损，以致肌肉瘦削，便泄无度。刻下泄虽渐定，而二便不固，痰气上升，胸次窒闷，口渴而不欲饮。舌苔糜腐，质淡白。小溲带黑，并无热痛情形。四肢虽属温和，而自觉恶寒，知味而不能食。脉左寸细数，关部弦搏，尺部细而带涩，右部濡弱，重按微滑，尺部细沉。手太阴之津，足阳明之气，足少阴之水，一齐耗亏，而湿痰留恋于胃之上口，致补益之品，不能飞渡胃关，气血从而日耗。勉同蓉舫先生议气血并补，汤丸并进，勿壅滞胃口，即请商政。", "7485": "二诊昨进气阴并补，痰涌稍定，寐醒之时，汗出亦止，胸次亦觉快畅，舌苔糜腐较化，未始不为起色。无如湿热逗留，津气遏伏，不能上布，虽不引饮，而频觉口渴。舌质干光少津。懊𢙐里急，小溲涩少。脉弦搏稍收。而均带细数。气血并亏，方虑草木无情，不能相济，乃湿热隐伏，致培养之剂，动多窒碍。勉与蓉舫先生同议，肾为肺子，金为水母，益水之上源，参以和中流化之品。即请商政。", "7486": "左饮食在胃，运化在脾，然所以运化者，阳气之鼓舞也。湿温之后，多进甘寒，致湿邪日见其有余，阳气日形其不足，所以纳食之后，动辄胀满，脘中微觉坚硬。脉细而沉。胃府失其通降之权。宜温运和中，使脾胃之气，旋运鼓舞，则不治其满而满自退也。", "7487": "简（左）感风入肺，肺失清肃。咳嗽痰色黄厚，夜重日轻。脉象带数。宜肃肺化痰。", "7488": "秦（童）风温袭于肺胃。咳嗽气逆，身热头胀。脉数右大。肺本清虚，今为风邪所阻，则降令无权。宜清肃太阴，疏泄肌表。", "7489": "二诊温疏太阴之表，咳略减轻。而脉象微数，营液不足之征。论病宜续进苦温，然肺虽恶寒，心则恶热，脉沉带数，未便耗伤营分，再出之以和平。", "7490": "邵（左）肺感风温，复以熬夜受寒，寒束热郁。由咽痛而致呛咳，痰不爽出，头胀恶寒。脉象沉弦。邪郁太阴，金失降令。拟辛温寒合方，以彻肺邪。", "7491": "二诊辛温寒以彻肺邪，咳仍不减。脉弦微数。热郁于肺。再宜清金肃肺。", "7492": "周（左）航海感风而咳剧，虽经养肺而咳止住，然肺络之中，邪未尽泄，所以稍一感触，辄喉痒咳剧。疏其新感，咳即渐减腠理日疏，邪仍内踞。金病则不能制木，木火自必刑金。然右脉浮滑，病仍在肺。前贤谓邪在肺络，或邪未楚而适投补益，以致邪伏难泄者，三拗汤主之。然苦温疏散，恐伤肺体。兹拟肺露而变其法，作日就月将之计，庶几疏不碍表，补不滞里耳，请备方家正之。", "7493": "王（左）降化温疏，脉证相安。久病而投猛剂，行侥徼幸，固知者所不为，然邪与正不能并立，不去其邪，何以保全其正气，则和平缓治，是犹畏疡溃之痛而养毒也，再作背水之计。", "7494": "二诊肺感风邪，不为疏解，反为补益，以致邪恋而不得泄，咳久不止。脉濡而气口独浮。既从外感而来，虽经日久，不得不为疏泄也。", "7495": "杨（左）咳嗽气逆痰多，遍身作痛。脉象弦滑。痰饮阻肺，肺失降令，络隧因而不宣。姑辛温寒以开饮邪。", "7496": "张（左）音塞不扬，两年之久，遂起呛咳，却不见红。脉象气口不调。寒热互阻于肺，然肺为水之上源，恐肺金日损，而变假为真。", "7497": "三诊用辛温寒合方，音塞较开，咳嗽大减。然天气温燥，呛咳复甚。脉象左大。伏匿之邪，虽得渐解，而肺气阴液，早为并损。再清金养肺。", "7498": "魏（左）肺有伏寒，稍一感冒，咳嗽即甚。兹当天气渐寒，更涉重洋，咳嗽因而尤甚，动辄气逆。脉沉弦重按少力，舌红苔薄白并不厚腻。此风寒痰饮有余于上，而肾本空虚于下。用雷氏上下分治法。", "7499": "徐（左）汗出略减，而咳嗽仍然不定，甚则呕涎。脉细濡软，舌黄苔白。时有凛寒之象。经谓久咳不已，则三焦受之。三焦者气之海也。进黄耆建中法。"});